#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the SPI bus and chip select pin
#define SPI_BUS 0
#define CHIP_SELECT 8

// Define the ADC channel
#define ADC_CHANNEL 0

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Close the SPI handle
        if (gpio_spi_close(SPI_BUS) != 0) {
            fprintf(stderr, "Failed to close SPI handle\n");
        }

        // Terminate pigpio
        if (gpioTerminate() != 0) {
            fprintf(stderr, "Failed to terminate pigpio\n");
        }

        // Exit with a non-zero status code to indicate an error
        exit(1);
    }
}

int main() {
    // Initialize the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set the chip select pin as an output
    if (gpioSetMode(CHIP_SELECT, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set chip select pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the SPI bus
    if (gpio_spi_open(SPI_BUS, 1000000) != 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set the SPI mode
    if (gpio_spi_set_mode(SPI_BUS, 0, 0, 0) != 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpio_spi_close(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Set the chip select pin low
    if (gpioWrite(CHIP_SELECT, 0) != 0) {
        fprintf(stderr, "Failed to set chip select pin low\n");
        gpio_spi_close(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set the chip select pin high
        if (gpioWrite(CHIP_SELECT, 1) != 0) {
            fprintf(stderr, "Failed to set chip select pin high\n");
            gpio_spi_close(SPI_BUS);
            gpioTerminate();
            return 1;
        }

        // Read the ADC value
        uint16_t adc_value;
        if (gpio_spi_xfer(SPI_BUS, &adc_value, 2, 1, 0) != 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            gpio_spi_close(SPI_BUS);
            gpioTerminate();
            return 1;
        }

        // Convert the ADC value to a 10-bit value
        uint16_t raw_adc_value = (adc_value >> 8) | ((adc_value & 0xFF) << 8);

        // Print the timestamp and ADC value
        time_t timestamp = time(NULL);
        printf("%lu: %d\n", timestamp, raw_adc_value);

        // Set the chip select pin low
        if (gpioWrite(CHIP_SELECT, 0) != 0) {
            fprintf(stderr, "Failed to set chip select pin low\n");
            gpio_spi_close(SPI_BUS);
            gpioTerminate();
            return 1;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close the SPI handle
    if (gpio_spi_close(SPI_BUS) != 0) {
        fprintf(stderr, "Failed to close SPI handle\n");
    }

    // Terminate pigpio
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }

    return 0;
}

