#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define ADS1115_ADDRESS 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_LO_W 0x00
#define ADS1115_REG_HI_W 0x01
#define ADS1115_REG_LO_X 0x02
#define ADS1115_REG_HI_X 0x03
#define ADS1115_REG_LO_Y 0x04
#define ADS1115_REG_HI_Y 0x05
#define ADS1115_REG_LO_Z 0x06
#define ADS1115_REG_HI_Z 0x07
#define ADS1115_REG_LO_STATUS 0x08
#define ADS1115_REG_HI_STATUS 0x09
#define ADS1115_REG_LO_DATA 0x0A
#define ADS1115_REG_HI_DATA 0x0B
#define ADS1115_REG_LO_CONFIG 0x0C
#define ADS1115_REG_HI_CONFIG 0x0D
#define ADS1115_REG_LO_LO_W 0x0E
#define ADS1115_REG_HI_LO_W 0x0F
#define ADS1115_REG_LO_LO_X 0x10
#define ADS1115_REG_HI_LO_X 0x11
#define ADS1115_REG_LO_LO_Y 0x12
#define ADS1115_REG_HI_LO_Y 0x13
#define ADS1115_REG_LO_LO_Z 0x14
#define ADS1115_REG_HI_LO_Z 0x15
#define ADS1115_REG_LO_LO_STATUS 0x16
#define ADS1115_REG_HI_LO_STATUS 0x17
#define ADS1115_REG_LO_LO_DATA 0x18
#define ADS1115_REG_HI_LO_DATA 0x19
#define ADS1115_REG_LO_LO_CONFIG 0x1A
#define ADS1115_REG_HI_LO_CONFIG 0x1B
#define ADS1115_REG_LO_LO_LO_W 0x1C
#define ADS1115_REG_HI_LO_LO_W 0x1D
#define ADS1115_REG_LO_LO_LO_X 0x1E
#define ADS1115_REG_HI_LO_LO_X 0x1F

#define MLX91219_SENSITIVITY 40e-3 // 40mV/A
#define MLX91219_ZERO_CURRENT 2.5 // 2.5V

int main() {
    int i2cHandle = gpioOpen(1, 2); // SDA
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        return 1;
    }

    int i2cAddress = ADS1115_ADDRESS;
    if (gpioI2CSetSlaveAddress(i2cHandle, i2cAddress) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioClose(i2cHandle);
        return 1;
    }

    uint16_t config = (1 << 15) | (1 << 14) | (1 << 13) | (1 << 12) | (1 << 9) | (1 << 8) | (1 << 5) | (1 << 4) | (1 << 3) | (1 << 2) | (1 << 1) | (1 << 0);
    uint8_t configBytes[2] = {config >> 8, config & 0xFF};
    if (gpioI2CWrite(i2cHandle, ADS1115_REG_CONFIG, 2, configBytes) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        gpioI2CSetSlaveAddress(i2cHandle, 0);
        gpioClose(i2cHandle);
        return 1;
    }

    uint16_t gain = (4 << 12) | (1 << 8) | (1 << 7);
    uint8_t gainBytes[2] = {gain >> 8, gain & 0xFF};
    if (gpioI2cWriteI2CBlockData(i2cHandle, ADS1115_REG_LO_CONFIG, 2, gainBytes) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        gpioI2CSetSlaveAddress(i2cHandle, 0);
        gpioClose(i2cHandle);
        return 1;
    }

    uint16_t dataRate = 128;
    uint8_t dataRateBytes[2] = {dataRate >> 8, dataRate & 0xFF};
    if (gpioI2cWriteI2CBlockData(i2cHandle, ADS1115_REG_LO_CONFIG, 2, dataRateBytes) < 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        gpioI2CSetSlaveAddress(i2cHandle, 0);
        gpioClose(i2cHandle);
        return 1;
    }

    while (1) {
        uint16_t data = 0;
        uint8_t dataBytes[2];
        if (gpioI2cReadI2CBlockData(i2cHandle, ADS1115_REG_LO_DATA, 2, dataBytes) < 0) {
            fprintf(stderr, "Failed to read from ADS1115 data register\n");
            gpioI2CSetSlaveAddress(i2cHandle, 0);
            gpioClose(i2cHandle);
            return 1;
        }
        data = (dataBytes[0] << 8) | dataBytes[1];

        float current = (data * MLX91219_SENSITIVITY) / 32768 - MLX91219_ZERO_CURRENT / 2.5;
        printf("Current: %.3f A\n", current);

        sleep(0.5);
    }

    gpioI2CSetSlaveAddress(i2cHandle, 0);
    gpioClose(i2cHandle);
    return 0;
}

void sigintHandler(int signal) {
    gpioI2CSetSlaveAddress(1, 0);
    gpioClose(1);
    gpioTerminate();
    exit(0);
}

int main() {
    signal(SIGINT, sigintHandler);
    return main();
}

