#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 4
#define MCP3008_CS 8
#define MCP3008_CHANNEL 0
#define SPI_SPEED 1000000
#define CSV_FILE "flame_data.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pin for flame sensor
    if (gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    int spi_fd = gpioOpen(MCP3008_CS, PI_SPI);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode and speed
    if (gpioSetSpeed(spi_fd, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read digital output from flame sensor
        int flame_detected = gpioRead(GPIO_FLAME_SENSOR);
        if (flame_detected < 0) {
            fprintf(stderr, "Failed to read flame sensor\n");
            break;
        }

        // Read analog output from MCP3008
        uint8_t data[2];
        if (spiXfer(spi_fd, MCP3008_CHANNEL, data, 2, 0) < 0) {
            fprintf(stderr, "Failed to read from MCP3008\n");
            break;
        }

        // Approximate temperature from analog reading
        int temperature = (int)((data[0] << 8 | data[1]) * 40.0 / 1023.0);

        // Log data
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fp, "%s,%d,%d\n", timestamp, flame_detected, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(fp);
    gpioClose(spi_fd);
    gpioTerminate();

    return 0;
}

