#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define FIRE_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define HEAT_SENSOR_ADC_ADDRESS 0x48
#define HEAT_SENSOR_ADC_CHANNEL 0
#define HEAT_SENSOR_ADC_GAIN 4
#define HEAT_SENSOR_ADC_SPS 128
#define HEAT_SENSOR_ADC_VREF 4096
#define HEAT_SENSOR_ADC_VMIN 0
#define HEAT_SENSOR_ADC_VMAX 3.3
#define HEAT_SENSOR_ADC_TMIN 20
#define HEAT_SENSOR_ADC_TMAX 80
#define HEAT_SENSOR_ADC_TTRIGGER 60
#define DEBOUNCE_INTERVAL 50
#define LOG_FILE "fire_log.txt"

volatile bool running = true;
bool flame_debounce = false;
uint32_t flame_debounce_timestamp = 0;

void flame_isr(int gpio, int level, uint32_t tick) {
    if (level == 0 && !flame_debounce) {
        flame_debounce = true;
        flame_debounce_timestamp = tick;
    }
}

int main() {
    int pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", pi);
