#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_FLAME_SENSOR 4
#define ADC_CHANNEL 0
#define SPI_CE 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SPEED 1000000
#define CSV_FILE "flame_data.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO for flame sensor
    if (gpioSetMode(GPIO_FLAME_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO for flame sensor\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI
    int spi = gpioOpen(SPI_CE, SPI_SPEED);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode
    if (gpioSetMode(SPI_SCLK, PI_ALT5) < 0 || gpioSetMode(SPI_MOSI, PI_ALT5) < 0 || gpioSetMode(SPI_MISO, PI_ALT5) < 0) {
        fprintf(stderr, "Failed to set up SPI mode\n");
        gpioClose(spi);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for append
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file for writing\n");
        gpioClose(spi);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler for SIGINT\n");
        fclose(fp);
        gpioClose(spi);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read flame sensor state
        int flame_state = gpioRead(GPIO_FLAME_SENSOR);
        if (flame_state < 0) {
            fprintf(stderr, "Failed to read flame sensor state\n");
            continue;
        }

        // Read ADC value
        uint16_t adc_value;
        if (spiXfer(spi, 0, &adc_value, 2, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Scale ADC value to temperature
        float temperature = (adc_value * 10.0f) / 1024.0f;

        // Log data to CSV file
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);
        fprintf(fp, "%s,%d,%f\n", timestamp, flame_state, temperature);

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(fp);
    gpioClose(spi);
    gpioTerminate();
    return 0;
}

