#define CO_SENSOR_ADDRESS 0x4D // I2C address of the MICS-4514 sensor
#define CO_ALERT_THRESHOLD 25 // 25 PPM CO alert threshold
#define CO_LOG_FILE "co_log.txt"
#define ALERT_LOG_FILE "alert_log.txt"

// Function to calculate CO level in PPM from 16-bit ADC reading
float calculate_co_ppm(uint16_t ox_reading) {
    // The MICS-4514 sensor has a linear response to CO concentration
    // The formula is: CO_ppm = (ox_reading * 100) / 65536
    return (float)ox_reading * 100 / 65536;
}

// Function to log CO reading to file
void log_co_reading(float co_ppm) {
    FILE *co_log = fopen(CO_LOG_FILE, "a");
    if (co_log == NULL) {
        perror("Error opening CO log file");
        exit(EXIT_FAILURE);
    }
    fprintf(co_log, "%.2f\n", co_log, co_ppm);
    fclose(co_log);
}

// Function to log alert to file
void log_alert() {
    FILE *alert_log = fopen(ALERT_LOG_FILE, "a");
    if (alert_log == NULL) {
        perror("Error opening alert log file");
        exit(EXIT_FAILURE);
    }
    fprintf(alert_log, "CO alert: 25 PPM threshold exceeded\n");
    fclose(alert_log);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release I2C bus and close files on exit
    gpioI2COpen(1, CO_SENSOR_ADDRESS, NULL);
    fclose(stdin);
    fclose(stdout);
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO library\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    int i2c_bus = gpioI2COpen(1, CO_SENSOR_ADDRESS, NULL);
    if (i2c_bus < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        gpioI2COpen(1, CO_SENSOR_ADDRESS, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Read 4 bytes from the sensor (2 bytes for OX and 2 bytes for RED)
        uint8_t buffer[4];
        if (i2cReadReg8(i2c_bus, 0x00, buffer, 4) < 0) {
            fprintf(stderr, "Error reading from sensor\n");
            gpioI2COpen(1, CO_SENSOR_ADDRESS, NULL);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        // Extract 16-bit ADC readings from the buffer
        uint16_t ox_reading = (buffer[0] << 8) | buffer[1];
        uint16_t red_reading = (buffer[2] << 8) | buffer[3];

        // Calculate CO level in PPM
        float co_ppm = calculate_co_ppm(ox_reading);

        // Log CO reading
        log_co_reading(co_ppm);

        // Check if CO level exceeds the alert threshold
        if (co_ppm >= CO_ALERT_THRESHOLD) {
            log_alert();
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Release I2C bus and close files on exit
    gpioI2COpen(1, CO_SENSOR_ADDRESS, NULL);
    fclose(stdin);
    fclose(stdout);
    gpioTerminate();
    return EXIT_SUCCESS;
}

