#define MIC1_ADDRESS 0x48
#define MIC2_ADDRESS 0x49
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1
#define SAMPLE_RATE 100  // ms
#define REFERENCE_PRESSURE 20e-6  // Pa
#define MIC_SENSITIVITY -38  // dBV/Pa
#define LOG_FILE "audio_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    gpioTerminate();
    fclose(log_file);
    printf("Cleaned up\n");
    exit(0);
}

int main() {
    int mic1_handle = gpioOpen(1, MIC1_CHANNEL, PI_I2C);
    int mic2_handle = gpioOpen(1, MIC2_CHANNEL, PI_I2C);

    if (mic1_handle < 0 || mic2_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        uint8_t data1[2];
        uint8_t data2[2];

        if (gpioI2CRead(mic1_handle, MIC1_ADDRESS, 0x00, data1, 2) != 2) {
            fprintf(log_file, "%f,%f\n", -999.0, -999.0);
            continue;
        }

        if (gpioI2CRead(mic2_handle, MIC2_ADDRESS, 0x00, data2, 2) != 2) {
            fprintf(log_file, "%f,%f\n", -999.0, -999.0);
            continue;
        }

        int16_t mic1_value = (data1[0] << 8) | data1[1];
        int16_t mic2_value = (data2[0] << 8) | data2[1];

        float mic1_level = 20 * log10(1 + (mic1_value / 32768.0) * REFERENCE_PRESSURE / (1 << 15)) + MIC_SENSITIVITY;
        float mic2_level = 20 * log10(1 + (mic2_value / 32768.0) * REFERENCE_PRESSURE / (1 << 15)) + MIC_SENSITIVITY;

        fprintf(log_file, "%f,%f\n", mic1_level, mic2_level);

        usleep(SAMPLE_RATE * 1000);
    }

    cleanup();
    return 0;
}

