#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define constants
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL A0
#define ADC_GAIN 1
#define ADC_REFERENCE 5.0
#define CURRENT_THRESHOLD 50.0
#define SAMPLE_RATE 10.0
#define BUFFER_SIZE 100
#define LED_PIN 17

// Define a struct to hold the circular buffer
typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
    int size;
} Buffer;

// Function to initialize the buffer
void buffer_init(Buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->size = 0;
}

// Function to add an element to the buffer
void buffer_add(Buffer *buf, float value) {
    if (buf->size < BUFFER_SIZE) {
        buf->data[buf->head] = value;
        buf->head = (buf->head + 1) % BUFFER_SIZE;
        buf->size++;
    }
}

// Function to get the average of the buffer
float buffer_average(Buffer *buf) {
    float sum = 0.0;
    for (int i = 0; i < buf->size; i++) {
        sum += buf->data[(buf->tail + i) % BUFFER_SIZE];
    }
    return sum / buf->size;
}

// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    // Turn off the LED
    gpioWrite(LED_PIN, 0);
    // Release resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the LED pin as an output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up LED pin\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the buffer
    Buffer buffer;
    buffer_init(&buffer);

    // Set up the I2C bus
    if (i2cOpen(1, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the ADS1115 ADC
    if (i2cWriteDevice(1, ADC_ADDRESS, 0x01, 0x84) < 0) {
        fprintf(stderr, "Failed to set up ADS1115 ADC\n");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC channel
    if (i2cWriteDevice(1, ADC_ADDRESS, 0x01, 0x84 | (ADC_CHANNEL << 4)) < 0) {
        fprintf(stderr, "Failed to set up ADC channel\n");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC gain
    if (i2cWriteDevice(1, ADC_ADDRESS, 0x01, 0x84 | (ADC_GAIN << 4)) < 0) {
        fprintf(stderr, "Failed to set up ADC gain\n");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC reference
    if (i2cWriteDevice(1, ADC_ADDRESS, 0x00, 0x03) < 0) {
        fprintf(stderr, "Failed to set up ADC reference\n");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        unsigned short adc_value;
        if (i2cReadDevice(1, ADC_ADDRESS, 0x00, &adc_value, 2) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            i2cClose(1);
            gpioTerminate();
            return 1;
        }

        // Convert the ADC value to a voltage
        float voltage = (adc_value * ADC_REFERENCE) / 32768.0;

        // Convert the voltage to a current
        float current = (voltage - 0.5) / (4.5 - 0.5) * 100.0;

        // Add the current to the buffer
        buffer_add(&buffer, current);

        // Check if the buffer is full
        if (buffer.size == BUFFER_SIZE) {
            // Get the average current
            float average_current = buffer_average(&buffer);

            // Check if the average current exceeds the threshold
            if (average_current > CURRENT_THRESHOLD) {
                // Turn on the LED
                gpioWrite(LED_PIN, 1);
            } else {
                // Turn off the LED
                gpioWrite(LED_PIN, 0);
            }
        }

        // Sleep for a short period
        usleep((unsigned int)(1000000 / SAMPLE_RATE));
    }

    // Release resources
    i2cClose(1);
    gpioTerminate();

    return 0;
}

