#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define REG_ID 0x12
#define REG_ATIME 0x01
#define REG_CONTROL 0x0F
#define REG_ENABLE 0x00
#define REG_CLEAR 0x14
#define REG_RED 0x15
#define REG_GREEN 0x16
#define REG_BLUE 0x17
#define REG_TEMP 0x18
#define REG_RAW 0x19
#define REG_ENABLE_ADC 0x02

#define MAX_READ_FAILURES 3

int i2c_fd;
int read_failures = 0;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (fclose(color_log) != 0) {
        perror("fclose");
    }
    gpioTerminate();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    if ((i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(1);
    }

    char filename[] = "color_log.csv";
    FILE *color_log = fopen(filename, "a");
    if (color_log == NULL) {
        if (errno == ENOENT) {
            color_log = fopen(filename, "w");
            if (color_log == NULL) {
                fprintf(stderr, "Failed to open %s for writing\n", filename);
                gpioTerminate();
                exit(1);
            }
            fprintf(color_log, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
        } else {
            fprintf(stderr, "Failed to open %s for appending\n", filename);
            gpioTerminate();
            exit(1);
        }
    }

    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));
        uint8_t id;
        if (i2c_read(i2c_fd, REG_ID, &id, 1) != 1) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        if ((id & 0x0F) != 0x44) {
            fprintf(stderr, "Invalid TCS34725 ID\n");
            gpioTerminate();
            exit(1);
        }
        read_failures = 0;

        uint8_t atime;
        if (i2c_read(i2c_fd, REG_ATIME, &atime, 1) != 1) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        atime = 0xFF; // Set integration time to 2.4 ms

        uint8_t control;
        if (i2c_read(i2c_fd, REG_CONTROL, &control, 1) != 1) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        control |= 0x01; // Set gain to 4x
        control &= ~0x02; // Clear ADC enable bit
        control |= 0x02; // Enable ADC

        if (i2c_write(i2c_fd, REG_ATIME, &atime, 1) != 1) {
            fprintf(stderr, "I2C write failure\n");
            gpioTerminate();
            exit(1);
        }
        if (i2c_write(i2c_fd, REG_CONTROL, &control, 1) != 1) {
            fprintf(stderr, "I2C write failure\n");
            gpioTerminate();
            exit(1);
        }

        usleep(3000); // Wait 3 ms after power-on

        uint16_t clear, red, green, blue;
        if (i2c_read(i2c_fd, REG_CLEAR, &clear, 2) != 2) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        if (i2c_read(i2c_fd, REG_RED, &red, 2) != 2) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        if (i2c_read(i2c_fd, REG_GREEN, &green, 2) != 2) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        if (i2c_read(i2c_fd, REG_BLUE, &blue, 2) != 2) {
            if (errno == EIO) {
                fprintf(stderr, "Transient I2C read failure\n");
                read_failures++;
            } else {
                fprintf(stderr, "I2C read failure\n");
                gpioTerminate();
                exit(1);
            }
            if (read_failures >= MAX_READ_FAILURES) {
                gpioTerminate();
                exit(1);
            }
            continue;
        }
        read_failures = 0;

        fprintf(color_log, "%s,%04x,%04x,%04x,%04x\n", timestamp, clear, red, green, blue);
        fflush(color_log);
        sleep(1);
    }

    if (fclose(color_log) != 0) {
        perror("fclose");
    }
    gpioTerminate();
    return 0;
}

