#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define REG_PRESSURE 0x00
#define LOG_FILE "pressure_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_pressure(double pressure_kPa) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm* now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", now_tm);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s,%.6f\n", timestamp, pressure_kPa);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }
    if (gpioSetMode(I2C_BUS, PI_I2C_SMBUS) < 0) {
        fprintf(stderr, "Error setting I2C mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    int i2c_handle = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    FILE* log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "timestamp,pressure_kPa\n");
    fclose(log_file);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        int result = i2cReadReg8(i2c_handle, REG_PRESSURE, 2);
        if (result < 0) {
            fprintf(stderr, "Error reading pressure register 0x%02x: %s\n", REG_PRESSURE, strerror(errno));
            continue;
        }
        uint16_t raw_value = (result >> 8) | (result << 8);
        double pressure_kPa = (raw_value / 65535.0) * 500.0;
        log_pressure(pressure_kPa);
        sleep(1);
    }

    fclose(log_file);
    gpioClose(i2c_handle);
    gpioTerminate();
    return 0;
}

