#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define PRESSURE_SENSOR_ADDRESS 0x48
#define ADS1115_ADDRESS 0x48
#define AIN0 0
#define AIN1 1
#define GAIN 2/3
#define FS 6144
#define SPS 128
#define LED_PIN 17
#define PRESSURE_MAX 105.0

// Define signal handler for SIGINT
void sigint_handler(int sig) {
    // Release resources
    gpioTerminate();
    exit(0);
}

// Define linear transfer function for pressure
float pressure_voltage_to_pressure(float voltage) {
    return (voltage / 5.0) * 400.0;
}

// Define simplified linear NTC approximation for temperature
float voltage_to_temperature(float voltage) {
    return (voltage - 1.0) * 100.0;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize ADS1115
    int ads1115_fd = gpioI2COpen(ADS1115_ADDRESS, 1);
    if (ads1115_fd < 0) {
        fprintf(stderr, "Failed to open ADS1115\n");
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    int config = (GAIN << 12) | (SPS << 8) | (AIN0 << 4) | AIN0;
    if (gpioI2CWriteByte(ads1115_fd, 0x01, config) < 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        gpioI2CClose(ads1115_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize pressure and temperature variables
    float pressure = 0.0;
    float temperature = 0.0;

    // Main loop
    while (1) {
        // Read pressure and temperature from ADS1115
        int pressure_voltage = 0;
        int temperature_voltage = 0;
        for (int i = 0; i < 3; i++) {
            if (gpioI2CReadByte(ads1115_fd, 0x00, &pressure_voltage) < 0) {
                // Retry up to 3 times
                continue;
            }
            if (gpioI2CReadByte(ads1115_fd, 0x01, &temperature_voltage) < 0) {
                // Retry up to 3 times
                continue;
            }
            break;
        }
        if (pressure_voltage < 0 || temperature_voltage < 0) {
            // Sensor-absent or bus-error path
            fprintf(stderr, "Failed to read from ADS1115\n");
            gpioI2CClose(ads1115_fd);
            gpioTerminate();
            return 1;
        }

        // Convert ADC voltage to pressure and temperature
        pressure = pressure_voltage_to_pressure(pressure_voltage / 32768.0);
        temperature = voltage_to_temperature(temperature_voltage / 32768.0);

        // Display pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Drive warning LED
        if (pressure > PRESSURE_MAX) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    gpioI2CClose(ads1115_fd);
    gpioTerminate();

    return 0;
}

