#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_SCK_PIN 11
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_MAX_VALUE 1024
#define ADC_VCC 3.3
#define ADC_VCC_HALF 1.65
#define CURRENT_SENSITIVITY 66e-3
#define CURRENT_MAX 10.0
#define GPIO_SHUTDOWN_PIN 27
#define LOG_FILE "current_log.txt"

int main() {
    int spi_fd;
    int gpio_fd;
    int result;
    uint8_t buffer[3];
    uint16_t adc_value;
    double current;
    struct timeval tv;
    FILE *log_file;

    // Initialize pigpio
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_fd);
        return 1;
    }

    // Set up GPIO shutdown pin
    if (gpioSetMode(GPIO_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", GPIO_SHUTDOWN_PIN);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_SHUTDOWN_PIN, 0);

    // Open SPI device
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI parameters
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %d\n", spi_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI speed: %d\n", spi_fd);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        memset(buffer, 0, 3);
        buffer[0] = 0x01; // Start bit
        buffer[1] = 0x01; // Single-ended channel configuration
        buffer[2] = 0x00; // Zero pad byte
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, buffer, buffer, 3) < 0)) {
            fprintf(stderr, "Failed to transfer SPI data: %d\n", spi_fd);
            close(spi_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }
        adc_value = (buffer[1] << 8) | buffer[2];

        // Check for invalid ADC value
        if (adc_value == 0 || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            close(spi_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Convert ADC value to voltage
        double voltage = (adc_value / (double) ADC_MAX_VALUE) * ADC_VCC;

        // Convert voltage to current
        current = (voltage - ADC_VCC_HALF) / CURRENT_SENSITIVITY;

        // Check for overcurrent
        if (current > CURRENT_MAX) {
            gpioWrite(GPIO_SHUTDOWN_PIN, 1);
            fprintf(log_file, "%lu: OVERCURRENT\n", (unsigned long) time(NULL));
            fclose(log_file);
            close(spi_fd);
            gpioTerminate();
            return 0;
        }

        // Log reading
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%lu: %f A\n", (unsigned long) tv.tv_sec, current);
        fflush(log_file);

        // Sleep
        usleep(100000);
    }

    // Clean up
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    close(spi_fd);
    fclose(log_file);
    gpioWrite(GPIO_SHUTDOWN_PIN, 0);
    gpioTerminate();
    exit(0);
}

// Register signal handler
void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
    }
}

