    close(log_fd);

    // Turn off alarm
    gpioSetMode(CO_ALARM_GPIO, PI_OUTPUT);
    gpioWrite(CO_ALARM_GPIO, 0);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

