    running = 0;
}

int main() {
    int spi_handle = -1;
    FILE *log_file = NULL;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", gpioError());
        return 1;
    }

    // Set up SPI pins
    if (gpioSetMode(ADC_CLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up SPI clock pin: %d\n", gpioError());
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_MISO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up SPI MISO pin: %d\n", gpioError());
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_MOSI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up SPI MOSI pin: %d\n", gpioError());
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ADC_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up SPI CS pin: %d\n", gpioError());
        gpioTerminate();
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %d\n", errno);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
