        // Perform SPI transfer
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed: %d\n", spiError());
            continue;
        }

        // Extract 10-bit ADC value
        uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];

        // Convert ADC value to methane concentration
        double concentration = (adc_value / 1023.0) * 5000.0;

        // Log reading
        struct tm time;
        time_t now = time(NULL);
        localtime_r(&now, &time);
        char log_line[256];
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", &time);
        fprintf(log_file, "%s %f PPM\n", log_line, concentration);

        // Check for alarm
        if (concentration > 1000.0) {
            fprintf(stderr, "Methane leak detected: %f PPM\n", concentration);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    fclose(log_file);
