#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define ADC_ADDRESS 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 1
#define ADC_RATE 1
#define PRESSURE_OFFSET 0.5
#define PRESSURE_SENSITIVITY 0.1
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0

// Define the pressure conversion function
double pressure_from_adc(int adc_value) {
    return (adc_value * PRESSURE_SENSITIVITY) + PRESSURE_OFFSET;
}

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Release resources
    gpio_i2c_close();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up I2C bus 1
    if (gpioI2CSetup(1, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Open the ADS1115 ADC
    int fd = gpioI2COpen(1, ADC_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open ADS1115 ADC\n");
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC
    uint8_t config = 0x01; // Single-ended input, 16-bit resolution
    if (gpioI2CWriteByte(fd, 0x01, config) < 0) {
        fprintf(stderr, "Failed to set up ADS1115 ADC\n");
        gpioI2CClose(fd);
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC channel
    config = 0x00; // Select AIN0
    if (gpioI2CWriteByte(fd, 0x01, config) < 0) {
        fprintf(stderr, "Failed to set up ADS1115 ADC channel\n");
        gpioI2CClose(fd);
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC gain
    config = ADC_GAIN << 3; // Set gain to 1x
    if (gpioI2CWriteByte(fd, 0x01, config) < 0) {
        fprintf(stderr, "Failed to set up ADS1115 ADC gain\n");
        gpioI2CClose(fd);
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Set up the ADC rate
    config = ADC_RATE << 4; // Set rate to 1 SPS
    if (gpioI2CWriteByte(fd, 0x01, config) < 0) {
        fprintf(stderr, "Failed to set up ADS1115 ADC rate\n");
        gpioI2CClose(fd);
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the log file
    FILE *log_file = fopen("pressure_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(fd);
        gpioI2CSetup(1, 0);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value
        int adc_value;
        if (gpioI2CReadByte(fd, 0x00, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADS1115 ADC value\n");
            fclose(log_file);
            gpioI2CClose(fd);
            gpioI2CSetup(1, 0);
            gpioTerminate();
            return 1;
        }

        // Convert the ADC value to pressure
        double pressure = pressure_from_adc(adc_value);

        // Validate the pressure range
        if (pressure < PRESSURE_MIN || pressure > PRESSURE_MAX) {
            fprintf(stderr, "Invalid pressure reading: %f kPa\n", pressure);
            continue;
        }

        // Log the pressure reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %f\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    fclose(log_file);
    gpioI2CClose(fd);
    gpioI2CSetup(1, 0);
    gpioTerminate();

    return 0;
}

