        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
        fprintf(log_file, "%s %f\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    fclose(log_file);
    gpioI2CClose(fd);
    gpioI2CSetup(1, 0);
    gpioTerminate();

    return 0;
