// Define constants
#define ADC_CS_PIN 8
#define ADC_CLK_PIN 11
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_VCC_PIN 17
#define ADC_GND_PIN 23
#define ADC_GAIN 1
#define ADC_OFFSET 0
#define ADC_MAX 4095
#define ADC_MIN 0
#define ADC_BITS 12
#define ADC_VCC 5.0
#define ADC_R0 10000.0
#define ADC_BETA 3950.0
#define HUMIDITY_ALERT 80.0
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity exceeded 80%."

// Define the sensor's transfer function
double calculateHumidity(double voltage) {
    return (voltage - 0.824) / 0.0315 * 100;
}

// Define the thermistor equation
double calculateTemperature(double voltage) {
    double resistance = ADC_VCC / (voltage / ADC_VCC) - 1;
    return 1 / (ADC_BETA * log(resistance / ADC_R0)) - 273.15;
}

// Define the signal handler for SIGINT and SIGTERM
void signalHandler(int signal) {
    // Release resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Set up ADC pins
    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioSetMode(ADC_CLK_PIN, PI_OUTPUT);
    gpioSetMode(ADC_MOSI_PIN, PI_OUTPUT);
    gpioSetMode(ADC_MISO_PIN, PI_INPUT);
    gpioSetMode(ADC_VCC_PIN, PI_OUTPUT);
    gpioSetMode(ADC_GND_PIN, PI_OUTPUT);

    // Set up ADC CS pin as output low
    gpioWrite(ADC_CS_PIN, 0);

    // Initialize ADC
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode
    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 0,
        .speed_hz = 1000000,
        .bits_per_word = 16,
        .cs_change = 1,
        .delay_usecs = 0,
        .bits_per_word = 16,
        .mode = 0,
        .cs_change = 1
    };

    // Set up ADC gain
    uint8_t gain = ADC_GAIN;
    uint8_t offset = ADC_OFFSET;
    uint8_t config = (gain << 4) | (offset & 0x0F);
    if (ioctl(adc_fd, SPI_IOC_WR_MAX_LENGTH, &config) < 0) {
        fprintf(stderr, "Failed to set ADC gain.\n");
        close(adc_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("humidity_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        close(adc_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        // Read ADC values
        uint16_t humidity_value = 0;
        uint16_t temperature_value = 0;
        transfer.tx_buf = (uint8_t *)&humidity_value;
        transfer.rx_buf = (uint8_t *)&humidity_value;
        transfer.len = 2;
        if (ioctl(adc_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            fprintf(stderr, "Failed to read ADC value.\n");
            close(adc_fd);
            gpioTerminate();
            return 1;
        }

        // Calculate humidity and temperature
        double humidity = calculateHumidity((double)humidity_value / ADC_MAX * ADC_VCC);
        double temperature = calculateTemperature((double)temperature_value / ADC_MAX * ADC_VCC);

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);

        // Check for humidity alert
        if (humidity > HUMIDITY_ALERT) {
            // Send email
            FILE *email_file = popen("ssmtp -t -i -f root@example.com < email.txt", "w");
            if (!email_file) {
                fprintf(stderr, "Failed to open email file.\n");
                fclose(log_file);
                close(adc_fd);
                gpioTerminate();
                return 1;
            }
            fprintf(email_file, "Subject: %s\n", EMAIL_SUBJECT);
            fprintf(email_file, "%s\n", EMAIL_BODY);
            pclose(email_file);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    fclose(log_file);
    close(adc_fd);
    gpioTerminate();

    return 0;
}

