        .speed_hz = 1000000,
        .bits_per_word = 8,
        .mode = SPI_MODE_0,
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &transfer.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    // Open CS line
    cs_line = gpiod_chip_get_line(chip, GPIO_CS);
    if (!cs_line) {
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open SCLK line
    sclk_line = gpiod_chip_get_line(chip, 11);
    if (!sclk_line) {
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open MOSI line
    mosi_line = gpiod_chip_get_line(chip, 10);
    if (!mosi_line) {
        gpiod_line_release(sclk_line);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open MISO line
    miso_line = gpiod_chip_get_line(chip, 9);
    if (!miso_line) {
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Initialize CS line as output
    if (gpiod_line_request_output(cs_line, 0) < 0) {
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(filename, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(miso_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(sclk_line);
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Check if log file is new
    if (fseek(log_file, 0, SEEK_END) == 0) {
        if (ftruncate(fileno(log_file), 0) < 0) {
            perror("Failed to truncate log file");
            fclose(log_file);
            gpiod_line_release(miso_line);
            gpiod_line_release(mosi_line);
            gpiod_line_release(sclk_line);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
        if (fseek(log_file, 0, SEEK_SET) < 0) {
            perror("Failed to seek log file");
            fclose(log_file);
            gpiod_line_release(miso_line);
            gpiod_line_release(mosi_line);
            gpiod_line_release(sclk_line);
            gpiod_line_release(cs_line);
            gpiod_chip_close(chip);
            close(spi_fd);
            return 1;
        }
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    // Main loop
    while (1) {
        // Set CS line low
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Failed to set CS line low");
            break;
        }

        // Transfer data
        transfer.tx_buf = (uint8_t *)&adc_value;
        transfer.rx_buf = (uint8_t *)&adc_value;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("Failed to transfer data");
            break;
        }

        // Clear CS line
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Failed to clear CS line");
            break;
        }

        // Validate ADC reading
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC reading: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value / ADC_MAX * ADC_VREF;

        // Convert voltage to temperature
        temperature_celsius = (voltage - 0.5) / 0.01;

        // Check temperature range
        if (temperature_celsius < TMP36_MIN || temperature_celsius > TMP36_MAX) {
            fprintf(stderr, "Temperature out of range: %f\n", temperature_celsius);
            continue;
        }

        // Log temperature
        time_t timestamp = time(NULL);
        struct tm *timeinfo;
        timeinfo = localtime(&timestamp);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
        fprintf(log_file, "%s,%f\n", buffer, temperature_celsius);

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file
    fclose(log_file);

    // Release GPIO lines
    gpiod_line_release(miso_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(cs_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close SPI device
    close(spi_fd);

    return 0;
}

// Signal handlers
void sigint_handler(int sig) {
    // Close log file
    fclose(log_file);

    // Release GPIO lines
    gpiod_line_release(miso_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(cs_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close SPI device
    close(spi_fd);

    exit(0);
}

void sigterm_handler(int sig) {
    // Close log file
    fclose(log_file);

    // Release GPIO lines
    gpiod_line_release(miso_line);
    gpiod_line_release(mosi_line);
    gpiod_line_release(sclk_line);
    gpiod_line_release(cs_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    // Close SPI device
    close(spi_fd);

    exit(0);
}

int main() {
    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to install SIGINT handler");
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install SIGTERM handler");
        return 1;
    }

    // Call main loop
    return main();
}
