#define ACCEL_SUPPLY 3.3
#define ACCEL_0G 1.65
#define ACCEL_SENSITIVITY 300e-3
#define ACCEL_MAX 2.0

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", gpioErrorStr(gpioError()));
    }
    if (fclose(log_file) != 0) {
