int main() {
    int spi_fd;
    int adc_channel[3] = {ADC_CHANNEL_X, ADC_CHANNEL_Y, ADC_CHANNEL_Z};
    float accel_x, accel_y, accel_z;
    float accel_magnitude;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrorStr(gpioError()));
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(ADC_CS_PIN, ADC_CS) != 0) {
        fprintf(stderr, "Error setting up GPIO pin %d: %s\n", ADC_CS_PIN, gpioErrorStr(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    if ((spi_fd = gpioOpen(ADC_CS_PIN, ADC_CLK, ADC_MOSI, ADC_MISO, ADC_SCK, ADC_FREQ, ADC_MODE)) < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", gpioErrorStr(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        // Select ADC channel
        for (int i = 0; i < 3; i++) {
            if (gpioSetMode(ADC_CS_PIN, ADC_CS_INIT) != 0) {
                fprintf(stderr, "Error setting up GPIO pin %d: %s\n", ADC_CS_PIN, gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }
            if (gpioWrite(ADC_CS_PIN, ADC_CS_HIGH) != 0) {
                fprintf(stderr, "Error setting GPIO pin %d high: %s\n", ADC_CS_PIN, gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }
            if (gpioDelayMicroseconds(1) != 0) {
                fprintf(stderr, "Error delaying: %s\n", gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }
            if (gpioWrite(ADC_CS_PIN, ADC_CS_LOW) != 0) {
                fprintf(stderr, "Error setting GPIO pin %d low: %s\n", ADC_CS_PIN, gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }
            if (gpioDelayMicroseconds(1) != 0) {
                fprintf(stderr, "Error delaying: %s\n", gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }

            // Read ADC value
            int adc_value;
            if (gpioSPIData(spi_fd, adc_channel[i], &adc_value, 1) != 0) {
                fprintf(stderr, "Error reading ADC value: %s\n", gpioErrorStr(gpioError()));
                cleanup();
                return 1;
            }

            // Validate ADC value
            if (adc_value < 0 || adc_value > ADC_MAX) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                cleanup();
                return 1;
            }

            // Compute acceleration
            accel_x = (float)adc_value * ACCEL_SENSITIVITY / ACCEL_SUPPLY;
            accel_y = (float)adc_value * ACCEL_SENSITIVITY / ACCEL_SUPPLY;
            accel_z = (float)adc_value * ACCEL_SENSITIVITY / ACCEL_SUPPLY;
            accel_magnitude = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

            // Log data
            fprintf(log_file, "%f,%f,%f,%f\n", accel_magnitude, accel_x, accel_y, accel_z);

            // Check for impact
            if (accel_magnitude > ACCEL_MAX) {
                fprintf(log_file, "IMPACT DETECTED\n");
            }

            // Delay
            usleep(100000);
        }
    }

    // Cleanup
    cleanup();

    return 0;
}

