#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FIFO_REG 0xC1
#define CMD_REG 0xC0
#define MAX_LOG_SIZE 1024

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Unix Timestamp,HR (bpm),SpO2 (%),Error Flag\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Write command to trigger measurement
        if (i2cWriteReg8(i2c_fd, CMD_REG, 0x01) < 0) {
            fprintf(stderr, "Transient I2C error\n");
            fprintf(log_file, "%lu,0,0,2\n", time(NULL));
            fflush(log_file);
            sleep(1);
            continue;
        }

        // Read FIFO register
        uint16_t fifo_data;
        if (i2cReadReg16(i2c_fd, FIFO_REG, &fifo_data) < 0) {
            fprintf(stderr, "Transient I2C error\n");
            fprintf(log_file, "%lu,0,0,2\n", time(NULL));
            fflush(log_file);
            sleep(1);
            continue;
        }

        // Read IR and RED ADC values from FIFO
        uint16_t ir_adc = (fifo_data >> 8) & 0xFF;
        uint16_t red_adc = fifo_data & 0xFF;

        // Log data
        fprintf(log_file, "%lu,%u,%u,0\n", time(NULL), ir_adc, red_adc);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C handle
    i2cClose(i2c_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

