#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define MEASUREMENT_RESPONSE_SIZE 6
#define CSV_LOG_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5000  // 5 seconds

// ICP-10125 calibration formulas
#define CALIBRATION_PRESSURE_A 0.00006103515625
#define CALIBRATION_PRESSURE_B 0.00000048828125
#define CALIBRATION_PRESSURE_C 0.0000000009765625
#define CALIBRATION_TEMPERATURE_A 0.0009765625
#define CALIBRATION_TEMPERATURE_B 0.0000009765625

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nReceived signal %d, exiting...\n", signal);
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

int main() {
    int i2c_fd;
    FILE *csv_file;
    char buffer[MEASUREMENT_RESPONSE_SIZE];
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data ioctl_data;
    struct timeval timeout;
    fd_set read_fds;
    int retry_count = 0;
    bool retry = true;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Open CSV log file
    csv_file = fopen(CSV_LOG_FILE, "a");
    if (!csv_file) {
        perror("Failed to open CSV log file");
        close(i2c_fd);
        exit(1);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Wait for 5 seconds
        usleep(SAMPLE_INTERVAL * 1000);

        // Send measurement command
        msg.addr = I2C_ADDRESS;
        msg.fmt = I2C_M_RD;
        msg.len = 1;
        msg.buf = &MEASUREMENT_COMMAND;
        ioctl_data.msgs = &msg;
        ioctl_data.nmsgs = 1;
        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            if (retry) {
                retry_count++;
                if (retry_count >= 5) {
                    retry = false;
                    perror("Failed to send measurement command");
                }
                continue;
            } else {
                perror("Failed to send measurement command");
                close(i2c_fd);
                fclose(csv_file);
                exit(1);
            }
        }

        // Wait for conversion to finish
        timeout.tv_sec = 0;
        timeout.tv_usec = 100000;
        FD_ZERO(&read_fds);
        FD_SET(i2c_fd, &read_fds);
        if (select(i2c_fd + 1, &read_fds, NULL, NULL, &timeout) < 0) {
            perror("Failed to wait for conversion to finish");
            close(i2c_fd);
            fclose(csv_file);
            exit(1);
        }

        // Read measurement response
        msg.addr = I2C_ADDRESS;
        msg.fmt = I2C_M_RD;
        msg.len = MEASUREMENT_RESPONSE_SIZE;
        msg.buf = buffer;
        ioctl_data.msgs = &msg;
        ioctl_data.nmsgs = 1;
        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            if (retry) {
                retry_count++;
                if (retry_count >= 5) {
                    retry = false;
                    perror("Failed to read measurement response");
                }
                continue;
            } else {
                perror("Failed to read measurement response");
                close(i2c_fd);
                fclose(csv_file);
                exit(1);
            }
        }

        // Extract pressure and temperature values
        uint16_t pressure_msb = (buffer[0] << 8) | buffer[1];
        uint16_t pressure_lsb = (buffer[2] << 8) | buffer[3];
        uint16_t temperature_msb = (buffer[4] << 8) | buffer[5];

        // Apply calibration formulas
        float pressure = (pressure_msb << 8) | pressure_lsb;
        pressure = (pressure * CALIBRATION_PRESSURE_A) + CALIBRATION_PRESSURE_B + CALIBRATION_PRESSURE_C;
        float temperature = (temperature_msb * CALIBRATION_TEMPERATURE_A) + CALIBRATION_TEMPERATURE_B;

        // Log data to CSV file
        fprintf(csv_file, "%lu,%.2f,%.2f\n", time(NULL), pressure, temperature);
        fflush(csv_file);

        // Log data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
    }

    // Close I2C file descriptor and CSV log file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

