#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <libgpiod.h>

#define LOG_FILE "flame_log.txt"
#define BUZZER_GPIO 18
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define TEMPERATURE_FILE "ambient_temp.txt"
#define TEMPERATURE_FALLBACK 25.0
#define SAMPLING_INTERVAL 500000 // 500ms

// Function to read temperature from file
double read_temperature() {
    FILE *file = fopen(TEMPERATURE_FILE, "r");
    if (file == NULL) {
        return TEMPERATURE_FALLBACK;
    }

    char buffer[32];
    if (fgets(buffer, sizeof(buffer), file) == NULL) {
        fclose(file);
        return TEMPERATURE_FALLBACK;
    }

    double temperature;
    if (sscanf(buffer, "%lf", &temperature) != 1) {
        fclose(file);
        return TEMPERATURE_FALLBACK;
    }

    fclose(file);
    return temperature;
}

// Function to log data to file
void log_data(double raw_adc, double voltage, double compensated_voltage, double temperature, bool flame_detected) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s,%.0f,%.3f,%.3f,%.1f,%s\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected ? "true" : "false");
    fclose(file);
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_close();
    exit(0);
}

int main() {
    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", gpiod_error_str(errno));
        return 1;
    }

    // Initialize SPI
    int spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (uint64_t)0x00, // Start bit
        .rx_buf = (uint64_t)0x00, // Dummy byte
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
        .mode = SPI_MODE_0, // CPOL=0, CPHA=0
    };

    // Initialize buzzer
    struct gpiod_line *buzzer_line = gpiod_line_request_by_name(chip, "gpio18", GPIOD_LINE_ACTIVE_HIGH);
    if (buzzer_line == NULL) {
        fprintf(stderr, "Error requesting buzzer line: %s\n", gpiod_error_str(errno));
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_direction(buzzer_line, GPIOD_LINE_DIRECTION_OUTPUT);
    gpiod_line_export(buzzer_line);

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(buzzer_line);
        close(spi_fd);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    double temperature = read_temperature();
    while (1) {
        // Read ADC value
        struct spi_ioc_transfer transfer_copy = transfer;
        transfer_copy.tx_buf = (uint64_t)0x00; // Single-ended config
        int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1, &transfer_copy);
        if (ret < 0) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            log_data(-1, -1, -1, temperature, false);
            gpiod_line_set_value(buzzer_line, 0);
            continue;
        }

        uint16_t raw_adc = *(uint16_t *)transfer_copy.rx_buf;
        int retries = 0;
        while (raw_adc < 0 || raw_adc > ADC_MAX) {
            if (retries >= 3) {
                fprintf(stderr, "Error reading ADC value: out of range\n");
                log_data(-1, -1, -1, temperature, false);
                gpiod_line_set_value(buzzer_line, 0);
                break;
            }
            retries++;
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1, &transfer_copy);
            if (ret < 0) {
                fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
                log_data(-1, -1, -1, temperature, false);
                gpiod_line_set_value(buzzer_line, 0);
                break;
            }
            raw_adc = *(uint16_t *)transfer_copy.rx_buf;
        }

        // Compute compensated voltage
        double voltage = (double)raw_adc / ADC_MAX;
        double compensated_voltage = voltage + (temperature - 25.0) * 0.001;

        // Check for flame detection
        bool flame_detected = compensated_voltage > 1.0;

        // Log data
        log_data(raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Update buzzer state
        gpiod_line_set_value(buzzer_line, flame_detected ? 1 : 0);

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Clean up
    gpiod_line_release(buzzer_line);
    close(spi_fd);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

