#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define JSON_FILE "water_levels.json"
#define LED_PIN 17
#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define HYS 5

int main() {
    int spi_fd = -1;
    int gpio_fd = -1;
    FILE *json_file = NULL;
    bool led_state = false;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        pigpio_error("Failed to initialize pigpio");
        return 1;
    }

    // Open SPI channel 0 (CE0) at 1 MHz with SPI mode 0 (flags=0)
    if ((spi_fd = gpioOpen(8, 0)) < 0) {
        pigpio_error("Failed to open SPI channel 0");
        gpioTerminate();
        return 1;
    }
    if (gpioSetSpeed(spi_fd, 1000000) < 0) {
        pigpio_error("Failed to set SPI speed");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(spi_fd, 0) < 0) {
        pigpio_error("Failed to set SPI mode");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open JSON file for append
    if ((json_file = fopen(JSON_FILE, "a")) == NULL) {
        pigpio_error("Failed to open JSON file");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        pigpio_error("Failed to set LED pin mode");
        fclose(json_file);
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint32_t timestamp = (tv.tv_sec * 1000) + (tv.tv_usec / 1000);

        // Read ADC value from MCP3008 channel 0
        uint8_t rx[3];
        if (gpioSPISendReceive(spi_fd, 0x01, 0x80 | (ADC_CHANNEL << 4), 0x00, rx, 3) < 0) {
            pigpio_error("Failed to read ADC value");
            continue;
        }

        // Parse ADC value
        uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];

        // Convert ADC value to percentage
        double water_level = (adc_value * 100.0) / ADC_MAX;

        // Log reading to JSON file
        fprintf(json_file, "{\"timestamp\":%lu,\"water_level\":%.2f}\n", timestamp, water_level);
        fflush(json_file);

        // Turn LED on/off based on water level
        if (water_level > 75 && !led_state) {
            gpioWrite(LED_PIN, 1);
            led_state = true;
        } else if (water_level <= 70 && led_state) {
            gpioWrite(LED_PIN, 0);
            led_state = false;
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Clean up
    fclose(json_file);
    gpioClose(spi_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Stop main loop
    exit(0);
}

void sigterm_handler(int sig) {
    // Stop main loop
    exit(0);
}

void pigpio_error(const char *msg) {
    fprintf(stderr, "pigpio error: %s\n", msg);
}

// Register signal handlers
void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        pigpio_error("Failed to set SIGINT handler");
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        pigpio_error("Failed to set SIGTERM handler");
    }
}

