            pigpio_error("Failed to read ADC value");
            continue;
        }

        // Parse ADC value
        uint16_t adc_value = (rx[1] & 0x03) << 8 | rx[2];

        // Convert ADC value to percentage
        double water_level = (adc_value * 100.0) / ADC_MAX;

        // Log reading to JSON file
        fprintf(json_file, "{\"timestamp\":%lu,\"water_level\":%.2f}\n", timestamp, water_level);
        fflush(json_file);

        // Turn LED on/off based on water level
        if (water_level > 75 && !led_state) {
            gpioWrite(LED_PIN, 1);
            led_state = true;
        } else if (water_level <= 70 && led_state) {
            gpioWrite(LED_PIN, 0);
            led_state = false;
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Clean up
    fclose(json_file);
    gpioClose(spi_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    // Stop main loop
    exit(0);
}

void sigterm_handler(int sig) {
    // Stop main loop
    exit(0);
}

void pigpio_error(const char *msg) {
    fprintf(stderr, "pigpio error: %s\n", msg);
}

// Register signal handlers
void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        pigpio_error("Failed to set SIGINT handler");
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        pigpio_error("Failed to set SIGTERM handler");
    }
}
