#define ADC_R1 10000
#define ADC_R2 1000
#define ADC_FLOW_RATE 0.0000000001  // L/min per count

#define CSV_FILE "airflow_log.csv"

// Function to calculate flow rate from ADC reading
double calculate_flow_rate(uint16_t reading) {
    double voltage = (ADC_VCC / ADC_MAX) * (reading * ADC_GAIN);
    double flow_rate = (voltage / (ADC_VCC / (ADC_R1 + ADC_R2))) * ADC_FLOW_RATE;
    return flow_rate;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

