        gpioTerminate();
        return 1;
    }

    int sclk_fd = gpioOpen(0, 1);  // SCLK
    if (sclk_fd < 0) {
        fprintf(stderr, "Failed to open SPI0 SCLK\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

