    if (mosi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0 MOSI\n");
        gpioClose(spi_fd);
        gpioClose(sclk_fd);
        gpioTerminate();
        return 1;
    }

    int miso_fd = gpioOpen(0, 3);  // MISO
    if (miso_fd < 0) {
        fprintf(stderr, "Failed to open SPI0 MISO\n");
        gpioClose(spi_fd);
        gpioClose(sclk_fd);
        gpioClose(mosi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up SPI0 mode
    if (gpioSetMode(spi_fd, PI_SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI0 mode\n");
        gpioClose(spi_fd);
        gpioClose(sclk_fd);
        gpioClose(mosi_fd);
        gpioClose(miso_fd);
        gpioTerminate();
        return 1;
    }

