    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open %s for writing\n", CSV_FILE);
        gpioClose(spi_fd);
        gpioClose(sclk_fd);
        gpioClose(mosi_fd);
        gpioClose(miso_fd);
        gpioTerminate();
        return 1;
    }

