        fprintf(stderr, "Failed to seek to end of %s\n", CSV_FILE);
        fclose(file);
        gpioClose(spi_fd);
        gpioClose(sclk_fd);
        gpioClose(mosi_fd);
        gpioClose(miso_fd);
        gpioTerminate();
        return 1;
    }
    if (ftell(file) == 0) {
        fprintf(file, "timestamp,flow_rate (L/min)\n");
    }

