#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <msmtp/msmtp.h>

#define LOG_FILE "plant_data.txt"
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION 300
#define DEFAULT_MAX_CALIBRATION 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_FREQUENCY 60

void sigint_handler(int sig) {
    gpioTerminate();
    free(msmtp_config);
    free(msmtp_server);
    free(msmtp_username);
    free(msmtp_password);
    exit(0);
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calibration = DEFAULT_MIN_CALIBRATION;
    int max_calibration = DEFAULT_MAX_CALIBRATION;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_frequency = DEFAULT_LOGGING_FREQUENCY;
    char *recipient_email = NULL;
    char *msmtp_config_file = NULL;

    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            if (strcmp(argv[i], "--spi-channel") == 0) {
                if (i + 1 < argc) {
                    spi_channel = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --spi-channel requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--adc-channel") == 0) {
                if (i + 1 < argc) {
                    adc_channel = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --adc-channel requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--min-calibration") == 0) {
                if (i + 1 < argc) {
                    min_calibration = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --min-calibration requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--max-calibration") == 0) {
                if (i + 1 < argc) {
                    max_calibration = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --max-calibration requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--moisture-threshold") == 0) {
                if (i + 1 < argc) {
                    moisture_threshold = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --moisture-threshold requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--logging-frequency") == 0) {
                if (i + 1 < argc) {
                    logging_frequency = atoi(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --logging-frequency requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--recipient-email") == 0) {
                if (i + 1 < argc) {
                    recipient_email = strdup(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --recipient-email requires an argument\n");
                    return 1;
                }
            } else if (strcmp(argv[i], "--msmtp-config") == 0) {
                if (i + 1 < argc) {
                    msmtp_config_file = strdup(argv[++i]);
                } else {
                    fprintf(stderr, "Error: --msmtp-config requires an argument\n");
                    return 1;
                }
            }
        }
    }

    if (!recipient_email || !msmtp_config_file) {
        fprintf(stderr, "Error: missing required arguments\n");
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: failed to initialize GPIO\n");
        return 1;
    }

    // Initialize SPI
    if (gpioSetMode(spi_channel, PI_SPI_MODE_0) < 0) {
        fprintf(stderr, "Error: failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockSpeed(spi_channel, 500000) < 0) {
        fprintf(stderr, "Error: failed to set SPI clock speed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockPolarity(spi_channel, PI_SPI_CLOCK_EDGE_RISING) < 0) {
        fprintf(stderr, "Error: failed to set SPI clock polarity\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetDataMode(spi_channel, PI_SPI_MODE_0) < 0) {
        fprintf(stderr, "Error: failed to set SPI data mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize msmtp
    FILE *msmtp_config = fopen(msmtp_config_file, "r");
    if (!msmtp_config) {
        fprintf(stderr, "Error: failed to open msmtp config file\n");
        gpioTerminate();
        return 1;
    }
    char *server = NULL;
    char *username = NULL;
    char *password = NULL;
    char line[1024];
    while (fgets(line, sizeof(line), msmtp_config)) {
        line[strcspn(line, "\n")] = 0;
        if (strncmp(line, "account default", 13) == 0) {
            server = strdup(line + 13);
        } else if (strncmp(line, "auth username", 12) == 0) {
            username = strdup(line + 12);
        } else if (strncmp(line, "auth password", 12) == 0) {
            password = strdup(line + 12);
        }
    }
    fclose(msmtp_config);
    if (!server || !username || !password) {
        fprintf(stderr, "Error: failed to parse msmtp config\n");
        gpioTerminate();
        return 1;
    }

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = 0;
        for (int i = 0; i < 10; i++) {
            int value = gpioReadADC(spi_channel, adc_channel);
            if (value < 0) {
                fprintf(stderr, "Error: failed to read ADC value\n");
                continue;
            }
            adc_value += value;
        }
        adc_value /= 10;

        // Calculate moisture percentage
        int moisture_percentage = (adc_value - min_calibration) * 100 / (max_calibration - min_calibration);

        // Log data
        time_t now = time(NULL);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        FILE *log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Error: failed to open log file\n");
            continue;
        }
        fprintf(log_file, "%s, %d\n", timestamp, moisture_percentage);
        fclose(log_file);

        // Check for low moisture
        if (moisture_percentage < moisture_threshold) {
            // Send email
            FILE *email = popen("echo 'Moisture level is low!' | msmtp -C " MSMTPT_CONFIG_FILE " -a " MSMTPT_CONFIG_FILE " " recipient_email, "w");
            if (!email) {
                fprintf(stderr, "Error: failed to send email\n");
                continue;
            }
            int status = pclose(email);
            if (status != 0) {
                fprintf(stderr, "Error: failed to send email (status %d)\n", status);
            }
        }

        // Sleep
        sleep(logging_frequency);
    }

    return 0;
}

