    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO for SPI\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI
    spi_fd = gpio_spi_open(gpio_fd, 0, 0, 0, 0, 0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpio_close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    fd = fopen(LOG_FILE, "a");
    if (fd == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_spi_close(spi_fd);
        gpio_close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler\n");
        fclose(fd);
        gpio_spi_close(spi_fd);
        gpio_close(gpio_fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Read from ADC
        uint8_t buf[3];
        if (gpio_spi_transfer(spi_fd, 0, buf, 3, 0, 0, 0) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            continue;
        }

        // Calculate moisture percentage
        int moisture = (buf[1] & 0x3f) << 8 | buf[2];
        moisture = (moisture * 100) / 1023;
        moisture = (moisture < 0) ? 0 : (moisture > 100) ? 100 : moisture;

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
        fprintf(fd, "%s %d %d\n", timestamp, moisture, moisture);
        fflush(fd);

        // Sleep
        usleep(sample_rate * 1e6);
    }

    return 0;
}

