#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>

#define ADC_CHANNEL 0
#define CALIBRATION_DRY 700
#define CALIBRATION_WET 300
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_LSB_FIRST 0
#define SPI_CS_HIGH 0

void cleanup(int sig) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    gpiod_close(gpio_fd);
    exit(0);
}

int main() {
    int spi_fd, gpio_fd;
    struct spi_ioc_transfer transfer;
    uint8_t buffer[3];
    uint16_t adc_value;
    float moisture_percentage;

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set up SPI parameters
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)buffer,
        .rx_buf = (unsigned long)buffer,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 1,
        .cs_high_pre_transfer = 1,
        .cs_low_pre_transfer = 1,
        .delay_usecs_post_transfer = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
        .mode = SPI_MODE,
        .lp_mode = SPI_LSB_FIRST,
        .nbits = SPI_LSB_FIRST,
        .cs_change = SPI_CS_HIGH
    };

    // Open GPIO device
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO device");
        close(spi_fd);
        return 1;
    }

    // Set up GPIO pin for chip select
    struct gpiod_line_request line_request = {
        .line = 8,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH,
        .consumer = "spi_cs"
    };
    if (gpiod_line_request(gpio_fd, &line_request) < 0) {
        perror("Failed to request GPIO line");
        gpiod_close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Initialize GPIO line
    if (gpiod_line_export(gpio_fd, 8, 0) < 0) {
        perror("Failed to export GPIO line");
        gpiod_line_release(gpio_fd, 8);
        gpiod_close(gpio_fd);
        close(spi_fd);
        return 1;
    }

    // Set up signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    while (1) {
        // Set chip select low
        if (gpiod_line_set_value(gpio_fd, 8, 0) < 0) {
            perror("Failed to set GPIO line low");
            break;
        }

        // Send conversion command to ADC
        transfer.tx_buf = (unsigned long)buffer;
        transfer.rx_buf = (unsigned long)buffer;
        transfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("Failed to send SPI message");
            break;
        }

        // Read ADC value
        adc_value = (buffer[1] << 8) | buffer[2];

        // Calculate moisture percentage
        moisture_percentage = (adc_value - CALIBRATION_DRY) / (CALIBRATION_WET - CALIBRATION_DRY) * 100;
        moisture_percentage = (moisture_percentage < 0) ? 0 : (moisture_percentage > 100) ? 100 : moisture_percentage;

        // Print ADC value and moisture percentage
        printf("ADC value: %d, Moisture percentage: %.2f%%\n", adc_value, moisture_percentage);

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up
    gpiod_line_release(gpio_fd, 8);
    gpiod_close(gpio_fd);
    close(spi_fd);
    return 0;
}

