#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define ADC_CHANNEL 0
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define ADC_VCC 3.3
#define ADC_VCC_MIN 0.5
#define ADC_VCC_MAX 4.5
#define PRESSURE_MIN 10  // kPa
#define PRESSURE_MAX 150  // kPa
#define PRESSURE_MIN_VOLTAGE 0.5  // V
#define PRESSURE_MAX_VOLTAGE 4.5  // V
#define PRESSURE_SPAN (PRESSURE_MAX - PRESSURE_MIN)
#define VOLTAGE_SPAN (ADC_VCC_MAX - ADC_VCC_MIN)

// Define the pressure conversion function
double pressure_to_kPa(double voltage) {
    return (voltage - PRESSURE_MIN_VOLTAGE) / VOLTAGE_SPAN * PRESSURE_SPAN + PRESSURE_MIN;
}

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Release resources
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the SPI bus
    if (gpioSetMode(8, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(9, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MISO mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(10, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI bus configuration
    if (gpioSetPullUpDnControl(8, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set CE0 pull-up/down\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(9, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set MISO pull-up/down\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the SPI bus
    if (gpioSetClock(11, 1000000) < 0) {
        fprintf(stderr, "Failed to set SCLK frequency\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetDataMode(10, PI_MODE_CPHA | PI_MODE_CPOL) < 0) {
        fprintf(stderr, "Failed to set MOSI mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the ADC
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        uint16_t adc_value;
        if (ioctl(adc_fd, SPI_IOC_READ, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            close(adc_fd);
            gpioTerminate();
            return 1;
        }

        // Validate the ADC value
        if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert the ADC value to voltage
        double voltage = (double)adc_value / ADC_MAX_VALUE * ADC_VCC;

        // Check for sensor-absent conditions
        if (voltage == ADC_VCC_MIN || voltage == ADC_VCC_MAX) {
            fprintf(stderr, "Sensor-absent condition detected\n");
            continue;
        }

        // Convert the voltage to pressure
        double pressure = pressure_to_kPa(voltage);

        // Log the reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(stdout, "%s: %f kPa\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    close(adc_fd);
    gpioTerminate();

    return 0;
}

