        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(10, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(11, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up the SPI bus configuration
    if (gpioSetPullUpDnControl(8, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set CE0 pull-up/down\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(9, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set MISO pull-up/down\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the SPI bus
    if (gpioSetClock(11, 1000000) < 0) {
        fprintf(stderr, "Failed to set SCLK frequency\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetDataMode(10, PI_MODE_CPHA | PI_MODE_CPOL) < 0) {
        fprintf(stderr, "Failed to set MOSI mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the ADC
    int adc_fd = open("/dev/spidev0.0", O_RDWR);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        uint16_t adc_value;
        if (ioctl(adc_fd, SPI_IOC_READ, &adc_value) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            close(adc_fd);
            gpioTerminate();
            return 1;
        }

        // Validate the ADC value
        if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert the ADC value to voltage
        double voltage = (double)adc_value / ADC_MAX_VALUE * ADC_VCC;

        // Check for sensor-absent conditions
        if (voltage == ADC_VCC_MIN || voltage == ADC_VCC_MAX) {
            fprintf(stderr, "Sensor-absent condition detected\n");
            continue;
        }

        // Convert the voltage to pressure
        double pressure = pressure_to_kPa(voltage);

        // Log the reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(stdout, "%s: %f kPa\n", timestamp, pressure);

        // Sleep for 1 second
        sleep(1);
    }

    // Release resources
    close(adc_fd);
    gpioTerminate();

    return 0;
}
