#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int spi_fd;
    uint8_t buf[3];
    uint16_t result;
    int ret;

    // Set up signal handler for clean exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open SPI device
    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    // Configure SPI
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (long)buf;
    xfer.rx_buf = (long)buf;
    xfer.len = 3;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS_PER_WORD;
    xfer.cs_change = 1;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Prepare MCP3008 single-ended read command for channel 0
        buf[0] = 0x01;  // Start bit
        buf[1] = 0x00;  // Config byte (single-ended, channel 0)
        buf[2] = 0x00;  // Don't-care byte

        // Perform SPI transfer
        xfer.tx_buf = (long)buf;
        xfer.rx_buf = (long)buf;
        xfer.len = 3;
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) < 0) {
            perror("Failed to perform SPI transfer");
            close(spi_fd);
            exit(EXIT_FAILURE);
        }

        // Extract 10-bit result from received data
        result = (buf[1] & 0x03) << 8 | buf[2];

        // Clamp result to 0-100 range
        result = (result > 1023) ? 1023 : result;
        result = (result < 0) ? 0 : result;

        // Calculate moisture percentage
        double moisture_percentage = (double)result / 1023 * 100;

        // Print moisture percentage to console
        printf("Moisture percentage: %.2f%%\n", moisture_percentage);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close SPI device
    close(spi_fd);

    return 0;
}

