#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEV "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_CS_PIN 8
#define CSV_FILE "environmental_data.csv"

int main() {
    int spi_fd, gpiod_fd;
    struct spi_ioc_transfer xfer;
    struct gpiod_line *cs_line;
    struct gpiod_line *cs_line2;
    struct gpiod_line *cs_line3;
    struct gpiod_line *cs_line4;
    char filename[256];
    char buffer[4];
    int i;
    int ret;
    struct tm *timeinfo;
    time_t rawtime;

    // Open the SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set up the SPI device
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Open the GPIO device
    gpiod_fd = gpiod_open("/dev/gpiochip0");
    if (gpiod_fd < 0) {
        perror("Failed to open GPIO device");
        close(spi_fd);
        return 1;
    }

    // Get the CS line
    cs_line = gpiod_line_request_output(gpiod_fd, SPI_CS_PIN, "cs");
    if (!cs_line) {
        perror("Failed to request CS line");
        gpiod_close(gpiod_fd);
        close(spi_fd);
        return 1;
    }

    // Get the CS lines for the other channels
    cs_line2 = gpiod_line_request_output(gpiod_fd, SPI_CS_PIN + 1, "cs2");
    if (!cs_line2) {
        perror("Failed to request CS line 2");
        gpiod_close(gpiod_fd);
        gpiod_line_release(cs_line);
        close(spi_fd);
        return 1;
    }

    cs_line3 = gpiod_line_request_output(gpiod_fd, SPI_CS_PIN + 2, "cs3");
    if (!cs_line3) {
        perror("Failed to request CS line 3");
        gpiod_close(gpiod_fd);
        gpiod_line_release(cs_line);
        gpiod_line_release(cs_line2);
        close(spi_fd);
        return 1;
    }

    cs_line4 = gpiod_line_request_output(gpiod_fd, SPI_CS_PIN + 3, "cs4");
    if (!cs_line4) {
        perror("Failed to request CS line 4");
        gpiod_close(gpiod_fd);
        gpiod_line_release(cs_line);
        gpiod_line_release(cs_line2);
        gpiod_line_release(cs_line3);
        close(spi_fd);
        return 1;
    }

    // Initialize the CS lines
    gpiod_line_set_value(cs_line, 1);
    gpiod_line_set_value(cs_line2, 1);
    gpiod_line_set_value(cs_line3, 1);
    gpiod_line_set_value(cs_line4, 1);

    // Open the CSV file
    sprintf(filename, "%s", CSV_FILE);
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        perror("Failed to open CSV file");
        gpiod_close(gpiod_fd);
        gpiod_line_release(cs_line);
        gpiod_line_release(cs_line2);
        gpiod_line_release(cs_line3);
        gpiod_line_release(cs_line4);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

        // Read the SPI data
        for (i = 0; i < 4; i++) {
            // Select the CS line
            gpiod_line_set_value(cs_line + i, 0);

            // Set up the SPI transfer
            memset(&xfer, 0, sizeof(xfer));
            xfer.tx_buf = (unsigned long)buffer;
            xfer.rx_buf = (unsigned long)buffer;
            xfer.len = 2;
            xfer.speed_hz = SPI_SPEED;
            xfer.bits_per_word = SPI_BITS_PER_WORD;
            xfer.cs_change = 1;

            // Perform the SPI transfer
            ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
            if (ret < 0) {
                perror("Failed to perform SPI transfer");
                gpiod_close(gpiod_fd);
                gpiod_line_release(cs_line);
                gpiod_line_release(cs_line2);
                gpiod_line_release(cs_line3);
                gpiod_line_release(cs_line4);
                close(spi_fd);
                fclose(fp);
                return 1;
            }

            // Get the voltage value
            int voltage = (buffer[0] << 8) | buffer[1];

            // Write the voltage value to the CSV file
            fprintf(fp, "%d,", voltage);
        }

        // Write a newline to the CSV file
        fprintf(fp, "\n");

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(cs_line);
    gpiod_line_release(cs_line2);
    gpiod_line_release(cs_line3);
    gpiod_line_release(cs_line4);
    gpiod_close(gpiod_fd);
    close(spi_fd);
    fclose(fp);

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    gpiod_line_release(cs_line);
    gpiod_line_release(cs_line2);
    gpiod_line_release(cs_line3);
    gpiod_line_release(cs_line4);
    gpiod_close(gpiod_fd);
    close(spi_fd);
    fclose(fp);
    exit(0);
}

// Register the signal handler
void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    setup_signals();
    // ... (rest of the code remains the same)
}

