            fprintf(fp, "%d,", voltage);
        }

        // Write a newline to the CSV file
        fprintf(fp, "\n");

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpiod_line_release(cs_line);
    gpiod_line_release(cs_line2);
    gpiod_line_release(cs_line3);
    gpiod_line_release(cs_line4);
    gpiod_close(gpiod_fd);
    close(spi_fd);
    fclose(fp);

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    gpiod_line_release(cs_line);
    gpiod_line_release(cs_line2);
    gpiod_line_release(cs_line3);
    gpiod_line_release(cs_line4);
    gpiod_close(gpiod_fd);
    close(spi_fd);
    fclose(fp);
    exit(0);
}

// Register the signal handler
void setup_signals() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
}

