    if (spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI bus %d\n", SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up the SPI pins
    if (gpioSetMode(MOSI_PIN, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", MOSI_PIN);
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MISO_PIN, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", MISO_PIN);
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SCLK_PIN, PI_ALT0) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", SCLK_PIN);
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin %d\n", CE_PIN);
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }

