    timer_id = gpioTimerCreate();
    if (timer_id < 0) {
        fprintf(stderr, "Failed to create timer\n");
        spiClose(SPI_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        uint16_t adc_value;
        if (spiXfer(SPI_BUS, 0x00, 0x00, 3, &adc_value, 3) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            spiClose(SPI_BUS);
            gpioTerminate();
            return 1;
        }

        // Convert the ADC value to a 10-bit moisture level
        uint16_t moisture = (adc_value >> 4) & 0x03FF;

        // Check if the pump should be turned on or off
        if (moisture < LOW_THRESHOLD && !pump_state) {
            pump_state = true;
            gpioWrite(PUMP_PIN, 1);
        } else if (moisture > HIGH_THRESHOLD && pump_state) {
            pump_state = false;
            gpioWrite(PUMP_PIN, 0);
        }

        // Log the reading
        log_buffer[log_index].timestamp = time(NULL);
        log_buffer[log_index].moisture = moisture;
        log_buffer[log_index].pump_state = pump_state;
        log_index = (log_index + 1) % LOG_SIZE;

        // Print the log buffer
        for (int i = 0; i < LOG_SIZE; i++) {
            log_entry_t *entry = &log_buffer[i];
            if (entry->timestamp != 0) {
                printf("%lu %d %s\n", entry->timestamp, entry->moisture, entry->pump_state ? "on" : "off");
            }
        }

        // Wait for the next sample
        gpioTimerAddMilli(timer_id, 5000, NULL);
    }

    return 0;
}

