#include <signal.h>
#include <pigpio.h>

#define MAX30102_I2C_ADDRESS 0x57
#define MAX30102_PART_ID 0x15
#define MAX30102_MODE_CONFIG 0x06
#define MAX30102_SPO2_CONFIG 0x08
#define MAX30102_LED1_PA 0x09
#define MAX30102_LED2_PA 0x0A
#define MAX30102_FIFO_DATA 0x07
#define MAX30102_SPO2_DATA_SIZE 6

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(i2c_fd));
        return 1;
    }

    int i2c_bus = 1;
    int i2c_address = MAX30102_I2C_ADDRESS;

    // Verify sensor presence
    uint8_t part_id;
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, 0xFF) < 0) {
        fprintf(stderr, "Failed to write to MAX30102: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (i2cReadReg8(i2c_fd, i2c_bus, i2c_address, 0xFF, &part_id) < 0) {
        fprintf(stderr, "Failed to read from MAX30102: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (part_id != MAX30102_PART_ID) {
        fprintf(stderr, "MAX30102 not found or incorrect address\n");
        goto cleanup;
    }

    // Initialize sensor
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Failed to reset MAX30102: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_MODE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Failed to configure MAX30102 for SpO2 mode: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_SPO2_CONFIG, 0x27) < 0) {
        fprintf(stderr, "Failed to configure MAX30102 for SpO2: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_LED1_PA, 0x24) < 0) {
        fprintf(stderr, "Failed to set LED1 PA: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }
    if (i2cWriteReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_LED2_PA, 0x24) < 0) {
        fprintf(stderr, "Failed to set LED2 PA: %s\n", gpioErrorStr(i2c_fd));
        goto cleanup;
    }

    FILE *log_file = fopen("health_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        uint8_t data[MAX30102_SPO2_DATA_SIZE];
        if (i2cReadReg8(i2c_fd, i2c_bus, i2c_address, MAX30102_FIFO_DATA, data, MAX30102_SPO2_DATA_SIZE) < 0) {
            fprintf(stderr, "Failed to read from MAX30102: %s\n", gpioErrorStr(i2c_fd));
            goto cleanup;
        }

        // Compute SpO2 using ratio-of-ratios method
        int32_t red = (data[0] << 8) | data[1];
        int32_t ir = (data[2] << 8) | data[3];
        int32_t spo2 = (red * 100) / (red + ir);

        // Compute heart rate via peak detection on IR signal
        int32_t ir_peaks = 0;
        for (int i = 0; i < MAX30102_SPO2_DATA_SIZE; i += 3) {
            if (ir > (data[i + 2] << 8) | data[i + 3]) {
                ir_peaks++;
            }
        }
        int32_t hr = (ir_peaks * 60) / 3;

        if (spo2 < 95) {
            fprintf(log_file, "%s SpO2: %d%%, HR: %d BPM\n", ctime(&time(NULL)), spo2, hr);
        }

        usleep(1000000); // 1 second
    }

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        gpioTerminate();
    }
    return 0;
}

