#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MCP3008_CHANNEL_COUNT 3
#define MCP3008_SPI_BUS 0
#define MCP3008_SPI_CE 0
#define MCP3008_SPI_SPEED 1000000
#define MCP3008_SPI_MODE 0
#define MCP3008_VREF 3.3

#define CSV_FILE "analog_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI handle
    int spi = gpioOpen(MCP3008_SPI_BUS, MCP3008_SPI_CE);
    if (spi < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and speed
    if (gpioSetMode(spi, MCP3008_SPI_MODE) < 0 || gpioSetSpeed(spi, MCP3008_SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI mode and speed\n");
        gpioClose(spi);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioClose(spi);
        gpioTerminate();
        return 1;
    }

    // Write header row to CSV file
    fprintf(csv_file, "Timestamp,Channel,Voltage\n");

    // Initialize timestamp
    time_t timestamp = time(NULL);

    // Main loop
    while (1) {
        // Read from each channel
        for (int channel = 0; channel < MCP3008_CHANNEL_COUNT; channel++) {
            // Assemble command byte
            uint8_t command = (1 << 7) | (channel << 4);

            // Send command and receive data
            uint8_t tx_buf[3] = {command, 0, 0};
            uint8_t rx_buf[3];
            int ret = gpioSPISendReceive(spi, tx_buf, rx_buf, 3, 0);
            if (ret < 0) {
                fprintf(stderr, "SPI communication error: %d\n", ret);
                continue;
            }

            // Extract 10-bit result
            uint16_t result = (rx_buf[1] & 0x03) << 8 | rx_buf[2];

            // Calculate voltage
            float voltage = (float)result / (1 << 10) * MCP3008_VREF;

            // Log reading to CSV file
            fprintf(csv_file, "%04d-%02d-%02dT%02d:%02d:%02dZ,%d,%f\n",
                    (int)(timestamp / 86400) % 100, (int)(timestamp / 3600) % 24, (int)(timestamp / 60) % 60,
                    (int)(timestamp % 60), channel, voltage);

            // Update timestamp
            timestamp++;
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close SPI handle
    gpioClose(spi);

    // Close CSV file
    fclose(csv_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

