#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x48
#define RELAY_PIN 17
#define REED_PIN 27
#define ADC_PIN 0
#define SAMPLES 10
#define SAMPLE_INTERVAL 50
#define POLL_INTERVAL 200
#define RELAY_DURATION 3000
#define LOG_FILE "/var/log/door_events.log"

int i2c_fd;
struct gpiod_line *relay_line, *reed_line;
uint16_t baseline_sum = 0;
uint16_t baseline_count = 0;
uint16_t threshold = 0;

void log_event(const char *event) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d.%03d %s\n",
            timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday,
            timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec,
            timestamp->tm_usec / 1000, event);
    fclose(log_file);
}

void init_i2c(void) {
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }
}

void init_gpios(void) {
    relay_line = gpiod_line_request_by_name(NULL, "gpio17", GPIOD_LINE_ACTIVE_HIGH);
    if (relay_line == NULL) {
        perror("gpiod_line_request_by_name");
        exit(1);
    }
    reed_line = gpiod_line_request_by_name(NULL, "gpio27", GPIOD_LINE_ACTIVE_LOW);
    if (reed_line == NULL) {
        perror("gpiod_line_request_by_name");
        exit(1);
    }
}

void deinit_gpios(void) {
    gpiod_line_release(reed_line);
    gpiod_line_release(relay_line);
}

void deinit_i2c(void) {
    close(i2c_fd);
}

void read_adc(void) {
    uint16_t value;
    if (i2c_smbus_write_byte(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_write_byte");
        return;
    }
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_read_byte_data");
        return;
    }
    if (i2c_smbus_write_byte(i2c_fd, 0x01) < 0) {
        perror("i2c_smbus_write_byte");
        return;
    }
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_read_byte_data");
        return;
    }
    if (i2c_smbus_write_byte(i2c_fd, 0x04) < 0) {
        perror("i2c_smbus_write_byte");
        return;
    }
    if (i2c_smbus_read_byte_data(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_read_byte_data");
        return;
    }
    if (i2c_smbus_write_byte(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_write_byte");
        return;
    }
    if (i2c_smbus_read_word_data(i2c_fd, 0x00) < 0) {
        perror("i2c_smbus_read_word_data");
        return;
    }
    value = (uint16_t) i2c_smbus_read_word_data(i2c_fd, 0x00);
    return value;
}

void calibrate(void) {
    uint16_t value;
    for (int i = 0; i < SAMPLES; i++) {
        usleep(SAMPLE_INTERVAL * 1000);
        value = read_adc();
        baseline_sum += value;
        baseline_count++;
    }
    threshold = (uint16_t) (baseline_sum / baseline_count * 0.8);
}

int main(void) {
    init_i2c();
    init_gpios();
    calibrate();
    while (1) {
        uint16_t value = read_adc();
        if (value < threshold) {
            log_event("door opened");
            gpiod_line_set_value(relay_line, 1);
            usleep(RELAY_DURATION * 1000);
            gpiod_line_set_value(relay_line, 0);
            if (gpiod_line_get_value(reed_line) == 0) {
                log_event("door not opened");
            } else {
                log_event("door opened");
            }
        }
        usleep(POLL_INTERVAL * 1000);
    }
    deinit_gpios();
    deinit_i2c();
    return 0;
}

void sigint_handler(int sig) {
    gpiod_line_set_value(relay_line, 0);
    deinit_gpios();
    deinit_i2c();
    exit(0);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    return main();
}

