#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

#define MAX_LOG_LINE 256

// Function to map ADC value to moisture percentage
float map_adc_to_moisture(int adc_value) {
    float dry = 200;
    float wet = 800;
    float min_adc = 0;
    float max_adc = 1023;
    float min_moisture = 0;
    float max_moisture = 100;

    return (adc_value - dry) * (max_moisture - min_moisture) / (wet - dry) + min_moisture;
}

// Function to log a message to the file
void log_message(const char *format, ...) {
    char log_line[MAX_LOG_LINE];
    va_list args;
    va_start(args, format);
    vsnprintf(log_line, MAX_LOG_LINE, format, args);
    va_end(args);
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", log_line);
        fclose(log_file);
    }
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    log_message("Received signal %d, shutting down...", signal);
    gpio_write(18, 0); // Turn off the pump
    spi_close(0);
    pigpio_stop();
    exit(0);
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    // Parse command-line options
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        log_message("Failed to initialize pigpio: %s", pigpio_error());
        return 1;
    }

    // Set up GPIO 18 as an output
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize GPIO: %s", gpioError());
        pigpio_stop();
        return 1;
    }
    if (gpioSetMode(18, PI_OUTPUT) < 0) {
        log_message("Failed to set GPIO 18 as output: %s", gpioError());
        gpioTerminate();
        pigpio_stop();
        return 1;
    }

    // Set up SPI0
    if (spiOpen(0, 1000000, 0) < 0) {
        log_message("Failed to open SPI0: %s", pigpio_error());
        gpioTerminate();
        pigpio_stop();
        return 1;
    }
    if (spiSetMode(0, SPI_MODE_0) < 0) {
        log_message("Failed to set SPI mode: %s", pigpio_error());
        spiClose(0);
        gpioTerminate();
        pigpio_stop();
        return 1;
    }
    if (spiSetClock(0, 1000000) < 0) {
        log_message("Failed to set SPI clock: %s", pigpio_error());
        spiClose(0);
        gpioTerminate();
        pigpio_stop();
        return 1;
    }
    if (spiSetBitOrder(0, SPI_LSB_FIRST) < 0) {
        log_message("Failed to set SPI bit order: %s", pigpio_error());
        spiClose(0);
        gpioTerminate();
        pigpio_stop();
        return 1;
    }
    if (spiSetDataMode(0, SPI_MODE_0) < 0) {
        log_message("Failed to set SPI data mode: %s", pigpio_error());
        spiClose(0);
        gpioTerminate();
        pigpio_stop();
        return 1;
    }

    // Set up CE0 as an output
    if (gpioSetMode(8, PI_OUTPUT) < 0) {
        log_message("Failed to set CE0 as output: %s", gpioError());
        spiClose(0);
        gpioTerminate();
        pigpio_stop();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC value
        int retries = 0;
        int adc_value;
        while (retries < 3) {
            if (spiXfer(0, 0x00, 1, &adc_value, 1) >= 0) {
                break;
            }
            retries++;
            log_message("Failed to read ADC value (retry %d/%d)", retries + 1, 3);
            usleep(100000);
        }
        if (retries == 3) {
            log_message("Failed to read ADC value after 3 retries");
            continue;
        }

        // Map the ADC value to moisture percentage
        float moisture = map_adc_to_moisture(adc_value);

        // Log the moisture reading
        log_message("Moisture: %.2f%%", moisture);

        // Check if the moisture is below the threshold
        if (moisture < threshold) {
            // Activate the pump
            gpioWrite(18, 1);
            log_message("Pump activated");

            // Wait for the duration
            usleep(duration * 1000000);

            // Deactivate the pump
            gpioWrite(18, 0);
            log_message("Pump deactivated");
        }

        // Wait for the sleep interval
        usleep(sleep_interval * 1000000);
    }

    // Clean up
    gpioTerminate();
    pigpio_stop();
    return 0;
}

