#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_CLK_PIN 11
#define ADC_MOSI_PIN 10
#define ADC_MISO_PIN 9
#define ADC_SAMPLE_RATE 10  // ms
#define EMA_ALPHA 0.1
#define PEAK_THRESHOLD 0.2

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_peak(double value) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
    FILE *log_file = fopen("/var/log/sound_events.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s %f\n", timestamp, value);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(ADC_CS_PIN, PI_OUTPUT);
    gpioWrite(ADC_CS_PIN, 1);

    int spi_fd = spiOpen(0, 1000000, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    spiSetMode(spi_fd, SPI_MODE_0);
    spiSetBitOrder(spi_fd, SPI_LSB_FIRST);
    spiSetDataMode(spi_fd, SPI_MODE_8BIT);

    double ema = 0.0;
    double last_value = 0.0;

    while (running) {
        if (gpioRead(ADC_CS_PIN) == 0) {
            uint8_t data = 0;
            if (spiXfer(spi_fd, &data, 1, 1000) != 1) {
                fprintf(stderr, "SPI transfer failed\n");
                break;
            }
            double value = (double)data / 1024.0;
            ema = EMA_ALPHA * value + (1 - EMA_ALPHA) * ema;
            if (value > ema * (1 + PEAK_THRESHOLD)) {
                log_peak(value);
            }
            last_value = value;
        }
        usleep(ADC_SAMPLE_RATE * 1000);
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

