#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define AIN0_CHANNEL 0
#define DUMMY_READ 0x00
#define CONTROL_BYTE 0x80

int main() {
    int i2c_fd;
    int ret;
    uint8_t control_byte;
    uint8_t sample;

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C address
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Configure the control byte for single-ended mode on channel 0
    control_byte = DUMMY_READ | (AIN0_CHANNEL << 4) | CONTROL_BYTE;
    ret = i2c_smbus_write_byte(i2c_fd, control_byte);
    if (ret < 0) {
        perror("Failed to write control byte");
        close(i2c_fd);
        return 1;
    }

    // Perform a dummy read to discard the previous conversion result
    ret = i2c_smbus_read_byte(i2c_fd);
    if (ret < 0) {
        perror("Failed to read dummy byte");
        close(i2c_fd);
        return 1;
    }

    // Open the GPIO chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Export the GPIO pin
    struct gpiod_line *line;
    line = gpiod_line_request_by_name(chip, "AIN0", GPIOD_LINE_ACTIVE_LOW);
    if (!line) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Set the direction of the GPIO pin to input
    ret = gpiod_line_set_direction(line, GPIOD_LINE_DIRECTION_INPUT);
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the control byte to trigger a new conversion
        ret = i2c_smbus_write_byte(i2c_fd, DUMMY_READ | (AIN0_CHANNEL << 4));
        if (ret < 0) {
            perror("Failed to read control byte");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            return 1;
        }

        // Read the current sample
        ret = i2c_smbus_read_byte(i2c_fd);
        if (ret < 0) {
            perror("Failed to read sample");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            close(i2c_fd);
            return 1;
        }

        // Print the sample value
        printf("%d\n", ret);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the I2C file descriptor
    close(i2c_fd);
    // Exit with a non-zero code
    exit(1);
}

// Register the signal handler
static void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        exit(1);
    }
}

