#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL AIN0
#define ADC_GAIN 1
#define ADC_RATE 128
#define ADC_THRESHOLD 500
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define VCC 3.3
#define ZERO_FIELD 2.5
#define SENSITIVITY 1.4e-3

// Circular buffer for storing readings
typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
} Buffer;

void buffer_init(Buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
}

void buffer_push(Buffer *buf, float value) {
    buf->data[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

float buffer_average(Buffer *buf) {
    float sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buf->data[(buf->tail + i) % BUFFER_SIZE];
    }
    return sum / BUFFER_SIZE;
}

int main() {
    // Initialize syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    // Set up GPIO27 as an output
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO27");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize I2C handle
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        gpioSetMode(GPIO_PIN, PI_OUTPUT);
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(fd, I2C_SLAVE, ADC_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        close(fd);
        gpioSetMode(GPIO_PIN, PI_OUTPUT);
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize ADC
    uint8_t config = 0x01; // Single-ended, 128 samples, 860 sps
    if (i2c_smbus_write_byte_data(fd, 0x01, config) < 0) {
        syslog(LOG_ERR, "Failed to configure ADC");
        close(fd);
        gpioSetMode(GPIO_PIN, PI_OUTPUT);
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize buffer
    Buffer buffer;
    buffer_init(&buffer);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t value;
        if (i2c_smbus_read_word_data(fd, ADC_CHANNEL, &value) < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (value * 5.0 / 32768.0) * VCC;

        // Check for invalid voltage
        if (voltage < 0 || voltage > VCC) {
            syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
            continue;
        }

        // Convert voltage to magnetic field strength
        float field = (voltage - ZERO_FIELD) / SENSITIVITY;

        // Store reading in buffer
        buffer_push(&buffer, field);

        // Check if threshold exceeded
        if (buffer_average(&buffer) > ADC_THRESHOLD) {
            syslog(LOG_INFO, "Threshold exceeded: %f Gauss", buffer_average(&buffer));
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        // Log reading
        syslog(LOG_INFO, "Reading: %f Gauss", field);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(fd);
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}

