        if (i2c_smbus_read_word_data(fd, ADC_CHANNEL, &value) < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            continue;
        }

        // Convert ADC value to voltage
        float voltage = (value * 5.0 / 32768.0) * VCC;

        // Check for invalid voltage
        if (voltage < 0 || voltage > VCC) {
            syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
            continue;
        }

        // Convert voltage to magnetic field strength
        float field = (voltage - ZERO_FIELD) / SENSITIVITY;

        // Store reading in buffer
        buffer_push(&buffer, field);

        // Check if threshold exceeded
        if (buffer_average(&buffer) > ADC_THRESHOLD) {
            syslog(LOG_INFO, "Threshold exceeded: %f Gauss", buffer_average(&buffer));
            gpioWrite(GPIO_PIN, 1);
        } else {
            gpioWrite(GPIO_PIN, 0);
        }

        // Log reading
        syslog(LOG_INFO, "Reading: %f Gauss", field);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    close(fd);
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();

    return 0;
}
```

This code uses the pigpio library to interact with the Raspberry Pi's GPIO and I2C interfaces. It initializes the ADC, reads the voltage from the SS49E sensor, converts it to a magnetic field strength, and stores the last 10 readings in a circular buffer. If the rolling average of the buffer exceeds the threshold, it drives GPIO27 HIGH to signal motor shutdown. The code also logs all readings, threshold events, and errors via syslog. It handles pigpio initialization failure, I2C/ADC read failures by skipping the sample and continuing, and invalid voltage readings outside 0-3.3 V. On SIGINT/SIGTERM, it stops the I2C handle, resets GPIO27 to LOW, terminates pigpio, and closes syslog.

