    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up the SPI handle
    int spi_fd = spiOpen(SPI0, 0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI handle: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up the SPI configuration
    spiSetMode(spi_fd, 0);
    spiSetClockSpeed(spi_fd, 1000000);
    spiSetBitOrder(spi_fd, SPI_LSB_FIRST);
    spiSetDataMode(spi_fd, SPI_MODE_0);

