#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Stop PWM
    gpioPWM(18, 0);
    // Release all pigpio resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Install SIGINT and SIGTERM handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    int spiHandle = gpioOpen(0, 0); // Open SPI0, CE0 on GPIO8
    if (spiHandle < 0) {
        fprintf(stderr, "Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and speed
    if (gpioSetMode(spiHandle, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockSpeed(spiHandle, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Set up PWM
    if (gpioPWM(18, 0) < 0) {
        fprintf(stderr, "Failed to set up PWM\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    if (gpioPWMSetClock(18, 1000) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }
    if (gpioPWMSetRange(18, 1023) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        unsigned char buffer[3];
        int result = gpioSPISendReceive(spiHandle, 0, 0, buffer, 3, 1000);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            gpioClose(spiHandle);
            gpioTerminate();
            return 1;
        }

        // Extract ADC value
        unsigned int adcValue = (buffer[1] << 8) | buffer[2];

        // Map ADC value to PWM duty cycle
        int dutyCycle = (adcValue * 1000) / 1023;

        // Print ADC and PWM values
        printf("ADC: %d, PWM: %d\n", adcValue, dutyCycle);

        // Update PWM
        gpioPWM(18, dutyCycle);

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

