#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define ADC_ADDRESS 0x48
#define ADC_CHANNEL AIN0
#define ADC_GAIN 4.096
#define DEFAULT_THRESHOLD 100.0
#define LED_PIN 17
#define SAMPLE_RATE 100

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main(int argc, char **argv) {
    int threshold = DEFAULT_THRESHOLD;
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, GPIO_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(1, ADC_ADDRESS, NULL) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    int fd = i2cOpen(1, ADC_ADDRESS, NULL);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        i2cClose(1, ADC_ADDRESS);
        gpioTerminate();
        return 1;
    }

    uint16_t raw_value;
    float magnetic_field;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        if (i2cWriteByte(fd, 0x01, 0x60) < 0) {
            fprintf(stderr, "Failed to write to ADC\n");
            i2cClose(1, ADC_ADDRESS);
            gpioTerminate();
            return 1;
        }

        if (i2cReadByte(fd, 0x00, &raw_value) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            i2cClose(1, ADC_ADDRESS);
            gpioTerminate();
            return 1;
        }

        magnetic_field = (raw_value * ADC_GAIN) / 32768.0;
        magnetic_field /= 1.0; // 1.0 mV/Gauss

        if (magnetic_field > threshold) {
            for (int i = 0; i < 20; i++) {
                gpioWrite(LED_PIN, 1);
                usleep(50 * 1000);
                gpioWrite(LED_PIN, 0);
                usleep(50 * 1000);
            }
        }

        printf("Magnetic field: %.2f Gauss\n", magnetic_field);
        usleep(SAMPLE_RATE * 1000);
    }

    i2cClose(1, ADC_ADDRESS);
    gpioTerminate();
    return 0;
}

