#define MQTT_PUMP_TOPIC "pump_control"
#define RELAY_PIN 17
#define ADC_CHANNEL 0
#define ADC_CLOCK 1000000
#define HUMIDITY_HYSTERESIS 5
#define READ_INTERVAL 60000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void pump_on() {
    if (gpioWrite(RELAY_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to turn pump on");
    }
}

void pump_off() {
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to turn pump off");
    }
}

void publish_moisture(int moisture) {
    char buffer[10];
    sprintf(buffer, "%d", moisture);
    if (mosquitto_publish(NULL, NULL, MQTT_TOPIC, strlen(buffer), buffer, 1, 0, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture reading");
    }
}

void on_connect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        exit(1);
    }
    if (mosquitto_subscribe(mosq, NULL, MQTT_PUMP_TOPIC, 1, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to pump control topic");
        exit(1);
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (strcmp(message->topic, MQTT_PUMP_TOPIC) == 0) {
        if (strcmp(message->data, "pump_on") == 0) {
            pump_on();
        } else if (strcmp(message->data, "pump_off") == 0) {
            pump_off();
        }
    }
}

int main() {
    int fd;
    int moisture;
    struct mosquitto *mosq;
    struct mosquitto_message message;
    struct sigaction sa;

    // Initialize syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }

    // Initialize SPI
    fd = spidev_open(0, 0);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        gpioTerminate();
        exit(1);
    }

    // Set up relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set relay pin as output");
        spidev_close(fd);
        gpioTerminate();
        exit(1);
    }

    // Set up ADC channel
    if (spidev_set_data_mode(fd, ADC_CHANNEL, SPI_MODE_0, ADC_CLOCK) != 0) {
        syslog(LOG_ERR, "Failed to set ADC channel");
        spidev_close(fd);
        gpioTerminate();
        exit(1);
    }

    // Initialize MQTT
    mosq = mosquitto_new(NULL);
    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60, NULL, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        spidev_close(fd);
        gpioTerminate();
        exit(1);
    }
    mosquitto_set_connect_callback(mosq, on_connect);
    mosquitto_set_message_callback(mosq, on_message);

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        mosquitto_disconnect(mosq);
        spidev_close(fd);
        gpioTerminate();
        exit(1);
    }

    // Main loop
    while (running) {
        // Read ADC value
        uint8_t buffer[2];
        if (spidev_transfer(fd, ADC_CHANNEL, buffer, 2) != 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
            mosquitto_disconnect(mosq);
            spidev_close(fd);
            gpioTerminate();
            exit(1);
        }
        moisture = (buffer[0] << 8) | buffer[1];

        // Check for sensor-absent condition
        if (moisture < 0 || moisture > 1023) {
            syslog(LOG_ERR, "Sensor-absent condition detected");
            mosquitto_disconnect(mosq);
            spidev_close(fd);
            gpioTerminate();
            exit(1);
        }

        // Publish moisture reading
        publish_moisture(moisture);

        // Check for pump control
        if (moisture < 30) {
            pump_on();
        } else if (moisture > 35) {
            pump_off();
        }

        // Sleep for 60 seconds
        usleep(READ_INTERVAL * 1000);
    }

    // Clean up
    pump_off();
    mosquitto_disconnect(mosq);
    spidev_close(fd);
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}
