#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>

#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500
#define PWM_FREQ 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100
#define PWM_DUTY_STEP 1
#define GPIO_MOTOR1 17
#define GPIO_MOTOR2 27
#define SPI_DEVICE "/dev/spidev0.0"
#define LOG_FILE "vibration_log.txt"

int spi_fd;
int gpio_fd;
int motor1_fd;
int motor2_fd;

void init_spi(void) {
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = 0;
    xfer.rx_buf = 0;
    xfer.len = 0;
    xfer.speed_hz = 1000000;
    xfer.bits_per_word = 8;
    xfer.cs_change = 1;

    if ((spi_fd = open(SPI_DEVICE, O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) < 0) {
        perror("Failed to set SPI mode");
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &xfer.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        exit(EXIT_FAILURE);
    }
}

void init_gpio(void) {
    if ((gpio_fd = gpioInitialise()) < 0) {
        perror("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_MOTOR1, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_MOTOR2, PI_OUTPUT) < 0) {
        perror("Failed to set GPIO mode");
        exit(EXIT_FAILURE);
    }

    if ((motor1_fd = gpioPWM(GPIO_MOTOR1, 0)) < 0) {
        perror("Failed to set PWM");
        exit(EXIT_FAILURE);
    }

    if ((motor2_fd = gpioPWM(GPIO_MOTOR2, 0)) < 0) {
        perror("Failed to set PWM");
        exit(EXIT_FAILURE);
    }
}

void cleanup(void) {
    if (gpio_fd >= 0) {
        gpioTerminate();
    }

    if (motor1_fd >= 0) {
        gpioPWM(GPIO_MOTOR1, 0);
    }

    if (motor2_fd >= 0) {
        gpioPWM(GPIO_MOTOR2, 0);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void log_event(uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s: ADC value: %d\n", timestamp, adc_value);
    fclose(file);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint16_t adc_value;

    init_spi();
    init_gpio();

    while (1) {
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = 0;
        xfer.rx_buf = 0;
        xfer.len = 1;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.cs_change = 1;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
            perror("Failed to read ADC value");
            continue;
        }

        adc_value = 0;
        if (read(spi_fd, &adc_value, 2) != 2) {
            perror("Failed to read ADC value");
            continue;
        }

        if (adc_value > ADC_THRESHOLD) {
            uint16_t duty_cycle = (adc_value - ADC_THRESHOLD) * (PWM_DUTY_MAX - PWM_DUTY_MIN) / (1023 - ADC_THRESHOLD) + PWM_DUTY_MIN;
            gpioPWM(GPIO_MOTOR1, duty_cycle);
            gpioPWM(GPIO_MOTOR2, duty_cycle);
            log_event(adc_value);
        } else {
            gpioPWM(GPIO_MOTOR1, 0);
            gpioPWM(GPIO_MOTOR2, 0);
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}

void sigint_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    return main();
}

