    if (gpio_fd >= 0) {
        gpioTerminate();
    }

    if (motor1_fd >= 0) {
        gpioPWM(GPIO_MOTOR1, 0);
    }

    if (motor2_fd >= 0) {
        gpioPWM(GPIO_MOTOR2, 0);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void log_event(uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s: ADC value: %d\n", timestamp, adc_value);
    fclose(file);
}

int main() {
    struct spi_ioc_transfer xfer;
    uint16_t adc_value;

    init_spi();
    init_gpio();

    while (1) {
        memset(&xfer, 0, sizeof(xfer));
        xfer.tx_buf = 0;
        xfer.rx_buf = 0;
        xfer.len = 1;
        xfer.speed_hz = 1000000;
        xfer.bits_per_word = 8;
        xfer.cs_change = 1;

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
            perror("Failed to read ADC value");
            continue;
        }

        adc_value = 0;
        if (read(spi_fd, &adc_value, 2) != 2) {
            perror("Failed to read ADC value");
            continue;
        }

        if (adc_value > ADC_THRESHOLD) {
            uint16_t duty_cycle = (adc_value - ADC_THRESHOLD) * (PWM_DUTY_MAX - PWM_DUTY_MIN) / (1023 - ADC_THRESHOLD) + PWM_DUTY_MIN;
            gpioPWM(GPIO_MOTOR1, duty_cycle);
            gpioPWM(GPIO_MOTOR2, duty_cycle);
            log_event(adc_value);
        } else {
            gpioPWM(GPIO_MOTOR1, 0);
            gpioPWM(GPIO_MOTOR2, 0);
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}

void sigint_handler(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    return main();
}
```

This code initializes the SPI device and sets up the GPIO pins for the motors. It then enters a loop where it reads the ADC value from the MCP3008, checks if it exceeds the threshold, and if so, sets the PWM duty cycle for the motors and logs the event. If the ADC value is below the threshold, it turns off the motors. The loop runs at 100 Hz, and the ADC is sampled every 10 ms. The program also handles SIGINT and SIGTERM signals by calling the `cleanup` function to stop the motors and close the SPI device before exiting.

