#define MAX_LINE_LENGTH 256

static int i2c_fd = -1;
static int spi_fd = -1;
static int gpiod_fd = -1;

static void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (gpiod_fd != -1) {
        gpiod_close(gpiod_fd);
        gpiod_fd = -1;
    }
    if (fclose(stdout) == EOF) {
