    char line[MAX_LINE_LENGTH];
    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);
    strftime(line, MAX_LINE_LENGTH, "%Y-%m-%d %H:%M:%S", current_time);
    fprintf(stdout, "%s,%f,%f,%d\n", line, sound_level_db, light_level_lux, error_code);
}

static int read_mcp3008(int spi_fd) {
    uint8_t data[2];
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long) data,
        .rx_buf = (unsigned long) data,
        .len = 2,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) == -1) {
        log_error(errno);
        return -1;
    }
    return (data[0] << 8) | data[1];
}

static int read_bh1750(int i2c_fd) {
    uint8_t data[2];
    struct i2c_msg msg = {
        .addr = BH1750_I2C_ADDRESS,
        .flags = 0,
        .len = 1,
        .buf = (unsigned char *) &BH1750_COMMAND_CONTINUOUS_HIGH_RESOLUTION_MODE
    };
    struct i2c_msg msg_read = {
        .addr = BH1750_I2C_ADDRESS,
        .flags = I2C_M_RD,
        .len = 2,
        .buf = (unsigned char *) data
    };
    if (i2c_transfer(i2c_fd, &msg, 1, &msg_read, 2) == -1) {
        log_error(errno);
        return -1;
    }
    usleep(180 * 1000);
    return (data[0] << 8) | data[1];
}

static void read_sensors() {
    int sound_level_db;
    int light_level_lux;
    if ((sound_level_db = read_mcp3008(spi_fd)) == -1) {
        log_data(0, 0, -1);
        return;
    }
    sound_level_db = (sound_level_db * 3.3 / 1024) * 20;
    if ((light_level_lux = read_bh1750(i2c_fd)) == -1) {
        log_data(sound_level_db, 0, -1);
        return;
    }
    light_level_lux = (light_level_lux * 1.2);
    log_data(sound_level_db, light_level_lux, 0);
}

static void sigint_handler(int signal) {
    cleanup();
    exit(0);
}

int main() {
    struct stat st;
    if (stat(LIGHT_LEVELS_FILE, &st) == 0 && S_ISREG(st.st_mode)) {
        remove(LIGHT_LEVELS_FILE);
    }
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        log_error(errno);
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_I2C_ADDRESS) == -1) {
        log_error(errno);
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }
    if ((spi_fd = open("/dev/spidev0.0", O_RDWR)) == -1) {
        log_error(errno);
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) == -1) {
        log_error(errno);
        close(spi_fd);
        spi_fd = -1;
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }
    if ((gpiod_fd = gpiod_open("/dev/gpiochip0", GPIOD_LINE_REQUEST_BOTH, 0)) == -1) {
        log_error(errno);
        close(spi_fd);
        spi_fd = -1;
        close(i2c_fd);
        i2c_fd = -1;
        return 1;
    }
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    while (1) {
        read_sensors();
        sleep(5);
    }
    return 0;
}

