#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define THRESHOLD 30
#define READ_INTERVAL 60 // seconds

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Turn off the pump
    gpioWrite(PUMP_GPIO, 0);
    // Close SPI
    spiClose(SPI_CHANNEL);
    // Terminate pigpio
    gpioTerminate();
    // Exit with status code 0
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open SPI channel
    if (spiOpen(SPI_CHANNEL, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Set up pump GPIO as output
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up pump GPIO\n");
        spiClose(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Initialize timestamp
    time_t last_read_time = time(NULL);

    while (1) {
        // Read timestamp
        time_t current_time = time(NULL);

        // Check if it's time to read the sensor
        if (difftime(current_time, last_read_time) >= READ_INTERVAL) {
            // Read the sensor value
            int16_t value;
            int retries = 0;
            while (retries < 3) {
                if (spiXfer(SPI_CHANNEL, 0x00, &value, 2) == 2) {
                    break;
                } else {
                    retries++;
                    if (retries == 3) {
                        fprintf(stderr, "Failed to read sensor value after 3 retries\n");
                        break;
                    }
                }
            }

            // Validate the read value
            if (retries < 3) {
                // Convert the value to a percentage
                int moisture = (int)((value * 100) / 1024);

                // Check if the moisture level is below the threshold
                if (moisture < THRESHOLD) {
                    // Turn on the pump
                    gpioWrite(PUMP_GPIO, 1);
                } else {
                    // Turn off the pump
                    gpioWrite(PUMP_GPIO, 0);
                }

                // Log the reading
                printf("%d: Moisture level: %d%%\n", (int)current_time, moisture);
            }

            // Update the last read time
            last_read_time = current_time;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

