#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define FAN_PIN 18
#define SAMPLING_INTERVAL 5000  // milliseconds
#define CO2_SLOPE 0.5
#define CO2_INTERCEPT -50
#define CO2_THRESHOLD 700

// Function to convert ADC reading to CO2 ppm
double co2_ppm(uint16_t adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0;  // Invalid ADC value
    }
    return CO2_SLOPE * adc_value + CO2_INTERCEPT;
}

// Function to log data to file
void log_data(double co2_ppm, bool fan_state) {
    char timestamp[20];
    time_t now;
    time(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen("air_quality.log", "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    fprintf(file, "%s,%f,%d\n", timestamp, co2_ppm, fan_state);
    fclose(file);
}

// Signal handler to clean up on exit
void cleanup(int sig) {
    gpioWrite(FAN_PIN, 0);  // Turn off fan
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(0, PI_SPI_MODE_0) < 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockSpeed(0, 1000000) < 0) {
        fprintf(stderr, "Error setting SPI clock speed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetCS(0, 17) < 0) {
        fprintf(stderr, "Error setting SPI CS\n");
        gpioTerminate();
        return 1;
    }

    // Initialize fan pin as output
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting fan pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value;
        int retries = 0;
        while (1) {
            if (gpioReadADC(0, ADC_CHANNEL, &adc_value) < 0) {
                if (retries++ < 5) {
                    fprintf(stderr, "Error reading ADC value, retrying...\n");
                    usleep(100000);  // Wait 100ms before retrying
                    continue;
                } else {
                    fprintf(stderr, "Error reading ADC value after 5 retries, giving up\n");
                    break;
                }
            }
            break;
        }
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        // Convert ADC value to CO2 ppm
        double co2_ppm = co2_ppm(adc_value);

        // Check if CO2 level exceeds threshold
        bool fan_state = (co2_ppm > CO2_THRESHOLD);

        // Log data
        log_data(co2_ppm, fan_state);

        // Update fan state
        gpioWrite(FAN_PIN, fan_state);

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL * 1000);
    }

    return 0;
}

