#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define RELAY_PIN 17
#define SENSOR_PIN 0
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define DEBOUNCE_DELAY 1000
#define POLLING_INTERVAL 100
#define LOG_FILE "door_events.log"

int main() {
    struct gpiod_line *relay_line = NULL;
    struct gpiod_chip *chip = NULL;
    struct spi_ioc_transfer transfer;
    int fd = -1;
    int ret = 0;
    uint8_t data = 0;
    struct timeval last_trigger = {0, 0};
    bool triggered = false;

    // Initialize GPIO
    if ((ret = gpiod_chip_new("gpiochip0", &chip)) < 0) {
        perror("gpiod_chip_new");
        goto cleanup;
    }

    if ((ret = gpiod_line_request_output(chip, "gpio17", GPIOD_LINE_ACTIVE_HIGH, &relay_line)) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    // Initialize SPI
    fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("open");
        goto cleanup;
    }

    transfer.tx_buf = NULL;
    transfer.rx_buf = NULL;
    transfer.len = 1;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = 8;

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        goto cleanup;
    }

    while (1) {
        // Read ADC value
        transfer.tx_buf = NULL;
        transfer.rx_buf = &data;
        if ((ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer)) < 0) {
            perror("ioctl");
            goto cleanup;
        }

        // Check if sensor is connected
        if (data == 0xFF) {
            // Sensor not connected, skip
            usleep(POLLING_INTERVAL * 1000);
            continue;
        }

        // Check if sensor is within range
        if (data < 200) {
            // Proximity detected, check debounce delay
            if (gettimeofday(&now, NULL) < 0) {
                perror("gettimeofday");
                goto cleanup;
            }
            if (now.tv_sec - last_trigger.tv_sec >= DEBOUNCE_DELAY || triggered) {
                // Trigger relay
                if ((ret = gpiod_line_set_value(relay_line, 1)) < 0) {
                    perror("gpiod_line_set_value");
                    goto cleanup;
                }
                triggered = true;
                gettimeofday(&last_trigger, NULL);
                fprintf(log_file, "%ld.%06ld: Door opened\n", last_trigger.tv_sec, last_trigger.tv_usec);
            }
        } else {
            // Proximity not detected, reset relay
            if ((ret = gpiod_line_set_value(relay_line, 0)) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
            triggered = false;
        }

        // Wait for polling interval
        usleep(POLLING_INTERVAL * 1000);
    }

cleanup:
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (chip) {
        gpiod_chip_release(chip);
    }
    if (fd >= 0) {
        close(fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    return 0;
}

