#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNELS 3
#define ADC_AVERAGE_WINDOW 5
#define ADC_AVERAGE_INTERVAL 5000000  // 5 seconds
#define VALVE_GPIO 17
#define VALVE_PWM_FREQ 100
#define VALVE_PWM_RANGE 100
#define VALVE_MIN 0
#define VALVE_MAX 100
#define VALVE_OPENING_MIN 0
#define VALVE_OPENING_MAX 100
#define ADC_MIN 0
#define ADC_MAX 1023
#define ADC_GAIN 1
#define ADC_OFFSET 0

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd;
    int valve_pwm;
    int valve_opening;
    int adc_values[ADC_CHANNELS];
    int adc_average;
    int log_fd;
    char log_buffer[256];
    struct tm *log_time;
    time_t log_timestamp;
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open SPI
    spi_fd = spiOpen(0, 1, 1000000, 0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fd = fopen("irrigation.log", "a");
    if (log_fd == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set up valve PWM
    valve_pwm = gpioPWM(VALVE_GPIO, 0);
    if (valve_pwm < 0) {
        fprintf(stderr, "Failed to set up valve PWM\n");
        fclose(log_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read ADC values
        for (i = 0; i < ADC_CHANNELS; i++) {
            int result;
            uint8_t command = 0x68 + (i << 2);
            uint8_t data[3];
            data[0] = 0x00;
            data[1] = 0x00;
            data[2] = 0x00;
            if (spiXfer(spi_fd, &command, 1, data, 3) != 3) {
                fprintf(stderr, "Failed to read ADC value %d\n", i);
                continue;
            }
            adc_values[i] = (data[1] << 8) | data[0];
        }

        // Calculate average ADC value
        adc_average = 0;
        int count = 0;
        for (i = 0; i < ADC_CHANNELS; i++) {
            if (adc_values[i] != -1) {
                adc_average += adc_values[i];
                count++;
            }
        }
        if (count > 0) {
            adc_average /= count;
        }

        // Map ADC average to valve opening
        valve_opening = (int)((float)(VALVE_OPENING_MAX - VALVE_OPENING_MIN) * (float)(ADC_MAX - adc_average) / (float)(ADC_MAX - ADC_MIN) + VALVE_OPENING_MIN);

        // Set valve PWM
        if (gpioPWM(VALVE_GPIO, (float)valve_opening / VALVE_OPENING_MAX * VALVE_PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set valve PWM\n");
        }

        // Log data
        log_timestamp = time(NULL);
        log_time = localtime(&log_timestamp);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", log_time);
        fprintf(log_fd, "%s, %d, %d, %d, %d\n", log_buffer, adc_values[0], adc_values[1], adc_values[2], valve_opening);
        fflush(log_fd);

        // Sleep
        usleep(ADC_AVERAGE_INTERVAL);
    }

    // Close valve PWM
    gpioPWM(VALVE_GPIO, 0);

    // Close SPI
    spiClose(spi_fd);

    // Close log file
    fclose(log_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

