#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define ADC_BITS 10
#define ADC_MAX 1023
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_DEVICE 0
#define SPI_CE 8
#define FILE_NAME "soil_data.txt"
#define MAX_ATTEMPTS 5
#define INITIAL_BACKOFF 100
#define MAX_BACKOFF 1000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void write_spi(uint8_t* data, int len) {
    int attempts = 0;
    int backoff = INITIAL_BACKOFF;
    while (attempts < MAX_ATTEMPTS) {
        if (gpio_spi_xfer(SPI_DEVICE, data, len) == 0) {
            return;
        }
        attempts++;
        if (attempts < MAX_ATTEMPTS) {
            usleep(backoff);
            backoff *= 2;
            if (backoff > MAX_BACKOFF) {
                backoff = MAX_BACKOFF;
            }
        }
    }
    fprintf(stderr, "SPI communication failed persistently\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CE mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SPI_CE, PI_HIGH) < 0) {
        fprintf(stderr, "Failed to set SPI CE high\n");
        gpioTerminate();
        return 1;
    }

    uint8_t command[] = {0x06, 0x00, 0x00, 0x00};
    command[1] = (ADC_CHANNEL >> 4) & 0x01;
    command[2] = ADC_CHANNEL & 0x0F;

    while (running) {
        if (gpioSetMode(SPI_CE, PI_LOW) < 0) {
            fprintf(stderr, "Failed to set SPI CE low\n");
            break;
        }

        write_spi(command, 4);

        uint8_t data[3];
        memset(data, 0, 3);
        write_spi(data, 3);

        if (gpioSetMode(SPI_CE, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to set SPI CE high\n");
            break;
        }

        uint16_t adc_value = (data[1] << 8) | data[0];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        double moisture_percentage = (100.0 * adc_value) / ADC_MAX;

        time_t now = time(NULL);
        struct tm* current_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", current_time);

        FILE* file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing\n");
            break;
        }

        fprintf(file, "%s,%.2f\n", timestamp, moisture_percentage);
        fclose(file);

        sleep(5);
    }

    gpioSetMode(SPI_CE, PI_OUTPUT);
    gpioSetMode(SPI_CE, PI_LOW);
    gpioTerminate();

    return 0;
}

