            fprintf(stderr, "Failed to set SPI CE low\n");
            break;
        }

        write_spi(command, 4);

        uint8_t data[3];
        memset(data, 0, 3);
        write_spi(data, 3);

        if (gpioSetMode(SPI_CE, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to set SPI CE high\n");
            break;
        }

        uint16_t adc_value = (data[1] << 8) | data[0];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        double moisture_percentage = (100.0 * adc_value) / ADC_MAX;

        time_t now = time(NULL);
        struct tm* current_time = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", current_time);

        FILE* file = fopen(FILE_NAME, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open file for writing\n");
            break;
        }

        fprintf(file, "%s,%.2f\n", timestamp, moisture_percentage);
        fclose(file);

        sleep(5);
    }

    gpioSetMode(SPI_CE, PI_OUTPUT);
    gpioSetMode(SPI_CE, PI_LOW);
    gpioTerminate();

    return 0;
}
