#include <syslog.h>

#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define RETRY_COUNT 3
#define RETRY_DELAY 1000  // 1 second

// Function to convert ADC value to AQI
int aqi_from_adc(uint16_t adc_value) {
    return (int)((adc_value * 500.0) / 1023.0);
}

// Function to read ADC value from MCP3008
uint16_t read_adc(int spi_fd) {
    uint8_t command = 0x01 | 0x08 | (ADC_CHANNEL << 4);
    uint8_t response[3];
    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &command, response, 3) == -1)) {
            if (errno == EIO) {
                // SPI read failed, retry
                retries++;
                usleep(RETRY_DELAY);
                continue;
            } else {
                // Other error, re-initialize SPI
                close(spi_fd);
                spi_fd = open("/dev/spidev0.0", O_RDWR);
                if (spi_fd == -1) {
                    syslog(LOG_ERR, "Failed to open SPI device");
                    exit(1);
                }
                if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) == -1) {
                    syslog(LOG_ERR, "Failed to set SPI mode");
                    exit(1);
                }
                if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) == -1) {
                    syslog(LOG_ERR, "Failed to set SPI speed");
                    exit(1);
                }
            }
        } else {
            // Extract 10-bit ADC value from response
            uint16_t adc_value = (response[1] << 8) | response[2];
            return adc_value;
        }
    }

