    int retries = 0;

    while (retries < RETRY_COUNT) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1, &command, response, 3) == -1)) {
            if (errno == EIO) {
                // SPI read failed, retry
                retries++;
                usleep(RETRY_DELAY);
                continue;
