#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 8
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_BITS 8
#define ADC_READ_RETRY 3
#define ADC_READ_DELAY 100000 // 100 ms

// Function to classify readings
const char* classify_reading(int ppm) {
    if (ppm > 50) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm < 20) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Function to read ADC value
int read_adc(int spi_fd) {
    uint8_t tx[] = { 0x01, (ADC_CHANNEL << 4) | 0x80, 0x00 };
    uint8_t rx[3];
    int retries = 0;

    while (retries < ADC_READ_RETRY) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(3, tx, rx, 3) == -1)) {
            if (errno == EIO) {
                // Sensor absent, return 0
                return 0;
            } else if (errno == EAGAIN) {
                // Retry
                retries++;
                usleep(ADC_READ_DELAY);
                continue;
            } else {
                // Other error, log and return -1
                fprintf(stderr, "Error reading ADC: %s\n", strerror(errno));
                return -1;
            }
        } else {
            // Valid read, return result
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
    }

    // All retries failed, log error and return -1
    fprintf(stderr, "Failed to read ADC after %d retries\n", ADC_READ_RETRY);
    return -1;
}

// Function to convert ADC value to PPM
double adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    // Close all file descriptors
    close(spi_fd);
    gpiod_close(gpio_fd);
    // Release GPIO resources
    gpiod_chip_free(gpio_chip);
    // Exit with status 0
    exit(0);
}

int main() {
    // Initialize GPIO
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Set up GPIO pin as output
    gpio_line_request_output(gpio_fd, ADC_CS_PIN, 0);
    gpio_line_set_value(gpio_fd, ADC_CS_PIN, 0);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        gpiod_chip_free(gpio_chip);
        return 1;
    }

    // Set up SPI parameters
    struct spi_ioc_transfer spi_transfer = {
        .tx_buf = (uint64_t)tx,
        .rx_buf = (uint64_t)rx,
        .len = 3,
        .speed_hz = ADC_SPI_SPEED,
        .bits_per_word = ADC_BITS,
        .mode = ADC_SPI_MODE
    };

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_free(gpio_chip);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        close(spi_fd);
        gpiod_chip_free(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set CS pin low
        gpio_line_set_value(gpio_fd, ADC_CS_PIN, 0);

        // Read ADC value
        int adc_value = read_adc(spi_fd);
        if (adc_value == -1) {
            // Log error and continue
            continue;
        }

        // Convert ADC value to PPM
        double ppm = adc_to_ppm(adc_value);

        // Classify reading
        const char* classification = classify_reading(ppm);

        // Log reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
        fprintf(stderr, "%s: PPM: %.2f, Classification: %s\n", timestamp, ppm, classification);

        // Log to file
        FILE* log_file = fopen("alcohol_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            continue;
        }
        fprintf(log_file, "%s: PPM: %.2f, Classification: %s\n", timestamp, ppm, classification);
        fclose(log_file);

        // Set CS pin high
        gpio_line_set_value(gpio_fd, ADC_CS_PIN, 1);

        // Sleep for 1 second
        sleep(1);
    }

    // Close all file descriptors
    close(spi_fd);
    gpiod_chip_free(gpio_chip);

    // Exit with status 0
    return 0;
}

