#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "irrigation.log"
#define PUMP_GPIO 18
#define THRESHOLD 300
#define ADC_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CE 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_data(int moisture, bool pump_on) {
    time_t now;
    struct tm *lt;
    char timestamp[20];

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s, moisture: %d, pump: %s\n", timestamp, moisture, pump_on ? "ON" : "OFF");
    fclose(log_file);
}

int main() {
    int moisture;
    bool pump_on = false;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    if (gpioSetMode(SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CE mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_SCLK, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI SCLK mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MOSI, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI MOSI mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_MISO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set SPI MISO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI clock and mode
    if (gpioSetClockSpeed(SPI_SCLK, SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI clock speed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SPI_CE, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }

    // Open SPI device
    int spi_fd = gpioOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        // Read ADC value
        char buffer[3];
        buffer[0] = 0x06; // Start bit, single-ended, channel 0
        buffer[1] = 0x00; // No delay
        buffer[2] = 0x00; // No delay

        if (gpioSPIDataRW(spi_fd, buffer, buffer, 3) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        moisture = (buffer[1] & 0x0F) << 8 | buffer[2];

        // Check if moisture level is below threshold
        if (moisture < THRESHOLD) {
            if (!pump_on) {
                if (gpioWrite(PUMP_GPIO, 1) < 0) {
                    fprintf(stderr, "Failed to turn on pump\n");
                } else {
                    pump_on = true;
                }
            }
        } else {
            if (pump_on) {
                if (gpioWrite(PUMP_GPIO, 0) < 0) {
                    fprintf(stderr, "Failed to turn off pump\n");
                } else {
                    pump_on = false;
                }
            }
        }

        log_data(moisture, pump_on);

        sleep(60);
    }

    // Turn off pump
    if (pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) < 0) {
            fprintf(stderr, "Failed to turn off pump\n");
        }
    }

    // Close SPI device
    gpioClose(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

