#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <sys/time.h>

#define ADC_CHANNEL 0
#define ADC_CS_PIN 0
#define ADC_CLK_SPEED 1000000
#define ADC_SAMPLE_RATE 100

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SPI
    int spiHandle = gpioOpen(ADC_CS_PIN, GPIO_MODE_OUTPUT);
    if (spiHandle < 0) {
        fprintf(stderr, "ERROR: Failed to open SPI handle\n");
        gpioTerminate();
        return 1;
    }

    // Set up SPI configuration
    struct spi_ioc_transfer spiTransfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 1,
        .speed_hz = ADC_CLK_SPEED,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .bits_modulo = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_change = 1
    };

    // Open log file
    FILE *logFile = fopen("airflow_log.txt", "a");
    if (logFile == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        gpioClose(spiHandle);
        gpioTerminate();
        return 1;
    }

    // Set up timer
    int timerId = gpioSetTimer(ADC_SAMPLE_RATE, 0, 0);
    if (timerId < 0) {
        fprintf(stderr, "ERROR: Failed to set up timer\n");
        gpioClose(spiHandle);
        fclose(logFile);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint8_t adcValue;
        struct timeval tv;
        gettimeofday(&tv, NULL);
        struct tm *timeInfo = localtime(&tv.tv_sec);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeInfo);
        if (gpioSPISendReceive(spiHandle, &adcValue, &spiTransfer) < 0) {
            fprintf(logFile, "%s ERROR: ADC read failed\n", timestamp);
        } else {
            // Convert ADC value to voltage
            float voltage = (adcValue * 3.3f) / 255.0f;

            // Convert voltage to airflow
            float airflow = (voltage - 0.5f) / (4.5f - 0.5f) * 200.0f;

            // Log reading
            fprintf(logFile, "%s %f SLPM\n", timestamp, airflow);
        }
    }

    // Clean up on exit
    gpioSPIClose(spiHandle);
    fclose(logFile);
    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT
void sigintHandler(int signal) {
    gpioSPIClose(spiHandle);
    fclose(logFile);
    gpioTerminate();
    exit(0);
}

// Register signal handler for SIGINT
void setupSignalHandler() {
    struct sigaction sa;
    sa.sa_handler = sigintHandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "ERROR: Failed to set up signal handler\n");
        exit(1);
    }
}

