#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "GPIO8"
#define SPI_DEV "/dev/spidev0.0"
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE_HZ 1000
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

int gpiod_fd = -1;
int spi_fd = -1;
FILE *log_file = NULL;

void cleanup(int sig) {
    if (gpiod_fd != -1) {
        gpiod_line_release(gpiod_fd, GPIO_LINE_NAME);
        gpiod_close(gpiod_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct gpiod_line_request req;
    struct gpiod_line_config config;
    struct spi_ioc_transfer transfer;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct timespec start_time;
    struct timespec next_sample_time;
    int ret;

    // Initialize signal handler for cleanup
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open GPIO chip
    gpiod_fd = gpiod_chip_open(GPIO_CHIP_NAME);
    if (gpiod_fd == -1) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO8 as output
    req.line = GPIO_LINE_NAME;
    req.consumer = "my_consumer";
    req.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_chip_request_lines(gpiod_fd, &req, 1);
    if (ret != 0) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", gpiod_error_str(ret));
        gpiod_close(gpiod_fd);
        return 1;
    }

    // Configure GPIO8 as output
    config.line = GPIO_LINE_NAME;
    config.consumer = "my_consumer";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    ret = gpiod_line_config(gpiod_fd, &config);
    if (ret != 0) {
        fprintf(stderr, "Failed to configure GPIO line: %s\n", gpiod_error_str(ret));
        gpiod_line_release(gpiod_fd, GPIO_LINE_NAME);
        gpiod_close(gpiod_fd);
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEV, O_RDWR);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpiod_line_release(gpiod_fd, GPIO_LINE_NAME);
        gpiod_close(gpiod_fd);
        return 1;
    }

