#include <errno.h>

#define ADC_CHANNEL 0
#define ADC_VREF 3.3
#define PPM_LINEAR_RELATIONSHIP 1000.0

// Signal handler to close SPI and terminate pigpio cleanly
void sigint_handler(int sig) {
    gpio_spi_close();
    pigpio_stop();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error());
        return 1;
    }

    // Set up SPI
    int spi_fd = gpio_spi_open(0, 1, 1000000); // CE0, 1 MHz
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        pigpio_stop();
        return 1;
    }

    // Set up GPIO for CE0
    if (gpio_set_mode(8, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 mode: %s\n", pigpio_error());
        gpio_spi_close(spi_fd);
        pigpio_stop();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("gas_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpio_spi_close(spi_fd);
        pigpio_stop();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpio_spi_close(spi_fd);
        pigpio_stop();
        return 1;
    }

    // Main loop
    while (1) {
        // Set CE0 high
        gpio_write(8, 1);

        // Read ADC value
        uint16_t adc_value;
        int retries = 0;
        while (1) {
            if (gpio_spi_transfer(spi_fd, 0x00, &adc_value, 2) >= 0) {
                break;
            }
            if (retries++ > 5) {
                fprintf(stderr, "Failed to read ADC value after 5 retries\n");
                break;
            }
            usleep(100000); // 100 ms delay
        }

        // Convert ADC value to voltage
        float voltage = (adc_value * ADC_VREF) / 1024.0;

        // Calculate PPM
        float ppm = voltage * PPM_LINEAR_RELATIONSHIP;

        // Log data
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld.%06ld %f %f\n", tv.tv_sec, tv.tv_usec, voltage, ppm);

        // Print data to console
        printf("Voltage: %f V, PPM: %f\n", voltage, ppm);

        // Set CE0 low
        gpio_write(8, 0);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    fclose(log_file);
    gpio_spi_close(spi_fd);
    pigpio_stop();
    return 0;
}

