#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the SPI bus and chip select pins
#define SPI_BUS 0
#define CS_PIN 8
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11

// Define the ADC channel numbers for each axis
#define X_AXIS 0
#define Y_AXIS 1
#define Z_AXIS 2

// Define the number of samples to average for the Kalman filter
#define NUM_SAMPLES 10

// Define the Kalman filter parameters
#define Q 0.01
#define R 0.1
#define A 1.0
#define B 1.0
#define H 1.0

// Define the ADXL335 sensitivity and zero-g bias
#define SENSITIVITY 300.0 / 1024.0
#define ZERO_G_BIAS 1.5

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release the SPI bus and GPIO resources
    gpioTerminate();
    exit(0);
}

// Define the Kalman filter function
void kalman_filter(float *x, float *y, float *z) {
    static float x_prev = 0.0;
    static float y_prev = 0.0;
    static float z_prev = 0.0;
    static float x_sum = 0.0;
    static float y_sum = 0.0;
    static float z_sum = 0.0;
    static int count = 0;

    // Update the sum of previous values
    x_sum += *x;
    y_sum += *y;
    z_sum += *z;

    // Update the previous values
    x_prev = *x;
    y_prev = *y;
    z_prev = *z;

    // Update the count
    count++;

    // If we have enough samples, calculate the average
    if (count >= NUM_SAMPLES) {
        *x = x_sum / NUM_SAMPLES;
        *y = y_sum / NUM_SAMPLES;
        *z = z_sum / NUM_SAMPLES;

        // Reset the sum and count
        x_sum = 0.0;
        y_sum = 0.0;
        z_sum = 0.0;
        count = 0;
    } else {
        // Otherwise, use the previous values
        *x = x_prev;
        *y = y_prev;
        *z = z_prev;
    }

    // Apply the Kalman filter
    *x = A * *x + B * (*x - *x_prev);
    *y = A * *y + B * (*y - *y_prev);
    *z = A * *z + B * (*z - *z_prev);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the SPI bus
    if (gpioSetMode(SPI_BUS, PI_SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up the chip select pin as an output
    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up the MOSI, MISO, and SCLK pins as outputs
    if (gpioSetMode(MOSI_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MOSI pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MISO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MISO pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCLK pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up the chip select pin as a low output
    if (gpioWrite(CS_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set CS pin value\n");
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the ADC values for each axis
        uint16_t x = 0;
        uint16_t y = 0;
        uint16_t z = 0;
        if (spiXfer(SPI_BUS, &x, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }
        if (spiXfer(SPI_BUS, &y, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }
        if (spiXfer(SPI_BUS, &z, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }

        // Scale the ADC values to g
        float x_scaled = (x * SENSITIVITY) + ZERO_G_BIAS;
        float y_scaled = (y * SENSITIVITY) + ZERO_G_BIAS;
        float z_scaled = (z * SENSITIVITY) + ZERO_G_BIAS;

        // Apply the Kalman filter
        kalman_filter(&x_scaled, &y_scaled, &z_scaled);

        // Print the filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_scaled, y_scaled, z_scaled);

        // Sleep for 100ms
        usleep(100000);
    }

    // Release the SPI bus and GPIO resources
    gpioTerminate();

    return 0;
}

