        uint16_t y = 0;
        uint16_t z = 0;
        if (spiXfer(SPI_BUS, &x, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }
        if (spiXfer(SPI_BUS, &y, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }
        if (spiXfer(SPI_BUS, &z, 1, MOSI_PIN, MISO_PIN, SCLK_PIN, CS_PIN, 0, 0, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC values\n");
            gpioTerminate();
            return 1;
        }

        // Scale the ADC values to g
        float x_scaled = (x * SENSITIVITY) + ZERO_G_BIAS;
        float y_scaled = (y * SENSITIVITY) + ZERO_G_BIAS;
        float z_scaled = (z * SENSITIVITY) + ZERO_G_BIAS;

        // Apply the Kalman filter
        kalman_filter(&x_scaled, &y_scaled, &z_scaled);

        // Print the filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_scaled, y_scaled, z_scaled);

        // Sleep for 100ms
        usleep(100000);
    }

    // Release the SPI bus and GPIO resources
    gpioTerminate();

    return 0;
}
