        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        exit(1);
    }

    struct gpiod_line *line3 = gpiod_line_request_input(chip, GPIO_SENSOR3, "sensor3");
    if (!line3) {
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read GPIO lines
        int value1 = gpiod_line_get_value(line1);
        int value2 = gpiod_line_get_value(line2);
