            fprintf(stderr, "Error reading GPIO line\n");
            continue;
        }

        // Calculate magnetic field strength
        double mT1 = (value1 == 1) ? (VCC - V_QUIESCENT) / SENSITIVITY : 0;
        double mT2 = (value2 == 1) ? (VCC - V_QUIESCENT) / SENSITIVITY : 0;
        double mT3 = (value3 == 1) ? (VCC - V_QUIESCENT) / SENSITIVITY : 0;

        // Check for out-of-range values
        if (mT1 < -100 || mT1 > 100) {
            fprintf(stderr, "Warning: sensor1 value out of range: %f mT\n", mT1);
        }
        if (mT2 < -100 || mT2 > 100) {
            fprintf(stderr, "Warning: sensor2 value out of range: %f mT\n", mT2);
        }
        if (mT3 < -100 || mT3 > 100) {
            fprintf(stderr, "Warning: sensor3 value out of range: %f mT\n", mT3);
        }

        // Log values
        fprintf(log_file, "%f,%f,%f\n", mT1, mT2, mT3);
        fflush(log_file);

        // Sleep
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
