#define LOG_FILE "watering.log"
#define PUMP_GPIO 17
#define ADC_CHANNEL 0
#define ADC_SPI_SPEED 500000
#define ADC_SPI_MODE 0
#define ADC_SPI_CE 0
#define ADC_THRESHOLD 30

// Signal handler for clean shutdown
void sigint_handler(int sig) {
    gpioWrite(PUMP_GPIO, 0);
    pigpio_close();
    exit(0);
}

// Function to log events to file
void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d - %s\n", current_time->tm_year + 1900, current_time->tm_mon + 1, current_time->tm_mday, current_time->tm_hour, current_time->tm_min, current_time->tm_sec, message);
    fclose(file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio");
        return 1;
    }

    // Set up signal handler for clean shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Set up GPIO for pump
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_event("Failed to set up GPIO for pump");
        gpioTerminate();
        return 1;
    }

    // Set up SPI for ADC
    if (spiOpen(ADC_SPI_CE, ADC_SPI_SPEED, ADC_SPI_MODE) < 0) {
        log_event("Failed to open SPI for ADC");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value;
        if (spiXfer(ADC_SPI_CE, 1, &adc_value, 1, 0) < 0) {
            log_event("Failed to read ADC value");
            continue;
        }

        // Calculate moisture level
        int moisture_level = (adc_value * 100) / 1023;

        // Log moisture level
        log_event("Moisture level: %d%%", moisture_level);

        // Turn on pump if moisture level is below threshold
        if (moisture_level < ADC_THRESHOLD) {
            log_event("Pump on");
            gpioWrite(PUMP_GPIO, 1);
        } else {
            log_event("Pump off");
            gpioWrite(PUMP_GPIO, 0);
        }

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up on exit
    gpioWrite(PUMP_GPIO, 0);
    pigpio_close();
    gpioTerminate();
    return 0;
}

