#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define CSV_FILE "sensor_data.csv"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_CHANNELS 3

int spi_fd = -1;
FILE *csv_file = NULL;

void cleanup(int sig) {
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

int main() {
    struct spi_ioc_transfer transfer;
    uint8_t data[3];
    uint16_t values[SPI_CHANNELS];
    char buffer[256];

    // Initialize signal handler for SIGINT
    signal(SIGINT, cleanup);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd == -1) {
        perror("Failed to open SPI device");
        exit(1);
    }

    // Set SPI mode, bits per word, and speed
    struct spi_ioc_transfer xfer;
    memset(&xfer, 0, sizeof(xfer));
    xfer.tx_buf = (unsigned long) data;
    xfer.rx_buf = (unsigned long) data;
    xfer.len = 3;
    xfer.speed_hz = SPI_SPEED;
    xfer.bits_per_word = SPI_BITS_PER_WORD;
    xfer.cs_change = 1;
    xfer.cs_high = 1;
    xfer.cs_low = 1;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) == -1) {
        perror("Failed to set SPI mode");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) == -1) {
        perror("Failed to set SPI bits per word");
        exit(1);
    }
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) == -1) {
        perror("Failed to set SPI speed");
        exit(1);
    }

    // Open CSV file for writing
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        exit(1);
    }

    // Log data every 1 second
    while (1) {
        // Read from each channel
        for (int i = 0; i < SPI_CHANNELS; i++) {
            data[0] = 0x01; // Start bit
            data[1] = 0x80 | (i << 4); // Single-ended mode with channel select
            data[2] = 0x00; // Dummy byte
            xfer.tx_buf = (unsigned long) data;
            xfer.rx_buf = (unsigned long) data;
            xfer.len = 3;
            if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) == -1) {
                perror("Failed to send SPI message");
                exit(1);
            }
            values[i] = ((data[1] & 0x03) << 8) | data[2];
        }

        // Log data to CSV file
        sprintf(buffer, "%d,%d,%d\n", values[0], values[1], values[2]);
        if (fputs(buffer, csv_file) == EOF) {
            perror("Failed to write to CSV file");
            exit(1);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

