    if (!json) {
        fprintf(stderr, "Error parsing JSON: %s\n", cJSON_GetErrorPtr());
        cJSON_Delete(json);
        return;
    }
    cJSON *led_state = cJSON_GetObjectItem(json, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        cJSON_Delete(json);
        return;
    }
    int state = led_state->valueint;
    cJSON_Delete(json);
    gpioWrite(GPIO_PIN, state);
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc) {
        fprintf(stderr, "Error disconnecting from MQTT broker: %d\n", rc);
    }
    running = 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error initialising pigpio: %d\n", rc);
        exit(1);
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    mosquitto_lib_init();
    mosquitto *mosq = mosquitto_new(MQTT_CLIENT_ID);
    if (!mosq) {
        fprintf(stderr, "Error creating MQTT client\n");
        gpioTerminate();
        exit(1);
    }
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    reconnect_mqtt();

    while (running) {
        if (!mosquitto_loop_start(mosq, 1000)) {
            fprintf(stderr, "Error starting MQTT loop\n");
            break;
        }
        if (!running) {
            break;
        }
        if (reconnect_delay < MAX_RECONNECT_DELAY) {
            reconnect_delay *= 2;
        }
        sleep(reconnect_delay);
        mosquitto_disconnect(mosq);
        reconnect_mqtt();
    }

    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

