#include <signal.h>
#include <unistd.h>
#include <libgpiod.h>

// Function to handle signal interrupts
void signal_handler(int sig) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    gpiod_context_unref(context);
    exit(0);
}

int main() {
    // Initialize libgpiod context
    context = gpiod_context_new();
    if (!context) {
        fprintf(stderr, "Failed to create libgpiod context\n");
        return 1;
    }

    // Open the chip
    chip = gpiod_chip_open(context, "gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open chip\n");
        gpiod_context_unref(context);
        return 1;
    }

    // Request the line
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        fprintf(stderr, "Failed to request line\n");
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the alarm LED line
    alarm_line = gpiod_chip_get_line(chip, 18);
    if (!alarm_line) {
        fprintf(stderr, "Failed to request alarm line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }

    // Export the lines
    if (gpiod_line_export(line, 0) < 0) {
        fprintf(stderr, "Failed to export line\n");
        gpiod_line_release(alarm_line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }
    if (gpiod_line_export(alarm_line, 0) < 0) {
        fprintf(stderr, "Failed to export alarm line\n");
        gpiod_line_release(alarm_line);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }

    // Set the direction of the lines
    if (gpiod_line_request_output(line, 0, 0) < 0) {
        fprintf(stderr, "Failed to set line direction\n");
        gpiod_line_unexport(line);
        gpiod_line_unexport(alarm_line);
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }
    if (gpiod_line_request_output(alarm_line, 0, 0) < 0) {
        fprintf(stderr, "Failed to set alarm line direction\n");
        gpiod_line_unexport(line);
        gpiod_line_unexport(alarm_line);
        gpiod_chip_close(chip);
        gpiod_context_unref(context);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the sound sensor
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read line\n");
            gpiod_line_unexport(line);
            gpiod_line_unexport(alarm_line);
            gpiod_chip_close(chip);
            gpiod_context_unref(context);
            return 1;
        }

        // Print the sound level
        printf("%d\n", value);

        // Blink the alarm LED if sound is detected
        if (value == 0) {
            gpiod_line_set_value(alarm_line, 1);
            usleep(1000000); // 1 second
            gpiod_line_set_value(alarm_line, 0);
        }

        // Delay
        usleep(100000); // 100 ms
    }

    // Clean up
    gpiod_line_unexport(line);
    gpiod_line_unexport(alarm_line);
    gpiod_chip_close(chip);
    gpiod_context_unref(context);
    return 0;
}

