#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <errno.h>

// Flag to indicate whether the program should exit
volatile sig_atomic_t exit_flag = 0;

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Open the GPIO chip
    int chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip < 0) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line 17
    int line = gpiod_chip_get_line(chip, 17);
    if (line < 0) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        exit(EXIT_FAILURE);
    }

    // Request the line for falling-edge event detection
    int request = gpiod_line_request(chip, line, "vibration-monitor", GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_EVENT_RISING | GPIOD_LINE_EVENT_FALLING);
    if (request < 0) {
        gpiod_line_release(chip, line);
        gpiod_chip_close(chip);
        perror("gpiod_line_request");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    FILE *log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (!log_file) {
        gpiod_line_release(chip, line);
        gpiod_chip_close(chip);
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    // Install signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        gpiod_line_release(chip, line);
        gpiod_chip_close(chip);
        fclose(log_file);
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Wait for a falling-edge event
        int event = gpiod_line_event_wait(chip, line, GPIOD_LINE_EVENT_FALLING, 1000);
        if (event < 0) {
            gpiod_line_release(chip, line);
            gpiod_chip_close(chip);
            fclose(log_file);
            perror("gpiod_line_event_wait");
            exit(EXIT_FAILURE);
        }

        // Read the event
        int value = gpiod_line_event_read(chip, line);
        if (value < 0) {
            gpiod_line_release(chip, line);
            gpiod_chip_close(chip);
            fclose(log_file);
            perror("gpiod_line_event_read");
            exit(EXIT_FAILURE);
        }

        // Log and print the event
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s: Falling edge detected on GPIO 17\n", timestamp);
        fprintf(stdout, "%s: Falling edge detected on GPIO 17\n", timestamp);
        fflush(stdout);

        // Shutdown the system
        system("sudo shutdown -h now");
    }

    // Clean up
    gpiod_line_release(chip, line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

