#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// BMP280 sensor constants
#define BMP280_ADDRESS 0x76
#define BMP280_CHIP_ID 0xD0
#define BMP280_CALIBRATION_START 0x88
#define BMP280_PRESSURE_MSB 0xF7
#define BMP280_PRESSURE_LSB 0xF8
#define BMP280_PRESSURE_XLSB 0xF9
#define BMP280_TEMP_MSB 0xFA
#define BMP280_TEMP_LSB 0xFB
#define BMP280_TEMP_XLSB 0xFC

// Bosch compensation formulas
#define BMP280_T1_LSB 0x00
#define BMP280_T1_MSB 0x01
#define BMP280_T2_LSB 0x02
#define BMP280_T2_MSB 0x03
#define BMP280_T3_LSB 0x04
#define BMP280_T3_MSB 0x05
#define BMP280_P1_LSB 0x06
#define BMP280_P1_MSB 0x07
#define BMP280_P2_LSB 0x08
#define BMP280_P2_MSB 0x09
#define BMP280_P3_LSB 0x0A
#define BMP280_P3_MSB 0x0B
#define BMP280_P4_LSB 0x0C
#define BMP280_P4_MSB 0x0D
#define BMP280_P5_LSB 0x0E
#define BMP280_P5_MSB 0x0F
#define BMP280_P6_LSB 0x10
#define BMP280_P6_MSB 0x11
#define BMP280_P7_LSB 0x12
#define BMP280_P7_MSB 0x13
#define BMP280_P8_LSB 0x14
#define BMP280_P8_MSB 0x15
#define BMP280_P9_LSB 0x16
#define BMP280_P9_MSB 0x17

// Sea-level pressure in Pa
#define SEA_LEVEL_PRESSURE 101325

// Function to read a byte from the BMP280 sensor
uint8_t read_byte(uint8_t reg) {
    uint8_t value;
    if (gpioI2CReadReg(BMP280_ADDRESS, reg, &value, 1) != 0) {
        fprintf(stderr, "Error reading from BMP280: %s\n", strerror(errno));
        exit(1);
    }
    return value;
}

// Function to read a 16-bit word from the BMP280 sensor
uint16_t read_word(uint8_t reg) {
    uint16_t value;
    if (gpioI2CReadReg(BMP280_ADDRESS, reg, (uint8_t*)&value, 2) != 0) {
        fprintf(stderr, "Error reading from BMP280: %s\n", strerror(errno));
        exit(1);
    }
    return value;
}

// Function to read a 24-bit word from the BMP280 sensor
uint32_t read_word24(uint8_t reg) {
    uint32_t value;
    if (gpioI2CReadReg(BMP280_ADDRESS, reg, (uint8_t*)&value, 3) != 0) {
        fprintf(stderr, "Error reading from BMP280: %s\n", strerror(errno));
        exit(1);
    }
    return value;
}

// Function to write a byte to the BMP280 sensor
void write_byte(uint8_t reg, uint8_t value) {
    if (gpioI2CWriteReg(BMP280_ADDRESS, reg, &value, 1) != 0) {
        fprintf(stderr, "Error writing to BMP280: %s\n", strerror(errno));
        exit(1);
    }
}

// Function to write a 16-bit word to the BMP280 sensor
void write_word(uint8_t reg, uint16_t value) {
    if (gpioI2CWriteReg(BMP280_ADDRESS, reg, (uint8_t*)&value, 2) != 0) {
        fprintf(stderr, "Error writing to BMP280: %s\n", strerror(errno));
        exit(1);
    }
}

// Function to calculate the temperature in Celsius
float calculate_temperature(uint16_t adc) {
    int32_t t_fine = 0;
    uint8_t t1 = read_byte(BMP280_T1_LSB);
    uint8_t t2 = read_byte(BMP280_T2_MSB);
    uint8_t t3 = read_byte(BMP280_T3_LSB);
    t_fine = (t1 << 8) | t2;
    t_fine = (t_fine << 8) | t3;
    t_fine = (t_fine >> 4) * 100;
    float temperature = (t_fine * 165.0) / 100.0;
    return temperature;
}

// Function to calculate the pressure in Pa
float calculate_pressure(uint32_t adc) {
    int32_t p = 0;
    uint8_t p1 = read_byte(BMP280_P1_LSB);
    uint8_t p2 = read_byte(BMP280_P2_MSB);
    uint8_t p3 = read_byte(BMP280_P3_LSB);
    uint8_t p4 = read_byte(BMP280_P4_MSB);
