#include <signal.h>
#include <pigpio.h>

#define NUM_ENTRIES 120
#define FILE_NAME "temp_log.dat"
#define SPI_CHANNEL 0
#define ADC_CHANNEL 0
#define VREF 3.3
#define LM35_MV_PER_C 0.01

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int spi_fd = -1;
    int file_fd = -1;
    float buffer[NUM_ENTRIES];
    int index = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI
    spi_fd = gpioOpen(SPI_CHANNEL, SPI_CHANNEL);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Open file for logging
    struct stat sb;
    if (stat(FILE_NAME, &sb) == 0 && S_ISREG(sb.st_mode)) {
        file_fd = open(FILE_NAME, O_RDWR | O_CREAT, 0644);
    } else {
        file_fd = open(FILE_NAME, O_RDWR | O_CREAT, 0644);
    }
    if (file_fd < 0) {
        fprintf(stderr, "Failed to open file for logging\n");
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        // Read temperature
        uint8_t tx[] = {0x01, 0x80, 0x00};
        uint8_t rx[3];
        if (gpioSPISendReceive(spi_fd, tx, rx, 3, 0, 0) < 0) {
            fprintf(stderr, "Failed to read from SPI\n");
            continue;
        }

        // Calculate temperature
        float temperature = ((rx[1] & 0x03) << 8) | rx[2];
        temperature *= VREF / 1024.0;
        temperature /= LM35_MV_PER_C;

        // Log temperature
        buffer[index] = temperature;
        index = (index + 1) % NUM_ENTRIES;

        // Log to file
        if (file_fd >= 0) {
            lseek(file_fd, 0, SEEK_SET);
            for (int i = 0; i < NUM_ENTRIES; i++) {
                fwrite(&buffer[i], sizeof(float), 1, file_fd);
            }
        }

        // Print temperature to console
        printf("Temperature: %.2f °C\n", temperature);

        // Sleep
        usleep(5000000);
    }

    // Close SPI
    if (spi_fd >= 0) {
        gpioClose(spi_fd);
    }

    // Close file
    if (file_fd >= 0) {
        close(file_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

