#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <sys/select.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define LOG_FILE "environmental_log.txt"

// Function to read from I2C bus
int i2c_read(uint8_t reg, uint8_t *buf, int len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        close(fd);
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C register");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to write to I2C bus
int i2c_write(uint8_t reg, uint8_t *buf, int len) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        close(fd);
        return -1;
    }

    if (write(fd, buf, len) != len) {
        perror("Failed to write to I2C register");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read from SPI bus
int spi_read(uint8_t *buf, int len) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)buf,
        .rx_buf = (unsigned long)buf,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
        perror("Failed to read from SPI device");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to write to SPI bus
int spi_write(uint8_t *buf, int len) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)buf,
        .rx_buf = (unsigned long)buf,
        .len = len,
        .speed_hz = 1000000,
        .bits_per_word = 8
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
        perror("Failed to write to SPI device");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read ADC value
int read_adc() {
    uint8_t buf[2];
    if (spi_read(buf, 2) < 0) {
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to read light level
int read_light() {
    uint8_t buf[2];
    i2c_write(0x00, NULL, 0); // Reset the sensor
    usleep(100000); // Wait for 100ms
    i2c_write(0x01, NULL, 0); // Start measurement
    usleep(100000); // Wait for 100ms
    i2c_read(0x03, buf, 2); // Read the measurement
    return (buf[0] << 8) | buf[1];
}

// Function to log data
void log_data(int light, int sound) {
    time_t now;
    struct tm *lt;
    char timestamp[20];

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
    fclose(fp);
}

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    log_data(-1, -1); // Log a final entry
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        int light = read_light();
        if (light < 0) {
            perror("Failed to read light level");
            continue;
        }

        int sound = read_adc();
        if (sound < 0) {
            perror("Failed to read sound level");
            continue;
        }

        log_data(light, sound);
        sleep(1);
    }

    return 0;
}

