// Function to handle signal to clean up GPIO resources
void cleanup(int sig) {
    gpiod_line_release(gpiod_line_open("/dev/gpiochip0", 17, GPIOD_LINE_ACTIVE_STATE_LOW));
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    exit(0);
}

int main() {
    // Open GPIO chip
    struct gpiod_chip *chip;
    if ((chip = gpiod_chip_open("/dev/gpiochip0")) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Open GPIO line
    struct gpiod_line *line;
    if ((line = gpiod_line_open(chip, 17, GPIOD_LINE_ACTIVE_STATE_LOW)) == NULL) {
        fprintf(stderr, "Failed to open GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Set line direction to input
    if (gpiod_line_request_output(line, GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE, GPIOD_LINE_REQUEST_FLAG_ACTIVE_STATE) != 0) {
        fprintf(stderr, "Failed to set line direction to input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set line to pull-down
    if (gpiod_line_set_pull(line, GPIOD_LINE_PULL_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("flame_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for cleanup
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read line value
        int value;
        if (gpiod_line_get_value(line, &value) != 0) {
            fprintf(stderr, "Failed to read line value\n");
            fclose(log_file);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Log event
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,17,%d\n", timestamp, value);

        // Check for flame detection
        if (value == 1) {
            printf("Flame detected!\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    return 0;
}

