#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define LOG_FILE "temperature_log.txt"
#define ADC_CHANNEL 0
#define DAC_ADDRESS 0x62
#define DAC_BUS 1
#define DAC_CHANNEL 0
#define DAC_MAX_VOLTAGE 3.3
#define DAC_MIN_VOLTAGE 0.0
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0
#define TEMPERATURE_MIN_C 0.0
#define TEMPERATURE_MAX_C 50.0
#define SAMPLING_INTERVAL 0.5

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open SPI bus
    int spi_fd = gpioOpen(0, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode and frequency
    if (gpioSetMode(spi_fd, SPI_MODE_0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetClockSpeed(spi_fd, 500000) < 0) {
        fprintf(stderr, "Failed to set SPI frequency\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(1, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(spi_fd);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize DAC
    if (i2cWriteReg(i2c_fd, DAC_ADDRESS, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to initialize DAC\n");
        fclose(log_file);
        gpioClose(spi_fd);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value;
        if (spiXfer(spi_fd, &adc_value, 2, 0, 0) < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue;
        }

        // Convert ADC value to temperature
        float temperature_c = (adc_value * (TEMPERATURE_MAX_C - TEMPERATURE_MIN_C) / (float)(ADC_MAX_VALUE - ADC_MIN_VALUE)) + TEMPERATURE_MIN_C;

        // Convert temperature to DAC voltage
        float dac_voltage = (temperature_c - TEMPERATURE_MIN_C) / (TEMPERATURE_MAX_C - TEMPERATURE_MIN_C) * (DAC_MAX_VOLTAGE - DAC_MIN_VOLTAGE) + DAC_MIN_VOLTAGE;

        // Write DAC value
        if (i2cWriteReg(i2c_fd, DAC_ADDRESS, 0x00, (uint8_t)(dac_voltage * 256)) < 0) {
            fprintf(stderr, "Failed to write DAC value\n");
            continue;
        }

        // Log reading
        time_t now = time(NULL);
        struct tm *now_tm = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
        fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature_c, dac_voltage);
        fprintf(stdout, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature_c, dac_voltage);

        // Sleep
        usleep((uint32_t)(SAMPLING_INTERVAL * 1000000));
    }

    // Clean up
    fclose(log_file);
    gpioClose(spi_fd);
    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Clean up
    fclose(log_file);
    gpioClose(spi_fd);
    gpioClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

// Set up signal handler for SIGINT
void setup_sigint_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(1);
    }
}

