#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define ADC_CHANNELS 3
#define ADC_CHANNEL_0 0
#define ADC_CHANNEL_1 1
#define ADC_CHANNEL_2 2
#define ADC_CS 17
#define ADC_CLK 23
#define ADC_MOSI 24
#define ADC_MISO 25

#define ADC_MAX_VALUE 1023
#define MOISTURE_MIN 0.0
#define MOISTURE_MAX 100.0

#define LOG_FILE "soil_data.txt"

int main() {
    int adc_fd;
    int gpio_fd;
    int moisture[ADC_CHANNELS];
    char timestamp[20];
    time_t now;
    struct tm *lt;
    FILE *log_file;

    // Initialize pigpio
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_fd);
        return 1;
    }

    // Set up SPI
    if ((adc_fd = spiOpen(ADC_CS, 0, 1000000)) < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Set up GPIO for chip select
    if (gpioSetMode(ADC_CS, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO for chip select: %d\n", gpioGetError());
        spiClose(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    while (1) {
        // Read timestamp
        time(&now);
        lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Read ADC values
        for (int i = 0; i < ADC_CHANNELS; i++) {
            // Set chip select low
            gpioWrite(ADC_CS, 0);

            // Read ADC value
            uint16_t adc_value;
            if (spiXfer(adc_fd, 0, &adc_value, 2) < 0) {
                fprintf(stderr, "Failed to read ADC value: %d\n", adc_fd);
                spiClose(adc_fd);
                gpioTerminate(gpio_fd);
                fclose(log_file);
                return 1;
            }

            // Set chip select high
            gpioWrite(ADC_CS, 1);

            // Check for invalid ADC value
            if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                continue;
            }

            // Convert ADC value to moisture percentage
            moisture[i] = (1.0 - (adc_value / (float)ADC_MAX_VALUE)) * 100.0;
        }

        // Log moisture readings
        for (int i = 0; i < ADC_CHANNELS; i++) {
            fprintf(log_file, "%s, Channel %d: %.2f%%\n", timestamp, i, moisture[i]);
        }

        // Sleep for 60 seconds
        gpioDelay(6000000000);
    }

    // Close SPI
    spiClose(adc_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate(gpio_fd);

    return 0;
}

