        return 1;
    }

    // Open log file
    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(adc_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    while (1) {
        // Read timestamp
        time(&now);
        lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

        // Read ADC values
        for (int i = 0; i < ADC_CHANNELS; i++) {
            // Set chip select low
            gpioWrite(ADC_CS, 0);

            // Read ADC value
            uint16_t adc_value;
            if (spiXfer(adc_fd, 0, &adc_value, 2) < 0) {
                fprintf(stderr, "Failed to read ADC value: %d\n", adc_fd);
                spiClose(adc_fd);
                gpioTerminate(gpio_fd);
                fclose(log_file);
                return 1;
            }

            // Set chip select high
            gpioWrite(ADC_CS, 1);

            // Check for invalid ADC value
            if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
                continue;
            }

            // Convert ADC value to moisture percentage
            moisture[i] = (1.0 - (adc_value / (float)ADC_MAX_VALUE)) * 100.0;
        }

        // Log moisture readings
        for (int i = 0; i < ADC_CHANNELS; i++) {
            fprintf(log_file, "%s, Channel %d: %.2f%%\n", timestamp, i, moisture[i]);
        }

        // Sleep for 60 seconds
        gpioDelay(6000000000);
    }

    // Close SPI
    spiClose(adc_fd);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate(gpio_fd);

    return 0;
}
