    }

    // Release all GPIO lines
    for (int i = 0; i < 4; i++) {
        gpiod_line_release(relay_lines[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(gpiod_chip);

    // Exit the program
    exit(0);
}

int main() {
    // Define the GPIO chip and lines
    const char *chip_name = "/dev/gpiochip0";
    const char *relay_pins[] = {"17", "22", "23", "24"};
    int relay_lines[4];

    // Open the GPIO chip
    gpiod_chip = gpiod_chip_open(chip_name);
    if (gpiod_chip == NULL) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Request the GPIO lines as output
    for (int i = 0; i < 4; i++) {
        relay_lines[i] = gpiod_line_request_output(gpiod_chip, relay_pins[i], "active-high");
        if (relay_lines[i] < 0) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(gpiod_chip);
            return 1;
        }
    }

    // Set all relay pins inactive (LOW)
    for (int i = 0; i < 4; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }

    // Install signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        gpiod_chip_close(gpiod_chip);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install signal handler");
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate each relay in sequence for 1 second
        for (int i = 0; i < 4; i++) {
            gpiod_line_set_value(relay_lines[i], 1);
            sleep(1);
            gpiod_line_set_value(relay_lines[i], 0);
            sleep(1);
        }

        // Delay 1 second between relays
        sleep(1);
    }

    return 0;
}

