#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define LED_PIN 16
#define DEBOUNCE_DELAY 500
#define ADC_THRESHOLD 500
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_SPI_CS 8

static volatile bool running = true;
static bool led_on = false;

void signal_handler(int sig) {
    running = false;
}

void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen("sound_events.log", "a");
    if (file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(file, "%s: %s\n", timestamp, message);
    fclose(file);
}

int main() {
    int spi_fd = spiOpen("/dev/spidev0.0", ADC_SPI_MODE, ADC_SPI_SPEED);
    if (spi_fd < 0) {
        perror("spiOpen");
        exit(EXIT_FAILURE);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        spiClose(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ADC_SPI_CS, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        spiClose(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        spiClose(spi_fd);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value;
        int ret = spiXfer(spi_fd, 0, 1, ADC_CHANNEL, 1, 0);
        if (ret < 0) {
            perror("spiXfer");
            gpioTerminate();
            spiClose(spi_fd);
            exit(EXIT_FAILURE);
        }

        adc_value = (ret >> 8) & 0xFF;

        if (adc_value > ADC_THRESHOLD && !led_on) {
            log_event("Sound detected");
            led_on = true;
            gpioWrite(LED_PIN, 1);
            usleep(DEBOUNCE_DELAY * 1000);
        } else if (adc_value <= ADC_THRESHOLD && led_on) {
            led_on = false;
            gpioWrite(LED_PIN, 0);
        }

        usleep(10 * 1000);
    }

    gpioTerminate();
    spiClose(spi_fd);
    return 0;
}

