// Define the GPIO pin numbers
#define RAIN_SENSOR_CHANNEL 0
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27
#define RAIN_THRESHOLD 5

// Define the SPI settings
#define SPI_SPEED 1000000
#define SPI_MODE 0

// Define the ADC channel
#define ADC_CHANNEL 0

// Define the PWM settings
#define PWM_RANGE 255
#define PWM_DUTY 150

// Define the log file
#define LOG_FILE "rain_log.txt"

// Define the volatile sig_atomic_t flag for graceful shutdown
volatile sig_atomic_t shutdown = 0;

// Define the signal handlers
void sigint_handler(int sig) {
    shutdown = 1;
}

void sigterm_handler(int sig) {
    shutdown = 1;
}

// Function to read the rain sensor value
int read_rain_sensor() {
    int tx[] = {0x01, (0x08 | RAIN_SENSOR_CHANNEL) << 4, 0x00};
    int rx[3];
    int result = 0;

    // Check if SPI is open
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }

    // Open SPI
    if (gpioOpen(0, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Transfer data to the ADC
    if (gpioSPIDataU8(0, tx, rx, 3) < 0) {
        fprintf(stderr, "Failed to transfer data to ADC: %s\n", strerror(errno));
        gpioClose(0);
        gpioTerminate();
        return -1;
    }

    // Parse the result
    result = (rx[1] & 0x03) << 8 | rx[2];

    // Close SPI
    gpioClose(0);

    return result;
}

// Function to convert the ADC value to a rain level
int adc_to_rain_level(int adc_value) {
    return (1023 - adc_value) / 102.3;
}

// Function to drive the motor
void drive_motor(int direction) {
    if (direction == 1) {
        // Drive the motor forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
    } else {
        // Drive the motor in reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
    }

    // Set the PWM speed
    gpioHardwarePWM(MOTOR_ENA, PWM_DUTY, PWM_RANGE);
}

// Function to log the rain reading
void log_rain_reading(int rain_level) {
    struct timeval tv;
    gettimeofday(&tv, NULL);

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    // Write the timestamp and rain level to the log file
    fprintf(log_file, "%ld.%06d %d\n", tv.tv_sec, tv.tv_usec, rain_level);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    // Initialize the GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGTERM handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the motor
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);

    // Initialize the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!shutdown) {
        // Read the rain sensor value
        int rain_level = read_rain_sensor();
        if (rain_level < 0) {
            break;
        }

        // Log the rain reading
        log_rain_reading(rain_level);

        // Check if the rain level is above the threshold
        if (rain_level >= RAIN_THRESHOLD) {
            // Close the window
            drive_motor(1);
            sleep(3);
        } else {
            // Open the window
            drive_motor(-1);
            sleep(3);
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Clean up
    gpioTerminate();
    fclose(log_file);
    return 0;
}

