#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <syslog.h>
#include <libgpiod.h>
#include <linux/spi/spidev.h>

#define GPIO_PUMP 17
#define ADC_CHANNEL 0
#define DRY_ADC 800
#define WET_ADC 300
#define THRESHOLD 30
#define LOG_FILE "soil_moisture.log"
#define LOG_INTERVAL 60

int log_file = -1;
gpiod_line *pump_line = NULL;
int spi_fd = -1;

void log_moisture(int moisture, bool pump_on) {
    char timestamp[20];
    time_t now;
    struct tm *lt;
    char buffer[256];

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

    sprintf(buffer, "%s,%.2f,%.d\n", timestamp, (double)moisture / 1024.0 * 100.0, pump_on);

    if (log_file != -1) {
        if (write(log_file, buffer, strlen(buffer)) != strlen(buffer)) {
            syslog(LOG_ERR, "Failed to write to log file");
        }
    }
}

void pump_on() {
    if (gpiod_line_request_output(pump_line, GPIOD_LINE_ACTIVE_HIGH) != 0) {
        syslog(LOG_ERR, "Failed to set pump line as output");
        exit(1);
    }
    if (gpiod_line_set_value(pump_line, 1) != 0) {
        syslog(LOG_ERR, "Failed to turn on pump");
        exit(1);
    }
}

void pump_off() {
    if (gpiod_line_set_value(pump_line, 0) != 0) {
        syslog(LOG_ERR, "Failed to turn off pump");
        exit(1);
    }
}

void init_spi() {
    struct spi_ioc_transfer xfer[] = {
        {
            .tx_buf = (unsigned long)0,
            .rx_buf = (unsigned long)0,
            .len = 2,
            .cs_change = 1,
            .delay_usecs = 0,
            .bits_per_word = 8,
            .speed_hz = 1000000,
            .mode = SPI_MODE_0,
        }
    };

    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, 0) != 0) {
        syslog(LOG_ERR, "Failed to set SPI mode");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, 8) != 0) {
        syslog(LOG_ERR, "Failed to set SPI bits per word");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, 1000000) != 0) {
        syslog(LOG_ERR, "Failed to set SPI speed");
        exit(1);
    }

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) != 1) {
        syslog(LOG_ERR, "Failed to send SPI message");
        exit(1);
    }
}

void init_gpio() {
    pump_line = gpiod_line_request("gpiochip0", GPIO_PUMP, GPIOD_LINE_REQUEST_OUTPUT);
    if (pump_line == NULL) {
        syslog(LOG_ERR, "Failed to request pump line");
        exit(1);
    }
}

void init_log() {
    log_file = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_file < 0) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }
}

void cleanup() {
    if (log_file != -1) {
        close(log_file);
        log_file = -1;
    }

    if (pump_line != NULL) {
        gpiod_line_release(pump_line);
        pump_line = NULL;
    }

    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main() {
    int moisture = 0;
    bool pump_on = false;

    openlog("soil_moisture", LOG_PID, LOG_USER);

    init_gpio();
    init_spi();
    init_log();

    while (1) {
        struct spi_ioc_transfer xfer = {
            .tx_buf = (unsigned long)0,
            .rx_buf = (unsigned long)moisture,
            .len = 2,
            .cs_change = 1,
            .delay_usecs = 0,
            .bits_per_word = 8,
            .speed_hz = 1000000,
            .mode = SPI_MODE_0,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer) != 1) {
            syslog(LOG_ERR, "Failed to send SPI message");
            break;
        }

        moisture = (moisture >> 8) | ((moisture & 0xFF) << 8);
        if (moisture < DRY_ADC || moisture > WET_ADC) {
            syslog(LOG_ERR, "Invalid ADC value: %d", moisture);
            break;
        }

        int percentage = (moisture - WET_ADC) * 100 / (DRY_ADC - WET_ADC);
        if (percentage < THRESHOLD && !pump_on) {
            pump_on = true;
            pump_on();
        } else if (percentage >= THRESHOLD && pump_on) {
            pump_on = false;
            pump_off();
        }

        log_moisture(percentage, pump_on);

        sleep(LOG_INTERVAL);
    }

    cleanup();
    closelog();

    return 0;
}

