#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define ADC_CHANNEL 0
#define ADC_VCC 3.3
#define ADC_MAX 1023
#define SENSITIVITY_MV_PER_MT 1.65
#define THRESHOLD_MT 10.0
#define LED_PIN 21
#define LOG_FILE "magnetic_log.txt"

// Function to handle SIGINT
void sigint_handler(int sig) {
    // Close SPI
    if (gpio_spi_close(0) != 0) {
        fprintf(stderr, "Error closing SPI: %s\n", strerror(errno));
    }

    // Turn off LED
    if (gpio_write(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error turning off LED: %s\n", strerror(errno));
    }

    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open SPI
    if (gpio_spi_open(0, 1000000) != 0) {
        fprintf(stderr, "Error opening SPI: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up SPI mode
    if (gpio_spi_set_mode(0, 0, 0, 0) != 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        gpio_spi_close(0);
        gpioTerminate();
        return 1;
    }

    // Set up LED pin as output
    if (gpio_set_mode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin mode: %s\n", strerror(errno));
        gpio_spi_close(0);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpio_spi_close(0);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint16_t adc_value;
        if (gpio_spi_xfer(0, 0, &adc_value, 2, 0) != 0) {
            fprintf(stderr, "Error reading ADC value: %s\n", strerror(errno));
            fclose(log_file);
            gpio_spi_close(0);
            gpioTerminate();
            return 1;
        }

        // Convert ADC value to voltage
        float voltage = (float)adc_value * ADC_VCC / ADC_MAX;

        // Calculate magnetic field strength
        float field_mt = (voltage - ADC_VCC / 2) * 1000 / SENSITIVITY_MV_PER_MT;

        // Log reading
        fprintf(log_file, "%f %f\n", time(NULL), field_mt);

        // Turn on LED if field exceeds threshold
        if (field_mt > THRESHOLD_MT) {
            if (gpio_write(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error turning on LED: %s\n", strerror(errno));
            }
        } else {
            if (gpio_write(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error turning off LED: %s\n", strerror(errno));
            }
        }

        // Delay
        usleep(100000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    if (gpio_spi_close(0) != 0) {
        fprintf(stderr, "Error closing SPI: %s\n", strerror(errno));
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

