#include <signal.h>
#include <pigpio.h>

#define ADC_CHANNEL 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define ADC_VALUE_FILE "moisture_log.txt"

void sigint_handler(int sig) {
    // Handle SIGINT (Ctrl+C) by closing SPI and terminating pigpio
    gpio_spi_close(SPI_CHANNEL);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI channel 0
    if (gpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Open file for logging
    FILE *file = fopen(ADC_VALUE_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file %s for logging\n", ADC_VALUE_FILE);
        gpio_spi_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        uint8_t tx_buf[2] = {0x01, 0x80 | (ADC_CHANNEL << 4)};
        uint8_t rx_buf[3];
        int result = gpio_spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3);
        if (result < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            fprintf(file, "%s: Error reading ADC value\n", ctime(&time(NULL)));
            fclose(file);
            gpio_spi_close(SPI_CHANNEL);
            gpioTerminate();
            return 1;
        }

        // Parse 10-bit result
        uint16_t adc_value = (rx_buf[1] >> 1) | (rx_buf[2] << 7);

        // Log reading
        fprintf(file, "%s: %d\n", ctime(&time(NULL)), adc_value);
        fflush(file);

        // Sleep for 60 seconds
        sleep(60);
    }

    // Clean up
    fclose(file);
    gpio_spi_close(SPI_CHANNEL);
    gpioTerminate();
    return 0;
}

