#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>
#include <linux/spi/spidev.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "line17"
#define SPI_DEVICE "/dev/spidev0.0"
#define ADC_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define LOG_INTERVAL 1000  // milliseconds

// Function to handle signal termination
void sig_handler(int sig) {
    gpiod_line_release(gpiod_chip_open(GPIO_CHIP_NAME), GPIO_LINE_NAME);
    close(spi_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s'\n", GPIO_CHIP_NAME);
        return 1;
    }

    struct gpiod_line *line;
    line = gpiod_chip_get_line(chip, GPIO_LINE_NAME);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line '%s'\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line '%s' as output\n", GPIO_LINE_NAME);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device '%s'\n", SPI_DEVICE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = NULL,
        .rx_buf = NULL,
        .len = 1,
        .speed_hz = 1000000,
        .bits_per_word = 8,
        .cs_change = 1,
        .delay_usecs = 0,
        .cs_high = 1,
        .cs_low = 1,
        .delay_usecs = 0
    };

    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        fclose(log_file);
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO line high to enable ADC
        gpiod_line_set_value(line, 1);

        // Read from ADC
        transfer.tx_buf = NULL;
        transfer.rx_buf = (uint8_t *)malloc(2);
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            fprintf(stderr, "Failed to read from ADC\n");
            free(transfer.rx_buf);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            close(spi_fd);
            return 1;
        }

        // Calculate current from ADC reading
        uint16_t adc_value = (transfer.rx_buf[0] << 8) | transfer.rx_buf[1];
        float current_A = (adc_value * 5.0 / 1024.0) / 0.1;  // 0-5V range, 100mV/A sensitivity

        // Log current reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%f\n", timestamp, current_A);

        // Set GPIO line low to disable ADC
        gpiod_line_set_value(line, 0);

        // Sleep for LOG_INTERVAL milliseconds
        usleep(LOG_INTERVAL * 1000);
    }

    return 0;
}

