#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Flag to indicate whether to exit the program cleanly
volatile int exit_cleanly = 0;

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    exit_cleanly = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0 (ce=0) at 1 MHz, mode 0
    int spi_fd = spiOpen(0, 1, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI0\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("current_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Set up timestamp
    struct tm *timestamp;
    time_t rawtime;
    time(&rawtime);
    timestamp = localtime(&rawtime);

    // Main loop
    while (!exit_cleanly) {
        // Read MCP3008 channel 0
        unsigned char tx[] = {0x01, 0x80 | (0 << 4), 0x00};
        unsigned char rx[3];
        if (spiXfer(spi_fd, tx, rx, 3, 0) != 3) {
            fprintf(stderr, "SPI transfer error\n");
            continue;
        }

        // Compute 10-bit result
        int raw_code = ((rx[1] & 0x03) << 8) | rx[2];

        // Convert raw code to voltage
        double voltage = (double)raw_code / 1023.0 * 5.0;

        // Check if voltage is within valid range
        if (voltage < 0 || voltage > 5.0) {
            fprintf(stderr, "Voltage out of range: %f\n", voltage);
            continue;
        }

        // Convert voltage to current
        double current = (voltage - 2.5) * (50.0 / 2.5);

        // Append timestamped line to log file
        char buffer[20];
        strftime(buffer, 20, "%Y-%m-%d %H:%M:%S", timestamp);
        fprintf(log_file, "%s %.2f A\n", buffer, current);
        fflush(log_file);

        // Delay for 100 ms
        gpioDelay(100000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI
    spiClose(spi_fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

