    struct gpiod_chip *chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request GPIO lines as inputs
    struct gpiod_line *line1 = gpiod_chip_get_line(chip, gpio1);
    if (!line1) {
        fprintf(stderr, "Failed to get GPIO line %d\n", gpio1);
        gpiod_chip_close(chip);
        return 1;
    }

    struct gpiod_line *line2 = gpiod_chip_get_line(chip, gpio2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d\n", gpio2);
        gpiod_line_release(line1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the lines as inputs
    if (gpiod_line_request_input(line1, GPIOD_LINE_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input\n", gpio1);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(line2, GPIOD_LINE_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input\n", gpio2);
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = 0;
        int sensor2_state = 0;
        for (int i = 0; i < 5; i++) {
            int value1 = gpiod_line_get_value(line1);
            int value2 = gpiod_line_get_value(line2);
            if (value1 == 0) {
                sensor1_state++;
            }
            if (value2 == 0) {
                sensor2_state++;
            }
            usleep(2000);
        }
        if (sensor1_state > 2) {
            sensor1_state = 0;
        } else {
            sensor1_state = 1;
        }
        if (sensor2_state > 2) {
            sensor2_state = 0;
        } else {
            sensor2_state = 1;
        }

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("Object present on both sensors\n");
        } else if (sensor1_state == 0) {
            printf("Object present on sensor 1\n");
        } else if (sensor2_state == 0) {
            printf("Object present on sensor 2\n");
        } else {
            printf("No object present on both sensors\n");
        }

        sleep(1);
    }

    // Release GPIO resources
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}

