    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpiod_line_release(line1);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = 0;
        int sensor2_state = 0;
        for (int i = 0; i < 5; i++) {
            int value1 = gpiod_line_get_value(line1);
            int value2 = gpiod_line_get_value(line2);
            if (value1 == 0) {
                sensor1_state++;
            }
            if (value2 == 0) {
                sensor2_state++;
            }
            usleep(2000);
        }
        if (sensor1_state > 2) {
            sensor1_state = 0;
        } else {
            sensor1_state = 1;
        }
        if (sensor2_state > 2) {
            sensor2_state = 0;
        } else {
            sensor2_state = 1;
        }

        if (sensor1_state == 0 && sensor2_state == 0) {
            printf("Object present on both sensors\n");
        } else if (sensor1_state == 0) {
            printf("Object present on sensor 1\n");
        } else if (sensor2_state == 0) {
            printf("Object present on sensor 2\n");
        } else {
            printf("No object present on both sensors\n");
        }

        sleep(1);
    }

    // Release GPIO resources
    gpiod_line_release(line1);
    gpiod_line_release(line2);
    gpiod_chip_close(chip);

    return 0;
}
```

This code uses the libgpiod library to interface with the GPIO pins on the Raspberry Pi 5. It sets up two GPIO lines as inputs, requests them as active-low inputs, and then enters a loop where it samples each line 5 times with a 2ms delay between samples. It then determines the state of each sensor (0 = object present, 1 = no object) by counting the number of times the line is low. If both sensors report object present simultaneously, it prints a warning message. The code also sets up a signal handler for SIGINT to release all GPIO resources and exit cleanly.

