#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t terminate = 0;

void signal_handler(int signal) {
    terminate = 1;
}

int read_mcp3008(int channel) {
    int ret;
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3];

    while ((ret = spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3, SPI_BAUD)) != 0) {
        if (ret == EIO) {
            printf("SPI transfer failed, retrying...\n");
            usleep(100000);
        } else {
            printf("SPI transfer failed with error %d\n", ret);
            return -1;
        }
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

double calculate_moisture_level(int adc_value) {
    return 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
}

void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        printf("Failed to open log file for writing\n");
        return;
    }

    fprintf(file, "%s,%f\n", buffer, moisture_level);
    fclose(file);
}

void spi_setup(spi_config_t config) {
    if (spiOpen(config.gpioCE, config.speed, config.mode) < 0) {
        printf("Failed to open SPI channel\n");
        exit(1);
    }
}

int main() {
    spi_config_t config = {
        .gpioCE = 8,  // CE0
        .speed = SPI_BAUD,
        .mode = SPI_MODE_0
    };

    if (pigpio_initialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    spi_setup(config);

    signal(SIGINT, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        moisture_level = fmax(0.0, fmin(moisture_level, 100.0));

        log_data(moisture_level);
        printf("Moisture level: %f%%\n", moisture_level);

        usleep(READ_DELAY * 1000000);
    }

    if (spiClose(SPI_CHANNEL) < 0) {
        printf("Failed to close SPI channel\n");
    }

    pigpio_cleanup();
    return 0;
}

