#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <pigpio.h>
#include <libcamera-still.h>

#define PIR_PIN 17
#define CAPTURE_DIR "/home/pi/security_cam/"
#define CAPTURE_FORMAT "jpg"
#define CAPTURE_SIZE "1280x720"
#define CAPTURE_ISO "100"
#define CAPTURE_DELAY 200
#define POLL_DELAY 50

int log_syslog(int priority, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(priority, fmt, args);
    va_end(args);
    return 0;
}

void sigint_handler(int sig) {
    log_syslog(LOG_INFO, "Received signal %d, shutting down...\n", sig);
    gpioTerminate();
    syslog(LOG_INFO, "Released pigpio resources\n");
    closelog();
    exit(0);
}

int main() {
    int gpio_fd;
    int motion_detected = 0;
    int last_state = 0;
    char filename[256];
    struct stat sb;

    // Initialize pigpio
    if ((gpio_fd = gpioInitialise()) < 0) {
        log_syslog(LOG_ERR, "Failed to initialize pigpio: %s\n", gpio_strerror(gpioError()));
        return 1;
    }

    // Configure GPIO17 as input with a pull-down resistor
    if (gpioSetMode(gpio_fd, PIR_PIN, PI_INPUT) < 0) {
        log_syslog(LOG_ERR, "Failed to set GPIO mode: %s\n", gpio_strerror(gpioError()));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(gpio_fd, PIR_PIN, PI_PUD_DOWN) < 0) {
        log_syslog(LOG_ERR, "Failed to set pull-up/down control: %s\n", gpio_strerror(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Open syslog
    openlog("security_cam", LOG_PID | LOG_PERROR, LOG_INFO);

    log_syslog(LOG_INFO, "Started security camera\n");

    while (1) {
        // Poll GPIO17 every 50 ms
        int state = gpioRead(gpio_fd, PIR_PIN);
        if (state != last_state) {
            log_syslog(LOG_INFO, "Motion detected\n");
            motion_detected = 1;
            last_state = state;
        }

        if (motion_detected) {
            // Apply a 200 ms debounce delay
            usleep(CAPTURE_DELAY * 1000);
            motion_detected = 0;
            last_state = gpioRead(gpio_fd, PIR_PIN);

            // Construct the output path
            strftime(filename, sizeof(filename), "/home/pi/security_cam/%Y%m%d_%H%M%S_%f.%s.jpg", localtime(&time(NULL)));
            if (stat(CAPTURE_DIR, &sb) != 0) {
                if (mkdir(CAPTURE_DIR, 0755) != 0) {
                    log_syslog(LOG_ERR, "Failed to create capture directory: %s\n", strerror(errno));
                    continue;
                }
            }

            // Capture a 1280x720 JPEG image
            char *argv[] = {"libcamera-still", "-t", CAPTURE_SIZE, "-o", filename, "--format", CAPTURE_FORMAT, "--iso", CAPTURE_ISO, NULL};
            pid_t pid = fork();
            if (pid == 0) {
                // Child process
                if (execvp("libcamera-still", argv) != 0) {
                    log_syslog(LOG_ERR, "Failed to execute libcamera-still: %s\n", strerror(errno));
                    exit(1);
                }
            } else if (pid > 0) {
                // Parent process
                int status;
                waitpid(pid, &status, 0);
                if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
                    log_syslog(LOG_ERR, "Failed to capture image: %d\n", WEXITSTATUS(status));
                } else {
                    log_syslog(LOG_INFO, "Captured image: %s\n", filename);
                }
            } else {
                log_syslog(LOG_ERR, "Failed to fork: %s\n", strerror(errno));
            }
        }

        // Sleep for 50 ms
        usleep(POLL_DELAY * 1000);
    }

    return 0;
}

