#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <libcamera/v4l2.h>

#define WIDTH 640
#define HEIGHT 480
#define FRAMES 1000

static volatile int running = 1;
static int fd;
static void *buf;
static struct v4l2_format fmt;
static struct v4l2_requestbuffers req;
static struct v4l2_buffer buf_info;

static void sigint_handler(int sig) {
    running = 0;
}

int main(int argc, char **argv) {
    char filename[256];
    int i;
    struct v4l2_capability cap;
    struct v4l2_mbus_format mbus_fmt;
    struct v4l2_streamparm parm;
    struct v4l2_event event;
    struct v4l2_event_subscription sub;
    fd_set rset;
    struct timeval tv;

    // Set up signal handling
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the V4L2 device
    if ((fd = open(argv[1], O_RDWR)) < 0) {
        perror("open");
        return 1;
    }

    // Get device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    // Set format to 640x480, 8-bit grayscale
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return 1;
    }

    // Get the MBUS format
    memset(&mbus_fmt, 0, sizeof(mbus_fmt));
    mbus_fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    mbus_fmt.fmt.pix.width = WIDTH;
    mbus_fmt.fmt.pix.height = HEIGHT;
    mbus_fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    mbus_fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_G_MBUS_FMT, &mbus_fmt) < 0) {
        perror("VIDIOC_G_MBUS_FMT");
        close(fd);
        return 1;
    }

    // Request a single buffer
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(fd);
        return 1;
    }

    // Map the buffer
    buf = mmap(NULL, req.count * req.num_buffers * mbus_fmt.fmt.pix.bytesperline * mbus_fmt.fmt.pix.height, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buf == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return 1;
    }

    // Set up streaming
    memset(&parm, 0, sizeof(parm));
    parm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    parm.streamparm.capture.timeperframe.numerator = 1;
    parm.streamparm.capture.timeperframe.denominator = 30;
    if (ioctl(fd, VIDIOC_S_PARM, &parm) < 0) {
        perror("VIDIOC_S_PARM");
        munmap(buf, req.count * req.num_buffers * mbus_fmt.fmt.pix.bytesperline * mbus_fmt.fmt.pix.height);
        close(fd);
        return 1;
    }

    // Subscribe to events
    memset(&sub, 0, sizeof(sub));
    sub.type = V4L2_EVENT_TYPE_VIDEO_CAPTURE;
    sub.id = V4L2_EVENT_ID_SOURCE_CHANGE;
    if (ioctl(fd, VIDIOC_SUBSCRIBE_EVENT, &sub) < 0) {
        perror("VIDIOC_SUBSCRIBE_EVENT");
        munmap(buf, req.count * req.num_buffers * mbus_fmt.fmt.pix.bytesperline * mbus_fmt.fmt.pix.height);
        close(fd);
        return 1;
    }

    // Open the output file
    for (i = 0; running && i < FRAMES; i++) {
        // Dequeue a buffer
        FD_ZERO(&rset);
        FD_SET(fd, &rset);
        tv.tv_sec = 2;
        tv.tv_usec = 0;
        if (select(fd + 1, &rset, NULL, NULL, &tv) < 0) {
            if (errno != EAGAIN) {
                perror("select");
                break;
            }
            continue;
        }
        if (!FD_ISSET(fd, &rset)) {
            continue;
        }

        // Get the buffer info
        if (ioctl(fd, VIDIOC_DQBUF, &buf_info) < 0) {
            perror("VIDIOC_DQBUF");
            break;
        }

        // Write the frame to a file
        sprintf(filename, "image_%04d.pgm", i);
        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            perror("fopen");
            break;
        }
        fwrite(buf + buf_info.m.offset, 1, buf_info.length, fp);
        fclose(fp);

        // Queue the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buf_info) < 0) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    // Unsubscribe from events
    if (ioctl(fd, VIDIOC_UNSUBSCRIBE_EVENT, &sub) < 0) {
        perror("VIDIOC_UNSUBSCRIBE_EVENT");
    }

    // Release resources
    munmap(buf, req.count * req.num_buffers * mbus_fmt.fmt.pix.bytesperline * mbus_fmt.fmt.pix.height);
    close(fd);
    return 0;
}

