#define FRAMES 2
#define LOG_FILE "frame_log.txt"

struct v4l2_format v4l2_format = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .fmt = VIDEO_FORMAT,
    .fmt.pix = {
