        .height = VIDEO_HEIGHT,
        .pixelformat = VIDEO_FORMAT,
        .field = V4L2_FIELD_NONE,
        .bytesperline = VIDEO_WIDTH * 2,
        .sizeimage = FRAMESIZE,
        .colorspace = V4L2_COLORSPACE_JPEG,
        .priv = 0,
        .flags = 0,
        .reserved = {0}
    }
};

struct v4l2_requestbuffers v4l2_reqbufs = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
    .count = FRAMES,
    .length = sizeof(struct v4l2_buffer)
};

struct v4l2_buffer v4l2_buf = {
    .type = V4L2_BUF_TYPE_VIDEO_CAPTURE,
    .memory = V4L2_MEMORY_MMAP,
    .index = 0,
    .timestamp = {0, 0},
    .bytesused = 0,
    .field = V4L2_FIELD_NONE,
    .sequence = 0,
    .m = {
        .magic = 0,
        .start = 0,
        .length = 0
    }
};

void sigint_handler(int sig) {
    v4l2_close();
    exit(0);
}

int v4l2_open() {
    int fd = open(VIDEO_DEV, O_RDWR);
    if (fd < 0) {
        perror("open");
        return -1;
    }
    return fd;
}

int v4l2_ioctl(int fd, int request, void *arg) {
    int ret = ioctl(fd, request, arg);
    if (ret < 0) {
        perror("ioctl");
        return -1;
    }
    return 0;
}

int v4l2_mmap(int fd, struct v4l2_buffer *buf) {
    void *addr = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (addr == MAP_FAILED) {
        perror("mmap");
        return -1;
    }
    buf->m.userptr = addr;
    return 0;
}

