    int fd = v4l2_open();
    if (fd < 0) {
        return -1;
    }
    v4l2_ioctl(fd, VIDIOC_STREAMOFF, &v4l2_buf);
    v4l2_ioctl(fd, VIDIOC_REQBUFS, &v4l2_reqbufs);
    munmap(v4l2_buf.m.userptr, v4l2_buf.length);
    close(fd);
    return 0;
}

