    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    int fd = v4l2_open();
    if (fd < 0) {
        return 1;
    }

    if (v4l2_ioctl(fd, VIDIOC_S_FMT, &v4l2_format) < 0) {
        v4l2_close();
        return 1;
    }

    if (v4l2_ioctl(fd, VIDIOC_REQBUFS, &v4l2_reqbufs) < 0) {
        v4l2_close();
        return 1;
    }

    for (int i = 0; i < v4l2_reqbufs.count; i++) {
        v4l2_buf.index = i;
        if (v4l2_ioctl(fd, VIDIOC_QUERYBUF, &v4l2_buf) < 0) {
            v4l2_close();
            return 1;
        }
        if (v4l2_mmap(fd, &v4l2_buf) < 0) {
            v4l2_close();
            return 1;
        }
    }

    int timeout = 1000;
    fd_set rset;
    struct timeval tv;
    tv.tv_sec = 0;
    tv.tv_usec = 0;
    while (1) {
        FD_ZERO(&rset);
        FD_SET(fd, &rset);
        if (select(fd + 1, &rset, NULL, NULL, &tv) < 0) {
            perror("select");
            v4l2_close();
            return 1;
        }
        if (FD_ISSET(fd, &rset)) {
            if (v4l2_ioctl(fd, VIDIOC_DQBUF, &v4l2_buf) < 0) {
                perror("VIDIOC_DQBUF");
                v4l2_close();
                return 1;
            }
            struct timeval tv2;
            gettimeofday(&tv2, NULL);
            uint64_t timestamp = (uint64_t)tv2.tv_sec * 1000000 + tv2.tv_usec;
            FILE *f = fopen(LOG_FILE, "a");
            if (f == NULL) {
                perror("fopen");
                v4l2_close();
                return 1;
            }
            fprintf(f, "%lu.%06lu\n", (unsigned long)timestamp / 1000000, (unsigned long)timestamp % 1000000);
            fclose(f);
            if (v4l2_ioctl(fd, VIDIOC_QBUF, &v4l2_buf) < 0) {
                perror("VIDIOC_QBUF");
                v4l2_close();
                return 1;
            }
        }
    }

    return 0;
