#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <arpa/inet.h>
#include <linux/videodev2.h>

#define VIDEO_DEV "/dev/video0"
#define MAX_FRAGMENTS 4
#define MAX_DGRAM_SIZE 65000
#define FRAGMENT_HEADER_SIZE 12

struct fragment_header {
    uint32_t frame_index;
    uint32_t fragment_index;
    uint32_t total_fragments;
    uint32_t payload_size;
};

int video_fd;
struct v4l2_format format;
struct v4l2_mbuf *buffers[MAX_FRAGMENTS];
struct v4l2_buffer *bufs[MAX_FRAGMENTS];
struct fragment_header headers[MAX_FRAGMENTS];
int fragment_count = 0;
int frame_count = 0;
int socket_fd;
struct sockaddr_in server_addr;
int bytes_sent = 0;

void sigint_handler(int sig) {
    close(socket_fd);
    for (int i = 0; i < MAX_FRAGMENTS; i++) {
        munmap(buffers[i].data, buffers[i].length);
    }
    close(video_fd);
    exit(0);
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    video_fd = open(VIDEO_DEV, O_RDWR);
    if (video_fd < 0) {
        perror("Failed to open video device");
        return 1;
    }

    memset(&format, 0, sizeof(format));
    format.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    format.fmt.pix.width = 640;
    format.fmt.pix.height = 480;
    format.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    format.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(video_fd, VIDIOC_S_FMT, &format) < 0) {
        perror("Failed to set video format");
        close(video_fd);
        return 1;
    }

    for (int i = 0; i < MAX_FRAGMENTS; i++) {
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        if (ioctl(video_fd, VIDIOC_REQBUFS, &MAX_FRAGMENTS) < 0) {
            perror("Failed to request buffers");
            close(video_fd);
            return 1;
        }
        if (ioctl(video_fd, VIDIOC_QUERYBUF, &bufs[i]) < 0) {
            perror("Failed to query buffer");
            close(video_fd);
            return 1;
        }
        buffers[i].length = bufs[i].length;
        buffers[i].data = mmap(NULL, bufs[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, video_fd, bufs[i].m.offset);
        if (buffers[i].data == MAP_FAILED) {
            perror("Failed to map buffer");
            close(video_fd);
            return 1;
        }
    }

    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket");
        for (int i = 0; i < MAX_FRAGMENTS; i++) {
            munmap(buffers[i].data, buffers[i].length);
        }
        close(video_fd);
        return 1;
    }

    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, argv[1], &server_addr.sin_addr);
    server_addr.sin_port = htons(atoi(argv[2]));

    while (1) {
        if (read(video_fd, buffers[fragment_count].data, buffers[fragment_count].length) < 0) {
            perror("Failed to read from video device");
            close(socket_fd);
            for (int i = 0; i < MAX_FRAGMENTS; i++) {
                munmap(buffers[i].data, buffers[i].length);
            }
            close(video_fd);
            return 1;
        }

        headers[fragment_count].frame_index = frame_count;
        headers[fragment_count].fragment_index = fragment_count;
        headers[fragment_count].total_fragments = MAX_FRAGMENTS;
        headers[fragment_count].payload_size = buffers[fragment_count].length;

        struct sockaddr_in sender_addr;
        socklen_t sender_len = sizeof(sender_addr);
        char buffer[MAX_DGRAM_SIZE];
        memcpy(buffer, &headers[fragment_count], FRAGMENT_HEADER_SIZE);
        memcpy(buffer + FRAGMENT_HEADER_SIZE, buffers[fragment_count].data, buffers[fragment_count].length - FRAGMENT_HEADER_SIZE);
        if (sendto(socket_fd, buffer, buffers[fragment_count].length, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Failed to send to server");
            close(socket_fd);
            for (int i = 0; i < MAX_FRAGMENTS; i++) {
                munmap(buffers[i].data, buffers[i].length);
            }
            close(video_fd);
            return 1;
        }
        bytes_sent += buffers[fragment_count].length;
        fragment_count = (fragment_count + 1) % MAX_FRAGMENTS;
        frame_count++;
    }

    close(socket_fd);
    for (int i = 0; i < MAX_FRAGMENTS; i++) {
        munmap(buffers[i].data, buffers[i].length);
    }
    close(video_fd);
    return 0;
}

