int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    int i;
    FILE *fp;

    // Install SIGINT/SIGTERM handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the device in blocking mode
    if ((fd = open("/dev/video0", O_RDWR)) == -1) {
        perror("Failed to open device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    // Check if device supports capture and streaming
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) || !(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support capture and streaming\n");
        close(fd);
        return 1;
    }

    // Set format to MJPEG at 1920x1080 with V4L2_FIELD_NONE
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Failed to set format");
        close(fd);
        return 1;
    }

    // Request 4 MMAP buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Failed to request buffers");
        close(fd);
        return 1;
    }

    // Query, mmap, and queue each buffer
    for (i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.index = i;
        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Failed to query buffer");
            close(fd);
            return 1;
        }
        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("Failed to mmap buffer");
            close(fd);
            return 1;
        }
        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Failed to queue buffer");
            close(fd);
            return 1;
        }
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &fmt.type) == -1) {
        perror("Failed to start streaming");
        close(fd);
        return 1;
    }

    // Dequeue one frame
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Failed to dequeue buffer");
        close(fd);
        return 1;
    }

    // Write raw MJPEG bytes directly to disk
    fp = fopen(FILENAME, "wb");
    if (fp == NULL) {
        perror("Failed to open file");
        close(fd);
        return 1;
    }
    if (write(fp, buffers[buf.index], buf.bytesused) != buf.bytesused) {
        perror("Failed to write to file");
        fclose(fp);
        close(fd);
        return 1;
    }
    fclose(fp);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &fmt.type) == -1) {
        perror("Failed to stop streaming");
        close(fd);
        return 1;
    }

    // Unmap all buffers
    for (i = 0; i < req.count; i++) {
        if (munmap(buffers[i], buf.length) == -1) {
            perror("Failed to unmap buffer");
            close(fd);
            return 1;
        }
    }

    // Free the buffer array
    free(buffers);

    // Close the file
    fclose(fp);

    // Close the device fd
    close(fd);

    return 0;
}

