// Define the GPIO pin numbers
#define PAN_SERVO 4
#define TILT_SERVO 5
#define TILT_UP 6
#define TILT_DOWN 7
#define PAN_LEFT 8
#define PAN_RIGHT 9

// Define the servo mid-position value
#define MID_POSITION 75

// Define the servo position range
#define MIN_POSITION 25
#define MAX_POSITION 125

// Define the servo increment value
#define INCREMENT 5

// Define the PWM period and frequency
#define PWM_PERIOD 20  // 20 ms
#define PWM_FREQ 50  // 50 Hz

// Define the PWM duty cycle range
#define MIN_DUTY 50
#define MAX_DUTY 100

// Define the PWM duty cycle step
#define DUTY_STEP 1

// Define the GPIO context
struct gpiod_line *pan_servo_line = NULL;
struct gpiod_line *tilt_servo_line = NULL;
struct gpiod_line *tilt_up_line = NULL;
struct gpiod_line *tilt_down_line = NULL;
struct gpiod_line *pan_left_line = NULL;
struct gpiod_line *pan_right_line = NULL;

// Define the servo positions
int pan_position = MID_POSITION;
int tilt_position = MID_POSITION;

// Define the PWM duty cycles
int pan_duty = MID_DUTY;
int tilt_duty = MID_DUTY;

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    // Release all GPIO resources
    gpiod_line_release(pan_servo_line);
    gpiod_line_release(tilt_servo_line);
    gpiod_line_release(tilt_up_line);
    gpiod_line_release(tilt_down_line);
    gpiod_line_release(pan_left_line);
    gpiod_line_release(pan_right_line);
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    exit(0);
}

int main() {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open the pan servo line
    pan_servo_line = gpiod_chip_get_line(chip, PAN_SERVO);
    if (!pan_servo_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the tilt servo line
    tilt_servo_line = gpiod_chip_get_line(chip, TILT_SERVO);
    if (!tilt_servo_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(pan_servo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the tilt up line
    tilt_up_line = gpiod_chip_get_line(chip, TILT_UP);
    if (!tilt_up_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the tilt down line
    tilt_down_line = gpiod_chip_get_line(chip, TILT_DOWN);
    if (!tilt_down_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the pan left line
    pan_left_line = gpiod_chip_get_line(chip, PAN_LEFT);
    if (!pan_left_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_line);
        gpiod_line_release(tilt_down_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the pan right line
    pan_right_line = gpiod_chip_get_line(chip, PAN_RIGHT);
    if (!pan_right_line) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(pan_servo_line);
        gpiod_line_release(tilt_servo_line);
        gpiod_line_release(tilt_up_line);
        gpiod_line_release(tilt_down_line);
        gpiod_line_release(pan_left_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the pan servo to the mid-position
    gpiod_line_request_output(pan_servo_line, 0);
    gpiod_line_set_value(pan_servo_line, pan_duty);
    gpiod_line_request_output(tilt_servo_line, 0);
    gpiod_line_set_value(tilt_servo_line, tilt_duty);

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Poll the buttons
        int tilt_up_value = gpiod_line_get_value(tilt_up_line);
        int tilt_down_value = gpiod_line_get_value(tilt_down_line);
        int pan_left_value = gpiod_line_get_value(pan_left_line);
        int pan_right_value = gpiod_line_get_value(pan_right_line);

        // Check if the tilt up button is pressed
        if (tilt_up_value == 0) {
            // Increment the tilt position
            if (tilt_position < MAX_POSITION) {
                tilt_position += INCREMENT;
                tilt_duty = (tilt_position * MAX_DUTY) / MAX_POSITION;
                gpiod_line_set_value(tilt_servo_line, tilt_duty);
            }
        }

        // Check if the tilt down button is pressed
        if (tilt_down_value == 0) {
            // Decrement the tilt position
            if (tilt_position > MIN_POSITION) {
                tilt_position -= INCREMENT;
                tilt_duty = (tilt_position * MAX_DUTY) / MAX_POSITION;
                gpiod_line_set_value(tilt_servo_line, tilt_duty);
            }
        }

        // Check if the pan left button is pressed
        if (pan_left_value == 0) {
            // Increment the pan position
            if (pan_position < MAX_POSITION) {
                pan_position += INCREMENT;
                pan_duty = (pan_position * MAX_DUTY) / MAX_POSITION;
                gpiod_line_set_value(pan_servo_line, pan_duty);
            }
        }

        // Check if the pan right button is pressed
        if (pan_right_value == 0) {
            // Decrement the pan position
            if (pan_position > MIN_POSITION) {
                pan_position -= INCREMENT;
                pan_duty = (pan_position * MAX_DUTY) / MAX_POSITION;
                gpiod_line_set_value(pan_servo_line, pan_duty);
            }
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    return 0;
}

