#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/videodev2.h>

#define VIDEO_DEV "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_fmtdesc fmt;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control control;
    int i, j;

    // Open the device
    fd = open(VIDEO_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Failed to query device capabilities");
        close(fd);
        return 1;
    }

    printf("Device capabilities:\n");
    printf("  Driver: %s\n", cap.driver);
    printf("  Card: %s\n", cap.card);
    printf("  Bus info: %s\n", cap.bus_info);
    printf("  Version: %d.%d\n", cap.version_major, cap.version_minor);
    printf("  Capabilities: %s\n", cap.capabilities);

    // Enumerate frame sizes
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        printf("  Format: %s\n", fmt.description);
        frmsize.index = 0;
        frmsize.type = V4L2_FRMSIZE_TYPE_DISCRETE;
        while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
            printf("    Resolution: %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
            frmsize.index++;
        }
        fmt.index++;
    }
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("Failed to enumerate frame sizes");
        close(fd);
        return 1;
    }

    // Enumerate frame intervals
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.index = 0;
    while (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) == 0) {
        frmival.index = 0;
        frmival.type = V4L2_FRMIVAL_TYPE_DISCRETE;
        while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
            printf("  Format: %s\n", fmt.description);
            printf("    Interval: %d/%d\n", frmival.discrete.denominator, frmival.discrete.numerator);
            frmival.index++;
        }
        fmt.index++;
    }
    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmt) < 0) {
        perror("Failed to enumerate frame intervals");
        close(fd);
        return 1;
    }

    // Check autofocus support
    control.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &control) < 0) {
        perror("Failed to query autofocus control");
        close(fd);
        return 1;
    }
    if (control.type == V4L2_CTRL_TYPE_BOOLEAN) {
        printf("Autofocus supported: yes\n");
    } else {
        printf("Autofocus supported: no\n");
    }

    close(fd);
    return 0;
}

