        return 1;
    }
    if (gpioSetMode(LEFT_BUTTON, PI_INPUT) < 0 || gpioSetPullUpDnControl(LEFT_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure LEFT button pin\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_BUTTON, PI_INPUT) < 0 || gpioSetPullUpDnControl(RIGHT_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure RIGHT button pin\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the servos to the center position
    if (gpioServo(PAN_SERVO, CENTER_POSITION) < 0 || gpioServo(TILT_SERVO, CENTER_POSITION) < 0) {
