        int right_button_state = gpioRead(RIGHT_BUTTON);

        // Update the servo positions based on the button states
        int pan_position = CENTER_POSITION;
        int tilt_position = CENTER_POSITION;
        if (up_button_state == 0) {
            pan_position += SERVO_INCREMENT;
        }
        if (down_button_state == 0) {
            pan_position -= SERVO_INCREMENT;
        }
        if (left_button_state == 0) {
            tilt_position += SERVO_INCREMENT;
        }
        if (right_button_state == 0) {
            tilt_position -= SERVO_INCREMENT;
        }

        // Clamp the servo positions to the valid range
        pan_position = (pan_position < 1000) ? 1000 : (pan_position > 2000) ? 2000 : pan_position;
        tilt_position = (tilt_position < 1000) ? 1000 : (tilt_position > 2000) ? 2000 : tilt_position;

        // Update the servo positions
        if (gpioServo(PAN_SERVO, pan_position) < 0 || gpioServo(TILT_SERVO, tilt_position) < 0) {
            fprintf(stderr, "Failed to update servos\n");
            gpioTerminate();
            return 1;
        }

        // Delay for the specified amount of time
        usleep(LOOP_DELAY * 1000);
    }

    // Clean up on exit
    gpioTerminate();
    return 0;
}

