#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000
#define JPEG_QUALITY 85
#define CAMERA_WIDTH 640
#define CAMERA_HEIGHT 480
#define CAMERA_DIR "motion_captures"
#define CAMERA_COMMAND "libcamera-still -t 1 -x %d -y %d -q %d -o %s"

#define MAX_FILENAME_LENGTH 256

static int gpio_fd;
static int motion_detected = 0;
static time_t last_motion_time = 0;

static void sigint_handler(int sig) {
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

static void sigterm_handler(int sig) {
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

static void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(1);
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-up/down resistor: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }
}

static void capture_image(const char *filename) {
    char camera_command[256];
    struct stat sb;
    if (stat(CAMERA_DIR, &sb) == 0 && S_ISDIR(sb.st_mode)) {
        // directory exists
    } else {
        if (mkdir(CAMERA_DIR, 0755) != 0) {
            fprintf(stderr, "Failed to create directory: %s\n", strerror(errno));
            return;
        }
    }
    sprintf(camera_command, CAMERA_COMMAND, CAMERA_WIDTH, CAMERA_HEIGHT, JPEG_QUALITY, filename);
    if (system(camera_command) != 0) {
        fprintf(stderr, "Failed to capture image: %s\n", strerror(errno));
    }
}

static void send_image(const char *filename) {
    CURL *curl;
    CURLcode res;
    char json[256];
    struct tm *tm;
    time_t now;
    char timestamp[32];

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl == NULL) {
        fprintf(stderr, "Failed to initialize libcurl\n");
        return;
    }
    now = time(NULL);
    tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm);
    sprintf(json, "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":\"true\",\"gpio\":%d}", filename, timestamp, GPIO_PIN);
    curl_easy_setopt(curl, CURLOPT_URL, "http://");
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, NULL);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 5L);
    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to send image: %s\n", curl_easy_strerror(res));
    }
    curl_easy_cleanup(curl);
}

static void poll_gpio() {
    int value;
    struct timeval tv;
    gettimeofday(&tv, NULL);
    if (gpioRead(GPIO_PIN) == 1 && tv.tv_sec - last_motion_time > DEBOUNCE_TIME / 1000) {
        motion_detected = 1;
        last_motion_time = tv.tv_sec;
    }
}

int main(int argc, char **argv) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }
    char *server_ip = argv[1];
    char *server_port = argv[2];
    init_pigpio();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    while (1) {
        poll_gpio();
        if (motion_detected) {
            char filename[MAX_FILENAME_LENGTH];
            sprintf(filename, "%s/%s_%ld.jpg", CAMERA_DIR, "capture", time(NULL));
            capture_image(filename);
            send_image(filename);
            motion_detected = 0;
        }
        usleep(100000);
    }
    return 0;
}

