#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <syslog.h>
#include <libgpiod.h>
#include <libcamera-still.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIMEOUT 50
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"

// Function to generate a timestamped filename
char *generate_filename() {
    time_t now;
    struct tm *now_tm;
    char filename[32];

    time(&now);
    now_tm = localtime(&now);
    strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S", now_tm);
    strcat(filename, "_mmm.jpg");

    return strdup(filename);
}

// Function to log an event
void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s - %s\n", ctime(&time(NULL)), message);
    fclose(log_file);
}

int main() {
    // Initialize libgpiod
    gpiod_context *ctx;
    gpiod_line *line;
    int ret;

    ctx = gpiod_ctx_new();
    if (ctx == NULL) {
        syslog(LOG_ERR, "Failed to create gpiod context");
        exit(EXIT_FAILURE);
    }

    line = gpiod_ctx_get_line(ctx, "gpiochip0", GPIO_PIN);
    if (line == NULL) {
        syslog(LOG_ERR, "Failed to get GPIO line");
        gpiod_ctx_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Claim the GPIO line as input with edge-falling detection and 50 ms debounce
    ret = gpiod_line_request_input(line, GPIOD_LINE_ACTIVE_LOW, GPIOD_EDGE_FALLING, GPIOD_LINE_DEBOUNCE, DEBOUNCE_TIMEOUT);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line: %s", gpiod_error_str(ret));
        gpiod_line_release(line);
        gpiod_ctx_free(ctx);
        exit(EXIT_FAILURE);
    }

    // Initialize libcamera-still
    char *filename = generate_filename();
    char *cmd = malloc(strlen("libcamera-still -o ") + strlen(filename) + strlen(" --width 640 --height 480 -q 85 --timeout 2000 --nopreview") + 1);
    sprintf(cmd, "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);

    // Main loop
    while (1) {
        // Wait for the GPIO line to change state
        ret = gpiod_line_event_wait(line, GPIOD_LINE_EVENT_BOTH, 1000);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to wait for GPIO line event: %s", gpiod_error_str(ret));
            gpiod_line_release(line);
            gpiod_ctx_free(ctx);
            free(cmd);
            free(filename);
            exit(EXIT_FAILURE);
        }

        // Check if the line changed state
        if (gpiod_line_event_get_state(line) == GPIOD_LINE_ACTIVE_LOW) {
            // Capture an image
            ret = system(cmd);
            if (ret != 0) {
                syslog(LOG_ERR, "Failed to capture image: %s", strerror(errno));
            } else {
                syslog(LOG_INFO, "Captured image: %s", filename);
            }
        }

        // Release the GPIO line
        gpiod_line_release(line);
        gpiod_line_request_input(line, GPIOD_LINE_ACTIVE_LOW, GPIOD_EDGE_FALLING, GPIOD_LINE_DEBOUNCE, DEBOUNCE_TIMEOUT);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_ctx_free(ctx);
    free(cmd);
    free(filename);

    return 0;
}

// Signal handlers
void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT, shutting down");
    gpiod_line_release(line);
    gpiod_ctx_free(ctx);
    exit(EXIT_SUCCESS);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received SIGTERM, shutting down");
    gpiod_line_release(line);
    gpiod_ctx_free(ctx);
    exit(EXIT_SUCCESS);
}

// Register signal handlers
void setup_signal_handlers() {
    struct sigaction sa;

    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

