#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <signal.h>

#define WIDTH 640
#define HEIGHT 480
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150

static void sigint_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (fd >= 0) {
            if (munmap(buffer, buf_size) == -1) {
                perror("munmap");
                exit(EXIT_FAILURE);
            }
            if (close(fd) == -1) {
                perror("close");
                exit(EXIT_FAILURE);
            }
        }
        free(buffer);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buf_size;
    int ret;

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Open /dev/video0
    fd = open("/dev/video0", O_RDWR);
    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Verify it is a V4L2 video capture device
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        exit(EXIT_FAILURE);
    }

    // Negotiate format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        exit(EXIT_FAILURE);
    }

    // Request one buffer
    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        exit(EXIT_FAILURE);
    }

    // Get buffer information
    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
        perror("VIDIOC_QUERYBUF");
        exit(EXIT_FAILURE);
    }
    buf_size = buf.length;
    buffer = mmap(NULL, buf_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (ioctl(fd, VIDIOC_STREAMON, &buf.type) == -1) {
        perror("VIDIOC_STREAMON");
        exit(EXIT_FAILURE);
    }

    // Wait for a frame
    struct timeval tv;
    fd_set fds;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = 2;
    tv.tv_usec = 0;
    if (select(fd + 1, &fds, NULL, NULL, &tv) == -1) {
        perror("select");
        exit(EXIT_FAILURE);
    }

    // Dequeue the buffer
    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }

    // Verify the captured width, height, and pixel format
    if (buf.length != buf_size || buf.bytesused != buf_size || buf.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }
    if (buf.width != WIDTH || buf.height != HEIGHT || buf.field != V4L2_FIELD_NONE || buf.pads[0].index != 0) {
        perror("VIDIOC_DQBUF");
        exit(EXIT_FAILURE);
    }

    // Crop the region
    unsigned char *yuyv = buffer;
    unsigned char *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    for (int y = 0; y < CROP_HEIGHT; y++) {
        for (int x = 0; x < CROP_WIDTH; x++) {
            int yuyv_x = (x + CROP_X) * 2;
            int yuyv_y = (y + CROP_Y) * 2;
            cropped[y * CROP_WIDTH * 2 + x * 2] = yuyv[yuyv_y * WIDTH * 2 + yuyv_x];
            cropped[y * CROP_WIDTH * 2 + x * 2 + 1] = yuyv[yuyv_y * WIDTH * 2 + yuyv_x + 1];
        }
    }

    // Save the cropped frame
    FILE *f = fopen("cropped.yuv", "wb");
    if (f == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    if (fwrite(cropped, 1, CROP_WIDTH * CROP_HEIGHT * 2, f) != CROP_WIDTH * CROP_HEIGHT * 2) {
        perror("fwrite");
        exit(EXIT_FAILURE);
    }
    if (fclose(f) == -1) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }
    free(cropped);

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &buf.type) == -1) {
        perror("VIDIOC_STREAMOFF");
        exit(EXIT_FAILURE);
    }

    // Clean up
    if (munmap(buffer, buf_size) == -1) {
        perror("munmap");
        exit(EXIT_FAILURE);
    }
    if (close(fd) == -1) {
        perror("close");
        exit(EXIT_FAILURE);
    }
    free(buffer);

    return EXIT_SUCCESS;
}

