#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins for the servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define the neutral angle (90 degrees)
#define NEUTRAL_ANGLE 90

// Define the minimum and maximum angles (0 and 180 degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define the PWM frequency (50 Hz)
#define PWM_FREQ 50

// Define the minimum and maximum PWM pulse widths (500 and 2500 microseconds)
#define MIN_PWM 500
#define MAX_PWM 2500

// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    // Set both servos to the neutral position
    gpioServo(PAN_GPIO, NEUTRAL_ANGLE);
    gpioServo(TILT_GPIO, NEUTRAL_ANGLE);

    // Terminate pigpio cleanly
    gpioTerminate();

    // Exit with code 0
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Set up the servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);
    gpioSetPWM(PAN_GPIO, PWM_FREQ, 0);
    gpioSetPWM(TILT_GPIO, PWM_FREQ, 0);

    // Set the initial angles to neutral
    int pan_angle = NEUTRAL_ANGLE;
    int tilt_angle = NEUTRAL_ANGLE;

    // Main loop
    while (1) {
        // Read user input from stdin
        char c;
        scanf(" %c", &c);

        // Handle 'q' input to exit
        if (c == 'q') {
            // Set both servos to the neutral position
            gpioServo(PAN_GPIO, NEUTRAL_ANGLE);
            gpioServo(TILT_GPIO, NEUTRAL_ANGLE);

            // Terminate pigpio cleanly
            gpioTerminate();

            // Exit with code 0
            exit(0);
        }

        // Handle arrow key inputs
        switch (c) {
            case 'w': // up
                if (tilt_angle < MAX_ANGLE) {
                    tilt_angle += 5;
                    gpioServo(TILT_GPIO, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle is at maximum\n");
                }
                break;
            case 's': // down
                if (tilt_angle > MIN_ANGLE) {
                    tilt_angle -= 5;
                    gpioServo(TILT_GPIO, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle is at minimum\n");
                }
                break;
            case 'a': // left
                if (pan_angle > MIN_ANGLE) {
                    pan_angle -= 5;
                    gpioServo(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle is at minimum\n");
                }
                break;
            case 'd': // right
                if (pan_angle < MAX_ANGLE) {
                    pan_angle += 5;
                    gpioServo(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle is at maximum\n");
                }
                break;
        }

        // Validate PWM settings
        if (pan_angle < MIN_ANGLE || pan_angle > MAX_ANGLE) {
            fprintf(stderr, "Invalid pan angle: %d\n", pan_angle);
            pan_angle = NEUTRAL_ANGLE;
            gpioServo(PAN_GPIO, pan_angle);
        }
        if (tilt_angle < MIN_ANGLE || tilt_angle > MAX_ANGLE) {
            fprintf(stderr, "Invalid tilt angle: %d\n", tilt_angle);
            tilt_angle = NEUTRAL_ANGLE;
            gpioServo(TILT_GPIO, tilt_angle);
        }

        // Set the PWM pulse widths
        int pan_pwm = (pan_angle * (MAX_PWM - MIN_PWM) / MAX_ANGLE) + MIN_PWM;
        int tilt_pwm = (tilt_angle * (MAX_PWM - MIN_PWM) / MAX_ANGLE) + MIN_PWM;
        gpioPWM(PAN_GPIO, pan_pwm);
        gpioPWM(TILT_GPIO, tilt_pwm);

        // Delay for 100 ms
        usleep(100000);
    }

    // Terminate pigpio cleanly
    gpioTerminate();

    // Exit with code 0
    exit(0);
}

