            case 's': // down
                if (tilt_angle > MIN_ANGLE) {
                    tilt_angle -= 5;
                    gpioServo(TILT_GPIO, tilt_angle);
                } else {
                    fprintf(stderr, "Tilt angle is at minimum\n");
                }
                break;
            case 'a': // left
                if (pan_angle > MIN_ANGLE) {
                    pan_angle -= 5;
                    gpioServo(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle is at minimum\n");
                }
                break;
            case 'd': // right
                if (pan_angle < MAX_ANGLE) {
                    pan_angle += 5;
                    gpioServo(PAN_GPIO, pan_angle);
                } else {
                    fprintf(stderr, "Pan angle is at maximum\n");
                }
                break;
        }

        // Validate PWM settings
        if (pan_angle < MIN_ANGLE || pan_angle > MAX_ANGLE) {
            fprintf(stderr, "Invalid pan angle: %d\n", pan_angle);
            pan_angle = NEUTRAL_ANGLE;
            gpioServo(PAN_GPIO, pan_angle);
        }
        if (tilt_angle < MIN_ANGLE || tilt_angle > MAX_ANGLE) {
            fprintf(stderr, "Invalid tilt angle: %d\n", tilt_angle);
            tilt_angle = NEUTRAL_ANGLE;
            gpioServo(TILT_GPIO, tilt_angle);
        }

        // Set the PWM pulse widths
        int pan_pwm = (pan_angle * (MAX_PWM - MIN_PWM) / MAX_ANGLE) + MIN_PWM;
        int tilt_pwm = (tilt_angle * (MAX_PWM - MIN_PWM) / MAX_ANGLE) + MIN_PWM;
        gpioPWM(PAN_GPIO, pan_pwm);
        gpioPWM(TILT_GPIO, tilt_pwm);

        // Delay for 100 ms
        usleep(100000);
    }

    // Terminate pigpio cleanly
    gpioTerminate();

    // Exit with code 0
    exit(0);
}
```

This code uses the pigpio library to control two SG90 servo motors connected to GPIO17 (pan) and GPIO18 (tilt) on a Raspberry Pi 4 Model B. It reads user input from stdin to adjust the pan and tilt angles in 5-degree increments, enforcing limits of 0 to 180 degrees. The code uses pigpio's hardware PWM at 50 Hz, with pulse widths ranging from 500 microseconds (0 degrees) to 2500 microseconds (180 degrees). It handles pigpio initialization failure, SIGINT (Ctrl+C), and out-of-range angles or PWM settings. The code also includes a 100 ms delay between commands to prevent excessive CPU usage.

