int main() {
    // Initialize GPIO and I2C
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up LCD
    uint8_t lcd_init_sequence[] = {
        LCD_FUNCTION_SET,
        LCD_DISPLAY_OFF,
