volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    if (gpioSetMode(GPIO17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 mode\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPullUpDnControl(GPIO17, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set GPIO17 pull-up/down\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetISR(GPIO17, EITHER_EDGE, NULL, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO17 interrupt\n");
        gpioTerminate();
        exit(1);
    }

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Failed to terminate pigpio\n");
        exit(1);
    }
}

