    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }

    int fd = bbI2COpen(1, LCD_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return;
    }

    if (i2cWriteReg(fd, 0x00, 0x03) < 0) {
        fprintf(stderr, "Failed to set LCD mode\n");
        i2cClose(fd);
        return;
    }

    if (i2cWriteReg(fd, 0x00, 0x02) < 0) {
        fprintf(stderr, "Failed to set LCD function set\n");
        i2cClose(fd);
        return;
    }

    if (i2cWriteReg(fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Failed to set LCD display on\n");
        i2cClose(fd);
        return;
    }

    if (i2cWriteReg(fd, 0x00, 0x06) < 0) {
        fprintf(stderr, "Failed to set LCD entry mode\n");
        i2cClose(fd);
        return;
    }

    if (i2cWriteReg(fd, 0x00, 0x0F) < 0) {
        fprintf(stderr, "Failed to set LCD display on\n");
        i2cClose(fd);
        return;
    }

    for (int i = 0; i < strlen(str); i++) {
        if (i2cWriteReg(fd, 0x00, str[i]) < 0) {
            fprintf(stderr, "Failed to write to LCD\n");
            i2cClose(fd);
            return;
        }
    }

    if (i2cWriteReg(fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Failed to clear LCD\n");
        i2cClose(fd);
        return;
    }

    i2cClose(fd);
}

void display_wind_speed(int speed) {
    char str[10];
    sprintf(str, "Speed: %.2f m/s", (float)speed / 2);
    display_lcd(str);
}

