    char str[10];
    sprintf(str, "Dir: %d deg", direction);
    display_lcd(str);
}

void update_wind_speed() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }

    int pulses = gpioGetISR(GPIO17, EITHER_EDGE);
    if (pulses < 0) {
        fprintf(stderr, "Failed to get GPIO17 interrupt\n");
        return;
    }

    int speed = pulses * PULSE_TO_SPEED;
    display_wind_speed(speed);
}

void update_wind_direction() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return;
    }

    int fd = bbSPIOpen(0, 0, SPI_SPEED, SPI_MODE, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        return;
    }

    uint8_t data[2];
    if (spiXfer(fd, &data, 2, 0, 0) < 0) {
        fprintf(stderr, "Failed to read from ADC\n");
        spiClose(fd);
        return;
    }

    int adc_value = (data[0] << 8) | data[1];
    if (adc_value == 0 || adc_value == ADC_MAX) {
        fprintf(stderr, "ADC reading stuck at %d\n", adc_value);
        spiClose(fd);
        return;
    }

    int direction = (int)((adc_value * ADC_LINEARITY) + ADC_MIN_DEGREES);
    display_wind_direction(direction);

    spiClose(fd);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    cleanup();

    while (running) {
        update_wind_speed();
        update_wind_direction();
        usleep(SAMPLE_WINDOW * 1000);
    }

    cleanup();
    return 0;
}

