#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <pcf8574.h>
#include <i2c-dev.h>

#define FLOW_SENSOR_GPIO 17
#define FLOW_SENSOR_CALIBRATION 7.5
#define FLOW_SENSOR_INTERVAL 1000  // 1 second
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDRESS 0x27

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void cleanup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL);

    if (pcf8574_close(LCD_I2C_BUS) < 0) {
        fprintf(stderr, "Failed to close LCD I2C bus\n");
    }

    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetAlertFunc(FLOW_SENSOR_GPIO, NULL);

    if (pcf8574_init(LCD_I2C_BUS, LCD_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize LCD I2C bus\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    uint32_t pulses = 0;
    uint32_t last_pulses = 0;
    uint32_t last_update = 0;

    while (running) {
        if (pcf8574_write(LCD_I2C_BUS, 0x80, "Flow Rate:") < 0) {
            fprintf(stderr, "Failed to write to LCD\n");
            running = false;
        }

        uint32_t current_time = time(NULL);
        if (current_time - last_update >= FLOW_SENSOR_INTERVAL) {
            last_update = current_time;

            if (pcf8574_write(LCD_I2C_BUS, 0xC0, "X.XX L/min") < 0) {
                fprintf(stderr, "Failed to write to LCD\n");
                running = false;
            }

            pulses = gpioGetCount(FLOW_SENSOR_GPIO);
            if (pulses == last_pulses) {
                // Sensor absent, wait for a pulse
                usleep(100000);
                pulses = gpioGetCount(FLOW_SENSOR_GPIO);
                if (pulses == last_pulses) {
                    // Sensor still absent, reset flow rate
                    pulses = 0;
                }
            }

            last_pulses = pulses;

            double flow_rate = (pulses - last_pulses) * FLOW_SENSOR_CALIBRATION / FLOW_SENSOR_INTERVAL;
            char flow_rate_str[10];
            sprintf(flow_rate_str, "%.2f", flow_rate);

            if (pcf8574_write(LCD_I2C_BUS, 0xC0, flow_rate_str) < 0) {
                fprintf(stderr, "Failed to write to LCD\n");
                running = false;
            }
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}

