            double flow_rate = (pulses - last_pulses) * FLOW_SENSOR_CALIBRATION / FLOW_SENSOR_INTERVAL;
            char flow_rate_str[10];
            sprintf(flow_rate_str, "%.2f", flow_rate);

            if (pcf8574_write(LCD_I2C_BUS, 0xC0, flow_rate_str) < 0) {
                fprintf(stderr, "Failed to write to LCD\n");
                running = false;
            }
        }

        usleep(10000);
    }

    cleanup();
    return 0;
}
