#define DELAY 150

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Release all GPIO lines
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(COL_PINS[i]);
    }
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(ROW_PINS[i]);
    }
    gpiod_chip_close(gpiod_chip);
    exit(0);
}

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the GPIO chip
    gpiod_chip *gpiod_chip = gpiod_chip_open(CHIP_NAME);
    if (!gpiod_chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Request output for column pins
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line *line = gpiod_line_request_output(gpiod_chip, COL_PINS[i], 0);
        if (!line) {
            perror("gpiod_line_request_output");
            gpiod_chip_close(gpiod_chip);
            exit(1);
        }
    }

    // Request output for row pins
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line *line = gpiod_line_request_output(gpiod_chip, ROW_PINS[i], 0);
        if (!line) {
            perror("gpiod_line_request_output");
            for (int j = 0; j < NUM_COLS; j++) {
                gpiod_line_release(COL_PINS[j]);
            }
            gpiod_chip_close(gpiod_chip);
            exit(1);
        }
    }

    // Main animation loop
    while (1) {
        // Clear the matrix by setting all column cathodes HIGH and all row anodes LOW
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_set_value(COL_PINS[i], 1);
        }
        for (int i = 0; i < NUM_ROWS; i++) {
            gpiod_line_set_value(ROW_PINS[i], 0);
        }

        // Scan columns from left to right
        for (int i = 0; i < NUM_COLS; i++) {
            // Set the corresponding column cathode LOW and all row anodes HIGH to light the entire column
            gpiod_line_set_value(COL_PINS[i], 0);
            for (int j = 0; j < NUM_ROWS; j++) {
                gpiod_line_set_value(ROW_PINS[j], 1);
            }

            // Delay for 150 ms
            usleep(DELAY * 1000);
        }

        // Clear the matrix again
        for (int i = 0; i < NUM_COLS; i++) {
            gpiod_line_set_value(COL_PINS[i], 1);
        }
        for (int i = 0; i < NUM_ROWS; i++) {
            gpiod_line_set_value(ROW_PINS[i], 0);
        }
    }

    // Release all GPIO lines
    for (int i = 0; i < NUM_COLS; i++) {
        gpiod_line_release(COL_PINS[i]);
    }
    for (int i = 0; i < NUM_ROWS; i++) {
        gpiod_line_release(ROW_PINS[i]);
    }
    gpiod_chip_close(gpiod_chip);

    return 0;
}

