#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4C
#define REG_DISTANCE 0x0D
#define SAMPLE_INTERVAL 100000 // 100ms
#define CSV_FILE "depth_log.csv"

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if file is new and write header
    if (fseek(log_file, 0, SEEK_END) == -1 || ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance\n");
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        // Write register address
        if (i2cWriteReg8(i2c_fd, REG_DISTANCE, 0) < 0) {
            fprintf(stderr, "Failed to write register address\n");
            break;
        }

        // Read 16-bit distance
        uint16_t distance;
        char buffer[2];
        if (i2cReadReg16(i2c_fd, REG_DISTANCE, buffer, 2) < 0) {
            fprintf(stderr, "Failed to read distance\n");
            break;
        }
        distance = (buffer[0] << 8) | buffer[1];

        // Log distance
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%ld,%d\n", tv.tv_sec, distance);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close I2C handle and log file
    gpioClose(i2c_fd);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

