#define SI1145_CMD_REG 0x18
#define SI1145_MEAS_RATE 0x01
#define SI1145_IRQ_CLR 0x80

#define MAX_LOG_LINE 256

static void sigint_handler(int sig) {
    if (i2cOpen(I2C_BUS, SI1145_ADDRESS, &i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
