#include <errno.h>
#include <string.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_SENSOR_LINE 4
#define GPIO_LED_LINE 17
#define POLL_INTERVAL 100000 // 100 ms
#define LOG_FILE "proximity.log"

// Function to handle signal interrupts
void sigint_handler(int sig) {
    gpiod_chip_close(gpio_chip);
    gpiod_line_release(gpio_sensor);
    gpiod_line_release(gpio_led);
    exit(0);
}

int main() {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (gpio_chip == NULL) {
        gpio_chip = gpiod_chip_open_by_name("gpiochip0");
        if (gpio_chip == NULL) {
            fprintf(stderr, "Failed to open GPIO chip\n");
            exit(1);
        }
    }

    // Get GPIO lines
    gpio_sensor = gpiod_line_request_output(gpio_chip, GPIO_SENSOR_LINE, "proximity_sensor");
    if (gpio_sensor == NULL) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_SENSOR_LINE);
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    gpio_led = gpiod_line_request_output(gpio_chip, GPIO_LED_LINE, "proximity_led");
    if (gpio_led == NULL) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LED_LINE);
        gpiod_line_release(gpio_sensor);
        gpiod_chip_close(gpio_chip);
        exit(1);
    }

    // Initialize LED
    gpiod_line_set_value(gpio_led, 1);

    // Main loop
    while (1) {
        // Read sensor value
        int sensor_value = gpiod_line_get_value(gpio_sensor);
        if (sensor_value == -1) {
            fprintf(stderr, "Failed to read GPIO line %d\n", GPIO_SENSOR_LINE);
            gpiod_line_release(gpio_sensor);
            gpiod_line_release(gpio_led);
            gpiod_chip_close(gpio_chip);
            exit(1);
        }

        // Check for falling edge (object entering range)
        if (sensor_value == 0 && gpiod_line_get_value(gpio_sensor) == 1) {
            // Log event
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
            FILE *log_file = fopen(LOG_FILE, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                gpiod_line_release(gpio_sensor);
                gpiod_line_release(gpio_led);
                gpiod_chip_close(gpio_chip);
                exit(1);
            }
            fprintf(log_file, "%s Object detected\n", timestamp);
            fclose(log_file);

            // Blink LED
            gpiod_line_set_value(gpio_led, 0);
            usleep(100000);
            gpiod_line_set_value(gpio_led, 1);
        }

        // Polling delay
        usleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_line_release(gpio_sensor);
    gpiod_line_release(gpio_led);
    gpiod_chip_close(gpio_chip);
    return 0;
}

