#define I2C_BUS 1
#define SI1145_ADDRESS 0x60
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define PS1 0x18
#define ALS_VIS 0x22
#define COMMAND 0x30
#define ALS_FORCE 0x06
#define PS_FORCE 0x07
#define MEAS_RATE_PS 0x01
#define MEAS_RATE_ALS 0x02

void sigint_handler(int sig) {
    if (i2c_close(I2C_BUS) < 0) {
        perror("i2c_close");
    }
    if (fclose(log_file) != 0) {
        perror("fclose");
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd = i2cOpen(I2C_BUS, SI1145_ADDRESS);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        return 1;
    }

    FILE *log_file = fopen("biometric_data.log", "w");
    if (!log_file) {
        perror("fopen");
        i2c_close(I2C_BUS);
        return 1;
    }

    struct tm *timeinfo;
    time_t rawtime;
    char timestamp[20];

    signal(SIGINT, sigint_handler);

    if (i2cWriteReg8(i2c_fd, PART_ID, 0x45) < 0) {
        fprintf(stderr, "Error: PART_ID mismatch\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error: failed to write to HW_KEY\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, CH_LIST, 0x4F) < 0) {
        fprintf(stderr, "Error: failed to write to CH_LIST\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, COMMAND, ALS_FORCE) < 0) {
        fprintf(stderr, "Error: failed to write to COMMAND (ALS_FORCE)\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, COMMAND, PS_FORCE) < 0) {
        fprintf(stderr, "Error: failed to write to COMMAND (PS_FORCE)\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, MEAS_RATE_PS, MEAS_RATE_PS) < 0) {
        fprintf(stderr, "Error: failed to write to MEAS_RATE_PS\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    if (i2cWriteReg8(i2c_fd, MEAS_RATE_ALS, MEAS_RATE_ALS) < 0) {
        fprintf(stderr, "Error: failed to write to MEAS_RATE_ALS\n");
        i2c_close(I2C_BUS);
        fclose(log_file);
        return 1;
    }

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);

        uint16_t ps1_data;
        if (i2cReadReg16(i2c_fd, PS1, &ps1_data, 2) < 0) {
            fprintf(stderr, "Error: failed to read PS1 data\n");
            i2c_close(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        uint16_t als_vis_data;
        if (i2cReadReg16(i2c_fd, ALS_VIS, &als_vis_data, 2) < 0) {
            fprintf(stderr, "Error: failed to read ALS_VIS data\n");
            i2c_close(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (double)ps1_data / 1000.0, (double)als_vis_data / 1000.0);
        if (ferror(log_file)) {
            fprintf(stderr, "Error: failed to write to log file\n");
            i2c_close(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        if (fflush(log_file) != 0) {
            fprintf(stderr, "Error: failed to flush log file\n");
            i2c_close(I2C_BUS);
            fclose(log_file);
            return 1;
        }

        usleep(1000000);
    }

    return 0;
}

