#define LOG_FILE "distance_log.txt"
#define TRIGGER_GPIO 17
#define ECHO_GPIO 27
#define TRIGGER_HZ 1000
#define TRIGGER_US 10
#define TIMEOUT_US 30000
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define WATERING_THRESHOLD 15
#define POLLING_INTERVAL 60000

static gpiod_line *trigger_line = NULL;
static gpiod_line *echo_line = NULL;
static FILE *log_file = NULL;

static void sigint_handler(int sig) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    exit(0);
}

static void log_message(const char *message) {
    struct tm *timeinfo;
    time_t rawtime;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
}

static void measure_distance() {
    struct gpiod_line_event event;
    struct gpiod_line_event *events;
    int num_events;
    int64_t pulse_start, pulse_end;
    int64_t pulse_width;
    int distance;

    if (gpiod_line_event_request(trigger_line, GPIOD_LINE_EVENT_RISING_EDGE, &events, &num_events, TIMEOUT_US) < 0) {
        log_message("Error requesting trigger event");
        return;
    }

    if (gpiod_line_event_request(echo_line, GPIOD_LINE_EVENT_BOTH_EDGES, &events, &num_events, TIMEOUT_US) < 0) {
