#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define PROXIMITY_THRESHOLD 200
#define CSV_FILE "color_proximity_log.csv"

// Function to handle I2C communication errors
void i2c_error_handler(int error) {
    fprintf(stderr, "I2C error: %s\n", strerror(error));
    // Close and reopen the I2C bus
    gpioI2COpen(I2C_BUS, I2C_ADDRESS, NULL);
    // Re-initialize the sensor
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x80, 0x03);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x81, 0xDB);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x83, 0xF6);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x8E, 0x87);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0xF1, 0x03);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x90, 0x01);
}

// Function to handle signal interrupts
void signal_handler(int signal) {
    // Close the I2C handle
    gpioI2CClose(I2C_BUS);
    // Close the CSV file
    fclose(fp);
    // Release all pigpio resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the I2C bus
    if (gpioI2COpen(I2C_BUS, I2C_ADDRESS, NULL) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify the sensor ID register
    uint8_t id;
    if (gpioI2CReadReg8(I2C_BUS, I2C_ADDRESS, 0x92, &id) < 0) {
        i2c_error_handler(errno);
    }
    if (id != 0xAB) {
        fprintf(stderr, "Invalid sensor ID\n");
        gpioI2CClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x80, 0x03);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x81, 0xDB);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x83, 0xF6);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x8E, 0x87);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0xF1, 0x03);
    gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, 0x90, 0x01);

    // Open the CSV file for writing
    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioI2CClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the 16-bit raw RGB color values and the 8-bit proximity value
        uint16_t r, g, b;
        uint8_t p;
        if (gpioI2CReadReg16(I2C_BUS, I2C_ADDRESS, 0x96, &r) < 0 || gpioI2CReadReg16(I2C_BUS, I2C_ADDRESS, 0x98, &g) < 0 || gpioI2CReadReg16(I2C_BUS, I2C_ADDRESS, 0x9A, &b) < 0 || gpioI2CReadReg8(I2C_BUS, I2C_ADDRESS, 0x9C, &p) < 0) {
            i2c_error_handler(errno);
        }

        // Check if the proximity value exceeds the threshold
        if (p > PROXIMITY_THRESHOLD) {
            // Log the data to the CSV file
            fprintf(fp, "%lu,%04x,%04x,%04x,%d\n", time(NULL), r, g, b, p);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    return 0;
}

