#define I2C_FILE "/dev/i2c-1"
#define SI1182_ADDRESS 0x5A
#define MEAS_RATE0 0x08
#define COMMAND 0x47
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define PART_ID 0x00
#define BPM_FILE "heartrate.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = open(I2C_FILE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    uint8_t part_id;
    if (i2c_smbus_read_byte_data(i2c_fd, PART_ID) < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        close(i2c_fd);
        return 1;
    }
    if (part_id != 0x5A) {
        fprintf(stderr, "Invalid Si1182 part ID 0x%02x\n", part_id);
        close(i2c_fd);
        return 1;
    }

    uint8_t meas_rate = 0x01; // Set MEAS_RATE0 to 1 Hz
    if (i2c_smbus_write_byte_data(i2c_fd, MEAS_RATE0, meas_rate) < 0) {
        perror("Failed to write MEAS_RATE0 register");
        close(i2c_fd);
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, COMMAND, 0x01) < 0) {
        perror("Failed to write COMMAND register");
        close(i2c_fd);
        return 1;
    }

    FILE *bpm_file = fopen(BPM_FILE, "a");
    if (!bpm_file) {
        perror("Failed to open BPM file");
        close(i2c_fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        fclose(bpm_file);
        close(i2c_fd);
        return 1;
    }

    time_t start_time = time(NULL);
    while (running) {
        uint16_t data;
        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA0) < 0) {
            fprintf(stderr, "Warning: failed to read PS_DATA0 register\n");
            continue;
        }
        if (i2c_smbus_read_word_data(i2c_fd, PS_DATA1) < 0) {
            fprintf(stderr, "Warning: failed to read PS_DATA1 register\n");
            continue;
        }
        data = (i2c_smbus_read_word_data(i2c_fd, PS_DATA0) << 8) | i2c_smbus_read_word_data(i2c_fd, PS_DATA1);
        uint16_t bpm = 60 * 1000 / (data * 1000); // placeholder BPM calculation
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%03dZ", localtime(&time(NULL)));
        fprintf(bpm_file, "%s,%d\n", timestamp, bpm);
        fflush(bpm_file);
        usleep(100000);
    }

    fclose(bpm_file);
    close(i2c_fd);
    return 0;
