// Function to read a byte from the I2C bus
uint8_t i2c_read_byte(int file, uint8_t reg) {
    uint8_t data;
    if (ioctl(file, I2C_SMBUS_READ, &data, 1, reg, 1) < 0) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        exit(1);
    }
    return data;
}

// Function to write a byte to the I2C bus
void i2c_write_byte(int file, uint8_t reg, uint8_t data) {
    if (ioctl(file, I2C_SMBUS_WRITE, reg, 1, &data, 1) < 0) {
        fprintf(stderr, "Error writing to I2C bus: %s\n", strerror(errno));
        exit(1);
    }
}

// Function to read a 16-bit value from the I2C bus
uint16_t i2c_read_word(int file, uint8_t reg) {
    uint8_t data[2];
    if (ioctl(file, I2C_SMBUS_READ, data, 2, reg, 2) < 0) {
        fprintf(stderr, "Error reading from I2C bus: %s\n", strerror(errno));
        exit(1);
    }
    return (data[0] << 8) | data[1];
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(1);
    }

    // Set up GPIO 17 as input with pull-up
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 17: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO 17: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Open the I2C bus
    int i2c_file = gpioI2COpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_file < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Verify sensor presence
    if (i2c_read_byte(i2c_file, 0x00) != 0x00) {
        fprintf(stderr, "Sensor not present at address 0x%02x\n", I2C_ADDRESS);
        gpioI2CClose(i2c_file);
        gpioTerminate();
        exit(1);
    }

    // Set up interrupt on GPIO 17
    if (gpioWatchdog(GPIO_PIN, MEASUREMENT_INTERVAL * 1000) < 0) {
        fprintf(stderr, "Failed to set up watchdog on GPIO 17: %s\n", strerror(errno));
        gpioI2CClose(i2c_file);
        gpioTerminate();
        exit(1);
    }

    // Start the sensor
    i2c_write_byte(i2c_file, 0x00, 0x01);

    // Open the log file
    FILE *log_file = fopen("distance_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2c_file);
        gpioTerminate();
        exit(1);
    }

    // Main loop
    while (1) {
        // Wait for interrupt
        if (gpioWaitForEvent(GPIO_PIN, PI_EDGE_FALLING) < 0) {
            fprintf(stderr, "Failed to wait for interrupt: %s\n", strerror(errno));
            break;
        }

        // Poll for measurement completion
        struct timeval timeout;
        timeout.tv_sec = MEASUREMENT_TIMEOUT / 1000;
        timeout.tv_usec = (MEASUREMENT_TIMEOUT % 1000) * 1000;
        if (select(0, NULL, NULL, NULL, &timeout) < 0) {
            fprintf(stderr, "Failed to poll for measurement completion: %s\n", strerror(errno));
            break;
        }
        if (i2c_read_byte(i2c_file, 0x13) & 0x01) {
            // Read result
            uint16_t distance = i2c_read_word(i2c_file, 0x14);
            // Clear interrupt
            i2c_write_byte(i2c_file, 0x0B, 0x01);
            // Log measurement
            struct timeval tv;
            gettimeofday(&tv, NULL);
            fprintf(log_file, "%lu,%d\n", tv.tv_sec * 1000 + tv.tv_usec / 1000, distance);
        }
    }

    // Close the log file
    fclose(log_file);

    // Close the I2C bus
    gpioI2CClose(i2c_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close the log file
    fclose(log_file);

    // Close the I2C bus
    gpioI2CClose(i2c_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

