#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define MEASUREMENT_DELAY_US 50000
#define SAMPLE_DELAY_MS 200
#define TIMESTAMP_SIZE 20
#define LOG_FILE "distance_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(log_file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up timestamp buffer
    char timestamp[TIMESTAMP_SIZE];
    time_t now;
    struct tm *timeinfo;
    while (running) {
        // Trigger measurement
        if (i2cWriteReg8(i2c_fd, I2C_ADDRESS, 0x00, 0x00) < 0) {
            fprintf(stderr, "I2C write error\n");
            continue;
        }

        // Wait for measurement
        usleep(MEASUREMENT_DELAY_US);

        // Read measurement
        uint16_t distance;
        if (i2cReadReg16(i2c_fd, I2C_ADDRESS, 0x00, &distance) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Convert to millimeters
        distance = (distance >> 8) | (distance << 8);

        // Get current time
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, TIMESTAMP_SIZE, "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log and print result
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        printf("%s, %d\n", timestamp, distance);

        // Wait for next sample
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    // Clean up
    fclose(log_file);
    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

