        fprintf(log_file, "%lu %d %d\n", timestamp, proximity_data, ambient_light_data);

        // Wait 500 ms before next reading
        usleep(500000);
    }

    // Close I2C handle
    gpioI2CClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

