#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x6A
#define LED_PIN 17
#define THRESHOLD 100  // default threshold in mm

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Release I2C handle
    if (i2c_close(I2C_BUS) != 0) {
        perror("i2c_close");
    }

    // Release GPIO
    gpioTerminate();

    // Exit with status code 0
    exit(0);
}

int main(int argc, char *argv[]) {
    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor's WHO_AM_I register
    uint8_t who_am_i;
    if (i2cReadReg8(i2c_fd, 0x0F, &who_am_i, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "Sensor not found at address 0x6A\n");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Parse threshold from command-line argument
    int threshold = THRESHOLD;
    if (argc > 1) {
        char *endptr;
        threshold = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0') {
            fprintf(stderr, "Invalid threshold value\n");
            i2c_close(I2C_BUS);
            gpioTerminate();
            return 1;
        }
    }

    // Set up LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        perror("gpioSetMode");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance measurement
        uint16_t distance;
        if (i2cReadReg16(i2c_fd, 0x00, &distance, 1) != 1) {
            fprintf(stderr, "Failed to read distance measurement\n");
            break;
        }

        // Log reading with timestamp
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        FILE *fp = fopen("tof_log.txt", "a");
        if (fp == NULL) {
            perror("fopen");
            break;
        }
        fprintf(fp, "%s: %d mm\n", timestamp, distance);
        fclose(fp);

        // Turn on LED if distance falls below threshold
        if (distance < threshold) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Release I2C handle
    if (i2c_close(I2C_BUS) != 0) {
        perror("i2c_close");
    }

    // Release GPIO
    gpioTerminate();

    return 0;
}

