#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x50
#define COMMAND_SIZE 4
#define RESPONSE_SIZE 15
#define SAMPLES_PER_CYCLE 10
#define DELAY_MSEC 100
#define LOG_FILE "intrusion_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    while (running) {
        uint8_t command[COMMAND_SIZE] = {0x50, 0x0A, 0x00, 0x01};
        uint8_t response[RESPONSE_SIZE];
        uint16_t distances[SAMPLES_PER_CYCLE];
        uint16_t sum = 0;
        uint16_t count = 0;

        // Write command to sensor
        if (write(i2c_fd, command, COMMAND_SIZE) != COMMAND_SIZE) {
            perror("Failed to write command to sensor");
            fclose(log_file);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Wait for 10 ms
        usleep(10000);

        // Read response from sensor
        if (read(i2c_fd, response, RESPONSE_SIZE) != RESPONSE_SIZE) {
            perror("Failed to read response from sensor");
            fclose(log_file);
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Validate response header
        if (response[0] != I2C_ADDRESS) {
            fprintf(stderr, "Invalid response header\n");
            continue;
        }

        // Extract distance values
        for (int i = 0; i < SAMPLES_PER_CYCLE; i++) {
            distances[i] = (response[11] << 8) | response[12];
            sum += distances[i];
            count++;
        }

        // Calculate average distance
        uint16_t average_distance = sum / count;

        // Check for intrusion
        if (average_distance < 1000) {
            time_t timestamp = time(NULL);
            fprintf(log_file, "%lu %d\n", timestamp, average_distance);
        }

        // Delay between cycles
        usleep(DELAY_MSEC * 1000);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    fclose(log_file);

    return 0;
}

