        distance = (buffer[1] << 8) | buffer[0];

        // Clear interrupt
        if (gpioI2CWrite(fd, REG_SYSTEM_INTERRUPT_CLEAR, 1, 1) < 0) {
            fprintf(stderr, "Failed to clear interrupt: %s\n", strerror(errno));
            continue;
