// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    // Cleanly close the I2C handle
    if (i2cClose(I2C_BUS_1) != 0) {
        fprintf(stderr, "Error closing I2C bus 1: %s\n", pigpioErrorStr(errno));
    }
    // Terminate the GPIO library
    gpioTerminate();
    exit(0);
}

int main() {
    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO library: %s\n", pigpioErrorStr(errno));
        return 1;
    }

    // Set up I2C bus 1
    if (i2cOpen(I2C_BUS_1, 0) < 0) {
        fprintf(stderr, "Error opening I2C bus 1: %s\n", pigpioErrorStr(errno));
        gpioTerminate();
        return 1;
    }

    // Set up the I2C address of the Si1182 sensor
    uint8_t address = 0x39;

    // Initialize the Si1182 sensor by writing 0x01 to the CONFIG register
    uint8_t config = 0x01;
    if (i2cWriteReg8(I2C_BUS_1, address, 0x18, &config, 1) != 1) {
        fprintf(stderr, "Error writing to Si1182 CONFIG register: %s\n", pigpioErrorStr(errno));
        i2cClose(I2C_BUS_1);
        gpioTerminate();
        return 1;
    }

    // Poll for data-ready bit 0 in the IRQ status register
    uint8_t irq_status;
    while (1) {
        if (i2cReadReg8(I2C_BUS_1, address, 0x25, &irq_status, 1) != 1) {
            fprintf(stderr, "Error reading from Si1182 IRQ status register: %s\n", pigpioErrorStr(errno));
            i2cClose(I2C_BUS_1);
            gpioTerminate();
            return 1;
        }
        if (irq_status & 0x01) {
            break;
        }
        usleep(100000); // 100 ms
    }

    // Read the 16-bit proximity result from registers 0x2A (LSB) and 0x2B (MSB)
    uint16_t proximity;
    if (i2cReadReg16(I2C_BUS_1, address, 0x2A, &proximity, 2) != 2) {
        fprintf(stderr, "Error reading from Si1182 proximity registers: %s\n", pigpioErrorStr(errno));
        i2cClose(I2C_BUS_1);
        gpioTerminate();
        return 1;
    }

    // Print the proximity value
    printf("Proximity: %d\n", proximity);

    // Periodically read and print the proximity value
    while (1) {
        // Poll for data-ready bit 0 in the IRQ status register
        while (1) {
            if (i2cReadReg8(I2C_BUS_1, address, 0x25, &irq_status, 1) != 1) {
                fprintf(stderr, "Error reading from Si1182 IRQ status register: %s\n", pigpioErrorStr(errno));
                i2cClose(I2C_BUS_1);
                gpioTerminate();
                return 1;
