#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Function to handle signal to clean up and exit
void sigint_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    int i2c_fd = -1;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data packets;
    uint16_t distance;
    uint8_t buffer[2];

    // Open I2C bus 1
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(i2c_fd, I2C_SLAVE, 0x4C) < 0) {
        perror("Failed to set slave address");
        close(i2c_fd);
        return 1;
    }

    // Verify device responds
    if (ioctl(i2c_fd, I2C_SLAVE, 0x4C) < 0) {
        perror("Failed to set slave address (again)");
        close(i2c_fd);
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read 16-bit distance register
        msg.addr = 0x4C;
        msg.fmt = I2C_M_RD;
        msg.len = 2;
        msg.buf = buffer;
        packets.msgs = &msg;
        packets.nmsgs = 1;
        if (ioctl(i2c_fd, I2C_RDWR, &packets) < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            continue;
        }

        // Convert raw value to millimeters
        distance = (buffer[0] << 8) | buffer[1];
        double mm = (double)distance * 0.125;

        // Print distance
        printf("Distance: %.3f mm\n", mm);

        // Sleep for 500 ms
        nanosleep((const struct timespec[]){{0, 500000000}}, NULL);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

