#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CHANNEL 0
#define SAMPLE_RATE 500  // ms

// Define a function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    // Release resources and exit cleanly
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up I2C bus
    if (gpioI2CSetup(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    int fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance and ambient light data
        uint16_t distance;
        uint16_t ambient;
        int ret = i2cReadReg8(fd, 0x00, 2, (uint8_t*)&distance, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read distance data\n");
            break;
        }
        ret = i2cReadReg8(fd, 0x02, 2, (uint8_t*)&ambient, 2);
        if (ret < 0) {
            fprintf(stderr, "Failed to read ambient light data\n");
            break;
        }

        // Log data
        printf("Distance: %d mm, Ambient: %d lux, Error flags: 0x%02x\n",
               distance, ambient, i2cGetError(fd));

        // Wait for next sample
        usleep(SAMPLE_RATE * 1000);
    }

    // Release resources
    gpioTerminate();
    return 0;
}
```

This code uses the `pigpio` library to interface with the Raspberry Pi's GPIO and I2C peripherals. It sets up a signal handler for SIGINT (Ctrl+C) to ensure clean resource release on exit. The main loop reads distance and ambient light data from the OPT3101 sensor every 500 ms and logs the data to the console. It also checks for I2C communication failures and releases resources on all exit paths.

