#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO 17 as an output for the trigger
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO 18 as an input for the echo with pull-up resistor
    if (gpioSetMode(18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 18 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set up a pull-up resistor on GPIO 18
    if (gpioSetPullUpDnControl(18, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor on GPIO 18\n");
        gpioTerminate();
        return 1;
    }

    // Set up a signal handler for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        // Send a 10 microsecond trigger pulse
        if (gpioWrite(17, 1) < 0 || gpioDelayMicroseconds(10) < 0 || gpioWrite(17, 0) < 0) {
            fprintf(stderr, "Failed to send trigger pulse\n");
            gpioTerminate();
            return 1;
        }

        // Wait for the echo rising edge
        if (gpioTick() + 200000 > gpioGetTick() || gpioWaitForRisingEdge(18, 200000) < 0) {
            fprintf(stderr, "Echo rising edge timeout\n");
            gpioTerminate();
            return 1;
        }

        // Wait for the echo falling edge
        if (gpioWaitForFallingEdge(18, 200000) < 0) {
            fprintf(stderr, "Echo falling edge timeout\n");
            gpioTerminate();
            return 1;
        }

        // Measure the echo pulse width
        uint32_t pulse_us = gpioTick() - gpioGetTick();

        // Check for invalid pulse duration
        if (pulse_us <= 0 || pulse_us > 38000) {
            fprintf(stderr, "Invalid pulse duration\n");
            gpioTerminate();
            return 1;
        }

        // Compute the distance in cm
        double distance_cm = (pulse_us * 0.0343) / 2;

        // Log the reading with a timestamp
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        printf("%s: Distance: %.2f cm\n", timestamp, distance_cm);

        // Wait for 1 second before repeating
        sleep(1);
    }

    // Clean up on exit
    gpioTerminate();
    return 0;
}

