#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUDRATE B115200
#define UART_TIMEOUT 1000
#define GPIO_LED 17
#define DISTANCE_THRESHOLD 1.0
#define RANGE_RESOLUTION 0.0486
#define RANGE_BINS 64
#define DATA_FRAME_SIZE 136

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_intrusion(double distance) {
    char timestamp[32];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    FILE *file = fopen("intrusion_log.csv", "a");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open intrusion log file");
        return;
    }
    fprintf(file, "%s,%f\n", timestamp, distance);
    fclose(file);
}

int main() {
    int uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        syslog(LOG_ERR, "Failed to open UART device");
        return EXIT_FAILURE;
    }

    struct termios uart_config;
    if (tcgetattr(uart_fd, &uart_config) < 0) {
        syslog(LOG_ERR, "Failed to get UART configuration");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    cfsetispeed(&uart_config, UART_BAUDRATE);
    cfsetospeed(&uart_config, UART_BAUDRATE);
    uart_config.c_cflag = (CS8 | CLOCAL | CREAD);
    uart_config.c_iflag = IGNBRK | IGNPAR;
    uart_config.c_oflag = 0;
    uart_config.c_lflag = 0;
    uart_config.c_cc[VMIN] = 1;
    uart_config.c_cc[VTIME] = UART_TIMEOUT / 100;
    if (tcsetattr(uart_fd, TCSANOW, &uart_config) < 0) {
        syslog(LOG_ERR, "Failed to set UART configuration");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        close(uart_fd);
        return EXIT_FAILURE;
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t magic_word[] = {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07};
    uint16_t range_profile[RANGE_BINS];

    while (running) {
        uint8_t buffer[DATA_FRAME_SIZE];
        ssize_t bytes_read = read(uart_fd, buffer, DATA_FRAME_SIZE);
        if (bytes_read < 0) {
            syslog(LOG_ERR, "Failed to read from UART");
            break;
        } else if (bytes_read < DATA_FRAME_SIZE) {
            syslog(LOG_ERR, "Incomplete data frame received");
            continue;
        }

        if (memcmp(buffer, magic_word, sizeof(magic_word)) != 0) {
            syslog(LOG_ERR, "Invalid magic word");
            continue;
        }

        for (int i = 0; i < RANGE_BINS; i++) {
            uint16_t value = (buffer[8 + i * 2 + 1] << 8) | buffer[8 + i * 2];
            range_profile[i] = value;
        }

        for (int i = 0; i < RANGE_BINS; i++) {
            double distance = (i * RANGE_RESOLUTION);
            if (distance < DISTANCE_THRESHOLD) {
                log_intrusion(distance);
                gpioWrite(GPIO_LED, 1);
                usleep(2000000);
                gpioWrite(GPIO_LED, 0);
            }
        }
    }

    gpioTerminate();
    close(uart_fd);
    return EXIT_SUCCESS;
}

