#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_SENSOR_PIN 17
#define GPIO_BUZZER_PIN 18
#define POLL_INTERVAL_US 100000
#define LOG_FILE "obstacle_log.txt"

static bool obstacle_detected = false;
static bool buzzer_on = false;

static void handle_sigint(int sig) {
    gpiod_chip_close(gpiod_chip_open(GPIO_CHIP_NAME));
    gpiod_line_release(gpiod_line_request(GPIO_CHIP_NAME, GPIO_SENSOR_PIN, "in"));
    gpiod_line_release(gpiod_line_request(GPIO_CHIP_NAME, GPIO_BUZZER_PIN, "out"));
    exit(0);
}

static void handle_sigterm(int sig) {
    handle_sigint(sig);
}

static void log_state_transition(bool new_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", current_time);

    fprintf(log_file, "%s: obstacle detected=%d\n", timestamp, new_state);
    fclose(log_file);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line, *buzzer_line;

    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    if ((sensor_line = gpiod_line_request(GPIO_CHIP_NAME, GPIO_SENSOR_PIN, "in")) == NULL) {
        gpiod_chip_close(chip);
        perror("gpiod_line_request");
        return 1;
    }

    if ((buzzer_line = gpiod_line_request(GPIO_CHIP_NAME, GPIO_BUZZER_PIN, "out")) == NULL) {
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        perror("gpiod_line_request");
        return 1;
    }

    gpiod_line_set_value(buzzer_line, buzzer_on ? 1 : 0);

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (1) {
        int value;
        if (gpiod_line_get_value(sensor_line, &value) != 0) {
            gpiod_line_release(sensor_line);
            gpiod_line_release(buzzer_line);
            gpiod_chip_close(chip);
            perror("gpiod_line_get_value");
            return 1;
        }

        if (value == 0 && !obstacle_detected) {
            obstacle_detected = true;
            buzzer_on = true;
            gpiod_line_set_value(buzzer_line, 1);
            log_state_transition(true);
        } else if (value == 1 && obstacle_detected) {
            obstacle_detected = false;
            buzzer_on = false;
            gpiod_line_set_value(buzzer_line, 0);
            log_state_transition(false);
        }

        usleep(POLL_INTERVAL_US);
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);
    return 0;
}

