#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define GPIO_ALERT_PIN 17
#define SAMPLE_INTERVAL 100000 // 100 ms
#define DISTANCE_THRESHOLD 10.0

// Function to handle signal requests
void signal_handler(int sig) {
    // Release I2C handle
    if (i2c_close(I2C_BUS) < 0) {
        fprintf(stderr, "Error closing I2C bus: %s\n", strerror(errno));
    }

    // Release GPIO handle
    gpioTerminate();

    // Exit with status code 0
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up GPIO alert pin
    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting up GPIO alert pin: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for signal-requested shutdown
        if (gpioRead(GPIO_ALERT_PIN) == 1) {
            break;
        }

        // Read distance measurement
        uint16_t distance;
        if (i2cReadReg8(I2C_FD, 0x31, &distance, 1) < 0 || i2cReadReg8(I2C_FD, 0x32, (uint8_t*)&(distance + 1), 1) < 0) {
            fprintf(stderr, "Error reading distance measurement: %s\n", strerror(errno));
            break;
        }

        // Trigger alert if distance is below threshold
        if (distance < (DISTANCE_THRESHOLD * 100)) {
            gpioWrite(GPIO_ALERT_PIN, 1);
        } else {
            gpioWrite(GPIO_ALERT_PIN, 0);
        }

        // Log distance measurement
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(log_file, "%s,%.2f\n", timestamp, (double)distance / 100.0);
        fflush(log_file);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Release I2C handle
    if (i2cClose(I2C_BUS) < 0) {
        fprintf(stderr, "Error closing I2C bus: %s\n", strerror(errno));
    }

    // Release GPIO handle
    gpioTerminate();

    return 0;
