#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define GPIO_LED 18
#define GPIO_RESISTOR 330
#define SAMPLING_INTERVAL 100000 // 100 ms
#define MIN_DISTANCE 50
#define MAX_DISTANCE 500
#define MIN_BLINK_FREQ 1
#define MAX_BLINK_FREQ 10

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void blink_led(int gpio, int freq) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioSetPullUpDnControl(GPIO_LED, PI_PUD_UP);

    while (running) {
        if (freq > 0) {
            gpioWrite(GPIO_LED, 1);
            usleep((1000000 / freq) / 2);
            gpioWrite(GPIO_LED, 0);
            usleep((1000000 / freq) / 2);
        } else {
            gpioWrite(GPIO_LED, 1);
            usleep(1000000);
            gpioWrite(GPIO_LED, 0);
        }
    }

    gpioTerminate();
}

void read_distance(int i2c_fd) {
    uint8_t data[2];
    int retries = 0;

    while (retries < 3 && running) {
        if (i2c_smbus_read_byte_data(i2c_fd, 0x00, data) < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error\n");
                break;
            }
            if (errno == EAGAIN) {
                usleep(10000);
                continue;
            }
            fprintf(stderr, "Failed to read distance: %s\n", strerror(errno));
            break;
        }

        uint16_t distance = (data[0] << 8) | data[1];
        double blink_freq = (double)(MAX_BLINK_FREQ - (distance - MIN_DISTANCE) * (MAX_BLINK_FREQ - MIN_BLINK_FREQ) / (MAX_DISTANCE - MIN_DISTANCE));
        blink_freq = (blink_freq < MIN_BLINK_FREQ) ? MIN_BLINK_FREQ : (blink_freq > MAX_BLINK_FREQ) ? MAX_BLINK_FREQ : blink_freq;

        fprintf(stderr, "%lu: distance=%d, blink_freq=%f Hz\n", (unsigned long)time(NULL), distance, blink_freq);

        if (retries == 0) {
            blink_led(GPIO_LED, (int)blink_freq);
        }
    }

    close(i2c_fd);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to configure I2C sensor\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        read_distance(i2c_fd);
        usleep(SAMPLING_INTERVAL);
    }

    close(i2c_fd);
    gpioTerminate();

    return 0;
}

