#define MEASUREMENT_DELAY_US 100000 // 100 ms delay between measurements
#define MAX_RETRIES 5 // Max retries for I2C operations
#define LOG_FILE "distance_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void write_i2c(uint8_t reg, uint8_t value) {
    int fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (pigpio_i2c_write_byte(fd, reg, value) == 0) {
            break;
        }
        retries++;
        if (retries >= MAX_RETRIES) {
            log_error("Failed to write to I2C bus");
            pigpio_i2c_close(fd);
            return;
        }
    }

    pigpio_i2c_close(fd);
}

uint16_t read_i2c(uint8_t reg) {
    int fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return 0;
    }

    int retries = 0;
    uint16_t value = 0;
    while (retries < MAX_RETRIES) {
        if (pigpio_i2c_read_byte(fd, reg, &value) == 0) {
            break;
        }
        retries++;
        if (retries >= MAX_RETRIES) {
            log_error("Failed to read from I2C bus");
            pigpio_i2c_close(fd);
            return 0;
        }
    }

    pigpio_i2c_close(fd);
    return value;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize GPIO");
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    uint8_t trigger_reg = 0x00; // Trigger register
    uint8_t measurement_reg = 0x00; // Measurement register

    while (running) {
        write_i2c(trigger_reg, 0x01); // Trigger a measurement
        usleep(MEASUREMENT_DELAY_US);

        uint16_t distance = read_i2c(measurement_reg);
        if (distance == 0) {
            continue;
        }

        char buffer[20];
        time_t timestamp = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        fprintf(log_file, "%s,%d\n", buffer, distance);
        fflush(log_file);

        usleep(MEASUREMENT_DELAY_US);
    }

    fclose(log_file);
    gpioTerminate();

    return 0;
}

