#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 27
#define DEBOUNCE_TIME 50
#define POLLING_TIME 10
#define LOG_FILE "proximity_log.txt"

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

void log_event(const char *event, int sensor_id) {
    time_t now;
    struct tm *now_tm;
    char timestamp[20];
    char log_line[100];

    time(&now);
    now_tm = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", now_tm);

    sprintf(log_line, "%s %d %s\n", timestamp, sensor_id, event);
    if (fputs(log_line, fopen(LOG_FILE, "a")) == EOF) {
        perror("fopen");
        exit(1);
    }
}

int main() {
    int sensor1_state = 0;
    int sensor2_state = 0;
    int sensor1_prev_state = 0;
    int sensor2_prev_state = 0;
    int gpio_fd = 0;

    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        exit(1);
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_SENSOR1);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", GPIO_SENSOR2);
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        usleep(POLLING_TIME * 1000);

        sensor1_state = gpioRead(GPIO_SENSOR1);
        sensor2_state = gpioRead(GPIO_SENSOR2);

        if (sensor1_state != sensor1_prev_state) {
            if (sensor1_state == 0) {
                log_event("DETECTED", 1);
            } else {
                log_event("CLEARED", 1);
            }
            sensor1_prev_state = sensor1_state;
        }

        if (sensor2_state != sensor2_prev_state) {
            if (sensor2_state == 0) {
                log_event("DETECTED", 2);
            } else {
                log_event("CLEARED", 2);
            }
            sensor2_prev_state = sensor2_state;
        }

        usleep(DEBOUNCE_TIME * 1000);
    }

    if (fclose(fopen(LOG_FILE, "a")) != 0) {
        perror("fclose");
    }

    gpioTerminate();
    return 0;
}

