#define I2C_SLAVE 0x0703
#define I2C_RDWR 0x0706
#define I2C_TIMEOUT 50 // ms

#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

#define CSV_FILE "distance_log.csv"

// Helper function to perform an I2C register read using a combined write-then-read transaction
uint16_t i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C bus: %d\n", errno);
        return 0;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C bus: %d\n", errno);
        return 0;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to log data to a CSV file
void log_data(double timestamp, uint16_t distance_mm) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening CSV file: %d\n", errno);
        return;
    }
    fprintf(fp, "%f,%d\n", timestamp, distance_mm);
    fclose(fp);
}

// Signal handler for clean shutdown
void sigint_handler(int sig) {
    close(i2c_fd);
    fclose(fp);
    exit(0);
}

