        fprintf(stderr, "Error setting I2C slave address: %d\n", errno);
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening CSV file: %d\n", errno);
        close(i2c_fd);
        return 1;
    }

