#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MLX75030_ADDRESS 0x4C
#define MLX75030_REG_DISTANCE 0x00
#define MLX75030_REG_STATUS 0x01
#define MLX75030_REG_ECHO 0x02
#define MLX75030_REG_CONFIG 0x03
#define MLX75030_REG_STATUS_MASK 0x01

#define MAX_RETRIES 3
#define RETRY_DELAY 10

void sigint_handler(int sig) {
    printf("\nCaught SIGINT, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    int gpio_init_result = gpioInitialise();
    if (gpio_init_result < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_init_result);
        return 1;
    }

    int i2c_bus = gpioOpen(1, 1);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %d\n", i2c_bus);
        gpioTerminate();
        return 1;
    }

    int i2c_address = MLX75030_ADDRESS;
    int retries = 0;
    while (gpioI2CSetup(i2c_bus, i2c_address) < 0 && retries < MAX_RETRIES) {
        usleep(RETRY_DELAY * 1000);
        retries++;
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to set up I2C bus 1 for address 0x%02X after %d retries\n", i2c_address, MAX_RETRIES);
        gpioClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    while (1) {
        int retries = 0;
        uint16_t distance = 0;
        while (gpioI2CReadReg8(i2c_bus, i2c_address, MLX75030_REG_DISTANCE, &distance, 2) < 0 && retries < MAX_RETRIES) {
            usleep(RETRY_DELAY * 1000);
            retries++;
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read distance from MLX75030 after %d retries\n", MAX_RETRIES);
            break;
        }

        if (gpioI2CReadReg8(i2c_bus, i2c_address, MLX75030_REG_STATUS, NULL, 1) < 0) {
            fprintf(stderr, "Failed to read status from MLX75030\n");
            break;
        }

        if ((gpioI2CReadReg8(i2c_bus, i2c_address, MLX75030_REG_STATUS, NULL, 1) & MLX75030_REG_STATUS_MASK) == 0) {
            fprintf(stderr, "MLX75030 status register indicates sensor-absent or bus-error\n");
            break;
        }

        printf("%d ms: distance = %d mm\n", (int)time(NULL) * 1000, distance);
        usleep(100000);
    }

    gpioI2CClose(i2c_bus);
    gpioTerminate();
    return 0;
}

