#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define VL53L4CX_I2C_ADDRESS 0x29
#define VL53L4CX_SOFT_RESET_REG 0x7FFF
#define VL53L4CX_START_REG 0x0009
#define VL53L4CX_INTERRUPT_STATUS_REG 0x0046
#define VL53L4CX_DISTANCE_HIGH_REG 0x0096
#define VL53L4CX_DISTANCE_LOW_REG 0x0097

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(i2c_fd));
        return 1;
    }

    int i2c_bus = i2cOpen(i2c_fd, 1);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", i2cErrorStr(i2c_bus));
        gpioTerminate();
        return 1;
    }

    if (i2cSetSlaveAddress(i2c_bus, VL53L4CX_I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", i2cErrorStr(i2c_bus));
        i2cClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByte(i2c_bus, VL53L4CX_SOFT_RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to perform soft reset: %s\n", i2cErrorStr(i2c_bus));
        i2cClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    usleep(10000);

    if (i2cWriteByte(i2c_bus, VL53L4CX_START_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to start ranging: %s\n", i2cErrorStr(i2c_bus));
        i2cClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        if (i2cWriteByte(i2c_bus, VL53L4CX_INTERRUPT_STATUS_REG, 0x00) < 0) {
            fprintf(stderr, "Failed to clear interrupt status: %s\n", i2cErrorStr(i2c_bus));
            continue;
        }

        usleep(500000);

        uint8_t status = i2cReadByte(i2c_bus, VL53L4CX_INTERRUPT_STATUS_REG);
        if (status < 0) {
            fprintf(stderr, "Failed to read interrupt status: %s\n", i2cErrorStr(i2c_bus));
            continue;
        }

        if (status & 0x01) {
            uint16_t distance = (i2cReadByte(i2c_bus, VL53L4CX_DISTANCE_HIGH_REG) << 8) | i2cReadByte(i2c_bus, VL53L4CX_DISTANCE_LOW_REG);
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%06d", localtime(&now));
            printf("%s, Distance: %d mm\n", timestamp, distance);
        }
    }

    i2cClose(i2c_bus);
    gpioTerminate();
    return 0;
}

