#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Function to handle SIGINT signal for clean shutdown
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Set up GPIO pin 22 as output for the buzzer
    if (gpioSetMode(22, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pin 22\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C bus 1
    if (gpioI2COpen(1, 1, NULL) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up VL53L1X time-of-flight sensor
    int fd = gpioI2COpen(1, 0x29, NULL);
    if (fd < 0) {
        fprintf(stderr, "Failed to open VL53L1X sensor\n");
        gpioI2CClose(1);
        gpioTerminate();
        return 1;
    }

    // Configure sensor for continuous ranging mode
    if (i2cWriteReg8(fd, 0x0001, 0x01) < 0) {
        fprintf(stderr, "Failed to configure sensor for continuous ranging mode\n");
        gpioI2CClose(fd);
        gpioI2CClose(1);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteReg8(fd, 0x0007, 0x07) < 0) {
        fprintf(stderr, "Failed to set system mode\n");
        gpioI2CClose(fd);
        gpioI2CClose(1);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance from sensor
        uint16_t distance;
        if (i2cReadReg16(fd, 0x0096, &distance) < 0) {
            fprintf(stderr, "Failed to read distance from sensor\n");
            gpioI2CClose(fd);
            gpioI2CClose(1);
            gpioTerminate();
            return 1;
        }

        // Check if distance is below 100 mm
        if (distance < 100) {
            // Activate buzzer
            gpioWrite(22, 1);
        } else {
            // Deactivate buzzer
            gpioWrite(22, 0);
        }

        // Wait 500 ms before next measurement
        usleep(500000);
    }

    // Clean up
    gpioI2CClose(fd);
    gpioI2CClose(1);
    gpioTerminate();
    return 0;
}

