        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0 || gpioSetMode(GPIO_ECHO, PI_INPUT) < 0) {
