    signal(SIGTERM, sigterm_handler);

    gpioWrite(GPIO_SERVO, 0);

    while (running) {
        gpioWrite(GPIO_TRIGGER, 1);
        usleep(10);
        gpioWrite(GPIO_TRIGGER, 0);

