        uint32_t end_time = 0;
        bool timeout = false;

        while (gpioRead(GPIO_ECHO) == 1 && !timeout) {
            end_time = gpioGetTicks(GPIO_ECHO);
            if (end_time - start_time > TIMEOUT) {
                timeout = true;
            }
            usleep(1);
        }

        if (timeout) {
            log_distance(-1.0);
            continue;
        }

        double distance = (end_time - start_time) * SPEED_OF_SOUND / 2.0;
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            log_distance(-1.0);
            continue;
        }

        double angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) + SERVO_MIN_PULSE;
        gpioWrite(GPIO_SERVO, 1);
        usleep((uint32_t)angle);
        gpioWrite(GPIO_SERVO, 0);

        log_distance(distance);

        usleep(LOG_INTERVAL);
    }

    gpioWrite(GPIO_SERVO, 0);
    gpioTerminate();

    return 0;
}

