#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>
#include <mqueue.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define VL53L1X_MODEL_ID 0xEA
#define VL53L1X_RESET_REG 0x0000
#define VL53L1X_MODEL_ID_REG 0x010F
#define VL53L1X_TIMING_BUDGET_REG 0x0080
#define VL53L1X_DATA_READY_REG 0x0089
#define VL53L1X_DISTANCE_REG 0x0096
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL 50

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    mqd_t mq = -1;
    char *mq_name = "/vl53l1x_distance";
    char buffer[20];

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    i2c_fd = pigpio_i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        perror("pigpio_i2c_open");
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize message queue
    mq = mq_open(mq_name, O_RDWR | O_CREAT, 0644, sizeof(int));
    if (mq < 0) {
        perror("mq_open");
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Check sensor model ID
    uint8_t model_id;
    if (pigpio_i2c_read_byte(i2c_fd, VL53L1X_MODEL_ID_REG, &model_id) < 0) {
        perror("pigpio_i2c_read_byte");
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }
    if (model_id != VL53L1X_MODEL_ID) {
        fprintf(stderr, "Invalid sensor model ID 0x%02x\n", model_id);
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Software reset
    if (pigpio_i2c_write_byte(i2c_fd, VL53L1X_RESET_REG, 0x00) < 0) {
        perror("pigpio_i2c_write_byte");
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }
    if (pigpio_i2c_write_byte(i2c_fd, VL53L1X_RESET_REG, 0x01) < 0) {
        perror("pigpio_i2c_write_byte");
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Configure timing budget
    uint8_t timing_budget = 0x32; // 50 ms
    if (pigpio_i2c_write_byte(i2c_fd, VL53L1X_TIMING_BUDGET_REG, timing_budget) < 0) {
        perror("pigpio_i2c_write_byte");
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Start ranging
    if (pigpio_i2c_write_byte(i2c_fd, VL53L1X_TIMING_BUDGET_REG, 0x01) < 0) {
        perror("pigpio_i2c_write_byte");
        mq_close(mq);
        pigpio_i2c_close(i2c_fd);
        gpioTerminate(gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Poll data-ready bit
        uint8_t data_ready;
        if (pigpio_i2c_read_byte(i2c_fd, VL53L1X_DATA_READY_REG, &data_ready) < 0) {
            perror("pigpio_i2c_read_byte");
            mq_close(mq);
            pigpio_i2c_close(i2c_fd);
            gpioTerminate(gpio_fd);
            exit(EXIT_FAILURE);
        }
        if (data_ready == 0) {
            usleep(POLL_INTERVAL * 1000);
            continue;
        }

        // Read distance
        uint16_t distance;
        if (pigpio_i2c_read_word(i2c_fd, VL53L1X_DISTANCE_REG, &distance) < 0) {
            perror("pigpio_i2c_read_word");
            mq_close(mq);
            pigpio_i2c_close(i2c_fd);
            gpioTerminate(gpio_fd);
            exit(EXIT_FAILURE);
        }

        // Log distance
        if (mq_send(mq, &distance, sizeof(distance), 0) < 0) {
            perror("mq_send");
            mq_close(mq);
            pigpio_i2c_close(i2c_fd);
            gpioTerminate(gpio_fd);
            exit(EXIT_FAILURE);
        }

        // Activate buzzer if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            if (gpioWrite(gpio_fd, BUZZER_GPIO, 1) < 0) {
                perror("gpioWrite");
                mq_close(mq);
                pigpio_i2c_close(i2c_fd);
                gpioTerminate(gpio_fd);
                exit(EXIT_FAILURE);
            }
            usleep(100000);
            if (gpioWrite(gpio_fd, BUZZER_GPIO, 0) < 0) {
                perror("gpioWrite");
                mq_close(mq);
                pigpio_i2c_close(i2c_fd);
                gpioTerminate(gpio_fd);
                exit(EXIT_FAILURE);
            }
        }

        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    mq_close(mq);
    pigpio_i2c_close(i2c_fd);
    gpioTerminate(gpio_fd);
    return 0;
}

