            gpioSetAlertFuncEx(ECHO_GPIO, alert_handler, NULL);
        } else {
            uint32_t start_tick = tick;
            while (gpioRead(ECHO_GPIO) == 1) {
                tick = gpioTick();
            }
            uint32_t end_tick = tick;
            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > 0) {
                distance = (int) (pulse_width * SPEED_OF_SOUND / 2.0);
                if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                    if (distance < 30 && !buzzer_on) {
                        gpioWrite(BUZZER_GPIO, 1);
                        buzzer_on = 1;
                    } else if (distance >= 30 && buzzer_on) {
                        gpioWrite(BUZZER_GPIO, 0);
                        buzzer_on = 0;
                    }
                    printf("Distance: %d cm\n", distance);
                } else {
                    printf("Invalid reading: %d cm\n", distance);
                }
            } else {
                printf("Sensor absent\n");
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for trigger GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for echo GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_GPIO, alert_handler, NULL) < 0) {
        fprintf(stderr, "Failed to register alert handler for echo GPIO\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        usleep(UPDATE_INTERVAL * 1000);
    }

    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();

    return 0;
}
