#define TRIG_PIN 23
#define ECHO_PIN 24
#define MEASUREMENT_INTERVAL_US 200000
#define MAX_MEASUREMENTS 2
#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define MIN_PULSE_WIDTH_US 100
#define MAX_PULSE_WIDTH_US 30000

// Function to handle SIGINT and SIGTERM signals
void sigint_handler(int sig) {
    // Close the log file
    fclose(log_file);
    // Release GPIO resources
    gpioTerminate();
    // Exit cleanly
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(gpioInitialise()));
        exit(1);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin mode: %s\n", gpioErrorStr(gpioSetMode(TRIG_PIN, PI_OUTPUT)));
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO pin mode: %s\n", gpioErrorStr(gpioSetMode(ECHO_PIN, PI_INPUT)));
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set ECHO pin pull-up/down control: %s\n", gpioErrorStr(gpioSetPullUpDnControl(ECHO_PIN, PI_PUD_DOWN)));
        gpioTerminate();
        exit(1);
    }

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Initialize variables
    uint32_t last_measurement_time = 0;
    uint32_t last_echo_time = 0;
    uint32_t last_rising_edge_time = 0;
    uint32_t last_falling_edge_time = 0;
    bool valid_measurement = false;

    // Main loop
    while (1) {
        // Generate a 10 microsecond trigger pulse
        if (gpioWrite(TRIG_PIN, 1) < 0) {
            fprintf(stderr, "Failed to set TRIG pin high: %s\n", gpioErrorStr(gpioWrite(TRIG_PIN, 1)));
            break;
        }
        usleep(10);
        if (gpioWrite(TRIG_PIN, 0) < 0) {
            fprintf(stderr, "Failed to set TRIG pin low: %s\n", gpioErrorStr(gpioWrite(TRIG_PIN, 0)));
            break;
        }

        // Wait for an echo
        uint32_t current_time = gpioTick();
        if (current_time - last_measurement_time < 60000) {
            // If no valid echo is received within 60 ms, log a timeout warning
            fprintf(stderr, "Timeout warning: no valid echo received within 60 ms\n");
            continue;
        }
        last_measurement_time = current_time;

        // Register an alert callback on ECHO
        if (gpioSetAlertFunc(ECHO_PIN, alert_callback, NULL) < 0) {
            fprintf(stderr, "Failed to set alert callback on ECHO pin: %s\n", gpioErrorStr(gpioSetAlertFunc(ECHO_PIN, alert_callback, NULL)));
            break;
        }

        // Wait for an echo
        while (1) {
            // Check if a valid measurement has been received
            if (valid_measurement) {
                // Calculate distance
                uint32_t pulse_width = (last_falling_edge_time - last_rising_edge_time);
                if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
                    // Reject readings below 100 microseconds as noise or above 30000 microseconds as a timeout/no object detected
                    fprintf(stderr, "Warning: rejected reading of %u microseconds\n", pulse_width);
                    valid_measurement = false;
                    continue;
                }
                double distance = (pulse_width / 2.0) * SPEED_OF_SOUND_CM_PER_US;
                // Log valid readings with an ISO 8601 timestamp
                char timestamp[32];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
                fprintf(log_file, "%s %.2f cm\n", timestamp, distance);
                fflush(log_file);
                valid_measurement = false;
            }
            // Check if the alert callback has been triggered
            if (gpioGetAlertFunc(ECHO_PIN) == alert_callback) {
                // Get the alert data
                uint32_t rising_edge_time = gpioGetAlertData(ECHO_PIN);
                uint32_t falling_edge_time = gpioGetAlertData(ECHO_PIN);
                // Update the last rising and falling edge times
                last_rising_edge_time = rising_edge_time;
                last_falling_edge_time = falling_edge_time;
                // Set the alert callback to NULL to prevent multiple triggers
                gpioSetAlertFunc(ECHO_PIN, NULL, NULL);
                valid_measurement = true;
            }
            // Check if the measurement has timed out
            if (current_time - last_measurement_time > MEASUREMENT_INTERVAL_US) {
                break;
            }
        }

        // Deregister the alert callback
        gpioSetAlertFunc(ECHO_PIN, NULL, NULL);
    }

    // Close the log file
    fclose(log_file);
    // Release GPIO resources
    gpioTerminate();
    return 0;
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick) {
    // Store the rising and falling edge times
    if (level == 1) {
        last_rising_edge_time = tick;
    } else {
        last_falling_edge_time = tick;
    }
}
