void log_gate_state(double distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(file, "%ld.%06ld: Gate state changed. Distance: %.2f cm\n", tv.tv_sec, tv.tv_usec, distance);
    fclose(file);
}

