#define VL53L1X_ADDRESS 0x29
#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_START_MEASUREMENT 0x0000
#define VL53L1X_REG_DISTANCE 0x0096
#define VL53L1X_REG_DISTANCE_MSB 0x0096
#define VL53L1X_REG_DISTANCE_LSB 0x0097
#define VL53L1X_REG_DATA_READY 0x0089
#define GPIO_TRIGGER 24
#define GPIO_MOTOR_FORWARD 17
#define GPIO_MOTOR_BACKWARD 18
#define DISTANCE_THRESHOLD_FORWARD 100
#define DISTANCE_THRESHOLD_BACKWARD 300

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void i2c_transaction(int fd, uint8_t reg, uint8_t* data, size_t len) {
    int ret;
    for (int i = 0; i < 5; i++) {
        ret = i2c_smbus_write_byte_data(fd, reg, data[0]);
        if (ret == 0) {
            break;
        }
        usleep(100000 * (1 << i));
    }
    if (ret != 0) {
        fprintf(stderr, "I2C write failed: %d\n", ret);
        exit(1);
    }
    for (size_t j = 1; j < len; j++) {
        ret = i2c_smbus_write_byte_data(fd, reg + j, data[j]);
        if (ret != 0) {
            fprintf(stderr, "I2C write failed: %d\n", ret);
            exit(1);
        }
    }
}

void i2c_read_transaction(int fd, uint8_t reg, uint8_t* data, size_t len) {
    int ret;
    for (int i = 0; i < 5; i++) {
        ret = i2c_smbus_read_byte_data(fd, reg);
        if (ret >= 0) {
            break;
        }
        usleep(100000 * (1 << i));
    }
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %d\n", ret);
        exit(1);
    }
    data[0] = ret;
    for (size_t j = 1; j < len; j++) {
        ret = i2c_smbus_read_byte_data(fd, reg + j);
        if (ret < 0) {
            fprintf(stderr, "I2C read failed: %d\n", ret);
            exit(1);
        }
        data[j] = ret;
    }
}

