// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    gpiod_close_all();
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

// Function to read a byte from the MPR121 sensor
uint8_t read_byte(uint8_t reg) {
    uint8_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return 0;
    }
    if (i2c_smbus_write_byte(i2c_fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        return 0;
    }
    if (i2c_smbus_read_byte(i2c_fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        return 0;
    }
    return data;
}

// Function to write a byte to the MPR121 sensor
void write_byte(uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        return;
    }
    if (i2c_smbus_write_byte_data(i2c_fd, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
    }
}

