#define MPR121_ADDRESS 0x5A
#define ELECTRODE_0 0
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x05
#define LED_PIN 27
#define LOG_FILE "proximity.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    gpioSetMode(LED_PIN, GPIO_OUTPUT);

    int fd = i2cOpen(1, MPR121_ADDRESS);
    if (fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    uint8_t device_id;
    if (i2cRead(fd, 0x00, &device_id, 1) != 1) {
        perror("i2cRead");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (device_id != 0x5A) {
        fprintf(stderr, "MPR121 device ID mismatch\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Write touch and release thresholds
    if (i2cWrite(fd, 0x02, &TOUCH_THRESHOLD, 1) != 1) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x03, &RELEASE_THRESHOLD, 1) != 1) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 registers
    if (i2cWrite(fd, 0x04, &TOUCH_THRESHOLD, 1) != 1) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x05, &RELEASE_THRESHOLD, 1) != 1) {
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x06, 0x00, 1) != 1) { // FFI
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x07, 0x00, 1) != 1) { // SFI
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x08, 0x00, 1) != 1) { // ESI
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x09, 0x00, 1) != 1) { // debounce
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x0A, 0x00, 1) != 1) { // AFE config
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }
    if (i2cWrite(fd, 0x0B, 0x00, 1) != 1) { // baseline filtering
        perror("i2cWrite");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        uint8_t status;
        if (i2cRead(fd, 0x00, &status, 1) != 1) {
            perror("i2cRead");
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }
        if (status & (1 << ELECTRODE_0)) {
            log_event("Proximity detected on electrode 0 at ");
            log_event(ctime(&time(0)));
            gpioWrite(LED_PIN, 1);
            sleep(1);
            gpioWrite(LED_PIN, 0);
        }
        usleep(100000); // 100ms
    }

    i2cClose(fd);
    gpioTerminate();
    return 0;
