#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define TRIG_PIN 17
#define ECHO_PIN 18
#define TRIGGER_US 10
#define LOG_FILE "distance_log.txt"

// Define the ISR callback function
void echoISR(int gpio, int level, uint32_t tick) {
    static uint32_t lastTick = 0;
    if (level == 1) {
        lastTick = tick;
    } else if (level == 0 && lastTick != 0) {
        uint32_t pulseWidth = tick - lastTick;
        if (pulseWidth > 0 && pulseWidth < 25000) {
            char buffer[32];
            time_t now = time(NULL);
            strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
            FILE *logFile = fopen(LOG_FILE, "a");
            if (logFile != NULL) {
                fprintf(logFile, "%s %.3f\n", buffer, (double) pulseWidth * 343 / 2e6);
                fclose(logFile);
            }
        }
        lastTick = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the trigger pin as an output
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up trigger pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up the echo pin as an input with interrupt-driven ISR
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up echo pin\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echoISR, NULL) < 0) {
        fprintf(stderr, "Failed to set up ISR\n");
        gpioTerminate();
        return 1;
    }

    // Install a SIGINT/SIGTERM handler for clean shutdown
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT/SIGTERM handler\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Fire a 10 microsecond trigger pulse
        gpioWrite(TRIG_PIN, 1);
        usleep(TRIGGER_US);
        gpioWrite(TRIG_PIN, 0);
        usleep(1000000 - TRIGGER_US); // Wait for 1 second

        // Check for SIGINT/SIGTERM
        if (sigpending(&sa) & (SIGINT | SIGTERM)) {
            break;
        }
    }

    // Disable the ISR and close the log file
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile != NULL) {
        fclose(logFile);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

