#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_TRIGGER 27
#define REG_CONTINUOUS_MODE 0x0018
#define REG_TIMEOUT 0x0019
#define REG_START_RANGING 0x0020
#define REG_DISTANCE 0x0014
#define REG_STATUS 0x0016

int main() {
    int i2c_fd;
    int gpio_fd;
    int ret;

    // Set up syslog
    openlog(NULL, LOG_PID, LOG_USER);

    // Initialize pigpio
    if ((ret = gpioInitialise()) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %d", ret);
        exit(EXIT_FAILURE);
    }

    // Set up GPIO27 as an output and set it high
    if ((ret = gpioSetMode(GPIO_TRIGGER, PI_OUTPUT)) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode: %d", ret);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if ((ret = gpioWrite(GPIO_TRIGGER, 1)) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO value: %d", ret);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open I2C device
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    if ((i2c_fd = open(i2c_dev_path, O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", errno);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up I2C device
    if ((ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS)) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %d", errno);
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize VL53L1X sensor
    uint8_t data[2];
    data[0] = 0x00;
    data[1] = 0x00;
    if ((ret = i2c_smbus_write_byte_data(i2c_fd, REG_CONTINUOUS_MODE, data[0])) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x%02x: %d", REG_CONTINUOUS_MODE, errno);
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if ((ret = i2c_smbus_write_byte_data(i2c_fd, REG_TIMEOUT, data[0])) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x%02x: %d", REG_TIMEOUT, errno);
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    data[0] = 0x01;
    if ((ret = i2c_smbus_write_byte_data(i2c_fd, REG_START_RANGING, data[0])) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x%02x: %d", REG_START_RANGING, errno);
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read distance and status
        if ((ret = i2c_smbus_read_i2c_block_data(i2c_fd, REG_DISTANCE, 2, data)) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x%02x: %d", REG_DISTANCE, errno);
            continue;
        }
        uint16_t distance = (data[0] << 8) | data[1];
        if ((ret = i2c_smbus_read_byte(i2c_fd, REG_STATUS)) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x%02x: %d", REG_STATUS, errno);
            continue;
        }
        uint8_t status = data[0];

        // Log data
        syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: 0x%02x", time(NULL), distance, status);

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

