        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Read distance and status
        if ((ret = i2c_smbus_read_i2c_block_data(i2c_fd, REG_DISTANCE, 2, data)) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x%02x: %d", REG_DISTANCE, errno);
            continue;
        }
        uint16_t distance = (data[0] << 8) | data[1];
        if ((ret = i2c_smbus_read_byte(i2c_fd, REG_STATUS)) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x%02x: %d", REG_STATUS, errno);
            continue;
        }
        uint8_t status = data[0];

        // Log data
        syslog(LOG_INFO, "Timestamp: %ld, Distance: %d mm, Status: 0x%02x", time(NULL), distance, status);

        // Wait 100 ms
        usleep(100000);
    }

    // Clean up
    close(i2c_fd);
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}
