#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_SERVO 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define SAMPLES 5
#define TIMEOUT 30000
#define SPEED_OF_SOUND 34300
#define CSV_FILE "distance_log.csv"

volatile sig_atomic_t stop = 0;

double distance_log[SAMPLES];
int distance_index = 0;
int distance_count = 0;
double distance_sum = 0.0;
double distance_avg = 0.0;
double servo_angle = 90.0;
bool pulse_width_valid = false;
uint32_t pulse_width = 0;

void alert_handler(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        pulse_width_valid = true;
    }
}

void sigint_handler(int sig) {
    stop = 1;
}

int main() {
    int fd;
    FILE *fp;
    int ret;

    // Initialize GPIO
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", ret);
        return 1;
    }

    // Set up GPIO modes
    if ((ret = gpioSetMode(GPIO_TRIGGER, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetMode(GPIO_ECHO, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetMode(GPIO_SERVO, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    // Set up servo
    if ((ret = gpioServo(GPIO_SERVO, SERVO_CENTER)) < 0) {
        fprintf(stderr, "Failed to set servo position: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    // Set up alert callback
    if ((ret = gpioSetAlertFunc(GPIO_ECHO, alert_handler, NULL)) < 0) {
        fprintf(stderr, "Failed to set alert callback: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    if ((fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644)) < 0) {
        fprintf(stderr, "Failed to open CSV file: %d\n", fd);
        gpioTerminate();
        return 1;
    }
    fp = fdopen(fd, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file: %d\n", fd);
        close(fd);
        gpioTerminate();
        return 1;
    }

    // Write header row
    fprintf(fp, "timestamp,distance,angle\n");

    while (!stop) {
        // Trigger ultrasonic sensor
        if ((ret = gpioWrite(GPIO_TRIGGER, 1)) < 0) {
            fprintf(stderr, "Failed to set GPIO: %d\n", ret);
            break;
        }
        usleep(10);
        if ((ret = gpioWrite(GPIO_TRIGGER, 0)) < 0) {
            fprintf(stderr, "Failed to set GPIO: %d\n", ret);
            break;
        }

        // Wait for echo
        if ((ret = gpioSetAlertThreshold(GPIO_ECHO, 1, TIMEOUT)) < 0) {
            fprintf(stderr, "Failed to set alert threshold: %d\n", ret);
            break;
        }
        while (pulse_width_valid == false && !stop) {
            usleep(100);
        }
        pulse_width_valid = false;

        // Calculate distance
        if (pulse_width == 0) {
            distance_log[distance_index] = -1.0;
        } else {
            double distance = (pulse_width * 2.0) / 2.0 / (SPEED_OF_SOUND / 1000000.0);
            if (distance < 2.0 || distance > 400.0) {
                distance_log[distance_index] = -1.0;
            } else {
                distance_log[distance_index] = distance;
                distance_sum += distance;
                distance_count++;
                if (distance_count >= SAMPLES) {
                    distance_avg = distance_sum / SAMPLES;
                    distance_count = 0;
                    distance_sum = 0.0;
                }
            }
        }

        // Map distance to servo angle
        if (distance_log[distance_index] == -1.0) {
            servo_angle = 90.0;
        } else {
            servo_angle = 90.0 + (log(distance_log[distance_index] / 2.0 + 1.0) * 90.0);
        }

        // Command servo
        if ((ret = gpioServo(GPIO_SERVO, (int) (servo_angle * (SERVO_MAX - SERVO_MIN) / 180.0 + SERVO_MIN))) < 0) {
            fprintf(stderr, "Failed to set servo position: %d\n", ret);
            break;
        }

        // Write to CSV file
        fprintf(fp, "%lu,%f,%f\n", (unsigned long) time(NULL), distance_log[distance_index], servo_angle);
        fflush(fp);

        // Wait for next measurement
        usleep(100000);
    }

    // Close CSV file
    fclose(fp);
    close(fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

