#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define SAMPLE_RATE 50  // ms
#define WARNING_THRESHOLD 200  // mm

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    i2cClose(I2C_BUS);
    exit(0);
}

void init_sensor() {
    int ret = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (ret < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", ret);
        exit(1);
    }

    // Set default configuration
    uint8_t config = 0x00;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to write default configuration: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }

    // Enable signal rate check
    config = 0x01;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable signal rate check: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }

    // Configure cross-talk compensation
    config = 0x02;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure cross-talk compensation: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }

    // Start ranging
    config = 0x03;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start ranging: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }
}

void read_distance() {
    uint16_t distance;
    int ret = i2cReadReg16(I2C_BUS, 0x00, &distance, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read distance: %d\n");
        return;
    }
    printf("Distance: %d mm\n", distance);
    if (distance < WARNING_THRESHOLD) {
        gpioWrite(GPIO_LED, 1);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %d\n", gpioInitialise());
        exit(1);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    signal(SIGINT, sigint_handler);

    init_sensor();

    uint16_t buffer[BUFFER_SIZE];
    int head = 0;
    int tail = 0;

    while (running) {
        read_distance();
        buffer[tail] = head == BUFFER_SIZE - 1 ? 0 : head + 1;
        tail = (tail + 1) % BUFFER_SIZE;
        if (head == tail) {
            head = 0;
        }
        usleep(SAMPLE_RATE * 1000);
    }

    gpioTerminate();
    i2cClose(I2C_BUS);
    return 0;
}

