    // Enable signal rate check
    config = 0x01;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to enable signal rate check: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }

    // Configure cross-talk compensation
    config = 0x02;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure cross-talk compensation: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }

    // Start ranging
    config = 0x03;
    ret = i2cWriteReg8(I2C_BUS, 0x00, &config, 1);
    if (ret < 0) {
        fprintf(stderr, "Failed to start ranging: %d\n", ret);
        i2cClose(I2C_BUS);
        exit(1);
    }
}

void read_distance() {
    uint16_t distance;
    int ret = i2cReadReg16(I2C_BUS, 0x00, &distance, 2);
    if (ret < 0) {
        fprintf(stderr, "Failed to read distance: %d\n");
        return;
    }
    printf("Distance: %d mm\n", distance);
    if (distance < WARNING_THRESHOLD) {
        gpioWrite(GPIO_LED, 1);
    } else {
        gpioWrite(GPIO_LED, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %d\n", gpioInitialise());
        exit(1);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    signal(SIGINT, sigint_handler);

    init_sensor();

    uint16_t buffer[BUFFER_SIZE];
    int head = 0;
    int tail = 0;

    while (running) {
        read_distance();
        buffer[tail] = head == BUFFER_SIZE - 1 ? 0 : head + 1;
        tail = (tail + 1) % BUFFER_SIZE;
        if (head == tail) {
            head = 0;
        }
        usleep(SAMPLE_RATE * 1000);
    }

    gpioTerminate();
    i2cClose(I2C_BUS);
    return 0;
}
```

This code uses the pigpio library to interface with the VL53L1X time-of-flight sensor over I2C bus 1 at address 0x29. It follows the recommended STMicroelectronics sequence to initialise the sensor and continuously reads distance measurements in millimeters every 50 ms. The last 10 readings are stored in a circular buffer. If any reading falls below 200 mm, it sets GPIO17 HIGH to activate a warning LED, otherwise it sets it LOW. The code also installs a SIGINT handler to turn off the LED, close the I2C handle, and terminate pigpio when the user presses Ctrl+C.

