#define DEFAULT_THRESHOLD 1000

// Flag to indicate if the program should exit
volatile bool exit_program = false;

// Flag to indicate if an interrupt has occurred
volatile bool interrupt_occurred = false;

// Queue to hold the interrupt data
char interrupt_data[256];

// Function to handle the interrupt
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Set the flag to indicate an interrupt has occurred
        interrupt_occurred = true;
    }
}

// Function to read the proximity value from the Si1102 sensor
int read_proximity(int i2c_fd) {
    uint16_t proximity;
    char buffer[2];

    // Read the high byte
    if (i2c_fd < 0) {
        perror("i2c_read");
        return -1;
    }
    if (i2c_read(i2c_fd, 0x08, 1, buffer, 1) != 1) {
        perror("i2c_read");
        return -1;
    }
    uint8_t high_byte = buffer[0];

    // Read the low byte
    if (i2c_fd < 0) {
        perror("i2c_read");
        return -1;
    }
    if (i2c_read(i2c_fd, 0x09, 1, buffer, 1) != 1) {
        perror("i2c_read");
        return -1;
    }
    uint8_t low_byte = buffer[0];

    // Combine the high and low bytes to form the 16-bit proximity value
    proximity = (high_byte << 8) | low_byte;

    return proximity;
}

// Function to log the proximity data
void log_proximity(int proximity, char *status) {
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity, status);
    fclose(log_file);
}

// Function to handle the SIGINT signal
void sigint_handler(int signal) {
    exit_program = true;
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int threshold = DEFAULT_THRESHOLD;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-a") == 0) {
            if (i + 1 < argc) {
                i2c_address = atoi(argv[++i]);
            } else {
                fprintf(stderr, "Error: missing argument for -a\n");
                return 1;
            }
        } else if (strcmp(argv[i], "-t") == 0) {
            if (i + 1 < argc) {
                threshold = atoi(argv[++i]);
            } else {
                fprintf(stderr, "Error: missing argument for -t\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Error: unknown argument '%s'\n", argv[i]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Initialize I2C
    int i2c_fd = i2cOpen(1, i2c_address);
    if (i2c_fd < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO27 as an interrupt pin
    if (gpioSetMode(27, PI_INPUT) < 0) {
        perror("gpioSetMode");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(27, PI_PUD_UP) < 0) {
        perror("gpioSetPullUpDnControl");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioISR(27, PI_RISING_EDGE, interrupt_handler) < 0) {
        perror("gpioISR");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up the interrupt handler to be thread-safe
    pthread_t thread;
    pthread_create(&thread, NULL, (void*)interrupt_handler, NULL);

    // Main loop
    while (!exit_program) {
        if (interrupt_occurred) {
            interrupt_occurred = false;
            int proximity = read_proximity(i2c_fd);
            if (proximity < 0) {
                perror("read_proximity");
                continue;
            }
            if (proximity > threshold) {
                log_proximity(proximity, "ALERT");
            } else {
                log_proximity(proximity, "SAFE");
            }
        }
        usleep(100000); // 100ms
    }

    // Clean up
    gpioISR(27, 0, NULL);
    gpioSetMode(27, PI_OUTPUT);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

