#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Stop PWM output
    if (gpioPWM(18, 0) != 0) {
        fprintf(stderr, "Error stopping PWM: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Terminate pigpio
    if (pigpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Exit cleanly
    exit(0);
}

int main() {
    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing signal handlers: %s\n", strerror(errno));
        exit(1);
    }

    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Set up GPIO pins
    if (gpioSetMode(18, PI_PWM) != 0 || gpioSetMode(23, PI_OUTPUT) != 0 || gpioSetMode(24, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting up GPIO: %s\n", pigpioErrorStr(errno));
        pigpioTerminate();
        exit(1);
    }

    // Set up PWM
    if (gpioPWM(18, 0) != 0) {
        fprintf(stderr, "Error setting up PWM: %s\n", pigpioErrorStr(errno));
        pigpioTerminate();
        exit(1);
    }

    // Set up HC-SR04
    int trigger = 23;
    int echo = 24;
    int timeout = 200000; // 200 ms
    int trigger_pulse = 10; // 10 us

    // Main loop
    while (1) {
        // Read distance
        int distance;
        if (gpioTrigger(trigger, PI_HIGH, trigger_pulse, echo, timeout, &distance, NULL) != 0) {
            // If echo times out, keep previous frequency
            continue;
        }

        // Map distance to frequency
        double frequency = 200 * exp(distance / 50.0);

        // Clamp frequency to valid range
        if (frequency < 200) {
            frequency = 200;
        } else if (frequency > 2000) {
            frequency = 2000;
        }

        // Set PWM frequency
        if (gpioPWM(18, (int)(frequency * 1000 / 2000)) != 0) {
            fprintf(stderr, "Error setting PWM frequency: %s\n", pigpioErrorStr(errno));
            break;
        }
    }

    // Clean up
    if (gpioPWM(18, 0) != 0) {
        fprintf(stderr, "Error stopping PWM: %s\n", pigpioErrorStr(errno));
    }
    pigpioTerminate();

    return 0;
}

