#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MIN_DIST 5
#define MAX_DIST 50
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BEEPER_PIN 18
#define DELAY_US 10
#define TIMEOUT_US 1000000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int pi = pigpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (pigpioSetMode(pi, TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin mode\n");
        pigpioCleanup(pi);
        return 1;
    }

    if (pigpioSetMode(pi, ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin mode\n");
        pigpioCleanup(pi);
        return 1;
    }

    if (pigpioSetPullUpDnControl(pi, ECHO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set echo pin pull-down\n");
        pigpioCleanup(pi);
        return 1;
    }

    if (pigpioHardwarePWM(pi, BEEPER_PIN, 0, 0) < 0) {
        fprintf(stderr, "Failed to set beeper pin PWM\n");
        pigpioCleanup(pi);
        return 1;
    }

    signal(SIGINT, sigint_handler);

    uint32_t last_distance = 0;
    uint32_t last_frequency = 0;

    while (running) {
        pigpioWrite(pi, TRIGGER_PIN, 1);
        usleep(10);
        pigpioWrite(pi, TRIGGER_PIN, 0);

        uint32_t start_time = pigpioGetTick();
        while (pigpioRead(pi, ECHO_PIN) == 1) {
            if (pigpioGetTick() - start_time > TIMEOUT_US) {
                fprintf(stderr, "Timeout reading echo pulse\n");
                last_distance = last_distance;
                break;
            }
        }

        uint32_t end_time = pigpioGetTick();
        uint32_t pulse_width = end_time - start_time;

        if (pulse_width == 0) {
            fprintf(stderr, "Failed to read echo pulse\n");
            last_distance = last_distance;
        } else {
            uint32_t distance = (pulse_width / 2) * 340 / 2; // speed of sound in cm/us
            if (distance < MIN_DIST || distance > MAX_DIST) {
                distance = last_distance;
            } else {
                last_distance = distance;
            }

            uint32_t frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DIST - distance) / (MAX_DIST - MIN_DIST);
            if (frequency < MIN_FREQ) {
                frequency = MIN_FREQ;
            } else if (frequency > MAX_FREQ) {
                frequency = MAX_FREQ;
            }

            if (last_frequency != frequency) {
                pigpioHardwarePWM(pi, BEEPER_PIN, 0, frequency);
                last_frequency = frequency;
            }

            printf("Distance: %u cm, Frequency: %u Hz\n", last_distance, last_frequency);
        }

        usleep(10000);
    }

    pigpioHardwarePWM(pi, BEEPER_PIN, 0, 0);
    pigpioCleanup(pi);
    return 0;
}

