#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_NO_CS 1
#define REG_CONTINUOUS_MODE 0x01
#define REG_RANGE_5M 0x00
#define REG_TRIGGER 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D
#define DISTANCE_MIN 200
#define DISTANCE_MAX 5000

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int spi = gpioInitialise();
    if (spi < 0) {
        fprintf(stderr, "Failed to initialise GPIO: %d\n", spi);
        return 1;
    }

    int cs = gpioOpen(GPIO_CE0, 1);
    if (cs < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %d\n", GPIO_CE0, cs);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_CE0, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", GPIO_CE0, gpioError());
        gpioClose(cs);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_CE0, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d high: %d\n", GPIO_CE0, gpioError());
        gpioClose(cs);
        gpioTerminate();
        return 1;
    }

    if (spiOpen(spi, GPIO_CE0, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST, SPI_NO_CS) < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", gpioError());
        gpioWrite(GPIO_CE0, 0);
        gpioClose(cs);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen("distance_log.csv", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %d\n", errno);
        spiClose(spi);
        gpioWrite(GPIO_CE0, 0);
        gpioClose(cs);
        gpioTerminate();
        return 1;
    }

    struct tm *timestamp;
    time_t now;
    char buffer[20];

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        if (gpioWrite(GPIO_CE0, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %d\n", GPIO_CE0, gpioError());
            continue;
        }

        uint8_t data[2];
        if (spiXfer(spi, REG_TRIGGER, 1, data, 2) < 0) {
            fprintf(stderr, "Failed to read from SPI: %d\n", gpioError());
            continue;
        }

        if (data[0] != REG_TRIGGER) {
            fprintf(stderr, "Invalid trigger response: %02x\n", data[0]);
            continue;
        }

        if (gpioWrite(GPIO_CE0, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %d\n", GPIO_CE0, gpioError());
            continue;
        }

        if (spiXfer(spi, REG_CONTINUOUS_MODE, 1, data, 1) < 0) {
            fprintf(stderr, "Failed to write to SPI: %d\n", gpioError());
            continue;
        }

        if (data[0] != REG_CONTINUOUS_MODE) {
            fprintf(stderr, "Invalid continuous mode response: %02x\n", data[0]);
            continue;
        }

        if (spiXfer(spi, REG_RANGE_5M, 1, data, 1) < 0) {
            fprintf(stderr, "Failed to write to SPI: %d\n", gpioError());
            continue;
        }

        if (data[0] != REG_RANGE_5M) {
            fprintf(stderr, "Invalid range response: %02x\n", data[0]);
            continue;
        }

        if (spiXfer(spi, REG_DISTANCE_LOW, 1, data, 1) < 0) {
            fprintf(stderr, "Failed to read from SPI: %d\n", gpioError());
            continue;
        }

        if (spiXfer(spi, REG_DISTANCE_HIGH, 1, data + 1, 1) < 0) {
            fprintf(stderr, "Failed to read from SPI: %d\n", gpioError());
            continue;
        }

        uint16_t distance = (data[1] << 8) | data[0];

        if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
            fprintf(stderr, "Invalid distance: %d\n", distance);
            continue;
        }

        time(&now);
        timestamp = localtime(&now);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timestamp);
        fprintf(log_file, "%s,%.3f\n", buffer, (double)distance / 10.0);

        usleep(100000);
    }

    fclose(log_file);
    spiClose(spi);
    gpioWrite(GPIO_CE0, 0);
    gpioClose(cs);
    gpioTerminate();

    return 0;
}

