#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x60
#define REG_AMBIENT_LIGHT_LOW 0x22
#define REG_AMBIENT_LIGHT_HIGH 0x23
#define LOG_FILE "proximity_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write header row to log file
    fprintf(log_file, "timestamp,als_visible\n");

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        fclose(log_file);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read ambient light value
        uint8_t low_byte;
        uint8_t high_byte;
        if (read(i2c_fd, &low_byte, 1) != 1) {
            if (errno == EIO) {
                // Sensor absent, log error and continue
                fprintf(stderr, "Error reading ambient light value: sensor absent\n");
            } else {
                perror("Failed to read ambient light value");
            }
            continue;
        }
        if (read(i2c_fd, &high_byte, 1) != 1) {
            if (errno == EIO) {
                // Sensor absent, log error and continue
                fprintf(stderr, "Error reading ambient light value: sensor absent\n");
            } else {
                perror("Failed to read ambient light value");
            }
            continue;
        }

        // Combine low and high bytes into 16-bit value
        uint16_t ambient_light = (high_byte << 8) | low_byte;

        // Log reading
        time_t timestamp = time(NULL);
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", localtime(&timestamp));
        fprintf(log_file, "%s,%d\n", timestamp_str, ambient_light);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Clean up
    fclose(log_file);
    close(i2c_fd);
    return 0;
}

