#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define SI1120_RESET 0x01
#define SI1120_PART_ID 0x41
#define SI1120_ALS_LOW 0x22
#define SI1120_ALS_HIGH 0x23
#define SI1120_PROX_LOW 0x18
#define SI1120_PROX_HIGH 0x19

#define MAX_RETRIES 3
#define RETRY_DELAY 10

void log_reading(int als, int prox, time_t timestamp) {
    FILE *log_file = fopen("si1120_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(1);
    }

    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(log_file, "%s, ALS: %d, Prox: %d\n", timestamp_str, als, prox);
    fclose(log_file);
}

int main() {
    int gpio = pigpioInitialise();
    if (gpio < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", pigpioErrorStr(gpio));
        return 1;
    }

    int i2c = gpioI2COpen(gpio, I2C_BUS);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpioErrorStr(i2c));
        pigpioTerminate();
        return 1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_RESET) >= 0) {
            break;
        }
        fprintf(stderr, "Failed to reset SI1120: %s\n", pigpioErrorStr(gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_RESET)));
        retries++;
        usleep(RETRY_DELAY * 1000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to reset SI1120 after %d retries\n", MAX_RETRIES);
        gpioI2CClose(i2c);
        pigpioTerminate();
        return 1;
    }

    retries = 0;
    while (retries < MAX_RETRIES) {
        if (gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_PART_ID) >= 0) {
            uint8_t part_id;
            if (gpioI2CReadByte(i2c, I2C_ADDRESS, &part_id) >= 0 && part_id == SI1120_PART_ID) {
                break;
            } else {
                fprintf(stderr, "Failed to read part ID: %s\n", pigpioErrorStr(gpioI2CReadByte(i2c, I2C_ADDRESS, &part_id)));
            }
        }
        fprintf(stderr, "Failed to write part ID: %s\n", pigpioErrorStr(gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_PART_ID)));
        retries++;
        usleep(RETRY_DELAY * 1000);
    }
    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to verify part ID after %d retries\n", MAX_RETRIES);
        gpioI2CClose(i2c);
        pigpioTerminate();
        return 1;
    }

    time_t start_time = time(NULL);
    while (1) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_ALS_LOW) >= 0) {
                break;
            }
            fprintf(stderr, "Failed to write ALS low byte: %s\n", pigpioErrorStr(gpioI2CWriteByte(i2c, I2C_ADDRESS, SI1120_ALS_LOW)));
