#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x39
#define MEASUREMENT_RATE 0x07
#define REG_PART_ID 0x00
#define REG_MEASUREMENT_RATE 0x08
#define REG_AMBIENT_LIGHT 0x22
#define REG_PROXIMITY 0x24
#define LOG_FILE "biometric_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;

void sigint_handler(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
}

void read_sensor() {
    uint8_t reg[2];
    uint16_t ambient_light;
    uint16_t proximity;

    if (read(i2c_fd, reg, 2) != 2) {
        perror("Failed to read from I2C bus");
        return;
    }

    if (reg[0] != 0x53) {
        fprintf(stderr, "Sensor not found or invalid part ID\n");
        return;
    }

    if (write(i2c_fd, &MEASUREMENT_RATE, 1) != 1) {
        perror("Failed to write to I2C bus");
        return;
    }

    if (read(i2c_fd, reg, 2) != 2) {
        perror("Failed to read from I2C bus");
        return;
    }

    ambient_light = (reg[0] << 8) | reg[1];
    proximity = (reg[1] << 8) | reg[0];

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, (int)(ambient_light * 0.1), proximity);
    printf("%s,%d,%d\n", timestamp, (int)(ambient_light * 0.1), proximity);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_i2c();
    init_log_file();

    while (1) {
        read_sensor();
        usleep(100000);
    }

    return 0;
}

