// Structure to hold the interrupt callback data
typedef struct {
    int rising_edge;
    int falling_edge;
} callback_data;

// Interrupt callback function
void callback(int gpio, int level, int tick) {
    static callback_data data;
    if (level == 1) {
        data.rising_edge = tick;
    } else {
        data.falling_edge = tick;
        int distance = (data.falling_edge - data.rising_edge) * 0.0343 / 2;
        if (distance < 20) {
            gpioWrite(27, 1);
        } else {
            gpioWrite(27, 0);
        }
        printf("Distance: %d cm\n", distance);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioStrerror(gpioError()));
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 mode: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO18 mode: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO27 mode: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(18, PI_FALSERISING_EDGE, callback, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO18 alert function: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Generate a 10 us trigger pulse
    if (gpioWrite(17, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO17 high: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }
    gpioDelay(10);
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "Failed to set GPIO17 low: %s\n", gpioStrerror(gpioError()));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Check for SIGINT
        if (signal(SIGINT, SIG_IGN) == SIG_IGN) {
            // SIGINT is already ignored
        } else if (signal(SIGINT, SIG_DFL) == SIG_ERR) {
            fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
            gpioTerminate();
            return 1;
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up on exit
    gpioTerminate();
    return 0;
}

