#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_GPIO 4
#define ECHO_GPIO 17
#define SERVO_GPIO 18
#define UPDATE_INTERVAL 100  // ms
#define MIN_DISTANCE 20
#define MAX_DISTANCE 200
#define MIN_SERVO_PULSE 500
#define MAX_SERVO_PULSE 2500
#define SERVO_PULSE_AT_110 1500

volatile int running = 1;

void cleanup(int sig) {
    running = 0;
    gpioServoWrite(SERVO_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for trigger GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for echo GPIO\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SERVO_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for servo GPIO\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, cleanup);

    while (running) {
        int distance = measureDistance();
        if (distance < 0) {
            fprintf(stderr, "Failed to measure distance\n");
            continue;
        }

        int servoPulse = (int)((double)(MAX_SERVO_PULSE - MIN_SERVO_PULSE) * (double)(MAX_DISTANCE - distance) / (double)MAX_DISTANCE + MIN_SERVO_PULSE);
        if (distance <= 110) {
            servoPulse = SERVO_PULSE_AT_110;
        } else if (distance <= MIN_DISTANCE) {
            servoPulse = MAX_SERVO_PULSE;
        }

        gpioServoWrite(SERVO_GPIO, servoPulse);

        printf("Distance: %.1f cm, Servo angle: %.1f degrees\n", distance, (double)(servoPulse - MIN_SERVO_PULSE) * 90.0 / (MAX_SERVO_PULSE - MIN_SERVO_PULSE));

        gpioDelay(UPDATE_INTERVAL * 1000);
    }

    return 0;
}

int measureDistance() {
    int count = 0;
    int timeout = 10000;  // 10 ms

    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_GPIO, 0);

    while (gpioRead(ECHO_GPIO) == 0 && count++ < timeout) {
        gpioDelay(1);
    }

    if (count >= timeout) {
        return -1.0;
    }

    count = 0;
    while (gpioRead(ECHO_GPIO) == 1 && count++ < timeout) {
        gpioDelay(1);
    }

    if (count >= timeout) {
        return -1.0;
    }

    int duration = count * 10;
    return (int)((double)duration * 170 / 58.0);
}

