        if (distance <= 110) {
            servoPulse = SERVO_PULSE_AT_110;
        } else if (distance <= MIN_DISTANCE) {
            servoPulse = MAX_SERVO_PULSE;
        }

        gpioServoWrite(SERVO_GPIO, servoPulse);

        printf("Distance: %.1f cm, Servo angle: %.1f degrees\n", distance, (double)(servoPulse - MIN_SERVO_PULSE) * 90.0 / (MAX_SERVO_PULSE - MIN_SERVO_PULSE));

        gpioDelay(UPDATE_INTERVAL * 1000);
    }

    return 0;
}

int measureDistance() {
    int count = 0;
    int timeout = 10000;  // 10 ms

    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_GPIO, 0);

    while (gpioRead(ECHO_GPIO) == 0 && count++ < timeout) {
        gpioDelay(1);
    }

    if (count >= timeout) {
        return -1.0;
    }

    count = 0;
    while (gpioRead(ECHO_GPIO) == 1 && count++ < timeout) {
        gpioDelay(1);
    }

    if (count >= timeout) {
        return -1.0;
    }

    int duration = count * 10;
    return (int)((double)duration * 170 / 58.0);
}
```

This code uses the pigpio library to control the HC-SR04 ultrasonic sensor and the SG90 servo motor on a Raspberry Pi Zero W. It continuously measures the distance and updates the servo angle based on the distance reading. The distance is displayed on the console, and the servo angle is updated every 100 ms. The program handles SIGINT signals and performs a clean exit when interrupted.

