#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define GATE_GPIO 18
#define SERVO_MIN 1000
#define SERVO_MAX 2000
#define DISTANCE_THRESHOLD_CLOSE 200
#define DISTANCE_THRESHOLD_FAR 250
#define LOG_FILE "gate_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int gpio_fd;
    int servo_fd;
    int distance;
    uint8_t model_id;
    uint16_t range_status;
    uint16_t distance_register;
    FILE *log_file;

    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize servo
    servo_fd = gpioServoCreate(GATE_GPIO);
    if (servo_fd < 0) {
        fprintf(stderr, "Failed to create servo: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioServoDestroy(servo_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X
    if (i2c_smbus_write_byte_data(i2c_fd, 0x010F, 0xEA) < 0) {
        fprintf(stderr, "Failed to write model ID: %s\n", strerror(errno));
        fclose(log_file);
        gpioServoDestroy(servo_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set timing budget
    if (i2c_smbus_write_byte_data(i2c_fd, 0x0200, 0x0A) < 0) {
        fprintf(stderr, "Failed to set timing budget: %s\n", strerror(errno));
        fclose(log_file);
        gpioServoDestroy(servo_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Start ranging
    if (i2c_smbus_write_byte_data(i2c_fd, 0x0201, 0x01) < 0) {
        fprintf(stderr, "Failed to start ranging: %s\n", strerror(errno));
        fclose(log_file);
        gpioServoDestroy(servo_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
