#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    gpioServo(18, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(23, PI_OUTPUT) < 0 || gpioSetMode(24, PI_INPUT) < 0 || gpioSetMode(18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Set up servo
    gpioServo(18, 500); // Initialize servo to 0 degrees

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Trigger the sensor
        if (gpioTick(23, 10, 50000) < 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue;
        }

        // Measure the echo pulse width
        int pulse_duration_us = gpioTick(24, 10, 50000);
        if (pulse_duration_us < 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            continue;
        }

        // Calculate distance
        double distance_cm = (pulse_duration_us * 0.0343) / 2;
        if (distance_cm <= 0) {
            distance_cm = 0;
        } else if (distance_cm >= 200) {
            distance_cm = 200;
        } else {
            distance_cm = (distance_cm - 20) / 180 * 160;
        }

        // Map distance to angle
        int angle = (int)distance_cm;

        // Ensure angle is within valid range
        if (angle < 0) {
            angle = 0;
        } else if (angle > 180) {
            angle = 180;
        }

        // Set servo angle
        gpioServo(18, angle * 10 + 500);

        // Print distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance_cm, angle);

        // Delay for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

