#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close I2C handle
    if (i2c_close(I2C_BUS_1) < 0) {
        perror("i2c_close");
    }

    // Terminate pigpio
    gpioTerminate();

    // Exit program
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open I2C bus 1
    int i2c_bus = i2cOpen(I2C_BUS_1, 0);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address for Si7005 sensor
    uint8_t address = 0x40;

    // Select internal temperature sensor and disable heater
    uint8_t config = 0x00;
    if (i2cWriteReg8(i2c_bus, address, 0x03, &config, 1) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2c_close(i2c_bus);
        gpioTerminate();
        return 1;
    }
    usleep(10000);

    // Wait for conversion to complete
    usleep(10000);

    // Read temperature register
    uint16_t temp_raw;
    if (i2cReadReg16(i2c_bus, address, 0x01, &temp_raw, 1) < 0) {
        fprintf(stderr, "Failed to read temperature register\n");
        i2c_close(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Read humidity register
    uint16_t humid_raw;
    if (i2cReadReg16(i2c_bus, address, 0x02, &humid_raw, 1) < 0) {
        fprintf(stderr, "Failed to read humidity register\n");
        i2c_close(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Convert readings
    float temp = (175.72 * temp_raw) / 65536.0 - 46.85;
    float humid = (125.0 * humid_raw) / 65536.0 - 6.0;

    // Print readings
    printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humid);

    // Main loop
    while (1) {
        // Select internal temperature sensor and disable heater
        if (i2cWriteReg8(i2c_bus, address, 0x03, &config, 1) < 0) {
            fprintf(stderr, "Failed to write to CONFIG register\n");
            i2c_close(i2c_bus);
            gpioTerminate();
            return 1;
        }
        usleep(10000);

        // Wait for conversion to complete
        usleep(10000);

        // Read temperature register
        if (i2cReadReg16(i2c_bus, address, 0x01, &temp_raw, 1) < 0) {
            fprintf(stderr, "Failed to read temperature register\n");
            i2c_close(i2c_bus);
            gpioTerminate();
            return 1;
        }

        // Read humidity register
        if (i2cReadReg16(i2c_bus, address, 0x02, &humid_raw, 1) < 0) {
            fprintf(stderr, "Failed to read humidity register\n");
            i2c_close(i2c_bus);
            gpioTerminate();
            return 1;
        }

        // Convert readings
        temp = (175.72 * temp_raw) / 65536.0 - 46.85;
        humid = (125.0 * humid_raw) / 65536.0 - 6.0;

        // Print readings
        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humid);

        // Wait 2 seconds
        usleep(2000000);
    }

    // Close I2C handle
    if (i2c_close(i2c_bus) < 0) {
        perror("i2c_close");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
