#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT40_ADDRESS 0x44
#define SHT40_CMD_MEASURE 0xFD
#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF
#define SHT40_TEMP_RAW_MAX 65535
#define SHT40_HUMIDITY_RAW_MAX 65535
#define SHT40_TEMP_MIN -45
#define SHT40_HUMIDITY_MIN -6
#define SHT40_TEMP_MAX 85
#define SHT40_HUMIDITY_MAX 100

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sht40_crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t crc = SHT40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHT40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    *crc = crc;
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    int i2c_bus = 1;
    if (gpioI2COpen(i2c_fd, i2c_bus, SHT40_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", i2c_bus);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (gpioI2CWriteByte(i2c_fd, i2c_bus, SHT40_CMD_MEASURE) < 0) {
            fprintf(stderr, "Failed to write to SHT40\n");
            gpioI2CClose(i2c_fd, i2c_bus);
            gpioI2COpen(i2c_fd, i2c_bus, SHT40_ADDRESS);
            continue;
        }

        usleep(10000);

        uint8_t data[6];
        if (gpioI2CRead(i2c_fd, i2c_bus, SHT40_ADDRESS, 6, data) < 0) {
            fprintf(stderr, "Failed to read from SHT40\n");
            gpioI2CClose(i2c_fd, i2c_bus);
            gpioI2COpen(i2c_fd, i2c_bus, SHT40_ADDRESS);
            continue;
        }

        uint8_t crc_temp = data[2];
        uint8_t crc_humidity = data[5];
        sht40_crc8(data, 2, &crc_temp);
        sht40_crc8(data + 3, 3, &crc_humidity);

        if (crc_temp != data[2] || crc_humidity != data[5]) {
            fprintf(stderr, "CRC error\n");
            gpioI2CClose(i2c_fd, i2c_bus);
            gpioI2COpen(i2c_fd, i2c_bus, SHT40_ADDRESS);
            continue;
        }

        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t humidity_raw = (data[3] << 8) | data[4];

        float temp = SHT40_TEMP_MIN + 175 * temp_raw / SHT40_TEMP_RAW_MAX;
        float humidity = SHT40_HUMIDITY_MIN + 125 * humidity_raw / SHT40_HUMIDITY_RAW_MAX;

        temp = (temp < SHT40_TEMP_MIN) ? SHT40_TEMP_MIN : (temp > SHT40_TEMP_MAX) ? SHT40_TEMP_MAX : temp;
        humidity = (humidity < SHT40_HUMIDITY_MIN) ? SHT40_HUMIDITY_MIN : (humidity > SHT40_HUMIDITY_MAX) ? SHT40_HUMIDITY_MAX : humidity;

        printf("Temperature: %.2f°C, Humidity: %.2f%%\n", temp, humidity);

        usleep(5000000);
    }

    gpioI2CClose(i2c_fd, i2c_bus);
    gpioTerminate();

    return 0;
}

