#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define REG_AMBIENT_TEMP 0x06
#define REG_OBJECT_TEMP 0x07
#define LOG_FILE "temperature_log.csv"
#define LOG_INTERVAL 5000000 // 5 seconds in microseconds

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close I2C file descriptor
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_fd >= 0) {
        fclose(log_fd);
    }

    // Exit the program
    exit(0);
}

int main() {
    // Open I2C device
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Register SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        close(i2c_fd);
        fclose(log_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ambient temperature
        uint16_t ambient_temp;
        if (i2c_smbus_read_byte_data(i2c_fd, REG_AMBIENT_TEMP) < 0) {
            // Handle sensor-absent scenario
            fprintf(stderr, "Error reading ambient temperature\n");
            continue;
        }
        i2c_smbus_read_byte_data(i2c_fd, REG_AMBIENT_TEMP + 1);
        ambient_temp = (uint16_t)((i2c_smbus_read_byte_data(i2c_fd, REG_AMBIENT_TEMP) << 8) | i2c_smbus_read_byte_data(i2c_fd, REG_AMBIENT_TEMP + 1));
        fprintf(stderr, "Ambient temperature: %d°C\n", (int)ambient_temp / 256);

        // Read object temperature
        uint16_t object_temp;
        if (i2c_smbus_read_byte_data(i2c_fd, REG_OBJECT_TEMP) < 0) {
            // Handle sensor-absent scenario
            fprintf(stderr, "Error reading object temperature\n");
            continue;
        }
        i2c_smbus_read_byte_data(i2c_fd, REG_OBJECT_TEMP + 1);
        object_temp = (uint16_t)((i2c_smbus_read_byte_data(i2c_fd, REG_OBJECT_TEMP) << 8) | i2c_smbus_read_byte_data(i2c_fd, REG_OBJECT_TEMP + 1));
        fprintf(stderr, "Object temperature: %d°C\n", (int)object_temp / 256);

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s,%.2f,%.2f\n", timestamp, (double)ambient_temp / 256, (double)object_temp / 256);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    fclose(log_fd);

    return 0;
}

