void log_error(const char *message) {
    FILE *error_file = fopen(ERROR_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file for writing\n");
        exit(1);
    }

    fprintf(error_file, "%s\n", message);

    fclose(error_file);
}

