    int fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        log_error("Failed to open I2C bus");
        return -1.0;
    }

    uint8_t data[2];
    if (i2cRead(fd, TEMPERATURE_REGISTER, 2, data) < 0) {
        log_error("Failed to read from I2C bus");
        i2cClose(fd);
        return -1.0;
    }

    double temperature = (data[0] << 8) | data[1];
    temperature /= 100.0;
    i2cClose(fd);
    return temperature;
