    if (log_file == NULL) {
        log_error("Failed to open log file for writing");
        gpioTerminate();
        return 1;
    }

    FILE *error_file = fopen(ERROR_FILE, "w");
    if (error_file == NULL) {
        log_error("Failed to open error log file for writing");
        fclose(log_file);
        gpioTerminate();
        return 1;
