#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define PRESSURE_SCALE_FACTOR 0x0001
#define TEMPERATURE_SCALE_FACTOR 0x0002
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

#define PRESSURE_OFFSET 0x00
#define PRESSURE_MASK 0xFF
#define TEMPERATURE_OFFSET 0x02
#define TEMPERATURE_MASK 0xFF

#define PRESSURE_DATA_OFFSET 0x00
#define PRESSURE_CRC_OFFSET 0x06
#define TEMPERATURE_DATA_OFFSET 0x07
#define TEMPERATURE_CRC_OFFSET 0x0B
#define SCALE_FACTORS_OFFSET 0x0C

#define PRESSURE_DATA_SIZE 2
#define TEMPERATURE_DATA_SIZE 2
#define SCALE_FACTORS_SIZE 2

#define CRC_SIZE 1

#define LOG_FILE "pressure_log.csv"

void sigint_handler(int sig) {
    (void)sig;
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(0);
}

void sigterm_handler(int sig) {
    (void)sig;
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(0);
}

int main() {
    int gpio_fd = pigpio_open();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (pigpio_i2c_open(gpio_fd, I2C_BUS, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        pigpio_close(gpio_fd);
        return 1;
    }

    struct tm *timeinfo;
    time_t rawtime;
    char buffer[80];

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        pigpio_i2c_close(gpio_fd);
        pigpio_close(gpio_fd);
        return 1;
    }

    char header[] = "timestamp,differential_pressure,temperature\n";
    if (fputs(header, log_file) == EOF) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(log_file);
        pigpio_i2c_close(gpio_fd);
        pigpio_close(gpio_fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

        uint8_t command[] = {0x36, 0x08};
        if (pigpio_i2c_write(gpio_fd, I2C_BUS, I2C_ADDRESS, command, 2) < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %s\n", strerror(errno));
            break;
        }

        usleep(1000);

        uint8_t data[PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE + SCALE_FACTORS_SIZE + CRC_SIZE * 3];
        if (pigpio_i2c_read(gpio_fd, I2C_BUS, I2C_ADDRESS, data, PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE + SCALE_FACTORS_SIZE + CRC_SIZE * 3) < 0) {
            fprintf(stderr, "Failed to read from I2C bus: %s\n", strerror(errno));
            break;
        }

        uint8_t pressure_data[PRESSURE_DATA_SIZE];
        uint8_t temperature_data[TEMPERATURE_DATA_SIZE];
        uint8_t scale_factors[SCALE_FACTORS_SIZE];
        uint8_t crc[PRESSURE_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1];
        uint8_t crc_temp[PRESSURE_CRC_OFFSET - TEMPERATURE_DATA_OFFSET + 1];
        uint8_t crc_scale[PRESSURE_CRC_OFFSET - SCALE_FACTORS_OFFSET + 1];

        memcpy(pressure_data, data, PRESSURE_DATA_SIZE);
        memcpy(temperature_data, data + PRESSURE_DATA_SIZE, TEMPERATURE_DATA_SIZE);
        memcpy(scale_factors, data + PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE, SCALE_FACTORS_SIZE);
        memcpy(crc, data + PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE + SCALE_FACTORS_SIZE, PRESSURE_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1);
        memcpy(crc_temp, data + PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE + SCALE_FACTORS_SIZE + PRESSURE_CRC_OFFSET - TEMPERATURE_DATA_OFFSET + 1, TEMPERATURE_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1);
        memcpy(crc_scale, data + PRESSURE_DATA_SIZE + TEMPERATURE_DATA_SIZE + SCALE_FACTORS_SIZE + PRESSURE_CRC_OFFSET + TEMPERATURE_CRC_OFFSET - SCALE_FACTORS_OFFSET + 1, SCALE_FACTORS_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1);

        uint8_t pressure_crc = crc_calculate(crc, PRESSURE_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1, CRC_POLYNOMIAL, CRC_INIT);
        uint8_t temperature_crc = crc_calculate(crc_temp, TEMPERATURE_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1, CRC_POLYNOMIAL, CRC_INIT);
        uint8_t scale_factors_crc = crc_calculate(crc_scale, SCALE_FACTORS_CRC_OFFSET - PRESSURE_DATA_OFFSET + 1, CRC_POLYNOMIAL, CRC_INIT);

        if (pressure_crc != data[PRESSURE_CRC_OFFSET] || temperature_crc != data[PRESSURE_CRC_OFFSET + 1] || scale_factors_crc != data[PRESSURE_CRC_OFFSET + 2]) {
            fprintf(stderr, "CRC error\n");
            break;
        }

        int16_t pressure = (pressure_data[0] << 8) | pressure_data[1];
        int16_t temperature = (temperature_data[0] << 8) | temperature_data[1];

        pressure = (pressure * PRESSURE_SCALE_FACTOR) >> 8;
        temperature = (temperature * TEMPERATURE_SCALE_FACTOR) >> 8;

        if (fputs(buffer, log_file) == EOF) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }

        if (fprintf(log_file, ",%d,%d\n", pressure, temperature) == EOF) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            break;
        }

        sleep(1);
    }

    fclose(log_file);
    pigpio_i2c_close(gpio_fd);
    pigpio_close(gpio_fd);

    return 0;
}

uint8_t crc_calculate(uint8_t *data, size_t size, uint8_t polynomial, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < size; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

