#include <pigpio.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define MEASUREMENT_RETRY_ATTEMPTS 3
#define MEASUREMENT_RETRY_BACKOFF 100 // ms
#define MEASUREMENT_INTERVAL 100 // ms
#define LOG_FILE "airflow.log"

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

void measurement_retry(int attempts, int backoff, int (*func)(int, int, void*), int fd, void* arg) {
    int retries = 0;
    while (retries < attempts) {
        if (func(fd, backoff * retries, arg) == 0) {
            return;
        }
        retries++;
        usleep(backoff * retries * 1000);
    }
    fprintf(stderr, "Failed to perform measurement after %d attempts\n", attempts);
    exit(1);
}

int i2c_write_retry(int fd, int backoff, void* arg) {
    return i2cWriteDevice(fd, I2C_ADDRESS, 2, (uint8_t*)arg);
}

int i2c_read_retry(int fd, int backoff, void* arg) {
    return i2cReadDevice(fd, I2C_ADDRESS, 6, (uint8_t*)arg);
}

int main() {
    int fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(fd);
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    gpioInitialise();

    uint8_t trigger_command[] = {0x21, 0x96};
    uint8_t measurement_data[6];

    while (!exit_flag) {
        measurement_retry(MEASUREMENT_RETRY_ATTEMPTS, MEASUREMENT_RETRY_BACKOFF, i2c_write_retry, fd, trigger_command);
        measurement_retry(MEASUREMENT_RETRY_ATTEMPTS, MEASUREMENT_RETRY_BACKOFF, i2c_read_retry, fd, measurement_data);

        uint16_t raw_pressure = (measurement_data[0] << 8) | measurement_data[1];
        uint16_t raw_temperature = (measurement_data[3] << 8) | measurement_data[4];

        double pressure_pa = raw_pressure / 60.0;
        double temperature_c = raw_temperature / 200.0;

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
        fflush(log_file);

        usleep(MEASUREMENT_INTERVAL * 1000);
    }

    i2cClose(fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

