#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define TEMPERATURE_COMMAND 0xF3
#define HUMIDITY_COMMAND 0xF5
#define TEMPERATURE_RAW_MAX 65536
#define HUMIDITY_RAW_MAX 65536
#define TEMPERATURE_OFFSET 46.85
#define TEMPERATURE_GAIN 175.72
#define HUMIDITY_OFFSET -6.0
#define HUMIDITY_GAIN 125.0

#define SAMPLE_INTERVAL 5000

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    char filename[] = "sensor_data.txt";
    FILE *file;
    char buffer[256];

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error());
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C open failed: %s\n", pigpio_error());
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open file for logging
    file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file for logging: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read temperature
        uint8_t command = TEMPERATURE_COMMAND;
        if (gpioI2CWriteReg8(i2c_fd, 0, &command, 1) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", pigpio_error());
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        uint8_t raw;
        int retries = 0;
        while (retries < 20) {
            if (gpioI2CReadReg8(i2c_fd, 0, &raw, 1) < 0) {
                if (errno == EIO) {
                    // Retry on transient I2C failure
                    usleep(100000);
                    retries++;
                    continue;
                } else {
                    fprintf(stderr, "I2C read failed: %s\n", pigpio_error());
                    fclose(file);
                    gpioClose(i2c_fd);
                    gpioTerminate();
                    exit(EXIT_FAILURE);
                }
            }
            break;
        }

        if (retries >= 20) {
            fprintf(stderr, "Failed to read temperature: %s\n", pigpio_error());
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        float temperature = (TEMPERATURE_GAIN * raw / TEMPERATURE_RAW_MAX) - TEMPERATURE_OFFSET;

        // Read humidity
        command = HUMIDITY_COMMAND;
        if (gpioI2CWriteReg8(i2c_fd, 0, &command, 1) < 0) {
            fprintf(stderr, "I2C write failed: %s\n", pigpio_error());
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        raw = 0;
        retries = 0;
        while (retries < 20) {
            if (gpioI2CReadReg8(i2c_fd, 0, &raw, 1) < 0) {
                if (errno == EIO) {
                    // Retry on transient I2C failure
                    usleep(100000);
                    retries++;
                    continue;
                } else {
                    fprintf(stderr, "I2C read failed: %s\n", pigpio_error());
                    fclose(file);
                    gpioClose(i2c_fd);
                    gpioTerminate();
                    exit(EXIT_FAILURE);
                }
            }
            break;
        }

        if (retries >= 20) {
            fprintf(stderr, "Failed to read humidity: %s\n", pigpio_error());
            fclose(file);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        float humidity = (HUMIDITY_GAIN * raw / HUMIDITY_RAW_MAX) - HUMIDITY_OFFSET;
        humidity = (humidity < 0) ? 0 : ((humidity > 100) ? 100 : humidity);

        // Log and print data
        time_t now = time(NULL);
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(file, "%s,%.2f,%.2f\n", buffer, temperature, humidity);
        fprintf(stderr, "Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Close I2C handle
    gpioClose(i2c_fd);

    // Close file
    fclose(file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

