#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define MEASUREMENT_DELAY_US 15000
#define MEASUREMENT_SIZE 3
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF

#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_FILE "error_log.txt"

void sigint_handler(int sig) {
    (void)sig;
    printf("\nReceived SIGINT, shutting down...\n");
    gpioTerminate();
    exit(0);
}

int main() {
    int fd;
    int ret;
    uint8_t buffer[MEASUREMENT_SIZE];
    uint8_t crc;
    double temperature;
    time_t now;
    struct tm *now_tm;
    FILE *log_file;
    FILE *error_file;

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", ret);
        return 1;
    }

    // Open I2C bus
    if ((fd = gpioOpen(I2C_BUS, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", fd);
        gpioTerminate();
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    error_file = fopen(ERROR_FILE, "a");
    if (!error_file) {
        fprintf(stderr, "Failed to open error log file: %s\n", ERROR_FILE);
        fclose(log_file);
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Write measurement command
        if ((ret = gpioI2cWrite(fd, MEASUREMENT_COMMAND, 1)) < 0) {
            fprintf(stderr, "Failed to write to I2C bus: %d\n", ret);
            fprintf(error_file, "%s: %d\n", __func__, ret);
            fclose(log_file);
            fclose(error_file);
            gpioClose(fd);
            gpioTerminate();
            return 1;
        }

        // Wait for measurement conversion
        usleep(MEASUREMENT_DELAY_US);

        // Read measurement data
        if ((ret = gpioI2cRead(fd, buffer, MEASUREMENT_SIZE)) < 0) {
            fprintf(stderr, "Failed to read from I2C bus: %d\n", ret);
            fprintf(error_file, "%s: %d\n", __func__, ret);
            fclose(log_file);
            fclose(error_file);
            gpioClose(fd);
            gpioTerminate();
            return 1;
        }

        // Validate CRC-8 checksum
        crc = 0xFF;
        for (int i = 0; i < MEASUREMENT_SIZE - 1; i++) {
            crc = (crc >> 1) ^ ((crc & 1) * CRC_POLYNOMIAL);
            crc ^= buffer[i];
        }
        if (crc != buffer[MEASUREMENT_SIZE - 1]) {
            fprintf(stderr, "CRC mismatch: expected 0x%02x, got 0x%02x\n", CRC_INITIAL, crc);
            fprintf(error_file, "%s: CRC mismatch\n", __func__);
            continue;
        }

        // Convert raw value to temperature
        temperature = -45 + 175 * (buffer[0] * 256 + buffer[1]) / 65535.0;

        // Log temperature reading
        time(&now);
        now_tm = localtime(&now);
        fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %f°C\n",
                now_tm->tm_year + 1900, now_tm->tm_mon + 1, now_tm->tm_mday,
                now_tm->tm_hour, now_tm->tm_min, now_tm->tm_sec, temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close log files
    fclose(log_file);
    fclose(error_file);

    // Close I2C bus
    gpioClose(fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

