#define SHT40_CRC_POLYNOMIAL 0x31
#define SHT40_CRC_INIT 0xFF

#define LOG_FILE "sht40_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(1);
    }
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDR) < 0) {
        perror("i2c_open");
        close(fd);
        exit(1);
    }
    return fd;
}

void i2c_close(int fd) {
    close(fd);
}

void sht40_read(int fd, uint8_t* data) {
    if (write(fd, &SHT40_CMD_HR, 1) != 1) {
        perror("sht40_read");
        return;
    }
    usleep(8500000); // wait at least 8.5 ms
    if (read(fd, data, 6) != 6) {
        perror("sht40_read");
        return;
    }
}

bool sht40_validate_crc(uint8_t* data) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < 5; i++) {
        crc = (crc << 1) ^ (crc & 0x80 ? SHT40_CRC_POLYNOMIAL : 0);
        crc ^= data[i];
    }
    return crc == data[5];
}

void sht40_log(int fd, double temperature, double humidity) {
    char buffer[64];
    struct timeval tv;
    gettimeofday(&tv, NULL);
    sprintf(buffer, "%ld.%06ld %f %f\n", tv.tv_sec, tv.tv_usec, temperature, humidity);
    if (write(fd, buffer, strlen(buffer)) != strlen(buffer)) {
        perror("sht40_log");
    }
}

int main() {
    int fd = i2c_open();
    FILE* log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        i2c_close(fd);
        exit(1);
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t data[6];
        sht40_read(fd, data);
        if (!sht40_validate_crc(data)) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }
        double temperature = -45 + 175 * (data[1] << 8 | data[0]) / 65535.0;
        double humidity = 100 * (data[3] << 8 | data[2]) / 65535.0;
        sht40_log(log_file, temperature, humidity);
        usleep(5000000); // wait 5 seconds
    }

    i2c_close(fd);
    fclose(log_file);
    return 0;
}

