#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_MEAS_CONT 0x36
#define SCALE_PRESSURE 240.0
#define SCALE_TEMP 200.0
#define OFFSET_TEMP -45.0

// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw pressure to Pa
float pressure_to_pa(uint16_t raw) {
    return (float)raw * SCALE_PRESSURE;
}

// Function to convert raw temperature to °C
float temp_to_c(uint16_t raw) {
    return (float)(raw * SCALE_TEMP + OFFSET_TEMP) / 100.0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    printf("\nExiting...\n");
