#include <pigpio.h>

#define BUFFER_SIZE 60
#define FAN_PIN 18
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define TEMPERATURE_CMD 0xE3
#define HUMIDITY_CMD 0xE5
#define TEMPERATURE_HYST 1.0
#define FAN_HYST 1.0

// Circular buffer structure
typedef struct {
    double data[BUFFER_SIZE];
    int head;
    int tail;
} Buffer;

// Function to initialize the circular buffer
void buffer_init(Buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
}

// Function to add an element to the circular buffer
void buffer_add(Buffer *buf, double value) {
    buf->data[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

// Function to get the last element from the circular buffer
double buffer_get_last(Buffer *buf) {
    return buf->data[buf->tail];
}

// Function to print the circular buffer
void buffer_print(Buffer *buf) {
    for (int i = buf->tail; i != buf->head; i = (i + 1) % BUFFER_SIZE) {
        printf("%f ", buf->data[i]);
    }
    for (int i = 0; i < buf->tail; i++) {
        printf("%f ", buf->data[i]);
    }
    printf("\n");
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpioWrite(FAN_PIN, 0); // Turn off the fan
    i2cClose(I2C_BUS);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Initialize the I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the circular buffer
    Buffer buffer;
    buffer_init(&buffer);

    // Set up the fan pin as an output
    if (gpioMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up fan pin\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read temperature
        int retries = 0;
        double temperature;
        while (retries < 3) {
            if (i2cWriteReg8(i2c_fd, TEMPERATURE_CMD, 0) < 0) {
                fprintf(stderr, "Failed to write temperature command\n");
                break;
            }
            usleep(10 * 1000); // Wait 10 ms
            uint16_t raw = i2cReadReg16(i2c_fd, 0);
            if (raw == 0xFFFF) {
                // Sensor absent
                fprintf(stderr, "Sensor absent\n");
                break;
            }
            temperature = 175.72 * raw / 65536.0 - 46.85;
            buffer_add(&buffer, temperature);
            if (temperature > 28.0 + TEMPERATURE_HYST) {
                gpioWrite(FAN_PIN, 1); // Turn on the fan
            } else if (temperature < 27.0 - TEMPERATURE_HYST) {
                gpioWrite(FAN_PIN, 0); // Turn off the fan
            }
            retries = 0;
            break;
        }
        if (retries >= 3) {
            // Failed to read temperature
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }

        // Read humidity
        retries = 0;
        double humidity;
        while (retries < 3) {
            if (i2cWriteReg8(i2c_fd, HUMIDITY_CMD, 0) < 0) {
                fprintf(stderr, "Failed to write humidity command\n");
                break;
            }
            usleep(10 * 1000); // Wait 10 ms
            uint16_t raw = i2cReadReg16(i2c_fd, 0);
            if (raw == 0xFFFF) {
                // Sensor absent
                fprintf(stderr, "Sensor absent\n");
                break;
            }
            humidity = 125.0 * raw / 65536.0 - 6.0;
            buffer_add(&buffer, humidity);
            retries = 0;
            break;
        }
        if (retries >= 3) {
            // Failed to read humidity
            fprintf(stderr, "Failed to read humidity\n");
            break;
        }

        // Print the buffer
        printf("%f %f ", buffer_get_last(&buffer), temperature);
        buffer_print(&buffer);

        // Wait 2 seconds
        usleep(2 * 1000 * 1000);
    }

    // Clean up
    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

