#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_START_MEASUREMENT 0x21B1
#define SCD40_DATA_READY 0xE4B8
#define SCD40_READ_DATA 0xEC05
#define SCD40_STOP_MEASUREMENT 0x3F86
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INIT 0xFF

#define LOG_FILE "air_quality.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t crc_value = SCD40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc_value = (crc_value ^ data[i]) ^ ((crc_value >> 4) & 1) ? (crc_value << 3) ^ (crc_value << 1) ^ 0x05 : (crc_value << 3) ^ (crc_value << 1);
    }
    *crc = crc_value;
}

int main() {
    int gpio_init = pigpioInitialise();
    if (gpio_init < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %d\n", gpio_init);
        return 1;
    }

    int i2c_handle = pigpioOpen(1, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1: %d\n", i2c_handle);
        pigpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        pigpioClose(i2c_handle);
        pigpioTerminate();
        return 1;
    }

    while (running) {
        if (pigpioWrite(i2c_handle, SCD40_I2C_ADDRESS, 1, SCD40_START_MEASUREMENT) < 0) {
            fprintf(stderr, "Failed to send Start Periodic Measurement command\n");
            break;
        }

        usleep(1000000); // Wait at least 1 second

        while (pigpioRead(i2c_handle, SCD40_I2C_ADDRESS, 1, SCD40_DATA_READY) < 0) {
            usleep(10000); // Wait for data to be ready
        }

        uint8_t data[9];
        if (pigpioRead(i2c_handle, SCD40_I2C_ADDRESS, 9, SCD40_READ_DATA, data) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        uint8_t crc = 0;
        crc8(data, 6, &crc);
        if (crc != data[7] || crc8(data + 1, 2, &crc) != data[8]) {
            fprintf(stderr, "Invalid CRC\n");
            break;
        }

        uint16_t co2 = (data[0] << 8) | data[1];
        uint16_t temperature = (data[2] << 8) | data[3];
        uint16_t humidity = (data[4] << 8) | data[5];

        fprintf(log_file, "%lu,%u,%f,%f\n", time(NULL), co2, -45 + 175 * temperature / (1 << 16), 100 * humidity / (1 << 16));
        fflush(log_file);

        usleep(5000000); // Wait 5 seconds
    }

    if (pigpioWrite(i2c_handle, SCD40_I2C_ADDRESS, 1, SCD40_STOP_MEASUREMENT) < 0) {
        fprintf(stderr, "Failed to send Stop Periodic Measurement command\n");
    }

    pigpioClose(i2c_handle);
    pigpioTerminate();
    fclose(log_file);

    return 0;
}

