#define CO2_SENSOR_ADDRESS 0x62
#define CO2_SENSOR_MEASUREMENT_INTERVAL 5000000  // 5 seconds
#define CO2_SENSOR_MEASUREMENT_COMMAND 0x21B1
#define CO2_SENSOR_GET_DATA_READY_STATUS 0xE4B8
#define CO2_SENSOR_READ_MEASUREMENT 0xEC05
#define CO2_SENSOR_STOP_MEASUREMENT 0x3F86
#define CO2_SENSOR_CRC8_POLYNOMIAL 0x31
#define CO2_SENSOR_CRC8_INIT 0xFF
#define CO2_SENSOR_CRC8_XOROUT 0x00
#define CO2_SENSOR_CRC8_XORIN 0x00
#define CO2_SENSOR_CRC8_TAB_SIZE 256
uint8_t co2_sensor_crc8_tab[CO2_SENSOR_CRC8_TAB_SIZE];

// Function to calculate CRC-8 checksum
uint8_t co2_sensor_crc8(uint8_t *data, uint8_t len) {
    uint8_t crc = CO2_SENSOR_CRC8_INIT;
    for (uint8_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) ^ co2_sensor_crc8_tab[(crc >> 4) & 0x0F];
        crc = (crc << 4) | (crc >> 4);
    }
    return crc;
}

