#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SAMPLING_INTERVAL 5000000  // 5 seconds in microseconds
#define MAX_FAILURES 3
#define MIN_TEMP -40
#define MAX_TEMP 150

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Close the log file
    fclose(log_file);
    // Release pigpio resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    int failures = 0;
    while (1) {
        // Read the current timestamp
        uint64_t timestamp = gpioTick();

        // Set the GPIO pin as an input
        if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO mode\n");
            break;
        }

        // Wait for a rising edge
        if (gpioWaitForRisingEdge(GPIO_PIN, 50000000) < 0) {
            fprintf(stderr, "Failed to wait for rising edge\n");
            break;
        }

        // Measure the high pulse width (TH) and total cycle width (TL)
        uint64_t start = gpioTick();
        while (gpioRead(GPIO_PIN) == 1) {
            // Busy-wait polling with microsecond-level timing
        }
        uint64_t th = gpioTick() - start;

        start = gpioTick();
        while (gpioRead(GPIO_PIN) == 0) {
            // Busy-wait polling with microsecond-level timing
        }
        uint64_t tl = gpioTick() - start;

        // Check for sensor-absent or stuck-line conditions
        if (tl < 500000 || tl > 20000000) {
            fprintf(stderr, "Sensor-absent or stuck-line condition detected\n");
            failures++;
            if (failures >= MAX_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                break;
            }
            continue;
        }

        // Convert the reading to degrees Celsius
        double temperature = 4215 - (2143 * th / tl);
        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %f°C\n", temperature);
            failures++;
            if (failures >= MAX_FAILURES) {
                fprintf(log_file, "SENSOR MALFUNCTION\n");
                break;
            }
            continue;
        }

        // Log the reading with an ISO-8601 timestamp
        char timestamp_str[32];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", localtime(&timestamp));
        fprintf(log_file, "%s %f°C\n", timestamp_str, temperature);

        // Wait for the next sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Close the log file
    fclose(log_file);
    // Release pigpio resources
    gpioTerminate();

    return 0;
}

