#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SHT35_ADDRESS 0x44
#define SHT35_MEAS_HIGHREP 0x24
#define SHT35_MEAS_HIGHREP_NO_STRETCH 0x00
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INIT 0xFF
#define SHT35_CRC_XOROUT 0x00
#define SHT35_CRC_XORIN 0x00

#define SHT35_TEMP_WORD 0x00
#define SHT35_HUMIDITY_WORD 0x01

#define SHT35_TEMP_OFFSET 2.0
#define SHT35_HUMIDITY_OFFSET 5.0
#define SHT35_TEMP_AMPLITUDE 2.0
#define SHT35_HUMIDITY_AMPLITUDE 5.0
#define SHT35_PERIOD 3600.0

#define LOG_FILE "environmental_data.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void log_data(double temperature, double humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2c_fd = gpioOpen(1, SHT35_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    double last_time = 0.0;
    while (running) {
        double current_time = time(NULL);
        if (current_time - last_time >= 5.0) {
            last_time = current_time;

            uint8_t command[2] = {SHT35_MEAS_HIGHREP, SHT35_MEAS_HIGHREP_NO_STRETCH};
            if (i2cWrite(i2c_fd, command, 2, 100) < 0) {
                fprintf(stderr, "Failed to write to SHT35\n");
                continue;
            }

            usleep(15000);

            uint8_t data[6];
            int retries = 0;
            while (retries < 3) {
                if (i2cRead(i2c_fd, data, 6, 100) < 0) {
                    fprintf(stderr, "Failed to read from SHT35\n");
                    retries++;
                    usleep(1000000);
                    continue;
                }

                uint16_t crc = SHT35_CRC_INIT;
                for (int i = 0; i < 6; i++) {
                    crc ^= data[i];
                    for (int j = 0; j < 8; j++) {
                        if (crc & 0x80) {
                            crc = (crc << 1) ^ SHT35_CRC_POLYNOMIAL;
                        } else {
                            crc <<= 1;
                        }
                    }
                }

                if (crc != SHT35_CRC_XOROUT) {
                    fprintf(stderr, "CRC failed\n");
                    retries++;
                    usleep(1000000);
                    continue;
                }

                uint16_t temperature = (data[0] << 8) | data[1];
                uint16_t humidity = (data[2] << 8) | data[3];

                double temp = (175.0 * (temperature / 65536.0)) - 45.0 + SHT35_TEMP_OFFSET + SHT35_TEMP_AMPLITUDE * sin((current_time - (current_time % SHT35_PERIOD)) / SHT35_PERIOD * 2 * M_PI);
                double humid = (100.0 * (humidity / 65536.0)) + SHT35_HUMIDITY_OFFSET + SHT35_HUMIDITY_AMPLITUDE * sin((current_time - (current_time % SHT35_PERIOD)) / SHT35_PERIOD * 2 * M_PI);

                log_data(temp, humid);
                break;
            }

            if (retries >= 3) {
                log_data(NAN, NAN);
            }
        }

        usleep(500000);
    }

    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

