#include <signal.h>
#include <syslog.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x36
#define CONVERSION_TIME_US 45000
#define CSV_FILE "airflow.csv"

// Function to calculate CRC-8 checksum
uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw data to pressure and temperature
void convert_data(uint8_t *data) {
    uint16_t pressure = (data[0] << 8) | data[1];
    uint16_t temperature = (data[2] << 8) | data[3];
    uint16_t scale_factor = (data[4] << 8) | data[5];
    uint8_t pressure_crc = data[6];
    uint8_t temperature_crc = data[7];
    uint8_t scale_factor_crc = data[8];

    if (crc8(data, 6, 0x31, 0xFF) != pressure_crc || crc8(data + 2, 6, 0x31, 0xFF) != temperature_crc || crc8(data + 4, 6, 0x31, 0xFF) != scale_factor_crc) {
        syslog(LOG_ERR, "Invalid CRC");
        exit(1);
    }

    double pressure_pa = (pressure * 100.0) / scale_factor;
    double temperature_c = (temperature * 100.0) / 256.0;

    syslog(LOG_INFO, "Pressure: %.2f Pa, Temperature: %.2f °C", pressure_pa, temperature_c);
}

// Function to write to CSV file
void write_to_csv(double pressure, double temperature) {
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        syslog(LOG_ERR, "Failed to open CSV file");
        exit(1);
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

int main() {
    // Open I2C bus
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C address");
        exit(1);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        syslog(LOG_ERR, "Failed to open CSV file");
        exit(1);
    }

    // Write header to CSV file
    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        exit(1);
    }

    while (1) {
        // Send measurement command
        uint8_t command[] = {MEASUREMENT_COMMAND};
        if (write(i2c_fd, command, 1) != 1) {
            syslog(LOG_ERR, "Failed to send measurement command");
            exit(1);
        }

        // Wait for conversion time
        usleep(CONVERSION_TIME_US);

        // Read data
        uint8_t data[9];
        if (read(i2c_fd, data, 9) != 9) {
            syslog(LOG_ERR, "Failed to read data");
            exit(1);
        }

        // Convert data
        convert_data(data);

        // Write to CSV file
        write_to_csv((double) data[0] * 100.0 / data[4], (double) data[2] * 100.0 / 256.0);

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

