#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>

#define SHT35_ADDR 0x44
#define SHT35_CMD_MEASURE 0x2400
#define SHT35_CRC_POLYNOMIAL 0x31
#define SHT35_CRC_INIT 0xFF
#define SHT35_TEMP_LSB 2
#define SHT35_HUM_LSB 4

#define CSV_FILE "environment.csv"

void crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t i, j;
    *crc = SHT35_CRC_INIT;
    for (i = 0; i < len; i++) {
        *crc ^= data[i];
        for (j = 0; j < 8; j++) {
            if (*crc & 0x80) {
                *crc = ((*crc << 1) ^ SHT35_CRC_POLYNOMIAL);
            } else {
                *crc <<= 1;
            }
        }
    }
}

int main() {
    int i2c_fd;
    int gpio_fd;
    char timestamp[32];
    struct tm *timeinfo;
    uint8_t data[6];
    uint8_t crc_temp, crc_humidity;
    float temperature, humidity;

    // Install SIGINT/SIGTERM handler for clean shutdown
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    if ((i2c_fd = gpioOpen(1, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file '%s'\n", CSV_FILE);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row to CSV file if it's empty
    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        fprintf(fp, "timestamp,temperature_c,humidity_pct\n");
    }

    // Main loop
    while (1) {
        // Get current time
        time_t rawtime;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Send measurement command to SHT35
        if (gpioI2cWriteReg(i2c_fd, SHT35_ADDR, SHT35_CMD_MEASURE, 1) < 0) {
            fprintf(stderr, "Failed to send measurement command to SHT35\n");
            break;
        }

        // Wait at least 15 ms
        usleep(15000);

        // Read 6 bytes from SHT35
        if (gpioI2cReadReg(i2c_fd, SHT35_ADDR, 0, data, 6) < 0) {
            fprintf(stderr, "Failed to read from SHT35\n");
            break;
        }

        // Validate CRC-8 checksums
        crc8(data + SHT35_TEMP_LSB, 2, &crc_temp);
        crc8(data + SHT35_HUM_LSB, 2, &crc_humidity);
        if (crc_temp != data[0] || crc_humidity != data[5]) {
            fprintf(stderr, "Invalid CRC-8 checksums\n");
            break;
        }

        // Convert raw values to temperature and humidity
        temperature = -45 + 175 * (data[0] << 8 | data[1]) / 65535;
        humidity = 100 * (data[3] << 8 | data[4]) / 65535;

        // Log reading to CSV file
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C handle and CSV file
    gpioClose(i2c_fd);
    fclose(fp);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

