#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define MEASUREMENT_TIMEOUT 100
#define MEASUREMENT_RETRY 10
#define MEASUREMENT_INTERVAL 5000000 // 5 seconds
#define CSV_FILE "environment.log"

// CRC-8 polynomial 0x31, initial value 0x00
uint8_t crc8(uint8_t data) {
    uint8_t crc = 0x00;
    for (int i = 0; i < 8; i++) {
        crc ^= data;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw Si7021 value to temperature and humidity
void convert_raw(uint16_t raw, uint8_t type, double *temperature, double *humidity) {
    if (type == 0xF3) {
        *temperature = 175.72 * raw / 65536.0 - 46.85;
    } else if (type == 0xF5) {
        *humidity = 125.0 * raw / 65536.0 - 6.0;
    }
}

// SIGINT/SIGTERM handler
void sigint_handler(int sig) {
    close(i2c_fd);
    exit(0);
}

int main() {
    // Open I2C device
    char i2c_dev_path[20];
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        exit(1);
    }

    // Install SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(i2c_fd);
        exit(1);
    }

    // Open CSV file for logging
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        perror("fopen");
        close(i2c_fd);
        exit(1);
    }

    // Log header
    fprintf(csv_file, "timestamp,temperature_C,humidity_percent\n");

    // Main loop
    while (1) {
        // Read temperature
        uint8_t cmd = 0xF3;
        uint8_t data[3];
        int retry = MEASUREMENT_RETRY;
        while (retry--) {
            if (write(i2c_fd, &cmd, 1) != 1) {
                perror("write");
                close(i2c_fd);
                exit(1);
            }
            fd_set fds;
            struct timeval tv;
            tv.tv_sec = MEASUREMENT_TIMEOUT / 1000000;
            tv.tv_usec = MEASUREMENT_TIMEOUT % 1000000;
            FD_ZERO(&fds);
            FD_SET(i2c_fd, &fds);
            if (select(i2c_fd + 1, &fds, NULL, NULL, &tv) > 0) {
                if (read(i2c_fd, data, 3) != 3) {
                    if (errno == EIO) {
                        // Reset sensor
                        uint8_t reset_cmd = 0xFE;
                        if (write(i2c_fd, &reset_cmd, 1) != 1) {
                            perror("write");
                            close(i2c_fd);
                            exit(1);
                        }
                    } else {
                        perror("read");
                        close(i2c_fd);
                        exit(1);
                    }
                } else {
                    if (crc8(data[0] ^ data[1] ^ data[2]) != data[2]) {
                        // CRC error
                        fprintf(csv_file, "%s,ERROR,ERROR\n", ctime(&time(NULL)));
                        fprintf(stderr, "CRC error\n");
                    } else {
                        double temperature, humidity;
                        convert_raw((data[0] << 8) | data[1], 0xF3, &temperature, NULL);
                        convert_raw((data[0] << 8) | data[1], 0xF5, NULL, &humidity);
                        // Read paired temperature
                        cmd = 0xE0;
                        if (write(i2c_fd, &cmd, 1) != 1) {
                            perror("write");
                            close(i2c_fd);
                            exit(1);
                        }
                        if (read(i2c_fd, data, 3) != 3) {
                            if (errno == EIO) {
                                // Reset sensor
                                uint8_t reset_cmd = 0xFE;
                                if (write(i2c_fd, &reset_cmd, 1) != 1) {
                                    perror("write");
                                    close(i2c_fd);
                                    exit(1);
                                }
                            } else {
                                perror("read");
                                close(i2c_fd);
                                exit(1);
                            }
                        } else {
                            if (crc8(data[0] ^ data[1] ^ data[2]) != data[2]) {
                                // CRC error
                                fprintf(csv_file, "%s,ERROR,ERROR\n", ctime(&time(NULL)));
                                fprintf(stderr, "CRC error\n");
                            } else {
                                double paired_temperature;
                                convert_raw((data[0] << 8) | data[1], 0xF3, &paired_temperature, NULL);
                                fprintf(csv_file, "%s,%.2f,%.2f\n", ctime(&time(NULL)), temperature, humidity);
                                fprintf(stderr, "Temperature: %.2f°C, Humidity: %.2f%%\n", temperature, humidity);
                            }
                        }
                    }
                }
                break;
            }
        }
        if (retry == 0) {
            // Timeout
            fprintf(csv_file, "%s,ERROR,ERROR\n", ctime(&time(NULL)));
            fprintf(stderr, "Timeout\n");
        }
        usleep(MEASUREMENT_INTERVAL);
    }

    // Close CSV file
