    FILE *file = fopen("airflow.dat", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for logging\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Write command to sensor
        result = gpioI2cWriteReg8(i2c_fd, COMMAND, CONVERSION_TIME);
        if (result < 0) {
            fprintf(stderr, "Failed to write command to sensor\n");
            break;
        }

        // Wait for conversion to complete
        usleep(1000000); // 1 second

        // Read data from sensor
        result = gpioI2cReadReg8(i2c_fd, COMMAND, buffer, NUM_BYTES);
        if (result < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        // Validate CRC-8 for pressure and temperature
        if (gpioI2cCrc8(buffer, NUM_BYTES - 2) != buffer[NUM_BYTES - 2]) {
            fprintf(stderr, "Invalid CRC-8 for pressure\n");
            break;
        }
        if (gpioI2cCrc8(buffer, NUM_BYTES - 6) != buffer[NUM_BYTES - 6]) {
            fprintf(stderr, "Invalid CRC-8 for temperature\n");
            break;
        }

        // Convert pressure and temperature
        pressure = (float) (buffer[0] << 8 | buffer[1]) / (float) (buffer[3] << 8 | buffer[4]) - 1000.0;
        temperature = (float) (buffer[5] << 8 | buffer[6]) / 200.0 - 45.0;

        // Log data
        fwrite(&pressure, sizeof(float), 1, file);
        fwrite(&temperature, sizeof(float), 1, file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    gpioClose(i2c_fd);

    // Close file
    fclose(file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

uint8_t gpioI2cCrc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

