#define FAN_GPIO 18
#define FAN_FREQ 25000
#define FAN_DUTY_MIN 0
#define FAN_DUTY_MAX 100
#define FAN_DUTY_STEP 1
#define LOG_FILE "flow_log.txt"
#define LOG_INTERVAL 100000  // 100 ms
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define SENSORS_COUNTS_PER_SLPM 1638
#define SENSORS_COUNTS_PER_10SLPM 14745

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_flow(double flow_rate) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fclose(log_file);
}

void set_fan_duty(double duty) {
    if (duty < FAN_DUTY_MIN || duty > FAN_DUTY_MAX) {
        fprintf(stderr, "Invalid fan duty: %f%%\n", duty);
        return;
    }

    int duty_int = (int) (duty * 100);
    if (gpioHardwarePWM(FAN_GPIO, FAN_FREQ, duty_int) != 0) {
        fprintf(stderr, "Error setting fan duty: %s\n", strerror(errno));
    }
}

