        fprintf(stderr, "Error setting fan GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioHardwarePWM(FAN_GPIO, FAN_FREQ, 0) != 0) {
        fprintf(stderr, "Error setting fan PWM: %s\n", strerror(errno));
        gpioTerminate();
