#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "environmental_data.txt"
#define I2C_BUS 1
#define I2C_ADDRESS 0x5D
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    int fd;
    int pressure;
    int16_t temp;
    char timestamp[20];
    struct tm *timeinfo;
    struct timeval tv;
    FILE *log_file;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", strerror(errno));
        exit(1);
    }

    // Open I2C bus
    fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        exit(1);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioClose(fd);
        gpioTerminate();
        exit(1);
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        gpioClose(fd);
        fclose(log_file);
        gpioTerminate();
        exit(1);
    }

    // Read WHO_AM_I register
    uint8_t who_am_i;
    if (i2cRead(fd, 0x0F, &who_am_i, 1) < 1) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        gpioClose(fd);
        fclose(log_file);
        gpioTerminate();
        exit(1);
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "Error: WHO_AM_I register does not match expected value\n");
        gpioClose(fd);
        fclose(log_file);
        gpioTerminate();
        exit(1);
    }

    // Configure CTRL_REG1
    uint8_t ctrl_reg1 = 0xB0;
    if (i2cWrite(fd, CTRL_REG1, &ctrl_reg1, 1) < 1) {
        fprintf(stderr, "Error writing CTRL_REG1: %s\n", strerror(errno));
        gpioClose(fd);
        fclose(log_file);
        gpioTerminate();
        exit(1);
    }

    while (!exit_flag) {
        gettimeofday(&tv, NULL);
        timeinfo = localtime_r(&tv.tv_sec, &tv);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Read pressure
        if (i2cRead(fd, PRESS_OUT_XL, &pressure, 3) < 3) {
            fprintf(stderr, "%s: Error reading pressure: %s\n", timestamp, strerror(errno));
            continue;
        }
        pressure = (pressure << 8) | (i2cRead(fd, PRESS_OUT_L, NULL, 1) & 0xFF) | ((i2cRead(fd, PRESS_OUT_H, NULL, 1) & 0xFF) << 8);
        pressure = (pressure >> 1) ^ ((pressure & 1) ? -1 : 0);
        double pressure_hpa = (double)pressure / 4096.0;

        // Read temperature
        if (i2cRead(fd, TEMP_OUT_L, &temp, 2) < 2) {
            fprintf(stderr, "%s: Error reading temperature: %s\n", timestamp, strerror(errno));
            continue;
        }
        temp = (temp << 8) | (i2cRead(fd, TEMP_OUT_H, NULL, 1) & 0xFF);
        temp = (temp >> 1) ^ ((temp & 1) ? -1 : 0);
        double temp_celsius = 42.5 + (double)temp / 480.0;

        // Log data
        fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure_hpa, temp_celsius);
        fflush(log_file);

        // Delay for 1 second
        gpioDelay(1000000);
    }

    // Close I2C handle
    gpioClose(fd);

    // Close log file
    fclose(log_file);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

