#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

// Define the number of elements in the circular buffer
#define BUFFER_SIZE 10

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x48

// Define the GPIO pin for the LED
#define LED_PIN 17

// Define the temperature register
#define TEMPERATURE_REGISTER 0x00

// Define the signal handlers
void sigint_handler(int sig) {
    // Turn off the LED
    gpioWrite(LED_PIN, 0);
    // Close the I2C handle
    i2cClose(I2C_BUS);
    // Terminate the GPIO library
    gpioTerminate();
    // Exit the program
    exit(0);
}

void sigterm_handler(int sig) {
    // Turn off the LED
    gpioWrite(LED_PIN, 0);
    // Close the I2C handle
    i2cClose(I2C_BUS);
    // Terminate the GPIO library
    gpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Open the I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the circular buffer
    float buffer[BUFFER_SIZE];
    int buffer_index = 0;

    // Initialize the LED
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Main loop
    while (1) {
        // Read the temperature register
        uint16_t temperature;
        if (i2cReadWordData(i2c_handle, TEMPERATURE_REGISTER, &temperature) < 0) {
            // If the read fails, skip this iteration
            continue;
        }

        // Swap the bytes and extract the value
        uint16_t swapped_temperature = (temperature << 8) | (temperature >> 8);

        // Convert the value to degrees Celsius
        float temp_celsius = (swapped_temperature >> 7) / 2.0;

        // Add the temperature to the circular buffer
        buffer[buffer_index] = temp_celsius;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Compute the running average
        float sum = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            sum += buffer[i];
        }
        float average = sum / BUFFER_SIZE;

        // Turn on the LED if the average temperature exceeds 28.0 °C
        if (average > 28.0) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

