#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define SCD30_I2C_ADDRESS 0x61
#define SCD30_MEASUREMENT_INTERVAL 2
#define SCD30_MEASUREMENT_COMMAND 0x0300
#define SCD30_DATA_READY_COMMAND 0x0202
#define SCD30_AMBIENT_PRESSURE_COMPENSATION 0
#define SCD30_CRC_POLYNOMIAL 0x31
#define SCD30_CRC_INITIAL_VALUE 0xFF

#define LOG_FILE "air_quality.log"

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, stopping measurement and exiting.", sig);
    stop_measurement = 1;
}

void stop_measurement = 0;

void scd30_crc8(uint8_t *data, size_t len, uint8_t *crc) {
    uint8_t crc_value = SCD30_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc_value = (crc_value ^ data[i]) ^ (crc_value >> 3);
        crc_value = (crc_value & 0x80) ? (crc_value << 1) ^ SCD30_CRC_POLYNOMIAL : crc_value << 1;
    }
    *crc = crc_value;
}

int main() {
    // Initialize logging
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", strerror(errno));
        exit(0);
    }

    // Open I2C bus 1
    int i2c_bus = i2cOpen(1, SCD30_I2C_ADDRESS);
    if (i2c_bus < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1: %s", strerror(errno));
        gpioTerminate();
        exit(0);
    }

    // Initialize SCD30 sensor
    uint8_t config[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    scd30_crc8(config, 8, &config[8]);
    if (i2cWriteDevice(i2c_bus, SCD30_MEASUREMENT_COMMAND, config, 9) < 0) {
        syslog(LOG_ERR, "Failed to write to SCD30 sensor: %s", strerror(errno));
        i2cClose(i2c_bus);
        gpioTerminate();
        exit(0);
    }

    // Set measurement interval
    uint8_t interval[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    interval[0] = SCD30_MEASUREMENT_INTERVAL >> 8;
    interval[1] = SCD30_MEASUREMENT_INTERVAL & 0xFF;
    scd30_crc8(interval, 2, &interval[2]);
    if (i2cWriteDevice(i2c_bus, SCD30_MEASUREMENT_COMMAND, interval, 3) < 0) {
        syslog(LOG_ERR, "Failed to write to SCD30 sensor: %s", strerror(errno));
        i2cClose(i2c_bus);
        gpioTerminate();
        exit(0);
    }

    // Enable ambient pressure compensation
    uint8_t ambient_pressure[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    ambient_pressure[0] = SCD30_AMBIENT_PRESSURE_COMPENSATION >> 8;
    ambient_pressure[1] = SCD30_AMBIENT_PRESSURE_COMPENSATION & 0xFF;
    scd30_crc8(ambient_pressure, 2, &ambient_pressure[2]);
    if (i2cWriteDevice(i2c_bus, SCD30_MEASUREMENT_COMMAND, ambient_pressure, 3) < 0) {
        syslog(LOG_ERR, "Failed to write to SCD30 sensor: %s", strerror(errno));
        i2cClose(i2c_bus);
        gpioTerminate();
        exit(0);
    }

    // Start measurement
    uint8_t start[] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
