// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x21

// Define the command bytes to start the sensor
#define START_COMMAND 0x36
#define START_SUB_COMMAND 0x2F

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the sampling interval in milliseconds
#define DEFAULT_INTERVAL 1000

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Release resources and exit cleanly
    gpioTerminate();
    exit(0);
}

int main(int argc, char **argv) {
    // Parse the sampling interval from the command line
    int interval = DEFAULT_INTERVAL;
    if (argc > 1) {
        interval = atoi(argv[1]);
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    int fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Send the start command to the sensor
    uint8_t start_command[] = {START_COMMAND, START_SUB_COMMAND};
    if (gpioI2cWrite(fd, start_command, 2) < 0) {
        fprintf(stderr, "Failed to send start command to sensor\n");
        gpioClose(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read from the sensor
        uint8_t data[NUM_BYTES];
        if (gpioI2cRead(fd, data, NUM_BYTES) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            gpioClose(fd);
            gpioTerminate();
            return 1;
        }

        // Verify the CRC-8 checksum on the pressure, temperature, and scale-factor words
        uint8_t pressure_crc = data[2];
        uint8_t temperature_crc = data[5];
        uint8_t scale_factor_crc = data[8];
        uint8_t pressure_msb = data[0];
        uint8_t pressure_lsb = data[1];
        uint8_t temperature_msb = data[3];
        uint8_t temperature_lsb = data[4];
        uint8_t scale_factor_msb = data[6];
        uint8_t scale_factor_lsb = data[7];

        uint8_t pressure_crc_calculated = crc8(data, 2);
        uint8_t temperature_crc_calculated = crc8(data + 3, 2);
        uint8_t scale_factor_crc_calculated = crc8(data + 6, 2);

        if (pressure_crc != pressure_crc_calculated || temperature_crc != temperature_crc_calculated || scale_factor_crc != scale_factor_crc_calculated) {
            fprintf(stderr, "CRC error: pressure 0x%02x, temperature 0x%02x, scale-factor 0x%02x (expected 0x%02x, 0x%02x, 0x%02x)\n",
                    pressure_crc, temperature_crc, scale_factor_crc, pressure_crc_calculated, temperature_crc_calculated, scale_factor_crc_calculated);
            gpioClose(fd);
            gpioTerminate();
            return 1;
        }

        // Convert the raw pressure using pressure_pa = raw_pressure / scale_factor
        uint32_t raw_pressure = (uint32x_t)pressure_msb << 8 | pressure_lsb;
        uint32_t scale_factor = (uint32_t)scale_factor_msb << 8 | scale_factor_lsb;
        float pressure_pa = (float)raw_pressure / scale_factor;

        // Log the reading to the console
        struct timeval tv;
        gettimeofday(&tv, NULL);
        printf("%ld.%06d Pa: %f\n", tv.tv_sec, tv.tv_usec, pressure_pa);

        // Sleep for the sampling interval
        usleep(interval * 1000);
    }

    // Release resources and exit cleanly
    gpioClose(fd);
    gpioTerminate();
    return 0;
}

// Calculate the CRC-8 checksum
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc = (crc ^ data[i]) ^ (crc >> 4);
        crc = (crc & 0x0F) ^ (crc >> 4);
    }
    return crc;
}

