#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x25

// Define the command to start continuous measurement
#define CONTINUOUS_MEASUREMENT 0x3615

// Define the CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the scale factors for pressure and temperature
#define SCALE_FACTOR_PRESSURE 0x0001
#define SCALE_FACTOR_TEMPERATURE 0x0002

// Function to calculate the CRC-8
uint8_t crc8(uint8_t *data, int len, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to handle SIGINT and SIGTERM
void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C bus
    if (gpioI2CSetClockSpeed(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C clock speed\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Send the continuous-measurement command
    uint8_t command[] = {CONTINUOUS_MEASUREMENT};
    if (gpioI2CWriteReg8(i2c_fd, I2C_ADDRESS, 0, command, 1) < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait for the conversion to complete
    usleep(45000);

    // Read the data from the sensor
    uint8_t data[NUM_BYTES];
    if (gpioI2CReadReg8(i2c_fd, I2C_ADDRESS, 0, data, NUM_BYTES) < 0) {
        fprintf(stderr, "Failed to read from I2C bus\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Validate the CRC-8 on each 3-byte data word
    for (int i = 0; i < NUM_BYTES; i += 3) {
        uint8_t crc = crc8(&data[i], 3, CRC_INITIAL_VALUE);
        if (crc != data[i + 2]) {
            fprintf(stderr, "CRC mismatch at offset 0x%02x\n", i);
            gpioClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Convert the raw values using the per-reading scale factors
    float pressure = (float)data[0] * 256 + data[1] / SCALE_FACTOR_PRESSURE;
    float temperature = (float)data[2] * 256 + data[3] / 200.0;

    // Log the results to stdout
    printf("Pressure: %.2f mbar, Temperature: %.2f°C\n", pressure, temperature);

    // Close the I2C handle
    gpioClose(i2c_fd);

    // Main loop
    while (1) {
        // Send the continuous-measurement command
        if (gpioI2CWriteReg8(i2c_fd, I2C_ADDRESS, 0, command, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            gpioTerminate();
            return 1;
        }

        // Wait for the conversion to complete
        usleep(45000);

        // Read the data from the sensor
        if (gpioI2CReadReg8(i2c_fd, I2C_ADDRESS, 0, data, NUM_BYTES) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            gpioTerminate();
            return 1;
        }

        // Validate the CRC-8 on each 3-byte data word
        for (int i = 0; i < NUM_BYTES; i += 3) {
            uint8_t crc = crc8(&data[i], 3, CRC_INITIAL_VALUE);
            if (crc != data[i + 2]) {
                fprintf(stderr, "CRC mismatch at offset 0x%02x\n", i);
                gpioTerminate();
                return 1;
            }
        }

        // Convert the raw values using the per-reading scale factors
        pressure = (float)data[0] * 256 + data[1] / SCALE_FACTOR_PRESSURE;
        temperature = (float)data[2] * 256 + data[3] / 200.0;

        // Log the results to stdout
        printf("Pressure: %.2f mbar, Temperature: %.2f°C\n", pressure, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}
