#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define CONFIG_REG 0x02
#define TEMP_REG 0x00
#define HUMIDITY_REG 0x01
#define DELAY_US 20000

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    char buffer[4];
    int config_value = 0x80; // Set bit 12 to enable combined measurement
    int temp, humidity;

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Configure I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Write configuration register
    if (write(i2c_fd, &config_value, 1) != 1) {
        perror("Failed to write configuration register");
        close(i2c_fd);
        exit(1);
    }

    while (running) {
        // Write temperature register
        if (write(i2c_fd, &TEMP_REG, 1) != 1) {
            perror("Failed to write temperature register");
            close(i2c_fd);
            exit(1);
        }

        // Wait for conversion to complete
        usleep(DELAY_US);

        // Read temperature and humidity
        if (read(i2c_fd, buffer, 4) != 4) {
            fprintf(stderr, "Failed to read temperature and humidity\n");
            continue;
        }

        // Convert raw values to temperature and humidity
        temp = (buffer[0] << 8) | buffer[1];
        humidity = (buffer[2] << 8) | buffer[3];
        temp = (temp / 65536.0) * 165.0 - 40.0;
        humidity = (humidity / 65536.0) * 100.0;

        // Print temperature and humidity
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);

        // Sleep for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

