#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Release resources and exit cleanly
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up I2C bus 1 (GPIO 2/3 for SDA/SCL)
    if (gpioSetMode(2, PI_I2C_SDA) < 0 || gpioSetMode(3, PI_I2C_SCL) < 0) {
        fprintf(stderr, "Failed to set up I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    int bus = gpioOpen(1);
    if (bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up Si7051 sensor at default 7-bit address 0x40
    if (i2cSetSlaveAddress(bus, 0x40) < 0) {
        fprintf(stderr, "Failed to set Si7051 sensor address\n");
        gpioTerminate();
        return 1;
    }

    // Function to read temperature from Si7051 sensor
    float read_temperature(int bus) {
        // Write temperature measurement command (0xE0)
        if (i2cWriteReg8(bus, 0xE0, 0x00) < 0) {
            return -1.0f; // Error: failed to write command
        }

        // Wait for measurement to complete (2.5ms)
        usleep(2500);

        // Read temperature measurement (2 bytes)
        uint8_t data[2];
        if (i2cReadReg8(bus, 0xE0, data, 2) < 0) {
            return -1.0f; // Error: failed to read data
        }

        // Convert temperature to Celsius
        float temperature = (data[0] << 8) | data[1];
        temperature = (temperature * 175.72) / 65536.0 - 46.85;

        return temperature;
    }

    // Main loop: read temperature every 5 seconds
    while (1) {
        float temperature = read_temperature(bus);
        if (temperature < 0.0f) {
            // Error: failed to read temperature
            fprintf(stderr, "Failed to read temperature\n");
            break;
        }

        printf("Temperature: %.2f°C\n", temperature);

        // Wait 5 seconds
        usleep(5000000);
    }

    // Release resources
    gpioTerminate();

    return 0;
}

