#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the pressure sensor register addresses
#define PRESSURE_REGISTER 0x00

// Define the signal handler function
void signal_handler(int sig) {
    // Release resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C bus
    int bus = gpioOpen(I2C_BUS, 1);
    if (bus < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up the I2C bus
    if (gpioI2CSetClockSpeed(bus, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C clock speed\n");
        gpioClose(bus);
        gpioTerminate();
        return 1;
    }

    // Initialize the pressure sensor
    uint8_t data[2];
    if (gpioI2CWriteReg8(bus, I2C_ADDRESS, PRESSURE_REGISTER, 0x00) < 0) {
        fprintf(stderr, "Failed to write to pressure sensor\n");
        gpioClose(bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the pressure value
        if (gpioI2CReadReg8(bus, I2C_ADDRESS, PRESSURE_REGISTER, data, 2) < 0) {
            fprintf(stderr, "Failed to read from pressure sensor\n");
            gpioClose(bus);
            gpioTerminate();
            return 1;
        }

        // Print the pressure value
        printf("%d.%03d mbar at %ld\n", (data[0] << 8) | data[1], 0, time(NULL));

        // Wait 500 ms
        usleep(500000);
    }

    // Release resources
    gpioClose(bus);
    gpioTerminate();

    return 0;
}

