code:
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x60

// Define the pressure sensor's registers
#define PRESSURE_MSB 0xAA
#define PRESSURE_LSB 0xAB

// Define the scaling factor for pressure conversion
#define PRESSURE_SCALE 0.1

// Function to handle I2C read/write errors
void i2c_error(const char *message) {
    fprintf(stderr, "I2C error: %s\n", message);
}

// Function to trigger a measurement and read the pressure value
uint16_t read_pressure(int i2c_fd) {
    // Trigger a measurement
    if (ioctl(i2c_fd, I2C_SLAVE_FORCE, I2C_ADDRESS) < 0) {
        i2c_error("Failed to set I2C slave address");
        return 0;
    }

    // Write the trigger command
    uint8_t trigger_cmd = 0x01;
    if (write(i2c_fd, &trigger_cmd, 1) != 1) {
        i2c_error("Failed to write trigger command");
        return 0;
    }

    // Read the pressure value
    uint8_t msb, lsb;
    if (read(i2c_fd, &msb, 1) != 1 || read(i2c_fd, &lsb, 1) != 1) {
        i2c_error("Failed to read pressure value");
        return 0;
    }

    // Combine the MSB and LSB into a 16-bit value
    uint16_t pressure = (msb << 8) | lsb;

    return pressure;
}

// Function to convert the raw pressure value to kPa
float pressure_to_kpa(uint16_t pressure) {
    return (float)pressure * PRESSURE_SCALE;
}

// Function to print a timestamp and pressure reading
void print_reading(float pressure) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    fprintf(stdout, "%s: %f kPa\n", timestamp, pressure);
}

// Signal handler to exit cleanly
void sigint_handler(int sig) {
    close(i2c_fd);
    exit(0);
}

int main() {
    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Install the signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to install signal handler");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the pressure value
        uint16_t pressure = read_pressure(i2c_fd);
        if (pressure == 0) {
            continue;
        }

        // Convert the pressure value to kPa
        float kpa = pressure_to_kpa(pressure);

        // Print the reading
        print_reading(kpa);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close the I2C file descriptor
    close(i2c_fd);

    return 0;
}

