#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define SDA_PIN 2
#define SCL_PIN 3
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define PRESSURE_SCALE 60.0
#define TEMPERATURE_SCALE 200.0

#define PRESSURE_LOG_FILE "pressure_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t addr, uint8_t reg, uint8_t* data, size_t len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .buf = data,
        .len = len
    };
    struct i2c_rdwr_ioctl_data i2c_msg = {
        .msgs = &msg,
        .nmsgs = 1
    };
    if (ioctl(fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t addr, uint8_t reg, uint8_t* data, size_t len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = I2C_M_RD,
        .buf = data,
        .len = len
    };
    struct i2c_rdwr_ioctl_data i2c_msg = {
        .msgs = &msg,
        .nmsgs = 1
    };
    if (ioctl(fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

uint8_t crc8(uint8_t* data, size_t len, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int fd = i2c_open();
    if (fd < 0) {
        return 1;
    }

    uint8_t data[9];
    if (i2c_write(fd, I2C_ADDRESS, 0x00, (uint8_t*)&CONTINUOUS_MEASUREMENT, 1) < 0) {
        close(fd);
        return 1;
    }

    usleep(45000);

    if (i2c_read(fd, I2C_ADDRESS, 0x00, data, 9) < 0) {
        close(fd);
        return 1;
    }

    uint16_t pressure = (data[1] << 8) | data[2];
    uint16_t temperature = (data[5] << 8) | data[6];
    uint8_t pressure_crc = data[3];
    uint8_t temperature_crc = data[7];

    if (crc8(data, 2, CRC_INIT) != pressure_crc || crc8(data + 4, 2, CRC_INIT) != temperature_crc) {
        fprintf(stderr, "CRC error\n");
        close(fd);
        return 1;
    }

    pressure /= PRESSURE_SCALE;
    temperature /= TEMPERATURE_SCALE;

    FILE* file = fopen(PRESSURE_LOG_FILE, "a");
    if (!file) {
        perror("fopen");
        close(fd);
        return 1;
    }

    fprintf(file, "%f,%f\n", pressure, temperature);
    fclose(file);

    close(fd);
    return 0;
}

