#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x36
#define MEASUREMENT_DATA 0x2F
#define MEASUREMENT_CRC_POLYNOMIAL 0x31
#define MEASUREMENT_CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_CRC_LENGTH 1
#define MEASUREMENT_DATA_LENGTH 2
#define MEASUREMENT_DELAY_US 8000

#define CSV_FILE "airflow_log.csv"

int i2c_fd = -1;
int gpio_fd = -1;

void crc8(uint8_t *data, size_t length, uint8_t *crc) {
    uint8_t crc_value = MEASUREMENT_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < length; i++) {
        crc_value = (crc_value ^ data[i]) ^ ((crc_value >> 4) & 0x0F);
        crc_value = (crc_value << 4) ^ ((crc_value >> 12) & 0x0F);
        crc_value = (crc_value << 4) ^ ((crc_value >> 8) & 0x0F);
        crc_value = (crc_value << 4) ^ ((crc_value >> 4) & 0x0F);
    }
    *crc = crc_value;
}

int main() {
    // Initialize GPIO
    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = gpioI2COpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    FILE *csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        if (access(CSV_FILE, F_OK) == -1) {
            csv_file = fopen(CSV_FILE, "w");
            if (csv_file == NULL) {
                fprintf(stderr, "Failed to open CSV file for writing\n");
                gpioI2CClose(i2c_fd);
                gpioTerminate();
                return 1;
            }
            fprintf(csv_file, "timestamp,pressure\n");
        } else {
            fprintf(stderr, "Failed to open CSV file for appending\n");
            gpioI2CClose(i2c_fd);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop
    while (1) {
        // Trigger measurement
        uint8_t command[] = {MEASUREMENT_COMMAND, MEASUREMENT_DATA};
        if (gpioI2CWriteReg8(i2c_fd, 0, command, 2) < 0) {
            fprintf(stderr, "Failed to write to I2C register\n");
            break;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_US);

        // Read measurement data
        uint8_t data[MEASUREMENT_DATA_LENGTH + MEASUREMENT_CRC_LENGTH];
        if (gpioI2CReadReg8(i2c_fd, 0, data, MEASUREMENT_DATA_LENGTH + MEASUREMENT_CRC_LENGTH) < 0) {
            fprintf(stderr, "Failed to read from I2C register\n");
            break;
        }

        // Verify CRC
        uint8_t crc;
        crc8(data, MEASUREMENT_DATA_LENGTH, &crc);
        if (crc != data[MEASUREMENT_DATA_LENGTH]) {
            fprintf(stderr, "Invalid CRC\n");
            break;
        }

        // Convert raw data to pressure
        int16_t pressure = (data[0] << 8) | data[1];
        if (pressure & 0x8000) {
            pressure -= 0x10000;
        }
        double pressure_pa = (double)pressure / 60.0;

        // Log pressure reading
        time_t timestamp = time(NULL);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
        fprintf(csv_file, "%s,%f\n", timestamp_str, pressure_pa);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C bus
    gpioI2CClose(i2c_fd);

    // Close CSV file
    fclose(csv_file);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

// Signal handlers
void sigint_handler(int signal) {
    // Close I2C bus
    gpioI2CClose(i2c_fd);

    // Close CSV file
    fclose(stdout);

    // Terminate GPIO
    gpioTerminate();

    exit(0);
}

void sigterm_handler(int signal) {
    // Close I2C bus
    gpioI2CClose(i2c_fd);

    // Close CSV file
    fclose(stdout);

    // Terminate GPIO
    gpioTerminate();

    exit(0);
}

// Register signal handlers
void setup_signal_handlers() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);
}

int main() {
    setup_signal_handlers();

    // ... (rest of the main function remains the same)
}

