#include <syslog.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x27
#define MEASUREMENT_DELAY_US 40
#define MEASUREMENT_INTERVAL_S 5
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_MAX_SIZE (1024 * 1024)

#define HIH6130_REG_MEASUREMENT 0x00
#define HIH6130_REG_STATUS 0x01
#define HIH6130_REG_DATA 0x02

#define HIH6130_STATUS_BUSY 0x80
#define HIH6130_STATUS_ERROR 0x40

int main() {
    int fd;
    int ret;
    uint8_t data[4];
    uint16_t raw_T, raw_H;
    double temperature, humidity;
    char timestamp[32];
    struct tm *timeinfo;
    FILE *log_file;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        i2cClose(fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Trigger measurement
        ret = i2cWriteReg8(fd, HIH6130_REG_MEASUREMENT, HIH6130_REG_MEASUREMENT);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to write to I2C register");
            fclose(log_file);
            i2cClose(fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_US * 1000);

        // Read data
        ret = i2cReadReg8(fd, HIH6130_REG_DATA, data, 4);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to read from I2C register");
            fclose(log_file);
            i2cClose(fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Validate status bits
        if ((data[0] & HIH6130_STATUS_BUSY) || (data[0] & HIH6130_STATUS_ERROR)) {
            syslog(LOG_ERR, "Invalid status bits");
            continue;
        }

        // Extract raw values
        raw_T = (data[1] << 8) | data[2];
        raw_H = (data[3] << 8) | data[2];

        // Convert raw values to temperature and humidity
        temperature = raw_T * 165.0 / 16383.0 - 40.0;
        humidity = raw_H * 100.0 / 16383.0;

        // Format timestamp
        timeinfo = localtime(time(NULL));
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

        // Log data
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file);

        // Check log file size
        if (fseek(log_file, 0, SEEK_END) == -1) {
            syslog(LOG_ERR, "Failed to seek log file");
            fclose(log_file);
            i2cClose(fd);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }
        if (ftell(log_file) >= LOG_FILE_MAX_SIZE) {
            fclose(log_file);
            log_file = fopen(LOG_FILE, "w");
            if (!log_file) {
                syslog(LOG_ERR, "Failed to open log file");
                i2cClose(fd);
                gpioTerminate();
                exit(EXIT_FAILURE);
            }
        }

        // Sleep
        sleep(MEASUREMENT_INTERVAL_S);
    }

    // Clean up
    fclose(log_file);
    i2cClose(fd);
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT, exiting");
    fclose(log_file);
    i2cClose(fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

// Initialize syslog
void init_syslog() {
    openlog("environmental_data", LOG_PID | LOG_PERROR, LOG_USER);
}

// Clean up syslog
void cleanup_syslog() {
    closelog();
}

