#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define SENT_TICKS_PER_US 1000
#define SENT_SYNC_PULSE 56
#define SENT_NIBBLE_MIN 12
#define SENT_NIBBLE_MAX 271
#define SENT_CHECKSUM_NIBBLE 0x0F
#define SENT_SCALE 0.00006103515625
#define SENT_OFFSET 0.0

// Global variables
bool running = true;
int fd;
uint8_t sync_count = 0;
uint8_t data[4] = {0};
uint8_t checksum = 0;
uint16_t pressure = 0;

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    running = false;
}

// Function to read pressure data from the SENT sensor
void read_pressure() {
    // Set up GPIO pin as input
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        exit(1);
    }

    // Read data from the sensor
    while (running) {
        // Wait for synchronization pulse
        uint32_t start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 1 && running) {
            if (gpioTick() - start_time > SENT_SYNC_PULSE * SENT_TICKS_PER_US) {
                // Timeout: sensor-absent condition
                fprintf(stderr, "Sensor-absent condition detected\n");
                break;
            }
        }
        if (!running) break;

        // Read status nibble
        uint32_t status_start_time = gpioTick();
        while (gpioRead(GPIO_PIN) == 0 && running) {
            if (gpioTick() - status_start_time > SENT_NIBBLE_MAX * SENT_TICKS_PER_US) {
                // Timeout: bus-error condition
                fprintf(stderr, "Bus-error condition detected\n");
                break;
            }
        }
        if (!running) break;
        uint8_t status_nibble = (gpioTick() - status_start_time) / (SENT_TICKS_PER_US * 12);
        if (status_nibble < SENT_NIBBLE_MIN || status_nibble > SENT_NIBBLE_MAX) {
            // Bus-error condition
            fprintf(stderr, "Bus-error condition detected\n");
            break;
        }
        checksum += status_nibble;

        // Read data nibbles
        for (int i = 0; i < 3; i++) {
            uint32_t data_start_time = gpioTick();
            while (gpioRead(GPIO_PIN) == 0 && running) {
                if (gpioTick() - data_start_time > SENT_NIBBLE_MAX * SENT_TICKS_PER_US) {
                    // Timeout: bus-error condition
                    fprintf(stderr, "Bus-error condition detected\n");
                    break;
                }
            }
            if (!running) break;
            uint8_t data_nibble = (gpioTick() - data_start_time) / (SENT_TICKS_PER_US * 12);
            if (data_nibble < SENT_NIBBLE_MIN || data_nibble > SENT_NIBBLE_MAX) {
                // Bus-error condition
                fprintf(stderr, "Bus-error condition detected\n");
                break;
            }
            data[i] = data_nibble;
            checksum += data_nibble;
        }

        // Check checksum
        if (checksum % 16 != 0) {
            // Bus-error condition
            fprintf(stderr, "Bus-error condition detected\n");
        } else {
            // Convert raw value to pressure
            pressure = (data[0] << 8) | data[1];
            pressure = (pressure * SENT_SCALE) + SENT_OFFSET;

            // Log pressure reading
            time_t now = time(NULL);
            struct tm *lt = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);
            FILE *fp = fopen("pressure_log.txt", "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open pressure log file\n");
                break;
            }
            fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
            fclose(fp);
        }

        // Reset checksum
        checksum = 0;
    }

    // Clean up
    gpioTerminate();
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    fd = gpioInitialise();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Start reading pressure data
    read_pressure();

    return 0;
}

