}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = gpioI2COpen(1, 0x48, NULL);
    if (i2c_fd == -1) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Verify device ID register
    uint8_t device_id[2];
    if (gpioI2CWriteReg8(i2c_fd, 0x00, 0x00) == -1) {
        fprintf(stderr, "Failed to write to device ID register\n");
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioI2CReadReg8(i2c_fd, 0x00, device_id, 2) == -1) {
        fprintf(stderr, "Failed to read from device ID register\n");
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (device_id[0] != 0x11 || device_id[1] != 0x17) {
        fprintf(stderr, "Invalid device ID: 0x%02x%02x\n", device_id[0], device_id[1]);
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open file for writing
    FILE *fp = fopen("greenhouse_temps.dat", "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up SIGINT handler\n");
        fclose(fp);
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up SIGTERM handler\n");
        fclose(fp);
        gpioI2CClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read temperature register
        uint8_t temp[2];
        if (gpioI2CWriteReg8(i2c_fd, 0x00, 0x00) == -1) {
            fprintf(stderr, "Failed to write to temperature register\n");
            break;
        }
        if (gpioI2CReadReg8(i2c_fd, 0x00, temp, 2) == -1) {
            fprintf(stderr, "Failed to read from temperature register\n");
            break;
        }

        // Convert temperature to float
        int16_t temp_int = (temp[0] << 8) | temp[1];
        float temp_float = (float)temp_int * 0.0078125;

        // Write temperature to file
        fwrite(&temp_float, sizeof(float), 1, fp);

        // Sleep for 60 seconds
        usleep(60000000);
    }

    // Release resources on exit
    fclose(fp);
    gpioI2CClose(i2c_fd);
    gpioTerminate();
    return 0;
}

