#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Function to calculate CRC-8 checksum
uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw temperature and humidity values to Celsius and %RH
void convert_values(uint16_t raw_temp, uint16_t raw_hum, float *temp, float *hum) {
    *temp = -45 + 175 * (raw_temp / 65535.0);
    *hum = -6 + 125 * (raw_hum / 65535.0);
}

// Signal handler to handle SIGINT
void sigint_handler(int sig) {
    // Close I2C handle
    if (i2c_close(I2C_BUS_1) < 0) {
        perror("i2c_close");
        exit(EXIT_FAILURE);
    }

    // Terminate pigpio
    if (gpioTerminate() < 0) {
        perror("gpioTerminate");
        exit(EXIT_FAILURE);
    }

    // Close log file
    if (fclose(log_file) != 0) {
        perror("fclose");
        exit(EXIT_FAILURE);
    }

    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus 1
    int i2c_bus = i2cOpen(I2C_BUS_1, 0);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file in append mode
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(i2c_bus);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Send high-precision measurement command
        uint8_t command[] = {0xFD};
        if (i2cWriteReg(i2c_bus, 0x44, 0, command, 1) < 0) {
            fprintf(stderr, "Failed to write to I2C bus\n");
            break;
        }

        // Wait for conversion
        usleep(8500000);

        // Read 6 bytes from I2C bus
        uint8_t data[6];
        if (i2cReadReg(i2c_bus, 0x44, 0, data, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            break;
        }

        // Validate CRC-8 checksum for temperature
        uint8_t crc_temp = crc8(data, 2, 0x31, 0xFF);
        if (crc_temp != data[2]) {
            fprintf(stderr, "Invalid CRC-8 checksum for temperature\n");
            break;
        }

        // Validate CRC-8 checksum for humidity
        uint8_t crc_hum = crc8(data + 3, 2, 0x31, 0xFF);
        if (crc_hum != data[5]) {
            fprintf(stderr, "Invalid CRC-8 checksum for humidity\n");
            break;
        }

        // Convert raw values to Celsius and %RH
        float temp, hum;
        convert_values((data[0] << 8) | data[1], (data[3] << 8) | data[4], &temp, &hum);

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temp, hum);
        fflush(log_file);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    return EXIT_SUCCESS;
}

