#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define FILE_NAME "temperature_log.dat"
#define TEMPERATURE_REGISTER 0x00
#define TEMPERATURE_RESOLUTION 0.0078125
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define SAMPLE_INTERVAL 5000000 // 5 seconds in microseconds

// Structure to represent a temperature reading
typedef struct {
    uint16_t timestamp;
    float temperature;
} TemperatureReading;

// Function to handle signal to exit
void signal_handler(int signal) {
    // Flush the buffer to the file
    if (fwrite(buffer, sizeof(TemperatureReading), buffer_size, fp) != buffer_size) {
        perror("fwrite");
    }

    // Release the I2C handle
    if (i2c_close(i2c_handle) != 0) {
        perror("i2c_close");
    }

    // Release the pigpio handle
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
    }
    gpioTerminate();

    // Close the file
    fclose(fp);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        perror("i2cOpen");
        gpioTerminate();
        return 1;
    }

    // Open the file for binary writing
    fp = fopen(FILE_NAME, "ab");
    if (fp == NULL) {
        perror("fopen");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the buffer
    buffer_size = 0;
    buffer = malloc(BUFFER_SIZE * sizeof(TemperatureReading));
    if (buffer == NULL) {
        perror("malloc");
        fclose(fp);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the temperature register
        uint8_t data[2];
        if (i2cRead(i2c_handle, TEMPERATURE_REGISTER, data, 2) != 0) {
            fprintf(stderr, "Error reading temperature register\n");
            continue;
        }

        // Convert the temperature
        uint16_t temperature = (data[0] << 8) | data[1];
        float temp = (float)temperature * TEMPERATURE_RESOLUTION;

        // Add the reading to the buffer
        if (buffer_size >= BUFFER_SIZE) {
            buffer_size = 0;
        }
        buffer[buffer_size].timestamp = (uint16_t)time(NULL);
        buffer[buffer_size].temperature = temp;
        buffer_size++;

        // Write the buffer to the file
        if (fwrite(buffer, sizeof(TemperatureReading), buffer_size, fp) != buffer_size) {
            perror("fwrite");
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    return 0;
}

