#define SHTC3_ADDRESS 0x70
#define SHTC3_MEASUREMENT_COMMAND 0x7866
#define SHTC3_CRC_POLYNOMIAL 0x31
#define SHTC3_CRC_INITIAL_VALUE 0xFF

// Function to calculate CRC-8
uint8_t shtc3_crc8(uint8_t *data, size_t len) {
    uint8_t crc = SHTC3_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SHTC3_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw temperature and humidity values to Celsius and percentage
void shtc3_convert(uint16_t raw, uint16_t *temperature, uint16_t *humidity) {
    *temperature = (175 * raw / 65535) - 45;
    *humidity = (100 * raw / 65535);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up I2C bus 1
    int i2c_bus = gpioOpen(1, 2); // SDA
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up I2C address
    if (gpioI2CSetSlaveAddress(i2c_bus, SHTC3_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioI2CClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("shtc3_environment.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioI2CClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Issue measurement command
        if (gpioI2CWriteByte(i2c_bus, SHTC3_MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Failed to issue measurement command\n");
            break;
        }

        // Wait for conversion
        usleep(1240000);

        // Read data
        uint8_t data[6];
        if (gpioI2CRead(i2c_bus, data, 6) < 0) {
            fprintf(stderr, "Failed to read data\n");
            break;
        }

        // Validate CRC
        if (shtc3_crc8(data, 2) != data[2] || shtc3_crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC failure\n");
            continue;
        }

        // Convert raw values
        uint16_t temperature, humidity;
        shtc3_convert((data[0] << 8) | data[1], &temperature, &humidity);

        // Validate temperature and humidity
        if (temperature < -40 || temperature > 125 || humidity < 0 || humidity > 100) {
            fprintf(stderr, "Out-of-range values\n");
            continue;
        }

        // Log and print readings
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Sleep
        sleep(5);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    gpioI2CClose(i2c_bus);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close I2C handle
    gpioI2CClose(i2c_bus);

    // Terminate GPIO
    gpioTerminate();

    // Exit cleanly
    exit(0);
}

// Register signal handler for SIGINT
void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
