#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define LOG_FILE "mag_temp_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(i2c_fd));
        return 1;
    }

    int i2c_bus = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioErrorStr(i2c_bus));
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    char header[] = "time,magnetic_field,G,temperature,C\n";
    if (fseek(log_file, 0, SEEK_END) == -1 || fwrite(header, 1, strlen(header), log_file) != strlen(header)) {
        fprintf(stderr, "Failed to write header to log file: %s\n", strerror(errno));
        fclose(log_file);
        gpioClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    struct tm *timeinfo;
    time_t rawtime;
    while (running) {
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        uint16_t raw_value;
        if (i2cReadReg8(i2c_bus, 0x00, &raw_value) < 0) {
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
        } else {
            float field_gauss = raw_value * 0.1;
            float temp_celsius = raw_value * 0.01 - 25.0;
            fprintf(log_file, "%s,%f,%f\n", timestamp, field_gauss, temp_celsius);
        }

        sleep(1);
    }

    fclose(log_file);
    gpioClose(i2c_bus);
    gpioTerminate();

    return 0;
}

