#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define REG_TEMP 0x00
#define RESOLUTION 0.0078125

static bool running = true;
static int i2c_handle;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = gpioOpen(I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open log file
    FILE *log_file = fopen("temperature_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    for (int i = 0; i < 3; i++) {
        if (gpioI2COpen(i2c_handle, I2C_ADDRESS) < 0) {
            fprintf(stderr, "Failed to initialize I2C handle (attempt %d)\n", i + 1);
            if (i < 2) {
                sleep(1);
            } else {
                gpioClose(i2c_handle);
                gpioTerminate();
                fclose(log_file);
                return 1;
            }
        } else {
            break;
        }
    }

    while (running) {
        // Read temperature
        uint16_t temp;
        if (gpioI2CReadReg8(i2c_handle, REG_TEMP, &temp, 2) < 0) {
            fprintf(stderr, "Failed to read temperature\n");
            gpioI2CClose(i2c_handle);
            gpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Convert temperature
        int16_t temp_int = (int16_t)temp;
        float temp_float = (float)temp_int * RESOLUTION;

        // Log temperature
        char log_str[32];
        time_t now = time(NULL);
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, Temperature: %.3f C\n", log_str, temp_float);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C handle and terminate GPIO
    gpioI2CClose(i2c_handle);
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

