#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    struct tm *timestamp;
    time_t rawtime;
    char timestamp_str[20];

    while (running) {
        time(&rawtime);
        timestamp = localtime(&rawtime);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp);

        int result = i2cReadDevice(i2c_fd, I2C_BUS, I2C_ADDRESS, 0, 4, NULL, NULL);
        if (result < 0) {
            fprintf(stderr, "Failed to read from I2C device: %d\n", result);
            if (i2c_fd >= 0) {
                i2c_close(i2c_fd);
                i2c_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
                if (i2c_fd < 0) {
                    fprintf(stderr, "Failed to re-open I2C device\n");
                    break;
                }
            }
            continue;
        }

        uint16_t raw_flow = (result >> 8) | (result & 0xFF);
        uint16_t raw_temp = (result >> 16) | ((result & 0xFF) << 8);

        float flow = ((float)raw_flow / 16384.0) - 0.1) / 0.8 * 25.0;
        float temp = ((float)raw_temp / 4096.0) - 0.1) / 0.8 * 80.0 - 40.0;

        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp_str, flow, temp);
        fflush(log_file);

        usleep(1000000); // 1 second
    }

    fclose(log_file);
    i2c_close(i2c_fd);
    gpioTerminate();

    return 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    return main();
}

