            fprintf(stderr, "DHT11: Checksum failure\n");
            fprintf(log_file, "%s: DHT11: Checksum failure\n", ctime(&start.tv_sec));
            continue;
        }

        fprintf(log_file, "%s: DHT11: Humidity: %d%%, Temperature: %d°C\n", ctime(&start.tv_sec), data[0], data[2]);
        fflush(log_file);

        gettimeofday(&end, NULL);
        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec) > DHT11_SAMPLE_INTERVAL_S * 1000000) {
            fprintf(stderr, "DHT11: Sample interval exceeded\n");
            fprintf(log_file, "%s: DHT11: Sample interval exceeded\n", ctime(&start.tv_sec));
            continue;
        }

        usleep(DHT11_SAMPLE_INTERVAL_S * 1000000);
    }

    return 0;
