#define SHT31_ADDRESS 0x44
#define SHT31_MEASUREMENT_COMMAND 0x2C06
#define SHT31_TEMPERATURE_REGISTER 0xE3
#define SHT31_HUMIDITY_REGISTER 0xE5
#define SHT31_CRC_POLYNOMIAL 0x31
#define SHT31_CRC_INITIAL_VALUE 0xFF

#define LOG_FILE "sht31d_data.log"

void sigint_handler(int signal) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        exit(1);
    }
    if (i2cOpen(1, SHT31_ADDRESS) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        exit(1);
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int signal) {
    sigint_handler(signal);
}

int validate_crc8(uint8_t data, uint8_t crc) {
    uint8_t calculated_crc = 0xFF;
    for (int i = 0; i < 8; i++) {
        if (calculated_crc & 0x80) {
            calculated_crc = (calculated_crc << 1) ^ SHT31_CRC_POLYNOMIAL;
        } else {
            calculated_crc = calculated_crc << 1;
        }
        calculated_crc ^= data & 0x01;
        data >>= 1;
    }
    return calculated_crc == crc;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    if (i2cOpen(1, SHT31_ADDRESS) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(1);
        gpioTerminate();
        return 1;
    }

    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    while (1) {
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        int retry_count = 0;
        while (retry_count < 3) {
            if (i2cWrite(1, SHT31_ADDRESS, 1, &SHT31_MEASUREMENT_COMMAND) < 0) {
                fprintf(stderr, "Error writing to I2C bus\n");
                retry_count++;
                usleep(500000); // 0.5 seconds
                continue;
            }
            usleep(15000); // 15 ms
            uint8_t data[6];
            if (i2cRead(1, SHT31_ADDRESS, 6, data) < 0) {
                fprintf(stderr, "Error reading from I2C bus\n");
                retry_count++;
                usleep(500000); // 0.5 seconds
                continue;
            }
            if (validate_crc8(data[2], data[3]) && validate_crc8(data[4], data[5])) {
                uint16_t temperature = (data[0] << 8) | data[1];
                uint16_t humidity = (data[2] << 8) | data[3];
                float temp = -45 + 175 * temperature / 65535;
                float humid = 100 * humidity / 65535;
                fprintf(log_file, "%s,%f,%f\n", timestamp, temp, humid);
                break;
            } else {
                fprintf(stderr, "Error validating CRC\n");
                retry_count++;
                usleep(500000); // 0.5 seconds
            }
        }
        if (retry_count == 3) {
            fprintf(stderr, "Error: persistent sensor failure\n");
            fprintf(log_file, "%s,Error: persistent sensor failure\n", timestamp);
        }
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        usleep(5000000); // 5 seconds
    }

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }
    i2cClose(1);
    gpioTerminate();
    return 0;
}

void handler(int signal) {
    sigint_handler(signal);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    return main();
}

