#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDRESS 0x64
#define SENSOR2_ADDRESS 0x65
#define DEVICE_ID_REGISTER 0x00
#define RED_CHANNEL_REGISTER 0x64
#define GREEN_CHANNEL_REGISTER 0x66
#define BLUE_CHANNEL_REGISTER 0x68
#define NUM_SENSORS 2
#define CSV_FILE "cct_log.csv"

// Function to compute Correlated Color Temperature (CCT) using McCamy's formula
double compute_cct(uint16_t red, uint16_t green, uint16_t blue) {
    double r = (double)red / 1024;
    double g = (double)green / 1024;
    double b = (double)blue / 1024;
    double r_prime = r / (r + g + b);
    double g_prime = g / (r + g + b);
    double b_prime = b / (r + g + b);
    double cct = 449 * pow(r_prime, 2) + 352 * g_prime + 279 * b_prime + 16;
    return cct;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Release I2C handles
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2cClose(i2cOpen(I2C_BUS, SENSOR1_ADDRESS + i)) != 0) {
                fprintf(stderr, "Error closing I2C handle for sensor %d\n", i);
            }
        }

        // Close file streams
        fclose(log_file);

        // Terminate pigpio
        pigpioTerminate();

        // Exit the program
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (pigpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        log_file = fopen(CSV_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file\n");
            pigpioTerminate();
            return 1;
        }
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }

    // Open I2C handles
