#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PRESSURE_REGISTER 0x0A2C
#define TEMPERATURE_REGISTER 0x0A2E
#define PRESSURE_MIN 0
#define PRESSURE_MAX 800
#define PRESSURE_OUTPUT_MIN 0
#define PRESSURE_OUTPUT_MAX 32768
#define TEMPERATURE_OFFSET -40
#define LOG_FILE "pressure_log.txt"

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioError());
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", gpioError());
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read pressure and temperature registers
        uint16_t pressure_raw, temperature_raw;
        if (i2cReadReg8(i2c_fd, I2C_ADDRESS, PRESSURE_REGISTER, 2, (uint8_t*)&pressure_raw) < 0) {
            fprintf(stderr, "%s: Failed to read pressure register: %s\n", ctime(&time(NULL)), gpioError());
            continue;
        }
        if (i2cReadReg8(i2c_fd, I2C_ADDRESS, TEMPERATURE_REGISTER, 2, (uint8_t*)&temperature_raw) < 0) {
            fprintf(stderr, "%s: Failed to read temperature register: %s\n", ctime(&time(NULL)), gpioError());
            continue;
        }

        // Convert raw values to pressure and temperature
        uint16_t pressure_kPa = (pressure_raw - PRESSURE_OUTPUT_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (PRESSURE_OUTPUT_MAX - PRESSURE_OUTPUT_MIN);
        float temperature_C = temperature_raw * 0.01 - TEMPERATURE_OFFSET;

        // Log results
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_kPa, temperature_C);

        // Sleep for 2 seconds
        usleep(2000000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    gpioClose(i2c_fd);

    // Terminate GPIO
    gpioTerminate();

    return 0;
}

