#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TEMPERATURE_REGISTER 0x00
#define LM75B_ADDRESS 0x48
#define FAN_GPIO 18
#define CIRCULAR_BUFFER_SIZE 60
#define HYS 2.0

volatile bool running = true;
uint16_t circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;
float running_average = 0.0;
bool fan_on = false;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void init_i2c() {
    int i2c_fd = gpioOpen(LM75B_ADDRESS, 1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
}

void read_temperature() {
    uint8_t data[2];
    if (i2cRead(i2c_fd, TEMPERATURE_REGISTER, data, 2) < 0) {
        fprintf(stderr, "Failed to read temperature\n");
        return;
    }
    int16_t temperature = (data[0] << 8) | data[1];
    temperature = (temperature & 0x1FF) - 256; // signed 9-bit format
    circular_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
    running_average = (running_average * (CIRCULAR_BUFFER_SIZE - 1) + temperature) / CIRCULAR_BUFFER_SIZE;
}

void control_fan() {
    if (running_average > 28.0 + HYS && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = true;
    } else if (running_average <= 26.0 - HYS && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = false;
    }
}

int main() {
    atexit(gpioTerminate);
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_pigpio();
    init_i2c();

    while (running) {
        read_temperature();
        control_fan();
        usleep(1000000);
    }

    gpioWrite(FAN_GPIO, 0);
    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

