#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>
#include <errno.h>

// Sensirion SDP810-500Pa sensor constants
#define SDP810_I2C_ADDRESS 0x25
#define SDP810_MEAS_CONT_CMD 0x362F
#define SDP810_MEAS_CONT_CMD_LEN 1
#define SDP810_MEAS_DATA_LEN 10
#define SDP810_CRC_POLYNOMIAL 0x31
#define SDP810_CRC_INIT 0xFF
#define SDP810_PRESS_SCALE 60
#define SDP810_TEMP_SCALE 200

// Log file path
#define LOG_FILE "airflow.log"

// Function to calculate CRC-8
uint8_t sdp810_crc8(uint8_t *data, size_t len, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SDP810_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int sdp810_read_data(int i2c_fd, uint8_t *data) {
    // Send the continuous-measurement command
    if (i2c_write(i2c_fd, SDP810_I2C_ADDRESS, SDP810_MEAS_CONT_CMD, SDP810_MEAS_CONT_CMD_LEN, 0) < 0) {
        fprintf(stderr, "Error sending command to SDP810 sensor: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the first measurement
    usleep(45000);

    // Read 9 bytes from the sensor
