#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x4A
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

int main() {
    int i2c_fd = -1;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Initialize libgpiod
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Open GPIO line
    line = gpiod_line_create_with_chip(chip, GPIO_LINE);
    if (!line) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO direction
    ret = gpiod_line_request_output(line, 0);
    if (ret < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        perror("Failed to set GPIO direction");
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        uint16_t temperature;
        int hysteresis_band = 1; // 1°C

        // Read temperature from I2C
        ret = i2c_smbus_read_word_data(i2c_fd, 0x00);
        if (ret < 0) {
            if (errno == EIO) {
                perror("Failed to read temperature from I2C");
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                close(i2c_fd);
                exit(EXIT_FAILURE);
            } else {
                perror("Failed to read temperature from I2C");
                continue;
            }
        }
        temperature = ret;

        // Combine MSB and LSB
        temperature = (temperature << 8) | (i2c_smbus_read_word_data(i2c_fd, 0x01) & 0xFF);

        // Right-shift result by 4 bits
        temperature >>= 4;

        // Convert to Celsius
        temperature *= 0.0625;

        // Drive LED based on temperature
        if (temperature > 28 + hysteresis_band) {
            ret = gpiod_line_set_value(line, 1);
            if (ret < 0) {
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                close(i2c_fd);
                perror("Failed to set GPIO high");
                exit(EXIT_FAILURE);
            }
        } else if (temperature < 27 - hysteresis_band) {
            ret = gpiod_line_set_value(line, 0);
            if (ret < 0) {
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                close(i2c_fd);
                perror("Failed to set GPIO low");
                exit(EXIT_FAILURE);
            }
        }

        // Log temperature
        printf("Temperature: %.2f°C\n", temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    // Handle SIGINT/SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    return 0;
}

void cleanup(int sig) {
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

