// Function to calculate CRC-8
uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the sensor
bool read_sensor_data(int fd, uint8_t *data) {
    // Send the continuous-measurement command
    if (i2c_write(fd, 0x25, 1, 1, &0x362F, 1) < 0) {
        fprintf(stderr, "Error sending command to sensor\n");
        return false;
    }

    // Wait at least 45 ms
    usleep(45000);

    // Read 9 bytes from the sensor
    if (i2c_read(fd, 0x25, 1, 1, data, 9) < 0) {
        fprintf(stderr, "Error reading from sensor\n");
        return false;
    }

    // Validate CRC-8 for pressure and temperature readings
    uint8_t pressure_crc = crc8(data, 3, 0x31, 0xFF);
    uint8_t temperature_crc = crc8(data + 4, 3, 0x31, 0xFF);
    if (pressure_crc != data[3] || temperature_crc != data[7]) {
        fprintf(stderr, "Invalid CRC\n");
        return false;
    }

    // Convert raw differential pressure and temperature
    int32_t pressure = (int32_t)((data[0] << 8) | data[1]) / (int32_t)((data[8] << 8) | data[9]);
    float temperature = (float)((data[2] << 8) | data[4]) / 200.0f;

    // Log the reading
    char timestamp[20];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "%s: Pressure: %d Pa, Temperature: %.2f°C\n", timestamp, pressure, temperature);
    FILE *fp = fopen("flow_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return false;
    }
    fprintf(fp, "%s: Pressure: %d Pa, Temperature: %.2f°C\n", timestamp, pressure, temperature);
    fclose(fp);

    return true;
}

