        fprintf(stderr, "Error setting up signal handler\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (true) {
        if (!read_sensor_data(fd, NULL)) {
            break;
        }
        usleep(100000); // 100 ms
    }

    // Release resources
    i2cClose(fd);
    gpioTerminate();

