    for (int i = 0; i < retry; i++) {
        if (gpioI2CRead(bus, address, 1, &result) == 0) {
            return result;
        }
        usleep(100000); // 100ms delay
    }
    fprintf(stderr, "Error reading from I2C bus %d at address 0x%02x: %s\n", bus, address, strerror(errno));
    exit(1);
}

// Function to write a byte to the I2C bus
void i2cWriteByte(int bus, int address, uint8_t value, int retry) {
    for (int i = 0; i < retry; i++) {
        if (gpioI2CWrite(bus, address, 1, &value) == 0) {
            return;
        }
        usleep(100000); // 100ms delay
    }
    fprintf(stderr, "Error writing to I2C bus %d at address 0x%02x: %s\n", bus, address, strerror(errno));
    exit(1);
}

// Function to read 2 bytes from the I2C bus
uint16_t i2cRead16(int bus, int address, int retry) {
    uint8_t high, low;
    high = i2cReadByte(bus, address, retry);
    low = i2cReadByte(bus, address, retry);
    return (high << 8) | low;
}

// Function to read temperature and humidity from the Si7021 sensor
void readSi7021(int bus, int address) {
    uint8_t id;
    id = i2cReadByte(bus, address, I2C_RETRY);
    if (id != 0x34) {
