    i2cWriteByte(bus, address, 0x00, I2C_RETRY);
    i2cReadByte(bus, address, I2C_RETRY);

    // Read firmware revision
    i2cWriteByte(bus, address, 0x00, I2C_RETRY);
    i2cReadByte(bus, address, I2C_RETRY);

