int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_bus = i2cOpen(I2C_BUS_1, 1);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        i2c_close(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Set up I2C address for HDC1080
    uint8_t address = 0x40;

    // Configure HDC1080 for 14-bit temperature and humidity resolution
    uint8_t config = 0x03; // 0x02 for 14-bit temperature, 0x03 for 14-bit humidity
