#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Sensirion STS40 temperature sensor constants
#define STS40_ADDRESS 0x44
#define STS40_MEAS_HIGH_REP 0x2C
#define STS40_MEAS_HIGH_REP_CMD 0xE0
#define STS40_CRC_POLYNOMIAL 0x31
#define STS40_CRC_INIT 0xFF

// CRC8 calculation function
uint8_t sts40_crc8(uint8_t *data, size_t len) {
    uint8_t crc = STS40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ STS40_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for clean shutdown
void sigint_handler(int sig) {
    if (sts40_fd >= 0) {
        close(sts40_fd);
    }
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    exit(0);
}

int main() {
    // Open I2C adapter
    sts40_fd = open("/dev/i2c-1", O_RDWR);
    if (sts40_fd < 0) {
        fprintf(stderr, "Error opening I2C adapter: %s\n", strerror(errno));
        return 1;
    }

    // Set slave address
    if (ioctl(sts40_fd, I2C_SLAVE, STS40_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(sts40_fd);
        return 1;
    }

    // Open log file
    log_fd = fopen("temperature_log.txt", "a");
    if (log_fd == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(sts40_fd);
        return 1;
    }

    // Install signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        close(sts40_fd);
        fclose(log_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send measurement command
        uint8_t cmd[] = {STS40_MEAS_HIGH_REP, STS40_MEAS_HIGH_REP_CMD};
        if (write(sts40_fd, cmd, 2) != 2) {
            fprintf(stderr, "Error sending measurement command: %s\n", strerror(errno));
            continue;
        }

        // Wait for conversion
        usleep(10000);

        // Read data
        uint8_t data[3];
        if (read(sts40_fd, data, 3) != 3) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            continue;
        }

        // Validate CRC
        uint8_t crc = sts40_crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC mismatch: expected 0x%02x, got 0x%02x\n", crc, data[2]);
            continue;
        }

        // Convert raw ticks to Celsius
        uint16_t raw = (data[0] << 8) | data[1];
        float temperature = -45 + 175 * raw / 65535.0;

        // Log temperature
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_fd, "%s %.2f°C\n", timestamp, temperature);

        // Sleep for 5 seconds
        sleep(5);
    }

    return 0;
}

