#include <fcntl.h>
#include <syslog.h>
#include <pthread.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SCD40_I2C_ADDRESS 0x62
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_CRC_POLYNOMIAL 0x31
#define SCD40_CRC_INITIAL_VALUE 0xFF
#define CSV_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define LOG_DIR "/var/log/scd40_data"
#define LOG_FILE "scd40_data.csv"
#define LOG_ERROR_FILE "scd40_error.log"

volatile sig_atomic_t running = 1;

typedef struct {
    int timestamp;
    int co2;
    float temperature;
    float humidity;
} reading_t;

pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
reading_t buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void log_error(const char *message) {
    FILE *file = fopen(ERROR_LOG, "a");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open error log file: %s", strerror(errno));
        return;
    }
    fprintf(file, "%lu: %s\n", time(NULL), message);
    fclose(file);
}

void *log_thread(void *arg) {
    while (running) {
        sleep(60);
        pthread_mutex_lock(&buffer_mutex);
        FILE *file = fopen(CSV_FILE, "a");
        if (file == NULL) {
            log_error("Failed to open CSV file for writing");
            pthread_mutex_unlock(&buffer_mutex);
            continue;
        }
        fprintf(file, "timestamp,co2,temperature,humidity\n");
        for (int i = 0; i < BUFFER_SIZE; i++) {
            int index = (buffer_head + i) % BUFFER_SIZE;
            if (buffer[index].timestamp != 0) {
                fprintf(file, "%d,%d,%.2f,%.2f\n", buffer[index].timestamp, buffer[index].co2, buffer[index].temperature, buffer[index].humidity);
            }
        }
        fclose(file);
        pthread_mutex_unlock(&buffer_mutex);
    }
    return NULL;
}

int crc8(uint8_t *data, int len, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    int i2c_fd = gpioOpen(1, 1);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    if (gpioI2CSetClockSpeed(i2c_fd, 100000) < 0) {
        log_error("Failed to set I2C clock speed");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioI2CSetSlaveAddress(i2c_fd, SCD40_I2C_ADDRESS, 0) < 0) {
        log_error("Failed to set I2C slave address");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    pthread_t log_thread_id;
    if (pthread_create(&log_thread_id, NULL, log_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        if (gpioI2CWriteByte(i2c_fd, SCD40_START_PERIODIC_MEASUREMENT) < 0) {
            log_error("Failed to send start-periodic-measurement command");
            continue;
        }
        sleep(1);

        for (int i = 0; i < 10; i++) {
            uint8_t data[9];
            if (gpioI2CRead(i2c_fd, SCD40_I2C_ADDRESS, 9, data) < 0) {
                log_error("Failed to read measurement data");
                continue;
            }

            if (data[8] != crc8(data, 8, SCD40_CRC_POLYNOMIAL, SCD40_CRC_INITIAL_VALUE)) {
                log_error("CRC check failed");
                continue;
            }

            int timestamp = time(NULL);
            int co2 = (data[0] << 8) | data[1];
            float temperature = -45 + 175 * (data[2] << 8 | data[3]) / 65535.0f;
            float humidity = 100 * (data[4] << 8 | data[5]) / 65535.0f;

            pthread_mutex_lock(&buffer_mutex);
            buffer[buffer_head].timestamp = timestamp;
            buffer[buffer_head].co2 = co2;
            buffer[buffer_head].temperature = temperature;
            buffer[buffer_head].humidity = humidity;
            buffer_head = (buffer_head + 1) % BUFFER_SIZE;
            pthread_mutex_unlock(&buffer_mutex);
        }

        sleep(5);
    }

    if (gpioI2CWriteByte(i2c_fd, SCD40_STOP_PERIODIC_MEASUREMENT) < 0) {
        log_error("Failed to send stop-periodic-measurement command");
    }

    pthread_join(log_thread_id, NULL);

    pthread_mutex_lock(&buffer_mutex);
    FILE *file = fopen(CSV_FILE, "a");
    if (file == NULL) {
        log_error("Failed to open CSV file for writing");
        pthread_mutex_unlock(&buffer_mutex);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    fprintf(file, "timestamp,co2,temperature,humidity\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_head + i) % BUFFER_SIZE;
        if (buffer[index].timestamp != 0) {
            fprintf(file, "%d,%d,%.2f,%.2f\n", buffer[index].timestamp, buffer[index].co2, buffer[index].temperature, buffer[index].humidity);
        }
    }
    fclose(file);
    pthread_mutex_unlock(&buffer_mutex);

    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    signal(SIGINT, sigint_handler);
    return main();
}

