#define I2C_BUS 1
#define I2C_ADDRESS 0x63
#define REG_WHO_AM_I 0x08
#define REG_PRESSURE_MSB 0x00
#define REG_PRESSURE_LSB 0x01
#define REG_TEMPERATURE_MSB 0x02
#define REG_TEMPERATURE_LSB 0x03
#define REG_CALIBRATION_MSB 0x05
#define REG_CALIBRATION_LSB 0x06
#define REG_CALIBRATION_LSB2 0x07
#define REG_CALIBRATION_LSB3 0x08

#define PRESSURE_LSB 0x00
#define PRESSURE_MSB 0x01
#define TEMPERATURE_LSB 0x02
#define TEMPERATURE_MSB 0x03

#define CALIBRATION_LSB 0x05
#define CALIBRATION_LSB2 0x06
#define CALIBRATION_LSB3 0x07

#define CALIBRATION_LSB4 0x08

#define PRESSURE_SCALE 0.00006103515625
#define TEMPERATURE_SCALE 0.0625

#define FILENAME "environmental_data.txt"

volatile bool exit_flag = false;

void sigint_handler(int sig) {
    exit_flag = true;
}

int main() {
    int i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (gpioI2CSetMode(i2c_fd, I2C_MODE_I2C) < 0) {
        fprintf(stderr, "Failed to set I2C mode: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        return 1;
    }

    if (gpioI2CSetClockSpeed(i2c_fd, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C clock speed: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        return 1;
    }

    if (gpioI2CSetSlaveAddress(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        return 1;
    }

    if (gpioI2CSetClockStretchLimit(i2c_fd, 100) < 0) {
        fprintf(stderr, "Failed to set I2C clock stretch limit: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        return 1;
    }

    FILE *file = fopen(FILENAME, "a");
    if (!file) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        return 1;
    }

    struct tm time;
    time_t now;
    char timestamp[20];

    while (!exit_flag) {
        if (gpioI2CWriteByte(i2c_fd, REG_WHO_AM_I, 0x08) < 0) {
            fprintf(stderr, "Failed to write to WHO_AM_I register: %s\n", strerror(errno));
            break;
        }

        uint8_t who_am_i;
        if (gpioI2CReadByte(i2c_fd, &who_am_i) < 0) {
            fprintf(stderr, "Failed to read from WHO_AM_I register: %s\n", strerror(errno));
            break;
        }

        if (who_am_i != 0x08) {
            fprintf(stderr, "Invalid WHO_AM_I value: 0x%02x\n", who_am_i);
            break;
        }

        uint16_t calibration[4];
        if (gpioI2CReadI2CBlockData(i2c_fd, REG_CALIBRATION_MSB, CALIBRATION_LSB4, calibration, 4) < 0) {
            fprintf(stderr, "Failed to read calibration coefficients: %s\n", strerror(errno));
            break;
        }

        while (!exit_flag) {
            if (gpioI2CWriteByte(i2c_fd, REG_PRESSURE_MSB, 0x00) < 0) {
                fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
                break;
            }

            usleep(10000);

            uint8_t data[6];
            if (gpioI2CReadI2CBlockData(i2c_fd, REG_PRESSURE_MSB, PRESSURE_LSB, data, 6) < 0) {
                fprintf(stderr, "Failed to read pressure and temperature data: %s\n", strerror(errno));
                break;
            }

            int16_t pressure = (data[PRESSURE_MSB] << 8) | data[PRESSURE_LSB];
            int16_t temperature = (data[TEMPERATURE_MSB] << 8) | data[TEMPERATURE_LSB];

            pressure = (pressure * calibration[0] + calibration[1]) / calibration[2] + calibration[3];
            temperature = (temperature * calibration[0] + calibration[1]) / calibration[2] + calibration[3];

            time = *localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &time);
            fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure * PRESSURE_SCALE, temperature * TEMPERATURE_SCALE);
            fflush(file);

            printf("%s,%.2f,%.2f\n", timestamp, pressure * PRESSURE_SCALE, temperature * TEMPERATURE_SCALE);

            sleep(5);
        }

        fclose(file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 0;
    }

    fclose(file);
    gpioClose(i2c_fd);
