#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x63
#define GPIO_LED "/sys/class/gpio/gpio17"
#define GPIO_LED_ON "export"
#define GPIO_LED_OFF "unexport"
#define GPIO_LED_VALUE "value"

// ICP-10125 calibration coefficients
#define COEF_A 0x66
#define COEF_B 0x67
#define COEF_C 0x68
#define COEF_D 0x69
#define COEF_E 0x6A
#define COEF_F 0x6B

// ICP-10125 command and data registers
#define CMD_MEASURE 0x4011
#define REG_PRESSURE 0x00
#define REG_TEMPERATURE 0x01
#define REG_CRC 0x02

// ICP-10125 conversion formulas
#define PRESSURE_CONVERSION(a, b, c, d, e, f, p) ((a * p + b) * p + c) * p + d * p + e
#define TEMPERATURE_CONVERSION(a, b, c, d, e, f, t) ((a * t + b) * t + c) * t + d * t + e

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    int pressure = 0;
    int temperature = 0;
    int crc = 0;
    int coef_a, coef_b, coef_c, coef_d, coef_e, coef_f;
    bool high_altitude = false;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }

    // Read calibration coefficients
    if (write(i2c_fd, &COEF_A, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_a, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (write(i2c_fd, &COEF_B, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_b, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (write(i2c_fd, &COEF_C, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_c, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (write(i2c_fd, &COEF_D, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_d, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (write(i2c_fd, &COEF_E, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_e, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (write(i2c_fd, &COEF_F, 1) < 0) {
        perror("Failed to write to I2C bus");
        close(i2c_fd);
        exit(1);
    }
    if (read(i2c_fd, &coef_f, 2) < 0) {
        perror("Failed to read from I2C bus");
        close(i2c_fd);
        exit(1);
    }

    // Open GPIO line
    gpio_fd = gpiod_open(GPIO_LED, GPIOD_LINE_EXPORT);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        exit(1);
    }

    // Set GPIO line as output
    if (gpiod_direction(gpio_fd, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        perror("Failed to set GPIO direction");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        exit(1);
    }

    // Blink LED at 1 Hz
    while (1) {
        // Trigger measurement
        if (write(i2c_fd, &CMD_MEASURE, 1) < 0) {
            perror("Failed to write to I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }

        // Wait for 20 ms
        usleep(20000);

        // Read data
        if (write(i2c_fd, &REG_PRESSURE, 1) < 0) {
            perror("Failed to write to I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }
        if (read(i2c_fd, &pressure, 2) < 0) {
            perror("Failed to read from I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }
        if (write(i2c_fd, &REG_TEMPERATURE, 1) < 0) {
            perror("Failed to write to I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }
        if (read(i2c_fd, &temperature, 2) < 0) {
            perror("Failed to read from I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }
        if (write(i2c_fd, &REG_CRC, 1) < 0) {
            perror("Failed to write to I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }
        if (read(i2c_fd, &crc, 2) < 0) {
            perror("Failed to read from I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }

        // Verify CRC
        if (crc != (pressure[0] ^ pressure[1] ^ temperature[0] ^ temperature[1]) & 0xFF) {
            perror("CRC mismatch");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            exit(1);
        }

        // Convert data
        pressure = PRESSURE_CONVERSION(coef_a, coef_b, coef_c, coef_d, coef_e, coef_f, pressure[0] << 8 | pressure[1]);
        temperature = TEMPERATURE_CONVERSION(coef_a, coef_b, coef_c, coef_d, coef_e, coef_f, temperature[0] << 8 | temperature[1]);

        // Check high altitude
        if (pressure < 95000) {
            high_altitude = true;
        } else {
            high_altitude = false;
        }

        // Blink LED
        if (high_altitude) {
            // Blink at 5 Hz
            for (int i = 0; i < 5; i++) {
                if (gpiod_write(gpio_fd, 1) < 0) {
                    perror("Failed to write to GPIO line");
                    gpiod_close(gpio_fd);
                    close(i2c_fd);
                    exit(1);
                }
                usleep(100000);
                if (gpiod_write(gpio_fd, 0) < 0) {
                    perror("Failed to write to GPIO line");
                    gpiod_close(gpio_fd);
                    close(i2c_fd);
                    exit(1);
                }
                usleep(100000);
            }
        } else {
            // Blink at 1 Hz
            if (gpiod_write(gpio_fd, 1) < 0) {
                perror("Failed to write to GPIO line");
                gpiod_close(gpio_fd);
                close(i2c_fd);
                exit(1);
            }
            usleep(500000);
            if (gpiod_write(gpio_fd, 0) < 0) {
                perror("Failed to write to GPIO line");
                gpiod_close(gpio_fd);
                close(i2c_fd);
                exit(1);
            }
            usleep(500000);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close GPIO line
    gpiod_close(gpio_fd);

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close GPIO line
    gpiod_close(gpio_fd);

    // Close I2C bus
    close(i2c_fd);

    // Exit
    exit(0);
}

// Register signal handler for SIGINT
void register_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register signal handler");
        exit(1);
    }
}

int main() {
    register_signal_handler();

    // ... (rest of the code remains the same)
}

