#define FAN_PIN 18
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define AMBIENT_REGISTER 0x06
#define OBJECT_REGISTER 0x07
#define HYSTERESIS 2

volatile bool running = true;

void cleanup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
