#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 8080
#define SHT40_ADDRESS 0x44
#define SHT40_MEASUREMENT_COMMAND 0xFD
#define SHT40_RETRY_COUNT 3

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read SHT40 sensor data
int read_sht40_data(int fd) {
    int retry_count = 0;
    int raw_T, raw_RH;
    char buffer[7];

    while (retry_count < SHT40_RETRY_COUNT) {
        if (i2cWriteReg(fd, SHT40_ADDRESS, SHT40_MEASUREMENT_COMMAND, 1) < 0) {
            printf("Error sending measurement command\n");
            return -1;
        }

        usleep(10000); // Wait at least 10 ms

        if (i2cReadReg(fd, SHT40_ADDRESS, 0, buffer, 6) < 0) {
            printf("Error reading sensor data\n");
            return -1;
        }

        raw_T = (buffer[0] << 8) | buffer[1];
        raw_RH = (buffer[2] << 8) | buffer[3];

        if (raw_T > 32767) {
            raw_T -= 65536;
        }

        if (raw_RH > 32767) {
            raw_RH -= 65536;
        }

        T = -45 + 175 * (raw_T / 65535);
        RH = -6 + 125 * (raw_RH / 65535);

        if (RH < 0) {
            RH = 0;
        } else if (RH > 100) {
            RH = 100;
        }

        return 0;
    }

    printf("Failed to read sensor data after %d retries\n", SHT40_RETRY_COUNT);
    return -1;
}

int main() {
    int fd;
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    char* html = "<html><body><h1>Temperature: %.2f°C, Humidity: %.2f%%</h1></body></html>";

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        printf("Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus 1
    fd = i2cOpen(1, SHT40_ADDRESS);
    if (fd < 0) {
        printf("Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create HTTP server
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        printf("Failed to create socket\n");
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&address, sizeof(address)) < 0) {
        printf("Failed to bind socket\n");
        close(server_fd);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        printf("Failed to listen on socket\n");
        close(server_fd);
        i2cClose(fd);
        gpioTerminate();
        return 1;
    }

    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr*)&address, (socklen_t*)&addrlen)) < 0) {
            printf("Failed to accept connection\n");
            close(server_fd);
            i2cClose(fd);
            gpioTerminate();
            return 1;
        }

        if (read_sht40_data(fd) < 0) {
            close(new_socket);
            continue;
        }

        sprintf(buffer, html, T, RH);
        send(new_socket, buffer, strlen(buffer), 0);
        close(new_socket);
    }

    close(server_fd);
    i2cClose(fd);
    gpioTerminate();
    return 0;
}

