#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define REG_TEMP 0x00
#define TEMPERATURE_FILE "temperature_log.csv"
#define TEMPERATURE_INTERVAL 5000  // 5 seconds

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (i2cSetSlaveAddress(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open temperature file for logging
    FILE *temperature_file = fopen(TEMPERATURE_FILE, "a");
    if (!temperature_file) {
        fprintf(stderr, "Failed to open temperature log file: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        gpioClose(i2c_fd);
        fclose(temperature_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Read temperature
        uint16_t temperature;
        if (i2cReadReg8(i2c_fd, REG_TEMP, &temperature, 2) < 0) {
            fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
            continue;
        }

        // Convert 12-bit two's complement value to Celsius
        temperature = (temperature >> 4) * 0.0625;

        // Log temperature
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(temperature_file, "%s,%.2f\n", timestamp, temperature);

        // Sleep for 5 seconds
        usleep(TEMPERATURE_INTERVAL * 1000);
    }

    // Clean up
    fclose(temperature_file);
    gpioClose(i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

