#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define MEASUREMENT_CONFIG 0x0E
#define CONFIG 0x0F
#define TEMPERATURE_REGISTER 0x00
#define HUMIDITY_REGISTER 0x02
#define MAX_RETRY_COUNT 5
#define MEASUREMENT_TIMEOUT 500000 // 500 ms

// Define signal handler for Ctrl+C
volatile sig_atomic_t stop = 0;

void signal_handler(int sig) {
    stop = 1;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Open I2C bus
    int i2c_handle = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    while (!stop) {
        // Trigger measurement
        int retry_count = 0;
        while (retry_count < MAX_RETRY_COUNT) {
            if (gpioWrite(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
                if (errno == EIO) {
                    // Handle I2C bus error
                    fprintf(stderr, "I2C bus error\n");
                    break;
                } else if (errno == EAGAIN) {
                    // Handle NAK (not acknowledged)
                    fprintf(stderr, "NAK received\n");
                    break;
                } else {
                    // Handle other errors
                    fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register: %d\n", errno);
                    break;
                }
            }

            // Wait for measurement to complete
            int timeout = 0;
            while (gpioRead(i2c_handle, MEASUREMENT_CONFIG) & 0x01 && timeout < MEASUREMENT_TIMEOUT) {
                usleep(1000);
                timeout += 1000;
            }

            if (timeout >= MEASUREMENT_TIMEOUT) {
                // Handle timeout
                fprintf(stderr, "Measurement timed out\n");
                break;
            }

            // Read temperature and humidity
            int temperature = 0;
            int humidity = 0;
            if (gpioReadReg8(i2c_handle, TEMPERATURE_REGISTER, &temperature) < 0) {
                if (errno == EIO) {
                    // Handle I2C bus error
                    fprintf(stderr, "I2C bus error\n");
                    break;
                } else if (errno == EAGAIN) {
                    // Handle NAK (not acknowledged)
                    fprintf(stderr, "NAK received\n");
                    break;
                } else {
                    // Handle other errors
                    fprintf(stderr, "Error reading temperature register: %d\n", errno);
                    break;
                }
            }
            if (gpioReadReg8(i2c_handle, HUMIDITY_REGISTER, &humidity) < 0) {
                if (errno == EIO) {
                    // Handle I2C bus error
                    fprintf(stderr, "I2C bus error\n");
                    break;
                } else if (errno == EAGAIN) {
                    // Handle NAK (not acknowledged)
                    fprintf(stderr, "NAK received\n");
                    break;
                } else {
                    // Handle other errors
                    fprintf(stderr, "Error reading humidity register: %d\n", errno);
                    break;
