// Function to calculate CRC-8 checksum
uint8_t crc8(uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_bus = gpioOpen(1, 1);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address to 0x25
    if (gpioI2CSetSlaveAddress(i2c_bus, 0x25) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        gpioI2CClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Set I2C speed to 100 kHz
    if (gpioI2CSpeed(i2c_bus, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        gpioI2CClose(ic_bus);
        gpioTerminate();
        return 1;
    }

    // Trigger continuous measurement
    uint8_t cmd[] = {0x36, 0x2F};
    if (gpioI2CWrite(i2c_bus, 1, cmd, 2) < 0) {
        fprintf(stderr, "Failed to write to I2C bus\n");
        gpioI2CClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Wait for measurement to complete (about 45 ms)
        usleep(45000);

        // Read 6 bytes from I2C bus
        uint8_t data[6];
        if (gpioI2CRead(i2c_bus, 1, data, 6) < 0) {
            fprintf(stderr, "Failed to read from I2C bus\n");
            gpioI2CClose(i2c_bus);
            gpioTerminate();
            return 1;
        }

        // Verify CRC-8 checksum for pressure data
        uint8_t pressure_crc = crc8(data, 3, 0x31, 0xFF);
        if (pressure_crc != data[3]) {
            fprintf(stderr, "Invalid pressure CRC\n");
            gpioI2CClose(i2c_bus);
            gpioTerminate();
            return 1;
        }

        // Verify CRC-8 checksum for temperature data
        uint8_t temperature_crc = crc8(data + 4, 3, 0x31, 0xFF);
        if (temperature_crc != data[5]) {
            fprintf(stderr, "Invalid temperature CRC\n");
            gpioI2CClose(i2c_bus);
            gpioTerminate();
            return 1;
        }

        // Log raw pressure and temperature values
        printf("Pressure: 0x%04x, Temperature: 0x%04x\n", (data[0] << 8) | data[1], (data[2] << 8) | data[3]);

        // Wait 500 ms before next measurement
        usleep(500000);
    }

    // Clean up
    gpioI2CClose(i2c_bus);
    gpioTerminate();

    return 0;
}

