#include <spidev.h>

#define MAX_PROFILE_SIZE 1024
#define MAX_LINE_LENGTH 128
#define LOG_FILE "reflow_log.csv"

// PID controller parameters
#define KP 10.0
#define KI 0.0
#define KD 0.0
#define PID_SAMPLE_TIME 1.0  // seconds

// MAX6675 thermocouple parameters
#define MAX6675_CS0 0
#define MAX6675_CS1 1
#define MAX6675_READ_DELAY 1000000  // 1 ms

// GPIO parameters
#define RELAY_PIN 17

// PID controller state
typedef struct {
    double error;
    double integral;
    double derivative;
    double output;
} pid_state_t;

pid_state_t pid_state;

// Function to read a line from a file
char* read_line(FILE* file) {
    char buffer[MAX_LINE_LENGTH];
    if (fgets(buffer, MAX_LINE_LENGTH, file) == NULL) {
        return NULL;
    }
    char* line = strdup(buffer);
    return line;
}

// Function to parse a line from a file into time and temperature
bool parse_line(char* line, double* time, double* temperature) {
    char* token;
    token = strtok(line, ",");
    if (token == NULL) {
        return false;
    }
    *time = atof(token);
    token = strtok(NULL, ",");
    if (token == NULL) {
        return false;
    }
    *temperature = atof(token);
    return true;
}

// Function to read a temperature from the MAX6675
uint16_t read_temperature(int fd) {
    uint16_t data;
    if (ioctl(fd, SPI_IOC_MESSAGE(1), NULL) < 0) {
        perror("SPI read error");
        return 0;
    }
    if (read(fd, &data, 2) != 2) {
        perror("SPI read error");
        return 0;
    }
    return data;
}

// Function to calculate the PID controller output
double calculate_pid(double error, double integral, double derivative) {
    pid_state.error = error;
    pid_state.integral += error * PID_SAMPLE_TIME;
    pid_state.derivative = (error - pid_state.error) / PID_SAMPLE_TIME;
    pid_state.output = KP * error + KI * pid_state.integral + KD * pid_state.derivative;
    if (pid_state.output < 0.0) {
        pid_state.output = 0.0;
    } else if (pid_state.output > 1.0) {
        pid_state.output = 1.0;
    }
    return pid_state.output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(double duty_cycle) {
    gpiod_line_set_value("gpiochip0", RELAY_PIN, (int)(duty_cycle * 100));
}

// Function to log temperature data
void log_temperature(double time, double temperature) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%f,%f\n", time, temperature);
    fclose(file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    gpiod_line_release("gpiochip0", RELAY_PIN);
    close(spidev_fd);
    exit(0);
}

int main() {
    // Open the SPI device
    spidev_fd = open("/dev/spidev0.0", O_RDWR);
    if (spidev_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Open the GPIO device
    gpiod_context* ctx = gpiod_ctx_new();
    if (ctx == NULL) {
        perror("Failed to create GPIO context");
        return 1;
    }

    // Initialize the relay pin
    gpiod_line_request_output(ctx, "gpiochip0", RELAY_PIN, 0);
    gpiod_line_set_value("gpiochip0", RELAY_PIN, 0);

    // Open the profile file
    FILE* profile_file = fopen("profile.txt", "r");
    if (profile_file == NULL) {
        perror("Failed to open profile file");
        return 1;
    }

    // Read the profile
    char* line;
    double time, temperature;
    while ((line = read_line(profile_file)) != NULL) {
        if (parse_line(line, &time, &temperature)) {
            // Log the temperature data
            log_temperature(time, temperature);
        }
        free(line);
    }

    // Close the profile file
    fclose(profile_file);

    // Initialize the PID controller
    pid_state.error = 0.0;
    pid_state.integral = 0.0;
    pid_state.derivative = 0.0;
    pid_state.output = 0.0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the temperature from the MAX6675
        uint16_t data = read_temperature(spidev_fd);
        if (data == 0) {
            // Sensor absent or bus error
            gpiod_line_release("gpiochip0", RELAY_PIN);
            close(spidev_fd);
            exit(1);
        }
        double temperature = (data >> 2) & 0xFFF;
        temperature /= 16.0;

        // Calculate the PID controller output
        double error = temperature - 235.0;  // Setpoint temperature
        double output = calculate_pid(error, pid_state.integral, pid_state.derivative);

        // Set the relay duty cycle
        set_relay_duty_cycle(output);

        // Log the temperature data
        log_temperature(time, temperature);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release("gpiochip0", RELAY_PIN);
    close(spidev_fd);
    gpiod_ctx_free(ctx);
    return 0;
}

