double pid_update(pid_t *pid, double setpoint, double temperature) {
    pid->error = setpoint - temperature;
    pid->integral += pid->error * PID_INTERVAL;
    pid->derivative = (pid->error - pid->error) / PID_INTERVAL;
    pid->output = KP * pid->error + KI * pid->integral + KD * pid->derivative;
    return pid->output;
}

// Define signal handlers
void sigint_handler(int sig) {
    // Turn off relay and PWM
    gpiod_line_set_value(gpiod, RELAY_PIN, 0);
    gpiod_pwm_set_raw(gpiod, PWM_PIN, 0);
    // Close GPIO lines
    gpiod_line_release(gpiod, RELAY_PIN);
    gpiod_pwm_release(gpiod, PWM_PIN);
    // Close chip
    gpiod_chip_close(gpiod);
    // Close log file
    fclose(log_file);
    // Exit
    exit(0);
}

void sigterm_handler(int sig) {
    // Turn off relay and PWM
    gpiod_line_set_value(gpiod, RELAY_PIN, 0);
    gpiod_pwm_set_raw(gpiod, PWM_PIN, 0);
    // Close GPIO lines
    gpiod_line_release(gpiod, RELAY_PIN);
    gpiod_pwm_release(gpiod, PWM_PIN);
    // Close chip
    gpiod_chip_close(gpiod);
    // Close log file
    fclose(log_file);
    // Exit
    exit(0);
}

int main(int argc, char **argv) {
    // Parse command-line arguments
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <setpoint> <kp> <ki> <kd>\n", argv[0]);
        exit(1);
    }
    double setpoint = atof(argv[1]);
    double kp = atof(argv[2]);
    double ki = atof(argv[3]);
    double kd = atof(argv[4]);

    // Initialize PID gains
    pid_t pid;
    pid_init(&pid);
    KP = kp;
    KI = ki;
    KD = kd;

    // Initialize GPIO
    gpiod = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod == NULL) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Initialize relay and PWM lines
    relay_line = gpiod_line_request_output(gpiod, RELAY_PIN, "relay");
    if (relay_line == NULL) {
        perror("gpiod_line_request_output");
        exit(1);
    }
    pwm_line = gpiod_pwm_request(gpiod, PWM_PIN, "pwm");
    if (pwm_line == NULL) {
        perror("gpiod_pwm_request");
        exit(1);
    }

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Initialize temperature file
    temperature_file = fopen(TEMPERATURE_FILE, "r");
    if (temperature_file == NULL) {
        perror("fopen");
        exit(1);
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read temperature
        char buffer[256];
        if (fgets(buffer, sizeof(buffer), temperature_file) == NULL) {
            perror("fgets");
            exit(1);
        }
        double temperature = atof(buffer);
        if (temperature < 0.0 || temperature > 100.0) {
            fprintf(stderr, "Invalid temperature reading: %f\n", temperature);
            continue;
        }

        // Validate CRC
        char crc[2];
        if (fread(crc, 1, 2, temperature_file) != 2) {
            perror("fread");
            exit(1);
        }
        if (crc[0] != 0x89 || crc[1] != 0x44) {
