        gpiod_pwm_set_raw(gpiod, PWM_PIN, (int)output);

        // Set relay
        gpiod_line_set_value(gpiod, RELAY_PIN, (output > 0.0));

        // Log data
        char log_buffer[256];
        time_t now = time(NULL);
        strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(log_buffer + strlen(log_buffer), ",%.2f,%.2f,%.2f,%.2f", temperature, setpoint, output, gpiod_pwm_get_raw(gpiod, PWM_PIN));
        fprintf(log_file, "%s%s\n", log_buffer, log_buffer + strlen(log_buffer));
        fflush(log_file);

        // Sleep
        sleep(LOG_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Close temperature file
    fclose(temperature_file);

    // Close GPIO lines
    gpiod_line_release(gpiod, RELAY_PIN);
    gpiod_pwm_release(gpiod, PWM_PIN);

    // Close chip
    gpiod_chip_close(gpiod);

