#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x38
#define RELAY_GPIO 17
#define MEASUREMENT_TRIGGER 0xAC
#define MEASUREMENT_DATA_LENGTH 6
#define MEASUREMENT_STATUS_MASK 0x80
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define RETRY_COUNT 3
#define RETRY_DELAY 10
#define POLL_INTERVAL 5000

static volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int i2c_read(int fd, uint8_t *data, size_t length) {
    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
            if (errno == EBUSY) {
                usleep(RETRY_DELAY * 1000);
                retries++;
                continue;
            }
            perror("ioctl");
            return -1;
        }
        if (i2c_smbus_read_byte_data(fd, MEASUREMENT_TRIGGER) == -1) {
            if (errno == EBUSY) {
                usleep(RETRY_DELAY * 1000);
                retries++;
                continue;
            }
            perror("i2c_smbus_read_byte_data");
            return -1;
        }
        usleep(80 * 1000);
        if (i2c_smbus_read_i2c_block_data(fd, 0, length, data) == -1) {
            if (errno == EBUSY) {
                usleep(RETRY_DELAY * 1000);
                retries++;
                continue;
            }
            perror("i2c_smbus_read_i2c_block_data");
            return -1;
        }
        if ((data[0] & MEASUREMENT_STATUS_MASK) == 0) {
            return 0;
        }
        retries++;
    }
    return -1;
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        perror("open");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_fd);
        return 1;
    }

    uint8_t init_sequence[] = {0xBE, 0x08, 0x00};
    if (i2c_smbus_write_i2c_block_data(i2c_fd, 0, 3, init_sequence) == -1) {
        perror("i2c_smbus_write_i2c_block_data");
        close(i2c_fd);
        return 1;
    }

    struct gpiod_line *relay_line;
    if ((relay_line = gpiod_line_request_byname(NULL, "/sys/class/gpio/gpio17", GPIOD_LINE_ACTIVE_HIGH)) == NULL) {
        perror("gpiod_line_request_byname");
        close(i2c_fd);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint8_t data[MEASUREMENT_DATA_LENGTH];
        if (i2c_read(i2c_fd, data, MEASUREMENT_DATA_LENGTH) == 0) {
            uint16_t humidity = (data[0] << 8) | data[1];
            printf("%lu: Humidity: %d%%\n", time(NULL), humidity);
            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                gpiod_line_set_value(relay_line, 1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                gpiod_line_set_value(relay_line, 0);
            }
        } else {
            fprintf(stderr, "Error reading from AHT20 sensor\n");
        }
        usleep(POLL_INTERVAL * 1000);
    }

    gpiod_line_release(relay_line);
    close(i2c_fd);
    return 0;
}

