#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <signal.h>
#include <json-c/json.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x40
#define HTU21D_REG_HUMIDITY 0xE5
#define HTU21D_REG_TEMPERATURE 0xE3
#define HTTP_URL "http://api.example.com/humidity"
#define HTTP_PORT 80
#define BUFFER_SIZE 1024

// Function to handle I2C read operation
int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    ret = ioctl(fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to handle I2C write operation
int i2c_write(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = 0;
    msg[1].len = len;
    msg[1].buf = buf;

    i2c_data.msgs = msg;
    i2c_data.nmsgs = 2;

    ret = ioctl(fd, I2C_RDWR, &i2c_data);
    if (ret < 0) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to send HTTP POST request
int http_post(int sock, char *url, char *data) {
    struct sockaddr_in server_addr;
    int ret;

    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    server_addr.sin_port = htons(HTTP_PORT);

    ret = connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (ret < 0) {
        syslog(LOG_ERR, "HTTP connect failed: %s", strerror(errno));
        return -1;
    }

    char *request = "POST / HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: ";
    char *content_length = malloc(strlen(request) + strlen(data) + 10);
    sprintf(content_length, "%s%d\r\n\r\n%s", request, strlen(data), data);
    ret = send(sock, content_length, strlen(content_length), 0);
    free(content_length);
    if (ret < 0) {
        syslog(LOG_ERR, "HTTP send failed: %s", strerror(errno));
        return -1;
    }

    char buffer[BUFFER_SIZE];
    ret = recv(sock, buffer, BUFFER_SIZE, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "HTTP receive failed: %s", strerror(errno));
        return -1;
    }

    close(sock);
    return 0;
}

// Function to read humidity from HTU21D sensor
int read_humidity(int fd) {
    uint8_t reg = HTU21D_REG_HUMIDITY;
    uint8_t buf[3];

    if (i2c_read(fd, reg, buf, 3) < 0) {
        return -1;
    }

    uint16_t humidity = (buf[0] << 8) | buf[1];
    return humidity;
}

// Function to read temperature from HTU21D sensor
int read_temperature(int fd) {
    uint8_t reg = HTU21D_REG_TEMPERATURE;
    uint8_t buf[3];

    if (i2c_read(fd, reg, buf, 3) < 0) {
        return -1;
    }

    uint16_t temperature = (buf[0] << 8) | buf[1];
    return temperature;
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, exiting...", sig);
    close(i2c_fd);
    close(http_fd);
    exit(0);
}

