#define BMP280_I2C_ADDRESS 0x76
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIBRATION_BLOCK_SIZE 24
#define BMP280_CTRL_MEAS_REG 0xF4
#define BMP280_FORCED_MODE 0x27
#define BMP280_FORCED_MODE_BIT 0x01
#define BMP280_DATA_REG 0xF7
#define BMP280_PRESSURE_DATA_OFFSET 0x00
#define BMP280_TEMP_DATA_OFFSET 0x02
#define BMP280_PRESSURE_DATA_SIZE 3
#define BMP280_TEMP_DATA_SIZE 3
#define BMP280_PRESSURE_THRESHOLD_HIGH 1020
#define BMP280_PRESSURE_THRESHOLD_LOW 980
#define LOG_FILE "pressure_log.txt"

// Function to read 1 byte from I2C device
uint8_t readByte(int fd, uint8_t reg) {
    uint8_t data;
    if (i2cWriteReg(fd, BMP280_I2C_ADDRESS, reg, 1, &reg) < 0) {
        return 0;
    }
    if (i2cReadReg(fd, BMP280_I2C_ADDRESS, reg, 1, &data) < 0) {
        return 0;
    }
    return data;
}

// Function to read n bytes from I2C device
uint8_t* readBytes(int fd, uint8_t reg, uint8_t n) {
    uint8_t* data = malloc(n);
    if (i2cWriteReg(fd, BMP280_I2C_ADDRESS, reg, 1, &reg) < 0) {
        free(data);
        return NULL;
    }
    if (i2cReadReg(fd, BMP280_I2C_ADDRESS, reg, n, data) < 0) {
        free(data);
        return NULL;
    }
    return data;
}

// Function to calculate temperature from raw data
float calculateTemperature(uint8_t* data) {
    int32_t t = (data[BMP280_TEMP_DATA_OFFSET] << 8) | data[BMP280_TEMP_DATA_OFFSET + 1];
    t = t >> 4;
    return t / 100.0;
}

// Function to calculate pressure from raw data
float calculatePressure(uint8_t* data) {
    int32_t p = (data[BMP280_PRESSURE_DATA_OFFSET] << 8) | data[BMP280_PRESSURE_DATA_OFFSET + 1];
    p = p << 8 | data[BMP280_PRESSURE_DATA_OFFSET + 2];
    p = p >> 8;
    p = p * 100;
    return p / 256.0;
}

// Function to apply Bosch compensation formulas
void applyCompensation(uint8_t* data, float* temperature, float* pressure) {
    int32_t t = calculateTemperature(data);
    int32_t p = calculatePressure(data);
    *temperature = t / 100.0;
    *pressure = p / 256.0;
    int32_t tFine = (int32_t)((t * 100) - 4000);
    int32_t var1 = ((tFine) * 2) + ((5 * tFine) / 4);
    int32_t var2 = (var1 + (1 << 8)) / (1 << 4);
    int32_t var4 = ((var2 * 2) / (1 << 11));
    int32_t var5 = (BMP280_CALIBRATION_BLOCK_SIZE + (BMP280_CALIBRATION_BLOCK_SIZE / 4)) * 2;
    int32_t var6 = (BMP280_CALIBRATION_BLOCK_SIZE * 2) - var5;
    int32_t t1 = (BMP280_CALIBRATION_BLOCK_SIZE + (BMP280_CALIBRATION_BLOCK_SIZE / 4)) * 2;
    int32_t t2 = (BMP280_CALIBRATION_BLOCK_SIZE * 2) - t1;
    int32_t p1 = (BMP280_CALIBRATION_BLOCK_SIZE + (BMP280_CALIBRATION_BLOCK_SIZE / 4)) * 2;
    int32_t p2 = (BMP280_CALIBRATION_BLOCK_SIZE * 2) - p1;
    int32_t var7 = (t1 * var6) / (var5 * 2);
    int32_t var8 = (t2 * var7);
    int32_t var9 = (p1 * var6) / (var5 * 2);
    int32_t var10 = (p2 * var9);
    int32_t var11 = (var1 + (var5 * var2)) / (var1 + (var5 * var2) - var8);
    int32_t var12 = (var4 * (var6 * var11));
    int32_t var13 = (var3 * (var6 * var11));
    int32_t var14 = (var12 + (var13 * var11));
    int32_t p = (var14 * 1048576) / (var1 + (var5 * var2) - var8);
    *pressure = p / 256.0;
}

int main() {
    int fd = i2cOpen(1, BMP280_I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    // Verify chip ID
    uint8_t chipId = readByte(fd, 0xD0);
    int retry = 0;
    while (chipId != BMP280_CHIP_ID && retry < 3) {
        if (i2cClose(fd) < 0) {
            fprintf(stderr, "Failed to close I2C bus\n");
            return 1;
        }
        fd = i2cOpen(1, BMP280_I2C_ADDRESS);
        if (fd < 0) {
            fprintf(stderr, "Failed to reopen I2C bus\n");
            return 1;
        }
        chipId = readByte(fd, 0xD0);
        retry++;
    }
    if (chipId != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid chip ID\n");
        return 1;
    }

    // Read calibration block
    uint8_t* calibrationBlock = readBytes(fd, 0x88, BMP280_CALIBRATION_BLOCK_SIZE);
    if (calibrationBlock == NULL) {
        fprintf(stderr, "Failed to read calibration block\n");
        return 1;
    }

    // Configure ctrl_meas register
    uint8_t ctrlMeas = BMP280_FORCED_MODE;
    if (i2cWriteReg(fd, BMP280_CTRL_MEAS_REG, 1, &ctrlMeas) < 0) {
        fprintf(stderr, "Failed to write to ctrl_meas register\n");
        free(calibrationBlock);
        return 1;
    }

    // Signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Main loop
    FILE* logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }
    struct timeval lastTimestamp;
    gettimeofday(&lastTimestamp, NULL);
    while (1) {
        // Trigger measurement
        uint8_t forcedMode = BMP280_FORCED_MODE | BMP280_FORCED_MODE_BIT;
        if (i2cWriteReg(fd, BMP280_CTRL_MEAS_REG, 1, &forcedMode) < 0) {
            fprintf(stderr, "Failed to write to ctrl_meas register\n");
            fclose(logFile);
            gpioTerminate();
            return 1;
        }

        // Wait for conversion completion
        usleep(10000);

        // Read raw data
        uint8_t* rawData = readBytes(fd, BMP280_DATA_REG, 6);
        if (rawData == NULL) {
            fprintf(stderr, "Failed to read raw data\n");
            fclose(logFile);
            gpioTerminate();
            return 1;
        }

        // Apply compensation formulas
        float temperature, pressure;
        applyCompensation(rawData, &temperature, &pressure);

        // Log pressure threshold breaches
        struct timeval currentTimestamp;
        gettimeofday(&currentTimestamp, NULL);
        if (pressure > BMP280_PRESSURE_THRESHOLD_HIGH || pressure < BMP280_PRESSURE_THRESHOLD_LOW) {
            fprintf(logFile, "%ld.%06ld: Pressure %f hPa\n", currentTimestamp.tv_sec, currentTimestamp.tv_usec, pressure);
        }

        // Close log file and terminate on exit
        if (currentTimestamp.tv_sec - lastTimestamp.tv_sec >= 2) {
            fclose(logFile);
            logFile = fopen(LOG_FILE, "a");
            if (logFile == NULL) {
                fprintf(stderr, "Failed to reopen log file\n");
                gpioTerminate();
                return 1;
            }
            lastTimestamp = currentTimestamp;
        }

        free(rawData);
    }

    fclose(logFile);
    gpioTerminate();
    return 0;
}

