#define TMP117_TEMP_REGISTER 0x00
#define AHT20_INIT_COMMAND 0xBE 0x08 0x00
#define AHT20_MEASURE_COMMAND 0xAC 0x33 0x00
#define AHT20_BUSY_BIT 0x80
#define AHT20_HUMIDITY_MASK 0x3F
#define AHT20_TEMPERATURE_MASK 0x3FFF

#define CSV_HEADER "Timestamp,Temperature(C),Humidity(%),MotionDetected\n"

static int i2c_fd = -1;
static int pir_fd = -1;
static bool sensors_present = true;

static void sigint_handler(int sig) {
    (void)sig;
    close(i2c_fd);
    gpiod_close(pir_fd);
    exit(0);
}

static void init_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        sensors_present = false;
        return;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        sensors_present = false;
        return;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        sensors_present = false;
        return;
    }
}

static void init_pir(void) {
    pir_fd = gpiod_open(PIR_CHIP, GPIOD_LINE_REQUEST_OUTPUT);
    if (pir_fd < 0) {
        perror("Failed to open PIR GPIO");
        sensors_present = false;
        return;
    }

    if (gpiod_line_request_output(pir_fd, PIR_LINE, PIR_DIRECTION) < 0) {
        perror("Failed to set PIR GPIO direction");
        gpiod_close(pir_fd);
        pir_fd = -1;
        sensors_present = false;
        return;
    }
}

static void read_tmp117(void) {
    uint16_t temp;
    int retries = 0;

    while (retries < 3) {
        if (i2c_smbus_write_byte_data(i2c_fd, TMP117_TEMP_REGISTER, 0x00) < 0) {
            perror("Failed to write to TMP117 temperature register");
            retries++;
            usleep(10000);
            continue;
        }

        if (i2c_smbus_read_word_data(i2c_fd, TMP117_TEMP_REGISTER) < 0) {
            perror("Failed to read from TMP117 temperature register");
            retries++;
            usleep(10000);
            continue;
        }

        temp = i2c_smbus_read_word_data(i2c_fd, TMP117_TEMP_REGISTER);
        break;
    }

    if (retries >= 3) {
        fprintf(stderr, "Failed to read from TMP117 temperature register after 3 retries\n");
        return;
    }

    double temperature = (double)temp / 256.0 * 0.0078125;
    printf("Temperature: %.2f°C\n", temperature);
}

static void read_aht20(void) {
    uint8_t data[7];
    int retries = 0;

    while (retries < 3) {
        if (i2c_smbus_write_i2c_block_data(i2c_fd, AHT20_INIT_COMMAND, 3, data) < 0) {
            perror("Failed to write to AHT20 init command");
            retries++;
            usleep(10000);
            continue;
        }

        if (i2c_smbus_write_i2c_block_data(i2c_fd, AHT20_MEASURE_COMMAND, 0, NULL) < 0) {
            perror("Failed to write to AHT20 measure command");
            retries++;
            usleep(10000);
            continue;
        }

        if (i2c_smbus_read_i2c_block_data(i2c_fd, AHT20_MEASURE_COMMAND, 7, data) < 0) {
            perror("Failed to read from AHT20 measure command");
            retries++;
            usleep(10000);
            continue;
        }

        if (data[0] & AHT20_BUSY_BIT) {
            usleep(10000);
            continue;
        }

        uint32_t humidity = (data[0] & AHT20_HUMIDITY_MASK) << 16 | data[1];
        uint32_t temperature = (data[2] & AHT20_TEMPERATURE_MASK) << 8 | data[3];

        double humidity_value = (double)humidity / 1024.0 * 100.0;
        double temperature_value = (double)temperature / 1024.0 * 200.0 - 50.0;

        printf("Humidity: %.2f%%\n", humidity_value);
        printf("Temperature: %.2f°C\n", temperature_value);
        break;
    }

    if (retries >= 3) {
        fprintf(stderr, "Failed to read from AHT20 measure command after 3 retries\n");
        return;
    }
}

static void read_pir(void) {
    int value;
    if (gpiod_line_get_value(pir_fd, PIR_LINE, &value) < 0) {
        perror("Failed to read PIR GPIO value");
        return;
    }

    printf("Motion detected: %s\n", value ? "yes" : "no");
}

static void log_data(void) {
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    char filename[32];
    strftime(filename, sizeof(filename), "/var/log/logger_%Y-%m-%d.csv", timestamp);

    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%04d-%02d-%02d,%f,%f,%s\n", timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday, 0.0, 0.0, sensors_present ? "yes" : "no");
    fclose(file);
}

int main(void) {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    init_i2c();
    init_pir();

    if (!sensors_present) {
        fprintf(stderr, "Warning: one or more sensors are not present\n");
    }

    while (1) {
        read_tmp117();
        read_aht20();
        read_pir();
        log_data();
        sleep(1);
    }

    close(i2c_fd);
    gpiod_close(pir_fd);
    return 0;
}

