#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    gpiod_close(gpio_fd);
    gpiod_close(motor_fd);
    gpiod_close(dir1_fd);
    gpiod_close(dir2_fd);
    gpiod_close(ena_fd);
    printf("Exiting...\n");
    exit(0);
}

int main() {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open GPIO chip
    gpio_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpio_fd == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Open GPIO lines
    motor_fd = gpiod_line_request_output(gpio_fd, "gpio17", 0);
    if (motor_fd == NULL) {
        gpiod_chip_close(gpio_fd);
        perror("gpiod_line_request_output");
        return 1;
    }
    dir1_fd = gpiod_line_request_output(gpio_fd, "gpio23", 0);
    if (dir1_fd == NULL) {
        gpiod_line_release(motor_fd);
        gpiod_chip_close(gpio_fd);
        perror("gpiod_line_request_output");
        return 1;
    }
    dir2_fd = gpiod_line_request_output(gpio_fd, "gpio24", 0);
    if (dir2_fd == NULL) {
        gpiod_line_release(motor_fd);
        gpiod_line_release(dir1_fd);
        gpiod_chip_close(gpio_fd);
        perror("gpiod_line_request_output");
        return 1;
    }
    ena_fd = gpiod_line_request_output(gpio_fd, "gpio22", 0);
    if (ena_fd == NULL) {
        gpiod_line_release(motor_fd);
        gpiod_line_release(dir1_fd);
        gpiod_line_release(dir2_fd);
        gpiod_chip_close(gpio_fd);
        perror("gpiod_line_request_output");
        return 1;
    }

    // Set up motor control
    gpiod_line_set_value(motor_fd, 0);
    gpiod_line_set_value(dir1_fd, 0);
    gpiod_line_set_value(dir2_fd, 1);
    gpiod_line_set_value(ena_fd, 1);

    while (1) {
        // Read rain sensor
        struct gpiod_line_event event;
        if (gpiod_line_event_read(motor_fd, &event) == -1) {
            perror("gpiod_line_event_read");
            gpiod_line_release(motor_fd);
            gpiod_line_release(dir1_fd);
            gpiod_line_release(dir2_fd);
            gpiod_line_release(ena_fd);
            gpiod_chip_close(gpio_fd);
            return 1;
        }
        if (event.value == 0) {
            // Rain detected, close window
            printf("Rain detected at %s\n", ctime(&event.timestamp));
            gpiod_line_set_value(motor_fd, 1);
            sleep(5);
            gpiod_line_set_value(motor_fd, 0);
            sleep(1);
        }
        sleep(2);
    }

    // Clean up
    gpiod_line_release(motor_fd);
    gpiod_line_release(dir1_fd);
    gpiod_line_release(dir2_fd);
    gpiod_line_release(ena_fd);
    gpiod_chip_close(gpio_fd);
    return 0;
}

