#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pigpio.h>

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Turn off the LED
    gpioWrite(17, 0);
    gpioWrite(22, 0);
    gpioWrite(27, 0);
    // Cleanly terminate the pigpio library
    gpioTerminate();
    // Exit the process
    exit(0);
}

// Function to map CPU load to a color gradient
void map_load_to_color(double load, int *red, int *green, int *blue) {
    if (load <= 0.5) {
        *red = 0;
        *green = (int) (load * 255);
        *blue = 0;
    } else if (load <= 1.0) {
        *red = (int) ((load - 0.5) * 255);
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO pins for the LED
    if (gpioSetMode(17, PI_OUTPUT) < 0 || gpioSetMode(22, PI_OUTPUT) < 0 || gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Initialize variables to store previous CPU load values
