    if (load <= 0.5) {
        *red = 0;
        *green = (int) (load * 255);
        *blue = 0;
    } else if (load <= 1.0) {
        *red = (int) ((load - 0.5) * 255);
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

