        sprintf(json, "{\"temperature\": %.2f, \"pressure\": %.2f}", (float)t / 100, (float)p / 100);

        struct sockaddr_in server;
        server.sin_family = AF_INET;
        server.sin_port = htons(UDP_PORT);
        inet_pton(AF_INET, UDP_ADDRESS, &server.sin_addr);

        if ((udp_fd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
            fprintf(stderr, "Failed to create UDP socket\n");
            i2cClose(i2c_fd);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(1);
        }

        if (sendto(udp_fd, json, strlen(json), 0, (struct sockaddr *)&server, sizeof(server)) < 0) {
            fprintf(stderr, "Failed to send UDP packet\n");
            close(udp_fd);
            i2cClose(i2c_fd);
            gpioClose(i2c_fd);
            gpioTerminate();
            exit(1);
        }

        close(udp_fd);

        usleep(5000000);
    }

    return 0;
