#define BMP180_MB 0x00
#define BMP180_MC 0x00
#define BMP180_MD 0x00

// Function to read 16-bit unsigned integer from I2C device
uint16_t read16(uint8_t reg) {
    uint16_t value;
    if (i2c_read(BMP180_ADDRESS, &reg, 1, &value, 2) != 2) {
        fprintf(stderr, "Error reading from BMP180\n");
        exit(1);
    }
    return value;
}

// Function to read 24-bit unsigned integer from I2C device
uint32_t read24(uint8_t reg) {
    uint32_t value;
    if (i2c_read(BMP180_ADDRESS, &reg, 1, &value, 3) != 3) {
        fprintf(stderr, "Error reading from BMP180\n");
        exit(1);
    }
    return value;
}

// Function to calculate temperature from 24-bit unsigned integer
float calculateTemperature(uint32_t adc) {
    uint32_t ut = (adc >> 8) & 0xFF;
    float x1 = ((ut - BMP180_AC6) * BMP180_AC5) / 2;
    float x2 = MathPow(1.0 + (x1 + BMP180_AC2) / (float)BMP180_AC4, 2);
    float x3 = (BMP180_AC3 * x1) / (x2 * (1 + (x1 / (float)BMP180_AC4)));
    float t = (x3 + (float)BMP180_B1) * 100;
    return t / 100;
}

// Function to calculate pressure from 24-bit unsigned integer
float calculatePressure(uint32_t adc) {
    uint32_t ut = (adc >> 8) & 0xFF;
    float x1 = ((ut - BMP180_AC6) * BMP180_AC5) / 2;
    float x2 = MathPow(1.0 + (x1 + BMP180_AC2) / (float)BMP180_AC4, 2);
    float x3 = (BMP180_AC3 * x1) / (x2 * (1 + (x1 / (float)BMP180_AC4));
    float t = (x3 + (float)BMP180_B1) * 100;
    float p = (BMP180_MB + (BMP180_MC * t) + (BMP180_MD * MathPow(t, 2))) / (float)BMP180_B2;
    return p;
}

