    if (gpioSetMode(2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(2, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up on GPIO2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioEdgeDetect(2, PI_FALLING_EDGE, 0) < 0) {
        fprintf(stderr, "Failed to set up interrupt on GPIO2\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    if (i2cOpen(1, BMP180_ADDRESS, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    BMP180_AC1 = read16(0xAA);
    BMP180_AC2 = read16(0xAC);
    BMP180_AC3 = read16(0xAE);
    BMP180_AC4 = read16(0xB0);
    BMP180_AC5 = read16(0xB2);
    BMP180_AC6 = read16(0xB4);
    BMP180_B1 = read16(0xB6);
    BMP180_B2 = read16(0xB8);
    BMP180_MB = read16(0xBA);
    BMP180_MC = read16(0xBC);
    BMP180_MD = read16(0xBE);

    // Open file for logging
    FILE *logFile = fopen("altitude_log.txt", "w");
    if (!logFile) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(BMP180_ADDRESS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigintHandler);

    // Main loop
    while (1) {
        // Wait for interrupt on GPIO2
        gpioWaitForEvent(2, PI_EDGE_FALLING);

        // Read temperature and pressure
        uint32_t adc = read24(0xF4 | (BMP180_PRESSURE_OS << 6));
        float temperature = calculateTemperature(adc);
        float pressure = calculatePressure(adc);

        // Log data
        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(logFile, "%ld,%f,%f\n", tv.tv_sec, temperature, pressure);

        // Wait 1 second
        usleep(1000000);
    }

    return 0;
}

