#define MAX31865_SCK 19
#define MAX31865_MOSI 23
#define MAX31865_MISO 24

#define MAX31865_REG_RTD_CONFIG 0x00
#define MAX31865_REG_RTD_FAULT 0x01
#define MAX31865_REG_RTD_STATUS 0x02
#define MAX31865_REG_RTD_TEMP 0x03

#define MAX31865_RTD_CONFIG_3WIRE_BIAS 0x80

