void sigint_handler(int sig) {
    if (cs_fd >= 0) {
        gpiod_line_release(cs_line);
        close(cs_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (fclose(stdout) != 0) {
        perror("fclose");
    }
