int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *cs_line;
    struct gpiod_line *sck_line;
    struct gpiod_line *mosi_line;
    struct gpiod_line *miso_line;

    // Initialize GPIO chip
    chip = gpiod_chip_new("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_new");
        return 1;
    }

    // Open chip-select line
    cs_line = gpiod_chip_get_line(chip, MAX31865_CS);
    if (!cs_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_unref(chip);
        return 1;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("open");
        gpiod_line_release(cs_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    // Initialize SPI device
    struct spidev_init_params spi_init_params = {
        .mode = SPI_MODE_0,
        .bits_per_word = 8,
        .max_speed_hz = 1000000,
        .chip_select = CS_HIGH
    };
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi_init_params.mode) < 0) {
        perror("ioctl");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_unref(chip);
        return 1;
    }

    // Open chip-select line for output
    if (gpiod_line_request_output(cs_line, 0) < 0) {
        perror("gpiod_line_request_output");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_chip_unref(chip);
        return 1;
    }

