    sck_line = gpiod_chip_get_line(chip, MAX31865_SCK);
    mosi_line = gpiod_chip_get_line(chip, MAX31865_MOSI);
    miso_line = gpiod_chip_get_line(chip, MAX31865_MISO);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_line_release(sck_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(miso_line);
        gpiod_chip_unref(chip);
        return 1;
