        fclose(log_file);
        close(spi_fd);
        gpiod_line_release(cs_line);
        gpiod_line_release(sck_line);
        gpiod_line_release(mosi_line);
        gpiod_line_release(miso_line);
        gpiod_chip_unref(chip);
