    if (ioctl(i2c_dev_fd, I2C_SLAVE, I2C_ADDRESS) == -1) {
        perror("ioctl");
        close(i2c_dev_fd);
        exit(1);
    }

    // Verify BME280 chip ID
    uint8_t chip_id;
    if (i2c_smbus_write_byte(i2c_dev_fd, 0xD0) == -1) {
        perror("i2c_smbus_write_byte");
        close(i2c_dev_fd);
        exit(1);
    }
