        fprintf(stderr, "Invalid BME280 chip ID\n");
        close(i2c_dev_fd);
        exit(1);
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        perror("fopen");
        close(i2c_dev_fd);
        exit(1);
    }

