                (tv.tv_sec % 3600 / 60) % 60, tv.tv_sec % 60, tv.tv_usec / 1000000);

        // Write to CSV file
        fprintf(csv_file, CSV_FORMAT, tv.tv_sec, temperature, humidity, pressure);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close I2C file descriptor and CSV file
    fclose(csv_file);
    close(i2c_dev_fd);

    return 0;
}

