#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define the BMP180 calibration coefficients structure
typedef struct {
    uint16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    int16_t ac5;
    int16_t ac6;
    uint16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_cal;

// Define the circular buffer structure
typedef struct {
    uint32_t timestamp;
    float pressure;
} pressure_reading;

#define BUFFER_SIZE 3600 // 60 seconds of data at 1 sample per 50 ms

// Global variables
gpio_timer_t timer_id;
int i2c_handle;
bmp180_cal calibration;
pressure_reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int alert_triggered = 0;
float rolling_average = 0.0;
int rolling_count = 0;

// Function to calculate the rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = buffer_tail; i < buffer_head; i++) {
        sum += buffer[i].pressure;
    }
    return sum / (buffer_head - buffer_tail);
}

// Function to check if the current pressure deviates by more than 5 hPa from the rolling average
bool check_alert() {
    float current_average = calculate_rolling_average();
    float current_pressure = buffer[buffer_tail].pressure;
    return (abs(current_pressure - current_average) > 5.0);
}

// Function to handle I2C read operation
int i2c_read_byte_data(int handle, uint8_t reg, uint8_t *data) {
    int ret = i2cReadByteData(handle, reg, data);
    if (ret < 0) {
        fprintf(stderr, "I2C read error: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to handle I2C write operation
int i2c_write_byte_data(int handle, uint8_t reg, uint8_t data) {
    int ret = i2cWriteByteData(handle, reg, data);
    if (ret < 0) {
        fprintf(stderr, "I2C write error: %d\n", ret);
        return -1;
    }
    return 0;
}

// Function to read the 11 calibration coefficients from the BMP180
int read_calibration() {
    uint8_t data[11];
    if (i2c_read_byte_data(i2c_handle, 0xAA, data) < 0) {
        return -1;
    }
    calibration.ac1 = (data[0] << 8) | data[1];
    calibration.ac2 = (data[2] << 8) | data[3];
    calibration.ac3 = (data[4] << 8) | data[5];
    calibration.ac4 = (data[6] << 8) | data[7];
    calibration.ac5 = (data[8] << 8) | data[9];
    calibration.ac6 = (data[10] << 8) | data[11];
    return 0;
}

// Function to read the pressure from the BMP180
int read_pressure() {
    uint8_t data[3];
    if (i2c_write_byte_data(i2c_handle, 0xF4, 0x34) < 0) {
        return -1;
    }
    usleep(5000);
    if (i2c_read_byte_data(i2c_handle, 0xF6, data) < 0) {
        return -1;
    }
    int32_t pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    pressure = (pressure * calibration.ac3) / 256 + calibration.ac2;
    pressure = pressure / 4;
    pressure = pressure + (calibration.ac1 * (1 << 15));
    pressure = pressure / 2;
    pressure = pressure / 1024;
    return pressure;
}

// Function to handle the timer interrupt
void timer_callback(int timer_id, int unused) {
    if (i2c_read_byte_data(i2c_handle, 0xF4, NULL) < 0) {
        fprintf(stderr, "I2C read error\n");
        return;
    }
    int pressure = read_pressure();
    if (pressure < 0) {
        fprintf(stderr, "Pressure read error\n");
        return;
    }
    buffer[buffer_head].timestamp = time(NULL);
    buffer[buffer_head].pressure = pressure;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    rolling_average = (rolling_average * (rolling_count - 1) + pressure) / rolling_count;
    rolling_count++;
    if (check_alert()) {
        fprintf(stderr, "Pressure alert: %f hPa\n", pressure);
        alert_triggered = 1;
    }
    if (alert_triggered) {
        gpioWrite(24, 1);
    } else {
        gpioWrite(24, 0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "GPIO initialization error\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, 0x77);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open error\n");
        gpioTerminate();
        return 1;
    }

    // Read the calibration coefficients
    if (read_calibration() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up the timer
    timer_id = gpioSetTimerFuncEx(50, timer_callback, NULL, NULL);
    if (timer_id < 0) {
        fprintf(stderr, "Timer setup error\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    // Clean up
    gpioSetTimerFuncEx(0, NULL, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    gpioSetTimerFuncEx(0, NULL, NULL, NULL);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Register the signal handler
void setup_signal_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}

