        gpioI2CClose(1, 0x77);
        gpioTerminate();
        exit(1);
    }

    // Start timer
    if (gpioTimerStart(timer) != 0) {
        fprintf(stderr, "Failed to start timer\n");
        gpioTimerDelete(timer);
        gpioI2CClose(1, 0x77);
        gpioTerminate();
        exit(1);
    }

    // Main loop
    while (1) {
        sleep(1);
    }

    return 0;
}

void sample_callback(int timer) {
    // Read temperature and pressure
    uint32_t temperature = read24(0xF6);
    uint32_t pressure = read24(0xF4);

    // Calculate temperature in °C
    int32_t temp = (int32_t)((temperature >> 8) & 0xFF) * 256 + (temperature & 0xFF);
    temp = temp * 200 / 1000 - 4000;

    // Calculate pressure in Pa
    int32_t pres = (int32_t)((pressure >> 8) & 0xFF) * 256 + (pressure >> 16 & 0xFF);
