#define FAN_GPIO 18
#define FAN_LOG_FILE "fan_log.txt"
#define FAN_LOG_INTERVAL 5000000  // 5 seconds
#define FAN_MIN_DUTY 0
#define FAN_MAX_DUTY 255
#define FAN_MIN_TEMP 40
#define FAN_MAX_TEMP 70
#define FAN_PWM_FREQ 25000  // 25 kHz

static volatile bool running = true;
static int fan_fd = -1;
static int log_fd = -1;

void cleanup(int sig) {
    running = false;
    if (fan_fd != -1) {
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        close(fan_fd);
    }
    if (log_fd != -1) {
        close(log_fd);
    }
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(1);
    }

    fan_fd = gpioOpen(FAN_GPIO, 1);
    if (fan_fd == -1) {
        perror("gpioOpen");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(FAN_GPIO, PI_PWM) == -1) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(1);
    }

    if (gpioSetPWMfrequency(FAN_GPIO, FAN_PWM_FREQ) == -1) {
        perror("gpioSetPWMfrequency");
        gpioTerminate();
        exit(1);
    }

    log_fd = open(FAN_LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        perror("open");
        gpioTerminate();
        exit(1);
    }

    while (running) {
        char temp_path[256];
        sprintf(temp_path, "/sys/class/thermal/thermal_zone0/temp");
        FILE *temp_file = fopen(temp_path, "r");
        if (temp_file == NULL) {
            perror("fopen");
            continue;
        }

        int temp;
        if (fscanf(temp_file, "%d", &temp) != 1) {
            perror("fscanf");
            fclose(temp_file);
            continue;
        }

        int duty = (temp - FAN_MIN_TEMP) * (FAN_MAX_DUTY - FAN_MIN_DUTY) / (FAN_MAX_TEMP - FAN_MIN_TEMP);
        if (duty < FAN_MIN_DUTY) {
            duty = FAN_MIN_DUTY;
        } else if (duty > FAN_MAX_DUTY) {
            duty = FAN_MAX_DUTY;
        }

        if (gpioPWM(FAN_GPIO, duty) == -1) {
            perror("gpioPWM");
            gpioTerminate();
            exit(1);
        }

        char log_str[256];
        time_t now = time(NULL);
        strftime(log_str, sizeof(log_str), "%Y-%m-%d %H:%M:%S", localtime(&now));
        sprintf(log_str + strlen(log_str), ", temp=%d, duty=%d\n", temp, duty);
        if (write(log_fd, log_str, strlen(log_str)) == -1) {
            perror("write");
        }

        fclose(temp_file);
        usleep(FAN_LOG_INTERVAL);
    }

    return 0;
}

