#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <pthread.h>
#include <gpiod.h>
#include <errno.h>

#define BUFFER_SIZE 60
#define TEMPERATURE_REGISTER 0x00
#define TEMPERATURE_ADDRESS 0x48
#define I2C_BUS 1
#define GPIO_PIN 18
#define TEMPERATURE_SHIFT 5
#define TEMPERATURE_MASK 0x1F
#define TEMPERATURE_MAX 28.0

// Structure to hold the circular buffer
typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int tail;
    int size;
    pthread_mutex_t mutex;
} CircularBuffer;

// Function to initialize the circular buffer
void initCircularBuffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Function to add an element to the circular buffer
void addElement(CircularBuffer *buffer, double element) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size < BUFFER_SIZE) {
        buffer->buffer[buffer->head] = element;
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        buffer->size++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to get the running average of the circular buffer
double getRunningAverage(CircularBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    double sum = 0.0;
    for (int i = 0; i < buffer->size; i++) {
        sum += buffer->buffer[(buffer->tail + i) % BUFFER_SIZE];
    }
    double average = sum / buffer->size;
    pthread_mutex_unlock(&buffer->mutex);
    return average;
}

// Function to read the temperature from the LM75 sensor
double readTemperature(int i2cFd) {
    uint8_t data[2];
    if (i2c_smbus_read_byte_data(i2cFd, TEMPERATURE_REGISTER, data) < 0) {
        perror("i2c_smbus_read_byte_data");
        return -1.0;
    }
    int16_t temperature = (data[0] << TEMPERATURE_SHIFT) | (data[1] << TEMPERATURE_SHIFT);
    if (temperature & 0x8000) {
        temperature -= 0x10000;
    }
    return (double)temperature / 256.0;
}

// Function to handle the background thread
void *threadFunc(void *arg) {
    CircularBuffer *buffer = (CircularBuffer *)arg;
    int i2cFd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2cFd < 0) {
