// Structure to hold the circular buffer
typedef struct {
    double buffer[BUFFER_SIZE];
    int head;
    int tail;
    int size;
    pthread_mutex_t mutex;
} CircularBuffer;

// Function to initialize the circular buffer
void initCircularBuffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->size = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Function to add an element to the circular buffer
void addElement(CircularBuffer *buffer, double element) {
    pthread_mutex_lock(&buffer->mutex);
    if (buffer->size < BUFFER_SIZE) {
        buffer->buffer[buffer->head] = element;
        buffer->head = (buffer->head + 1) % BUFFER_SIZE;
        buffer->size++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Function to get the running average of the circular buffer
double getRunningAverage(CircularBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    double sum = 0.0;
    for (int i = 0; i < buffer->size; i++) {
        sum += buffer->buffer[(buffer->tail + i) % BUFFER_SIZE];
    }
    double average = sum / buffer->size;
    pthread_mutex_unlock(&buffer->mutex);
    return average;
}

