#define MAX31865_SCK 1
#define MAX31865_MOSI 2
#define MAX31865_MISO 3
#define GPIO_HEATER 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PID_DT 0.1
#define PID_KI 0.1
#define PID_KP 1.0
#define TARGET_TEMP 25.0
#define FAULT_TEMP 80.0

#define JSON_CONFIG_FILE "config.json"

typedef struct {
    double target;
    double kp;
    double ki;
    double kd;
} config_t;

void sigint_handler(int sig) {
    gpioPWM(GPIO_HEATER, 0);
    spiClose(MAX31865_CS);
    gpioTerminate();
    exit(0);
}

void fault_handler() {
    fprintf(stderr, "Fault detected, shutting down...\n");
    gpioPWM(GPIO_HEATER, 0);
    spiClose(MAX31865_CS);
    gpioTerminate();
    exit(1);
}

int main() {
    int ret;
    config_t config = { TARGET_TEMP, PID_KP, PID_KI, PID_KD };

    // Load config from file
    FILE *fp = fopen(JSON_CONFIG_FILE, "r");
    if (fp) {
        json_t *root = json_load_file(JSON_CONFIG_FILE, 0);
        if (root) {
            json_t *target = json_object_get(root, "target");
            json_t *kp = json_object_get(root, "kp");
            json_t *ki = json_object_get(root, "ki");
            json_t *kd = json_object_get(root, "kd");
            if (target && kp && ki && kd) {
                config.target = json_number_value(target);
                config.kp = json_number_value(kp);
                config.ki = json_number_value(ki);
                config.kd = json_number_value(kd);
            }
            json_decref(root);
        }
        fclose(fp);
    }

    // Initialize pigpio
    if ((ret = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", ret);
        return 1;
    }

    // Initialize SPI
    if ((ret = spiOpen(MAX31865_CS, 1, 500000)) < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", ret);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX31865
    if ((ret = spiXfer(MAX31865_CS, 0xC1, 1)) < 0) {
        fprintf(stderr, "Failed to initialize MAX31865: %d\n", ret);
        spiClose(MAX31865_CS);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO
    if ((ret = gpioSetMode(GPIO_HEATER, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %d\n", ret);
        spiClose(MAX31865_CS);
        gpioTerminate();
        return 1;
    }
    if ((ret = gpioSetPWM(GPIO_HEATER, PWM_FREQ, PWM_RANGE)) < 0) {
        fprintf(stderr, "Failed to set PWM: %d\n", ret);
        spiClose(MAX31865_CS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read temperature
        uint16_t msb, lsb;
        if ((ret = spiXfer(MAX31865_CS, 0x01, 1, &msb, 1)) < 0) {
            fault_handler();
        }
        if ((ret = spiXfer(MAX31865_CS, 0x02, 1, &lsb, 1)) < 0) {
            fault_handler();
        }
        if (msb & 0x01) {
            fault_handler();
        }
        uint16_t code = (msb << 8) | lsb;
        uint16_t r_rtd = (code / 32768) * 430;
        double t = 0;
        if (r_rtd > 0) {
            t = (r_rtd - 100) / (4.8039 * 100) + 0.01;
        }

        // PID control
        double error = config.target - t;
        double pid = config.kp * error + config.ki * error * PID_DT + config.kd * (error - error_last) / PID_DT;
        error_last = error;
        double duty = (pid + 1) / 2 * PWM_RANGE;

        // Limit duty cycle
        duty = (duty < 0) ? 0 : (duty > PWM_RANGE) ? PWM_RANGE : duty;

        // Set PWM
        if ((ret = gpioPWM(GPIO_HEATER, duty)) < 0) {
            fault_handler();
        }

        // Check for faults
        uint8_t fault_status;
        if ((ret = spiXfer(MAX31865_CS, 0x07, 1, &fault_status, 1)) < 0) {
            fault_handler();
        }
        if (fault_status & 0x01) {
            fault_handler();
        }

        // Sleep
        usleep(100000);
    }

    return 0;
}

