#define BMP180_ADDRESS 0x77
#define BMP180_REG_AC1 0xAA
#define BMP180_REG_AC2 0xAC
#define BMP180_REG_AC3 0xAE
#define BMP180_REG_AC4 0xB0
#define BMP180_REG_AC5 0xB2
#define BMP180_REG_AC6 0xB4
#define BMP180_REG_X1 0xB6
#define BMP180_REG_X2 0xB8
#define BMP180_REG_X3 0xBA
#define BMP180_REG_X4 0xBC
#define BMP180_REG_X5 0xBE
#define BMP180_REG_TEMP 0xF6
#define BMP180_REG_PRESS 0xF4
#define BMP180_REG_STATUS 0xF3

#define BREACH_LOG_FILE "breach_log.txt"

#define MAX_BREACH_LOG_SIZE 1024

int i2c_fd = -1;
int breach_count = 0;

struct sigaction sa;

void sig_handler(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(0);
}

void read_bmp180_reg(int reg, uint8_t *buf, int len) {
    if (i2c_fd < 0) {
        return;
    }

    struct i2c_msg msg[2];
    msg[0].addr = BMP180_ADDRESS;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = BMP180_ADDRESS;
    msg[1].flags = I2C_M_RD;
    msg[1].len = len;
    msg[1].buf = buf;

    int ret = i2c_transfer(i2c_fd, msg, 2);
    if (ret < 0) {
        if (errno == EAGAIN) {
            // retry
            return;
        } else if (errno == EIO) {
            // bus error
            fprintf(stderr, "I2C bus error\n");
            exit(1);
        } else {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            exit(1);
        }
    }
}

void write_bmp180_reg(int reg, uint8_t val) {
    if (i2c_fd < 0) {
        return;
    }

    struct i2c_msg msg;
    msg.addr = BMP180_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = &val;

    int ret = i2c_transfer(i2c_fd, &msg, 1);
    if (ret < 0) {
        if (errno == EAGAIN) {
            // retry
            return;
        } else if (errno == EIO) {
            // bus error
            fprintf(stderr, "I2C bus error\n");
            exit(1);
        } else {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            exit(1);
        }
    }
}

