    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        exit(1);
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDRESS) < 0) {
        perror("ioctl");
        exit(1);
    }

    uint8_t ac1, ac2, ac3, ac4, ac5, ac6, x1, x2, x3, x4, x5, x6;
    read_bmp180_reg(BMP180_REG_AC1, &ac1, 1);
    read_bmp180_reg(BMP180_REG_AC2, &ac2, 1);
    read_bmp180_reg(BMP180_REG_AC3, &ac3, 1);
    read_bmp180_reg(BMP180_REG_AC4, &ac4, 1);
    read_bmp180_reg(BMP180_REG_AC5, &ac5, 1);
    read_bmp180_reg(BMP180_REG_AC6, &ac6, 1);
    read_bmp180_reg(BMP180_REG_X1, &x1, 1);
    read_bmp180_reg(BMP180_REG_X2, &x2, 1);
    read_bmp180_reg(BMP180_REG_X3, &x3, 1);
    read_bmp180_reg(BMP180_REG_X4, &x4, 1);
    read_bmp180_reg(BMP180_REG_X5, &x5, 1);
    read_bmp180_reg(BMP180_REG_X6, &x6, 1);

    while (1) {
        struct timeval tv;
        tv.tv_sec = 1;
        tv.tv_usec = 0;
        fd_set rset;
        FD_ZERO(&rset);
        FD_SET(i2c_fd, &rset);
        if (select(i2c_fd + 1, &rset, NULL, NULL, &tv) < 0) {
            if (errno == EINTR) {
                continue;
            } else {
                perror("select");
                exit(1);
            }
        }

        uint8_t temp, press;
        write_bmp180_reg(BMP180_REG_TEMP, 0x2E);
        usleep(100000);
        read_bmp180_reg(BMP180_REG_STATUS, &temp, 1);
        while ((temp & 0x08) == 0) {
            usleep(100000);
            read_bmp180_reg(BMP180_REG_STATUS, &temp, 1);
        }
        read_bmp180_reg(BMP180_REG_TEMP, &temp, 1);
        write_bmp180_reg(BMP180_REG_PRESS, 0x34);
        usleep(100000);
        read_bmp180_reg(BMP180_REG_STATUS, &temp, 1);
        while ((temp & 0x08) == 0) {
            usleep(100000);
            read_bmp180_reg(BMP180_REG_STATUS, &temp, 1);
        }
        read_bmp180_reg(BMP180_REG_PRESS, &press, 3);

        int32_t ut = (temp << 8) | (read_bmp180_reg(BMP180_REG_TEMP, NULL, 1) & 0xFF);
