#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define HEATER_PIN 17
#define SPI_BUS 0
#define SPI_CE 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11
#define MAX31855_FAULT 0x80
#define MAX31855_OPEN 0x40
#define MAX31855_SHORT_GND 0x20
#define MAX31855_SHORT_VCC 0x10
#define MAX31855_OK 0x00
#define MAX31855_TEMP_MASK 0x1F
#define MAX31855_FAULT_MASK 0xE0
#define TARGET_TEMP 25.0
#define MAX_DUTY 80
#define LOG_FILE "heater_log.csv"

// Define the PI controller parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.0
#define DT 0.1
#define I_MAX 100.0
#define D_MAX 100.0

// Define the PI controller state
typedef struct {
    double error;
    double integral;
    double derivative;
    double last_error;
} pi_state_t;

// Define the log file structure
typedef struct {
    FILE *file;
    time_t last_log_time;
} log_t;

// Function to read the temperature from the MAX31855
int max31855_read(int fd) {
    uint8_t data;
    if (spiXfer(fd, &data, 1, 1, 0) != 1) {
        return -1;
    }
    return (int)((data & MAX31855_TEMP_MASK) * 25.0);
}

// Function to calculate the PI controller output
double pi_control(double error, pi_state_t *state) {
    double output = Kp * error + Ki * state->integral + Kd * (error - state->last_error);
    state->integral += error * DT;
    state->last_error = error;
    if (state->integral > I_MAX) {
        state->integral = I_MAX;
    } else if (state->integral < -I_MAX) {
        state->integral = -I_MAX;
    }
    if (output > D_MAX) {
        output = D_MAX;
    } else if (output < -D_MAX) {
        output = -D_MAX;
    }
    return output;
}

// Function to handle the SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Turn off the heater
    gpioWrite(HEATER_PIN, 0);
    // Close the log file
    log_close();
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

// Function to initialize the log file
void log_init() {
    log_t *log = malloc(sizeof(log_t));
    log->file = fopen(LOG_FILE, "w");
    if (log->file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        exit(1);
    }
    log->last_log_time = time(NULL);
}

// Function to log the temperature and duty cycle
void log_log(double temp, double duty) {
    time_t now = time(NULL);
    if (now - log->last_log_time > 1) {
        fprintf(log->file, "%s,%.2f,%.2f\n", ctime(&now), temp, duty);
        log->last_log_time = now;
    }
}

// Function to close the log file
void log_close() {
    if (log->file != NULL) {
        fclose(log->file);
        free(log);
    }
}

int main() {
    // Initialize the PI controller state
    pi_state_t state;
    state.error = 0.0;
    state.integral = 0.0;
    state.derivative = 0.0;
    state.last_error = 0.0;

    // Initialize the log file
    log_init();

    // Initialize the SPI bus
    int fd = spiOpen(SPI_BUS, SPI_CE, 0);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        exit(1);
    }

    // Initialize the MAX31855
    uint8_t data;
    if (spiXfer(fd, &data, 1, 1, 0) != 1) {
        fprintf(stderr, "Failed to read MAX31855\n");
        spiClose(fd);
        log_close();
        exit(1);
    }
    if ((data & MAX31855_FAULT_MASK) != MAX31855_OK) {
        fprintf(stderr, "MAX31855 fault\n");
        spiClose(fd);
        log_close();
        exit(1);
    }

    // Initialize the heater pin
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        spiClose(fd);
        log_close();
        exit(1);
    }
    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the temperature from the MAX31855
        int temp = max31855_read(fd);
        if (temp < 0) {
            // If the MAX31855 read fails, set the heater duty cycle to 0%
            gpioWrite(HEATER_PIN, 0);
            log_log(0.0, 0.0);
            continue;
        }

        // Calculate the error
        double error = TARGET_TEMP - temp / 25.0;

        // Calculate the PI controller output
        double duty = pi_control(error, &state);

        // Limit the duty cycle to the safe maximum
        duty = (duty > MAX_DUTY) ? MAX_DUTY : duty;

        // Write the duty cycle to the heater pin
        gpioWrite(HEATER_PIN, (int)(duty * 255));

        // Log the temperature and duty cycle
        log_log(temp / 25.0, duty);

        // Sleep for 100ms
        usleep(100000);
    }

    return 0;
}

