        spiClose(fd);
        log_close();
        exit(1);
    }

    // Initialize the heater pin
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        spiClose(fd);
        log_close();
        exit(1);
    }
    if (gpioSetMode(HEATER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set heater pin mode\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        gpioTerminate();
        spiClose(fd);
        log_close();
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the temperature from the MAX31855
        int temp = max31855_read(fd);
        if (temp < 0) {
            // If the MAX31855 read fails, set the heater duty cycle to 0%
            gpioWrite(HEATER_PIN, 0);
            log_log(0.0, 0.0);
            continue;
        }

        // Calculate the error
        double error = TARGET_TEMP - temp / 25.0;

        // Calculate the PI controller output
        double duty = pi_control(error, &state);

        // Limit the duty cycle to the safe maximum
        duty = (duty > MAX_DUTY) ? MAX_DUTY : duty;

        // Write the duty cycle to the heater pin
        gpioWrite(HEATER_PIN, (int)(duty * 255));

        // Log the temperature and duty cycle
        log_log(temp / 25.0, duty);

        // Sleep for 100ms
        usleep(100000);
    }

    return 0;
}
