#include <pigpio.h>
#include <curl/curl.h>

#define DHT_PIN 4
#define DHT_TYPE DHT22
#define DHT_BIT_LENGTH 40
#define DHT_CHECKSUM_LENGTH 8
#define DHT_RETRY_COUNT 3
#define DHT_RETRY_DELAY 1000
#define API_URL "http://yourserver.com/api/humidity"

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int dht_read(int pin) {
    int fd = gpioOpen(pin, PI_READ);
    if (fd < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d: %s\n", pin, strerror(errno));
        return -1;
    }

    gpioSetMode(fd, PI_INPUT);
    gpioPullUpDnControl(fd, PI_PUD_UP);

    gpioDelay(1000); // 1 ms delay

    gpioWrite(fd, 0); // Pull the data line low
    gpioDelay(1000); // 1 ms delay

    int bits = 0;
    for (int i = 0; i < DHT_BIT_LENGTH; i++) {
        int level = gpioRead(fd);
        gpioDelay(50); // 50 us delay
        if (level == 0) {
            bits |= (1 << (DHT_BIT_LENGTH - 1 - i));
        }
    }

    gpioClose(fd);
    return bits;
}

int dht_parse(int bits) {
    int humidity = (bits >> 24) & 0xFF;
    int temperature = (bits >> 16) & 0xFF;
    int checksum = (bits >> 8) & 0xFF;

    int calculated_checksum = (humidity + temperature) & 0xFF;
    if (calculated_checksum != checksum) {
        return -1;
    }

    return humidity;
}

size_t write_callback(char *ptr, size_t size, size_t nmemb, void *userdata) {
    return fwrite(ptr, size, nmemb, (FILE *)userdata);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    CURL *curl;
    CURLcode res;
    FILE *fp;

    for (int retry = 0; retry < DHT_RETRY_COUNT; retry++) {
        int bits = dht_read(DHT_PIN);
        if (bits < 0) {
            fprintf(stderr, "Failed to read DHT data: %s\n", strerror(errno));
            continue;
        }

        int humidity = dht_parse(bits);
        if (humidity < 0) {
            fprintf(stderr, "Failed to parse DHT data: %s\n", strerror(errno));
            continue;
        }

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (!curl) {
            fprintf(stderr, "Failed to initialize libcurl: %s\n", curl_easy_strerror(curl_easy_get_last_error(curl)));
            continue;
        }

        fp = fopen("output.json", "w");
        if (!fp) {
            fprintf(stderr, "Failed to open output file: %s\n", strerror(errno));
            curl_easy_cleanup(curl);
            continue;
        }

        char json[256];
        sprintf(json, "{\"humidity\": %d, \"temperature\": %d}", humidity, 0); // Assuming temperature is not used in this example
        fwrite(json, strlen(json), 1, fp);
        fclose(fp);

        curl_easy_setopt(curl, CURLOPT_URL, API_URL);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, fp);
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "Failed to send HTTP request: %s\n", curl_easy_strerror(res));
            curl_easy_cleanup(curl);
            continue;
        }

        curl_easy_cleanup(curl);
        break;
    }

    gpioTerminate();
    return 0;
}

