        data[4] != 0x55 || data[5] != 0x55) {
        fprintf(stderr, "Invalid calibration coefficients\n");
        return false;
    }

    cal->ac1 = (uint16_t)((data[0] << 8) | data[1]);
    cal->ac2 = (int16_t)((data[2] << 8) | data[3]);
    cal->ac3 = (int16_t)((data[4] << 8) | data[5]);
    cal->ac4 = (uint16_t)((data[6] << 4) | (data[7] >> 4));
    cal->ac5 = (uint16_t)((data[8] << 4) | (data[9] >> 4));
    cal->ac6 = (uint16_t)((data[10] << 4) | (data[11] >> 4));
    cal->b1 = (int16_t)((data[12] << 8) | data[13]);
    cal->b2 = (int16_t)((data[14] << 8) | data[15]);
    cal->mb = (int16_t)((data[16] << 8) | data[17]);
    cal->mc = (int16_t)((data[18] << 8) | data[19]);
    cal->md = (int16_t)((data[20] << 8) | data[21]);

    return true;
}

// Function to read pressure from BMP180
int16_t read_pressure(bmp180_cal *cal) {
    int ret;
    uint8_t data[3];

    // Write start of measurement
    ret = i2c_write_reg(I2C_BUS, BMP180_ADDRESS, 0xF4, 0x2E, 1);
    if (ret < 0) {
        fprintf(stderr, "Error starting measurement: %d\n", ret);
        return -1;
    }

    // Wait for measurement to complete
    usleep(DELAY_US);

    // Read pressure data
    ret = i2c_read_reg(I2C_BUS, BMP180_ADDRESS, 0xF6, data, 3);
    if (ret < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", ret);
        return -1;
    }

    // Calculate pressure
    int32_t adc = (int32_t)((data[0] << 16) | (data[1] << 8) | data[2]);
    int32_t pressure = (int32_t)((adc / 2) - (cal->ac6 * 64 * (int32_t)adc + cal->ac5 * (int32_t)adc * (int32_t)adc / 4096) / 1024);
    pressure = (pressure * (int32_t)cal->ac5) / (int32_t)cal->ac4;
    pressure = pressure + (int32_t)cal->b1 * (int32_t)adc / (int32_t)cal->ac2;
    pressure = pressure / 4;
    pressure = pressure + (int32_t)cal->b2 * (int32_t)adc / (int32_t)cal->ac2;
    pressure = pressure / 4;
    pressure = pressure + (int32_t)cal->mb * (int32_t)cal->ac6 / (int32_t)cal->ac5;
    pressure = pressure / 2;
    pressure = pressure + (int32_t)cal->mc * (int32_t)cal->ac6 / (int32_t)ac5;
    pressure = pressure / 4;
    pressure = pressure + (int32_t)cal->md * (int32_t)cal->ac6 / (int32_t)ac5;
    pressure = pressure / 8;
    pressure = pressure + 5000;

    return (int16_t)pressure;
}

// Function to handle push-button interrupt
void interrupt_handler(int gpio, int level, uint32_t tick) {
    // Check if the interrupt is a falling edge
    if (level == 0) {
        // Debounce the interrupt
        if (tick - gpioTick > DEBOUNCE_US) {
            // Toggle logging state
            logging = !logging;
            gpioTick = tick;
        }
    }
}

int main() {
    int ret;
    int fd;
    int logging = 0;
    uint32_t gpioTick = 0;
    FILE *fp;
    bmp180_cal cal;

    // Initialize pigpio
    ret = pigpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error initializing pigpio: %d\n", ret);
        return 1;
    }

    // Set up I2C bus
    fd = i2cOpen(I2C_BUS, 1);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", fd);
        pigpioCleanup();
        return 1;
    }

    // Read calibration coefficients from BMP180
    if (!read_cal(&cal)) {
        i2cClose(fd);
        pigpioCleanup();
        return 1;
    }

    // Set up GPIO pin for push-button interrupt
    ret = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error setting up GPIO pin: %d\n", ret);
        i2cClose(fd);
        pigpioCleanup();
        return 1;
    }
    ret = gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);
    if (ret < 0) {
        fprintf(stderr, "Error setting up pull-up resistor: %d\n", ret);
        i2cClose(fd);
        pigpioCleanup();
        return 1;
    }
    ret = gpioSetISR(GPIO_PIN, EITHER_EDGE, 0, interrupt_handler);
    if (ret < 0) {
        fprintf(stderr, "Error setting up interrupt handler: %d\n", ret);
        i2cClose(fd);
        pigpioCleanup();
        return 1;
    }

    // Open log file
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %d\n", errno);
        i2cClose(fd);
        pigpioCleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Check if logging is enabled
        if (logging) {
            // Read pressure from BMP180
            int16_t pressure = read_pressure(&cal);
            if (pressure < 0) {
                fprintf(stderr, "Error reading pressure: %d\n", pressure);
                continue;
            }

            // Log pressure reading
            fprintf(fp, "%lu %d\n", (unsigned long)time(NULL), pressure);
            fflush(fp);
        } else {
            // Print status message
            printf("Logging disabled\n");
        }

        // Wait for 2 seconds
        usleep(2000000);
    }

    // Clean up
    fclose(fp);
    i2cClose(fd);
    pigpioCleanup();

    return 0;
}

// Handle SIGINT
void sigint_handler(int sig) {
    // Clean up
    fclose(fp);
    i2cClose(fd);
    pigpioCleanup();
    exit(0);
}

// Register SIGINT handler
void setup_signals() {
    struct sigaction sa;

    // Set up SIGINT handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
}
```

This code uses the pigpio library to interact with the Raspberry Pi's GPIO and I2C interfaces. It reads calibration coefficients from the BMP180 pressure sensor, sets up a push-button interrupt on GPIO4, and logs pressure readings to a file when the interrupt is triggered. The logging state is toggled on and off by the interrupt handler, and the program exits cleanly when a SIGINT signal is received.

