#define DHT22_BIT_LENGTH 40
#define DHT22_BIT_TIME 50 // us
#define DHT22_START_SIGNAL_TIME 20 // us
#define DHT22_BACKOFF 2000000 // 2 seconds
#define READ_INTERVAL 10000 // 10 seconds

static char server_url[256];
static CURL *curl;
static int retry_count = 0;

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received SIGINT, shutting down...");
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Received SIGTERM, shutting down...");
    gpioTerminate();
    curl_global_cleanup();
    exit(0);
}

int dht22_read() {
    int i, j, bit;
    unsigned int data = 0;
    gpioSetMode(DHT22_PIN, PI_INPUT);
    gpioPullUp(DHT22_PIN, PI_PUD_UP);
    gpioDelay(DHT22_START_SIGNAL_TIME);
    gpioWrite(DHT22_PIN, 1);
    gpioDelay(DHT22_BIT_TIME);
    gpioWrite(DHT22_PIN, 0);
    gpioDelay(DHT22_START_SIGNAL_TIME);
    for (i = 0; i < DHT22_BIT_LENGTH; i++) {
        gpioDelay(DHT22_BIT_TIME);
        bit = gpioRead(DHT22_PIN);
        gpioDelay(DHT22_BIT_TIME);
        if (gpioRead(DHT22_PIN)) {
            data |= 1 << (DHT22_BIT_LENGTH - 1 - i);
        }
    }
    return data;
}

int main(int argc, char **argv) {
    int humidity;
    char json[256];
    struct curl_slist *headers = NULL;
    struct sigaction sa;
    int server_url_len;

    // Initialize syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Parse command-line options
    if (argc > 1) {
        server_url_len = strlen(argv[1]);
        if (server_url_len < 256) {
            strncpy(server_url, argv[1], server_url_len);
            server_url[server_url_len] = '\0';
        } else {
            syslog(LOG_ERR, "Server URL too long");
            exit(1);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(1);
    }

