    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up SIGINT handler");
        exit(1);
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler");
        exit(1);
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        gpioTerminate();
        exit(1);
    }

    // Set up headers
    headers = curl_slist_append(headers, "Content-Type: application/json");

    while (1) {
        // Read humidity
        humidity = dht22_read();
        if (humidity == 0) {
            syslog(LOG_ERR, "DHT22 sensor not detected");
            gpioTerminate();
            curl_global_cleanup();
            exit(1);
        }

        // Validate checksum
        if ((humidity & 0x0000) != (humidity >> 8 & 0xFF)) {
            syslog(LOG_ERR, "Checksum failed");
            retry_count++;
            if (retry_count >= 3) {
                gpioTerminate();
                curl_global_cleanup();
                exit(1);
            }
            continue;
        }

        // Create JSON payload
        sprintf(json, "{\"humidity\": %d}", humidity >> 8);

        // POST to server
        curl_easy_setopt(curl, CURLOPT_URL, server_url);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
        if (curl_easy_perform(curl) != CURLE_OK) {
            syslog(LOG_ERR, "Failed to POST to server");
            retry_count++;
            if (retry_count >= 3) {
                gpioTerminate();
                curl_global_cleanup();
                exit(1);
            }
            continue;
        }

        // Check HTTP response
        long response_code;
        curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
        if (response_code != 200) {
            syslog(LOG_ERR, "Non-2xx HTTP response");
            retry_count++;
            if (retry_count >= 3) {
                gpioTerminate();
                curl_global_cleanup();
                exit(1);
            }
            continue;
        }

        // Log success
        syslog(LOG_INFO, "Posted humidity reading: %d", humidity >> 8);

        // Sleep
        usleep(READ_INTERVAL * 1000);
    }

    // Clean up
    gpioTerminate();
    curl_global_cleanup();
    return 0;
}

