#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define FAN_CONTROL_LOG_FILE "/var/log/fan_control.log"
#define THERMAL_ZONE "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_DEVICE "/sys/class/thermal/cooling_device0"

#define FAN_SPEED_TIER_0 0
#define FAN_SPEED_TIER_1 1
#define FAN_SPEED_TIER_2 2
#define FAN_SPEED_TIER_3 3

#define FAN_SPEED_TIER_THRESHOLDS { 45, 55, 65 }

#define MAX_STATE 3

static int cooling_device_fd = -1;
static int fan_speed_tier = FAN_SPEED_TIER_0;

static void log_event(const char *message) {
    FILE *file = fopen(FAN_CONTROL_LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp);

    fprintf(file, "%s: %s\n", timestamp_str, message);
    fclose(file);
}

static void update_fan_speed() {
    int temp_fd = open(THERMAL_ZONE, O_RDONLY);
    if (temp_fd == -1) {
        perror("open");
        return;
    }

    char temp_str[11];
    ssize_t bytes_read = read(temp_fd, temp_str, sizeof(temp_str) - 1);
    if (bytes_read == -1) {
        perror("read");
        close(temp_fd);
        return;
    }

    temp_str[bytes_read] = '\0';
    int temp = atoi(temp_str);
    close(temp_fd);

    for (int i = 0; i < 3; i++) {
        if (temp < FAN_SPEED_TIER_THRESHOLDS[i]) {
            fan_speed_tier = i;
            break;
        }
    }

    if (fan_speed_tier == FAN_SPEED_TIER_0) {
        log_event("Fan stopped");
    } else {
        int max_state;
        int state = fan_speed_tier;
        cooling_device_fd = open(COOLING_DEVICE "/max_state", O_RDONLY);
        if (cooling_device_fd == -1) {
            perror("open");
            return;
        }

        char max_state_str[11];
        ssize_t max_state_bytes_read = read(cooling_device_fd, max_state_str, sizeof(max_state_str) - 1);
        if (max_state_bytes_read == -1) {
            perror("read");
            close(cooling_device_fd);
            return;
        }

        max_state_str[max_state_bytes_read] = '\0';
        max_state = atoi(max_state_str);
        close(cooling_device_fd);

        if (state > max_state) {
            state = max_state;
        }

        cooling_device_fd = open(COOLING_DEVICE "/cur_state", O_WRONLY);
        if (cooling_device_fd == -1) {
            perror("open");
            return;
        }

        char state_str[11];
        sprintf(state_str, "%d", state);
        ssize_t state_bytes_written = write(cooling_device_fd, state_str, strlen(state_str));
        if (state_bytes_written == -1) {
            perror("write");
            close(cooling_device_fd);
            return;
        }

        close(cooling_device_fd);

        log_event("Fan speed changed to state %d", state);
    }
}

static void sigint_handler(int signal) {
    if (cooling_device_fd != -1) {
        char state_str[11];
        sprintf(state_str, "%d", FAN_SPEED_TIER_0);
        ssize_t state_bytes_written = write(cooling_device_fd, state_str, strlen(state_str));
        if (state_bytes_written == -1) {
            perror("write");
        }
        close(cooling_device_fd);
    }

    log_event("Shutdown initiated");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        update_fan_speed();
        sleep(5);
    }

    return 0;
}

