        close(cooling_device_fd);

        if (state > max_state) {
            state = max_state;
        }

        cooling_device_fd = open(COOLING_DEVICE "/cur_state", O_WRONLY);
        if (cooling_device_fd == -1) {
            perror("open");
            return;
        }

        char state_str[11];
        sprintf(state_str, "%d", state);
        ssize_t state_bytes_written = write(cooling_device_fd, state_str, strlen(state_str));
        if (state_bytes_written == -1) {
            perror("write");
            close(cooling_device_fd);
            return;
        }

        close(cooling_device_fd);

        log_event("Fan speed changed to state %d", state);
    }
}

static void sigint_handler(int signal) {
    if (cooling_device_fd != -1) {
        char state_str[11];
        sprintf(state_str, "%d", FAN_SPEED_TIER_0);
        ssize_t state_bytes_written = write(cooling_device_fd, state_str, strlen(state_str));
        if (state_bytes_written == -1) {
            perror("write");
        }
        close(cooling_device_fd);
    }

    log_event("Shutdown initiated");
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    while (1) {
        update_fan_speed();
        sleep(5);
    }

    return 0;
}
