#include <pigpio.h>
#include <syslog.h>

// PID controller parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define TARGET 50.0

// Thermocouple parameters
#define SPI_SPEED 500000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_CS_PIN 8
#define SPI_CLK_PIN 11
#define SPI_DO_PIN 9

// Heater parameters
#define HEATER_PIN 18
#define PWM_FREQ 1000

// Fault detection parameters
#define MAX31855_FAULT_OPEN 0x80
#define MAX31855_FAULT_SHORT_GND 0x40
#define MAX31855_FAULT_SHORT_VCC 0x20

// PID state
typedef struct {
    double error;
    double integral;
    double derivative;
    double last_error;
    double last_time;
} pid_state_t;

pid_state_t pid_state;

// PID function
double pid(double error, double dt) {
    pid_state.error = error;
    pid_state.integral += error * dt;
    pid_state.derivative = (error - pid_state.last_error) / dt;
    pid_state.last_error = error;
    pid_state.last_time += dt;
    return Kp * error + Ki * pid_state.integral + Kd * pid_state.derivative;
}

// Thermocouple function
double read_temperature() {
    int fd = spi_open(SPI_CS_PIN, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        return -1.0;
    }

    uint8_t data[4];
    int ret = spi_xfer(fd, data, 4, 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read from SPI device");
        spi_close(fd);
        return -1.0;
    }

    double temperature = (data[0] << 8) | data[1];
    temperature *= 0.25;

    uint8_t fault = (data[3] & 0x80) ? MAX31855_FAULT_OPEN : 0;
    fault |= (data[3] & 0x40) ? MAX31855_FAULT_SHORT_GND : 0;
    fault |= (data[3] & 0x20) ? MAX31855_FAULT_SHORT_VCC : 0;

    if (fault) {
        syslog(LOG_ERR, "Thermocouple fault: 0x%x", fault);
        return -1.0;
    }

    spi_close(fd);
    return temperature;
}

// Heater function
void set_heater(double duty) {
    if (duty < 0.0 || duty > 1.0) {
        syslog(LOG_ERR, "Invalid heater duty cycle: %f", duty);
        return;
    }

    int ret = gpioHardwarePWM(HEATER_PIN, PWM_FREQ, duty * 1000000);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to set heater PWM");
    }
}

// Signal handler
void sigint_handler(int sig) {
    set_heater(0.0);
    spi_close(SPI_CS_PIN);
    pigpio_stop();
    syslog(LOG_INFO, "Exiting...");
    exit(0);
}

int main() {
    // Initialize logging
    openlog(NULL, LOG_PID, LOG_USER);

    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        return 1;
    }

    // Initialize SPI
    if (spiOpen(SPI_CS_PIN, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST) < 0) {
        syslog(LOG_ERR, "Failed to open SPI device");
        pigpio_stop();
        return 1;
    }

    // Initialize heater
    set_heater(0.0);

    // Initialize PID state
    pid_state.error = 0.0;
    pid_state.integral = 0.0;
    pid_state.derivative = 0.0;
    pid_state.last_error = 0.0;
    pid_state.last_time = 0.0;

    // Set up signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        double temperature = read_temperature();
        if (temperature < 0.0) {
            set_heater(0.0);
            continue;
        }

        double error = TARGET - temperature;
        double pid_output = pid(error, 1.0);
        if (temperature > 100.0 || temperature < 0.0) {
            pid_output = 0.0;
        }

        set_heater(pid_output);

        // Log data
        FILE *fp = fopen("heater_log.txt", "a");
        if (fp == NULL) {
            syslog(LOG_ERR, "Failed to open log file");
            continue;
        }

        fprintf(fp, "%f %f %f\n", temperature, pid_output, error);
        fclose(fp);

        usleep(1000000);
    }

    return 0;
}

