volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,temperature,duty_cycle\n");

    // Set up PWM
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWM(FAN_GPIO, 0, FAN_PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read temperature
        char temp_str[10];
        int temp_fd = open(TEMP_FILE, O_RDONLY);
        if (temp_fd < 0) {
            fprintf(stderr, "Failed to open temperature file\n");
            break;
        }

        if (read(temp_fd, temp_str, 10) != 10) {
            fprintf(stderr, "Failed to read temperature\n");
            close(temp_fd);
            break;
        }

        close(temp_fd);

        int temp = atoi(temp_str);
        if (temp < 0) {
            fprintf(stderr, "Invalid temperature value\n");
            break;
        }

        // Calculate duty cycle
        int duty_cycle = (temp - 40) * 30 / 30 + 0;
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        // Set PWM duty cycle
        if (gpioPWM(FAN_GPIO, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
            break;
        }

        // Log data
        time_t timestamp = time(NULL);
        fprintf(log_file, "%lu,%d,%d\n", timestamp, temp, duty_cycle);

        // Sleep
        usleep(LOG_INTERVAL);
    }

    // Clean up
    fclose(log_file);
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();

    return 0;
}

