#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define I2C_RETRY_COUNT 3
#define MEASUREMENT_COMMAND 0x36
#define MEASUREMENT_LENGTH 3
#define FLOW_RATE_SCALE 0.01

// Function to calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = 0;
    for (size_t i = 0; i < length; i++) {
        crc = (crc ^ data[i]) ^ (crc >> 4);
        crc = (crc & 0x0F) * 0x02 ^ (crc >> 4);
    }
    return crc;
}

// Function to read from I2C bus
int read_i2c(int fd, uint8_t address, uint8_t *data, size_t length) {
    int retry_count = 0;
    while (retry_count < I2C_RETRY_COUNT) {
        if (i2c_read(fd, address, data, length) == length) {
            return 0;
        } else if (errno == EIO) {
            retry_count++;
            usleep(100000); // 100ms delay
        } else {
            return -1;
        }
    }
    return -1;
}

// Function to write to I2C bus
int write_i2c(int fd, uint8_t address, uint8_t *data, size_t length) {
    int retry_count = 0;
    while (retry_count < I2C_RETRY_COUNT) {
        if (i2c_write(fd, address, data, length) == length) {
            return 0;
        } else if (errno == EIO) {
            retry_count++;
            usleep(100000); // 100ms delay
        } else {
            return -1;
        }
    }
    return -1;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Close I2C handles
        i2c_close(I2C_BUS);
        // Terminate pigpio
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = i2cOpen(I2C_BUS, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C handles for both sensors
    int sensor1_fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    int sensor2_fd = i2cOpen(I2C_BUS, I2C_ADDRESS + 1);
    if (sensor1_fd < 0 || sensor2_fd < 0) {
        fprintf(stderr, "Failed to open I2C handles\n");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    FILE *log_file = fopen("flow_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2c_close(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read from sensor 1
        uint8_t data[MEASUREMENT_LENGTH];
        if (read_i2c(sensor1_fd, I2C_ADDRESS, data, MEASUREMENT_LENGTH) == 0) {
            if (data[2] == calculate_crc8(data, MEASUREMENT_LENGTH - 1)) {
                uint16_t flow_rate = (data[0] << 8) | data[1];
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
                        (int)time(NULL) % 10000 / 100, (int)time(NULL) % 100 / 10, (int)time(NULL) % 10,
                        (int)time(NULL) / 3600 % 24, (int)time(NULL) / 60 % 60, (int)time(NULL) % 60,
                        (int)(flow_rate * FLOW_RATE_SCALE));
            }
        }

        // Read from sensor 2
        if (read_i2c(sensor2_fd, I2C_ADDRESS + 1, data, MEASUREMENT_LENGTH) == 0) {
            if (data[2] == calculate_crc8(data, MEASUREMENT_LENGTH - 1)) {
                uint16_t flow_rate = (data[0] << 8) | data[1];
                fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d,%d\n",
                        (int)time(NULL) % 10000 / 100, (int)time(NULL) % 100 / 10, (int)time(NULL) % 10,
                        (int)time(NULL) / 3600 % 24, (int)time(NULL) / 60 % 60, (int)time(NULL) % 60,
                        (int)(flow_rate * FLOW_RATE_SCALE));
            }
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handles
    i2c_close(sensor1_fd);
    i2c_close(sensor2_fd);
    i2c_close(I2C_BUS);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

