// Function to initialize GPIO
bool init_gpio() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return false;
    }

    // Set the GPIO pins as inputs with internal pull-up resistors
    if (gpioSetMode(GPIO_A, PI_INPUT) < 0 || gpioSetPullUpDnControl(GPIO_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure GPIO A\n");
        gpioTerminate();
        return false;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) < 0 || gpioSetPullUpDnControl(GPIO_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to configure GPIO B\n");
        gpioTerminate();
        return false;
    }

    return true;
}

// Function to read the state of the encoder
int read_encoder() {
    // Read the state of the GPIO pins
    int state_A = gpioRead(GPIO_A);
    int state_B = gpioRead(GPIO_B);

    // Determine the direction of rotation
    int direction = (state_A == 1 && state_B == 0) ? 1 : (state_A == 0 && state_B == 1) ? -1 : 0;

    return direction;
}

// Function to update the encoder state
void update_encoder(int direction) {
    // Update the encoder state
    static int state = 0;
    static int last_direction = 0;
    static int pulses = 0;

    // Check for state changes
    if (direction != 0 && last_direction != direction) {
        // Update the last direction
        last_direction = direction;

        // Increment the pulse count
        pulses += direction;

        // Calculate the normalized angular position
        double position = (double)pulses / PULSES_PER_REVOLUTION * 360.0;

        // Log the event
        FILE *file = fopen(LOG_FILE, "a");
        if (file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }
        fprintf(file, "%.2f\n", position);
        fclose(file);
    }
}

int main() {
    // Initialize the GPIO library
    if (!init_gpio()) {
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of the encoder
        int direction = read_encoder();

        // Update the encoder state
        update_encoder(direction);

        // Sleep for a short period to avoid consuming too much CPU
        usleep(10000);
    }

    return 0;
}

