#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define FIFO_DATA_REG 0x60
#define LED_PIN 17
#define THRESHOLD 2000
#define LOG_FILE "adpd144ri_log.txt"
#define LOG_INTERVAL 100000 // 100 ms

int i2c_fd;
struct gpiod_line *led_line;
struct gpiod_line *irq_line;
struct gpiod_line *irq_event;

void log_data(double timestamp, int red, int ir) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%f,%d,%d\n", timestamp, red, ir);
    fclose(log_file);
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (irq_line != NULL) {
        gpiod_line_release(irq_line);
    }
    if (irq_event != NULL) {
        gpiod_event_release(irq_event);
    }
    exit(0);
}

void sigint_handler(int sig) {
    cleanup();
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line_request req;
    struct gpiod_line_config config;
    struct i2c_msg msg;
    char buffer[2];
    int red, ir;
    double timestamp;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        exit(1);
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(1);
    }

    req.consumer = "adpd144ri";
    req.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    req.line_offset = LED_PIN;
    req.flags = GPIOD_LINE_REQUEST_ACTIVE_HIGH;
    if (gpiod_line_request(led_line, &req) < 0) {
        perror("gpiod_line_request");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        close(i2c_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        exit(1);
    }

    while (1) {
        // Read data from FIFO
        msg.buf = buffer;
        msg.len = 2;
        msg.flags = 0;
        msg.addr = I2C_ADDRESS;
        msg.fmt = I2C_M_RD;
        if (ioctl(i2c_fd, I2C_RDWR, &msg) < 0) {
            perror("ioctl");
            cleanup();
        }
        red = (buffer[0] << 8) | buffer[1];
        ir = (buffer[0] << 8) | buffer[1];

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Log data
        timestamp = (double)time(NULL);
        log_data(timestamp, red, ir);

        // Sleep for 100 ms
        usleep(LOG_INTERVAL);
    }

    return 0;
}

