#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

volatile int pulses = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
double last_timestamp = 0.0;
double last_rpm = 0.0;

void sigint_handler(int sig) {
    (void)sig;
    gpioTerminate();
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    exit(0);
}

void* isr(void* arg) {
    while (1) {
        int edge = gpioRead(GPIO_PIN);
        if (edge == 1) {
            pthread_mutex_lock(&pulse_mutex);
            pulses++;
            pthread_mutex_unlock(&pulse_mutex);
        }
        usleep(1000); // 1ms resolution
    }
    return NULL;
}

int main() {
    int log_file = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_file == -1) {
        perror("open");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    pthread_t isr_thread;
    if (pthread_create(&isr_thread, NULL, isr, NULL) != 0) {
        fprintf(stderr, "Failed to create ISR thread\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        double current_timestamp = (double)time(NULL);
        double elapsed = current_timestamp - last_timestamp;
        if (elapsed > 0.0) {
            double rpm = (pulses / elapsed) * 60.0;
            last_rpm = rpm;
            last_timestamp = current_timestamp;
            pulses = 0;
            fprintf(log_file, "%.2f\n", rpm);
            fflush(log_file);
        }
        pthread_mutex_unlock(&pulse_mutex);
        usleep(1000000); // 1s resolution
    }

    return 0;
}

