    if (gpioSetAlertFunc(GPIO_PIN, isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return 1;
    }

    pthread_t isr_thread;
    if (pthread_create(&isr_thread, NULL, isr, NULL) != 0) {
        fprintf(stderr, "Failed to create ISR thread\n");
        gpioTerminate();
        return 1;
    }

    while (1) {
        pthread_mutex_lock(&pulse_mutex);
        double current_timestamp = (double)time(NULL);
        double elapsed = current_timestamp - last_timestamp;
        if (elapsed > 0.0) {
            double rpm = (pulses / elapsed) * 60.0;
            last_rpm = rpm;
            last_timestamp = current_timestamp;
            pulses = 0;
            fprintf(log_file, "%.2f\n", rpm);
            fflush(log_file);
        }
        pthread_mutex_unlock(&pulse_mutex);
        usleep(1000000); // 1s resolution
    }

    return 0;
}
