        // Read FIFO data registers
        msg.buf = &ret;
        msg.len = 1;
        msg.flags = 0;
        msg.addr = I2C_ADDRESS;
        msg.fmt = I2C_M_RD;
        ret = ioctl(i2c_fd, I2C_MSG, &msg);
        if (ret == -1) {
