            fprintf(stderr, "Error reading FIFO data register\n");
            cleanup();
        }
        int ir = ret;

        // Log data
        log_time_t = time(NULL);
        log_time = localtime(&log_time_t);
        strftime(log_buf, sizeof(log_buf), "%Y-%m-%d %H:%M:%S", log_time);
        fprintf(fopen(LOG_FILE, "a"), "%s,%d,%d\n", log_buf, red, ir);
        fclose(fopen(LOG_FILE, "a"));

        // Trigger LED if IR reading exceeds threshold
        if (ir > THRESHOLD) {
            ret = gpiod_write(gpio_fd, GPIO_LED, 1);
            if (ret != 0) {
                perror("gpiod_write");
                cleanup();
            }
        } else {
            ret = gpiod_write(gpio_fd, GPIO_LED, 0);
            if (ret != 0) {
                perror("gpiod_write");
                cleanup();
            }
        }

        // Sleep
        usleep(100000);
    }

    return 0;
}

