#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

// Define signal handlers for SIGINT and SIGTERM
void sigint_handler(int sig) {
    gpiod_close(ctx);
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_close(ctx);
    exit(0);
}

int main() {
    // Initialize libgpiod context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        fprintf(stderr, "Failed to create libgpiod context\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_new(ctx, "gpiochip0");
    if (!chip) {
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Open GPIO lines
    line_in = gpiod_line_new(chip, "17", GPIOD_LINE_ACTIVE_STATE_HIGH);
    if (!line_in) {
        gpiod_chip_free(chip);
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to open GPIO line 17\n");
        return 1;
    }

    line_out = gpiod_line_new(chip, "18", GPIOD_LINE_ACTIVE_STATE_LOW);
    if (!line_out) {
        gpiod_line_free(line_in);
        gpiod_chip_free(chip);
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to open GPIO line 18\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Set up logging
    FILE *log_file = fopen("audio_log.txt", "w");
    if (!log_file) {
        gpiod_line_free(line_in);
        gpiod_line_free(line_out);
        gpiod_chip_free(chip);
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set GPIO 18 to output and set to LOW (60dB gain)
    if (gpiod_line_direction(line_out, GPIOD_DIRECTION_OUTPUT) < 0) {
        fclose(log_file);
        gpiod_line_free(line_in);
        gpiod_line_free(line_out);
        gpiod_chip_free(chip);
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to set GPIO 18 direction\n");
        return 1;
    }
    if (gpiod_line_value(line_out, 0) < 0) {
        fclose(log_file);
        gpiod_line_free(line_in);
        gpiod_line_free(line_out);
        gpiod_chip_free(chip);
        gpiod_ctx_free(ctx);
        fprintf(stderr, "Failed to set GPIO 18 value\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Poll GPIO 17 for rising edges
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line_in, 10 * 1000, &event) < 0) {
            fclose(log_file);
            gpiod_line_free(line_in);
            gpiod_line_free(line_out);
            gpiod_chip_free(chip);
            gpiod_ctx_free(ctx);
            fprintf(stderr, "Failed to poll GPIO 17\n");
            return 1;
        }
        if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Log peak sound event
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
            fprintf(log_file, "%s 1\n", timestamp);
        }
    }

    // Clean up on exit
    fclose(log_file);
    gpiod_line_free(line_in);
    gpiod_line_free(line_out);
    gpiod_chip_free(chip);
    gpiod_ctx_free(ctx);
    return 0;
}

