#define SLF3S4000B_CRC_INITIAL_VALUE 0xFF

// Function to calculate CRC-8
uint8_t slf3s4000b_crc8(uint8_t *data, size_t len) {
    uint8_t crc = SLF3S4000B_CRC_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ SLF3S4000B_CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to convert raw flow value to flow rate in uL/min
float slf3s4000b_flow_rate(uint16_t raw_flow) {
    return (float)raw_flow / 1000.0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Close I2C handle
    if (gpioI2COpen(1, SLF3S4000B_I2C_ADDRESS, NULL) == -1) {
        fprintf(stderr, "Error closing I2C handle\n");
    }

    // Flush and close log file
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file\n");
    }

    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c_handle = gpioI2COpen(1, SLF3S4000B_I2C_ADDRESS, NULL);
    if (i2c_handle == -1) {
        fprintf(stderr, "Error opening I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor by sending measurement command
    uint8_t command[] = {SLF3S4000B_MEASUREMENT_COMMAND >> 8, SLF3S4000B_MEASUREMENT_COMMAND & 0xFF};
    if (gpioI2CWrite(i2c_handle, command, 2) != 2) {
        fprintf(stderr, "Error sending measurement command\n");
        gpioI2CClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read 3 bytes from sensor
        uint8_t data[3];
        if (gpioI2CRead(i2c_handle, data, 3) != 3) {
            fprintf(stderr, "Error reading from sensor\n");
            continue;
        }

        // Validate CRC-8
        uint8_t crc = slf3s4000b_crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC check failed\n");
            continue;
        }

        // Convert raw flow value to flow rate
        uint16_t raw_flow = (data[0] << 8) | data[1];
        float flow_rate = slf3s4000b_flow_rate(raw_flow);

        // Log flow rate
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
        fflush(log_file);

        // Sleep for 1000 ms
        usleep(1000000);
    }

    return 0;
}
```

Note: This code assumes that the `pigpio` library is installed and configured properly on the Raspberry Pi. Also, the `time.h` header is used for the `time` and `localtime` functions, which are used to get the current timestamp. The `strftime` function is used to format the timestamp as a string. The `usleep` function is used to sleep for 1000 ms. The `signal` function is used to set up the signal handler for SIGINT. The `fclose` function is used to close the log file. The `gpioTerminate` function is used to terminate the pigpio library.

