#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define REG_START 0x00
#define REG_END 0x06
#define LOG_FILE "air_quality_log.csv"

int main() {
    int i2c_fd = gpioInitialise();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", i2c_fd);
        return 1;
    }

    int log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    struct timeval last_log_time;
    gettimeofday(&last_log_time, NULL);

    while (1) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        if (current_time.tv_sec - last_log_time.tv_sec >= 5) {
            uint8_t buffer[7];
            int bytes_read = i2cReadReg8(i2c_fd, I2C_BUS, I2C_ADDRESS, REG_START, buffer, 7);
            if (bytes_read != 7) {
                fprintf(stderr, "Failed to read from I2C bus: %d\n", bytes_read);
                break;
            }

            uint16_t tvoc = (buffer[1] << 8) | buffer[2];
            uint16_t eCO2 = (buffer[5] << 8) | buffer[6];

            double iaq = 100 - (tvoc / 10.0) - ((eCO2 - 400) / 50.0);
            iaq = fmax(0.0, fmin(iaq, 100.0));

            fprintf(log_file, "%lu,%.2f,%.2f,%.2f\n", current_time.tv_sec, iaq, tvoc, eCO2);
            fflush(log_file);

            last_log_time = current_time;
        }

        usleep(100000);
    }

    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

