#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NUMBER 17
#define TOUCH_THRESHOLD 5000000 // 5 seconds in nanoseconds
#define POLL_INTERVAL 100000 // 100 ms in nanoseconds

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    struct timespec last_touch_time;
    uint64_t last_touch_ns = 0;

    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open gpiochip0
    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    // Request line as input with consumer label
    if ((line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER)) == NULL) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_NUMBER, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request(chip, line, GPIOD_LINE_REQUEST_INPUT, GPIOD_LINE_EDGE_NONE, "ttp223_tamper") != 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_LINE_NUMBER, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize last_touch_time
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
    last_touch_ns = last_touch_time.tv_sec * 1000000000 + last_touch_time.tv_nsec;

    while (running) {
        // Poll the line
        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_LINE_NUMBER, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Check if the line is high (touched)
        if (event.value == GPIOD_LINE_EVENT_VALUE_HIGH) {
            // Get current time
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
            uint64_t current_ns = last_touch_time.tv_sec * 1000000000 + last_touch_time.tv_nsec;

            // Check if the sensor has been continuously touched for more than 5 seconds
            if (current_ns - last_touch_ns > TOUCH_THRESHOLD) {
                printf("Intrusion alert!\n");
                last_touch_ns = current_ns;
            }
        } else {
            // Reset timer when the sensor is released
            last_touch_ns = 0;
        }

        // Sleep for a short period
        nanosleep((const struct timespec[]){{0, POLL_INTERVAL}}, NULL);
    }

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

