#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <linux/spi/spi.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define MIC_I2C_BUS 1
#define MIC_I2C_ADDR 0x1A
#define MIC_LSEL_PIN 17
#define MIC_SAMPLE_RATE 48000
#define MIC_BITS_PER_SAMPLE 24
#define MIC_CHANNELS 1
#define MIC_SAMPLE_SIZE (MIC_BITS_PER_SAMPLE / 8)
#define MIC_FRAME_SIZE (MIC_CHANNELS * MIC_SAMPLE_SIZE)
#define MIC_PCM_FILE "audio_capture.pcm"

int main() {
    int i, ret;
    int fd_i2c, fd_spi, fd_pcm;
    struct i2c_msg msg;
    struct spi_ioc_transfer xfer;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    snd_pcm_t *handle;
    snd_pcm_hw_params_t *hw_params;
    snd_pcm_sw_params_t *sw_params;
    snd_pcm_uframes_t frames;
    snd_pcm_sframes_t frames_read;
    uint8_t buffer[MIC_FRAME_SIZE];
    uint32_t sample;

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    line = gpiod_chip_get_line(chip, MIC_LSEL_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_output(line, "active-high");
    gpiod_line_set_value(line, 0);

    // Initialize I2C
    fd_i2c = open("/dev/i2c-" + MIC_I2C_BUS, O_RDWR);
    if (fd_i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    fd_spi = open("/dev/spidev0.0", O_RDWR);
    if (fd_spi < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        close(fd_i2c);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize ALSA
    snd_pcm_open(&handle, "plughw:0,0", SND_PCM_STREAM_CAPTURE, 0, 0, NULL, NULL);
    if (snd_pcm_hw_params_malloc(&hw_params) < 0) {
        fprintf(stderr, "Failed to allocate hardware parameters\n");
        close(fd_spi);
        close(fd_i2c);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    snd_pcm_hw_params_any(handle, hw_params);
    snd_pcm_hw_params_set_access(handle, hw_params, SND_PCM_ACCESS_MMAP_INTERLEAVED);
    snd_pcm_hw_params_set_format(handle, hw_params, SND_PCM_FORMAT_S16_LE);
    snd_pcm_hw_params_set_rate(handle, hw_params, MIC_SAMPLE_RATE, 0);
    snd_pcm_hw_params_set_channels(handle, hw_params, MIC_CHANNELS);
    snd_pcm_hw_params_set_buffer_size(handle, hw_params, MIC_FRAME_SIZE);
    snd_pcm_hw_params(handle, hw_params);

    snd_pcm_sw_params_malloc(&sw_params);
    snd_pcm_sw_params_current(handle, sw_params);
    snd_pcm_sw_params_set_start_threshold(handle, sw_params, 0);
    snd_pcm_sw_params_set_stop_threshold(handle, sw_params, 0);
    snd_pcm_sw_params(handle, sw_params);

    snd_pcm_prepare(handle);

    // Open PCM file for writing
    fd_pcm = open(MIC_PCM_FILE, O_WRONLY | O_CREAT, 0644);
    if (fd_pcm < 0) {
        fprintf(stderr, "Failed to open PCM file\n");
        snd_pcm_close(handle);
        snd_pcm_sw_params_free(sw_params);
        snd_pcm_hw_params_free(hw_params);
        close(fd_spi);
        close(fd_i2c);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read I2S data
        ret = read(fd_spi, buffer, MIC_FRAME_SIZE);
        if (ret < 0) {
            fprintf(stderr, "Failed to read I2S data\n");
            break;
        }

        // Extract 24-bit data and right-shift to 16-bit PCM samples
        for (i = 0; i < MIC_FRAME_SIZE; i += MIC_SAMPLE_SIZE) {
            sample = (buffer[i] << 16) | (buffer[i + 1] << 8) | buffer[i + 2];
            sample >>= (MIC_BITS_PER_SAMPLE - 16);
            if (sample & 0x8000) {
                sample -= 0x10000;
            }
            fwrite(&sample, sizeof(uint16_t), 1, fd_pcm);
        }

        // Wait for more data to be available
        snd_pcm_wait(handle, 1000);
    }

    // Clean up
    snd_pcm_close(handle);
    snd_pcm_sw_params_free(sw_params);
    snd_pcm_hw_params_free(hw_params);
    close(fd_pcm);
    close(fd_spi);
    close(fd_i2c);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Clean up on exit
    snd_pcm_close(NULL);
    snd_pcm_sw_params_free(NULL);
    snd_pcm_hw_params_free(NULL);
    close(0);
    close(1);
    close(2);
    exit(0);
}

// Register signal handler for SIGINT
int main() {
    signal(SIGINT, sigint_handler);
    // ... (rest of the code remains the same)
