        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(GPIO_SENSOR, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down control for GPIO%d\n", GPIO_SENSOR);
        gpioTerminate();
        exit(1);
    }
}

void cleanup_gpio() {
    if (fan_on) {
        gpioPWM(GPIO_FAN, 0);
    }
    gpioSetMode(GPIO_SENSOR, PI_INPUT);
    gpioSetMode(GPIO_FAN, PI_OUTPUT);
    gpioSetPullUpDnControl(GPIO_SENSOR, PI_PUD_OFF);
    gpioTerminate();
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    char timestamp_str[32];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timestamp);
