            log_event("Flame detected");
            flame_detected = true;
            last_flame_timestamp = time(NULL);
        }
    } else {
        if (flame_detected) {
            log_event("Flame ended");
            flame_detected = false;
            flame_duration = (uint32_t)time(NULL) - last_flame_timestamp;
            if (flame_duration > 0) {
                double duty_cycle = pow(1.0 - (double)flame_duration / 10.0, FAN_DUTY_EXPONENT) * FAN_DUTY_MAX;
                if (duty_cycle > 0) {
                    fan_on = true;
                    gpioPWM(GPIO_FAN, (int)duty_cycle);
                } else {
                    fan_on = false;
                    gpioPWM(GPIO_FAN, 0);
                }
            }
        }
    }
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    init_gpio();

    log_event("System started");

    while (1) {
        poll_sensor();
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    return 0;
}

