// Define the magic number for the binary log file
#define MAGIC_NUMBER 0x52444144

// Define the configuration struct
typedef struct {
    uint32_t start_frequency;
    uint32_t end_frequency;
    uint32_t num_chirps;
    uint32_t num_samples;
    uint32_t frame_period;
} config_t;

// Function to handle SIGINT/SIGTERM
void sigint_handler(int sig) {
    // Close SPI
    gpio_spi_close(0);

    // Release GPIO
    gpio_cleanup();

    // Close the file
    fclose(log_file);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI0.0 at 1 MHz mode 0
    if (gpio_spi_open(0, 1000000, 0) < 0) {
        fprintf(stderr, "Failed to open SPI0.0\n");
        gpio_cleanup();
        return 1;
    }

    // Set up GPIO 23 as output for hardware trigger
    if (gpioSetMode(23, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 23\n");
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Set up GPIO 24 as input for data-ready interrupt
    if (gpioSetMode(24, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 24\n");
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Open the binary log file
    log_file = fopen("mmwave_log.bin", "wb");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Write the magic number to the log file
    if (fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write magic number to log file\n");
        fclose(log_file);
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Write the timestamp to the log file
    uint64_t timestamp = time(NULL);
    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        fclose(log_file);
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Write the configuration to the log file
    config_t config = {
        .start_frequency = 77000000000,
        .end_frequency = 79000000000,
        .num_chirps = 64,
        .num_samples = 256,
        .frame_period = 100000
    };
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        fprintf(stderr, "Failed to write configuration to log file\n");
        fclose(log_file);
        gpio_spi_close(0);
        gpio_cleanup();
        return 1;
    }

    // Set up the signal handler for SIGINT/SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    int frame_number = 0;
    while (1) {
        // Assert the hardware trigger
        gpioWrite(23, 1);

        // Wait for the data-ready interrupt
        while (gpioRead(24) == 0) {
            usleep(1000);
        }

        // Read 32768 bytes of heatmap data via SPI full-duplex transfer
        uint8_t data[32768];
        if (gpio_spi_transfer(0, data, 32768) < 0) {
            fprintf(stderr, "Failed to read heatmap data\n");
            fclose(log_file);
            gpio_spi_close(0);
            gpio_cleanup();
            return 1;
        }

        // Log the frame with a per-frame timestamp and frame number
        uint64_t timestamp = time(NULL);
        if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
            fprintf(stderr, "Failed to write timestamp to log file\n");
            fclose(log_file);
            gpio_spi_close(0);
            gpio_cleanup();
            return 1;
        }
        if (fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1) {
            fprintf(stderr, "Failed to write frame number to log file\n");
            fclose(log_file);
            gpio_spi_close(0);
            gpio_cleanup();
            return 1;
        }
        if (fwrite(data, 32768, 1, log_file) != 1) {
            fprintf(stderr, "Failed to write heatmap data to log file\n");
            fclose(log_file);
            gpio_spi_close(0);
            gpio_cleanup();
            return 1;
        }

        // Increment the frame number
        frame_number++;
    }

    return 0;
}

