#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 20
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL 100000 // 100ms

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    gpiod_close(gpio_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    // Open the GPIO chip
    gpio_fd = gpiod_chip_open(GPIO_CHIP);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Check if the GPIO pin is valid
    if (gpiod_chip_get_line(gpio_fd, GPIO_PIN) < 0) {
        fprintf(stderr, "Invalid GPIO pin: %d\n", GPIO_PIN);
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_chip_close(gpio_fd);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling: %s\n", strerror(errno));
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        return 1;
    }

    // Initialize the GPIO line as an input
    if (gpiod_line_request_output(gpio_fd, GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(gpio_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the current state of the GPIO line
        struct gpiod_line_event event;
        if (gpiod_line_event_read(gpio_fd, GPIO_PIN, &event) < 0) {
            fprintf(stderr, "Failed to read GPIO line event: %s\n", strerror(errno));
            break;
        }

        // Check if the state has changed
        if (event.value != gpiod_line_get_value(gpio_fd, GPIO_PIN)) {
            // Get the current timestamp
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", now_tm);

            // Log the state transition
            fprintf(log_file, "%s: %s\n", timestamp, event.value ? "Flame detected" : "Flame cleared");
            fflush(log_file);

            // Update the current state
            gpiod_line_set_value(gpio_fd, GPIO_PIN, event.value);
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL);
    }

    // Clean up
    gpiod_line_release(gpio_fd, GPIO_PIN);
    gpiod_chip_close(gpio_fd);
    fclose(log_file);
    return 0;
}

