#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x44
#define CONVERSION_TIME 100  // ms
#define FS_RANGE_AUTO 0x01

#define LIGHT_SENSOR_REG_RESULT 0x00
#define LIGHT_SENSOR_REG_CONFIG 0x01

#define LIGHT_SENSOR_CONFIG_CONTINUOUS 0x01
#define LIGHT_SENSOR_CONFIG_FS_AUTO 0x01

#define LIGHT_SENSOR_FS_0_1_LUX 0x00
#define LIGHT_SENSOR_FS_1_LUX 0x01
#define LIGHT_SENSOR_FS_10_LUX 0x02
#define LIGHT_SENSOR_FS_100_LUX 0x03

#define LIGHT_SENSOR_FS_MASK 0x03

#define LIGHT_SENSOR_EXPO_MASK 0xF000
#define LIGHT_SENSOR_MANI_MASK 0x0FFF

#define LIGHT_SENSOR_EXPO_SHIFT 12
#define LIGHT_SENSOR_MANI_SHIFT 0

#define LIGHT_SENSOR_LUX_SCALE 0.01

#define LIGHT_SENSOR_FILE "light_data.txt"

static int i2c_fd = -1;
static int pigpio_fd = -1;

static void cleanup(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (pigpio_fd != -1) {
        gpioTerminate();
        pigpio_fd = -1;
    }
    if (fopen(LIGHT_SENSOR_FILE, "a") != NULL) {
        fclose(fopen(LIGHT_SENSOR_FILE, "a"));
    }
    exit(0);
}

static void read_light_sensor() {
    uint16_t result;
    int retry_count = 0;

    while (retry_count < 5) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl(I2C_SLAVE)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_write(i2c_fd, &LIGHT_SENSOR_REG_CONFIG, 1) < 0) {
            perror("i2c_write(LIGHT_SENSOR_REG_CONFIG)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_write(i2c_fd, &LIGHT_SENSOR_CONFIG_CONTINUOUS, 1) < 0) {
            perror("i2c_write(LIGHT_SENSOR_CONFIG_CONTINUOUS)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_write(i2c_fd, &LIGHT_SENSOR_REG_CONFIG, 1) < 0) {
            perror("i2c_write(LIGHT_SENSOR_REG_CONFIG)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_write(i2c_fd, &LIGHT_SENSOR_CONFIG_FS_AUTO, 1) < 0) {
            perror("i2c_write(LIGHT_SENSOR_CONFIG_FS_AUTO)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_write(i2c_fd, &LIGHT_SENSOR_REG_RESULT, 1) < 0) {
            perror("i2c_write(LIGHT_SENSOR_REG_RESULT)");
            retry_count++;
            usleep(100000);
            continue;
        }

        usleep(CONVERSION_TIME * 1000);

        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
            perror("ioctl(I2C_SLAVE)");
            retry_count++;
            usleep(100000);
            continue;
        }

        if (i2c_read(i2c_fd, &result, 2) < 0) {
            perror("i2c_read(LIGHT_SENSOR_REG_RESULT)");
            retry_count++;
            usleep(100000);
            continue;
        }

        uint8_t exponent = (result >> LIGHT_SENSOR_EXPO_SHIFT) & 0xF;
        uint16_t mantissa = result & LIGHT_SENSOR_MANI_MASK;

        double lux = LIGHT_SENSOR_LUX_SCALE * pow(2, exponent) * mantissa;

        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(fopen(LIGHT_SENSOR_FILE, "a"), "%s %.2f lux\n", timestamp, lux);

        retry_count = 0;
        break;
    }

    if (retry_count >= 5) {
        fprintf(stderr, "Failed to read light sensor after 5 retries\n");
    }
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    if ((pigpio_fd = gpioInitialise()) < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("open(/dev/i2c-" I2C_BUS ")");
        gpioTerminate();
        return 1;
    }

    while (1) {
        read_light_sensor();
        usleep(1000000);
    }

    return 0;
}

