#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <libgpiod.h>

// Define a flag to exit the main loop
volatile sig_atomic_t exit_flag = 0;

// Signal handler to set the exit flag
void sigint_handler(int sig) {
    exit_flag = 1;
}

int main() {
    // Initialize the signal handler for SIGINT
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Open the chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening chip: %s\n", gpiod_strerror(errno));
        return EXIT_FAILURE;
    }

    // Request the line as input with bias pulled up
    struct gpiod_line *line;
    line = gpiod_chip_request_line(chip, 17, GPIOD_LINE_ACTIVE_LOW);
    if (!line) {
        fprintf(stderr, "Error requesting line: %s\n", gpiod_strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the line as input with bias pulled up
    struct gpiod_line_config config = GPIOD_LINE_CONFIG_INPUT | GPIOD_LINE_CONFIG_BIAS_PULL_UP;
    if (gpiod_line_config(line, &config) == -1) {
        fprintf(stderr, "Error configuring line: %s\n", gpiod_strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the line settings
    struct gpiod_line_settings settings;
    if (gpiod_line_settings(line, &settings) == -1) {
        fprintf(stderr, "Error getting line settings: %s\n", gpiod_strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!exit_flag) {
        // Get the current value of the line
        int value;
        if (gpiod_line_request_get_value(line, &value) == -1) {
            fprintf(stderr, "Error getting line value: %s\n", gpiod_strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Log the flame detection status
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);
        if (value == 0) {
            fprintf(stdout, "%s Flame Detected: YES\n", timestamp);
        } else {
            fprintf(stdout, "%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Release the line request
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    // Free the config and settings objects
    gpiod_line_config_free(&config);
    gpiod_line_settings_free(&settings);

    return EXIT_SUCCESS;
}

