// Function to handle signal to exit cleanly
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    // Set GPIO modes
    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 mode\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(18, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 18 mode\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(27, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 mode\n");
        gpioTerminate();
        exit(1);
    }

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        // Read GPIO values
        int left = gpioRead(17);
        int center = gpioRead(18);
        int right = gpioRead(27);

        // Print GPIO values
        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        // Wait 50 ms
        usleep(50000);
    }

    // Clean up on exit
    gpioTerminate();
    return 0;
}

