#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Define GPIO pins for TTP226
    int gpio_pins[] = {2, 3, 4, 17, 23, 24, 25, 8};

    // Configure each GPIO as input with a pull-down resistor
    for (int i = 0; i < 8; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO%d mode to input\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set GPIO%d pull-up/down resistor\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Sampling loop
    while (1) {
        // Poll and log the state of all 8 channels
        for (int i = 0; i < 8; i++) {
            int state = gpioRead(gpio_pins[i]);
            printf("%d", state);
            if (i < 7) {
                printf(" ");
            }
        }
        printf("]\n");

        // Print timestamp
        printf("[%d ms]\n", (int) (gpioMicrosecond() / 1000));

        // Delay for 100 ms
        gpioDelay(100000);
    }

    // Clean up on exit
    gpioTerminate();
    return 0;
}

