#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle SIGINT (Ctrl+C) signal
void sigint_handler(int sig) {
    // Release GPIO resources
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Set GPIO 4 and 5 as inputs with pull-up resistors
    if (gpioSetMode(4, PI_INPUT) < 0 || gpioSetMode(5, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set pull-up resistors for GPIO 4 and 5
    if (gpioSetPullUpDnControl(4, PI_PUD_UP) < 0 || gpioSetPullUpDnControl(5, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up/down control\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of GPIO 4 and 5
        int state4 = gpioRead(4);
        int state5 = gpioRead(5);

        // Log the state of each sensor
        printf("Sensor 1: %s, Sensor 2: %s\n", state4 == 0 ? "LOW" : "HIGH", state5 == 0 ? "LOW" : "HIGH");

        // Wait 500 ms
        usleep(500000);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

