#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod/libgpiod.h>

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip);
    gpiod_line_release_all(gpiod_lines);
    exit(0);
}

int main() {
    // Install SIGINT handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip *gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request lines
    gpiod_line *gpiod_lines[8];
    for (int i = 0; i < 8; i++) {
        gpiod_lines[i] = gpiod_line_request(gpiod_chip, i + 2, "input", GPIOD_LINE_ACTIVE_STATE_HIGH, GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH);
        if (!gpiod_lines[i]) {
            gpiod_chip_close(gpiod_chip);
            perror("gpiod_line_request");
            return 1;
        }
    }

    // Set up logging
    char timestamp[32];
    time_t now;
    struct tm *lt;
    while (1) {
        // Get current time
        time(&now);
        lt = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", lt);

        // Read lines
        for (int i = 0; i < 8; i++) {
            int value = gpiod_line_get_value(gpiod_lines[i]);
            if (value == -1) {
                gpiod_chip_close(gpiod_chip);
                gpiod_line_release_all(gpiod_lines);
                perror("gpiod_line_get_value");
                return 1;
            }
            printf("%s,%d", timestamp, value);
        }
        printf("\n");

        // Sleep for 50 ms
        usleep(50000);
    }

    // Release resources
    gpiod_line_release_all(gpiod_lines);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

