#include <pigpio.h>

// Function to handle SIGINT (Ctrl+C) signal
void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        exit(1);
    }

    // Set up GPIO 4 as a digital input with internal pull-up resistor
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO 4 as input\n");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(4, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable internal pull-up resistor on GPIO 4\n");
        gpioTerminate();
        exit(1);
    }

    // Poll the sensor every 100 ms
    while (1) {
        // Read the current state of the sensor
        int state = gpioRead(4);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO 4\n");
            gpioTerminate();
            exit(1);
        }

        // Validate the read result
        if (state != 0 && state != 1) {
            fprintf(stderr, "Invalid read result from GPIO 4: %d\n", state);
            gpioTerminate();
            exit(1);
        }

        // Log a message based on the sensor state
        char *message = state == 0 ? "Tilted" : "Not Tilted";
        fprintf(stdout, "%s at %s\n", message, ctime(&time(NULL));
        fflush(stdout);

        // Wait 100 ms before polling again
        usleep(100000);
    }

    // This path is unreachable due to the infinite loop above
    return 0;
}

