#define ALS_FORCE_REG 0x06
#define CSV_FILE "uv_als_log.csv"

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Release resources and exit cleanly
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open I2C bus
    int i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor's PART ID
    uint8_t part_id;
    if (i2cWriteReg8(i2c_fd, 0x00, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PART ID register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (i2cReadReg8(i2c_fd, 0x00, &part_id) < 0) {
        fprintf(stderr, "Failed to read PART ID register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART ID: 0x%02x\n", part_id);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write 0x17 to HW_KEY register
    if (i2cWriteReg8(i2c_fd, HW_KEY_REG, 0x17) < 0) {
        fprintf(stderr, "Failed to write to HW_KEY register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure CHLIST register
    if (i2cWriteReg8(i2c_fd, CHLIST_REG, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CHLIST register\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Trigger measurements
    if (i2cWriteReg8(i2c_fd, ALS_FORCE_REG, 0x06) < 0) {
        fprintf(stderr, "Failed to trigger measurements\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        fclose(csv_file);
        gpioClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read UV index and Visible ALS data
        uint16_t uv_index;
        uint16_t als_visible;
        if (i2cReadReg16(i2c_fd, UV_INDEX_REG, &uv_index) < 0) {
            fprintf(stderr, "Failed to read UV index\n");
            break;
        }
        if (i2cReadReg16(i2c_fd, ALS_VIS_REG, &als_visible) < 0) {
            fprintf(stderr, "Failed to read Visible ALS data\n");
            break;
        }

        // Log data to CSV file
        fprintf(csv_file, "%lu,%.2f,%.2f\n", time(NULL), (double)uv_index / 100.0, (double)als_visible / 100.0);

        // Print data to console
        printf("UV Index: %.2f, Visible ALS: %.2f\n", (double)uv_index / 100.0, (double)als_visible / 100.0);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    fclose(csv_file);
    gpioClose(i2c_fd);
    gpioTerminate();

    return 0;
}
