#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR_0 0x36
#define I2C_ADDR_1 0x37
#define GPIO_ALARM 17
#define LOG_FILE "flow_log.txt"
#define SCALE_FACTOR 0.036
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Function to calculate 8-bit CRC
uint8_t sensirion_crc(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Open I2C bus
    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open GPIO lines
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }
    line = gpiod_chip_get_line(chip, GPIO_ALARM);
    if (!line) {
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO line as output
    gpiod_line_request_output(line, 0);
    gpiod_line_set_value(line, 0);

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read from first sensor
        uint8_t data[9];
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR_0) < 0) {
            perror("Failed to set I2C slave address");
            continue;
        }
        if (read(i2c_fd, data, 9) != 9) {
            perror("Failed to read from I2C");
            continue;
        }
        if (data[0] != 0x00 || sensirion_crc(data, 8) != data[8]) {
            fprintf(stderr, "CRC failure on sensor 0\n");
            continue;
        }
        int16_t flow = (data[1] << 8) | data[2];
        if (flow & 0x8000) {
            flow -= 0x10000;
        }
        flow *= SCALE_FACTOR;

        // Read from second sensor
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR_1) < 0) {
            perror("Failed to set I2C slave address");
            continue;
        }
        if (read(i2c_fd, data, 9) != 9) {
            perror("Failed to read from I2C");
            continue;
        }
        if (data[0] != 0x00 || sensirion_crc(data, 8) != data[8]) {
            fprintf(stderr, "CRC failure on sensor 1\n");
            continue;
        }
        int16_t flow2 = (data[1] << 8) | data[2];
        if (flow2 & 0x8000) {
            flow2 -= 0x10000;
        }
        flow2 *= SCALE_FACTOR;

        // Calculate average flow rate
        double avg_flow = (flow + flow2) / 2.0;

        // Log flow rate
        fprintf(log_file, "%.3f\n", avg_flow);

        // Drive alarm
        gpiod_line_set_value(line, avg_flow < 0.5);
        usleep(1000000);

        // Release resources
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        fclose(log_file);
        exit(0);
    }

    // Clean shutdown on SIGINT/SIGTERM
    signal(SIGINT, SIG_IGN);
    signal(SIGTERM, SIG_IGN);
    return 0;
}

