#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUFFER_SIZE 100
#define POLL_INTERVAL 50  // ms

// Structure to hold a single entry in the circular buffer
typedef struct {
    uint32_t timestamp;
    int reading;
} BufferEntry;

// Circular buffer
BufferEntry buffer[BUFFER_SIZE];
int bufferHead = 0;
int bufferTail = 0;

// Function to print the buffer contents
void printBuffer() {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        BufferEntry* entry = &buffer[(bufferHead + i) % BUFFER_SIZE];
        char timestampStr[20];
        strftime(timestampStr, sizeof(timestampStr), "%Y-%m-%d %H:%M:%S", localtime(&entry->timestamp));
        printf("%s: %d\n", timestampStr, entry->reading);
    }
}

// Signal handler for SIGINT
void sigintHandler(int sig) {
    printBuffer();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigintHandler);

    // Configure GPIO 4 as input with internal pull-up resistor
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 4 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(4, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable internal pull-up resistor on GPIO 4\n");
        gpioTerminate();
        return 1;
    }

    // Initialize timestamp
    time_t timestamp = time(NULL);

    while (1) {
        // Poll GPIO 4
        int reading = gpioRead(4);
        if (reading == 0) {
            // Record detection
            buffer[bufferTail].timestamp = timestamp;
            buffer[bufferTail].reading = reading;
            bufferTail = (bufferTail + 1) % BUFFER_SIZE;
            if (bufferTail == bufferHead) {
                // Buffer is full, overwrite oldest entry
                bufferHead = (bufferHead + 1) % BUFFER_SIZE;
            }
            // Print alert
            printf("Obstacle detected!\n");
        }

        // Update timestamp
        timestamp = time(NULL);

        // Sleep for POLL_INTERVAL ms
        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

