#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x55
#define SDA_PIN 2
#define SCL_PIN 3
#define MODE_CONTROL 0x1D
#define OPERATING_STATUS 0x1B
#define ACCEL_X_H 0x2A
#define ACCEL_X_L 0x2B
#define ACCEL_Y_H 0x2C
#define ACCEL_Y_L 0x2D
#define ACCEL_Z_H 0x2E
#define ACCEL_Z_L 0x2F
#define SCALE 0.0009765625

int i2c_fd = -1;
FILE *csv_file = NULL;

void sigint_handler(int sig) {
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

int main() {
    struct i2c_adapter adapter;
    struct i2c_msg msg;
    char buffer[2];
    int retry = 0;
    time_t last_status_check = time(NULL);

    // Initialize GPIO pins for I2C
    system("echo 2 > /sys/class/gpio/export");
    system("echo 3 > /sys/class/gpio/export");
    system("echo low > /sys/class/gpio/gpio2/value");
    system("echo low > /sys/class/gpio/gpio3/value");
    system("echo out > /sys/class/gpio/gpio2/direction");
    system("echo out > /sys/class/gpio/gpio3/direction");

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd == -1) {
        perror("Failed to open I2C device");
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open CSV file for append
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        perror("Failed to open CSV file");
        exit(1);
    }

    // Write to MODE_CONTROL register to switch to active mode
    msg.msg_type = I2C_MSG_WRITE;
    msg.addr = I2C_ADDR;
    msg.buf = (uint8_t *)&MODE_CONTROL;
    msg.len = 1;
    while (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1 && errno == EBUSY) {
        usleep(10000);
        retry++;
        if (retry > 10) {
            perror("Failed to set I2C slave address");
            exit(1);
        }
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("Failed to set I2C slave address");
        exit(1);
    }
    if (write(i2c_fd, msg.buf, msg.len) != msg.len) {
        perror("Failed to write to MODE_CONTROL register");
        exit(1);
    }

    // Wait for sensor to become active
    while (1) {
        msg.msg_type = I2C_MSG_READ;
        msg.addr = I2C_ADDR;
        msg.buf = (uint8_t *)&buffer;
        msg.len = 1;
        if (read(i2c_fd, msg.buf, msg.len) != msg.len) {
            perror("Failed to read from OPERATING_STATUS register");
            continue;
        }
        if (buffer[0] & (1 << 0)) {
            break;
        }
        if (time(NULL) - last_status_check > 1) {
            fprintf(stderr, "Sensor did not become active within 1 second\n");
            exit(1);
        }
        usleep(100000);
        last_status_check = time(NULL);
    }

    // Main loop
    while (1) {
        // Read acceleration registers
        msg.msg_type = I2C_MSG_READ;
        msg.addr = I2C_ADDR;
        msg.buf = (uint8_t *)&buffer;
        msg.len = 2;
        while (read(i2c_fd, msg.buf, msg.len) != msg.len) {
            perror("Failed to read from acceleration registers");
            usleep(10000);
        }

        // Convert raw values to g
        int16_t x = (buffer[0] << 8) | buffer[1];
        int16_t y = (buffer[2] << 8) | buffer[3];
        int16_t z = (buffer[4] << 8) | buffer[5];
        double ax = x * SCALE;
        double ay = y * SCALE;
        double az = z * SCALE;

        // Log sample as CSV row
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(csv_file, "%s,%.6f,%.6f,%.6f\n", timestamp, ax, ay, az);

        // Wait 500 ms
        usleep(500000);
    }

    return 0;
}

