#define STALL_CONFIRMATION_TIME 2000  // 2 seconds
#define LOG_FILE "stall_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_stall(const char *timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    char log_entry[256];
    sprintf(log_entry, "%s: Stall detected\n", timestamp);
    if (fputs(log_entry, file) == EOF) {
        perror("fputs");
    }
    fclose(file);
}

int main() {
    int gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpioSetMode(gpio_fd, GPIO_SENSOR1, PI_INPUT);
    gpioSetMode(gpio_fd, GPIO_SENSOR2, PI_INPUT);

    struct timeval last_read[2] = {{0, 0}, {0, 0}};
    bool stall_detected = false;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        int sensor1_value = gpioRead(gpio_fd, GPIO_SENSOR1);
        int sensor2_value = gpioRead(gpio_fd, GPIO_SENSOR2);

        if (sensor1_value == 0 && sensor2_value == 0) {
            if (!stall_detected) {
                gettimeofday(&last_read[0], NULL);
                stall_detected = true;
            }

            if (current_time.tv_sec - last_read[0].tv_sec >= STALL_CONFIRMATION_TIME / 1000) {
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time.tv_sec));
                log_stall(timestamp);
                stall_detected = false;
            }
        } else {
            stall_detected = false;
        }

        usleep(100000);  // 100ms
    }

    gpioTerminate(gpio_fd);
    return 0;
}

