#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x0E
#define DEVICE_ID_REG 0x00
#define DEVICE_ID_EXPECTED 0x8D
#define CSV_FILE "magnetic_log.csv"
#define CSV_HEADER "timestamp,X(mT),Y(mT),Z(mT)\n"
#define CSV_DELIMITER ","
#define CSV_FORMAT "%s,%d,%d,%d\n"
#define SAMPLE_INTERVAL 100000 // 100 ms
#define LSB_SCALE_FACTOR 0.1 // LSB = 0.1 mT for 50 mT range

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", gpioErrorStr(gpioError()));
    }
    if (i2cClose(I2C_BUS) != 0) {
        fprintf(stderr, "Error closing I2C bus: %s\n", i2cErrorStr(i2cError()));
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

void log_data(double timestamp, int16_t x, int16_t y, int16_t z) {
    char buffer[256];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S.%03d", localtime(&timestamp));
    fprintf(log_file, CSV_FORMAT, buffer, x * LSB_SCALE_FACTOR, y * LSB_SCALE_FACTOR, z * LSB_SCALE_FACTOR);
}

int main() {
    int fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", i2cErrorStr(i2cError()));
        return 1;
    }

    if (i2cWriteReg8(fd, DEVICE_ID_REG, DEVICE_ID_EXPECTED) != 0) {
        fprintf(stderr, "Error writing device ID register: %s\n", i2cErrorStr(i2cError()));
        i2cClose(fd);
        return 1;
    }

    if (i2cWriteReg8(fd, 0x01, 0x01) != 0) { // Enable continuous-conversion mode
        fprintf(stderr, "Error enabling continuous-conversion mode: %s\n", i2cErrorStr(i2cError()));
        i2cClose(fd);
        return 1;
    }

    if (i2cWriteReg8(fd, 0x02, 0x07) != 0) { // Enable all three axes
        fprintf(stderr, "Error enabling all three axes: %s\n", i2cErrorStr(i2cError()));
        i2cClose(fd);
        return 1;
    }

    if (i2cWriteReg8(fd, 0x03, 0x01) != 0) { // Set 50 mT range
        fprintf(stderr, "Error setting 50 mT range: %s\n", i2cErrorStr(i2cError()));
        i2cClose(fd);
        return 1;
    }

    FILE *log_file = fopen(CSV_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(fd);
        return 1;
    }

    if (fputs(CSV_HEADER, log_file) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(fd);
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(fd);
        return 1;
    }

    while (running) {
        struct tm timestamp;
        time_t now = time(NULL);
        localtime_r(&now, &timestamp);
        int16_t x, y, z;
        if (i2cReadReg16(fd, 0x04, &x) != 0 || i2cReadReg16(fd, 0x06, &y) != 0 || i2cReadReg16(fd, 0x08, &z) != 0) {
            fprintf(stderr, "Error reading magnetic field values: %s\n", i2cErrorStr(i2cError()));
            continue;
        }
        log_data(mktime(&timestamp), x, y, z);
        usleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

