#define LOG_FILE "flood_log.txt"
#define GPIO_PIN 23
#define POLL_INTERVAL 2000  // milliseconds
#define REINIT_DELAY 60000  // milliseconds

void log_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%s %s\n", timestamp, message);
    fclose(file);
}

void gpio_init() {
    if (gpioInitialise() < 0) {
        log_message("Error initializing pigpio");
        exit(EXIT_FAILURE);
    }
}

void gpio_reinit() {
    log_message("Failed to read GPIO, attempting reinitialization...");
    sleep(REINIT_DELAY / 1000);
    gpio_cleanup();
    gpio_init();
}

int main() {
    gpio_init();

    int pin = gpioOpen(GPIO_PIN);
    if (pin < 0) {
        log_message("Failed to open GPIO pin");
        gpio_cleanup();
        exit(EXIT_FAILURE);
    }

    while (1) {
        int value = gpioRead(pin);
        if (value == 1) {
            log_message("ALERT: Water detected");
            log_message("Water detected");
        }

        sleep(POLL_INTERVAL / 1000);
    }

    gpio_close(pin);
    gpio_cleanup();
    return 0;
}

void cleanup_and_exit(int signal) {
    log_message("Received signal, cleaning up...");
    gpio_close(pin);
    gpio_cleanup();
    exit(EXIT_SUCCESS);
}

int main(int argc, char *argv[]) {
    signal(SIGINT, cleanup_and_exit);
    signal(SIGTERM, cleanup_and_exit);

    return main();
}

