        if (fsync(fd) < 0) {
            fprintf(stderr, "Failed to sync log file: %s\n", strerror(errno));
            break;
        }
        pulses = 0;
        pulse_window = false;
    }

    // Clean up
    close(fd);
    gpioTerminate();

    return 0;
}

