#include <fcntl.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 27
#define ROTATION_LOG_FILE "rotation_log.txt"

// Mutex for protecting shared state
pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared state for quadrature state machine
int state = 0;
int prev_state = 0;

// Function to handle rotation detection
void rotation_detected(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&state_mutex);
    if (level == 1) {
        // Rising edge
        if (state == 0) {
            // Transition from 0 to 1
            state = 1;
        } else if (state == 1) {
            // Transition from 1 to 0
            state = 0;
        }
    } else {
        // Falling edge
        if (state == 1) {
            // Transition from 1 to 0
            state = 0;
        } else if (state == 0) {
            // Transition from 0 to 1
            state = 1;
        }
    }
    pthread_mutex_unlock(&state_mutex);

    // Determine direction of rotation
    if (state == 1 && prev_state == 0) {
        // Clockwise rotation
        fprintf(stderr, "CW rotation detected at %s\n", ctime(&tick));
        pthread_mutex_lock(&state_mutex);
        prev_state = state;
        pthread_mutex_unlock(&state_mutex);
    } else if (state == 0 && prev_state == 1) {
        // Counter-clockwise rotation
        fprintf(stderr, "CCW rotation detected at %s\n", ctime(&tick));
        pthread_mutex_lock(&state_mutex);
        prev_state = state;
        pthread_mutex_unlock(&state_mutex);
    }
}

// Function to log rotation events to file
void log_rotation(int direction) {
    FILE *file = fopen(ROTATION_LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d.%03d %s rotation\n",
            timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday,
            timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec,
            (int) (rawtime % 1000), (direction == 1) ? "CW" : "CCW");
    fclose(file);
}

// Signal handler for SIGINT and SIGTERM
void sigint_handler(int sig) {
    fprintf(stderr, "Received signal %d, shutting down...\n", sig);
    log_rotation(prev_state == 1 ? 1 : 0);
    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO pins
    if (gpioSetMode(GPIO_A, PI_INPUT) < 0 || gpioSetMode(GPIO_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) < 0 || gpioSetPullUpDown(GPIO_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up alert functions for GPIO pins
    if (gpioSetAlertFunc(GPIO_A, rotation_detected) < 0 || gpioSetAlertFunc(GPIO_B, rotation_detected) < 0) {
        fprintf(stderr, "Failed to set alert functions\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Log initial state
    log_rotation(0);

    // Main loop
    while (1) {
        // Wait for signal
        sleep(1);
    }

    return EXIT_SUCCESS;
}

