#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

// Signal handlers for SIGINT and SIGTERM
void sigint_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, shutting down...", sig);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, shutting down...", sig);
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

int main() {
    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open GPIO chip");
        return 1;
    }

    // Request the line for GPIO 23 (physical pin 16)
    line = gpiod_chip_get_line(chip, 23);
    if (line == NULL) {
        syslog(LOG_ERR, "Failed to request line for GPIO 23");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for GPIO 18 (physical pin 12)
    led_line = gpiod_chip_get_line(chip, 18);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to request line for GPIO 18");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the direction of the lines to output and input
    if (gpiod_line_request_output(line, "active-high") < 0) {
        syslog(LOG_ERR, "Failed to set line direction for GPIO 23");
        gpiod_line_release(line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_direction(led_line, "output") < 0) {
        syslog(LOG_ERR, "Failed to set line direction for GPIO 18");
        gpiod_line_release(line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize the syslog
    openlog("tpp223b", LOG_PID | LOG_PERROR, LOG_USER);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the state of the touch sensor
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            syslog(LOG_ERR, "Failed to read line state");
            break;
        }

        // Log the touch event
        syslog(LOG_INFO, "Touch sensor state: %d", state);

        // Turn the LED on if the sensor is touched
        if (state == 1) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
        }

        // Sleep for 50 ms
        usleep(50000);
    }

    // Release the lines and close the chip
    gpiod_line_release(line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    // Close the syslog
    closelog();

    return 0;
}

