        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize the syslog
    openlog("tpp223b", LOG_PID | LOG_PERROR, LOG_USER);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read the state of the touch sensor
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            syslog(LOG_ERR, "Failed to read line state");
            break;
        }

        // Log the touch event
        syslog(LOG_INFO, "Touch sensor state: %d", state);

        // Turn the LED on if the sensor is touched
        if (state == 1) {
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(led_line, 0);
