#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LOG_SIZE 100
#define DEBOUNCE_DELAY 50

// Structure to hold a log entry
typedef struct {
    int sensor;
    int state;
    time_t timestamp;
} LogEntry;

// Global variables
int gpio[2] = {4, 17}; // Sensor GPIOs
int led[2] = {27, 22}; // LED GPIOs
int log[LOG_SIZE];
int logIndex = 0;
int logOverflow = 0;
int logFilled = 0;
int logSize = 0;
int gpioHandle = 0;

// Function to handle log buffer overflow
void logOverflowHandler() {
    logOverflow++;
    logFilled = 0;
}

// Function to log an event
void logEvent(int sensor, int state) {
    if (logFilled >= LOG_SIZE) {
        logOverflowHandler();
    }
    log[logIndex].sensor = sensor;
    log[logIndex].state = state;
    log[logIndex].timestamp = time(NULL);
    logFilled++;
    logIndex = (logIndex + 1) % LOG_SIZE;
}

// Signal handler for SIGINT and SIGTERM
void signalHandler(int sig) {
    gpioWrite(led[0], 0);
    gpioWrite(led[1], 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if ((gpioHandle = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", gpioHandle);
        return 1;
    }

    // Set sensor GPIOs as inputs
    for (int i = 0; i < 2; i++) {
        if (gpioSetMode(gpio[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %d\n", gpio[i], gpioHandle);
            gpioTerminate();
            return 1;
        }
    }

    // Set LED GPIOs as outputs
    for (int i = 0; i < 2; i++) {
        if (gpioSetMode(led[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output: %d\n", led[i], gpioHandle);
            gpioTerminate();
            return 1;
        }
    }

    // Set initial LED states to off
    for (int i = 0; i < 2; i++) {
        gpioWrite(led[i], 0);
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Main loop
    while (1) {
        for (int i = 0; i < 2; i++) {
            int state = gpioRead(gpio[i]);
            if (state == 1) {
                logEvent(gpio[i], 1);
                gpioWrite(led[i], 1);
            } else {
                logEvent(gpio[i], 0);
                gpioWrite(led[i], 0);
            }
        }
        usleep(DEBOUNCE_DELAY * 1000);
    }

    // Print log buffer contents and overflow count on exit
    for (int i = 0; i < LOG_SIZE; i++) {
        if (log[i].timestamp != 0) {
            printf("%d %d %ld\n", log[i].sensor, log[i].state, log[i].timestamp);
        }
    }
    printf("Overflow count: %d\n", logOverflow);

    return 0;
}

