    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(17, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set internal pull-up resistor on GPIO 17\n");
        gpioTerminate();
        return 1;
    }

