        fprintf(stderr, "Failed to set up signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the state of GPIO 17
        int state = gpioRead(17);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO 17\n");
            break;
        }

        // Check for state transition
        if (state == 0) {
            // Rain detected
            fprintf(log_file, "%lu: Rain Detected\n", time(NULL));
        } else {
            // No rain
            fprintf(log_file, "%lu: No Rain\n", time(NULL));
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close the log file and release pigpio resources
    fclose(log_file);
    gpioTerminate();

    return 0;
