#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define DEBOUNCE_TIME 5000  // 5 ms debounce time in microseconds
#define PULSES_PER_REV 2
#define LOG_FILE "shaft_log.txt"

volatile bool running = true;
uint64_t last_timestamp = 0;
uint64_t last_state[2] = {0, 0};
uint64_t pulse_count = 0;
uint64_t last_pulse_time[2] = {0, 0};

void sigint_handler(int sig) {
    running = false;
}

void log_state(uint64_t timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(file, "%llu,%u,%u\n", timestamp, last_state[0], last_state[1]);
    fclose(file);
}

void update_state(uint64_t timestamp, uint8_t state[2]) {
    if (state[0] != last_state[0] || state[1] != last_state[1]) {
        pulse_count++;
        last_state[0] = state[0];
        last_state[1] = state[1];
        log_state(timestamp);
    }

    if (pulse_count >= PULSES_PER_REV) {
        uint64_t time_diff = timestamp - last_timestamp;
        uint64_t rpm = (pulse_count * 60 * 1000000) / (time_diff * PULSES_PER_REV);
        printf("RPM: %llu\n", rpm);
        pulse_count = 0;
        last_timestamp = timestamp;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        uint8_t state[2] = {0, 0};
        uint64_t timestamp = gpioTimestamp();

        if (gpioRead(GPIO_SENSOR1) == 1) {
            state[0] = 1;
        }

        if (gpioRead(GPIO_SENSOR2) == 1) {
            state[1] = 1;
        }

        if (timestamp - last_pulse_time[0] > DEBOUNCE_TIME) {
            last_pulse_time[0] = timestamp;
        }

