        fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, hr, spo2);
        fflush(log_file);

        // Sleep for 1 second
        sleep(1);
    }

    // Close log file and I2C handle on exit
    fclose(log_file);
    close_i2c(I2C_BUS);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

