#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define GPIO_ALARM 27
#define LOG_FILE "bridge_integrity.log"
#define POLL_INTERVAL 100  // ms
#define TILT_THRESHOLD 2000  // ms

bool alarm_active = false;
bool sensor1_tilted = false;
bool sensor2_tilted = false;
time_t last_tilt_time = 0;
time_t last_threshold_exceeded_time = 0;

void log_event(const char *event) {
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&now));
    fprintf(stderr, "%s %s\n", timestamp, event);
    fprintf(stderr, "Sensor 1: %s, Sensor 2: %s\n", sensor1_tilted ? "Tilted" : "Not tilted", sensor2_tilted ? "Tilted" : "Not tilted");
    fflush(stderr);
}

void sigint_handler(int sig) {
    log_event("SIGINT received, shutting down");
    gpioWrite(GPIO_ALARM, 0);
    fclose(stderr);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    log_event("SIGTERM received, shutting down");
    gpioWrite(GPIO_ALARM, 0);
    fclose(stderr);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    if (fopen(LOG_FILE, "a") == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    gpioSetMode(GPIO_SENSOR1, PI_INPUT);
    gpioSetPullUpDnControl(GPIO_SENSOR1, PI_PUD_DOWN);
    gpioSetMode(GPIO_SENSOR2, PI_INPUT);
    gpioSetPullUpDnControl(GPIO_SENSOR2, PI_PUD_DOWN);
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0);

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        int sensor1_value = gpioRead(GPIO_SENSOR1);
        int sensor2_value = gpioRead(GPIO_SENSOR2);

        if (sensor1_value == 1 && !sensor1_tilted) {
            log_event("Sensor 1 tilted");
            sensor1_tilted = true;
            last_tilt_time = time(NULL);
        } else if (sensor1_value == 0 && sensor1_tilted) {
            log_event("Sensor 1 not tilted");
            sensor1_tilted = false;
        }

        if (sensor2_value == 1 && !sensor2_tilted) {
            log_event("Sensor 2 tilted");
            sensor2_tilted = true;
            last_tilt_time = time(NULL);
        } else if (sensor2_value == 0 && sensor2_tilted) {
            log_event("Sensor 2 not tilted");
            sensor2_tilted = false;
        }

        if (sensor1_tilted && sensor2_tilted) {
            if (time(NULL) - last_tilt_time > TILT_THRESHOLD) {
                log_event("Threshold exceeded");
                if (!alarm_active) {
                    gpioWrite(GPIO_ALARM, 1);
                    alarm_active = true;
                }
            }
        } else {
            if (alarm_active) {
                log_event("Threshold not exceeded");
                gpioWrite(GPIO_ALARM, 0);
                alarm_active = false;
            }
        }

        if (time(NULL) - last_threshold_exceeded_time > TILT_THRESHOLD) {
            last_threshold_exceeded_time = 0;
        }

        gpioDelay(POLL_INTERVAL);
    }

    return 0;
}

