#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SEISMIC_SENSOR_ADDRESS 0x1D
#define SEISMIC_SENSOR_CTRL1 0x1F
#define SEISMIC_SENSOR_X 0x28
#define SEISMIC_SENSOR_Y 0x2A
#define SEISMIC_SENSOR_Z 0x2C
#define SEISMIC_SENSOR_THRESHOLD 500
#define SEISMIC_SENSOR_LED_PIN 17
#define SEISMIC_SENSOR_LOG_FILE "seismic_events.log"

#define MAX_RETRIES 3

int gpi = 0;
int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (gpi != 0) {
        gpioTerminate();
    }
}

void sigint_handler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    if ((gpi = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        exit(1);
    }

    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) == -1) {
        perror("open");
        cleanup();
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SEISMIC_SENSOR_ADDRESS) == -1) {
        perror("ioctl");
        cleanup();
        exit(1);
    }

    // Verify sensor presence and clear power-down bit in CTRL1
    uint8_t ctrl1;
    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (i2c_smbus_read_byte_data(i2c_fd, SEISMIC_SENSOR_CTRL1) == -1) {
            perror("i2c_smbus_read_byte_data");
            cleanup();
            exit(1);
        }
        ctrl1 = i2c_smbus_read_byte_data(i2c_fd, SEISMIC_SENSOR_CTRL1);
        if ((ctrl1 & 0x01) == 0) {
            break;
        }
        usleep(100000); // 100ms
    }
    if ((ctrl1 & 0x01) != 0) {
        fprintf(stderr, "Sensor not present or failed to clear power-down bit\n");
        cleanup();
        exit(1);
    }

    // Set up logging
    struct tm *timeinfo;
    time_t rawtime;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    log_file = fopen(SEISMIC_SENSOR_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        cleanup();
        exit(1);
    }

    while (1) {
        // Read 3-axis acceleration registers
        uint8_t data[6];
        for (int retry = 0; retry < MAX_RETRIES; retry++) {
            if (i2c_smbus_read_i2c_block_data(i2c_fd, SEISMIC_SENSOR_X, 6, data) == -1) {
                perror("i2c_smbus_read_i2c_block_data");
                cleanup();
                exit(1);
            }
            if (data[0] == 0x00 && data[1] == 0x00 && data[2] == 0x00 && data[3] == 0x00 && data[4] == 0x00 && data[5] == 0x00) {
                // Sensor not present
                usleep(100000); // 100ms
                continue;
            }
            break;
        }
        if (data[0] == 0x00 && data[1] == 0x00 && data[2] == 0x00 && data[3] == 0x00 && data[4] == 0x00 && data[5] == 0x00) {
            // Sensor not present
            continue;
        }

        // Compute Euclidean vibration magnitude
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        int magnitude = (int)sqrt((double)x * x + (double)y * y + (double)z * z);

        // Check if vibration exceeds threshold
        if (magnitude > SEISMIC_SENSOR_THRESHOLD) {
            // Log event
            fprintf(log_file, "%s: %d\n", timestamp, magnitude);
            fclose(log_file);
            log_file = fopen(SEISMIC_SENSOR_LOG_FILE, "a");
            if (log_file == NULL) {
                perror("fopen");
                cleanup();
                exit(1);
            }

            // Turn on LED
            if (gpioWrite(SEISMIC_SENSOR_LED_PIN, 1) < 0) {
                perror("gpioWrite");
                cleanup();
                exit(1);
            }

            // Wait for 1 second
            usleep(1000000);

            // Turn off LED
            if (gpioWrite(SEISMIC_SENSOR_LED_PIN, 0) < 0) {
                perror("gpioWrite");
                cleanup();
                exit(1);
            }
        }

        // Wait for 100ms
        usleep(100000);
    }

    cleanup();
    return 0;
}

