#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <gpiod.h>

#define LOG_FACILITY LOG_USER
#define LOG_IDENT "flame_monitor"
#define LOG_LEVEL LOG_INFO

#define NUM_SENSORS 5
#define DEBOUNCE_MS 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t exit_flag = 0;

struct gpiod_line *lines[NUM_SENSORS];

void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    int chip = gpiod_chip_open("gpiochip0");
    if (chip < 0) {
        syslog(LOG_ERR, "Failed to open chip: %s", gpiod_error_str(errno));
        closelog();
        exit(1);
    }

    syslog(LOG_INFO, "Flame monitor started");

    struct gpiod_line_request req;
    memset(&req, 0, sizeof(req));
    req.consumer = "flame_monitor";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.direction = GPIOD_LINE_REQUEST_DIRECTION_OUT_HIGH;

    for (int i = 0; i < NUM_SENSORS; i++) {
        int pin = (i == 0) ? 2 : (i == 1) ? 3 : (i == 2) ? 4 : (i == 3) ? 17 : 27;
        lines[i] = gpiod_chip_get_line(chip, pin);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "Failed to get line %d: %s", pin, gpiod_error_str(errno));
            continue;
        }

        if (gpiod_line_request(lines[i], &req) < 0) {
            syslog(LOG_ERR, "Failed to request line %d: %s", pin, gpiod_error_str(errno));
            gpiod_line_release(lines[i]);
            continue;
        }

        if (gpiod_line_direction(lines[i], GPIOD_LINE_DIRECTION_OUT_HIGH) < 0) {
            syslog(LOG_ERR, "Failed to set direction of line %d: %s", pin, gpiod_error_str(errno));
            gpiod_line_release(lines[i]);
            continue;
        }
    }

    struct tm *now;
    time_t t;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        for (int i = 0; i < NUM_SENSORS; i++) {
            gpiod_line_release(lines[i]);
        }
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    flock(fileno(log_file), LOCK_EX);

    while (!exit_flag) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int pin = (i == 0) ? 2 : (i == 1) ? 3 : (i == 2) ? 4 : (i == 3) ? 17 : 27;
            int value = gpiod_line_get_value(lines[i]);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read line %d: %s", pin, gpiod_error_str(errno));
                continue;
            }

            if (value == 0) {
                struct gpiod_line_request req;
                memset(&req, 0, sizeof(req));
                req.consumer = "flame_monitor";
                req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
                req.direction = GPIOD_LINE_REQUEST_DIRECTION_OUT_HIGH;

                if (gpiod_line_request(lines[i], &req) < 0) {
                    syslog(LOG_ERR, "Failed to request line %d: %s", pin, gpiod_error_str(errno));
                    continue;
                }

                struct timespec debounce;
                debounce.tv_sec = 0;
                debounce.tv_nsec = DEBOUNCE_MS * 1000000;
                nanosleep(&debounce);

                int value2 = gpiod_line_get_value(lines[i]);
                if (value2 < 0) {
                    syslog(LOG_ERR, "Failed to read line %d after debounce: %s", pin, gpiod_error_str(errno));
                    continue;
                }

                if (value2 == 0) {
                    time(&t);
                    now = localtime(&t);
                    char buffer[32];
                    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S%z", now);
                    fprintf(log_file, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", buffer, i, pin);
                    fflush(log_file);
                }
            }
        }

        sleep(1);
    }

    flock(fileno(log_file), LOCK_UN);
    fclose(log_file);

    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }

    gpiod_chip_close(chip);
    closelog();

    return 0;
}

void cleanup() {
    exit_flag = 1;
    for (int i = 0; i < NUM_SENSORS; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
    closelog();
    exit(0);
}

int main() {
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    openlog(LOG_IDENT, LOG_PID, LOG_FACILITY);

    atexit(cleanup);

    return main();
}

