int main() {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open GPIO chip
    int chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == -1) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Get line numbers for OUT0-OUT7
    int line_numbers[] = {5, 6, 13, 19, 26, 12, 16, 20};
    int num_lines = sizeof(line_numbers) / sizeof(line_numbers[0]);

    // Open lines in active-high mode
    struct gpiod_line **lines = malloc(num_lines * sizeof(struct gpiod_line *));
    for (int i = 0; i < num_lines; i++) {
        lines[i] = gpiod_chip_get_line(chip, line_numbers[i]);
        if (lines[i] == NULL) {
            perror("gpiod_chip_get_line");
            gpiod_chip_close(chip);
            free(lines);
            exit(1);
        }
        if (gpiod_line_request_output(lines[i], "active-high") == -1) {
            perror("gpiod_line_request_output");
            gpiod_chip_close(chip);
            free(lines);
            exit(1);
        }
    }

    // Create a bulk line request
    struct gpiod_line_bulk bulk;
    if (gpiod_line_bulk_new(&bulk, lines, num_lines) == -1) {
        perror("gpiod_line_bulk_new");
        gpiod_chip_close(chip);
        free(lines);
        exit(1);
    }

    // Main loop
    while (1) {
        // Read all lines in the bulk request
        struct gpiod_line_event *events;
        int num_events;
        if (gpiod_line_bulk_read(&bulk, &events, &num_events) == -1) {
            perror("gpiod_line_bulk_read");
            gpiod_chip_close(chip);
            free(lines);
            free(events);
            exit(1);
        }

        // Process events
        for (int i = 0; i < num_events; i++) {
            struct gpiod_line_event *event = &events[i];
            if (event->value == GPIOD_LINE_EVENT_VALUE_HIGH) {
                // Touch detected
                printf("%s T%d-%d\n", iso8601_time(), event->line->number, event->line->consumer->consumer_name);
            } else if (event->value == GPIOD_LINE_EVENT_VALUE_LOW) {
                // Touch released
                printf("%s T%d-%d\n", iso8601_time(), event->line->number, event->line->consumer->consumer_name);
            }
        }

        // Free events
        free(events);

        // Sleep for 50 milliseconds
        usleep(50000);
    }

    // Clean up
    gpiod_line_bulk_free(&bulk);
    gpiod_chip_close(chip);
    free(lines);
    return 0;
}

