#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define LOG_FILE "grow_log.txt"
#define I2C_BUS 1
#define I2C_ADDR 0x10
#define ALS_GAIN 0x00
#define ALS_INT_TIME 0x00
#define ALS_REG 0x04
#define LED_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 100

// Adaptive brightness logic
#define BRIGHTNESS_THRESHOLD_100 100
#define BRIGHTNESS_THRESHOLD_500 500
#define BRIGHTNESS_THRESHOLD_1000 1000

// Signal handler for SIGINT/SIGTERM
void sig_handler(int sig) {
    // Turn off the LED
    gpioHardwarePWM(LED_GPIO, 0);
    // Close the log file
    fclose(log_file);
    // Close the I2C bus
    i2c_close(i2c_bus);
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Open the I2C bus
    i2c_bus = i2cOpen(I2C_BUS, I2C_ADDR);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    uint16_t config = (ALS_GAIN << 8) | ALS_INT_TIME;
    if (i2cWriteReg8(i2c_bus, 0x00, config) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        i2c_close(i2c_bus);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up the signal handler
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Set up the LED PWM
    gpioHardwarePWM(LED_GPIO, 100);

    // Main loop
    while (1) {
        // Read ALS register
        uint16_t raw = i2cReadReg16(i2c_bus, ALS_REG);
        if (raw < 0) {
            fprintf(stderr, "Failed to read ALS register\n");
            i2c_close(i2c_bus);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Convert to lux
        double lux = raw * 0.0576;

        // Calculate brightness
        int brightness;
        if (lux < BRIGHTNESS_THRESHOLD_100) {
            brightness = PWM_RANGE;
        } else if (lux < BRIGHTNESS_THRESHOLD_500) {
            brightness = (int)(PWM_RANGE * 0.75);
        } else if (lux < BRIGHTNESS_THRESHOLD_1000) {
            brightness = (int)(PWM_RANGE * 0.5);
        } else {
            brightness = (int)(PWM_RANGE * 0.25);
        }

        // Log the sample
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%d,0\n", timestamp, lux, brightness);
        fflush(log_file);

        // Update the LED PWM
        gpioHardwarePWM(LED_GPIO, brightness);

        // Sleep for 1 second
        usleep(1000000);
    }

    return 0;
}

// Global variables
FILE *log_file;
int i2c_bus;

