#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_LOG_FILE "touch_log.txt"
#define TOUCH_DEBOUNCE_TIME 200  // ms
#define TOUCH_POLL_INTERVAL 50  // ms

// Signal handler to clean up on exit
void sig_handler(int sig) {
    gpioWrite(17, 0);  // Turn off the LED
    gpioTerminate();  // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO 2-9 as inputs with pull-down resistors
    for (int i = 2; i <= 9; i++) {
        if (gpioSetMode(i, PI_INPUT) < 0 || gpioSetPullUpDnControl(i, PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to configure GPIO %d\n", i);
            gpioTerminate();
            return 1;
        }
    }

    // Configure GPIO 17 as an output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to configure GPIO 17\n");
        gpioTerminate();
        return 1;
    }

    // Open the touch log file
    FILE *touch_log = fopen(TOUCH_LOG_FILE, "a");
    if (!touch_log) {
        fprintf(stderr, "Failed to open touch log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the last touch state
    bool last_touch_state[8] = {false};

    // Main loop
    while (1) {
        // Poll the inputs
        for (int i = 2; i <= 9; i++) {
            int state = gpioRead(i);
            if (state == 1 && !last_touch_state[i - 2]) {
                // New touch detected, log it
                time_t now = time(NULL);
                struct tm *now_tm = localtime(&now);
                char timestamp[20];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
                fprintf(touch_log, "%s - Channel %d Touched\n", timestamp, i - 1);
                fflush(touch_log);
                // Turn on the LED
                gpioWrite(17, 1);
            } else if (state == 0 && last_touch_state[i - 2]) {
                // Touch released, turn off the LED if all channels are released
                bool all_released = true;
                for (int j = 2; j <= 9; j++) {
                    if (gpioRead(j) == 1) {
                        all_released = false;
                        break;
                    }
                }
                if (all_released) {
                    gpioWrite(17, 0);
                }
            }
            last_touch_state[i - 2] = state;
        }

        // Sleep for a bit
        usleep(TOUCH_POLL_INTERVAL * 1000);
    }

    // Clean up
    fclose(touch_log);
    gpioTerminate();
    return 0;
}

