    config_word = htobe16(CONFIG_WORD);
    if (i2cWriteWordData(i2c_fd, CONFIG_REGISTER, &config_word) < 0) {
        fprintf(stderr, "Failed to write configuration word\n");
        i2cClose(i2c_fd);
        return 1;
    }

