    result_word = be16toh(result_word);

    // Extract exponent and mantissa
    exponent = (result_word >> 12) & 0x0F;
    mantissa = result_word & 0x0FFF;

    // Compute lux value
    lux = mantissa * 0.01 * (1 << exponent);

    // Log reading to file
    strftime(log_buffer, sizeof(log_buffer), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
    sprintf(log_buffer + strlen(log_buffer), ", %.2f", lux);
    FILE *log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        return 1;
    }
    fprintf(log_file, "%s\n", log_buffer);
    fclose(log_file);

    // Print lux value to stdout
    printf("%.2f\n", lux);

    while (running) {
        // Wait for conversion to complete
        usleep(CONVERSION_TIME * 1000);

        // Read result register
        if (i2cReadWordData(i2c_fd, RESULT_REGISTER, &result_word) < 0) {
