// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    // Signal-safe cleanup
    close_log_file();
    gpioTerminate();
    exit(0);
}

// Function to close the log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Function to open the log file in append mode
FILE* open_log_file() {
    log_file = fopen("fire_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        exit(1);
    }
    return log_file;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", gpioErrorStr(gpioInitialise()));
        exit(1);
    }

    // Set up signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, sigint_handler);

    // Open the log file
    log_file = open_log_file();

    // Set up GPIO 17 as output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting up GPIO 17: %s\n", gpioErrorStr(gpioSetMode(17, PI_OUTPUT)));
        close_log_file();
        gpioTerminate();
        exit(1);
    }

    // Set up GPIO 4 as input
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting up GPIO 4: %s\n", gpioErrorStr(gpioSetMode(4, PI_INPUT)));
        close_log_file();
        gpioTerminate();
        exit(1);
    }

    // Main loop
    while (1) {
        // Read the state of GPIO 4
        int state = gpioRead(4);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO 4: %s\n", gpioErrorStr(gpioRead(4)));
            continue;
        }

        // Log the reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s: GPIO 4: %d\n", timestamp, state);

        // Trigger an alert if a flame is detected
        if (state == 0) {
            // Set GPIO 17 HIGH for 1 second
            if (gpioWrite(17, 1) < 0) {
                fprintf(stderr, "Error setting GPIO 17 HIGH: %s\n", gpioErrorStr(gpioWrite(17, 1)));
            }
            sleep(1);
            if (gpioWrite(17, 0) < 0) {
                fprintf(stderr, "Error setting GPIO 17 LOW: %s\n", gpioErrorStr(gpioWrite(17, 0)));
            }
        }

        // Sleep for 500 milliseconds
        usleep(500000);
    }

    // Clean up on exit
    close_log_file();
    gpioTerminate();

    return 0;
}

