#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_NAME "gpio4"
#define DEBOUNCE_INTERVAL_US 50000
#define LOG_FILE "touch_log.txt"

static volatile bool running = true;
static gpiod_line_t line;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    gpiod_chip_t *chip;
    if ((chip = gpiod_chip_open(GPIO_CHIP_NAME)) == NULL) {
        fprintf(stderr, "Failed to open GPIO chip '%s'\n", GPIO_CHIP_NAME);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(chip, GPIO_LINE_NAME, 0);
    if (gpiod_line_direction(chip, GPIO_LINE_NAME, GPIOD_LINE_DIRECTION_INPUT) == -1) {
        fprintf(stderr, "Failed to set direction of line '%s'\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_edge(chip, GPIO_LINE_NAME, GPIOD_LINE_EVENT_BOTH);
    if (gpiod_line_edge_trigger(chip, GPIO_LINE_NAME, GPIOD_LINE_EDGE_RISING) == -1) {
        fprintf(stderr, "Failed to set edge trigger for line '%s'\n", GPIO_LINE_NAME);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpiod_chip_close(chip);
        gpiod_line_release(chip, GPIO_LINE_NAME);
        exit(EXIT_FAILURE);
    }

    struct timespec debounce_interval;
    debounce_interval.tv_sec = DEBOUNCE_INTERVAL_US / 1000000;
    debounce_interval.tv_nsec = (DEBOUNCE_INTERVAL_US % 1000000) * 1000;

    while (running) {
        gpiod_line_event_t event;
        if (gpiod_line_event_read(chip, GPIO_LINE_NAME, &event, &debounce_interval) == -1) {
            fprintf(stderr, "Failed to read event from line '%s'\n", GPIO_LINE_NAME);
            break;
        }

        if (event.event == GPIOD_LINE_EVENT_RISING) {
            fprintf(log_file, "%s: Touch Detected\n", ctime_r(&event.timestamp, NULL));
        } else if (event.event == GPIOD_LINE_EVENT_FALLING) {
            fprintf(log_file, "%s: Touch Released\n", ctime_r(&event.timestamp, NULL));
        }

        if (fflush(log_file) == EOF) {
            fprintf(stderr, "Failed to flush log file\n");
            break;
        }
    }

    gpiod_line_release(chip, GPIO_LINE_NAME);
    gpiod_chip_close(chip);
    fclose(log_file);

    return EXIT_SUCCESS;
}

