#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_INIT_VALUE 0xFF
#define FLOW_RATE_SCALE 90.0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0

#define LOG_FILE "cooling_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd;
    int i2c_handle;
    int crc_value;
    uint16_t raw_flow;
    float flow_rate;
    char status[16];
    char timestamp[32];
    time_t now;
    struct tm *lt;
    FILE *log_file;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C handle
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to initialize I2C handle\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Send command sequence
        if (i2c_write(i2c_fd, &COMMAND, 2) < 0) {
            fprintf(stderr, "Failed to send command sequence\n");
            close(i2c_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Wait at least 2 ms
        usleep(2000);

        // Read 3 bytes from sensor
        if (i2c_read(i2c_fd, &raw_flow, &crc_value, 3) < 0) {
            fprintf(stderr, "Failed to read from sensor\n");
            close(i2c_fd);
            fclose(log_file);
            gpioTerminate();
            return 1;
        }

        // Validate CRC
        crc_value = crc8(crc_value, CRC_POLYNOMIAL, CRC_INIT, CRC_INIT_VALUE);
        if (crc_value != 0) {
            fprintf(log_file, "%s,%f,ERROR\n", ctime_r(&now, timestamp), 0.0);
            continue;
        }

        // Convert raw flow value to ml/min
        flow_rate = (float)raw_flow / FLOW_RATE_SCALE;

        // Validate flow rate
        if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
            status[0] = 'I';
            status[1] = 'N';
            status[2] = 'V';
            status[3] = 'A';
            status[4] = 'L';
            status[5] = 'I';
            status[6] = 'D';
            status[7] = ' ';
            status[8] = 'F';
            status[9] = 'L';
            status[10] = 'O';
            status[11] = 'W';
            status[12] = ' ';
            status[13] = 'R';
            status[14] = 'A';
            status[15] = 'T';
        } else {
