#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

// Function to handle signal interrupts
void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), 4));
    exit(0);
}

int main() {
    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    int chip_fd = gpiod_chip_open("/dev/gpiochip0");
    if (chip_fd < 0) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request the line
    int line_fd = gpiod_chip_get_line(chip_fd, 4);
    if (line_fd < 0) {
        gpiod_chip_close(chip_fd);
        perror("gpiod_chip_get_line");
        return 1;
    }

    // Request the line as an active-low input with falling edge event
    struct gpiod_line_event event;
    event.active_low = true;
    event.edge = GPIOD_LINE_EVENT_FALLING_EDGE;
    if (gpiod_line_request_events(line_fd, &event, GPIOD_LINE_EVENT_FALLING_EDGE) < 0) {
        gpiod_line_release(line_fd);
        gpiod_chip_close(chip_fd);
        perror("gpiod_line_request_events");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("flame_events.txt", "a");
    if (!log_file) {
        gpiod_line_release(line_fd);
        gpiod_chip_close(chip_fd);
        perror("fopen");
        return 1;
    }

    // Main loop
    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line_fd, &event, 1000) < 0) {
            gpiod_line_release(line_fd);
            gpiod_chip_close(chip_fd);
            fclose(log_file);
            perror("gpiod_line_event_wait");
            return 1;
        }

        // Check if the event is a falling edge
        if (event.event == GPIOD_LINE_EVENT_FALLING_EDGE) {
            // Print an alert with a timestamp
            time_t now = time(NULL);
            struct tm *now_tm = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", now_tm);
            printf("%s: Flame detected!\n", timestamp);

            // Log the event
            fprintf(log_file, "%s: Flame detected!\n", timestamp);
            fflush(log_file);
        }
    }

    // Clean up
    gpiod_line_release(line_fd);
    gpiod_chip_close(chip_fd);
    fclose(log_file);
    return 0;
}

