#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_INPUT 4
#define GPIO_OUTPUT 17
#define DEBOUNCE_TIME 200
#define POLL_INTERVAL 10
#define LOG_FILE "touch_log.txt"

volatile bool debouncing = false;
volatile bool last_state = false;

void sigint_handler(int sig) {
    gpioWrite(GPIO_OUTPUT, 0);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_INPUT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %s\n", GPIO_INPUT, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_OUTPUT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output: %s\n", GPIO_OUTPUT, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        int state = gpioRead(GPIO_INPUT);
        if (state == 1 && !last_state && !debouncing) {
            debouncing = true;
            if (time(NULL) - last_touch_time < DEBOUNCE_TIME / 1000) {
                continue;
            }
            last_touch_time = time(NULL);
            debouncing = false;
            last_state = true;
            gpioWrite(GPIO_OUTPUT, !gpioRead(GPIO_OUTPUT));
            fprintf(log_file, "%s\n", ctime(&last_touch_time));
        } else if (state == 0 && last_state) {
            last_state = false;
        }

        usleep(POLL_INTERVAL * 1000);
    }

    return 0;
}

