// Define the sensor pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the log file path
#define LOG_FILE "magnet_log.txt"

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Close the log file
    fclose(log_file);
    // Terminate the pigpio library
    gpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
