        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Record the initial state of the sensors
    uint8_t initial_state[3];
    if (gpioRead(SENSOR1_PIN, &initial_state[0]) != 0 || gpioRead(SENSOR2_PIN, &initial_state[1]) != 0 || gpioRead(SENSOR3_PIN, &initial_state[2]) != 0) {
        fprintf(stderr, "Failed to read initial sensor state\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

