    while (1) {
        // Poll the sensors
        uint8_t current_state[3];
        if (gpioRead(SENSOR1_PIN, &current_state[0]) != 0 || gpioRead(SENSOR2_PIN, &current_state[1]) != 0 || gpioRead(SENSOR3_PIN, &current_state[2]) != 0) {
