#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define LED_CURRENT 0x3F
#define AVERAGING 0x04
#define ENABLE 0x01
#define HEART_RATE_REGISTER 0x2A
#define MAX_SAMPLES 5
#define BPM_MIN 30
#define BPM_MAX 220

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    int gpio_fd = -1;
    FILE *log_file = NULL;

    // Initialize pigpio
    if ((gpio_fd = pigpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_fd);
        return 1;
    }

    // Open I2C bus
    if ((i2c_fd = pigpioOpen(I2C_BUS, 1)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_fd);
        pigpioTerminate();
        return 1;
    }

    // Open log file
    if ((log_file = fopen("heart_rate.csv", "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pigpioClose(i2c_fd);
        pigpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (running) {
        // Verify sensor's PART_ID and HW_REV registers
        uint8_t part_id;
        uint8_t hw_rev;
        if (pigpioI2cReadReg8(i2c_fd, I2C_ADDRESS, 0x00, &part_id) < 0 || part_id != 0x02) {
            fprintf(stderr, "Invalid PART_ID register\n");
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }
        if (pigpioI2cReadReg8(i2c_fd, I2C_ADDRESS, 0x01, &hw_rev) < 0 || hw_rev != 0x01) {
            fprintf(stderr, "Invalid HW_REV register\n");
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Configure sensor
        if (pigpioI2cWriteReg8(i2c_fd, I2C_ADDRESS, 0x3F, LED_CURRENT) < 0) {
            fprintf(stderr, "Failed to write LED current register\n");
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }
        if (pigpioI2cWriteReg8(i2c_fd, I2C_ADDRESS, 0x04, AVERAGING) < 0) {
            fprintf(stderr, "Failed to write averaging register\n");
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }
        if (pigpioI2cWriteReg8(i2c_fd, I2C_ADDRESS, 0x01, ENABLE) < 0) {
            fprintf(stderr, "Failed to write enable register\n");
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Read heart-rate register
        uint16_t heart_rate;
        int retries = 0;
        while (retries < 5) {
            if (pigpioI2cReadWordData(i2c_fd, I2C_ADDRESS, HEART_RATE_REGISTER, &heart_rate) >= 0) {
                break;
            }
            retries++;
            if (retries >= 5) {
                fprintf(stderr, "Failed to read heart-rate register after 5 retries\n");
                pigpioClose(i2c_fd);
                pigpioTerminate();
                fclose(log_file);
                return 1;
            }
            usleep(100000); // wait 100ms before retrying
        }

        // Convert raw value to BPM
        uint16_t bpm = heart_rate * 0.5;

        // Apply 5-sample moving average
        static uint16_t samples[MAX_SAMPLES];
        static int sample_index = 0;
        samples[sample_index] = bpm;
        sample_index = (sample_index + 1) % MAX_SAMPLES;
        uint16_t sum = 0;
        for (int i = 0; i < MAX_SAMPLES; i++) {
            sum += samples[i];
        }
        bpm = sum / MAX_SAMPLES;

        // Validate BPM
        if (bpm < BPM_MIN || bpm > BPM_MAX) {
            fprintf(stderr, "Invalid BPM: %d\n", bpm);
            pigpioClose(i2c_fd);
            pigpioTerminate();
            fclose(log_file);
            return 1;
        }

        // Log BPM
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d\n", timestamp, bpm);
        fflush(log_file);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    pigpioClose(i2c_fd);

    // Terminate pigpio
    pigpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

