#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <libgpiod.h>

// Function to handle signal
void sig_handler(int sig) {
    // Release the GPIO line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Check if the line is available
    if (gpiod_chip_line_is_available(chip, 17) == 0) {
        fprintf(stderr, "Line 17 is not available\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the line as input with an internal pull-up
    line = gpiod_chip_get_line(chip, 17);
    if (line == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(line, GPIOD_LINE_ACTIVE_LOW) == -1) {
        perror("gpiod_line_request_output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_direction(line, GPIOD_LINE_DIRECTION_INPUT) == -1) {
        perror("gpiod_line_request_direction");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_edge_trigger(line, GPIOD_LINE_EDGE_FALLING) == -1) {
        perror("gpiod_line_request_edge_trigger");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_bypass_pull(line, GPIOD_LINE_BYPASS_PULL_UP) == -1) {
        perror("gpiod_line_request_bypass_pull");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the line
        int value = gpiod_line_get_value(line);
        if (value == -1) {
            perror("gpiod_line_get_value");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            return 1;
        }

        // Check for falling edge
        if (value == 0) {
            // Print to console
            printf("FLAME DETECTED\n");

            // Append to log file
            char timestamp[20];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
            fflush(log_file);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return 0;
}

