#define STABILIZATION_DELAY 200000 // 200 ms

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Reset all output pins to 0
    for (int i = GPIO_BASE; i < GPIO_BASE + GPIO_COUNT; i++) {
        gpiod_line_request_output(i, 0);
    }
    // Release all libgpiod resources
    gpiod_chip_close(gpiod_chip);
    // Exit cleanly
    exit(0);
}

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip_t *chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request lines for input and output
    gpiod_line_request_t *lines = gpiod_chip_request_lines(chip, NULL, NULL, GPIO_COUNT, NULL);
    if (!lines) {
        gpiod_chip_close(chip);
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        return 1;
    }

    // Request output lines for counter display
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpiod_line_request_output(lines[i], 0);
    }

    // Stabilization delay
    usleep(STABILIZATION_DELAY);

    // Open the log file
    FILE *log_file = fopen(TOUCH_LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Warning: unable to open log file '%s': %s\n", TOUCH_LOG_FILE, strerror(errno));
    }

    // Initialize counter and previous states
    uint8_t counter = 0;
    uint8_t prev_states[GPIO_COUNT];

    // Main loop
    while (1) {
        // Read the current states of the sensor lines
        for (int i = 0; i < GPIO_COUNT; i++) {
            int state;
            if (gpiod_line_request_get_value(lines[i], &state) == -1) {
                fprintf(stderr, "Error reading line %d: %s\n", i + 1, strerror(errno));
                gpiod_chip_release_lines(lines);
                gpiod_chip_close(chip);
                return 1;
            }
            if (state != prev_states[i]) {
                // Rising edge detected, increment counter and update output
                counter = (counter + 1) % 256;
                gpiod_line_request_set_value(lines[i], 1);
                for (int j = 0; j < GPIO_COUNT; j++) {
                    gpiod_line_request_set_value(lines[j + GPIO_BASE], (counter >> j) & 1);
                }
                // Log the touch event
                char timestamp[32];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", localtime(&now));
                fprintf(log_file ? log_file : stderr, "%s, Channel: %d, Counter: %d\n", timestamp, i + 1, counter);
                fprintf(stderr, "Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev_states[i] = state;
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Release all libgpiod resources
    gpiod_chip_release_lines(lines);
    gpiod_chip_close(chip);

    return 0;
}

