                gpiod_line_release(line17);
                gpiod_line_release(line27);
                gpiod_line_release(line22);
                gpiod_chip_close(chip);
                fclose(log_file);
                return 1;
            }
        } else {
            // Turn off the LED
            if (gpiod_line_set_value(line22, 0) == -1) {
                perror("gpiod_line_set_value");
                gpiod_line_release(line17);
                gpiod_line_release(line27);
                gpiod_line_release(line22);
                gpiod_chip_close(chip);
                fclose(log_file);
                return 1;
            }
        }

        // Log the data
        char timestamp[20];
        time_t now;
        time(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%d,%d,%d\n", timestamp, value17, value27, (value17 == 0 && value27 == 0) ? 1 : 0);
        fflush(log_file);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Release the lines
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_line_release(line22);

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return 0;
}

