#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Flag to indicate whether the program is running
volatile sig_atomic_t running = 1;

// Signal handler for SIGINT
void sigint_handler(int sig) {
    running = 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up GPIO4 as a digital input
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO17 as a digital output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set the initial state of the LED to OFF
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "Failed to set LED OFF\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpioTerminate();
        return 1;
    }

    // Sample the microphone at approximately 8 kHz
    while (running) {
        // Read the state of the microphone
        int level = gpioRead(4);
        if (level < 0) {
            fprintf(stderr, "Failed to read GPIO4\n");
            break;
        }

        // Check if a peak has been detected
        if (level == 1) {
            // Print a timestamp
            time_t now = time(NULL);
            printf("%ld.%03ld\n", (long)now, (long)(now * 1000) % 1000);
            // Turn the LED ON for 100 ms
            if (gpioWrite(17, 1) < 0) {
                fprintf(stderr, "Failed to set LED ON\n");
                break;
            }
            usleep(100000);
            if (gpioWrite(17, 0) < 0) {
                fprintf(stderr, "Failed to set LED OFF\n");
                break;
            }
        }

        // Wait for 125 microseconds
        if (gpioDelay(125000) < 0) {
            fprintf(stderr, "Failed to delay\n");
            break;
        }
    }

    // Ensure the LED is OFF
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "Failed to set LED OFF\n");
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

