#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle signal interrupts
void signal_handler(int sig) {
    gpiod_line_release_all();
    exit(0);
}

int main() {
    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize GPIO
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(1);
    }

    // Configure GPIO17 (left), GPIO27 (center), and GPIO22 (right) as active-low inputs with pull-up enabled
    struct gpiod_line *left_line, *center_line, *right_line;
    left_line = gpiod_chip_get_line(chip, 17);
    if (!left_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(1);
    }
    center_line = gpiod_chip_get_line(chip, 27);
    if (!center_line) {
        gpiod_line_release(left_line);
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(1);
    }
    right_line = gpiod_chip_get_line(chip, 22);
    if (!right_line) {
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Request the lines as active-low inputs with pull-up enabled
    if (gpiod_line_request_output(left_line, "left", GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH) == -1) {
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_output(center_line, "center", GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH) == -1) {
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(1);
    }
    if (gpiod_line_request_output(right_line, "right", GPIOD_LINE_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_ACTIVE_HIGH) == -1) {
        gpiod_line_release(left_line);
        gpiod_line_release(center_line);
        gpiod_line_release(right_line);
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        exit(1);
    }

    // Main loop: read and log sensor states every 100 ms
    while (1) {
        struct gpiod_line_event event;
        if (gpiod_line_event_read(left_line, &event) == -1) {
            gpiod_line_release(left_line);
            gpiod_line_release(center_line);
            gpiod_line_release(right_line);
            gpiod_chip_close(chip);
            perror("gpiod_line_event_read");
            exit(1);
        }
        if (gpiod_line_event_read(center_line, &event) == -1) {
            gpiod_line_release(left_line);
            gpiod_line_release(center_line);
            gpiod_line_release(right_line);
            gpiod_chip_close(chip);
            perror("gpiod_line_event_read");
            exit(1);
        }
        if (gpiod_line_event_read(right_line, &event) == -1) {
            gpiod_line_release(left_line);
            gpiod_line_release(center_line);
            gpiod_line_release(right_line);
            gpiod_chip_close(chip);
            perror("gpiod_line_event_read");
            exit(1);
        }

        // Log sensor states
        printf("Left: %s, Center: %s, Right: %s\n", event.value == GPIOD_LINE_EVENT_VALUE_LOW ? "LOW" : "HIGH", event.value == GPIOD_LINE_EVENT_VALUE_LOW ? "LOW" : "HIGH", event.value == GPIOD_LINE_EVENT_VALUE_LOW ? "LOW" : "HIGH");

        // Sleep for 100 ms
        usleep(100000);
    }

