#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define REG_ALS_LSB 0x24
#define REG_ALS_MSB 0x25
#define REG_ALS_DATA_SIZE 2
#define READ_TIMEOUT 100 // ms

// Function to read I2C register
int read_i2c_register(int i2c_fd, uint8_t reg_addr, uint8_t *data, int size) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    int ret;

    // Prepare I2C message
    msgs->addr = I2C_ADDRESS;
    msgs->flags = I2C_M_RD;
    msgs->len = 1;
    msgs->buf = &reg_addr;

    // Send I2C message to read register address
    ret = ioctl(i2c_fd, I2C_RDWR, msgs);
    if (ret < 0) {
        perror("i2c_RDWR");
        return -1;
    }

    // Prepare I2C message to read data
    msgs->addr = I2C_ADDRESS;
    msgs->flags = 0;
    msgs->len = size;
    msgs->buf = data;

    // Send I2C message to read data
    ret = ioctl(i2c_fd, I2C_RDWR, msgs);
    if (ret < 0) {
        perror("i2c_RDWR");
        return -1;
    }

    return 0;
}

// Function to read ALS data from Si1175 sensor
int read_als_data(int i2c_fd, uint16_t *als_data) {
    uint8_t data[REG_ALS_DATA_SIZE];

    // Read ALS LSB and MSB registers
    if (read_i2c_register(i2c_fd, REG_ALS_LSB, data, REG_ALS_DATA_SIZE) < 0) {
        return -1;
    }

    // Combine LSB and MSB into 16-bit value
    *als_data = (data[0] << 8) | data[1];

    return 0;
}

// Function to handle signal interrupt
void sigint_handler(int sig) {
    // Release I2C device
    close(i2c_fd);

    // Exit program
    exit(0);
}

int main() {
    int i2c_fd;
    uint16_t als_data;
    struct i2c_adapter *adapter;
    struct i2c_client *client;
    char i2c_dev_path[256];

    // Get I2C device path
    sprintf(i2c_dev_path, "/dev/i2c-%d", I2C_BUS);

    // Open I2C device
    i2c_fd = open(i2c_dev_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    // Get I2C adapter and client
    adapter = i2c_get_adapter(I2C_BUS);
    if (!adapter) {
        perror("i2c_get_adapter");
        close(i2c_fd);
        return 1;
    }

    client = i2c_get_client(adapter, I2C_ADDRESS);
    if (!client) {
        perror("i2c_get_client");
        i2c_put_adapter(adapter);
        close(i2c_fd);
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Initialize ALS data
    als_data = 0;

    // Main loop
    while (1) {
        // Read ALS data
        if (read_als_data(i2c_fd, &als_data) < 0) {
            perror("read_als_data");
            break;
        }

        // Log ALS data
        printf("ALS data: 0x%04x\n", als_data);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Release I2C device and adapter
    i2c_put_client(client);
    i2c_put_adapter(adapter);
    close(i2c_fd);

    return 0;
}

