#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

// Compile with: gcc -o ttp226_reader ttp226_reader.c -lgpiod

// Define the GPIO pin numbers for the TTP226 sensor
#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

// Define the number of channels
#define NUM_CHANNELS 8

// Define the poll interval in milliseconds
#define POLL_INTERVAL 200

// Define the SIGINT/SIGTERM handler function
void sigint_handler(int sig) {
    // Release all libgpiod resources
    gpiod_line_release_all();
    gpiod_chip_release();
    exit(0);
}

int main() {
    // Install the SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Open the gpiochip0
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        exit(1);
    }

    // Request all 8 lines as inputs
    struct gpiod_line *lines[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, TP1 + i);
        if (!lines[i]) {
            fprintf(stderr, "Failed to request line %d: %s\n", TP1 + i, strerror(errno));
            gpiod_chip_release(chip);
            exit(1);
        }
        if (gpiod_line_request_output(lines[i], 0) == -1) {
            fprintf(stderr, "Failed to request line %d as input: %s\n", TP1 + i, strerror(errno));
            gpiod_chip_release(chip);
            exit(1);
        }
    }

    // Initialize the monotonic clock
    struct timeval tv;
    gettimeofday(&tv, NULL);

    // Main loop
    while (1) {
        // Poll each line and print the state
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int value;
            if (gpiod_line_get_value(lines[i], &value) == -1) {
                fprintf(stderr, "Failed to read line %d: %s\n", TP1 + i, strerror(errno));
                gpiod_chip_release(chip);
                exit(1);
            }
            printf("%d", value);
            if (i < NUM_CHANNELS - 1) printf(" ");
        }
        printf("\n");

        // Print the timestamp
        struct timeval tv2;
        gettimeofday(&tv2, NULL);
        double timestamp = (tv2.tv_sec - tv.tv_sec) + (tv2.tv_usec - tv.tv_usec) / 1e6;
        printf("[%f] ", timestamp);

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Release all libgpiod resources
    gpiod_line_release_all();
    gpiod_chip_release();

    return 0;
}

