#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define GPIO_LED 17
#define POLL_INTERVAL 200

int main() {
    int i2c_fd, gpio_fd;
    int ret;
    uint8_t buffer[2];
    uint16_t calibrated[4];
    uint16_t threshold = 200;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open GPIO line
    gpio_fd = gpiod_open("/sys/class/gpio/gpio17");
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Power on and enable RGBC
    buffer[0] = 0x01; // PON
    buffer[1] = 0x01; // AEN
    ret = write(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to write to I2C bus");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Set integration time and gain
    buffer[0] = 0x00; // ATIME
    buffer[1] = 0x00; // CONTROL
    ret = write(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to write to I2C bus");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Verify sensor ID
    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Failed to read from I2C bus");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }
    if (buffer[0] != 0x44 || buffer[1] != 0x25) {
        printf("Invalid sensor ID\n");
        gpiod_close(gpio_fd);
        close(i2c_fd);
        return 1;
    }

    // Poll sensor
    while (1) {
        // Read channel registers
        ret = read(i2c_fd, buffer, 8);
        if (ret != 8) {
            perror("Failed to read from I2C bus");
            gpiod_close(gpio_fd);
            close(i2c_fd);
            return 1;
        }

        // Apply calibration
        calibrated[0] = (buffer[1] << 8) | buffer[0]; // Clear
        calibrated[1] = (buffer[3] << 8) | buffer[2]; // Red
        calibrated[2] = (buffer[5] << 8) | buffer[4]; // Green
        calibrated[3] = (buffer[7] << 8) | buffer[6]; // Blue

        // Apply per-channel gain and offset calibration
        calibrated[0] -= 0x0000; // Clear
        calibrated[1] -= 0x0000; // Red
        calibrated[2] -= 0x0000; // Green
        calibrated[3] -= 0x0000; // Blue

        // Display calibrated values
        printf("Calibrated RGB: %04x %04x %04x %04x\n", calibrated[0], calibrated[1], calibrated[2], calibrated[3]);

        // Drive LED
        if (calibrated[1] > threshold) {
            gpiod_direction(gpio_fd, GPIOD_OUT);
            gpiod_write(gpio_fd, 1);
        } else {
            gpiod_direction(gpio_fd, GPIOD_OUT);
            gpiod_write(gpio_fd, 0);
        }

        // Sleep
        usleep(POLL_INTERVAL * 1000);
    }

    // Clean up
    gpiod_close(gpio_fd);
    close(i2c_fd);

    return 0;
}

// Signal handlers
void sigint_handler(int sig) {
    gpiod_close(gpio_fd);
    close(i2c_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_close(gpio_fd);
    close(i2c_fd);
    exit(0);
}

