#define LED_PIN 18
#define LIGHT_SENSOR_I2C_BUS 1
#define LIGHT_SENSOR_ADDRESS 0x23
#define LIGHT_SENSOR_COMMAND 0x10
#define LIGHT_SENSOR_RETRY_COUNT 5
#define LIGHT_SENSOR_RETRY_DELAY 100

// Smooth, non-linear (logarithmic) brightness mapping function
uint8_t map_brightness(uint16_t lux) {
    return (uint8_t)((log(lux + 1) / log(1000 + 1)) * 255);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up I2C bus
    if (gpioI2CSetup(LIGHT_SENSOR_I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Set up light sensor
    for (int retry = 0; retry < LIGHT_SENSOR_RETRY_COUNT; retry++) {
        if (gpioI2CWrite(LIGHT_SENSOR_I2C_BUS, LIGHT_SENSOR_ADDRESS, 1, &LIGHT_SENSOR_COMMAND) < 0) {
            fprintf(stderr, "Failed to write to light sensor (retry %d)\n", retry + 1);
            sleep(LIGHT_SENSOR_RETRY_DELAY / 1000);
            continue;
        }

        // Wait for 180 ms
        usleep(180000);

        // Read 2 bytes from light sensor
        uint8_t data[2];
        if (gpioI2CRead(LIGHT_SENSOR_I2C_BUS, LIGHT_SENSOR_ADDRESS, 2, data) < 0) {
            fprintf(stderr, "Failed to read from light sensor (retry %d)\n", retry + 1);
            sleep(LIGHT_SENSOR_RETRY_DELAY / 1000);
            continue;
        }

        // Compute lux
        uint16_t lux = (data[0] << 8) | data[1];
        lux /= 1.2;

        // Map lux to brightness
        uint8_t brightness = map_brightness(lux);

        // Set LED strip brightness
        gpioHardwarePWM(LED_PIN, brightness);

        // Wait for 100 ms
        usleep(100000);
    }

    // Clean up
    gpioTerminate();

    return 0;
}

