#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define SPI_BUS "/dev/spidev0.0"
#define APA102_LED_COUNT 32

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        exit(1);
    }
    return fd;
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("i2c_write: ioctl");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_write: write");
        return -1;
    }
    if (write(fd, &value, 1) != 1) {
        perror("i2c_write: write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("i2c_read: ioctl");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read: write");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read: read");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

int spi_open() {
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        perror("spi_open");
        exit(1);
    }
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)malloc(4 * APA102_LED_COUNT),
        .rx_buf = NULL,
        .len = 4 * APA102_LED_COUNT,
        .speed_hz = 1000000,
        .bits_per_word = 32,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
        perror("spi_open: ioctl");
        free(xfer.tx_buf);
        exit(1);
    }
    return fd;
}

void spi_write(int fd, uint32_t *data, int count) {
    struct spi_ioc_transfer xfer = {
        .tx_buf = (unsigned long)data,
        .rx_buf = NULL,
        .len = count * 4,
        .speed_hz = 1000000,
        .bits_per_word = 32,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1, &xfer) < 0)) {
        perror("spi_write: ioctl");
    }
}

void adjust_brightness(int fd, int lux) {
    int brightness = (lux - 10) / 290 * 31;
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    uint32_t frame[APA102_LED_COUNT];
    for (int i = 0; i < APA102_LED_COUNT; i++) {
        frame[i] = 0xE0 | brightness;
    }
    spi_write(fd, frame, APA102_LED_COUNT);
}

int main() {
    signal(SIGINT, sigint_handler);

    int i2c_fd = i2c_open();
    if (i2c_fd < 0) exit(1);

    if (i2c_write(i2c_fd, 0x20, 0x10) < 0) {
        perror("main: i2c_write");
        close(i2c_fd);
        exit(1);
    }

    usleep(120000);

    int lux = i2c_read(i2c_fd, 0x00);
    if (lux < 0) {
        perror("main: i2c_read");
        close(i2c_fd);
        exit(1);
    }

    lux = lux / 1.2;

    int spi_fd = spi_open();
    if (spi_fd < 0) {
        perror("main: spi_open");
        close(i2c_fd);
        exit(1);
    }

    while (running) {
        if (i2c_read(i2c_fd, 0x00) < 0) {
            perror("main: i2c_read");
            close(i2c_fd);
            close(spi_fd);
            exit(1);
        }
        lux = i2c_read(i2c_fd, 0x00) / 1.2;
        adjust_brightness(spi_fd, lux);
        usleep(100000);
    }

    spi_write(spi_fd, NULL, 0);
    close(spi_fd);
    close(i2c_fd);
    return 0;
}

