#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

#define APA102_MISO 9
#define APA102_SCK 11
#define APA102_SDI 10
#define APA102_CSC 25
#define APA102_N 60

#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void fade_strip(int brightness) {
    for (int i = 0; i < APA102_N; i++) {
        gpio_write(APA102_SDI, brightness);
        gpioDelay(1);
    }
}

void read_bh1750(int addr, int *lux) {
    int fd = i2cOpen(1, addr);
    if (fd < 0) {
        printf("Failed to open I2C bus 1 for address 0x%x\n", addr);
        return;
    }

    if (i2cWriteByte(fd, 0x21) < 0) {
        i2cClose(fd);
        return;
    }

    if (i2cDelay(180) < 0) {
        i2cClose(fd);
        return;
    }

    uint8_t data[2];
    if (i2cRead(fd, data, 2) < 0) {
        i2cClose(fd);
        return;
    }

    *lux = (data[0] << 8) | data[1];
    i2cClose(fd);
}

int main() {
    if (gpioInitialise() < 0) {
        printf("Failed to initialize pigpio\n");
        return 1;
    }

    if (gpioSetMode(APA102_SDI, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(APA102_SCK, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(APA102_MISO, PI_ALT5) < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(APA102_CSC, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    if (spiOpen(APA102_SCK, APA102_SDI, 1000000) < 0) {
        gpioTerminate();
        return 1;
    }

    int lux_sum = 0;
    int sensor_count = 0;

    signal(SIGINT, sigint_handler);

    while (running) {
        int lux[3];
        for (int i = 0; i < 3; i++) {
            read_bh1750((i & 1) ? BH1750_ADDR_HIGH : BH1750_ADDR_LOW, &lux[i]);
            if (lux[i] >= 0) {
                lux_sum += lux[i];
                sensor_count++;
            }
        }

        if (sensor_count == 0) {
            printf("No BH1750 sensors present\n");
            continue;
        }

        int avg_lux = lux_sum / sensor_count;
        int brightness = (avg_lux < 100) ? (avg_lux / 10) : 0;

        fade_strip(brightness);

        lux_sum = 0;
        sensor_count = 0;
        usleep(500000);
    }

    fade_strip(0);
    spiClose();
    gpioTerminate();

    return 0;
}

