    if (gpioSetMode(APA102_MISO, PI_ALT5) < 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(APA102_CSC, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    if (spiOpen(APA102_SCK, APA102_SDI, 1000000) < 0) {
        gpioTerminate();
        return 1;
    }

    int lux_sum = 0;
    int sensor_count = 0;

    signal(SIGINT, sigint_handler);

    while (running) {
        int lux[3];
        for (int i = 0; i < 3; i++) {
            read_bh1750((i & 1) ? BH1750_ADDR_HIGH : BH1750_ADDR_LOW, &lux[i]);
            if (lux[i] >= 0) {
                lux_sum += lux[i];
                sensor_count++;
            }
        }

        if (sensor_count == 0) {
            printf("No BH1750 sensors present\n");
            continue;
        }

        int avg_lux = lux_sum / sensor_count;
        int brightness = (avg_lux < 100) ? (avg_lux / 10) : 0;

        fade_strip(brightness);

        lux_sum = 0;
        sensor_count = 0;
        usleep(500000);
    }

    fade_strip(0);
    spiClose();
    gpioTerminate();

    return 0;
}
