    if (val > WS2812B_DUTY_MAX) {
        val = WS2812B_DUTY_MAX;
    } else if (val < WS2812B_DUTY_MIN) {
        val = WS2812B_DUTY_MIN;
    }

    uint32_t period = 1000000 / WS2812B_FREQ;
    uint32_t duty = (uint32_t)val * period;
    uint32_t high = duty;
    uint32_t low = period - duty;

    for (int i = 0; i < 1000; i++) {
        gpio_set(1);
        usleep(high);
        gpio_set(0);
        usleep(low);
    }
}

void ws2812b_threshold_set(uint8_t val) {
    gpio_set(val);
}

