    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int fd = i2c_init();
    ws2812b_init();

    for (int i = 0; i < 3; i++) {
        if (i2c_read(0x00) == 0x0000) {
            break;
        }

        if (i < 2) {
            usleep(100000);
        }
    }

    if (i2c_read(0x00) != 0x0000) {
        fprintf(stderr, "Failed to initialize VEML7700\n");
        close(fd);
        exit(1);
    }

    while (running) {
        uint16_t lux = i2c_read(0x04);
        lux_to_brightness(lux);
        printf("Lux: %d, Brightness: %d\n", lux, ws2812b_get_duty());
        usleep(200000);
    }

    close(fd);
    gpiod_close(gpiod_open("/sys/class/gpio/gpio18"));
    return 0;
}

