#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

// Define GPIO pin numbers
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define signal handler for SIGINT
void sigint_handler(int sig) {
    gpiod_line_release(FLAME_SENSOR_PIN);
    gpiod_line_release(BUZZER_PIN);
    gpiod_line_release(LED_PIN);
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize GPIO lines
    struct gpiod_line *flame_sensor_line = gpiod_line_request("gpiochip0", FLAME_SENSOR_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_DIRECTION_INPUT);
    if (!flame_sensor_line) {
        perror("gpiod_line_request");
        exit(1);
    }

    struct gpiod_line *buzzer_line = gpiod_line_request("gpiochip0", BUZZER_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!buzzer_line) {
        gpiod_line_release(FLAME_SENSOR_PIN);
        perror("gpiod_line_request");
        exit(1);
    }

    struct gpiod_line *led_line = gpiod_line_request("gpiochip0", LED_PIN, GPIOD_LINE_ACTIVE_LOW, GPIOD_LINE_DIRECTION_OUTPUT);
    if (!led_line) {
        gpiod_line_release(FLAME_SENSOR_PIN);
        gpiod_line_release(BUZZER_PIN);
        perror("gpiod_line_request");
        exit(1);
    }

    // Perform self-test
    printf("Performing self-test...\n");
    for (int i = 0; i < 2; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(500000);
        gpiod_line_set_value(led_line, 0);
        usleep(500000);
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; i++) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 0) {
            flame_detected = 1;
        }
        usleep(100000);
    }

    if (flame_detected) {
        printf("Self-test failed: flame sensor consistently reads LOW\n");
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(led_line, 1);
            usleep(100000);
            gpiod_line_set_value(led_line, 0);
            usleep(100000);
        }
        for (int i = 0; i < 3; i++) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(200000);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(200000);
            gpiod_line_set_value(buzzer_line, 1);
            usleep(600000);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(200000);
        }
        gpiod_line_release(FLAME_SENSOR_PIN);
        gpiod_line_release(BUZZER_PIN);
        gpiod_line_release(LED_PIN);
        exit(1);
    }

    printf("Self-test passed\n");

    // Main loop
    while (1) {
        int value = gpiod_line_get_value(flame_sensor_line);
        if (value == 0) {
            printf("Flame detected at %lu\n", (unsigned long)time(NULL));
            gpiod_line_set_value(buzzer_line, 1);
            gpiod_line_set_value(led_line, 1);
        } else {
            gpiod_line_set_value(buzzer_line, 0);
            gpiod_line_set_value(led_line, 0);
        }
        usleep(50000);
    }

    return 0;
}

