#include <sys/signal.h>
#include <sys/time.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define BLINK_MIN_HZ 0.5
#define BLINK_MAX_HZ 5.0
#define BLINK_MAX_LUX 1000

int i2c_fd;
uint16_t buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
uint16_t sum = 0;
int blink_hz = 0;
struct itimerspec blink_timer;
struct sigaction sa;
struct sigaction sa_old;

void blink_handler(int sig) {
    (void)sig;
    blink_timer.it_value.tv_sec = 0;
    blink_timer.it_value.tv_nsec = (1000000000 / blink_hz) * 500000000;
    if (timer_settime(blink_fd, 0, &blink_timer, NULL) == -1) {
        perror("timer_settime");
        exit(1);
    }
}

void blink() {
    (void)write(blink_fd, "1", 1);
    usleep((1000000000 / blink_hz) * 500000000 / 2);
    (void)write(blink_fd, "0", 1);
    usleep((1000000000 / blink_hz) * 500000000 / 2);
}

void read_i2c() {
    uint8_t data[2];
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        perror("ioctl");
        return;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("read");
        return;
    }
    uint16_t raw = (data[0] << 8) | data[1];
    buffer[buffer_head] = raw;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    sum += raw;
    if (buffer_head == buffer_tail) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        sum -= buffer[buffer_tail];
    }
    blink_hz = (int)(0.5 + (sum / (double)BUFFER_SIZE / 1.2 / 1000) * 4.5);
    blink_hz = (blink_hz < BLINK_MIN_HZ) ? BLINK_MIN_HZ : (blink_hz > BLINK_MAX_HZ) ? BLINK_MAX_HZ : blink_hz;
}

