    blink_timer.it_value.tv_nsec = (1000000000 / BLINK_MIN_HZ) * 500000000;
    blink_timer.it_interval.tv_sec = 0;
    blink_timer.it_interval.tv_nsec = 0;
    if (timer_create(CLOCK_REALTIME, &blink_timer, &blink_fd) == -1) {
        perror("timer_create");
        return 1;
    }
    sa.sa_handler = blink_handler;
    sa.sa_flags = 0;
    if (sigaction(SIGALRM, &sa, &sa_old) == -1) {
