#include <gpiod.h>

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip);
    gpiod_line_release(gpiod_led_line);
    gpiod_line_release(gpiod_button_line);
    exit(0);
}

int main() {
    // Open GPIO chip 0
    gpiod_chip *gpiod_chip = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod_chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Request LED line (BCM GPIO17) as output initially low
    gpiod_line *gpiod_led_line = gpiod_chip_get_line(gpiod_chip, 17);
    if (!gpiod_led_line) {
        fprintf(stderr, "Failed to request LED line\n");
        gpiod_chip_close(gpiod_chip);
        return 1;
    }
    if (gpiod_line_request_output(gpiod_led_line, 0, GPIOD_LINE_ACTIVE_LOW) != 0) {
        fprintf(stderr, "Failed to request LED line as output\n");
        gpiod_line_release(gpiod_led_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    // Request button line (BCM GPIO18) as input with internal pull-up and falling-edge event detection
    gpiod_line *gpiod_button_line = gpiod_chip_get_line(gpiod_chip, 18);
    if (!gpiod_button_line) {
        fprintf(stderr, "Failed to request button line\n");
        gpiod_line_release(gpiod_led_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }
    if (gpiod_line_request_input(gpiod_button_line, GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_EVENT_RISING | GPIOD_LINE_EVENT_FALLING) != 0) {
        fprintf(stderr, "Failed to request button line as input\n");
        gpiod_line_release(gpiod_button_line);
        gpiod_line_release(gpiod_led_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        gpiod_line_release(gpiod_button_line);
        gpiod_line_release(gpiod_led_line);
        gpiod_chip_close(gpiod_chip);
        return 1;
    }

    // Blink LED while monitoring for button events
    while (1) {
        // Toggle LED
        if (gpiod_line_get_value(gpiod_led_line) == 0) {
            if (gpiod_line_set_value(gpiod_led_line, 1) != 0) {
                fprintf(stderr, "Failed to set LED high\n");
                break;
            }
        } else {
            if (gpiod_line_set_value(gpiod_led_line, 0) != 0) {
                fprintf(stderr, "Failed to set LED low\n");
                break;
            }
        }

        // Wait for button event or 1-second timeout
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(gpiod_button_line, 1000000000, &event) != 0) {
            fprintf(stderr, "Failed to wait for button event\n");
            break;
        }

        // Check if button was pressed (falling edge)
        if (event.event == GPIOD_LINE_EVENT_FALLING) {
            // Stop blinking, turn off LED, and exit
            gpiod_line_set_value(gpiod_led_line, 0);
            printf("Button pressed, exiting...\n");
            break;
        }
    }

    // Release resources
    gpiod_line_release(gpiod_button_line);
    gpiod_line_release(gpiod_led_line);
    gpiod_chip_close(gpiod_chip);

    return 0;
}

