#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <gpiod.h>

#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_RATE 10
#define DEFAULT_LOG_FILE "impact_log.txt"

// Structure to hold accelerometer data
typedef struct {
    int16_t x, y, z;
} AccelData;

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Release I2C handle
    if (i2c_close(i2c_open(1, 0x19)) < 0) {
        perror("i2c_close");
    }

    // Release GPIO handle
    gpioTerminate();

    // Exit with status code 0
    exit(0);
}

int main(int argc, char **argv) {
    // Parse command-line arguments
    float threshold = DEFAULT_THRESHOLD;
    int rate = DEFAULT_RATE;
    char *log_file = DEFAULT_LOG_FILE;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[++i]);
        } else if (strcmp(argv[i], "-r") == 0 && i + 1 < argc) {
            rate = atoi(argv[++i]);
        } else if (strcmp(argv[i], "-l") == 0 && i + 1 < argc) {
            log_file = argv[++i];
        }
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set GPIO17 as output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    int i2c = i2c_open(1, 0x19);
    if (i2c < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    uint8_t ctrl_reg1 = 0x27; // Enable all axes, 100 Hz
    uint8_t ctrl_reg4 = 0x00; // 2G full-scale, sensitivity 16384 LSB/G
    if (i2c_write(i2c, 0x1E, &ctrl_reg1, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG1_A\n");
        i2c_close(i2c);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(i2c, 0x2D, &ctrl_reg4, 1) < 0) {
        fprintf(stderr, "Failed to write CTRL_REG4_A\n");
        i2c_close(i2c);
        gpioTerminate();
        return 1;
    }

    // Initialize signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        i2c_close(i2c);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        AccelData data;
        uint8_t reg = 0x28; // OUT_X_L_A
        if (i2c_read(i2c, reg, (uint8_t *)&data.x, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }
        reg++;
        if (i2c_read(i2c, reg, (uint8_t *)&data.y, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }
        reg++;
        if (i2c_read(i2c, reg, (uint8_t *)&data.z, 2) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        // Calculate G-force magnitude
        float magnitude = sqrtf((float)data.x * data.x + (float)data.y * data.y + (float)data.z * data.z) / 16384.0f;

        // Check if impact threshold exceeded
        if (magnitude > threshold) {
            // Pulse GPIO17 HIGH for 50 ms
            gpioWrite(17, 1);
            usleep(50000);
            gpioWrite(17, 0);

            // Log timestamped accelerometer data
            FILE *fp = fopen(log_file, "a");
            if (fp == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                break;
            }
            fprintf(fp, "%f %f %f\n", magnitude, data.x, data.y);
            fclose(fp);
        }

        // Sleep for 100 ms
        usleep(100000 / rate);
    }

    // Release I2C handle
    if (i2c_close(i2c) < 0) {
        perror("i2c_close");
    }

    // Release GPIO handle
    gpioTerminate();

    return 0;
}

