#define ALS_REG_MSB 0x65
#define RGB_REG_RED 0x66
#define RGB_REG_GREEN 0x68
#define RGB_REG_BLUE 0x6A
#define MODE_REG 0x0D
#define LED_GPIO 18
#define CSV_FILE "color_log.csv"
#define CSV_HEADER "timestamp,ALS,R,G,B\n"
#define SAMPLE_INTERVAL 500

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

void i2c_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
    if (gpioSetMode(LED_GPIO, PI_PWM) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        exit(1);
    }
}

void i2c_write(uint8_t reg, uint8_t value) {
    int fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return;
    }
    if (i2cWriteReg8(fd, reg, value) < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%02x\n", reg);
        gpioClose(fd);
        return;
    }
    gpioClose(fd);
}

uint16_t i2c_read_16bit(uint8_t reg) {
    int fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 0;
    }
    uint16_t value = i2cReadReg16(fd, reg);
    gpioClose(fd);
    return value;
}

void i2c_read_als() {
    uint16_t als = i2c_read_16bit(ALS_REG_LSB);
    if (als == 0) {
        fprintf(stderr, "Failed to read ALS value\n");
        return;
    }
    uint16_t msb = i2c_read_16bit(ALS_REG_MSB);
    als = (als << 8) | msb;
    return als;
}

void i2c_read_rgb() {
    uint16_t red = i2c_read_16bit(RGB_REG_RED);
    if (red == 0) {
        fprintf(stderr, "Failed to read red value\n");
        return;
    }
    uint16_t green = i2c_read_16bit(RGB_REG_GREEN);
    if (green == 0) {
        fprintf(stderr, "Failed to read green value\n");
        return;
    }
    uint16_t blue = i2c_read_16bit(RGB_REG_BLUE);
    if (blue == 0) {
        fprintf(stderr, "Failed to read blue value\n");
        return;
    }
    return;
}

