#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x1F
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define SENSITIVITY 4096.0
#define THRESHOLD 19.62

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = pigpioOpen(I2C_BUS, 1);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (pigpioI2CSetMode(i2c_fd, I2C_MODE_I2C) < 0) {
        fprintf(stderr, "Failed to set I2C mode\n");
        pigpioClose(i2c_fd);
        return 1;
    }

    if (pigpioI2CSetSlaveAddress(i2c_fd, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        pigpioClose(i2c_fd);
        return 1;
    }

    if (pigpioI2CWriteReg8(i2c_fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Failed to set CTRL_REG1\n");
        pigpioClose(i2c_fd);
        return 1;
    }

    if (pigpioI2CWriteReg8(i2c_fd, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to set XYZ_DATA_CFG\n");
        pigpioClose(i2c_fd);
        return 1;
    }

    if (pigpioI2CWriteReg8(i2c_fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Failed to set CTRL_REG1\n");
        pigpioClose(i2c_fd);
        return 1;
    }

    struct tm time;
    time_t now;
    char filename[20];
    FILE *file;

    while (running) {
        if (pigpioI2CReadReg8(i2c_fd, WHO_AM_I_REG, 1, NULL, 0) < 0) {
            fprintf(stderr, "Failed to read WHO_AM_I_REG\n");
            continue;
        }

        if (pigpioI2CReadReg8(i2c_fd, WHO_AM_I_REG, 1, NULL, 0) != 0xC7) {
            fprintf(stderr, "WHO_AM_I_REG does not match 0xC7\n");
            pigpioClose(i2c_fd);
            return 1;
        }

        if (pigpioI2CReadReg8(i2c_fd, OUT_X_MSB, 6, NULL, 0) < 0) {
            fprintf(stderr, "Failed to read OUT_X_MSB\n");
            continue;
        }

        uint8_t data[6];
        if (pigpioI2CReadReg8(i2c_fd, OUT_X_MSB, 6, data, 0) < 0) {
            fprintf(stderr, "Failed to read OUT_X_MSB\n");
            continue;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        x >>= 2;
        y >>= 2;
        z >>= 2;

        float magnitude = sqrtf((float)x * x + (float)y * y + (float)z * z) / SENSITIVITY * 9.81;

        if (magnitude > THRESHOLD) {
            time = *localtime(&now);
            strftime(filename, sizeof(filename), "impact_log.txt", "%Y-%m-%d %H:%M:%S", &time);
            file = fopen(filename, "a");
            if (file == NULL) {
                fprintf(stderr, "Failed to open log file\n");
                continue;
            }

            fprintf(file, "%.3f,%.3f,%.3f,%.3f\n", now, x, y, z);
            fclose(file);
        }

        sleep(0.05);
    }

    pigpioI2CClose(i2c_fd);
    gpioTerminate();
    return 0;
}

