#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F
#define SAMPLES 100
#define PERIOD_US 50
#define ALERT_THRESHOLD 50.0
#define SENSITIVITY 0.00875

#define LOG_FILE "gyro_log.txt"

int gyro_fd;
FILE *log_file;

void cleanup(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    if (gyro_fd >= 0) {
        close(gyro_fd);
    }
    exit(0);
}

int main() {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_msg;
    uint8_t buffer[6];
    uint16_t x, y, z;
    uint16_t x_offset = 0, y_offset = 0, z_offset = 0;
    uint32_t timestamp;
    struct tm time;
    char log_line[256];

    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    gyro_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (gyro_fd < 0) {
        perror("Failed to open I2C device");
        exit(1);
    }

    if (ioctl(gyro_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(gyro_fd);
        exit(1);
    }

    // Check if the sensor is present
    msg.buf = buffer;
    msg.len = 1;
    msg.addr = I2C_ADDR;
    i2c_msg.msg = &msg;
    i2c_msg.nmsgs = 1;
    if (ioctl(gyro_fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("Failed to read WHO_AM_I");
        close(gyro_fd);
        exit(1);
    }
    if (buffer[0] != 0xD3) {
        fprintf(stderr, "Sensor not found\n");
        close(gyro_fd);
        exit(1);
    }

    // Configure CTRL_REG1
    msg.buf = (uint8_t[]) {0x0F};
    msg.len = 1;
    msg.addr = CTRL_REG1;
    i2c_msg.msg = &msg;
    i2c_msg.nmsgs = 1;
    if (ioctl(gyro_fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("Failed to write CTRL_REG1");
        close(gyro_fd);
        exit(1);
    }

    // Configure CTRL_REG4
    msg.buf = (uint8_t[]) {0x00};
    msg.len = 1;
    msg.addr = CTRL_REG4;
    i2c_msg.msg = &msg;
    i2c_msg.nmsgs = 1;
    if (ioctl(gyro_fd, I2C_RDWR, &i2c_msg) < 0) {
        perror("Failed to write CTRL_REG4");
        close(gyro_fd);
        exit(1);
    }

    // Perform calibration
    for (int i = 0; i < SAMPLES; i++) {
        usleep(PERIOD_US * 1000);
        msg.buf = buffer;
        msg.len = 6;
        msg.addr = OUT_X_L;
        i2c_msg.msg = &msg;
        i2c_msg.nmsgs = 1;
        if (ioctl(gyro_fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to read gyro data");
            close(gyro_fd);
            exit(1);
        }
        x = (uint16_t)((buffer[1] << 8) | buffer[0]);
        y = (uint16_t)((buffer[3] << 8) | buffer[2]);
        z = (uint16_t)((buffer[5] << 8) | buffer[4]);
        x_offset += x;
        y_offset += y;
        z_offset += z;
    }
    x_offset /= SAMPLES;
    y_offset /= SAMPLES;
    z_offset /= SAMPLES;

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close(gyro_fd);
        exit(1);
    }

    while (1) {
        msg.buf = buffer;
        msg.len = 6;
        msg.addr = OUT_X_L;
        i2c_msg.msg = &msg;
        i2c_msg.nmsgs = 1;
        if (ioctl(gyro_fd, I2C_RDWR, &i2c_msg) < 0) {
            perror("Failed to read gyro data");
            fclose(log_file);
            close(gyro_fd);
            exit(1);
        }
        x = (uint16_t)((buffer[1] << 8) | buffer[0]) - x_offset;
        y = (uint16_t)((buffer[3] << 8) | buffer[2]) - y_offset;
        z = (uint16_t)((buffer[5] << 8) | buffer[4]) - z_offset;
        if (x > ALERT_THRESHOLD || x < -ALERT_THRESHOLD || y > ALERT_THRESHOLD || y < -ALERT_THRESHOLD || z > ALERT_THRESHOLD || z < -ALERT_THRESHOLD) {
            fprintf(stderr, "Warning: axis exceeded %f dps\n", ALERT_THRESHOLD);
            fprintf(log_file, "%s: Warning: axis exceeded %f dps\n", ctime(&timestamp), ALERT_THRESHOLD);
        }
        timestamp = time(NULL);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S.%03d", localtime(&timestamp));
        fprintf(log_file, "%s: %f %f %f\n", log_line, x * SENSITIVITY, y * SENSITIVITY, z * SENSITIVITY);
        fflush(log_file);
        usleep(PERIOD_US * 1000);
    }

    return 0;
}

