    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioError(gpio_fd));
        return 1;
    }

    // Set up LED pin as output
    if (gpioSetMode(gpio_fd, LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode: %s\n", gpioError(gpio_fd));
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Initialize I2C
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Verify DEVID register
    uint8_t devid;
    if (i2c_smbus_read_byte_data(i2c_fd, DEVID_REG, &devid) < 0) {
        fprintf(stderr, "Failed to read DEVID register: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Invalid DEVID register value: 0x%02x\n", devid);
        close(i2c_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

