        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        close(i2c_fd);
        close(log_fd);
        gpioTerminate(gpio_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read acceleration data
        uint8_t x_data[2];
        uint8_t y_data[2];
        uint8_t z_data[2];
        if (i2c_smbus_read_i2c_block_data(i2c_fd, ACCEL_X_REG, 2, x_data) < 0 ||
            i2c_smbus_read_i2c_block_data(i2c_fd, ACCEL_Y_REG, 2, y_data) < 0 ||
            i2c_smbus_read_i2c_block_data(i2c_fd, ACCEL_Z_REG, 2, z_data) < 0) {
            fprintf(stderr, "Failed to read acceleration data: %s\n", strerror(errno));
            close(i2c_fd);
            close(log_fd);
            gpioTerminate(gpio_fd);
            return 1;
        }

        // Calculate acceleration values
        int16_t x = (x_data[0] << 8) | x_data[1];
        int16_t y = (y_data[0] << 8) | y_data[1];
        int16_t z = (z_data[0] << 8) | z_data[1];

        // Log data
        time_t timestamp = time(NULL);
        sprintf(log_buf, "%lu,%d,%d,%d\n", timestamp, x / 64, y / 64, z / 64);
        if (write(log_fd, log_buf, strlen(log_buf)) < 0) {
            fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
            close(i2c_fd);
            close(log_fd);
            gpioTerminate(gpio_fd);
            return 1;
        }

        // Check if acceleration exceeds 2.0g
        if (abs(x) > 128 || abs(y) > 128 || abs(z) > 128) {
            gpioWrite(gpio_fd, LED_PIN, 1);
        } else {
            gpioWrite(gpio_fd, LED_PIN, 0);
        }

        // Sleep
        usleep(LOG_INTERVAL_US);
    }

    // Clean up
    close(i2c_fd);
    close(log_fd);
    gpioTerminate(gpio_fd);
    return 0;
