#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E
#define ACCEL_CTRL_REG1_A 0x20
#define MAG_MR_REG_M 0x02
#define ACCEL_OUT_X_L_A 0x28
#define MAG_OUT_X_H_M 0x03
#define SAMPLE_RATE 100000 // 100 ms
#define CSV_HEADER "timestamp,heading,accel_x,accel_y,accel_z,mag_x,mag_y,mag_z\n"

// Function to write a byte to a register
static int write_byte(int fd, uint8_t addr, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (i2c_write(fd, addr, buf, 2, 1) < 0) {
        fprintf(stderr, "Error writing to I2C bus\n");
        return -1;
    }
    return 0;
}

// Function to read a byte from a register
static int read_byte(int fd, uint8_t addr, uint8_t reg, uint8_t *value) {
    uint8_t buf[1] = {reg};
    if (i2c_write(fd, addr, buf, 1, 1) < 0) {
        fprintf(stderr, "Error writing to I2C bus\n");
        return -1;
    }
    if (i2c_read(fd, addr, value, 1, 1) < 0) {
        fprintf(stderr, "Error reading from I2C bus\n");
        return -1;
    }
    return 0;
}

// Function to read 2 bytes from a register
static int read_word(int fd, uint8_t addr, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (read_byte(fd, addr, reg, &buf[0]) < 0) {
        return -1;
    }
    if (read_byte(fd, addr, reg + 1, &buf[1]) < 0) {
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to calculate the tilt-compensated heading
static float calculate_heading(uint16_t ax, uint16_t ay, uint16_t az, uint16_t mx, uint16_t my, uint16_t mz) {
    // Calculate the pitch and roll angles
    float pitch = atan2(ay, sqrt(ax * ax + az * az));
    float roll = atan2(-ax, ay);

    // Calculate the magnetic field vector in the device's local coordinate system
    float mx_local = mx * cos(pitch) + mz * sin(pitch) * sin(roll);
    float my_local = my * cos(pitch) + mz * sin(pitch) * cos(roll);

    // Calculate the heading
    float heading = atan2(my_local, mx_local);
    if (heading < 0) {
        heading += 2 * M_PI;
    }

    return heading;
}

// Signal handler for SIGINT and SIGTERM
static void sigint_handler(int sig) {
    // Close the I2C handles
    i2c_close(I2C_BUS);
    // Terminate pigpio
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open the I2C bus
    int fd = i2cOpen(I2C_BUS, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Initialize the accelerometer
    if (write_byte(fd, ACCEL_ADDR, ACCEL_CTRL_REG1_A, 0x27) < 0) {
        i2c_close(fd);
        return 1;
    }

    // Initialize the magnetometer
    if (write_byte(fd, MAG_ADDR, MAG_MR_REG_M, 0x00) < 0) {
        i2c_close(fd);
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("compass_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        i2c_close(fd);
        return 1;
    }

    // Write the CSV header
    fprintf(log_file, "%s", CSV_HEADER);

    // Set up the signal handler
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Read the accelerometer data
        uint16_t ax, ay, az;
        if (read_word(fd, ACCEL_ADDR, ACCEL_OUT_X_L_A, &ax) < 0 || read_word(fd, ACCEL_ADDR, ACCEL_OUT_X_L_A + 2, &ay) < 0 || read_word(fd, ACCEL_ADDR, ACCEL_OUT_X_L_A + 4, &az) < 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            break;
        }

        // Read the magnetometer data
        uint16_t mx, my, mz;
        if (read_word(fd, MAG_ADDR, MAG_OUT_X_H_M, &mx) < 0 || read_word(fd, MAG_ADDR, MAG_OUT_X_H_M + 2, &my) < 0 || read_word(fd, MAG_ADDR, MAG_OUT_X_H_M + 4, &mz) < 0) {
            fprintf(stderr, "Error reading magnetometer data\n");
            break;
        }

        // Calculate the tilt-compensated heading
        float heading = calculate_heading(ax, ay, az, mx, my, mz);

        // Log the data
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.6f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, ax / 16384.0, ay / 16384.0, az / 16384.0, mx / 10.0, my / 10.0, mz / 10.0);

        // Sleep for 100 ms
        usleep(SAMPLE_RATE);
    }

    // Close the log file
    fclose(log_file);

    // Close the I2C handle
    i2c_close(fd);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

