#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <gpiod.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000
#define SPI_BITS 16
#define REG_X_GYRO 0x04
#define REG_Y_GYRO 0x06
#define REG_Z_GYRO 0x08
#define REG_X_ACCEL 0x0A
#define REG_Y_ACCEL 0x0C
#define REG_Z_ACCEL 0x0E
#define SENS_GYRO 0.005
#define SENS_ACCEL 0.00025
#define DELAY_US 40
#define SAMPLE_RATE 100
#define CSV_FILE "imu_data.csv"

volatile bool running = true;

void cleanup() {
    if (spiClose(SPI_CHANNEL) != 0) {
        fprintf(stderr, "Error closing SPI channel\n");
    }
    if (fclose(f) != 0) {
        fprintf(stderr, "Error closing CSV file\n");
    }
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio\n");
    }
}

void sig_handler(int sig) {
    running = false;
}

int main() {
    int fd;
    FILE *f;

    if ((fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Error initialising pigpio\n");
        return 1;
    }

    if (gpioSetMode(fd, 8, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(fd, 8, 1) != 0) {
        fprintf(stderr, "Error setting GPIO high\n");
        gpioTerminate();
        return 1;
    }

    if ((f = fopen(CSV_FILE, "w")) == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(f, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    if ((fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS)) < 0) {
        fprintf(stderr, "Error opening SPI channel\n");
        fclose(f);
        gpioTerminate();
        return 1;
    }

    atexit(cleanup);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (running) {
        uint16_t data;
        uint8_t address;
        uint32_t timestamp;

        timestamp = (uint32_t)time(NULL) * 1000;

        for (address = REG_X_GYRO; address <= REG_Z_ACCEL; address++) {
            if (spiXfer(fd, 0x0000, &data, SPI_BITS, SPI_MODE) < 0) {
                fprintf(stderr, "Error reading from SPI channel\n");
                continue;
