#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_BUS 0
#define CS_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define REG_GYRO_X 0x04
#define REG_GYRO_Y 0x06
#define REG_GYRO_Z 0x08
#define REG_ACCEL_X 0x0A
#define REG_ACCEL_Y 0x0C
#define REG_ACCEL_Z 0x0E

int main() {
    int spi_fd, cs_fd;
    struct spi_ioc_transfer xfer;
    uint8_t reg_addr;
    uint16_t data;
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Initialize GPIO line for chip-select
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    line = gpiod_chip_get_line(chip, CS_PIN);
    if (!line) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        return 1;
    }

    ret = gpiod_line_request_output(line, 0);
    if (ret) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_output");
        return 1;
    }

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        perror("open");
        return 1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret) {
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        perror("ioctl(SPI_IOC_WR_MODE)");
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret) {
        close(spi_fd);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        return 1;
    }

    // Main loop
    while (1) {
        // Select chip
        gpiod_line_set_value(line, 1);

        // Read gyroscope data
        reg_addr = (REG_GYRO_X | 0x80);
        xfer.tx_buf = (uint64_t)&reg_addr;
        xfer.rx_buf = (uint64_t)&data;
        xfer.len = 2;
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = 16;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret) {
            close(spi_fd);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            perror("ioctl(SPI_IOC_MESSAGE)");
            return 1;
        }

        printf("Gyroscope X: %f dps\n", (float)data >> 8 & 0xFF * 0.02);
        printf("Gyroscope Y: %f dps\n", (float)data & 0xFF * 0.02);
        printf("Gyroscope Z: %f dps\n", (float)(data >> 8 & 0xFF) * 0.02);

        // Read accelerometer data
        reg_addr = (REG_ACCEL_X | 0x80);
        xfer.tx_buf = (uint64_t)&reg_addr;
        xfer.rx_buf = (uint64_t)&data;
        xfer.len = 2;
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = 16;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
        if (ret) {
            close(spi_fd);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            perror("ioctl(SPI_IOC_MESSAGE)");
            return 1;
        }

        printf("Accelerometer X: %f g\n", (float)data >> 8 & 0xFF * 0.00025);
        printf("Accelerometer Y: %f g\n", (float)data & 0xFF * 0.00025);
        printf("Accelerometer Z: %f g\n", (float)(data >> 8 & 0xFF) * 0.00025);

        // Deselect chip
        gpiod_line_set_value(line, 0);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    close(spi_fd);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

