        xfer.tx_buf = (uint64_t)&reg_addr;
        xfer.rx_buf = (uint64_t)&data;
        xfer.len = 2;
        xfer.speed_hz = SPI_SPEED;
        xfer.bits_per_word = 16;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &xfer);
