#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define WHO_AM_I_REG 0x75
#define PWR_MGMT_1_REG 0x6B
#define ACCEL_CONFIG_REG 0x1C
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    int retries = 0;
    int retry_max = 3;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return 1;
    }

    // Verify sensor presence
    uint8_t who_am_i;
    while (retry_max-- > 0) {
        if (read(i2c_fd, &who_am_i, 1) != 1) {
            if (errno == EIO) {
                // Bus error, try again
                continue;
            } else if (errno == EAGAIN) {
                // Transient read failure, try again
                continue;
            } else {
                // Other error, give up
                perror("Failed to read WHO_AM_I register");
                close(i2c_fd);
                return 1;
            }
        }
        if (who_am_i != 0x86) {
            // Sensor not present, give up
            perror("Sensor not present");
            close(i2c_fd);
            return 1;
        }
        break;
    }

    // Initialize sensor
    uint8_t pwr_mgmt_1 = 0x00;
    if (write(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        perror("Failed to write PWR_MGMT_1 register");
        close(i2c_fd);
        return 1;
    }

    uint8_t accel_config = 0x00;
    if (write(i2c_fd, &accel_config, 1) != 1) {
        perror("Failed to write ACCEL_CONFIG register");
        close(i2c_fd);
        return 1;
    }

    uint8_t gyro_config = 0x00;
    if (write(i2c_fd, &gyro_config, 1) != 1) {
        perror("Failed to write GYRO_CONFIG register");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read accelerometer data
        uint8_t accel_xout_h, accel_xout_l, accel_yout_h, accel_yout_l, accel_zout_h, accel_zout_l;
        while (retry_max-- > 0) {
            if (read(i2c_fd, &accel_xout_h, 1) != 1) {
                if (errno == EIO) {
                    // Bus error, try again
                    continue;
                } else if (errno == EAGAIN) {
                    // Transient read failure, try again
                    continue;
                } else {
                    // Other error, give up
                    perror("Failed to read ACCEL_XOUT_H register");
                    close(i2c_fd);
                    return 1;
                }
            }
            if (read(i2c_fd, &accel_xout_l, 1) != 1) {
                perror("Failed to read ACCEL_XOUT_L register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &accel_yout_h, 1) != 1) {
                perror("Failed to read ACCEL_YOUT_H register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &accel_yout_l, 1) != 1) {
                perror("Failed to read ACCEL_YOUT_L register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &accel_zout_h, 1) != 1) {
                perror("Failed to read ACCEL_ZOUT_H register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &accel_zout_l, 1) != 1) {
                perror("Failed to read ACCEL_ZOUT_L register");
                close(i2c_fd);
                return 1;
            }
            break;
        }

        // Read gyroscope data
        uint8_t gyro_xout_h, gyro_xout_l, gyro_yout_h, gyro_yout_l, gyro_zout_h, gyro_zout_l;
        while (retry_max-- > 0) {
            if (read(i2c_fd, &gyro_xout_h, 1) != 1) {
                if (errno == EIO) {
                    // Bus error, try again
                    continue;
                } else if (errno == EAGAIN) {
                    // Transient read failure, try again
                    continue;
                } else {
                    // Other error, give up
                    perror("Failed to read GYRO_XOUT_H register");
                    close(i2c_fd);
                    return 1;
                }
            }
            if (read(i2c_fd, &gyro_xout_l, 1) != 1) {
                perror("Failed to read GYRO_XOUT_L register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &gyro_yout_h, 1) != 1) {
                perror("Failed to read GYRO_YOUT_H register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &gyro_yout_l, 1) != 1) {
                perror("Failed to read GYRO_YOUT_L register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &gyro_zout_h, 1) != 1) {
                perror("Failed to read GYRO_ZOUT_H register");
                close(i2c_fd);
                return 1;
            }
            if (read(i2c_fd, &gyro_zout_l, 1) != 1) {
                perror("Failed to read GYRO_ZOUT_L register");
                close(i2c_fd);
                return 1;
            }
            break;
        }

        // Print raw data
        printf("Accelerometer: %04x %04x %04x %04x %04x %04x\n",
               (uint16_t)accel_xout_h << 8 | accel_xout_l,
               (uint16_t)accel_yout_h << 8 | accel_yout_l,
               (uint16_t)accel_zout_h << 8 | accel_zout_l,
               (uint16_t)gyro_xout_h << 8 | gyro_xout_l,
               (uint16_t)gyro_yout_h << 8 | gyro_yout_l,
               (uint16_t)gyro_zout_h << 8 | gyro_zout_l);

        // Sleep for 50 ms
        usleep(50000);
    }

    // Clean up
    close(i2c_fd);
    return 0;
