#define I2C_BUS 1
#define I2C_ADDRESS 0x53
#define LED_PIN 17
#define LOG_FILE "impact_log.txt"
#define POLL_INTERVAL 10  // ms
#define IMPACT_THRESHOLD 2.5  // g
#define SCALE_FACTOR 256  // LSB/g

// Function to read a byte from the ADXL345
uint8_t read_byte(int fd, uint8_t reg) {
    uint8_t data;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_read_byte(fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        exit(EXIT_FAILURE);
    }
    return data;
}

// Function to read 2 bytes from the ADXL345
uint16_t read_word(int fd, uint8_t reg) {
    uint16_t data;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_read_byte_data(fd, reg, (uint8_t*)&data) < 0) {
        perror("i2c_smbus_read_byte_data");
        exit(EXIT_FAILURE);
    }
    return data;
}

// Function to write a byte to the ADXL345
void write_byte(int fd, uint8_t reg, uint8_t data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte_data(fd, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(EXIT_FAILURE);
    }
}

// Function to write 2 bytes to the ADXL345
void write_word(int fd, uint8_t reg, uint16_t data) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte_data(fd, reg, (uint8_t)(data >> 8)) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(EXIT_FAILURE);
    }
    if (i2c_smbus_write_byte_data(fd, reg + 1, (uint8_t)data) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(EXIT_FAILURE);
    }
}

// Function to calculate the acceleration magnitude
float calculate_magnitude(uint16_t x, uint16_t y, uint16_t z) {
    return sqrt((float)x * x + (float)y * y + (float)z * z) / SCALE_FACTOR;
}

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    close(i2c_fd);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        exit(EXIT_FAILURE);
    }

    // Set up the LED pin as an output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open the I2C bus
    if ((i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR)) < 0) {
        perror("open");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Verify the ADXL345 device ID
    if (read_byte(i2c_fd, 0x00) != 0xE5) {
        fprintf(stderr, "Invalid ADXL345 device ID\n");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Configure the ADXL345 for full-resolution mode at the +-2g range
    write_byte(i2c_fd, 0x2D, 0x0A);  // Data format: 16-bit, right-justified
    write_byte(i2c_fd, 0x31, 0x0A);  // Data rate: 1600 Hz
    write_byte(i2c_fd, 0x2D, 0x08);  // Power control: normal mode

    // Set up the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    if ((log_fd = fopen(LOG_FILE, "a")) == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (1) {
        // Read the X, Y, and Z acceleration values
        uint16_t x = read_word(i2c_fd, 0x32);
        uint16_t y = read_word(i2c_fd, 0x34);
        uint16_t z = read_word(i2c_fd, 0x36);

        // Calculate the acceleration magnitude
        float magnitude = calculate_magnitude(x, y, z);

        // Check if the magnitude exceeds the threshold
        if (magnitude > IMPACT_THRESHOLD) {
            // Turn on the LED
            gpioWrite(LED_PIN, 1);

            // Wait for 500 ms
            usleep(500000);

            // Turn off the LED
            gpioWrite(LED_PIN, 0);

            // Log the impact
            fprintf(log_fd, "%f %d %d %d\n", time(NULL), (int)magnitude, (int)x, (int)y);
        }

        // Wait for the next poll interval
        usleep(POLL_INTERVAL * 1000);
    }

    // Close the log file
    fclose(log_fd);

    // Close the I2C bus
    close(i2c_fd);

    // Terminate the GPIO library
    gpioTerminate();

    return EXIT_SUCCESS;
}

