#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x68
#define WHO_AM_I_REG 0x75
#define ACCEL_CONFIG_REG 0x1D
#define GYRO_CONFIG_REG 0x1B
#define ACCEL_XOUT_H_REG 0x3B
#define ACCEL_XOUT_L_REG 0x3C
#define ACCEL_YOUT_H_REG 0x3D
#define ACCEL_YOUT_L_REG 0x3E
#define ACCEL_ZOUT_H_REG 0x3F
#define ACCEL_ZOUT_L_REG 0x40
#define GYRO_XOUT_H_REG 0x43
#define GYRO_XOUT_L_REG 0x44
#define GYRO_YOUT_H_REG 0x45
#define GYRO_YOUT_L_REG 0x46
#define GYRO_ZOUT_H_REG 0x47
#define GYRO_ZOUT_L_REG 0x48

void sigint_handler(int sig) {
    if (i2cClose(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
    }
    pigpio_stop();
    fclose(fp);
    exit(0);
}

int main() {
    int fd = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (i2cWriteByte(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up the device\n");
        i2cClose(fd);
        return 1;
    }

    if (i2cWriteByte(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set accelerometer configuration\n");
        i2cClose(fd);
        return 1;
    }

    if (i2cWriteByte(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope configuration\n");
        i2cClose(fd);
        return 1;
    }

    if (i2cReadByte(fd, WHO_AM_I_REG) != 0x12) {
        fprintf(stderr, "Device ID mismatch\n");
        i2cClose(fd);
        return 1;
    }

    FILE *fp = fopen("imu_log.csv", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(fd);
        return 1;
    }

    fprintf(fp, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        i2cClose(fd);
        return 1;
    }

    while (1) {
        usleep(100000);

        uint8_t accel_data[6];
        if (i2cReadI2CBlockData(fd, ACCEL_XOUT_H_REG, accel_data, 6) < 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            break;
        }

        uint8_t gyro_data[6];
        if (i2cReadI2CBlockData(fd, GYRO_XOUT_H_REG, gyro_data, 6) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            break;
        }

        uint16_t accel_x = (accel_data[1] << 8) | accel_data[0];
        uint16_t accel_y = (accel_data[3] << 8) | accel_data[2];
        uint16_t accel_z = (accel_data[5] << 8) | accel_data[4];

        uint16_t gyro_x = (gyro_data[1] << 8) | gyro_data[0];
        uint16_t gyro_y = (gyro_data[3] << 8) | gyro_data[2];
        uint16_t gyro_z = (gyro_data[5] << 8) | gyro_data[4];

        fprintf(fp, "%lu,%d,%d,%d,%d,%d,%d\n", time(NULL), accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
    }

    fclose(fp);
    i2cClose(fd);
    return 0;
}

