#define I2C_ADDRESS 0x1D
#define WHO_AM_I_REG 0x0D
#define ACCEL_X_REG 0x00
#define ACCEL_Y_REG 0x01
#define ACCEL_Z_REG 0x02
#define LED_PIN 17
#define THRESHOLD 2000
#define LOG_FILE "impact_log.txt"

int i2c_fd;
int led_fd;
char log_entry[64];

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
}

void init_led() {
    led_fd = gpioInitialise();
    if (led_fd < 0) {
        perror("Failed to initialize GPIO");
        exit(1);
    }
    gpioSetMode(led_fd, LED_PIN, GPIO_OUTPUT);
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void close_led() {
    if (led_fd >= 0) {
        gpioTerminate(led_fd);
        led_fd = -1;
    }
}

void read_acceleration(int* x, int* y, int* z) {
    struct i2c_msg msg;
    struct i2c_msg msg2;
    char buffer[2];

    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = (uint8_t*) &ACCEL_X_REG;
    msg2.addr = I2C_ADDRESS;
    msg2.flags = I2C_M_RD;
    msg2.len = 2;
    msg2.buf = buffer;

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    if (i2c_transfer(i2c_fd, &msg, 1, &msg2, 2) < 0) {
        perror("Failed to read acceleration data");
        exit(1);
    }

    *x = (int16_t) ((buffer[0] << 8) | buffer[1]) / 16;
    msg.buf = (uint8_t*) &ACCEL_Y_REG;
    if (i2c_transfer(i2c_fd, &msg, 1, &msg2, 2) < 0) {
        perror("Failed to read acceleration data");
        exit(1);
    }
    *y = (int16_t) ((buffer[0] << 8) | buffer[1]) / 16;
    msg.buf = (uint8_t*) &ACCEL_Z_REG;
    if (i2c_transfer(i2c_fd, &msg, 1, &msg2, 2) < 0) {
        perror("Failed to read acceleration data");
        exit(1);
    }
    *z = (int16_t) ((buffer[0] << 8) | buffer[1]) / 16;
}

void check_impact(int x, int y, int z) {
    double magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > THRESHOLD) {
        gpioWrite(led_fd, 1);
        sleep(0.5);
        gpioWrite(led_fd, 0);
        time_t now = time(NULL);
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S", localtime(&now));
        FILE* log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Failed to open log file");
            exit(1);
        }
        fprintf(log_file, "%s: Impact detected (x=%d, y=%d, z=%d)\n", log_entry, x, y, z);
        fclose(log_file);
    }
}

int main() {
    init_i2c();
    init_led();

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        exit(1);
    }

    char buffer[1];
    struct i2c_msg msg;
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = buffer;

    if (i2c_transfer(i2c_fd, &msg, 1, NULL, 0) < 0) {
        perror("Failed to read WHO_AM_I register");
        exit(1);
    }

    if (buffer[0] != 0x1A) {
        fprintf(stderr, "Sensor identity mismatch (expected 0x1A, got 0x%02x)\n", buffer[0]);
        exit(1);
    }

    while (1) {
        int x, y, z;
        read_acceleration(&x, &y, &z);
        check_impact(x, y, z);
        sleep(0.1);
    }

    close_i2c();
    close_led();

    return 0;
}

void sigint_handler(int sig) {
    close_i2c();
    close_led();
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    return main();
}

