#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x35
#define REG_X 0x10
#define REG_Y 0x11
#define REG_Z 0x12
#define CSV_FILE "magnetic_field_log.csv"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    int i2c_fd;
    char csv_file[256];
    FILE *csv;
    uint16_t x, y, z;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    struct i2c_msg msgs[2];
    struct tm *timeinfo;
    time_t rawtime;

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Check if CSV file exists, create it if not
    if (access(CSV_FILE, F_OK) == -1) {
        csv = fopen(CSV_FILE, "w");
        if (csv == NULL) {
            perror("Failed to open CSV file for writing");
            exit(1);
        }
        fprintf(csv, "timestamp,x,y,z\n");
        fclose(csv);
    } else {
        csv = fopen(CSV_FILE, "a");
        if (csv == NULL) {
            perror("Failed to open CSV file for appending");
            exit(1);
        }
    }

    // Set up I2C message
    msgs[0].addr = I2C_ADDRESS;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = (uint8_t *)&REG_X;

    msgs[1].addr = I2C_ADDRESS;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len = 2;
    msgs[1].buf = (uint8_t *)&x;

    while (running) {
        // Read X, Y, and Z registers
        i2c_data.msgs = msgs;
        i2c_data.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read I2C registers");
            continue;
        }

        // Read Y register
        msgs[0].len = 1;
        msgs[0].buf = (uint8_t *)&REG_Y;
        msgs[1].len = 2;
        msgs[1].buf = (uint8_t *)&y;
        i2c_data.msgs = msgs;
        i2c_data.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read I2C registers");
            continue;
        }

        // Read Z register
        msgs[0].len = 1;
        msgs[0].buf = (uint8_t *)&REG_Z;
        msgs[1].len = 2;
        msgs[1].buf = (uint8_t *)&z;
        i2c_data.msgs = msgs;
        i2c_data.nmsgs = 2;
        if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
            perror("Failed to read I2C registers");
            continue;
        }

        // Convert 16-bit little-endian values to big-endian
        x = (x << 8) | (x >> 8);
        y = (y << 8) | (y >> 8);
        z = (z << 8) | (z >> 8);

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(csv_file, sizeof(csv_file), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to CSV file
        fprintf(csv, "%s,%d,%d,%d\n", csv_file, x, y, z);
        fflush(csv);

        // Sleep for 1 second
        sleep(1);
    }

    // Close I2C file descriptor and CSV file
    close(i2c_fd);
    fclose(csv);

    return 0;
}

