// Function to read a single byte from the ADXL345
uint8_t read_byte(int i2c_fd, uint8_t reg) {
    uint8_t data;
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte(i2c_fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_byte(i2c_fd, &data) < 0) {
        perror("i2c_smbus_read_byte");
        exit(1);
    }
    return data;
}

// Function to write a single byte to the ADXL345
void write_byte(int i2c_fd, uint8_t reg, uint8_t data) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte_data(i2c_fd, reg, data) < 0) {
        perror("i2c_smbus_write_byte_data");
        exit(1);
    }
}

// Function to read 6 bytes from the ADXL345
void read_block(int i2c_fd, uint8_t reg, uint8_t* data) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(1);
    }
    if (i2c_smbus_write_byte(i2c_fd, reg) < 0) {
        perror("i2c_smbus_write_byte");
        exit(1);
    }
    if (i2c_smbus_read_i2c_block_data(i2c_fd, reg, 6, data) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        exit(1);
    }
}

// Function to check if the freefall bit is set in INT_SOURCE
bool is_freefall(int i2c_fd) {
    uint8_t data;
    read_byte(i2c_fd, 0x30);
    return (data & (1 << 2)) != 0;
}

// Function to log a freefall event
void log_freefall(int i2c_fd, uint8_t* data) {
    time_t now = time(NULL);
    struct tm* tm = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3d", tm);
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data[0], data[1], data[2]);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        exit(1);
    }

    // Check device ID
    uint8_t data;
    write_byte(i2c_fd, 0x00, 0x00);
    if (read_byte(i2c_fd, 0x00) != 0xE5) {
        fprintf(stderr, "Invalid device ID\n");
        close(i2c_fd);
        exit(1);
    }

    // Put sensor in standby
    write_byte(i2c_fd, 0x2D, 0x00);

    // Configure sensor
    write_byte(i2c_fd, 0x1D, 0x0A);  // THRESH_FF
    write_byte(i2c_fd, 0x1E, 0x20);  // TIME_FF
    write_byte(i2c_fd, 0x2E, 0x04);  // INT_ENABLE
    write_byte(i2c_fd, 0x2F, 0x00);  // INT_MAP
    write_byte(i2c_fd, 0x2D, 0x08);  // POWER_CTL

    // Request falling-edge interrupt on GPIO17
    struct gpiod_line_request req;
    req.consumer = "freefall";
    req.request_type = GPIOD_LINE_REQ_DIR_OUT;
    req.line = GPIO_PIN;
    req.flags = GPIOD_LINE_REQ_FLAG_ACTIVE_LOW;
    int gpio_fd = gpiod_open("/sys/class/gpio/export");
    if (gpio_fd < 0) {
        perror("gpiod_open");
        close(i2c_fd);
        exit(1);
    }
    if (gpiod_line_request(gpio_fd, &req) < 0) {
        perror("gpiod_line_request");
        close(gpio_fd);
        close(i2c_fd);
        exit(1);
    }
    gpiod_line_direction(gpio_fd, GPIOD_LINE_REQ_DIR_OUT);
    gpiod_line_set_value(gpio_fd, 1);

    // Open log file
    FILE* log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        perror("fopen");
        close(i2c_fd);
        gpiod_close(gpio_fd);
        exit(1);
    }
    fprintf(log_file, "timestamp,X,Y,Z\n");
    fflush(log_file);
    fclose(log_file);

    // Poll for interrupts
    struct gpiod_line_event event;
    while (1) {
        if (gpiod_line_event(gpio_fd, &event) < 0) {
            perror("gpiod_line_event");
            break;
        }
        if (event.event == GPIOD_LINE_EVENT_RISING_EDGE) {
            if (is_freefall(i2c_fd)) {
                uint8_t data[6];
                read_block(i2c_fd, 0x32, data);
                log_freefall(i2c_fd, data);
