        }
    }

    // Disable interrupts and close resources
    gpiod_line_direction(gpio_fd, GPIOD_LINE_REQ_DIR_IN);
    gpiod_line_set_value(gpio_fd, 0);
    gpiod_line_release(gpio_fd);
    gpiod_close(gpio_fd);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

