#define ACCEL_RANGE 2
#define GYRO_ODR 104
#define GYRO_RANGE 250
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define WINDOW_SIZE 1.0
#define CSV_FILE "motion_log.txt"

// Define state machine states
