    IDLE,
    FREEFALL,
    IMPACT
} state_t;

// Define signal handler for SIGINT and SIGTERM
void sig_handler(int sig) {
    // Release I2C bus and GPIO resources
    gpio_i2c_close(I2C_BUS);
    gpio_cleanup();
    exit(0);
}

int main() {
    // Initialize GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize I2C bus
    if (gpio_i2c_init(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to initialize I2C bus\n");
        gpio_cleanup();
        return 1;
    }

    // Set up I2C bus pins
    if (gpioSetMode(2, PI_INPUT) < 0 || gpioSetMode(3, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up I2C bus pins\n");
        gpio_i2c_close(I2C_BUS);
        gpio_cleanup();
        return 1;
    }

    // Check if sensor is present
    uint8_t who_am_i;
    if (gpio_i2c_read(I2C_BUS, I2C_ADDRESS, 0x0F, &who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        gpio_i2c_close(I2C_BUS);
        gpio_cleanup();
        return 1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "Sensor not present\n");
        gpio_i2c_close(I2C_BUS);
        gpio_cleanup();
        return 1;
    }

    // Configure sensor
    uint8_t reg[2];
    reg[0] = 0x10; // CTRL_REG1
    reg[1] = (ACCEL_ODR << 5) | (ACCEL_RANGE << 3) | (GYRO_ODR << 1) | GYRO_RANGE;
    if (gpio_i2c_write(I2C_BUS, I2C_ADDRESS, reg, 2) < 0) {
        fprintf(stderr, "Failed to configure sensor\n");
        gpio_i2c_close(I2C_BUS);
        gpio_cleanup();
        return 1;
    }

    // Open CSV file for logging
    FILE *fp = fopen(CSV_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpio_i2c_close(I2C_BUS);
        gpio_cleanup();
        return 1;
    }

    // Initialize state machine
    state_t state = IDLE;
    double last_timestamp = 0.0;
    double last_accel_magnitude = 0.0;

    // Main loop
    while (1) {
        // Read sensor data
        uint8_t data[6];
        if (gpio_i2c_read(I2C_BUS, I2C_ADDRESS, 0x00, data, 6) < 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            break;
        }

        // Calculate acceleration and gyroscope values
        int16_t accel_x = (data[0] << 8) | data[1];
        int16_t accel_y = (data[2] << 8) | data[3];
        int16_t accel_z = (data[4] << 8) | data[5];
        int16_t gyro_x = (data[0] << 8) | data[1];
        int16_t gyro_y = (data[2] << 8) | data[3];
        int16_t gyro_z = (data[4] << 8) | data[5];

        // Calculate acceleration magnitude
        double accel_magnitude = sqrt(pow(accel_x / 16384.0, 2) + pow(accel_y / 16384.0, 2) + pow(accel_z / 16384.0, 2));

        // Update state machine
        if (state == IDLE) {
            if (accel_magnitude < FREEFALL_THRESHOLD) {
                state = FREEFALL;
                last_timestamp = time(NULL);
                last_accel_magnitude = accel_magnitude;
            }
        } else if (state == FREEFALL) {
            if (accel_magnitude > IMPACT_THRESHOLD) {
                state = IMPACT;
            } else if (time(NULL) - last_timestamp > WINDOW_SIZE) {
                state = IDLE;
            }
        } else if (state == IMPACT) {
            if (accel_magnitude < IMPACT_THRESHOLD) {
                state = IDLE;
            }
        }

        // Log data
        double timestamp = time(NULL);
        fprintf(fp, "%f,%f,%f,%f,%f,%f,%f,%f\n", timestamp, accel_x / 16384.0, accel_y / 16384.0, accel_z / 16384.0, gyro_x / 131.0, gyro_y / 131.0, gyro_z / 131.0, accel_magnitude);
        fflush(fp);

        // Sleep for 1ms
        usleep(1000);
    }

    // Close CSV file
    fclose(fp);

    // Release I2C bus and GPIO resources
    gpio_i2c_close(I2C_BUS);
    gpio_cleanup();

    return 0;
}

