#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS_PER_WORD 16
#define SPI_DUMMY 0
#define REG_X_GYRO_OUT 0x14
#define REG_WHO_AM_I 0x0F
#define SCALE 0.0305

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close the SPI handle
    if (gpio_spi_close(SPI_CHANNEL) != 0) {
        fprintf(stderr, "Error closing SPI handle: %s\n", strerror(errno));
    }

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the log file
    FILE *log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Write the CSV header
    fprintf(log_file, "timestamp,angular_rate_x\n");

    // Initialize the SPI handle
    int spi_handle = gpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_BITS_PER_WORD, SPI_DUMMY);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI handle: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Check the WHO_AM_I register
    uint16_t who_am_i;
    if (gpio_spi_xfer(spi_handle, REG_WHO_AM_I | 0x80, &who_am_i, 2) != 2) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        gpio_spi_close(spi_handle);
        fclose(log_file);
        return 1;
    }
    if (who_am_i != 0x3F5A) {
        fprintf(stderr, "Error: WHO_AM_I register does not match expected value (0x3F5A), got 0x%04X\n", who_am_i);
        gpio_spi_close(spi_handle);
        fclose(log_file);
        return 1;
    }

    // Set up the signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handler: %s\n", strerror(errno));
        gpio_spi_close(spi_handle);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the X_GYRO_OUT register
        uint16_t x_gyro_out;
        if (gpio_spi_xfer(spi_handle, REG_X_GYRO_OUT | 0x80, &x_gyro_out, 2) != 2) {
            fprintf(stderr, "Error reading X_GYRO_OUT register: %s\n", strerror(errno));
            break;
        }

        // Scale the value
        float angular_rate = (float)x_gyro_out * SCALE;

        // Log the reading
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s,%.6f\n", timestamp, angular_rate);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close the SPI handle
    if (gpio_spi_close(spi_handle) != 0) {
        fprintf(stderr, "Error closing SPI handle: %s\n", strerror(errno));
    }

    // Close the log file
    fclose(log_file);

    return 0;
}

