int readData(int fd) {
    uint8_t data[6];
    if (i2cReadReg(fd, GYRO_OUT_X_L, data, 6) < 0) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to degrees per second
void convertData(uint8_t* data, float* gyro) {
    gyro[0] = (data[1] << 8) | data[0];
    gyro[1] = (data[3] << 8) | data[2];
    gyro[2] = (data[5] << 8) | data[4];
    for (int i = 0; i < 3; i++) {
        gyro[i] = (float)gyro[i] / 114.285;
    }
}

