    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2cWriteReg(fd, GYRO_CTRL_REG1, 0x0F, 1) >= 0) {
            break;
        }
        if (i < MAX_RETRIES - 1) {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
        }
    }
    if (i2cWriteReg(fd, GYRO_CTRL_REG4, 0x00, 1) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        i2cClose(fd);
        return 1;
    }

    // Open file for logging
    FILE* file = fopen("gyro_log.csv", "w");
    if (!file) {
        fprintf(stderr, "Error opening file for logging\n");
        i2cClose(fd);
        return 1;
    }

    // Write header row
    fprintf(file, "Timestamp,X,Y,Z\n");

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = SIG_IGN;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    // Main loop
    while (1) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp = tv.tv_sec * 1000000000 + tv.tv_usec * 1000;

        // Read data from gyroscope
        if (readData(fd) < 0) {
            fprintf(stderr, "Error reading data\n");
            break;
        }

        // Convert data to degrees per second
        uint8_t data[6];
        readData(fd);
        float gyro[3];
        convertData(data, gyro);

        // Log data
        fprintf(file, "%llu,%f,%f,%f\n", timestamp, gyro[0], gyro[1], gyro[2]);

        // Sleep for 10 ms
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    fclose(file);
    i2cClose(fd);
    gpioTerminate();
    return 0;
}

