// Flag to indicate whether to continue running the main loop
volatile int running = 1;

// SIGINT handler to set the running flag to 0
void sigint_handler(int sig) {
    running = 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio library\n");
        return 1;
    }

    // Set up the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Set up GPIO17 as an input with internal pull-up resistor
    if (gpioSetMode(17, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO17 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(17, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable internal pull-up resistor on GPIO17\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    FILE *log_file = fopen("flame_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Poll the sensor
        int value = gpioRead(17);
        if (value == PI_BAD_GPIO) {
            fprintf(log_file, "%s - Error reading sensor\n", ctime(&time(NULL)));
            fflush(log_file);
        } else {
            // Log the result
            fprintf(log_file, "%s - Flame detected: %s\n", ctime(&time(NULL)), value == 0 ? "YES" : "NO");
            fflush(log_file);

            // Print a fire alarm message if a flame is detected
            if (value == 0) {
                printf("FLAME DETECTED!\n");
            }
        }

        // Sleep for 500 ms
        usleep(500000);
    }

    // Close the log file if open
    if (log_file) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

