#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDRESS 0x53
#define CSV_FILE "vibration_log.csv"
#define SAMPLE_INTERVAL 100000 // 100 ms in microseconds
#define REG_X_LSB 0x28
#define REG_X_MSB 0x29
#define REG_Y_LSB 0x2A
#define REG_Y_MSB 0x2B
#define REG_Z_LSB 0x2C
#define REG_Z_MSB 0x2D

// Function to read a single byte from the I2C bus
uint8_t read_byte(int fd, uint8_t reg) {
    uint8_t data;
    if (ioctl(fd, I2C_SLAVE, I2C_SLAVE_ADDRESS) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return 0xFF; // Return an error value to indicate sensor-absent
    }
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        perror("i2c_smbus_read_byte_data");
        return 0xFF; // Return an error value to indicate sensor-absent
    }
    return data;
}

// Function to read a 16-bit signed value from the I2C bus
int16_t read_acceleration(int fd, uint8_t reg_lsb, uint8_t reg_msb) {
    uint8_t lsb = read_byte(fd, reg_lsb);
    uint8_t msb = read_byte(fd, reg_msb);
    if (lsb == 0xFF || msb == 0xFF) {
        return 0; // Return 0 to indicate sensor-absent
    }
    return (msb << 8) | lsb;
}

// Function to write a string to a file with a timestamp
void write_to_csv(FILE *file, const char *format, ...) {
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timestamp);
    fprintf(file, "%s,", timestamp_str);
    va_list args;
    va_start(args, format);
    vfprintf(file, format, args);
    va_end(args);
    fputc('\n', file);
}

// Signal handler to clean up resources on exit
void sigint_handler(int sig) {
    close(i2c_fd);
    fclose(csv_file);
    exit(0);
}

int main() {
    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open(I2C_BUS)");
        return 1;
    }

    // Open the CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("fopen(CSV_FILE)");
        close(i2c_fd);
        return 1;
    }

    // Write the header to the CSV file
    fprintf(csv_file, "Timestamp,X,Y,Z\n");

    // Install the signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Read the acceleration data
        int16_t x = read_acceleration(i2c_fd, REG_X_LSB, REG_X_MSB);
        int16_t y = read_acceleration(i2c_fd, REG_Y_LSB, REG_Y_MSB);
        int16_t z = read_acceleration(i2c_fd, REG_Z_LSB, REG_Z_MSB);

        // Write the data to the CSV file
        write_to_csv(csv_file, "%d,%d,%d", x, y, z);

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up resources
    close(i2c_fd);
    fclose(csv_file);
    return 0;
}

