#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MMA8452_ADDRESS 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define DATA_X_MSB_REG 0x01
#define DATA_X_LSB_REG 0x02
#define DATA_Y_MSB_REG 0x03
#define DATA_Y_LSB_REG 0x04
#define DATA_Z_MSB_REG 0x05
#define DATA_Z_LSB_REG 0x06

volatile bool exit_program = false;

void sigint_handler(int sig) {
    exit_program = true;
}

int main() {
    int i2c_fd;
    int log_fd;
    char filename[] = "fall_log.txt";
    struct i2c_msg msg;
    struct i2c_msg msg_read;
    uint8_t buffer[6];
    uint8_t who_am_i;
    uint8_t ctrl_reg1;
    uint16_t x, y, z;
    double tilt_angle;
    struct sigaction sa;

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Open log file
    log_fd = open(filename, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd < 0) {
        perror("Failed to open log file");
        close(i2c_fd);
        exit(1);
    }

    // Set up signal handler
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }

    // Verify sensor identity
    msg.addr = MMA8452_ADDRESS;
    msg.flags = 0;
    msg.buf = &who_am_i;
    msg.len = 1;
    msg_read.addr = MMA8452_ADDRESS;
    msg_read.flags = I2C_M_RD;
    msg_read.buf = &who_am_i;
    msg_read.len = 1;
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }
    if (i2c_transfer(i2c_fd, &msg, 1) < 0 || i2c_transfer(i2c_fd, &msg_read, 1) < 0) {
        perror("Failed to read WHO_AM_I register");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register does not match expected value\n");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }

    // Initialize sensor
    msg.addr = MMA8452_ADDRESS;
    msg.flags = 0;
    msg.buf = &ctrl_reg1;
    msg.len = 1;
    msg_read.addr = MMA8452_ADDRESS;
    msg_read.flags = I2C_M_RD;
    msg_read.buf = &ctrl_reg1;
    msg_read.len = 1;
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }
    ctrl_reg1 = 0x00; // Clear bit 0 to place in standby mode
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }
    ctrl_reg1 |= 0x08; // Set bits 3-5 to 100 Hz data rate
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }
    ctrl_reg1 |= 0x01; // Set bit 0 to switch to active mode
    if (i2c_transfer(i2c_fd, &msg, 1) < 0) {
        perror("Failed to write CTRL_REG1 register");
        close(i2c_fd);
        close(log_fd);
        exit(1);
    }

    while (!exit_program) {
        // Read data registers
        msg.addr = MMA8452_ADDRESS;
        msg.flags = 0;
        msg.buf = buffer;
        msg.len = 6;
        msg_read.addr = MMA8452_ADDRESS;
        msg_read.flags = I2C_M_RD;
        msg_read.buf = buffer;
        msg_read.len = 6;
        if (ioctl(i2c_fd, I2C_SLAVE, MMA8452_ADDRESS) < 0) {
            perror("Failed to set I2C slave address");
            break;
        }
        if (i2c_transfer(i2c_fd, &msg, 6) < 0 || i2c_transfer(i2c_fd, &msg_read, 6) < 0) {
            perror("Failed to read data registers");
            break;
        }

        // Combine MSB/LSB and right-shift to form signed 12-bit values
        x = (buffer[DATA_X_MSB_REG] << 4) | (buffer[DATA_X_LSB_REG] >> 4);
        y = (buffer[DATA_Y_MSB_REG] << 4) | (buffer[DATA_Y_LSB_REG] >> 4);
        z = (buffer[DATA_Z_MSB_REG] << 4) | (buffer[DATA_Z_LSB_REG] >> 4);

        // Compute tilt angle
        tilt_angle = atan2(x, sqrt(y*y + z*z));

        // Log data if tilt angle exceeds 45 degrees
        if (fabs(tilt_angle) > M_PI/4) {
            char timestamp[20];
            time_t now;
            time(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            fprintf(log_fd, "%s %04x %04x %04x\n", timestamp, x, y, z);
            fsync(log_fd);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Close I2C file descriptor
    close(i2c_fd);

    // Close log file
    close(log_fd);

    return 0;
}

