#define CTRL_REG4 0x2D
#define OUT_X_L_REG 0x28
#define OUT_X_H_REG 0x29
#define OUT_Y_L_REG 0x2A
#define OUT_Y_H_REG 0x2B
#define OUT_Z_L_REG 0x2C
#define OUT_Z_H_REG 0x2D
#define MAG_SENSITIVITY 0.146
#define THRESHOLD 800

// Calibration constants
#define X_OFFSET -0.5
#define Y_OFFSET 0.2
#define Z_OFFSET 0.1
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Signal handler for SIGINT/SIGTERM
void sigint_handler(int sig) {
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    int i2c_fd;
    int retries = 0;
    int log_fd;
    FILE *log_file;
    char buffer[6];
    int16_t x, y, z;
    float x_mg, y_mg, z_mg;
    float total_mg;
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_data;

    // Open I2C device
    while ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        if (retries++ < 3) {
            perror("Failed to open I2C device");
            usleep(100000);
        } else {
            fprintf(stderr, "Failed to open I2C device after 3 retries\n");
            exit(1);
        }
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        exit(1);
    }

    // Configure sensor
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.buf = (uint8_t *)&CTRL_REG1;
    msg.len = 1;
    msg.buf[0] = 0x70;
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to write CTRL_REG1");
        close(i2c_fd);
        exit(1);
    }

    msg.buf = (uint8_t *)&CTRL_REG4;
    msg.len = 1;
    msg.buf[0] = 0x0C;
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to write CTRL_REG4");
        close(i2c_fd);
        exit(1);
    }

    msg.buf = (uint8_t *)&CTRL_REG3;
    msg.len = 1;
    msg.buf[0] = 0x00;
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to write CTRL_REG3");
        close(i2c_fd);
        exit(1);
    }

    // Verify sensor presence
    msg.buf = (uint8_t *)&WHO_AM_I_REG;
    msg.len = 1;
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read WHO_AM_I");
        close(i2c_fd);
        exit(1);
    }
    if (msg.buf[0] != 0x3D) {
        fprintf(stderr, "Sensor not present\n");
        close(i2c_fd);
