// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_CS_PIN 8
#define RESET_REGISTER 0x1F
#define POWER_CTL_REGISTER 0x2D
#define STATUS_REGISTER 0x04
#define PARTID_REGISTER 0x01
#define XDATA_REGISTER 0x08
#define YDATA_REGISTER 0x0B
#define ZDATA_REGISTER 0x0E
#define MEASUREMENT_MODE 0x01
#define RUN_BIT 0x80
#define STABLE_BIT 0x80
#define GAIN 0.0000039

// Function to handle signal interrupts
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        // Close the SPI handle
        gpio_spi_close(SPI_CHANNEL);
        // Close the file
        fclose(log_file);
        // Terminate pigpio
        gpioTerminate();
        exit(0);
    }
}

// Function to read data from the ADXL354B
int read_data(int register_address) {
    int data = 0;
    int retries = 0;
    while (retries < 5) {
        // Set the CS pin low
        gpioWrite(SPI_CS_PIN, 0);
        // Write the register address
        gpio_spi_write(SPI_CHANNEL, register_address, 1);
        // Write the read command
        gpio_spi_write(SPI_CHANNEL, 0x80, 1);
        // Read 3 bytes
        int bytes_read = gpio_spi_read(SPI_CHANNEL, &data, 3);
        // Check if the read was successful
        if (bytes_read == 3) {
            break;
        }
        retries++;
    }
    return data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the SPI channel
    if (gpio_spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_LSB_FIRST) < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Set the CS pin as an output
    gpioSetMode(SPI_CS_PIN, PI_OUTPUT);

    // Reset the ADXL354B
    gpioWrite(SPI_CS_PIN, 0);
    gpio_spi_write(SPI_CHANNEL, RESET_REGISTER, 0x52);
    usleep(1000);
    gpioWrite(SPI_CS_PIN, 1);

    // Check if the ADXL354B is present
    int part_id = read_data(PARTID_REGISTER);
    if (part_id != 0x1D) {
        fprintf(stderr, "ADXL354B not found\n");
        gpio_spi_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Set the measurement mode
    gpioWrite(SPI_CS_PIN, 0);
    gpio_spi_write(SPI_CHANNEL, POWER_CTL_REGISTER, 0x00);
    while (read_data(STATUS_REGISTER) & STABLE_BIT) {
        usleep(100);
    }
    gpio_spi_write(SPI_CHANNEL, POWER_CTL_REGISTER, MEASUREMENT_MODE);
    gpioWrite(SPI_CS_PIN, 1);

    // Open the log file
    FILE *log_file = fopen("vibration_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpio_spi_close(SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the data
        int x_data = read_data(XDATA_REGISTER);
        int y_data = read_data(YDATA_REGISTER);
        int z_data = read_data(ZDATA_REGISTER);

        // Calculate the acceleration
        float x_accel = (x_data & 0x00FF) | ((x_data & 0xFF00) << 8);
        x_accel = (x_accel * GAIN) * 2;
        float y_accel = (y_data & 0x00FF) | ((y_data & 0xFF00) << 8);
        y_accel = (y_accel * GAIN) * 2;
        float z_accel = (z_data & 0x00FF) | ((z_data & 0xFF00) << 8);
        z_accel = (z_accel * GAIN) * 2;

        // Log the data
        fprintf(log_file, "%f %f %f\n", x_accel, y_accel, z_accel);

        // Wait 100 ms
        usleep(100000);
    }

    // Close the SPI handle
    gpio_spi_close(SPI_CHANNEL);

    // Close the file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

