#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define IMU_SPI_CHANNEL 0
#define IMU_SPI_SPEED 1000000
#define IMU_SPI_MODE 3
#define IMU_SPI_LSBFIRST 0
#define IMU_SPI_BITS_PER_WORD 16
#define IMU_SPI_DELAY_US 10

#define IMU_GYRO_X_REG 0x04
#define IMU_GYRO_Y_REG 0x06
#define IMU_GYRO_Z_REG 0x08
#define IMU_ACCL_X_REG 0x0A
#define IMU_ACCL_Y_REG 0x0C
#define IMU_ACCL_Z_REG 0x0E

#define IMU_GYRO_SCALE 0.05
#define IMU_ACCL_SCALE 0.0025

#define LOG_FILE "imu_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void imu_read(uint8_t reg, uint16_t *data) {
    uint8_t buf[3];
    buf[0] = (reg & 0x80) | (reg & 0x7F);
    buf[1] = 0xFF; // dummy byte
    if (spiXfer(IMU_SPI_CHANNEL, buf, 2, data, 2, IMU_SPI_SPEED, IMU_SPI_MODE, IMU_SPI_LSBFIRST, IMU_SPI_BITS_PER_WORD, IMU_SPI_DELAY_US) != 2) {
        fprintf(stderr, "Error reading from IMU: spiXfer failed\n");
        return;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    if (spiOpen(IMU_SPI_CHANNEL, IMU_SPI_SPEED, IMU_SPI_MODE, IMU_SPI_LSBFIRST, IMU_SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Error opening SPI channel\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(IMU_SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");

    signal(SIGINT, sigint_handler);

    while (running) {
        uint16_t gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z;
        imu_read(IMU_GYRO_X_REG, &gyro_x);
        imu_read(IMU_GYRO_Y_REG, &gyro_y);
        imu_read(IMU_GYRO_Z_REG, &gyro_z);
        imu_read(IMU_ACCL_X_REG, &accl_x);
        imu_read(IMU_ACCL_Y_REG, &accl_y);
        imu_read(IMU_ACCL_Z_REG, &accl_z);

        uint64_t timestamp = (uint64_t)time(NULL) * 1000000000 + (uint64_t)clock_gettime(CLOCK_REALTIME, NULL).tv_nsec;
        fprintf(log_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp / 1000000.0, gyro_x * IMU_GYRO_SCALE, gyro_y * IMU_GYRO_SCALE, gyro_z * IMU_GYRO_SCALE, accl_x * IMU_ACCL_SCALE, accl_y * IMU_ACCL_SCALE, accl_z * IMU_ACCL_SCALE);
        fflush(log_file);

        usleep(IMU_SPI_DELAY_US * 1000);
    }

    fclose(log_file);
    spiClose(IMU_SPI_CHANNEL);
    gpioTerminate();

    return 0;
}

