        uint64_t timestamp = (uint64_t)time(NULL) * 1000000000 + (uint64_t)clock_gettime(CLOCK_REALTIME, NULL).tv_nsec;
        fprintf(log_file, "%llu,%f,%f,%f,%f,%f,%f\n", timestamp / 1000000.0, gyro_x * IMU_GYRO_SCALE, gyro_y * IMU_GYRO_SCALE, gyro_z * IMU_GYRO_SCALE, accl_x * IMU_ACCL_SCALE, accl_y * IMU_ACCL_SCALE, accl_z * IMU_ACCL_SCALE);
        fflush(log_file);

        usleep(IMU_SPI_DELAY_US * 1000);
    }

    fclose(log_file);
    spiClose(IMU_SPI_CHANNEL);
    gpioTerminate();

    return 0;
