#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Function to handle SIGINT (Ctrl+C) to ensure clean exit
void sigint_handler(int sig) {
    gpiod_line_release_all();
    exit(0);
}

int main() {
    // Set up signal handler for SIGINT
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the gpiochip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request GPIO17 and GPIO27 as input lines
    struct gpiod_line *line17, *line27;
    line17 = gpiod_chip_get_line(chip, 17);
    if (!line17) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        return 1;
    }
    line27 = gpiod_chip_get_line(chip, 27);
    if (!line27) {
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        return 1;
    }

    // Request both lines together for input
    if (gpiod_line_request_get_values(line17, line27, GPIOD_LINE_ACTIVE_LOW) == -1) {
        gpiod_line_release(line17);
        gpiod_line_release(line27);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_get_values");
        return 1;
    }

    // Main loop
    while (1) {
        // Poll both sensors every 100 ms
        struct gpiod_line_values values;
        if (gpiod_line_request_get_values(line17, line27, GPIOD_LINE_ACTIVE_LOW, &values) == -1) {
            gpiod_line_release(line17);
            gpiod_line_release(line27);
            gpiod_chip_close(chip);
            perror("gpiod_line_request_get_values");
            return 1;
        }

        // Log the obstacle detection status to the console with a timestamp
        time_t now = time(NULL);
        struct tm *lt = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);
        printf("%s: ", timestamp);
        printf("GPIO17: %d, GPIO27: %d\n", values.values[0], values.values[1]);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Release resources on exit
    gpiod_line_release(line17);
    gpiod_line_release(line27);
    gpiod_chip_close(chip);
    return 0;
}

