#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <libgpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_LSBFIRST 0
#define SPI_BITS_PER_WORD 16
#define MSC_CTRL 0x24
#define X_RATE 0x04
#define Y_RATE 0x06
#define Z_RATE 0x08
#define SCALE_FACTOR 0.02

int main() {
    int spi_fd, cs_fd;
    struct spi_ioc_transfer transfer;
    struct gpiod_line *cs_line;
    int ret;

    // Initialize SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    // Set SPI mode and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    // Initialize CS pin
    cs_fd = gpiod_chip_open("/dev/gpiochip0");
    if (cs_fd < 0) {
        perror("Failed to open GPIO chip");
        close(spi_fd);
        return 1;
    }

    cs_line = gpiod_chip_get_line(cs_fd, CS_PIN);
    if (!cs_line) {
        perror("Failed to get CS line");
        gpiod_chip_close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Set CS pin as output
    ret = gpiod_line_request_output(cs_line, "active-high");
    if (ret < 0) {
        perror("Failed to request CS line as output");
        gpiod_line_release(cs_line);
        gpiod_chip_close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Write to MSC_CTRL register to enable data ready mode
    transfer.tx_buf = NULL;
    transfer.rx_buf = NULL;
    transfer.len = 2;
    transfer.speed_hz = SPI_SPEED;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.cs_change = 1;
    transfer.delay_usecs = 0;
    transfer.cs_high = 0;
    transfer.cs_low = 0;
    transfer.bits_per_word = SPI_BITS_PER_WORD;
    transfer.mode = SPI_MODE;
    transfer.lsb_first = SPI_LSBFIRST;

    uint8_t msc_ctrl_data[] = {0x00, 0x00};
    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        perror("Failed to write to MSC_CTRL register");
        gpiod_line_release(cs_line);
        gpiod_chip_close(cs_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Select CS pin low
        gpiod_line_set_value(cs_line, 0);

        // Read X, Y, and Z rate registers
        transfer.tx_buf = (uint8_t *) &X_RATE;
        transfer.rx_buf = (uint8_t *) &X_RATE;
        transfer.len = 2;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret < 0) {
            perror("Failed to read X rate register");
            gpiod_line_release(cs_line);
            gpiod_chip_close(cs_fd);
            close(spi_fd);
            return 1;
        }

        transfer.tx_buf = (uint8_t *) &Y_RATE;
        transfer.rx_buf = (uint8_t *) &Y_RATE;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret < 0) {
            perror("Failed to read Y rate register");
            gpiod_line_release(cs_line);
            gpiod_chip_close(cs_fd);
            close(spi_fd);
            return 1;
        }

        transfer.tx_buf = (uint8_t *) &Z_RATE;
        transfer.rx_buf = (uint8_t *) &Z_RATE;
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret < 0) {
            perror("Failed to read Z rate register");
            gpiod_line_release(cs_line);
            gpiod_chip_close(cs_fd);
            close(spi_fd);
            return 1;
        }

        // Convert raw values to angular rates
        int16_t x_rate = (int16_t) ((X_RATE[0] << 8) | X_RATE[1]);
        int16_t y_rate = (int16_t) ((Y_RATE[0] << 8) | Y_RATE[1]);
        int16_t z_rate = (int16_t) ((Z_RATE[0] << 8) | Z_RATE[1]);
        float x_rate_deg = x_rate * SCALE_FACTOR;
        float y_rate_deg = y_rate * SCALE_FACTOR;
        float z_rate_deg = z_rate * SCALE_FACTOR;

        // Log results
        printf("X rate: %.2f deg/sec, Y rate: %.2f deg/sec, Z rate: %.2f deg/sec\n", x_rate_deg, y_rate_deg, z_rate_deg);

        // Select CS pin high
        gpiod_line_set_value(cs_line, 1);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Release resources
    gpiod_line_release(cs_line);
    gpiod_chip_close(cs_fd);
    close(spi_fd);

    return 0;
}

