#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x6B

// Define the WHO_AM_I register value
#define WHO_AM_I 0x0F

// Define the CTRL1_XL and CTRL2_G register values
#define CTRL1_XL 0x42
#define CTRL2_G 0x42

// Define the OUTX_L_G register address
#define OUTX_L_G 0x22

// Define the gyro and accel sensitivities
#define GYRO_SENSITIVITY 0.00875
#define ACCEL_SENSITIVITY 0.000061

// Function to handle SIGINT
void sigint_handler(int sig) {
    // Close the I2C handle
    if (i2cClose(I2C_BUS) != 0) {
        fprintf(stderr, "Error closing I2C handle\n");
    }
    // Terminate the pigpio library
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Install the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open the I2C bus
    if (i2cOpen(I2C_BUS, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
