        gpioTerminate();
        return 1;
    }
    if (gpioI2CWriteReg8(i2c, 0x1D, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG1\n");
        gpioI2CClose(i2c);
        gpioTerminate();
        return 1;
    }
    if (gpioI2CWriteReg8(i2c, 0x1D, 0x5C, 0x00) < 0) {
        fprintf(stderr, "Failed to write M_CTRL_REG2\n");
