#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <syslog.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x53
#define REG_X 0x32
#define REG_Y 0x33
#define REG_Z 0x34
#define REG_STATUS 0x00
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"

int i2c_fd = -1;
volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t* data, size_t len) {
    if (i2c_fd < 0) {
        return -1;
    }
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to I2C register");
        return -1;
    }
    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read from I2C register");
        return -1;
    }
    return 0;
}

void log_event(const char* message) {
    FILE* file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(file, "%s: %s\n", ctime(&time(NULL)), message);
    fclose(file);
}

int main() {
    if (i2c_open() < 0) {
        return 1;
    }

    signal(SIGINT, sigint_handler);

    uint8_t data[4];
    while (running) {
        if (i2c_read(REG_X, data, 4) < 0) {
            if (errno == EIO) {
                // Sensor absent
                syslog(LOG_INFO, "Sensor absent");
                log_event("Sensor absent");
            } else if (errno == EBUSY) {
                // Bus error
                syslog(LOG_INFO, "Bus error");
                log_event("Bus error");
            } else {
                perror("Failed to read from I2C register");
            }
            break;
        }

        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = 0; // Not used in this example

        double angle_x = atan2(y, z) * 180.0 / M_PI;
        double angle_y = atan2(x, z) * 180.0 / M_PI;

        if (fabs(angle_x) > TILT_THRESHOLD || fabs(angle_y) > TILT_THRESHOLD) {
            log_event("Tilt detected: X = %.2f, Y = %.2f", angle_x, angle_y);
        }

        usleep(100000);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

