#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL 1  // in milliseconds
#define WINDOW_SIZE 5000  // in milliseconds
#define WINDOW_INTERVAL 1000  // in milliseconds

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold = atoi(argv[1]);
    if (threshold <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d mode to input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    int high_count = 0;
    time_t last_window_end = time(NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_window_end >= WINDOW_SIZE / 1000) {
            if (high_count >= threshold) {
                fprintf(stderr, "ALERT: %d high-readings in %d seconds\n", high_count, WINDOW_SIZE / 1000);
            } else {
                fprintf(stderr, "Normal: %d high-readings in %d seconds\n", high_count, WINDOW_SIZE / 1000);
            }
            high_count = 0;
            last_window_end = current_time;
        }

        int value = gpioRead(GPIO_PIN);
        if (value == 1) {
            high_count++;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}

