    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d mode to input\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    int high_count = 0;
    time_t last_window_end = time(NULL);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_window_end >= WINDOW_SIZE / 1000) {
            if (high_count >= threshold) {
                fprintf(stderr, "ALERT: %d high-readings in %d seconds\n", high_count, WINDOW_SIZE / 1000);
            } else {
                fprintf(stderr, "Normal: %d high-readings in %d seconds\n", high_count, WINDOW_SIZE / 1000);
            }
            high_count = 0;
            last_window_end = current_time;
        }

        int value = gpioRead(GPIO_PIN);
        if (value == 1) {
            high_count++;
        }

        usleep(SAMPLE_INTERVAL * 1000);
    }

    gpioTerminate();
    return 0;
}
```

This code uses the `pigpio` library to monitor the state of GPIO17 on the Raspberry Pi 3 Model B+, and counts the number of high-readings within a 5-second window. It accepts a single command-line argument representing the minimum number of high-readings required to trigger an alert. The program runs in a continuous loop, printing a timestamped status line to stderr at the end of each 5-second window. It handles SIGINT and SIGTERM signals by terminating the `pigpio` library and exiting cleanly.

