#define DOOR_B 27

// Define the SIGINT/SIGTERM handler function
void sig_handler(int sig) {
    volatile sig_atomic_t exit_flag = 1;
}

int main() {
    // Initialize the SIGINT/SIGTERM handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize the random number generator
    srand(time(NULL));

    // Open the GPIO chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_error_str(errno));
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO17 and GPIO27 as outputs
    struct gpiod_line *line_a, *line_b;
    line_a = gpiod_chip_get_line(chip, DOOR_A);
    if (!line_a) {
        fprintf(stderr, "Failed to get line %d: %s\n", DOOR_A, gpiod_error_str(errno));
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line_a, 0) != 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", DOOR_A, gpiod_error_str(errno));
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    line_b = gpiod_chip_get_line(chip, DOOR_B);
    if (!line_b) {
        fprintf(stderr, "Failed to get line %d: %s\n", DOOR_B, gpiod_error_str(errno));
        gpiod_line_release(line_a);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line_b, 0) != 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", DOOR_B, gpiod_error_str(errno));
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Set both lines to LOW (locked)
    if (gpiod_line_set_value(line_a, 0) != 0) {
        fprintf(stderr, "Failed to set line %d to LOW: %s\n", DOOR_A, gpiod_error_str(errno));
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_set_value(line_b, 0) != 0) {
        fprintf(stderr, "Failed to set line %d to LOW: %s\n", DOOR_B, gpiod_error_str(errno));
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Generate a random 6-digit code
    int code = rand() % 900000 + 100000;
    printf("Security code: %06d\n", code);

    // Open the access log file
    FILE *log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open access log file: %s\n", strerror(errno));
        gpiod_line_release(line_a);
        gpiod_line_release(line_b);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        char input[7];
        printf("Enter security code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            fprintf(stderr, "Failed to read input: %s\n", strerror(errno));
            gpiod_line_release(line_a);
            gpiod_line_release(line_b);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        // Clear the newline character
        input[strcspn(input, "\n")] = 0;

        // Check if the input is a 6-digit number
        if (strlen(input) != 6 || !isdigit(input[0]) || !isdigit(input[1]) || !isdigit(input[2]) || !isdigit(input[3]) || !isdigit(input[4]) || !isdigit(input[5])) {
            printf("Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        // Check if the input matches the code
        if (atoi(input) == code) {
            // Unlock Door A for 5 seconds
            if (gpiod_line_set_value(line_a, 1) != 0) {
                fprintf(stderr, "Failed to set line %d to HIGH: %s\n", DOOR_A, gpiod_error_str(errno));
                gpiod_line_release(line_a);
                gpiod_line_release(line_b);
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            usleep(5000000);
            if (gpiod_line_set_value(line_a, 0) != 0) {
                fprintf(stderr, "Failed to set line %d to LOW: %s\n", DOOR_A, gpiod_error_str(errno));
                gpiod_line_release(line_a);
                gpiod_line_release(line_b);
                gpiod_chip_close(chip);
                fclose(log_file);
                exit(EXIT_FAILURE);
            }
            // Log the successful entry
            fprintf(log_file, "%s,%06d\n", asctime(localtime(&time(NULL))), code);
            fclose(log_file);
            // Generate a new random code
            code = rand() % 900000 + 100000;
            printf("Security code: %06d\n");
        } else {
            printf("Access denied\n");
        }
    }

    // Release all libgpiod resources
    gpiod_line_release(line_a);
    gpiod_line_release(line_b);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
}

