#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define CONVERSION_TIME 180 // ms
#define READ_BYTES 2
#define LOG_FILE "light_log.txt"
#define LOG_INTERVAL 5000 // ms
#define LUX_FORMULA (5.0 / 6.0)

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int i2c_open() {
    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int i2c_write(int fd, uint8_t addr, uint8_t reg, uint8_t value) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = 0,
        .buf = &value,
        .len = 1
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_RDWR, &msgs[0]);
    if (ret < 0) {
        perror("Failed to write to I2C bus");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t addr, uint8_t reg, uint8_t* buf, int len) {
    struct i2c_msg msg = {
        .addr = addr,
        .flags = I2C_M_RD,
        .buf = buf,
        .len = len
    };
    struct i2c_msg msgs[] = {msg};
    int ret = ioctl(fd, I2C_RDWR, &msgs[0]);
    if (ret < 0) {
        perror("Failed to read from I2C bus");
        return -1;
    }
    return 0;
}

void log_reading(double lux) {
    FILE* file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }
    char timestamp[32];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(file, "%s, Lux: %.2f\n", timestamp, lux);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);

    int fd = i2c_open();
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (i2c_write(fd, I2C_ADDR, 0x21, 0x21) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    usleep(CONVERSION_TIME * 1000);

    uint8_t data[READ_BYTES];
    if (i2c_read(fd, I2C_ADDR, 0x00, data, READ_BYTES) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    double lux = (data[0] << 8 | data[1]) * LUX_FORMULA;

    while (running) {
        log_reading(lux);
        usleep(LOG_INTERVAL * 1000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

