#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define PWM_GPIO 18
#define SAMPLING_INTERVAL 20
#define PLAYBACK_DURATION 5000

int i2c_fd;
int pwm_fd;
int client_fd;
int client_addr_len = sizeof(struct sockaddr_in);
struct sockaddr_in server_addr, client_addr;

void init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }
}

void init_i2c() {
    i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C address\n");
        exit(1);
    }
}

void init_pwm() {
    pwm_fd = gpioPWM(PWM_GPIO, 0);
    if (pwm_fd < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        exit(1);
    }
}

void reset_mpr121() {
    uint8_t data[1] = {0x1F};
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2A, data[0]) < 0) {
        fprintf(stderr, "Failed to reset MPR121\n");
        exit(1);
    }
}

void configure_mpr121() {
    uint8_t data[2] = {0x01, 0x00};
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2B, data[0]) < 0) {
        fprintf(stderr, "Failed to configure MPR121\n");
        exit(1);
    }
    if (i2c_smbus_write_byte_data(i2c_fd, 0x2C, data[1]) < 0) {
        fprintf(stderr, "Failed to configure MPR121\n");
        exit(1);
    }
}

void map_touch_value_to_frequency(uint8_t value) {
    float frequency = 220 + (880 - 220) * (log(value + 1) / log(16));
    return frequency;
}

void play_tone(float frequency) {
    float period = 1 / frequency;
    int duty_cycle = (int) (period * 1000000);
    if (gpioHardwarePWM(pwm_fd, duty_cycle) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        exit(1);
    }
}

void handle_client() {
    char buffer[1024];
    int bytes_received = recv(client_fd, buffer, 1024, 0);
    if (bytes_received < 0) {
        fprintf(stderr, "Failed to receive data from client\n");
        exit(1);
    }
    if (strncmp(buffer, "MOTION_DETECTED:", strlen("MOTION_DETECTED:")) == 0) {
        char *secret_key = strstr(buffer, SECRET_KEY);
        if (secret_key == NULL) {
            fprintf(stderr, "Invalid secret key\n");
            exit(1);
        }
        for (int i = 0; i < PLAYBACK_DURATION / SAMPLING_INTERVAL; i++) {
            uint8_t data[1];
            if (i2c_smbus_read_byte_data(i2c_fd, 0x00, data) < 0) {
                fprintf(stderr, "Failed to read MPR121 data\n");
                exit(1);
            }
            float frequency = map_touch_value_to_frequency(data[0]);
            play_tone(frequency);
            sleep(SAMPLING_INTERVAL / 1000.0);
        }
    }
}

int main() {
    init_pigpio();
    init_i2c();
    init_pwm();
    reset_mpr121();
