#define MAG_I2C_ADDR 0x1E
#define MAG_CTRL_REG1_M 0x20
#define MAG_OUT_X_L_M 0x08
#define MAG_OUT_X_H_M 0x09
#define MAG_OUT_Y_L_M 0x0A
#define MAG_OUT_Y_H_M 0x0B
#define MAG_OUT_Z_L_M 0x0C
#define MAG_OUT_Z_H_M 0x0D

#define PWM_FREQ 1000
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100

int main() {
    int i2c_fd = -1;
    int pwm_fd = -1;
    int ret;
    uint8_t mag_data[6];
    uint16_t x, y, z;
    uint16_t duty;
    struct gpiod_line *led_line;
    struct gpiod_line_request line_req;
    struct gpiod_line_request line_req_pwm;
    struct gpiod_chip *chip;
    struct gpiod_pwm *pwm;

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize I2C bus
    if (ioctl(i2c_fd, I2C_SLAVE, MAG_I2C_ADDR) < 0) {
        perror("Failed to initialize I2C bus");
        close(i2c_fd);
        return 1;
    }

    // Initialize LED pin
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get LED line");
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    line_req.line = led_line;
    line_req.consumer = "example";
    line_req.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_line_request_output(led_line, &line_req);
    if (ret < 0) {
        perror("Failed to request LED line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    // Initialize PWM
    pwm_fd = open("/dev/pwm/0", O_RDWR);
    if (pwm_fd < 0) {
        perror("Failed to open PWM device");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    line_req_pwm.line = led_line;
    line_req_pwm.consumer = "example";
    line_req_pwm.request_type = GPIOD_LINE_REQUEST_OUTPUT;
    ret = gpiod_line_request_output(led_line, &line_req_pwm);
    if (ret < 0) {
        perror("Failed to request PWM line");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    pwm = gpiod_pwm_open(pwm_fd);
    if (!pwm) {
        perror("Failed to open PWM");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    gpiod_pwm_set_frequency(pwm, PWM_FREQ);
    gpiod_pwm_set_range(pwm, 100);

    // Initialize magnetometer
    uint8_t ctrl_reg1_m = 0x18; // 10 Hz continuous conversion
    if (write(i2c_fd, &ctrl_reg1_m, 1) < 0) {
        perror("Failed to write to magnetometer CTRL_REG1_M");
        close(pwm_fd);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        close(i2c_fd);
        return 1;
    }

    while (1) {
        // Read magnetometer data
        if (read(i2c_fd, mag_data, 6) < 0) {
            perror("Failed to read from magnetometer");
            continue;
        }

        // Extract X, Y, Z magnetic field data
        x = (mag_data[1] << 8) | mag_data[0];
        y = (mag_data[3] << 8) | mag_data[2];
        z = (mag_data[5] << 8) | mag_data[4];

        // Compute magnitude of Z-axis field
        uint16_t magnitude = (uint16_t)sqrt((double)x * x + (double)y * y + (double)z * z);

        // Adjust LED brightness proportionally
        duty = (uint16_t)((double)magnitude / 16384.0 * (PWM_DUTY_MAX - PWM_DUTY_MIN) + PWM_DUTY_MIN);
        gpiod_pwm_set_duty(pwm, duty);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    gpiod_pwm_close(pwm);
    close(pwm_fd);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);
    close(i2c_fd);

    return 0;
}

