#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define signal handlers for SIGINT and SIGTERM
void sigint_handler(int sig) {
    // Release I2C handle and pigpio library resources
    if (i2c_close(I2C1) != 0) {
        fprintf(stderr, "Error closing I2C handle\n");
    }
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    // Release I2C handle and pigpio library resources
    if (i2c_close(I2C1) != 0) {
        fprintf(stderr, "Error closing I2C handle\n");
    }
    gpioTerminate();
    exit(0);
}

// Function to read 3 bytes from the HMC5883L magnetometer
int read_magnetometer(int fd, uint8_t *buf) {
    if (i2c_read(fd, 0x1E, 0x03, buf, 3) != 3) {
        fprintf(stderr, "Error reading from magnetometer\n");
        return -1;
    }
    return 0;
}

// Function to write 1 byte to the HMC5883L magnetometer
int write_magnetometer(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[1] = {val};
    if (i2c_write(fd, 0x1E, reg, buf, 1) != 1) {
        fprintf(stderr, "Error writing to magnetometer\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int fd = i2cOpen(1, 0x1E);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure HMC5883L magnetometer
    uint8_t config_a = 0x70;  // 8-sample averaging, 15 Hz output rate, gain = 1.3 Gauss
    uint8_t config_b = 0x20;  // Mode register = 0x00 for continuous mode
    if (write_magnetometer(fd, 0x00, config_a) != 0) {
        i2c_close(fd);
        gpioTerminate();
        return 1;
    }
    if (write_magnetometer(fd, 0x01, config_b) != 0) {
        i2c_close(fd);
        gpioTerminate();
        return 1;
    }

    // Initialize variables for hard-iron offset calculation
    int offset_count = 0;
    int64_t offset_x = 0;
    int64_t offset_y = 0;
    int64_t offset_z = 0;

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler for SIGINT\n");
        i2c_close(fd);
        gpioTerminate();
        return 1;
    }
    sa.sa_handler = sigterm_handler;
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handler for SIGTERM\n");
        i2c_close(fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read raw magnetometer values
        uint8_t buf[3];
        if (read_magnetometer(fd, buf) != 0) {
            break;
        }

        // Convert raw values to integers
        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[1] << 8) | buf[2];
        int16_t z = (buf[2] << 8) | buf[0];

        // Update hard-iron offset calculation
        offset_x += x;
        offset_y += y;
        offset_z += z;
        offset_count++;
        if (offset_count >= 100) {
            offset_x /= 100;
            offset_y /= 100;
            offset_z /= 100;
            offset_count = 0;
        }

        // Apply hard-iron offset to raw reading
        int16_t x_corrected = x - offset_x;
        int16_t y_corrected = y - offset_y;
        int16_t z_corrected = z - offset_z;

        // Print offset-corrected values
        printf("%d %d %d\n", x_corrected, y_corrected, z_corrected);

        // Sleep for 500 ms
        usleep(500000);
    }

    // Release I2C handle and pigpio library resources
    if (i2c_close(fd) != 0) {
        fprintf(stderr, "Error closing I2C handle\n");
    }
    gpioTerminate();

    return 0;
}

