    close(i2c_fd);
    return 0;
}

void sigint_handler(int sig) {
    gpiod_line_release(NULL);
    close(STDIN_FILENO);
    exit(0);
}

int main() {
    signal(SIGINT, sigint_handler);

    return main();
}

