    running = 0;
}

void cleanup() {
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio: %s\n", strerror(errno));
    }
    if (close(serial_port1) != 0) {
        fprintf(stderr, "Error closing serial port 1: %s\n", strerror(errno));
    }
    if (close(serial_port2) != 0) {
        fprintf(stderr, "Error closing serial port 2: %s\n", strerror(errno));
    }
    if (gpioWrite(GPIO_LOCK1, 0) != 0) {
        fprintf(stderr, "Error setting GPIO 17 low: %s\n", strerror(errno));
    }
    if (gpioWrite(GPIO_LOCK2, 0) != 0) {
        fprintf(stderr, "Error setting GPIO 27 low: %s\n", strerror(errno));
    }
}

