int main() {
    // Open the log
    openlog("door_strike", LOG_PID | LOG_PERROR, LOG_USER);

    // Open the gpiochip by name
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open gpiochip0");
        closelog();
        exit(1);
    }

    // Request the PIR pin as an input
    line_pir = gpiod_line_request_input(chip, "gpio4");
    if (line_pir == NULL) {
        syslog(LOG_ERR, "Failed to request PIR pin as input");
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    // Request the relay pin as an output
    line_relay = gpiod_line_request_output(chip, "gpio17");
    if (line_relay == NULL) {
        syslog(LOG_ERR, "Failed to request relay pin as output");
        gpiod_line_release(line_pir);
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    // Initialize the relay to LOW
    gpiod_line_set_value(line_relay, 0);

    // Set up signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGINT handler");
        gpiod_line_release(line_pir);
        gpiod_line_release(line_relay);
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to set up SIGTERM handler");
        gpiod_line_release(line_pir);
        gpiod_line_release(line_relay);
        gpiod_chip_close(chip);
        closelog();
        exit(1);
    }

    // Main loop
    int last_state = 0;
    int failsafe_triggered = 0;
    while (1) {
        // Read the PIR pin value
        int pir_value = gpiod_line_get_value(line_pir);
        if (pir_value == -1) {
            syslog(LOG_ERR, "Failed to read PIR pin value");
            gpiod_line_release(line_pir);
            gpiod_line_release(line_relay);
            gpiod_chip_close(chip);
            closelog();
            exit(1);
        }

        // Check if motion is detected
        if (pir_value == 1) {
            // Log motion detection
            syslog(LOG_INFO, "Motion detected");

            // Check if failsafe has been triggered
            if (failsafe_triggered) {
                // Log failsafe trigger
                syslog(LOG_WARNING, "Failsafe triggered, de-energizing relay");
                gpiod_line_set_value(line_relay, 0);
                failsafe_triggered = 0;
            } else {
                // Energize the relay
                gpiod_line_set_value(line_relay, 1);
                syslog(LOG_INFO, "Relay on");

                // Set a timer for 1 second
                struct timespec timeout;
                timeout.tv_sec = 1;
                timeout.tv_nsec = 0;
                nanosleep(&timeout);

                // De-energize the relay
                gpiod_line_set_value(line_relay, 0);
                syslog(LOG_INFO, "Relay off");
            }

            // Reset the failsafe timer
            failsafe_triggered = 0;
        } else {
            // Check if the PIR sensor has been HIGH for more than 10 seconds
            if (last_state == 1 && (gettimeofday(NULL, NULL) - last_tv.tv_sec > 10)) {
                // Log failsafe trigger
                syslog(LOG_WARNING, "Failsafe triggered, de-energizing relay");
                gpiod_line_set_value(line_relay, 0);
                failsafe_triggered = 1;
            }
        }

        // Update the last state
        last_state = pir_value;
        last_tv = *gettimeofday();

        // Poll the PIR pin every 50 ms
        struct timespec sleep;
        sleep.tv_sec = 0;
        sleep.tv_nsec = 50000000;
        nanosleep(&sleep);
    }

    return 0;
