            failsafe_triggered = 0;
        } else {
            // Check if the PIR sensor has been HIGH for more than 10 seconds
            if (last_state == 1 && (gettimeofday(NULL, NULL) - last_tv.tv_sec > 10)) {
                // Log failsafe trigger
                syslog(LOG_WARNING, "Failsafe triggered, de-energizing relay");
                gpiod_line_set_value(line_relay, 0);
                failsafe_triggered = 1;
            }
        }

        // Update the last state
        last_state = pir_value;
        last_tv = *gettimeofday();

        // Poll the PIR pin every 50 ms
        struct timespec sleep;
        sleep.tv_sec = 0;
        sleep.tv_nsec = 50000000;
        nanosleep(&sleep);
    }

    return 0;
}
