#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/timerfd.h>
#include <sys/syslog.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <signal.h>
#include <errno.h>

#define MPU6050_ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_XOUT_L 0x3C
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_YOUT_L 0x3E
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define MPU6050_ACCEL_ZOUT_L 0x40

#define MPU6050_PWR_MGMT_1 0x6B

#define MPU6050_ACCEL_RANGE_2G 0x00

#define MPU6050_I2C_BUS "/dev/i2c-1"
#define MPU6050_I2C_ADDR 0x68

#define BUF_SIZE 1024
#define CIRCULAR_BUFFER_SIZE 1024
#define CIRCULAR_BUFFER_MASK (CIRCULAR_BUFFER_SIZE - 1)

struct mpu6050_accel {
    float x;
    float y;
    float z;
};

struct circular_buffer {
    struct mpu6050_accel data[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
};

struct circular_buffer buffer;

int i2c_fd;
struct i2c_client *client;
struct i2c_client *client_buf;
struct i2c_client *client_sysfs;
struct i2c_client *client_sysfs_buf;

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, exiting...", sig);
    close(i2c_fd);
    munmap(client, sizeof(*client));
    munmap(client_buf, sizeof(*client_buf));
    munmap(client_sysfs, sizeof(*client_sysfs));
    munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
    exit(0);
}

void sigterm_handler(int sig) {
    syslog(LOG_INFO, "Caught signal %d, exiting...", sig);
    close(i2c_fd);
    munmap(client, sizeof(*client));
    munmap(client_buf, sizeof(*client_buf));
    munmap(client_sysfs, sizeof(*client_sysfs));
    munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
    exit(0);
}

void init_mpu6050() {
    uint8_t reg = 0x6B;
    uint8_t val = 0x00;
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_I2C_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        exit(1);
    }
    if (i2c_smbus_write_byte_data(i2c_fd, reg, val) < 0) {
        syslog(LOG_ERR, "Failed to write to PWR_MGMT_1 register");
        exit(1);
    }
    reg = 0x1C;
    val = 0x00;
    if (i2c_smbus_write_byte_data(i2c_fd, reg, val) < 0) {
        syslog(LOG_ERR, "Failed to write to ACCEL_CONFIG register");
        exit(1);
    }
}

void read_accel_data() {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(i2c_fd, MPU6050_ACCEL_XOUT_H, 6, data) < 0) {
        syslog(LOG_ERR, "Failed to read from ACCEL_XOUT_H register");
        return;
    }
    struct mpu6050_accel *accel = &buffer.data[buffer.head];
    accel->x = (float)((data[0] << 8) | data[1]) / 16384.0;
    accel->y = (float)((data[2] << 8) | data[3]) / 16384.0;
    accel->z = (float)((data[4] << 8) | data[5]) / 16384.0;
    buffer.head = (buffer.head + 1) & CIRCULAR_BUFFER_MASK;
}

void write_sysfs() {
    char filename[256];
    sprintf(filename, "/sys/kernel/mpu6050_accel/latest");
    int fd = open(filename, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open sysfs file");
        return;
    }
    struct mpu6050_accel *accel = &buffer.data[buffer.tail];
    char buffer[256];
    sprintf(buffer, "%f %f %f", accel->x, accel->y, accel->z);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        syslog(LOG_ERR, "Failed to write to sysfs file");
    }
    close(fd);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    i2c_fd = open(MPU6050_I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        exit(1);
    }

    client = mmap(NULL, sizeof(*client), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (client == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map I2C client");
        close(i2c_fd);
        exit(1);
    }

    client_buf = mmap(NULL, sizeof(*client_buf), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (client_buf == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map I2C client buffer");
        munmap(client, sizeof(*client));
        close(i2c_fd);
        exit(1);
    }

    client_sysfs = mmap(NULL, sizeof(*client_sysfs), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (client_sysfs == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map I2C sysfs client");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        close(i2c_fd);
        exit(1);
    }

    client_sysfs_buf = mmap(NULL, sizeof(*client_sysfs_buf), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (client_sysfs_buf == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map I2C sysfs buffer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        close(i2c_fd);
        exit(1);
    }

    init_mpu6050();

    buffer.head = 0;
    buffer.tail = 0;

    int timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        syslog(LOG_ERR, "Failed to create timer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
        close(i2c_fd);
        exit(1);
    }

    struct itimerspec spec;
    spec.it_value.tv_sec = 0;
    spec.it_value.tv_nsec = 10000000; // 10ms
    spec.it_interval.tv_sec = 0;
    spec.it_interval.tv_nsec = 10000000; // 10ms
    if (timerfd_settime(timer_fd, 0, &spec, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set timer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
        close(i2c_fd);
        close(timer_fd);
        exit(1);
    }

    while (1) {
        int events;
        read(timer_fd, &events, sizeof(events));
        read_accel_data();
        write_sysfs();
        buffer.tail = (buffer.tail + 1) & CIRCULAR_BUFFER_MASK;
    }

    munmap(client, sizeof(*client));
    munmap(client_buf, sizeof(*client_buf));
    munmap(client_sysfs, sizeof(*client_sysfs));
    munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
    close(i2c_fd);
    close(timer_fd);
    return 0;
}

