        munmap(client_buf, sizeof(*client_buf));
        close(i2c_fd);
        exit(1);
    }

    client_sysfs_buf = mmap(NULL, sizeof(*client_sysfs_buf), PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    if (client_sysfs_buf == MAP_FAILED) {
        syslog(LOG_ERR, "Failed to map I2C sysfs buffer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        close(i2c_fd);
        exit(1);
    }

    init_mpu6050();

    buffer.head = 0;
    buffer.tail = 0;

    int timer_fd = timerfd_create(CLOCK_REALTIME, 0);
    if (timer_fd < 0) {
        syslog(LOG_ERR, "Failed to create timer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
        close(i2c_fd);
        exit(1);
    }

    struct itimerspec spec;
    spec.it_value.tv_sec = 0;
    spec.it_value.tv_nsec = 10000000; // 10ms
    spec.it_interval.tv_sec = 0;
    spec.it_interval.tv_nsec = 10000000; // 10ms
    if (timerfd_settime(timer_fd, 0, &spec, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set timer");
        munmap(client, sizeof(*client));
        munmap(client_buf, sizeof(*client_buf));
        munmap(client_sysfs, sizeof(*client_sysfs));
        munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
        close(i2c_fd);
        close(timer_fd);
        exit(1);
    }

    while (1) {
        int events;
        read(timer_fd, &events, sizeof(events));
        read_accel_data();
        write_sysfs();
        buffer.tail = (buffer.tail + 1) & CIRCULAR_BUFFER_MASK;
    }

    munmap(client, sizeof(*client));
    munmap(client_buf, sizeof(*client_buf));
    munmap(client_sysfs, sizeof(*client_sysfs));
    munmap(client_sysfs_buf, sizeof(*client_sysfs_buf));
    close(i2c_fd);
    close(timer_fd);
    return 0;
}
