        lines[i] = gpiod_line_request_by_name(ctx, "/sys/class/gpio/gpio%d/value", i + RELAY_1);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to request line %d\n", i + RELAY_1);
            cleanup();
        }
    }

