    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
    }

    struct timeval last_time[RELAY_LINES];
    for (int i = 0; i < RELAY_LINES; i++) {
        last_time[i].tv_sec = 0;
        last_time[i].tv_nsec = 0;
    }

    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);
        for (int i = 0; i < RELAY_LINES; i++) {
            if (now.tv_sec - last_time[i].tv_sec >= INTERVAL_1 + INTERVAL_2 + INTERVAL_3 + INTERVAL_4 - 1) {
                last_time[i].tv_sec = now.tv_sec;
                last_time[i].tv_nsec = now.tv_nsec;
                toggle_relay(i, true);
            }
            if (now.tv_sec - last_time[i].tv_sec >= INTERVAL_1 - 1) {
                last_time[i].tv_sec = now.tv_sec;
                last_time[i].tv_nsec = now.tv_nsec;
                toggle_relay(i, false);
            }
            if (now.tv_sec - last_time[i].tv_sec >= INTERVAL_2 - 1) {
                last_time[i].tv_sec = now.tv_sec;
                last_time[i].tv_nsec = now.tv_nsec;
                toggle_relay(i + 1, true);
            }
            if (now.tv_sec - last_time[i].tv_sec >= INTERVAL_3 - 1) {
                last_time[i].tv_sec = now.tv_sec;
                last_time[i].tv_nsec = now.tv_nsec;
                toggle_relay(i + 2, false);
            }
            if (now.tv_sec - last_time[i].tv_sec >= INTERVAL_4 - 1) {
                last_time[i].tv_sec = now.tv_sec;
                last_time[i].tv_nsec = now.tv_nsec;
                toggle_relay(i + 3, true);
            }
        }
        usleep(100000);
    }

    return EXIT_SUCCESS;
}

