#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define GPIO_SENSOR_PIN 17
#define GPIO_RELAY_PIN 27
#define DEBOUNCE_TIME 1000  // 1 second
#define ALARM_DURATION 3000  // 3 seconds
#define LOG_FILE "alarm_log.txt"

// Global variables
int gpio_sensor_fd = -1;
int gpio_relay_fd = -1;
int debounce_cooldown = 0;
int alarm_active = 0;

// Function to log an alarm event
void log_alarm() {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(file, "%lu\n", time(NULL));
    fclose(file);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    if (gpio_relay_fd != -1) {
        gpio_write(gpio_relay_fd, 0, 1);  // Turn off the relay
    }
    if (gpio_sensor_fd != -1) {
        gpio_close(gpio_sensor_fd);
    }
    if (gpio_relay_fd != -1) {
        gpio_close(gpio_relay_fd);
    }
    exit(0);
}

int main() {
    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    // Open GPIO pins
    gpio_sensor_fd = gpioOpen(GPIO_SENSOR_PIN, PI_INPUT);
    if (gpio_sensor_fd == -1) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_SENSOR_PIN);
        gpioTerminate();
        exit(1);
    }
    gpio_relay_fd = gpioOpen(GPIO_RELAY_PIN, PI_OUTPUT);
    if (gpio_relay_fd == -1) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_RELAY_PIN);
        gpio_close(gpio_sensor_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up debounce cooldown
    debounce_cooldown = time(NULL);

    while (1) {
        // Read the state of the sensor
        int sensor_state = gpioRead(gpio_sensor_fd);
        if (sensor_state == -1) {
            fprintf(stderr, "Failed to read GPIO %d\n", GPIO_SENSOR_PIN);
            gpio_close(gpio_sensor_fd);
            gpio_close(gpio_relay_fd);
            gpioTerminate();
            exit(1);
        }

        // Check if the sensor is HIGH and the cooldown period has passed
        if (sensor_state == 1 && time(NULL) - debounce_cooldown >= DEBOUNCE_TIME) {
            // Trigger the alarm
            if (gpio_relay_fd != -1) {
                gpio_write(gpio_relay_fd, 1, 1);  // Turn on the relay
            }
            alarm_active = 1;
            log_alarm();
            sleep(ALARM_DURATION / 1000);  // Wait for the alarm duration
            if (gpio_relay_fd != -1) {
                gpio_write(gpio_relay_fd, 0, 1);  // Turn off the relay
            }
            alarm_active = 0;
            debounce_cooldown = time(NULL);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up on exit
    if (gpio_relay_fd != -1) {
        gpio_write(gpio_relay_fd, 0, 1);  // Turn off the relay
    }
    if (gpio_sensor_fd != -1) {
        gpio_close(gpio_sensor_fd);
    }
    if (gpio_relay_fd != -1) {
        gpio_close(gpio_relay_fd);
    }
    gpioTerminate();

    return 0;
}

