#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define PWR_MGMT_1 0x6B
#define WHO_AM_I 0x75
#define THRESHOLD 50.0
#define SAMPLES 100
#define SENSITIVITY 131.0

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} GyroData;

// Structure to hold the circular buffer
typedef struct {
    GyroData data[SAMPLES];
    int head;
    int tail;
} GyroBuffer;

// Function to initialize the gyroscope
void initGyro(int fd) {
    // Wake up the sensor by clearing the sleep bit in PWR_MGMT_1
    uint8_t reg = 0x6B;
    uint8_t val = 0x00;
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        exit(1);
    }
    if (write(fd, &val, 1) != 1) {
        perror("write");
        exit(1);
    }

    // Verify the device by reading the WHO_AM_I register
    reg = 0x75;
    uint8_t id;
    if (read(fd, &id, 1) != 1) {
        perror("read");
        exit(1);
    }
    if (id != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I register does not match expected value\n");
        exit(1);
    }
}

// Function to read gyroscope data
void readGyroData(int fd, GyroData *data) {
    // Read the 6 bytes of gyroscope data
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buf[6];
    if (read(fd, buf, 6) != 6) {
        perror("read");
        exit(1);
    }

    // Convert the data to float values
    data->x = (float)((buf[1] << 8) | buf[0]) / SENSITIVITY;
    data->y = (float)((buf[3] << 8) | buf[2]) / SENSITIVITY;
    data->z = (float)((buf[5] << 8) | buf[4]) / SENSITIVITY;
}

// Function to calculate the magnitude of the gyroscope data
float calculateMagnitude(GyroData data) {
    return sqrtf(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to handle the callback when the angular velocity exceeds the threshold
void callback(GyroData data) {
    printf("Angular velocity exceeded threshold: %f degrees/second\n", calculateMagnitude(data));
}

// Function to handle the circular buffer
void gyroBufferPush(GyroBuffer *buffer, GyroData data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % SAMPLES;
}

void gyroBufferPop(GyroBuffer *buffer, GyroData *data) {
    if (buffer->tail == buffer->head) {
        // Buffer is empty
        return;
    }
    *data = buffer->data[buffer->tail];
    buffer->tail = (buffer->tail + 1) % SAMPLES;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDRESS) < 0) {
        perror("ioctl");
        close(fd);
        exit(1);
    }

    initGyro(fd);

    GyroBuffer buffer;
    buffer.head = 0;
    buffer.tail = 0;

    signal(SIGINT, SIG_IGN);

    while (1) {
        GyroData data;
        readGyroData(fd, &data);
        gyroBufferPush(&buffer, data);

        if (calculateMagnitude(data) > THRESHOLD) {
            callback(data);
        }

        usleep(100000); // 100ms
    }

    close(fd);
    return 0;
}

