#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1E
#define REG_CONFIG_A 0x00
#define REG_CONFIG_B 0x01
#define REG_MODE 0x02
#define REG_DATA 0x03
#define GPIO_PIN 17
#define SAMPLE_RATE 100 // ms
#define BUFFER_SIZE 100
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define X_OFFSET 100
#define Y_OFFSET -50

// Define a struct to hold the circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int tail;
} Buffer;

// Function to initialize the buffer
void buffer_init(Buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
}

// Function to add an element to the buffer
void buffer_add(Buffer *buf, float value) {
    buf->buffer[buf->head] = value;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
}

// Function to get the last element from the buffer
float buffer_get_last(Buffer *buf) {
    return buf->buffer[buf->tail];
}

// Function to get the oldest element from the buffer
float buffer_get_oldest(Buffer *buf) {
    return buf->buffer[buf->tail];
}

// Function to clear the buffer
void buffer_clear(Buffer *buf) {
    memset(buf->buffer, 0, sizeof(buf->buffer));
    buf->head = 0;
    buf->tail = 0;
}

// Function to handle I2C errors
void i2c_error_handler(int sig) {
    fprintf(stderr, "I2C error: %s\n", strerror(errno));
    exit(1);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, i2c_error_handler);
    signal(SIGTERM, i2c_error_handler);

    // Initialize the I2C bus
    if (gpioI2CSetup(I2C_BUS, 100000) < 0) {
        fprintf(stderr, "Failed to set up I2C bus\n");
        return 1;
    }

    // Initialize the buffer
    Buffer buffer;
    buffer_init(&buffer);

    // Initialize the magnetometer
    int config_a = 0x70;
    int config_b = 0x20;
    int mode = 0x00;
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, REG_CONFIG_A, config_a) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_A register\n");
        return 1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, REG_CONFIG_B, config_b) < 0) {
        fprintf(stderr, "Failed to write to CONFIG_B register\n");
        return 1;
    }
    if (gpioI2CWriteReg8(I2C_BUS, I2C_ADDRESS, REG_MODE, mode) < 0) {
        fprintf(stderr, "Failed to write to MODE register\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read 6 bytes from the magnetometer
        int data[6];
        if (gpioI2CReadReg8(I2C_BUS, I2C_ADDRESS, REG_DATA, data, 6) < 0) {
            fprintf(stderr, "Failed to read from magnetometer\n");
            continue;
        }

        // Convert the data to a heading
        float x = (data[0] << 8) | data[1];
        float z = (data[2] << 8) | data[3];
        float y = (data[4] << 8) | data[5];
        x = x / 16384.0 - X_OFFSET;
        y = y / 16384.0 - Y_OFFSET;
        float heading = atan2(y, x) * 180.0 / 3.14159;

        // Compensate for hard-iron distortion
        if (heading < 0) heading += 360.0;

        // Check if the heading deviates more than 10 degrees from the target
        if (abs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            // Drive GPIO17 high
            gpioWrite(GPIO_PIN, 1);
        } else {
            // Drive GPIO17 low
            gpioWrite(GPIO_PIN, 0);
        }

        // Add the heading to the buffer
        buffer_add(&buffer, heading);

        // Log the heading
        printf("%f\n", heading);

        // Sleep for 100 ms
        usleep(SAMPLE_RATE * 1000);
    }

    // Clean up
    gpioI2CSetup(I2C_BUS, 0);
    gpioTerminate();
    return 0;
}

