const int step_sequence[] = {0x01, 0x02, 0x04, 0x08};

// Motor step count for a quarter turn
const int steps_per_turn = 512;

// Flag to track button press state
int lock_button_pressed = 0;
int unlock_button_pressed = 0;

// Flag to track motor running state
int motor_running = 0;

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // De-energize motor coils
    gpio_write(MOTOR_A, 0);
    gpio_write(MOTOR_B, 0);
    gpio_write(MOTOR_C, 0);
    gpio_write(MOTOR_D, 0);

    // Release pigpio resources
    gpioTerminate();

    // Exit program
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(MOTOR_A, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", MOTOR_A);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_B, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", MOTOR_B);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_C, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", MOTOR_C);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MOTOR_D, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", MOTOR_D);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as input\n", LOCK_BUTTON);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as input\n", UNLOCK_BUTTON);
        gpioTerminate();
        return 1;
    }

    // Set up internal pull-up resistors for buttons
    if (gpioSetPullUpDnControl(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor for GPIO %d\n", LOCK_BUTTON);
        gpioTerminate();
        return 1;
