    if (gpioSetPullUpDnControl(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor for GPIO %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON) == 0 && lock_button_pressed == 0) {
            lock_button_pressed = 1;
            printf("Locking...\n");
            motor_running = 1;
            for (int i = 0; i < steps_per_turn; i++) {
                for (int j = 0; j < 4; j++) {
                    gpio_write(MOTOR_A, step_sequence[j] & 0x01);
                    gpio_write(MOTOR_B, step_sequence[j] & 0x02);
                    gpio_write(MOTOR_C, step_sequence[j] & 0x04);
                    gpio_write(MOTOR_D, step_sequence[j] & 0x08);
