    if (gpioSetMode(MOTOR_D, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as output\n", MOTOR_D);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as input\n", LOCK_BUTTON);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO %d as input\n", UNLOCK_BUTTON);
        gpioTerminate();
        return 1;
    }

    // Set up internal pull-up resistors for buttons
    if (gpioSetPullUpDnControl(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor for GPIO %d\n", LOCK_BUTTON);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set up pull-up resistor for GPIO %d\n", UNLOCK_BUTTON);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON) == 0 && lock_button_pressed == 0) {
            lock_button_pressed = 1;
            printf("Locking...\n");
            motor_running = 1;
            for (int i = 0; i < steps_per_turn; i++) {
                for (int j = 0; j < 4; j++) {
                    gpio_write(MOTOR_A, step_sequence[j] & 0x01);
                    gpio_write(MOTOR_B, step_sequence[j] & 0x02);
                    gpio_write(MOTOR_C, step_sequence[j] & 0x04);
                    gpio_write(MOTOR_D, step_sequence[j] & 0x08);
                    usleep(2000);
                }
            }
            motor_running = 0;
            lock_button_pressed = 0;
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON) == 0 && unlock_button_pressed == 0) {
            unlock_button_pressed = 1;
            printf("Unlocking...\n");
            motor_running = 1;
            for (int i = 0; i < steps_per_turn; i++) {
                for (int j = 3; j >= 0; j--) {
                    gpio_write(MOTOR_A, step_sequence[j] & 0x01);
                    gpio_write(MOTOR_B, step_sequence[j] & 0x02);
                    gpio_write(MOTOR_C, step_sequence[j] & 0x04);
                    gpio_write(MOTOR_D, step_sequence[j] & 0x08);
                    usleep(2000);
                }
            }
            motor_running = 0;
            unlock_button_pressed = 0;
        }

        // Check for motor running state
        if (motor_running == 0) {
            gpio_write(MOTOR_A, 0);
            gpio_write(MOTOR_B, 0);
            gpio_write(MOTOR_C, 0);
            gpio_write(MOTOR_D, 0);
        }

        // Sleep for 10ms
        usleep(10000);
    }

    return 0;
}
