#define I2C_BUS "/dev/i2c-1"
#define MPU_ADDRESS 0x68
#define SERVO_GPIO 18
#define SERVO_PWM "/sys/class/pwm/pwmchip2/pwm0"
#define LOG_FILE "solar_tracker.log"

// Exponential backoff function
uint32_t exponential_backoff(uint32_t attempts, uint32_t max_attempts, uint32_t min_delay, uint32_t max_delay) {
    uint32_t delay = min_delay;
    for (uint32_t i = 0; i < attempts; i++) {
        if (i < max_attempts) {
            delay *= 2;
            if (delay > max_delay) {
                delay = max_delay;
            }
        }
        usleep(delay * 1000);
    }
    return delay;
}

// Read 16-bit value from I2C device
uint16_t read_word16(int fd, uint8_t reg) {
    uint8_t data[2];
    if (ioctl(fd, I2C_SLAVE, MPU_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        return 0;
    }
    if (i2c_smbus_write_byte(fd, reg) < 0) {
        syslog(LOG_ERR, "Failed to write to I2C register");
        return 0;
    }
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        syslog(LOG_ERR, "Failed to read from I2C register");
        return 0;
    }
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        syslog(LOG_ERR, "Failed to read from I2C register");
        return 0;
    }
    data[0] = i2c_smbus_read_byte_data(fd, reg);
    data[1] = i2c_smbus_read_byte_data(fd, reg);
    uint16_t value = (data[0] << 8) | data[1];
    return value;
}

// Read 16-bit value from I2C device with exponential backoff
uint16_t read_word16_backoff(int fd, uint8_t reg, uint32_t attempts, uint32_t max_attempts, uint32_t min_delay, uint32_t max_delay) {
    uint32_t delay = exponential_backoff(attempts, max_attempts, min_delay, max_delay);
    for (uint32_t i = 0; i < attempts; i++) {
        uint16_t value = read_word16(fd, reg);
        if (value != 0) {
            return value;
        }
        usleep(delay * 1000);
    }
    syslog(LOG_ERR, "Failed to read from I2C register after %d attempts", attempts);
    return 0;
}

// Write 16-bit value to I2C device
void write_word16(int fd, uint8_t reg, uint16_t value) {
    uint8_t data[2];
    data[0] = (value >> 8) & 0xFF;
    data[1] = value & 0xFF;
    if (ioctl(fd, I2C_SLAVE, MPU_ADDRESS) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address");
        return;
    }
    if (i2c_smbus_write_byte_data(fd, reg, data[0]) < 0) {
        syslog(LOG_ERR, "Failed to write to I2C register");
        return;
    }
    if (i2c_smbus_write_byte_data(fd, reg, data[1]) < 0) {
        syslog(LOG_ERR, "Failed to write to I2C register");
        return;
    }
}

// Read accelerometer data
void read_accelerometer(int fd) {
    uint16_t x = read_word16_backoff(fd, 0x3B, 5, 10, 100, 1000);
    uint16_t y = read_word16_backoff(fd, 0x3D, 5, 10, 100, 1000);
    uint16_t z = read_word16_backoff(fd, 0x3F, 5, 10, 100, 1000);
    syslog(LOG_INFO, "Accelerometer: x=%d, y=%d, z=%d", x, y, z);
}

// Read gyroscope data
void read_gyroscope(int fd) {
    uint16_t x = read_word16_backoff(fd, 0x43, 5, 10, 100, 1000);
    uint16_t y = read_word16_backoff(fd, 0x45, 5, 10, 100, 1000);
    uint16_t z = read_word16_backoff(fd, 0x47, 5, 10, 100, 1000);
    syslog(LOG_INFO, "Gyroscope: x=%d, y=%d, z=%d", x, y, z);
}

// Calculate pitch and roll from accelerometer data
void calculate_pitch_roll(uint16_t x, uint16_t y, uint16_t z) {
    float pitch = atan2f((float) x, (float) z) * 180 / M_PI;
    float roll = atan2f((float) y, (float) z) * 180 / M_PI;
    syslog(LOG_INFO, "Pitch: %f, Roll: %f", pitch, roll);
}

// Set servo position
void set_servo_position(int fd, float position) {
    FILE *file = fopen(SERVO_PWM "/enable", "w");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open servo enable file");
        return;
    }
    fprintf(file, "1");
    fclose(file);
    file = fopen(SERVO_PWM "/period", "w");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open servo period file");
        return;
    }
    fprintf(file, "2000000");
    fclose(file);
    file = fopen(SERVO_PWM "/duty_cycle", "w");
    if (file == NULL) {
        syslog(LOG_ERR, "Failed to open servo duty cycle file");
        return;
    }
    fprintf(file, "%d", (int) (position * 100));
    fclose(file);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    syslog(LOG_INFO, "Received signal %d, exiting", signum);
    close(i2c_fd);
    fclose(servofd);
    fclose(logfile);
    exit(0);
}

int main() {
    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device");
        return 1;
    }

    // Open servo PWM device
    servofd = fopen(SERVO_PWM "/enable", "w");
    if (servofd == NULL) {
        syslog(LOG_ERR, "Failed to open servo enable file");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    logfile = fopen(LOG_FILE, "a");
    if (logfile == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        fclose(servofd);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handling");
        fclose(servofd);
        fclose(logfile);
        close(i2c_fd);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handling");
        fclose(servofd);
        fclose(logfile);
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    write_word16(i2c_fd, 0x6B, 0x00);

    // Main loop
    while (1) {
        read_accelerometer(i2c_fd);
        read_gyroscope(i2c_fd);
        calculate_pitch_roll(read_word16(i2c_fd, 0x3B), read_word16(i2c_fd, 0x3D), read_word16(i2c_fd, 0x3F));
        float position = 0.5; // adjust this value to control the servo position
        set_servo_position(servofd, position);
        fprintf(logfile, "%f,%f,%f\n", time(NULL), position, 0);
        fflush(logfile);
        sleep(1);
    }

    // Clean up
    fclose(servofd);
    fclose(logfile);
    close(i2c_fd);
    return 0;
}

