#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pins for the relays
#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

// Define the PWM frequency and duty range
#define PWM_FREQ 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_MAX 100

// Define the transition time for fading
#define TRANSITION_TIME 1800

// Define the schedule file
#define SCHEDULE_FILE "lighting_schedule.txt"

// Function to handle signal to exit cleanly
void sigint_handler(int sig) {
    // Turn off all relays
    gpioWrite(RELAY1, 0);
    gpioWrite(RELAY2, 0);
    gpioWrite(RELAY3, 0);
    gpioWrite(RELAY4, 0);

    // Release GPIO resources
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set up the PWM channels
    if (gpioSetMode(RELAY1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up PWM channel for relay 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up PWM channel for relay 2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up PWM channel for relay 3\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up PWM channel for relay 4\n");
        gpioTerminate();
        return 1;
    }

    // Set up the PWM frequencies
    if (gpioSetPWMfrequency(RELAY1, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set up PWM frequency for relay 1\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY2, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set up PWM frequency for relay 2\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY3, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set up PWM frequency for relay 3\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPWMfrequency(RELAY4, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set up PWM frequency for relay 4\n");
        gpioTerminate();
        return 1;
    }

    // Read the schedule
    FILE *schedule_file = fopen(SCHEDULE_FILE, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Failed to open schedule file\n");
        gpioTerminate();
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        char time[9];
        char relay[3];
        char on_off[3];
        if (sscanf(line, "%8s %2s %2s", time, relay, on_off) != 3) {
            fprintf(stderr, "Invalid schedule entry: %s\n", line);
            continue;
        }

        int relay_num = atoi(relay);
        if (relay_num != 1 && relay_num != 2 && relay_num != 3 && relay_num != 4) {
            fprintf(stderr, "Invalid relay number: %s\n", line);
            continue;
        }

        int on = atoi(on_off);
        if (on != 0 && on != 1) {
            fprintf(stderr, "Invalid on/off value: %s\n", line);
            continue;
        }

        // Convert time to seconds since midnight
        int hours = atoi(time);
        int minutes = atoi(time + 3);
        int seconds = atoi(time + 6);
        int time_in_seconds = hours * 3600 + minutes * 60 + seconds;

        // Check if the current time matches the schedule entry
        time_t current_time = time(NULL);
