#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU_ADDRESS 0x68
#define REG_PWR_MGMT_1 0x6B
#define REG_GYRO_DATA 0x43
#define GYRO_SENSITIVITY 131.0
#define LOG_INTERVAL 100000 // 100 ms in microseconds

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int main() {
    int i2c_fd = -1;
    int gyro_fd = -1;
    char gyro_log[256];

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Open MPU-6050
    gyro_fd = open("/dev/i2c-1", O_RDWR);
    if (gyro_fd < 0) {
        perror("Failed to open MPU-6050");
        close(i2c_fd);
        return 1;
    }

    // Set I2C bus to use MPU-6050
    if (ioctl(gyro_fd, I2C_SLAVE, MPU_ADDRESS) < 0) {
        perror("Failed to set I2C bus to MPU-6050");
        close(gyro_fd);
        close(i2c_fd);
        return 1;
    }

    // Wake up the sensor
    uint8_t wake_up[] = {0x00};
    if (write(gyro_fd, wake_up, 1) != 1) {
        perror("Failed to wake up the sensor");
        close(gyro_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        close(gyro_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        // Read 6 bytes of gyroscope data
        uint8_t gyro_data[6];
        if (read(gyro_fd, gyro_data, 6) != 6) {
            perror("Failed to read gyroscope data");
            break;
        }

        // Convert signed 16-bit values to degrees/second
        int16_t x = (gyro_data[0] << 8) | gyro_data[1];
        int16_t y = (gyro_data[2] << 8) | gyro_data[3];
        int16_t z = (gyro_data[4] << 8) | gyro_data[5];
        float x_deg_per_s = (float)x * GYRO_SENSITIVITY;
        float y_deg_per_s = (float)y * GYRO_SENSITIVITY;
        float z_deg_per_s = (float)z * GYRO_SENSITIVITY;

        // Log data
        sprintf(gyro_log, "%lu %f %f %f\n", getmicrotime(), x_deg_per_s, y_deg_per_s, z_deg_per_s);
        if (write(1, gyro_log, strlen(gyro_log)) != strlen(gyro_log)) {
            perror("Failed to log data");
            break;
        }

        // Sleep for 100 ms
        usleep(LOG_INTERVAL);
    }

    // Clean up
    close(gyro_fd);
    close(i2c_fd);
    return 0;
}

uint32_t getmicrotime() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec * 1000000 + tv.tv_usec;
}

