#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <gpiod.h>

#define LOG_FILE "vibration_events.log"
#define MAX_EVENTS 5
#define DEFAULT_TIMEOUT 1000

volatile sig_atomic_t exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int timeout = DEFAULT_TIMEOUT;
    if (argc > 1) {
        timeout = atoi(argv[1]);
    }

    // Open the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting signal handler: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Open the GPIO line
    struct gpiod_line *line;
    if ((line = gpiod_line_request_input("gpio17", GPIOD_LINE_ACTIVE_HIGH, GPIOD_LINE_EVENT_RISING | GPIOD_LINE_EVENT_FALLING)) == NULL) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", gpiod_cerr());
        fclose(log_file);
        return 1;
    }

    // Initialize the event buffer
    struct gpiod_line_event events[MAX_EVENTS];
    int event_count = 0;

    // Main loop
    while (!exit_flag) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, timeout, &event, sizeof(event)) != 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit cleanly
                break;
            } else {
                fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
                gpiod_line_release(line);
                fclose(log_file);
                return 1;
            }
        }

        // Log the event
        char timestamp[32];
        struct timeval tv;
        gettimeofday(&tv, NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&tv.tv_sec));
        fprintf(log_file, "%s.%06d %s\n", timestamp, tv.tv_usec, event.value == 1 ? "1" : "0");
        fflush(log_file);
        fsync(fileno(log_file));

        // Add the event to the buffer
        events[event_count % MAX_EVENTS] = event;
        event_count = (event_count + 1) % MAX_EVENTS;

        // Check for earthquake alert
        int high_count = 0;
        for (int i = 0; i < event_count; i++) {
            if (events[i].value == 1) {
                high_count++;
            }
        }
        if (high_count >= 3) {
            fprintf(stderr, "EARTHQUAKE ALERT at %s\n", timestamp);
        }
    }

    // Release the GPIO line and close the log file
    gpiod_line_release(line);
    fclose(log_file);
    return 0;
}

