#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define REG_MR_M 0x02
#define REG_CRA_M 0x00
#define REG_OUT_X_MSB 0x03
#define REG_OUT_X_LSB 0x04
#define REG_OUT_Z_MSB 0x05
#define REG_OUT_Z_LSB 0x06
#define REG_OUT_Y_MSB 0x07
#define REG_OUT_Y_LSB 0x08

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define CSV_FILE "mag_log.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("write");
        exit(1);
    }
}

void read_bytes(int fd, uint8_t reg, uint8_t* buf, size_t len) {
    uint8_t cmd[2] = {I2C_SLAVE, I2C_ADDR};
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl");
        exit(1);
    }
    if (write(fd, cmd, 2) != 2) {
        perror("write");
        exit(1);
    }
    if (write(fd, &reg, 1) != 1) {
        perror("write");
        exit(1);
    }
    if (read(fd, buf, len) != len) {
        perror("read");
        exit(1);
    }
}

void read_magnetometer(int fd) {
    uint8_t data[6];
    read_bytes(fd, REG_OUT_X_MSB, data, 6);
    int16_t x = (data[0] << 8) | data[1];
    int16_t z = (data[2] << 8) | data[3];
    int16_t y = (data[4] << 8) | data[5];
    x -= X_OFFSET;
    y -= Y_OFFSET;
    z -= Z_OFFSET;
    float heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) heading += 360;
    char direction[10];
    if (heading >= 337.5 || heading < 22.5) strcpy(direction, "N");
    else if (heading >= 22.5 && heading < 67.5) strcpy(direction, "NE");
    else if (heading >= 67.5 && heading < 112.5) strcpy(direction, "E");
    else if (heading >= 112.5 && heading < 157.5) strcpy(direction, "SE");
    else if (heading >= 157.5 && heading < 202.5) strcpy(direction, "S");
    else if (heading >= 202.5 && heading < 247.5) strcpy(direction, "SW");
    else if (heading >= 247.5 && heading < 292.5) strcpy(direction, "W");
    else if (heading >= 292.5 && heading < 337.5) strcpy(direction, "NW");
    printf("%s %.2f\n", direction, heading);
    FILE* file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        exit(1);
    }
    fprintf(file, "%f,%.2f,%.2f,%.2f,%.2f\n", time(NULL), x, y, z, heading);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    write_byte(fd, REG_MR_M, 0x00);

    if (write(fd, REG_CRA_REG_M, 0x14) != 1) {
        perror("write");
        exit(1);
    }

    while (running) {
        read_magnetometer(fd);
        usleep(1000000);
    }

    close(fd);
    return 0;
}

