    float heading = atan2f(y, x) * 180 / M_PI;
    if (heading < 0) heading += 360;
    char direction[10];
    if (heading >= 337.5 || heading < 22.5) strcpy(direction, "N");
    else if (heading >= 22.5 && heading < 67.5) strcpy(direction, "NE");
    else if (heading >= 67.5 && heading < 112.5) strcpy(direction, "E");
    else if (heading >= 112.5 && heading < 157.5) strcpy(direction, "SE");
    else if (heading >= 157.5 && heading < 202.5) strcpy(direction, "S");
    else if (heading >= 202.5 && heading < 247.5) strcpy(direction, "SW");
    else if (heading >= 247.5 && heading < 292.5) strcpy(direction, "W");
    else if (heading >= 292.5 && heading < 337.5) strcpy(direction, "NW");
    printf("%s %.2f\n", direction, heading);
    FILE* file = fopen(CSV_FILE, "a");
    if (!file) {
        perror("fopen");
        exit(1);
    }
    fprintf(file, "%f,%.2f,%.2f,%.2f,%.2f\n", time(NULL), x, y, z, heading);
    fclose(file);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    int fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        exit(1);
    }

    write_byte(fd, REG_MR_M, 0x00);

    if (write(fd, REG_CRA_REG_M, 0x14) != 1) {
        perror("write");
        exit(1);
    }

    while (running) {
        read_magnetometer(fd);
        usleep(1000000);
    }

    close(fd);
    return 0;
}
