        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set the relay to OFF initially
    gpioWrite(RELAY_PIN, 0);

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

