#include <libgpiod.h>

#define RELAY1 17
#define RELAY2 23
#define RELAY3 24
#define RELAY4 25

#define RELAY_LINES 4

static volatile int running = 1;
static gpiod_line *lines[RELAY_LINES];

void sigint_handler(int sig) {
    running = 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize random number generator
    srand(time(NULL));

    // Open the gpiochip
    int chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == -1) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    // Request the lines as outputs with an inactive (OFF) drive of 1
    for (int i = 0; i < RELAY_LINES; i++) {
        lines[i] = gpiod_line_request_output(chip, i + RELAY1, GPIOD_LINE_ACTIVE_STATE_HIGH);
        if (lines[i] == NULL) {
            perror("gpiod_line_request_output");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
    }

    // Open the log file
    FILE *log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        perror("fopen");
        gpiod_chip_close(chip);
        for (int i = 0; i < RELAY_LINES; i++) {
            gpiod_line_release(lines[i]);
        }
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Generate a simulated soil-moisture value from 0 to 100
        int moisture = rand() % 101;

        // If the moisture reading is below 30, activate each relay
        if (moisture < 30) {
            for (int i = 0; i < RELAY_LINES; i++) {
                gpiod_line_set_value(lines[i], 0);
                fprintf(stderr, "Relay %d activated at %s\n", i + 1, ctime(&time(NULL)));
                fprintf(log_file, "Relay %d activated at %s with moisture level %d%%\n", i + 1, ctime(&time(NULL)), moisture);
                fflush(log_file);
                sleep(5);
                gpiod_line_set_value(lines[i], 1);
                fprintf(stderr, "Relay %d deactivated at %s\n", i + 1, ctime(&time(NULL)));
                fprintf(log_file, "Relay %d deactivated at %s with moisture level %d%%\n", i + 1, ctime(&time(NULL)), moisture);
                fflush(log_file);
                sleep(1);
            }
        }

        sleep(10);
    }

    // Deactivate all relays
    for (int i = 0; i < RELAY_LINES; i++) {
        gpiod_line_set_value(lines[i], 1);
    }

    // Release the lines
    for (int i = 0; i < RELAY_LINES; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close the chip
    gpiod_chip_close(chip);

    // Close the log file
    fclose(log_file);

    return 0;
}

