#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Signal flags
volatile sig_atomic_t stop_servos = 0;
volatile sig_atomic_t stop_program = 0;

// Function to handle signals
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        stop_servos = 1;
        stop_program = 1;
    }
}

// Function to initialize GPIO
int init_gpio() {
    int ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", ret);
        exit(1);
    }
    return ret;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioTerminate();
}

// Function to set servo position with retries
int set_servo_position(int gpio, int position, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        if (gpioServo(gpio, position) == 0) {
            return 0;
        }
        retries++;
        usleep(100000); // 100 ms
    }
    fprintf(stderr, "Failed to set servo position: %d\n", position);
    return -1;
}

int main() {
    // Initialize GPIO
    int ret = init_gpio();
    if (ret < 0) {
        return ret;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handlers\n");
        cleanup_gpio();
        return 1;
    }

    // Set up servo pins
    int valve_gpio = 17;
    int nozzle_gpio = 18;
    gpioSetMode(valve_gpio, PI_OUTPUT);
    gpioSetMode(nozzle_gpio, PI_OUTPUT);

    // Simulated soil moisture values
    int moisture_values[] = {20, 40, 60, 80, 100};
    int moisture_index = 0;

    while (!stop_program) {
        // Check moisture level
        int moisture = moisture_values[moisture_index];
        if (moisture < 50) {
            // Watering cycle
            // Open valve
            if (set_servo_position(valve_gpio, 1500, 3) != 0) {
                // If valve fails to open, stop watering cycle
                stop_servos = 1;
                break;
            }

            // Sweep nozzle
            int nozzle_positions[] = {0, 450, 1500, 2250, 0};
            for (int i = 0; i < 5; i++) {
                if (set_servo_position(nozzle_gpio, nozzle_positions[i], 3) != 0) {
                    // If nozzle position fails, log error and continue
                    fprintf(stderr, "Error setting nozzle position: %d\n", nozzle_positions[i]);
                }
                usleep(200000000); // 2 seconds
            }

            // Hold nozzle at 90 degrees for 5 seconds
            if (set_servo_position(nozzle_gpio, 1500, 3) != 0) {
                // If nozzle fails to hold position, log error and continue
                fprintf(stderr, "Error setting nozzle position: 1500\n");
            }
            usleep(5000000); // 5 seconds

            // Close valve
            if (set_servo_position(valve_gpio, 500, 3) != 0) {
                // If valve fails to close, print critical warning
                fprintf(stderr, "Warning: failed to close valve\n");
            }
        }

        // Wait 5 seconds before reading next moisture value
        usleep(5000000); // 5 seconds

        // Move to next moisture value
        moisture_index = (moisture_index + 1) % 5;
    }

    // Stop servos
    if (!stop_servos) {
        set_servo_position(valve_gpio, 0, 3);
        set_servo_position(nozzle_gpio, 0, 3);
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

