    gpioWrite(STEPPER_COIL_B, 0);
    gpioWrite(STEPPER_COIL_C, 0);
    gpioWrite(STEPPER_COIL_D, 0);
    gpioTerminate();
    exit(0);
}

// Function to rotate the motor clockwise
void rotate_clockwise(int steps) {
    int i;
    for (i = 0; i < steps; i++) {
        int j;
        for (j = 0; j < 4; j++) {
            gpioWrite(STEPPER_COIL_A, step_sequence[j] & 1);
            gpioWrite(STEPPER_COIL_B, step_sequence[j] & 2);
            gpioWrite(STEPPER_COIL_C, step_sequence[j] & 4);
            gpioWrite(STEPPER_COIL_D, step_sequence[j] & 8);
            usleep(3000); // 3 ms delay
        }
    }
    gpioWrite(STEPPER_COIL_A, 0);
    gpioWrite(STEPPER_COIL_B, 0);
    gpioWrite(STEPPER_COIL_C, 0);
    gpioWrite(STEPPER_COIL_D, 0);
}

// Function to rotate the motor counter-clockwise
void rotate_counter_clockwise(int steps) {
    int i;
    for (i = 0; i < steps; i++) {
        int j;
        for (j = 0; j < 4; j++) {
            gpioWrite(STEPPER_COIL_A, (step_sequence[j] >> 1) & 1);
            gpioWrite(STEPPER_COIL_B, (step_sequence[j] >> 2) & 1);
            gpioWrite(STEPPER_COIL_C, (step_sequence[j] >> 3) & 1);
            gpioWrite(STEPPER_COIL_D, (step_sequence[j] >> 4) & 1);
            usleep(3000); // 3 ms delay
        }
    }
    gpioWrite(STEPPER_COIL_A, 0);
    gpioWrite(STEPPER_COIL_B, 0);
    gpioWrite(STEPPER_COIL_C, 0);
    gpioWrite(STEPPER_COIL_D, 0);
}

int main() {
    int lock_button_state = 1;
    int unlock_button_state = 1;
    int last_lock_button_state = 1;
    int last_unlock_button_state = 1;
