    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %d\n", gpioInitialise());
        return 1;
    }

    // Set up GPIO modes
    if (gpioSetMode(STEPPER_COIL_A, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for STEPPER_COIL_A: %d\n", gpioSetMode(STEPPER_COIL_A, PI_OUTPUT));
        gpioTerminate();
        return 1;
