        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(STEPPER_COIL_C, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for STEPPER_COIL_C: %d\n", gpioSetMode(STEPPER_COIL_C, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(STEPPER_COIL_D, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for STEPPER_COIL_D: %d\n", gpioSetMode(STEPPER_COIL_D, PI_OUTPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LOCK_BUTTON: %d\n", gpioSetMode(LOCK_BUTTON, PI_INPUT));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for UNLOCK_BUTTON: %d\n", gpioSetMode(UNLOCK_BUTTON, PI_INPUT));
        gpioTerminate();
        return 1;
    }

    // Set up pull-up resistors for buttons
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for LOCK_BUTTON: %d\n", gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for UNLOCK_BUTTON: %d\n", gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    while (1) {
        // Read button states
        lock_button_state = gpioRead(LOCK_BUTTON);
        unlock_button_state = gpioRead(UNLOCK_BUTTON);

        // Debounce buttons
        if (lock_button_state != last_lock_button_state || unlock_button_state != last_unlock_button_state) {
