                rotate_clockwise(512);
            } else if (unlock_button_state == 0 && lock_button_state == 1) {
                // Unlock button pressed
                printf("Unlocking...\n");
                rotate_counter_clockwise(512);
            }
            last_lock_button_state = lock_button_state;
            last_unlock_button_state = unlock_button_state;
        }

        // Sleep for a short period to debounce
        usleep(100);
    }

    return 0;
}

