#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_TRIGGER 17
#define GPIO_ECHO 18
#define LOG_FILE "distance_log.txt"
#define MIN_GUARD 60  // ms
#define PULSE_WIDTH_US 10
#define SPEED_OF_SOUND 343.0  // m/s
#define CONVERSION_FACTOR 0.01715  // cm/us

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    int log_fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (log_fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    struct gpiod_line *trigger_line, *echo_line;
    struct gpiod_line_request req;
    struct gpiod_line_request_event req_event;

    if (gpiod_cdev_open("/dev/gpiochip0", 0, 0, &req) != 0) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_byname(req.fd, "gpio17", GPIOD_LINE_REQUEST_OUTPUT, GPIOD_LINE_REQUEST_ACTIVE_HIGH, &trigger_line) != 0) {
        fprintf(stderr, "Failed to request trigger line\n");
        gpiod_cdev_close(req.fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_byname(req.fd, "gpio18", GPIOD_LINE_REQUEST_INPUT, GPIOD_LINE_REQUEST_ACTIVE_HIGH, &echo_line) != 0) {
        fprintf(stderr, "Failed to request echo line\n");
        gpiod_line_release(trigger_line);
        gpiod_cdev_close(req.fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_export(trigger_line);
    gpiod_line_export(echo_line);

    gpiod_line_set_value(trigger_line, 1);
    usleep(PULSE_WIDTH_US * 1000);
    gpiod_line_set_value(trigger_line, 0);

    struct timespec start, end;
    uint64_t duration_us = 0;

    while (running) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
            perror("clock_gettime");
            break;
        }

        gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &req_event);
        if (gpiod_line_event_wait(req_event, 50 * 1000 * 1000) != 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &req_event);
        if (gpiod_line_event_wait(req_event, 50 * 1000 * 1000) != 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("clock_gettime");
            break;
        }

        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration_us < MIN_GUARD * 1000) {
            fprintf(stderr, "Guard time not met\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        double distance_cm = duration_us * CONVERSION_FACTOR;
        fprintf(log_fd, "%.2f\n", distance_cm);
        fflush(log_fd);

        usleep(1000000);  // 1 second
    }

    gpiod_line_unexport(trigger_line);
    gpiod_line_unexport(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_cdev_close(req.fd);
    close(log_fd);

    return 0;
}

