    gpiod_line_set_value(trigger_line, 0);

    struct timespec start, end;
    uint64_t duration_us = 0;

    while (running) {
        if (clock_gettime(CLOCK_MONOTONIC, &start) == -1) {
            perror("clock_gettime");
            break;
        }

        gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_RISING_EDGE, &req_event);
        if (gpiod_line_event_wait(req_event, 50 * 1000 * 1000) != 0) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        gpiod_line_event_subscribe(echo_line, GPIOD_LINE_EVENT_FALLING_EDGE, &req_event);
        if (gpiod_line_event_wait(req_event, 50 * 1000 * 1000) != 0) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        if (clock_gettime(CLOCK_MONOTONIC, &end) == -1) {
            perror("clock_gettime");
            break;
        }

        duration_us = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

        if (duration_us < MIN_GUARD * 1000) {
            fprintf(stderr, "Guard time not met\n");
            fprintf(log_fd, "-1\n");
            fflush(log_fd);
            continue;
        }

        double distance_cm = duration_us * CONVERSION_FACTOR;
        fprintf(log_fd, "%.2f\n", distance_cm);
        fflush(log_fd);

        usleep(1000000);  // 1 second
    }

    gpiod_line_unexport(trigger_line);
    gpiod_line_unexport(echo_line);
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_cdev_close(req.fd);
    close(log_fd);

    return 0;
}
