        i2cClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2cReadReg8(i2c_bus, VL53L1X_ADDRESS, VL53L1X_INTERRUPT_STATUS, 1) == 0x01) {
            uint16_t distance = (uint16_t)i2cReadReg8(i2c_bus, VL53L1X_ADDRESS, VL53L1X_DISTANCE_MSB, 1) << 8 | i2cReadReg8(i2c_bus, VL53L1X_ADDRESS, VL53L1X_DISTANCE_LSB, 1);
            if (distance <= 500) {
                gpioWrite(relay_gpio, 1);
            } else {
                gpioWrite(relay_gpio, 0);
            }
            printf("Distance: %d mm\n", distance);
        }

        usleep(100000);
    }

    i2cClose(i2c_bus);
    gpioWrite(relay_gpio, 0);
    gpioTerminate();

    return 0;
}

