#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDRESS 0x68
#define GYRO_CONFIG 0x1B
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x43

volatile bool running = true;

void signal_handler(int sig) {
    running = false;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buf, int len) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = MPU6050_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = &reg;
    msgs->next = NULL;

    struct i2c_msg *msgs_read = malloc(sizeof(struct i2c_msg));
    msgs_read->addr = MPU6050_ADDRESS;
    msgs_read->flags = I2C_M_RD;
    msgs_read->len = len;
    msgs_read->buf = buf;
    msgs_read->next = NULL;

    int ret = ioctl(fd, I2C_RDWR, msgs);
    if (ret < 0) {
        perror("i2c_read");
        return -1;
    }

    ret = ioctl(fd, I2C_RDWR, msgs_read);
    if (ret < 0) {
        perror("i2c_read");
        free(msgs_read);
        return -1;
    }

    free(msgs_read);
    return 0;
}

int i2c_write(int fd, uint8_t reg, uint8_t val) {
    struct i2c_msg msg;
    struct i2c_msg *msgs = &msg;
    msgs->addr = MPU6050_ADDRESS;
    msgs->flags = 0;
    msgs->len = 1;
    msgs->buf = &reg;
    msgs->next = NULL;

    struct i2c_msg *msgs_write = malloc(sizeof(struct i2c_msg));
    msgs_write->addr = MPU6050_ADDRESS;
    msgs_write->flags = 0;
    msgs_write->len = 1;
    msgs_write->buf = &val;
    msgs_write->next = NULL;

    int ret = ioctl(fd, I2C_RDWR, msgs);
    if (ret < 0) {
        perror("i2c_write");
        free(msgs_write);
        return -1;
    }

    ret = ioctl(fd, I2C_RDWR, msgs_write);
    if (ret < 0) {
        perror("i2c_write");
        free(msgs_write);
        return -1;
    }

    free(msgs_write);
    return 0;
}

int main() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    if (i2c_write(fd, PWR_MGMT_1, 0x06)) {
        close(fd);
        return 1;
    }

    if (i2c_write(fd, GYRO_CONFIG, 0x00)) {
        close(fd);
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t buf[6];
    while (running) {
        if (i2c_read(fd, ACCEL_XOUT_H, buf, 6) < 0) {
            close(fd);
            return 1;
        }

        int16_t x = (buf[0] << 8) | buf[1];
        int16_t y = (buf[2] << 8) | buf[3];
        int16_t z = (buf[4] << 8) | buf[5];

        x = (x * 131.0) / 32768;
        y = (y * 131.0) / 32768;
        z = (z * 131.0) / 32768;

        printf("x: %f, y: %f, z: %f\n", x, y, z);

        usleep(100000);
    }

    close(fd);
    return 0;
}

