// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpiod_chip_close(gpiod_chip);
    gpiod_line_release(gpiod_line_17);
    gpiod_line_release(gpiod_line_18);
    gpiod_line_release(gpiod_line_27);
    gpiod_line_release(gpiod_line_22);
    exit(0);
}

// Function to log a message to the file
void log_message(const char *message) {
    FILE *file = fopen("watering_log.txt", "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(file, "%s\n", message);
    fclose(file);
}

int main() {
    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    // Request lines as outputs with active-low semantics
    gpiod_line *line_17 = gpiod_chip_get_line(chip, 17);
    if (line_17 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line_17, 0, "active-low");
    if (gpiod_line_get_value(line_17) != 0) {
        gpiod_line_set_value(line_17, 0);
    }

    gpiod_line *line_18 = gpiod_chip_get_line(chip, 18);
    if (line_18 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line_17);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line_18, 0, "active-low");
    if (gpiod_line_get_value(line_18) != 0) {
        gpiod_line_set_value(line_18, 0);
    }

    gpiod_line *line_27 = gpiod_chip_get_line(chip, 27);
    if (line_27 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line_27, 0, "active-low");
    if (gpiod_line_get_value(line_27) != 0) {
        gpiod_line_set_value(line_27, 0);
    }

    gpiod_line *line_22 = gpiod_chip_get_line(chip, 22);
    if (line_22 == NULL) {
        perror("gpiod_chip_get_line");
        gpiod_line_release(line_17);
        gpiod_line_release(line_18);
        gpiod_line_release(line_27);
        gpiod_chip_close(chip);
        return 1;
    }
    gpiod_line_request_output(line_22, 0, "active-low");
    if (gpiod_line_get_value(line_22) != 0) {
        gpiod_line_set_value(line_22, 0);
    }

    // Initialize the last water time
    struct timeval last_water_time;
    gettimeofday(&last_water_time, NULL);

    // Main loop
    while (1) {
        struct timeval now;
        gettimeofday(&now, NULL);
        if ((now.tv_sec - last_water_time.tv_sec) >= 86400) {
            // Watering cycle
            log_message("Watering cycle started at %04d-%02d-%02d %02d:%02d:%02d");
            printf("Watering cycle started at %04d-%02d-%02d %02d:%02d:%02d\n",
                   now.tv_sec % 86400, (now.tv_sec / 86400) % 7, (now.tv_sec / (86400 * 7)) % 52,
                   now.tv_sec % 3600 / 60, (now.tv_sec / 60) % 60, now.tv_sec % 60);
            gpiod_line_set_value(line_17, 1);
            sleep(5);
            gpiod_line_set_value(line_17, 0);
            gpiod_line_set_value(line_18, 1);
            sleep(5);
            gpiod_line_set_value(line_18, 0);
            gpiod_line_set_value(line_27, 1);
            sleep(5);
            gpiod_line_set_value(line_27, 0);
            gpiod_line_set_value(line_22, 1);
            sleep(5);
            gpiod_line_set_value(line_22, 0);
            last_water_time = now;
        }
        sleep(60);
    }

    return 0;
}

