            gpioTerminate();
            exit(1);
        }
    }

    // Simulate sunrise
    for (int duty_cycle = 0; duty_cycle <= 255; duty_cycle++) {
        // Log event
        FILE *log_file = fopen("smart_lighting.log", "a");
