        // Set PWM duty cycle
        for (int i = 0; i < 4; i++) {
            if (gpioPWM(pins[i], duty_cycle) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle on pin %d\n", pins[i]);
                gpioTerminate();
                exit(1);
            }
        }

        // Wait 1 second
        usleep(1000000);
    }

    // Release resources
    gpioTerminate();

    return 0;
}

