#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MPU6050_ADDRESS 0x68
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B

#define LED_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 20
#define SAMPLE_RATE_MS 1000 / SAMPLE_RATE_HZ

typedef struct {
    int16_t x, y, z;
    uint32_t timestamp;
} GyroReading;

GyroReading buffer[BUFFER_SIZE];
int bufferHead = 0;
int bufferTail = 0;

void signalHandler(int signal) {
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    int i2cHandle = gpioOpen(2, 1);
    if (i2cHandle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise GPIO\n");
        gpioClose(i2cHandle);
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    // Verify the sensor is present
    uint8_t whoAmI;
    if (i2cWriteReg8(i2cHandle, MPU6050_ADDRESS, WHO_AM_I, 1) < 0) {
        fprintf(stderr, "Failed to write to WHO_AM_I register\n");
        gpioTerminate();
        return 1;
    }
    if (i2cReadReg8(i2cHandle, MPU6050_ADDRESS, WHO_AM_I, &whoAmI, 1) < 0) {
        fprintf(stderr, "Failed to read from WHO_AM_I register\n");
        gpioTerminate();
        return 1;
    }
    if (whoAmI != 0x68) {
        fprintf(stderr, "MPU6050 not found\n");
        gpioTerminate();
        return 1;
    }

    // Wake the sensor
    if (i2cWriteReg8(i2cHandle, MPU6050_ADDRESS, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register\n");
        gpioTerminate();
        return 1;
    }

    // Set the sample rate
    if (i2cWriteReg8(i2cHandle, MPU6050_ADDRESS, SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to write to SMPLRT_DIV register\n");
        gpioTerminate();
        return 1;
    }

    // Set the gyro full-scale range
    if (i2cWriteReg8(i2cHandle, MPU6050_ADDRESS, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to GYRO_CONFIG register\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    while (1) {
        // Read the gyro data
        int bytesRead = i2cReadReg16(i2cHandle, MPU6050_ADDRESS, GYRO_XOUT_H, &buffer[bufferTail].x, 2);
        if (bytesRead < 0) {
            if (bytesRead == -1) {
                // Try to re-initialise the I2C bus
                gpioTerminate();
                i2cHandle = gpioOpen(2, 1);
                if (i2cHandle < 0) {
                    fprintf(stderr, "Failed to open I2C bus\n");
                    return 1;
                }
                if (gpioInitialise() < 0) {
                    fprintf(stderr, "Failed to initialise GPIO\n");
                    gpioClose(i2cHandle);
                    return 1;
                }
                continue;
            } else {
                fprintf(stderr, "Failed to read from GYRO_XOUT_H register\n");
                gpioTerminate();
                return 1;
            }
        }

        bytesRead = i2cReadReg16(i2cHandle, MPU6050_ADDRESS, GYRO_YOUT_H, &buffer[bufferTail].y, 2);
        if (bytesRead < 0) {
            if (bytesRead == -1) {
                // Try to re-initialise the I2C bus
                gpioTerminate();
                i2cHandle = gpioOpen(2, 1);
                if (i2cHandle < 0) {
                    fprintf(stderr, "Failed to open I2C bus\n");
                    return 1;
                }
                if (gpioInitialise() < 0) {
                    fprintf(stderr, "Failed to initialise GPIO\n");
                    gpioClose(i2cHandle);
                    return 1;
                }
                continue;
            } else {
                fprintf(stderr, "Failed to read from GYRO_YOUT_H register\n");
                gpioTerminate();
                return 1;
            }
        }

        bytesRead = i2cReadReg16(i2cHandle, MPU6050_ADDRESS, GYRO_ZOUT_H, &buffer[bufferTail].z, 2);
        if (bytesRead < 0) {
            if (bytesRead == -1) {
                // Try to re-initialise the I2C bus
                gpioTerminate();
                i2cHandle = gpioOpen(2, 1);
                if (i2cHandle < 0) {
                    fprintf(stderr, "Failed to open I2C bus\n");
                    return 1;
                }
                if (gpioInitialise() < 0) {
                    fprintf(stderr, "Failed to initialise GPIO\n");
                    gpioClose(i2cHandle);
                    return 1;
                }
                continue;
            } else {
                fprintf(stderr, "Failed to read from GYRO_ZOUT_H register\n");
                gpioTerminate();
                return 1;
            }
        }

        // Convert the signed 16-bit big-endian values to degrees/second
        buffer[bufferTail].x = (int16_t)((buffer[bufferTail].x >> 8) | (buffer[bufferTail].x << 8));
        buffer[bufferTail].y = (int16_t)((buffer[bufferTail].y >> 8) | (buffer[bufferTail].y << 8));
        buffer[bufferTail].z = (int16_t)((buffer[bufferTail].z >> 8) | (buffer[bufferTail].z << 8));

        // Store the reading with its timestamp
        buffer[bufferTail].timestamp = time(NULL);

        // Check if the absolute value of any axis exceeds 250 deg/s
        if (abs(buffer[bufferTail].x) > 250 || abs(buffer[bufferTail].y) > 250 || abs(buffer[bufferTail].z) > 250) {
            gpioWrite(LED_PIN, 1);
        } else {
            gpioWrite(LED_PIN, 0);
        }

        // Move to the next buffer entry
        bufferTail = (bufferTail + 1) % BUFFER_SIZE;

        // Sleep for the remaining time to reach the desired sample rate
        usleep(SAMPLE_RATE_MS * 1000 - (time(NULL) - buffer[bufferTail].timestamp) * 1000);
    }

    return 0;
}

