#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define SPI_BUS 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_LSB_FIRST 0
#define SPI_CS_PIN 8
#define SPI_CS_LINE "chip-select-0"
#define LED_PIN 17
#define BUFFER_SIZE 64
#define MAX_DEG_PER_SEC 200.0
#define SENSITIVITY 131.0

struct gyroscope_data {
    uint16_t timestamp;
    float x;
    float y;
    float z;
};

struct gyroscope_data buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

void signal_handler(int sig) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%d,%f,%f,%f\n", buffer[i].timestamp, buffer[i].x, buffer[i].y, buffer[i].z);
    }
    close_spi();
    gpiod_close(gpio_fd);
    gpiod_release(gpio_fd);
    exit(0);
}

int open_spi() {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(1);
    }
    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(1);
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        exit(1);
    }
    return fd;
}

void close_spi() {
    close(gpio_fd);
    close(spidev_fd);
}

int open_gpio() {
    gpio_fd = gpiod_open(SPI_CS_LINE, GPIOD_LINEHANDLE);
    if (gpio_fd < 0) {
        perror("Failed to open GPIO line");
        exit(1);
    }
    if (gpiod_direction(gpio_fd, GPIOD_OUT) < 0) {
        perror("Failed to set GPIO direction");
        gpiod_close(gpio_fd);
        exit(1);
    }
    gpiod_line_request_output(gpio_fd, GPIOD_LINEHANDLE, 0);
}

void close_gpio() {
    gpiod_close(gpio_fd);
}

void read_gyroscope_data() {
    uint8_t reg = 0x43;
    uint8_t data[2];
    gpiod_line_set_value(gpio_fd, GPIOD_LINEHANDLE, 1);
    if (ioctl(spidev_fd, SPI_IOC_MESSAGE(1, &reg, data, 2) < 0)) {
        perror("Failed to read gyroscope data");
        return;
    }
    gpiod_line_set_value(gpio_fd, GPIOD_LINEHANDLE, 0);
    uint16_t x = (data[0] << 8) | data[1];
    if (x == 0 || x == 0xFFFF) {
        return;
    }
    x = (x >> 1) ^ ((x & 1) ? 0x7FFF : 0);
    buffer[buffer_head].timestamp = time(NULL);
    buffer[buffer_head].x = (float)x * SENSITIVITY;
    if (buffer[buffer_head].x > MAX_DEG_PER_SEC || buffer[buffer_head].x < -MAX_DEG_PER_SEC) {
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(gpio_fd, GPIOD_LINEHANDLE, 1);
            usleep(500000);
            gpiod_line_set_value(gpio_fd, GPIOD_LINEHANDLE, 0);
            usleep(500000);
        }
    }
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
}

int main() {
    signal(SIGINT, signal_handler);
    spidev_fd = open_spi();
    open_gpio();
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer[i].timestamp = 0;
        buffer[i].x = 0;
        buffer[i].y = 0;
        buffer[i].z = 0;
    }
    while (1) {
        read_gyroscope_data();
        if (buffer_head == buffer_tail) {
            buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
        }
    }
    return 0;
}

