#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU_ADDRESS 0x68
#define ACCEL_CONFIG 0x1C
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GPIO_LED 21

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void cleanup() {
    gpioSetMode(GPIO_LED, GPIO_MODE_OUTPUT);
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
    i2cClose(I2C_BUS);
    fclose(log_file);
    printf("Cleanup complete.\n");
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    if (i2cOpen(I2C_BUS, MPU_ADDRESS) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        cleanup();
    }

    // Wake up the sensor
    uint8_t pwr_mgmt_1 = 0x00;
    if (i2cWriteReg(I2C_BUS, PWR_MGMT_1, &pwr_mgmt_1, 1) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1.\n");
        cleanup();
    }

    // Set accelerometer full-scale range to ±2g
    uint8_t accel_config = 0x00;
    if (i2cWriteReg(I2C_BUS, ACCEL_CONFIG, &accel_config, 1) < 0) {
        fprintf(stderr, "Failed to write to ACCEL_CONFIG.\n");
        cleanup();
    }

    // Verify successful configuration
    uint8_t config = 0x00;
    if (i2cReadReg(I2C_BUS, ACCEL_CONFIG, &config, 1) < 0) {
        fprintf(stderr, "Failed to read from ACCEL_CONFIG.\n");
        cleanup();
    }
    if (config != 0x00) {
        fprintf(stderr, "Failed to set accelerometer full-scale range.\n");
        cleanup();
    }

    // Open log file
    FILE *log_file = fopen("tilt_log.txt", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
    }

    // Set up LED
    gpioSetMode(GPIO_LED, GPIO_MODE_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    // Main loop
    while (running) {
        // Read accelerometer data
        uint8_t data[6];
        if (i2cReadReg(I2C_BUS, ACCEL_XOUT_H, data, 6) < 0) {
            fprintf(stderr, "Failed to read from accelerometer.\n");
            continue;
        }

        // Compute roll and pitch
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];
        double roll = atan2(y, z) * 180 / M_PI;
        double pitch = atan2(-x, sqrt(y * y + z * z)) * 180 / M_PI;

        // Log reading
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);

        // Print roll and pitch to console
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        // Turn on LED if roll or pitch exceeds 45 degrees
        if (abs(roll) > 45 || abs(pitch) > 45) {
            gpioWrite(GPIO_LED, 1);
        } else {
            gpioWrite(GPIO_LED, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    cleanup();
    return 0;
}

