#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <string.h>
#include <time.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define GPIO_DEV "/sys/class/gpio/gpio17/value"
#define LOG_FILE "biometric_log.txt"
#define RETRIES 3
#define DELAY 10
#define READ_INTERVAL 100

static int i2c_fd = -1;
static int gpio_fd = -1;
static bool running = true;

void cleanup(int sig) {
    running = false;
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (gpio_fd != -1) {
        gpiod_line_release(gpio_fd);
        gpio_fd = -1;
    }
    gpiod_cleanup();
    fclose(log_file);
}

void log_reading(uint16_t ambient_light, uint16_t proximity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,AmbientLight:%04x,Proximity:%04x\n", timestamp, ambient_light, proximity);
    fflush(log_file);
}

int read_i2c(uint8_t reg) {
    uint8_t buf[2];
    int retries = 0;
    while (retries < RETRIES) {
        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("ioctl");
            return -1;
        }
        if (write(i2c_fd, &reg, 1) != 1) {
            perror("write");
            return -1;
        }
        if (read(i2c_fd, buf, 2) != 2) {
            perror("read");
            return -1;
        }
        if (buf[0] == reg && buf[1] == 0x00) {
            return (buf[2] << 8) | buf[3];
        }
        retries++;
        usleep(DELAY * 1000);
    }
    return -1;
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        return 1;
    }

    gpio_fd = gpiod_line_request_output("gpio17", NULL);
    if (gpio_fd < 0) {
        perror("gpiod_line_request_output");
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (running) {
        uint16_t ambient_light = read_i2c(0x20);
        uint16_t proximity = read_i2c(0x22);
        log_reading(ambient_light, proximity);
        if (proximity > 100) {
            gpiod_line_set_value(gpio_fd, 1);
        } else {
            gpiod_line_set_value(gpio_fd, 0);
        }
        usleep(READ_INTERVAL * 1000);
    }

    return 0;
}

