    if (!log_file) {
        perror("fopen");
        return 1;
    }

    while (running) {
        uint16_t ambient_light = read_i2c(0x20);
        uint16_t proximity = read_i2c(0x22);
        log_reading(ambient_light, proximity);
        if (proximity > 100) {
            gpiod_line_set_value(gpio_fd, 1);
        } else {
            gpiod_line_set_value(gpio_fd, 0);
        }
        usleep(READ_INTERVAL * 1000);
