                fprintf(stderr, "Error reading Y axis angular rate: %s\n", pigpioErrorStr(pigpioError()));
                break;
            }
        }
        y_rate = (y_dummy << 8) | y_addr;

        // Log the data
        time_t timestamp = time(NULL);
        fprintf(gyro_file, "%lu.%06lu, %d, %d\n", (unsigned long)timestamp, (unsigned long)timestamp * 1000000, x_rate, y_rate);

        // Delay for 10 ms
        usleep(10000);
    }

    // Close SPI
    if (spiClose(spi) != 0) {
        fprintf(stderr, "Error closing SPI: %s\n", pigpioErrorStr(pigpioError()));
    }

    // Flush and close the file
    if (fclose(gyro_file) != 0) {
        fprintf(stderr, "Error closing file: %s\n", strerror(errno));
    }

    // Terminate pigpio
    pigpioTerminate();

    return 0;
