#include <signal.h>
#include <pigpio.h>

// Define constants
#define ALERT_PIN 17
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define SEISMIC_DURATION 500000  // 500 milliseconds
#define LOG_FILE "seismic_events.txt"

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Close the log file
    fclose(log_file);
    // Set the alert pin LOW
    gpioWrite(ALERT_PIN, 0);
    // Terminate pigpio
    gpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Install SIGINT and SIGTERM signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file '%s'\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up the alert pin as an output
    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up alert pin\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up the sensors as inputs with pull-down resistors
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0 || gpioSetPullUpDnControl(SENSOR1_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set up sensor 1\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0 || gpioSetPullUpDnControl(SENSOR2_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set up sensor 2\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register edge-triggered callbacks for both sensors
    if (gpioSetAlertFunc(SENSOR1_PIN, PI_RISING_EDGE, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register sensor 1 callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR2_PIN, PI_RISING_EDGE, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register sensor 2 callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up the callback for both falling edges
    if (gpioSetAlertFunc(SENSOR1_PIN, PI_FALLING_EDGE, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register sensor 1 falling edge callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFunc(SENSOR2_PIN, PI_FALLING_EDGE, sensor_callback) < 0) {
        fprintf(stderr, "Failed to register sensor 2 falling edge callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Run indefinitely
    while (1) {
        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick) {
    // Check if both sensors are HIGH
    if (gpioRead(SENSOR1_PIN) == 1 && gpioRead(SENSOR2_PIN) == 1) {
        // Check if the duration is long enough
        if (tick - last_tick >= SEISMIC_DURATION) {
            // Set the alert pin HIGH
            gpioWrite(ALERT_PIN, 1);
            // Log the event
            fprintf(log_file, "%s - Seismic event detected!\n", ctime(&tick));
            // Reset the last tick
            last_tick = tick;
        }
    } else {
        // Reset the last tick
        last_tick = 0;
    }
}

// Global variables
FILE *log_file;
uint32_t last_tick = 0;

