#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define MAX_BUFFER_SIZE 100
#define SPI_BUS 0
#define SPI_CE 8
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_LED 17
#define SPI_THRESHOLD 20.0
#define SPI_SENSITIVITY 200

// Thread-safe, in-memory circular buffer
typedef struct {
    int head;
    int tail;
    int count;
    double buffer[MAX_BUFFER_SIZE];
} Buffer;

void buffer_init(Buffer *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
}

bool buffer_is_full(Buffer *buf) {
    return buf->count == MAX_BUFFER_SIZE;
}

bool buffer_is_empty(Buffer *buf) {
    return buf->count == 0;
}

void buffer_push(Buffer *buf, double value) {
    if (buffer_is_full(buf)) {
        buf->head = (buf->head + 1) % MAX_BUFFER_SIZE;
    }
    buf->buffer[buf->tail] = value;
    buf->tail = (buf->tail + 1) % MAX_BUFFER_SIZE;
    buf->count++;
}

double buffer_pop(Buffer *buf) {
    if (buffer_is_empty(buf)) {
        return 0.0;
    }
    double value = buf->buffer[buf->head];
    buf->head = (buf->head + 1) % MAX_BUFFER_SIZE;
    buf->count--;
    return value;
}

void sigint_handler(int sig) {
    // Clean up resources
    gpio_spi_close(SPI_BUS);
    gpio_write(SPI_LED, 0);
    pigpio_stop();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Initialize LED
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        pigpio_stop();
        return 1;
    }
    if (gpio_set_mode(SPI_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED mode\n");
        pigpio_stop();
        return 1;
    }
    if (gpio_write(SPI_LED, 0) < 0) {
        fprintf(stderr, "Failed to set LED state\n");
        pigpio_stop();
        return 1;
    }

    // Initialize SPI
    if (gpio_spi_open(SPI_BUS, SPI_CE, SPI_SCLK, SPI_MOSI, SPI_MISO) < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        pigpio_stop();
        return 1;
    }
    if (gpio_spi_set_speed(SPI_BUS, 1000000) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        pigpio_stop();
        return 1;
    }
    if (gpio_spi_set_mode(SPI_BUS, 0, 0) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        pigpio_stop();
        return 1;
    }

    // Initialize buffer
    Buffer buffer;
    buffer_init(&buffer);

    // Set up signal handler for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        // Read gyroscope data
        uint16_t xh, xl;
        if (gpio_spi_xfer(SPI_BUS, 0x02 | 0x80, &xh, 1) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            pigpio_stop();
            return 1;
        }
        if (gpio_spi_xfer(SPI_BUS, 0x03 | 0x80, &xl, 1) < 0) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            pigpio_stop();
            return 1;
        }
        uint16_t x = (xh << 8) | xl;
        if (x & 0x8000) {
            x -= 0x10000;
        }
        double rate = (double)x / SPI_SENSITIVITY;

        // Store reading in buffer
        buffer_push(&buffer, rate);

        // Check if rate exceeds threshold
        if (fabs(rate) > SPI_THRESHOLD) {
            gpio_write(SPI_LED, 1);
        } else {
            gpio_write(SPI_LED, 0);
        }

        // Print reading
        printf("%f\n", rate);

        // Sleep for 10ms
        usleep(10000);
    }

    return 0;
}

