#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define LOG_FILE "touch_relay.log"
#define RELAY_GPIO 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x5A
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE 0x21
#define CHARGE_TIME 0x0D
#define RUN_MODE 0x0D
#define ELECTRODE 0

static FILE *log_file = NULL;

void sigint_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int i2c_fd;
    int gpio_fd;
    int touch_status = 0;
    int prev_touch_status = 0;
    struct tm *timestamp;
    char timestamp_str[20];

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %s", gpioErrorStr(gpioInitError()));
        exit(1);
    }

    // Set GPIO17 as output
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 as output: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }

    // Set GPIO17 to LOW
    if (gpioWrite(RELAY_GPIO, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 to LOW: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }

    // Open I2C device
    i2c_fd = gpioOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }

    // Configure MPR121
    if (i2cWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x80: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x5E, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x5E: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x5D, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x5D: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x41, TOUCH_THRESHOLD) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x41: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x42, RELEASE_THRESHOLD) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x42: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x5B, DEBOUNCE) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x5B: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x5C, CHARGE_TIME) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x5C: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }
    if (i2cWriteReg8(i2c_fd, 0x5E, RUN_MODE) < 0) {
        syslog(LOG_ERR, "Failed to write to register 0x5E: %s", gpioErrorStr(gpioError()));
        gpioTerminate();
        exit(1);
    }

    while (1) {
        // Read touch status
        if (i2cReadReg8(i2c_fd, 0x00, &touch_status) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x00: %s", gpioErrorStr(gpioError()));
            gpioTerminate();
            exit(1);
        }
        if (i2cReadReg8(i2c_fd, 0x01, &touch_status) < 0) {
            syslog(LOG_ERR, "Failed to read from register 0x01: %s", gpioErrorStr(gpioError()));
            gpioTerminate();
            exit(1);
        }

        // Debounce touch events
        if (touch_status != prev_touch_status) {
            if (touch_status & (1 << ELECTRODE)) {
                if (gpioRead(RELAY_GPIO) == 0) {
                    if (gpioWrite(RELAY_GPIO, 1) < 0) {
                        syslog(LOG_ERR, "Failed to set GPIO17 to HIGH: %s", gpioErrorStr(gpioError()));
                        gpioTerminate();
                        exit(1);
                    }
                }
            } else {
                if (gpioRead(RELAY_GPIO) == 1) {
                    if (gpioWrite(RELAY_GPIO, 0) < 0) {
                        syslog(LOG_ERR, "Failed to set GPIO17 to LOW: %s", gpioErrorStr(gpioError()));
                        gpioTerminate();
                        exit(1);
                    }
                }
            }
            prev_touch_status = touch_status;
        }

        // Log touch status
        timestamp = localtime(&time(NULL));
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timestamp);
        fprintf(log_file, "%s: Touch status: 0x%02x\n", timestamp_str, touch_status);

        // Sleep for 10 ms
        usleep(10000);
    }

    return 0;
}

