#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO17 17
#define GPIO18 18
#define GPIO23 23
#define DEBOUNCE_INTERVAL 50  // ms
#define DEBOUNCE_COUNT 3

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpiod_close(ctx);
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize the logger
    openlog(NULL, LOG_PID | LOG_CONS, LOG_USER);
    setlogmask(LOG_UPTO(LOG_INFO));

    // Open the log file
    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        exit(1);
    }

    // Initialize the GPIO context
    ctx = gpiod_ctx_new();
    if (!ctx) {
        syslog(LOG_ERR, "Failed to create GPIO context");
        fclose(log_file);
        exit(1);
    }

    // Initialize the GPIO lines
    gpio17 = gpiod_chip_get_line(ctx, GPIO17);
    gpio18 = gpiod_chip_get_line(ctx, GPIO18);
    gpio23 = gpiod_chip_get_line(ctx, GPIO23);

    if (!gpio17 || !gpio18 || !gpio23) {
        syslog(LOG_ERR, "Failed to get GPIO lines");
        gpiod_ctx_free(ctx);
        fclose(log_file);
        exit(1);
    }

    // Set the GPIO lines as input/output
    if (gpiod_line_request_output(gpio17, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 as output");
        gpiod_ctx_free(ctx);
        fclose(log_file);
        exit(1);
    }
    if (gpiod_line_request_output(gpio18, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO18 as output");
        gpiod_ctx_free(ctx);
        fclose(log_file);
        exit(1);
    }
    if (gpiod_line_request_direction(gpio23, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO23 as output");
        gpiod_ctx_free(ctx);
        fclose(log_file);
        exit(1);
    }

    // Initialize the debounce counter
    debounce_count = 0;

    // Main loop
    while (1) {
        // Read the flame sensor
        int value = gpiod_line_get_value(gpio17);
        if (value < 0) {
            syslog(LOG_ERR, "Failed to read GPIO17");
            break;
        }

        // Debounce the sensor reading
        if (value == 0 && debounce_count < DEBOUNCE_COUNT) {
            debounce_count++;
        } else if (value == 1 && debounce_count > 0) {
            debounce_count = 0;
        }

        // Check if flame is detected
        if (debounce_count == DEBOUNCE_COUNT) {
            // Activate the buzzer and LED
            gpiod_line_set_value(gpio18, 1);
            gpiod_line_set_value(gpio23, 1);

            // Log the event
            syslog(LOG_INFO, "Flame Detected");
            fprintf(log_file, "%lu Flame Detected\n", time(NULL));
            fflush(log_file);
        } else {
            // Deactivate the buzzer and LED
            gpiod_line_set_value(gpio18, 0);
            gpiod_line_set_value(gpio23, 0);
        }

        // Sleep for the debounce interval
        usleep(DEBOUNCE_INTERVAL * 1000);
    }

    // Release the GPIO lines
    gpiod_line_release(gpio17);
    gpiod_line_release(gpio18);
    gpiod_line_release(gpio23);

    // Close the log file
    fclose(log_file);

    // Free the GPIO context
    gpiod_ctx_free(ctx);

    // Close the logger
    closelog();

    return 0;
}

