#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define DISPENSE_DURATION 1000
#define DISPENSE_INTERVAL 5000000
#define DISPENSE_LOG_FILE "dispense_log.txt"

void sigint_handler(int sig) {
    gpioTerminate();
    exit(0);
}

int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

int configure_gpio(int pin, int direction) {
    if (gpioSetMode(pin, direction) < 0) {
        fprintf(stderr, "Failed to configure GPIO%d as %s: %s\n", pin, direction == GPIO_MODE_OUTPUT ? "output" : "input", strerror(errno));
        return 1;
    }
    return 0;
}

int log_dispense(int solenoid1, int solenoid2, int duration) {
    FILE *file = fopen(DISPENSE_LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open dispense log file: %s\n", strerror(errno));
        return 1;
    }
    time_t now = time(NULL);
    struct tm *timestamp = localtime(&now);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d: Solenoids %d and %d activated for %d ms\n",
            timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday, timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec, solenoid1, solenoid2, duration);
    fclose(file);
    return 0;
}

int dispense() {
    if (gpioWrite(17, 1) < 0 || gpioWrite(27, 1) < 0) {
        fprintf(stderr, "Failed to activate solenoids: %s\n", strerror(errno));
        return 1;
    }
    gpioDelay(DISPENSE_DURATION / 2);
    if (gpioWrite(17, 0) < 0 || gpioWrite(27, 0) < 0) {
        fprintf(stderr, "Failed to deactivate solenoids: %s\n", strerror(errno));
        return 1;
    }
    gpioDelay(DISPENSE_DURATION / 2);
    return 0;
}

int main() {
    if (init_pigpio() != 0) {
        return 1;
    }
    if (configure_gpio(17, GPIO_MODE_OUTPUT) != 0 || configure_gpio(27, GPIO_MODE_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }
    signal(SIGINT, sigint_handler);
    while (1) {
        if (dispense() != 0) {
            break;
        }
        log_dispense(17, 27, DISPENSE_DURATION);
        gpioDelay(DISPENSE_INTERVAL);
    }
    gpioTerminate();
    return 0;
}

