#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_MOTOR_A_FORWARD 17
#define GPIO_MOTOR_A_BACKWARD 18
#define GPIO_MOTOR_B_FORWARD 22
#define GPIO_MOTOR_B_BACKWARD 23
#define GPIO_ENABLE_A 24
#define GPIO_ENABLE_B 25
#define LOG_FILE "balance_log.txt"
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define PID_DT 0.05
#define DISTANCE_THRESHOLD 20.0
#define SPEED_MAX 255

volatile int running = 1;

void sigint_handler(int sig) {
    running = 0;
}

void pid_controller(float *motor_a_speed, float *motor_b_speed, float tilt_error, float distance) {
    float error = tilt_error;
    float integral = 0.0;
    float derivative = 0.0;

    *motor_a_speed = 0.0;
    *motor_b_speed = 0.0;

    integral += error * PID_DT;
    derivative = (error - tilt_error) / PID_DT;

    *motor_a_speed = PID_KP * error + PID_KI * integral + PID_KD * derivative;
    *motor_b_speed = -PID_KP * error - PID_KI * integral - PID_KD * derivative;

    if (*motor_a_speed > SPEED_MAX) {
        *motor_a_speed = SPEED_MAX;
    } else if (*motor_a_speed < -SPEED_MAX) {
        *motor_a_speed = -SPEED_MAX;
    }

    if (*motor_b_speed > SPEED_MAX) {
        *motor_b_speed = SPEED_MAX;
    } else if (*motor_b_speed < -SPEED_MAX) {
        *motor_b_speed = -SPEED_MAX;
    }
}

int main() {
    int log_fd = -1;
    int motor_a_forward = -1;
    int motor_a_backward = -1;
    int motor_b_forward = -1;
    int motor_b_backward = -1;
    int enable_a = -1;
    int enable_b = -1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    motor_a_forward = gpioOpen(GPIO_MOTOR_A_FORWARD);
    motor_a_backward = gpioOpen(GPIO_MOTOR_A_BACKWARD);
    motor_b_forward = gpioOpen(GPIO_MOTOR_B_FORWARD);
    motor_b_backward = gpioOpen(GPIO_MOTOR_B_BACKWARD);
    enable_a = gpioOpen(GPIO_ENABLE_A);
    enable_b = gpioOpen(GPIO_ENABLE_B);

    if (motor_a_forward < 0 || motor_a_backward < 0 || motor_b_forward < 0 || motor_b_backward < 0 || enable_a < 0 || enable_b < 0) {
        fprintf(stderr, "Failed to open GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(motor_a_forward, PI_OUTPUT);
    gpioSetMode(motor_a_backward, PI_OUTPUT);
    gpioSetMode(motor_b_forward, PI_OUTPUT);
    gpioSetMode(motor_b_backward, PI_OUTPUT);
    gpioSetMode(enable_a, PI_OUTPUT);
    gpioSetMode(enable_b, PI_OUTPUT);

    gpioWrite(enable_a, 1);
    gpioWrite(enable_b, 1);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    srand(time(NULL));

    while (running) {
        float tilt_error = (float)rand() / RAND_MAX * 20.0 - 10.0;
        float distance = (float)rand() / RAND_MAX * 398.0 + 2.0;

        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(motor_a_forward, 0);
            gpioWrite(motor_a_backward, 1);
            gpioWrite(motor_b_forward, 0);
            gpioWrite(motor_b_backward, 1);
            gpioPWM(motor_a_backward, 50);
            gpioPWM(motor_b_backward, 50);
        } else {
            pid_controller(&motor_a_speed, &motor_b_speed, tilt_error, distance);

            gpioWrite(motor_a_forward, motor_a_speed > 0);
            gpioWrite(motor_a_backward, motor_a_speed < 0);
            gpioWrite(motor_b_forward, motor_b_speed > 0);
            gpioWrite(motor_b_backward, motor_b_speed < 0);

            gpioPWM(motor_a_forward, abs(motor_a_speed));
            gpioPWM(motor_a_backward, abs(motor_a_speed));
            gpioPWM(motor_b_forward, abs(motor_b_speed));
            gpioPWM(motor_b_backward, abs(motor_b_speed));
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
