    motor_a_backward = gpioOpen(GPIO_MOTOR_A_BACKWARD);
    motor_b_forward = gpioOpen(GPIO_MOTOR_B_FORWARD);
    motor_b_backward = gpioOpen(GPIO_MOTOR_B_BACKWARD);
    enable_a = gpioOpen(GPIO_ENABLE_A);
    enable_b = gpioOpen(GPIO_ENABLE_B);

    if (motor_a_forward < 0 || motor_a_backward < 0 || motor_b_forward < 0 || motor_b_backward < 0 || enable_a < 0 || enable_b < 0) {
        fprintf(stderr, "Failed to open GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    gpioSetMode(motor_a_forward, PI_OUTPUT);
    gpioSetMode(motor_a_backward, PI_OUTPUT);
    gpioSetMode(motor_b_forward, PI_OUTPUT);
    gpioSetMode(motor_b_backward, PI_OUTPUT);
    gpioSetMode(enable_a, PI_OUTPUT);
    gpioSetMode(enable_b, PI_OUTPUT);

    gpioWrite(enable_a, 1);
    gpioWrite(enable_b, 1);

    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
