        if (!buffer) {
            fprintf(stderr, "Error allocating memory for ALSA buffer\n");
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
