            }

            float rms = sqrt(sum / params.period_size);
            float color = (rms * sensitivity) / 32768.0f;
            color = (color < 0.1f) ? 0.1f : (color > 1.0f) ? 1.0f : color;

            float r = 0, g = 0, b = 0;
            if (color < 0.33f) {
