                g = (color / 0.33f) * 255;
                b = 0;
            } else if (color < 0.66f) {
                r = (color - 0.33f) / 0.33f * 255;
                g = 255;
                b = 0;
            } else {
                r = 255;
                g = (1.0f - (color - 0.66f) / 0.33f) * 255;
                b = 0;
            }

