            }

            gpioPWM(LED_RED, r * 65535);
            gpioPWM(LED_GREEN, g * 65535);
            gpioPWM(LED_BLUE, b * 65535);

            t += 0.01;
            usleep(10000);
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    gpioSetMode(LED_RED, PI_OUTPUT);
    gpioSetMode(LED_GREEN, PI_OUTPUT);
    gpioSetMode(LED_BLUE, PI_OUTPUT);

    return main(argc, argv);
}

