            fprintf(stderr, "Error setting ALSA rate: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            return 1;
        }

        if (snd_pcm_hw_params_set_channels(params.handle, params.hw_params, params.channels) < 0) {
            fprintf(stderr, "Error setting ALSA channels: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            return 1;
        }

        if (snd_pcm_hw_params_set_format(params.handle, params.hw_params, params.format) < 0) {
            fprintf(stderr, "Error setting ALSA format: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            return 1;
        }

        if (snd_pcm_hw_params_set_period_size(params.handle, params.hw_params, params.period_size, 0) < 0) {
            fprintf(stderr, "Error setting ALSA period size: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            return 1;
        }

        if (snd_pcm_sw_params_malloc(&params.sw_params) < 0) {
            fprintf(stderr, "Error allocating ALSA software parameters: %s\n", snd_strerror(-1));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            return 1;
        }

        if (snd_pcm_sw_params_current(params.handle, params.sw_params) < 0) {
            fprintf(stderr, "Error getting ALSA software parameters: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        if (snd_pcm_sw_params_set_start_threshold(params.handle, params.sw_params, 0) < 0) {
            fprintf(stderr, "Error setting ALSA start threshold: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        if (snd_pcm_sw_params_set_stop_threshold(params.handle, params.sw_params, 0) < 0) {
            fprintf(stderr, "Error setting ALSA stop threshold: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        if (snd_pcm_sw_params_set_period_event(params.handle, params.sw_params, 1) < 0) {
            fprintf(stderr, "Error setting ALSA period event: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        if (snd_pcm_sw_params_apply(params.handle, params.sw_params) < 0) {
            fprintf(stderr, "Error applying ALSA software parameters: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        if (snd_pcm_prepare(params.handle) < 0) {
            fprintf(stderr, "Error preparing ALSA device: %s\n", snd_strerror(snd_pcm_status(params.handle)));
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        int16_t *buffer = malloc(params.period_size * params.channels * sizeof(int16_t));
        if (!buffer) {
            fprintf(stderr, "Error allocating memory for ALSA buffer\n");
            snd_pcm_close(params.handle);
            snd_pcm_hw_params_free(params.hw_params);
            snd_pcm_sw_params_free(params.sw_params);
            return 1;
        }

        while (1) {
            int bytes_read = snd_pcm_readi(params.handle, buffer, params.period_size);
            if (bytes_read < 0) {
                if (bytes_read == -EPIPE) {
                    snd_pcm_prepare(params.handle);
                } else if (bytes_read == -ESTRPIPE) {
                    snd_pcm_resume(params.handle);
                } else {
                    fprintf(stderr, "Error reading ALSA device: %s\n", snd_strerror(snd_pcm_status(params.handle)));
                    snd_pcm_close(params.handle);
                    snd_pcm_hw_params_free(params.hw_params);
                    snd_pcm_sw_params_free(params.sw_params);
                    free(buffer);
                    return 1;
                }
            }

            float sum = 0;
            for (int i = 0; i < params.period_size; i++) {
                sum += (float)buffer[i] * buffer[i];
            }

            float rms = sqrt(sum / params.period_size);
            float color = (rms * sensitivity) / 32768.0f;
            color = (color < 0.1f) ? 0.1f : (color > 1.0f) ? 1.0f : color;

            float r = 0, g = 0, b = 0;
            if (color < 0.33f) {
                r = 0;
                g = (color / 0.33f) * 255;
                b = 0;
            } else if (color < 0.66f) {
                r = (color - 0.33f) / 0.33f * 255;
                g = 255;
                b = 0;
            } else {
                r = 255;
                g = (1.0f - (color - 0.66f) / 0.33f) * 255;
                b = 0;
            }

            gpioPWM(LED_RED, r * 65535);
            gpioPWM(LED_GREEN, g * 65535);
            gpioPWM(LED_BLUE, b * 65535);

            usleep(10000);
        }

        snd_pcm_close(params.handle);
        snd_pcm_hw_params_free(params.hw_params);
        snd_pcm_sw_params_free(params.sw_params);
        free(buffer);
    } else {
        float t = 0;
        while (1) {
            float r = 0, g = 0, b = 0;
            if (sin(t) < 0) {
                r = 0;
                g = (sin(t) / -1) * 255;
                b = 0;
            } else if (sin(t) < 0.5) {
                r = (sin(t) / 0.5) * 255;
                g = 255;
                b = 0;
            } else {
                r = 255;
                g = (1.0f - (sin(t) - 0.5) / 0.5) * 255;
                b = 0;
            }

            gpioPWM(LED_RED, r * 65535);
            gpioPWM(LED_GREEN, g * 65535);
            gpioPWM(LED_BLUE, b * 65535);

            t += 0.01;
            usleep(10000);
        }
    }

    return 0;
}

int main(int argc, char **argv) {
    signal(SIGINT, sighandler);
    signal(SIGTERM, sighandler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    gpioSetMode(LED_RED, PI_OUTPUT);
    gpioSetMode(LED_GREEN, PI_OUTPUT);
    gpioSetMode(LED_BLUE, PI_OUTPUT);

    return main(argc, argv);
}
