#define I2C_BUS 1
#define I2C_ADDRESS 0x29
#define REG_POWER_ON 0x80
#define REG_RGBC_ENABLE 0x03
#define REG_INTEGRATION_TIME 0x81
#define REG_CLEAR_LOW 0x14
#define REG_CLEAR_HIGH 0x15
#define REG_RED_LOW 0x16
#define REG_RED_HIGH 0x17
#define REG_GREEN_LOW 0x18
#define REG_GREEN_HIGH 0x19
#define REG_BLUE_LOW 0x1A
#define REG_BLUE_HIGH 0x1B

#define CSV_FILE "color_data.csv"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    close_i2c(I2C_BUS);
    fclose(fp);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    fp = fopen(CSV_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open %s for writing: %s\n", CSV_FILE, strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    int i2c_fd = open_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (i2c_write_byte_data(i2c_fd, I2C_ADDRESS, REG_POWER_ON, 0x01) < 0) {
        fprintf(stderr, "Failed to power on TCS34725: %s\n", strerror(errno));
        close_i2c(I2C_BUS);
        return 1;
    }

    if (i2c_write_byte_data(i2c_fd, I2C_ADDRESS, REG_RGBC_ENABLE, REG_RGBC_ENABLE) < 0) {
        fprintf(stderr, "Failed to enable RGBC: %s\n", strerror(errno));
        close_i2c(I2C_BUS);
        return 1;
    }

    if (i2c_write_byte_data(i2c_fd, I2C_ADDRESS, REG_INTEGRATION_TIME, 0xD5) < 0) {
        fprintf(stderr, "Failed to set integration time: %s\n", strerror(errno));
        close_i2c(I2C_BUS);
        return 1;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    fprintf(fp, "timestamp,clear,red,green,blue\n");

    while (running) {
        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_CLEAR_LOW, &clear) < 0) {
            fprintf(stderr, "Failed to read clear low byte: %s\n", strerror(errno));
            clear = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_CLEAR_HIGH, &clear_high) < 0) {
            fprintf(stderr, "Failed to read clear high byte: %s\n", strerror(errno));
            clear_high = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_RED_LOW, &red) < 0) {
            fprintf(stderr, "Failed to read red low byte: %s\n", strerror(errno));
            red = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_RED_HIGH, &red_high) < 0) {
            fprintf(stderr, "Failed to read red high byte: %s\n", strerror(errno));
            red_high = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_GREEN_LOW, &green) < 0) {
            fprintf(stderr, "Failed to read green low byte: %s\n", strerror(errno));
            green = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_GREEN_HIGH, &green_high) < 0) {
            fprintf(stderr, "Failed to read green high byte: %s\n", strerror(errno));
            green_high = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_BLUE_LOW, &blue) < 0) {
            fprintf(stderr, "Failed to read blue low byte: %s\n", strerror(errno));
            blue = 0;
        }

        if (i2c_read_byte_data(i2c_fd, I2C_ADDRESS, REG_BLUE_HIGH, &blue_high) < 0) {
            fprintf(stderr, "Failed to read blue high byte: %s\n", strerror(errno));
            blue_high = 0;
        }

        clear = (clear << 8) | clear_high;
        red = (red << 8) | red_high;
        green = (green << 8) | green_high;
        blue = (blue << 8) | blue_high;

        fprintf(fp, "%lu,%d,%d,%d,%d\n", tv.tv_sec, clear, red, green, blue);

        gpioDelay(500000);

        gettimeofday(&tv, NULL);
    }

    fclose(fp);
    close_i2c(I2C_BUS);
    gpioTerminate();
    return 0;
}

