#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO pin numbers
#define SUNRISE_PIN 17
#define DAYTIME_PIN 27
#define SUNSET_PIN 22
#define NIGHT_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHT_DURATION 43200

// Define the total duration of the cycle in seconds
#define CYCLE_DURATION (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHT_DURATION)

// Define the signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    // Turn off all relays
    gpiod_line_set_value(gpiod_line_get(SUNRISE_PIN), 1);
    gpiod_line_set_value(gpiod_line_get(DAYTIME_PIN), 1);
    gpiod_line_set_value(gpiod_line_get(SUNSET_PIN), 1);
    gpiod_line_set_value(gpiod_line_get(NIGHT_PIN), 1);

    // Release GPIO resources
    gpiod_line_release(gpiod_line_get(SUNRISE_PIN));
    gpiod_line_release(gpiod_line_get(DAYTIME_PIN));
    gpiod_line_release(gpiod_line_get(SUNSET_PIN));
    gpiod_line_release(gpiod_line_get(NIGHT_PIN));

    // Close the GPIO chip
    gpiod_chip_close(gpiod_chip_get_by_name("gpiochip0"));

    // Exit the program
    exit(0);
}

int main() {
    // Open the GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get the GPIO lines
    struct gpiod_line *sunrise_line = gpiod_line_get(SUNRISE_PIN);
    struct gpiod_line *daytime_line = gpiod_line_get(DAYTIME_PIN);
    struct gpiod_line *sunset_line = gpiod_line_get(SUNSET_PIN);
    struct gpiod_line *night_line = gpiod_line_get(NIGHT_PIN);

    // Request the GPIO lines as output
    if (gpiod_line_request_output(sunrise_line, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", SUNRISE_PIN);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(daytime_line, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", DAYTIME_PIN);
        gpiod_line_release(sunrise_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(sunset_line, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", SUNSET_PIN);
        gpiod_line_release(sunrise_line);
        gpiod_line_release(daytime_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(night_line, 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", NIGHT_PIN);
        gpiod_line_release(sunrise_line);
        gpiod_line_release(daytime_line);
        gpiod_line_release(sunset_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        gpiod_line_release(sunrise_line);
        gpiod_line_release(daytime_line);
        gpiod_line_release(sunset_line);
        gpiod_line_release(night_line);
        gpiod_chip_close(chip);
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handling\n");
        gpiod_line_release(sunrise_line);
        gpiod_line_release(daytime_line);
        gpiod_line_release(sunset_line);
        gpiod_line_release(night_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int phase = 0;
    int duty_cycle = 0;
    while (1) {
        // Sunrise phase
        if (phase == 0) {
            if (duty_cycle < SUNRISE_DURATION) {
                gpiod_line_set_value(sunrise_line, 0);
                gpiod_line_set_value(daytime_line, 0);
                gpiod_line_set_value(sunset_line, 0);
                gpiod_line_set_value(night_line, 0);
                duty_cycle++;
                usleep(100000); // 100ms
            } else {
                phase = 1;
                duty_cycle = 0;
            }
        }

        // Daytime phase
        else if (phase == 1) {
            gpiod_line_set_value(sunrise_line, 1);
            gpiod_line_set_value(daytime_line, 1);
            gpiod_line_set_value(sunset_line, 1);
            gpiod_line_set_value(night_line, 1);
            usleep(DAYTIME_DURATION * 1000000); // 1s
            phase = 2;
            duty_cycle = 0;
        }

        // Sunset phase
        else if (phase == 2) {
            if (duty_cycle < SUNSET_DURATION) {
                gpiod_line_set_value(sunrise_line, 0);
                gpiod_line_set_value(daytime_line, 0);
                gpiod_line_set_value(sunset_line, 0);
