// Debouncing interval in milliseconds
#define DEBOUNCE_INTERVAL 200

// Flag to track if motion is detected
volatile int motion_detected = 0;

// Flag to track if the previous state was LOW
volatile int previous_state = 1;

// Timestamp of the last motion detection
volatile time_t last_motion_time = 0;

// File pointer to the log file
FILE *log_file = NULL;

void sigint_handler(int sig) {
    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

