        last_motion_time = time(NULL);

        // Set the motion detected flag
        motion_detected = 1;

        // Log the event
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", localtime(&last_motion_time));
