#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU_ADDRESS 0x68
#define REG_PWR_MGMT_1 0x6B
#define REG_SMPLRT_DIV 0x19
#define REG_CONFIG 0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_GYRO_X_H 0x43
#define REG_GYRO_X_L 0x44
#define REG_GYRO_Y_H 0x45
#define REG_GYRO_Y_L 0x46
#define REG_GYRO_Z_H 0x47
#define REG_GYRO_Z_L 0x48
#define SENSITIVITY 131.0

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void init_mpu6050(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, MPU_ADDRESS, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, MPU_ADDRESS, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        exit(1);
    }
    if (i2cWriteByteData(i2c_handle, MPU_ADDRESS, REG_GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to set gyroscope full-scale range\n");
        exit(1);
    }
}

int main() {
    int i2c_handle = i2cOpen(I2C_BUS, MPU_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(1);
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        i2cClose(i2c_handle);
        exit(1);
    }

    FILE *log_file = fopen("gyro_log.csv", "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(1);
    }

    int attempts = 0;
    while (running) {
        if (i2cWriteByteData(i2c_handle, MPU_ADDRESS, REG_PWR_MGMT_1, 0x00) < 0) {
            if (attempts < 3) {
                attempts++;
                init_mpu6050(i2c_handle);
                attempts = 0;
            } else {
                fprintf(stderr, "Failed to wake up MPU-6050 after 3 attempts\n");
                break;
            }
        }

        uint8_t data[6];
        if (i2cReadI2CBlockData(i2c_handle, MPU_ADDRESS, REG_GYRO_X_H, 6, data) < 0) {
            if (attempts < 3) {
                attempts++;
                init_mpu6050(i2c_handle);
                attempts = 0;
            } else {
                fprintf(stderr, "Failed to read gyroscope data after 3 attempts\n");
                break;
            }
        }

        int16_t x = (data[1] << 8) | data[0];
        int16_t y = (data[3] << 8) | data[2];
        int16_t z = (data[5] << 8) | data[4];

        x = (x * SENSITIVITY) / 32768;
        y = (y * SENSITIVITY) / 32768;
        z = (z * SENSITIVITY) / 32768;

        struct timeval tv;
        gettimeofday(&tv, NULL);
        fprintf(log_file, "%lu.%06d,%.2f,%.2f,%.2f\n", tv.tv_sec, tv.tv_usec / 1000, x, y, z);

        usleep(10000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

