#include <pigpio.h>

// GPIO pin numbers for the relays
#define RELAY_1 4
#define RELAY_2 17
#define RELAY_3 27
#define RELAY_4 22

// GPIO pin numbers for the simulated moisture sensor
#define SENSOR 23

// Log file path
#define LOG_FILE "irrigation_log.txt"

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Deactivate all relays
    gpioWrite(RELAY_1, 1);
    gpioWrite(RELAY_2, 1);
    gpioWrite(RELAY_3, 1);
    gpioWrite(RELAY_4, 1);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up the GPIO pins as outputs
    gpioSetMode(RELAY_1, PI_OUTPUT);
    gpioSetMode(RELAY_2, PI_OUTPUT);
    gpioSetMode(RELAY_3, PI_OUTPUT);
    gpioSetMode(RELAY_4, PI_OUTPUT);
    gpioSetMode(SENSOR, PI_INPUT);

    // Main loop
    while (1) {
        // Read the simulated moisture sensor
        int sensor_reading = rand() % 101;

        // Determine the relay states
        int relay_states[] = {0, 0, 0, 0};
        relay_states[0] = sensor_reading < 30;
        relay_states[1] = sensor_reading < 30;
        relay_states[2] = sensor_reading < 30;
        relay_states[3] = sensor_reading < 30;

        // Write the relay states
        gpioWrite(RELAY_1, relay_states[0] ? 0 : 1);
        gpioWrite(RELAY_2, relay_states[1] ? 0 : 1);
        gpioWrite(RELAY_3, relay_states[2] ? 0 : 1);
        gpioWrite(RELAY_4, relay_states[3] ? 0 : 1);

        // Log the sensor reading and relay states
        char timestamp[20];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "%s, Sensor: %d, Relay 1: %d, Relay 2: %d, Relay 3: %d, Relay 4: %d\n",
                timestamp, sensor_reading, relay_states[0], relay_states[1], relay_states[2], relay_states[3]);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

