#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>
#include <i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x53
#define GPIO_ALARM 27
#define FREEFALL_CONFIRMATION_DELAY 5000000
#define FREEFALL_CONFIRMATION_INTERVAL 5000000
#define FREEFALL_THRESHOLD 0.2
#define SCALE_FACTOR 256.0

// Function to convert raw 16-bit signed value to g-force
double convertToGForce(int16_t value) {
    return (double)value / SCALE_FACTOR;
}

// Function to read 6 bytes from the ADXL345
int readData(int fd) {
    uint8_t data[6];
    if (i2c_smbus_read_i2c_block_data(fd, 0x32, 6, data) < 0) {
        fprintf(stderr, "Error reading from ADXL345\n");
        return -1;
    }
    return data[0] << 8 | data[1];
}

// Function to check if all axes are below the threshold
bool isFreefall(int16_t x, int16_t y, int16_t z) {
    return (abs(x) < (FREEFALL_THRESHOLD * SCALE_FACTOR)) &&
           (abs(y) < (FREEFALL_THRESHOLD * SCALE_FACTOR)) &&
           (abs(z) < (FREEFALL_THRESHOLD * SCALE_FACTOR));
}

// Function to log freefall event to file
void logFreefall(const char *filename, int16_t x, int16_t y, int16_t z) {
    time_t now;
    struct tm *lt;
    char timestamp[20];

    time(&now);
    lt = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", lt);

    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing\n");
        return;
    }

    fprintf(file, "%s,%.3f,%.3f,%.3f\n", timestamp, convertToGForce(x), convertToGForce(y), convertToGForce(z));
    fclose(file);
}

// SIGINT handler
void sigintHandler(int sig) {
    int fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        exit(1);
    }

    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0);

    i2c_close(fd);
    pigpio_stop();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Set up SIGINT handler
    signal(SIGINT, sigintHandler);

    // Open I2C bus
    int fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    // Configure ADXL345
    if (i2c_smbus_write_byte_data(fd, 0x31, 0x0B) < 0) {
        fprintf(stderr, "Error configuring ADXL345\n");
        i2c_close(fd);
        return 1;
    }
    if (i2c_smbus_write_byte_data(fd, 0x2D, 0x08) < 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        i2c_close(fd);
        return 1;
    }

    // Initialize GPIO
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0);

    // Main loop
    struct timeval lastFreefall;
    gettimeofday(&lastFreefall, NULL);
    while (1) {
        // Read data from ADXL345
        int16_t x = readData(fd);
        if (x < 0) {
            continue;
        }

        // Read Y and Z axes
        int16_t y = readData(fd);
        int16_t z = readData(fd);
        if (y < 0 || z < 0) {
            continue;
        }

        // Check for freefall
        if (isFreefall(x, y, z)) {
            gettimeofday(&lastFreefall, NULL);
            continue;
        }

        // Check for confirmed freefall
        struct timeval now;
        gettimeofday(&now, NULL);
        if ((now.tv_sec - lastFreefall.tv_sec) >= 0.5) {
            gettimeofday(&lastFreefall, NULL);
            continue;
        }

        // Log freefall event
        logFreefall("freefall.log", x, y, z);

        // Drive alarm
        gpioWrite(GPIO_ALARM, 1);
        usleep(5000000);
        gpioWrite(GPIO_ALARM, 0);
    }

    // Clean up
    i2c_close(fd);
    pigpio_stop();
    return 0;
}

