#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <pigpio.h>
#include <pthread.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000 // 4 meters in cm
#define MAX_TIMEOUT 10000000 // 100 ms in ns
#define MEASUREMENT_INTERVAL 200000000 // 200 ms in ns
#define TICKS_PER_SECOND 1000000000 // 1 second in ns

// Mutex for shared pulse-timing variables
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared pulse-timing variables
volatile uint32_t trigger_sent = 0;
volatile uint32_t echo_start = 0;
volatile uint32_t echo_end = 0;

// File descriptor for logging
int log_fd = -1;

// Callback for rising-edge interrupt on ECHO pin
void rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    echo_start = tick;
    pthread_mutex_unlock(&pulse_mutex);
}

// Callback for falling-edge interrupt on ECHO pin
void falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    echo_end = tick;
    pthread_mutex_unlock(&pulse_mutex);
}

// SIGINT handler
void sigint_handler(int sig) {
    // Cancel callbacks
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioSetAlertFunc(TRIG_PIN, NULL);

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Exit
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin mode\n");
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO pin mode\n");
        return 1;
    }
    if (gpioSetAlertFunc(ECHO_PIN, rising_edge_callback) < 0) {
        fprintf(stderr, "Failed to set rising-edge callback for ECHO pin\n");
        return 1;
    }
    if (gpioSetAlertFunc(TRIG_PIN, NULL) < 0) {
        fprintf(stderr, "Failed to clear TRIG pin callback\n");
        return 1;
    }

    // Open log file
    log_fd = open("distance_log.txt", O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (log_fd < 0) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Set up measurement loop
    while (1) {
        // Send trigger pulse
        pthread_mutex_lock(&pulse_mutex);
        if (trigger_sent == 0) {
            trigger_sent = gpioMicrosleep(TRIG_PIN, 10);
            if (trigger_sent == 0) {
                fprintf(stderr, "Failed to send trigger pulse\n");
                break;
            }
        }
        pthread_mutex_unlock(&pulse_mutex);

        // Wait for echo pulse
        uint32_t start = 0;
        uint32_t end = 0;
        uint32_t timeout = 0;
        while (1) {
            pthread_mutex_lock(&pulse_mutex);
            if (echo_start != 0) {
                start = echo_start;
                echo_start = 0;
            }
            pthread_mutex_unlock(&pulse_mutex);
            if (start != 0) {
                break;
            }
            if (timeout++ > MAX_TIMEOUT) {
                break;
            }
            usleep(1000);
        }
        if (start == 0) {
            fprintf(stderr, "No echo pulse received\n");
            continue;
        }

        // Wait for echo pulse end
        timeout = 0;
        while (1) {
            pthread_mutex_lock(&pulse_mutex);
            if (echo_end != 0) {
                end = echo_end;
                echo_end = 0;
            }
            pthread_mutex_unlock(&pulse_mutex);
            if (end != 0) {
                break;
            }
            if (timeout++ > MAX_TIMEOUT) {
                break;
            }
            usleep(1000);
        }
        if (end == 0) {
            fprintf(stderr, "No echo pulse end received\n");
            continue;
        }

        // Check for wrap-around
        if (end < start) {
            end += TICKS_PER_SECOND;
        }

        // Calculate distance
        uint32_t pulse_width = end - start;
        if (pulse_width > MAX_DISTANCE * 2) {
            fprintf(stderr, "Invalid pulse width\n");
            continue;
        }

        // Log measurement
        struct timeval tv;
        gettimeofday(&tv, NULL);
        uint64_t timestamp_ns = tv.tv_sec * 1000000000 + tv.tv_usec * 1000;
        fprintf(log_fd, "%llu,%u\n", timestamp_ns, pulse_width / 2);

        // Reset trigger timing
        pthread_mutex_lock(&pulse_mutex);
        trigger_sent = 0;
        pthread_mutex_unlock(&pulse_mutex);

        // Wait for next measurement
        usleep(MEASUREMENT_INTERVAL);
    }

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
        log_fd = -1;
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    return 0;
}

