    moveMotor(X_AXIS_MOTOR_IN1, X_AXIS_MOTOR_IN2, X_AXIS_MOTOR_IN3, X_AXIS_MOTOR_IN4, -SQUARE_SIDE_LENGTH * STEPS_PER_MM);

