#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <getopt.h>

#define DEFAULT_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0
#define DEFAULT_RATE 10
#define DEFAULT_INTERVAL 100000 // 100 ms

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    i2cClose(I2C1);
    pigpio_stop();
    exit(0);
}

// Function to read acceleration data from the LIS3DH sensor
void read_acceleration(int fd, int address, float threshold, int rate, int interval) {
    int16_t x, y, z;
    uint8_t reg1 = 0x57; // CTRL_REG1: ±2g, high-resolution mode, 100 Hz
    uint8_t reg4 = 0x88; // CTRL_REG4: 100 Hz
    uint8_t data[6];

    // Write CTRL_REG1 and CTRL_REG4
    i2cWriteByteData(fd, address, 0x20, reg1);
    i2cWriteByteData(fd, address, 0x23, reg4);

    while (1) {
        // Read acceleration data
        i2cReadI2CBlockData(fd, address, 0x2D, 6, data);

        // Extract x, y, and z acceleration values
        x = (data[1] << 8) | data[0];
        y = (data[3] << 8) | data[2];
        z = (data[5] << 8) | data[4];

        // Compute g values
        float gx = (float)x >> 4;
        float gy = (float)y >> 4;
        float gz = (float)z >> 4;

        // Scale g values
        gx *= 0.0009765625;
        gy *= 0.0009765625;
        gz *= 0.0009765625;

        // Check if acceleration exceeds threshold
        if (fabs(gx) > threshold || fabs(gy) > threshold || fabs(gz) > threshold) {
            // Log event
            syslog(LOG_INFO, "High acceleration detected at %f s: x=%f g, y=%f g, z=%f g\n", (float)time(NULL), gx, gy, gz);
            // Trigger shutdown
            system("sudo shutdown -h now");
        }

        // Sleep for the next interval
        usleep(interval);
    }
}

int main(int argc, char **argv) {
    int address = DEFAULT_ADDRESS;
    float threshold = DEFAULT_THRESHOLD;
    int rate = DEFAULT_RATE;
    int interval = DEFAULT_INTERVAL;

    // Parse command line arguments
    int opt;
    while ((opt = getopt(argc, argv, "a:t:r:i:")) != -1) {
        switch (opt) {
            case 'a':
                address = strtoul(optarg, NULL, 16);
                if (address < 0x08 || address > 0x77) {
                    fprintf(stderr, "Invalid I2C address: %x\n", address);
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold: %f\n", threshold);
                    return 1;
                }
                break;
            case 'r':
                rate = atoi(optarg);
                if (rate <= 0) {
                    fprintf(stderr, "Invalid rate: %d\n", rate);
                    return 1;
                }
                interval = 1000000 / rate;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a address] [-t threshold] [-r rate]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (pigpio_initialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    int fd = i2cOpen(1, address);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        pigpio_stop();
        return 1;
    }

    // Register SIGINT handler
    signal(SIGINT, sigint_handler);

    // Start reading acceleration data
    read_acceleration(fd, address, threshold, rate, interval);

    // Cleanup on exit
    atexit(pigpio_stop);
    atexit(i2cClose);
    return 0;
}

