#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <libgpiod.h>

// Define motor control functions
void move_forward() {
    printf("Move forward\n");
}

void turn_left() {
    printf("Turn left\n");
}

void turn_right() {
    printf("Turn right\n");
}

void stop() {
    printf("Stop\n");
}

// Define signal handlers
void sigint_handler(int sig) {
    gpiod_close(gpio_fd);
    exit(0);
}

void sigterm_handler(int sig) {
    gpiod_close(gpio_fd);
    exit(0);
}

// Define the circular buffer structure
typedef struct {
    int left[5];
    int center[5];
    int right[5];
    int head;
    int tail;
} buffer_t;

// Function to initialize the circular buffer
void buffer_init(buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
}

// Function to add an element to the circular buffer
void buffer_add(buffer_t *buf, int value, int sensor) {
    if (sensor == 0) {
        buf->left[buf->head] = value;
    } else if (sensor == 1) {
        buf->center[buf->head] = value;
    } else if (sensor == 2) {
        buf->right[buf->head] = value;
    }
    buf->head = (buf->head + 1) % 5;
}

// Function to get the average value from the circular buffer
int buffer_avg(buffer_t *buf, int sensor) {
    int sum = 0;
    for (int i = 0; i < 5; i++) {
        if (sensor == 0) {
            sum += buf->left[i];
        } else if (sensor == 1) {
            sum += buf->center[i];
        } else if (sensor == 2) {
            sum += buf->right[i];
        }
    }
    return sum / 5;
}

int main() {
    // Initialize GPIO
    gpio_fd = gpiod_open("/dev/gpiochip0", GPIOD_LINEHANDLE_OPEN);
    if (gpio_fd < 0) {
        perror("gpiod_open");
        exit(1);
    }

    // Initialize GPIO lines
    gpio_line = gpiod_line_request(gpio_fd, "gpio4", GPIOD_LINE_REQUEST_OUTPUT);
    if (gpio_line < 0) {
        perror("gpiod_line_request");
        gpiod_close(gpio_fd);
        exit(1);
    }

    gpio_line = gpiod_line_request(gpio_fd, "gpio17", GPIOD_LINE_REQUEST_INPUT);
    if (gpio_line < 0) {
        perror("gpiod_line_request");
        gpiod_close(gpio_fd);
        exit(1);
    }

    gpio_line = gpiod_line_request(gpio_fd, "gpio27", GPIOD_LINE_REQUEST_INPUT);
    if (gpio_line < 0) {
        perror("gpiod_line_request");
        gpiod_close(gpio_fd);
        exit(1);
    }

    gpio_line = gpiod_line_request(gpio_fd, "gpio22", GPIOD_LINE_REQUEST_OUTPUT);
    if (gpio_line < 0) {
        perror("gpiod_line_request");
        gpiod_close(gpio_fd);
        exit(1);
    }

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    // Initialize circular buffer
    buffer_t buf;
    buffer_init(&buf);

    // Main loop
    while (1) {
        // Read sensor values
        int left = gpiod_line_get_value(gpio_fd, gpio_line[0]);
        int center = gpiod_line_get_value(gpio_fd, gpio_line[1]);
        int right = gpiod_line_get_value(gpio_fd, gpio_line[2]);

        // Add sensor values to circular buffer
        buffer_add(&buf, left, 0);
        buffer_add(&buf, center, 1);
        buffer_add(&buf, right, 2);

        // Check for alert condition
        if (buffer_avg(&buf, 1) == 1 && buf.center[buf.tail] == 1) {
            // Drive alert pin high for 2 seconds
            gpiod_line_set_value(gpio_fd, gpio_line[3], 1);
            sleep(2);
            gpiod_line_set_value(gpio_fd, gpio_line[3], 0);
        }

        // Implement line-following logic
        if (center == 0) {
            move_forward();
        } else if (left == 0) {
            turn_left();
        } else if (right == 0) {
            turn_right();
        } else {
            stop();
        }

        // Log sensor values
        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    gpiod_close(gpio_fd);
    return 0;
}

