#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x30
#define REG_CONVERSION_START 0xC1
#define REG_CONVERSION_DATA 0xC0
#define REG_CONVERSION_DATA_LSB 0xC0
#define REG_CONVERSION_DATA_MSB 0xC1
#define THRESHOLD 5.0
#define SAMPLING_INTERVAL 100000 // 100 ms

// Function to handle SIGINT signal
void sigint_handler(int sig) {
    // Close I2C handle
    if (i2cClose(i2cOpen(I2C_BUS, I2C_ADDRESS)) < 0) {
        fprintf(stderr, "Error closing I2C handle: %s\n", strerror(errno));
    }

    // Deactivate relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    // Log shutdown
    fprintf(stderr, "Shutdown\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Install SIGINT handler
    signal(SIGINT, sigint_handler);

    // Open I2C bus
    int i2c = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize relay
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    // Open log file
    FILE *log_file = fopen("magnetic_events.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Start conversion
        if (i2cWriteByteData(i2c, REG_CONVERSION_START, 0x01) < 0) {
            fprintf(stderr, "Error starting conversion: %s\n", strerror(errno));
            gpioWrite(RELAY_PIN, 0);
            continue;
        }

        // Poll for conversion completion
        int poll_attempts = 0;
        while (i2cReadByte(i2c, REG_CONVERSION_START) != 0x00 && poll_attempts < 50) {
            poll_attempts++;
            usleep(SAMPLING_INTERVAL);
        }

        if (poll_attempts >= 50) {
            fprintf(stderr, "Timeout error: conversion did not complete\n");
            continue;
        }

        // Read conversion data
        uint8_t lsb, msb;
        if (i2cReadByteData(i2c, REG_CONVERSION_DATA_LSB, &lsb) < 0 || i2cReadByteData(i2c, REG_CONVERSION_DATA_MSB, &msb) < 0) {
            fprintf(stderr, "Error reading conversion data: %s\n", strerror(errno));
            gpioWrite(RELAY_PIN, 0);
            continue;
        }

        // Calculate field strength
        int16_t field_raw = (msb << 8) | lsb;
        float field_mT_x100 = (float)field_raw * 25 / 1000;

        // Check if field strength exceeds threshold
        if (field_mT_x100 > THRESHOLD * 100) {
            // Activate relay
            gpioWrite(RELAY_PIN, 1);
        } else {
            // Deactivate relay
            gpioWrite(RELAY_PIN, 0);
        }

        // Log field reading
        char timestamp[32];
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
        fprintf(log_file, "%s,field=%f,relay=%d\n", timestamp, field_mT_x100, gpioRead(RELAY_PIN));
        fflush(log_file);

        // Sleep for sampling interval
        usleep(SAMPLING_INTERVAL);
    }

    // Close log file
    fclose(log_file);

    // Close I2C handle
    if (i2cClose(i2c) < 0) {
        fprintf(stderr, "Error closing I2C handle: %s\n", strerror(errno));
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

