#include <unistd.h>
#include <time.h>

#define PORT 5000
#define RELAY_PIN 18
#define LOG_FILE "relay_log.txt"

void handle_sigint(int sig) {
    // Handle SIGINT and SIGTERM
    printf("Caught signal %d, shutting down...\n", sig);
    close_socket();
    close_log_file();
    gpioTerminate();
    exit(0);
}

void close_socket() {
    // Close all sockets
    close(sockfd);
}

void close_log_file() {
    // Close the log file
    fclose(log_file);
}

void init_gpio() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(1);
    }
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
}

void init_socket() {
    // Initialize socket
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        exit(1);
    }
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);
    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind failed");
        exit(1);
    }
    if (listen(sockfd, 3) < 0) {
        perror("listen failed");
        exit(1);
    }
}

void handle_client(int client_fd) {
    char buffer[256];
    int bytes_received;
    while ((bytes_received = recv(client_fd, buffer, 256, 0)) > 0) {
        buffer[bytes_received] = '\0';
        char *cmd = strtok(buffer, " \t\r\n");
        if (strcasecmp(cmd, "ON") == 0) {
            gpioWrite(RELAY_PIN, 1);
            fprintf(log_file, "%s: Relay turned ON\n", ctime(&now));
        } else if (strcasecmp(cmd, "OFF") == 0) {
            gpioWrite(RELAY_PIN, 0);
            fprintf(log_file, "%s: Relay turned OFF\n", ctime(&now));
        } else {
            fprintf(log_file, "%s: Invalid command '%s'\n", ctime(&now), buffer);
        }
    }
    close(client_fd);
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    // Initialize GPIO
    init_gpio();

    // Initialize socket
    init_socket();

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    // Accept incoming connections
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_fd = accept(sockfd, (struct sockaddr *)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("accept failed");
        exit(1);
    }

    // Handle client
    handle_client(client_fd);

    // Close socket and log file
    close_socket();
    close_log_file();

    return 0;
}

