#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>

#define FLOW_LOG_FILE "flow_log.txt"
#define FLOW_THRESHOLD 5.0
#define FLOW_SCALE 1.0 / 1500.0
#define FLOW_POLLING_INTERVAL 100

volatile bool exit_requested = false;

void sigint_handler(int sig) {
    exit_requested = true;
}

int main() {
    int gpio = gpioInitialise();
    if (gpio < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %d", gpio);
        exit(1);
    }

    int i2c1 = gpioI2COpen(1, 0x08, 0);
    if (i2c1 < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1: %d", i2c1);
        gpioTerminate();
        exit(1);
    }

    int i2c2 = gpioI2COpen(1, 0x09, 0);
    if (i2c2 < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus 1: %d", i2c2);
        gpioI2CClose(i2c1);
        gpioTerminate();
        exit(1);
    }

    if (gpioSetMode(gpio, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO 18 as output");
        gpioI2CClose(i2c1);
        gpioI2CClose(i2c2);
        gpioTerminate();
        exit(1);
    }

    if (gpioWrite(gpio, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO 18 low");
        gpioI2CClose(i2c1);
        gpioI2CClose(i2c2);
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    FILE *flow_log = fopen(FLOW_LOG_FILE, "a");
    if (flow_log == NULL) {
        syslog(LOG_ERR, "Failed to open %s for writing", FLOW_LOG_FILE);
        gpioI2CClose(i2c1);
        gpioI2CClose(i2c2);
        gpioTerminate();
        exit(1);
    }

    while (!exit_requested) {
        if (gpioI2CWriteByte(i2c1, 0x36, 0x08) != 0) {
            syslog(LOG_WARNING, "Failed to write to sensor 1");
            continue;
        }

        if (gpioI2CWriteByte(i2c2, 0x36, 0x08) != 0) {
            syslog(LOG_WARNING, "Failed to write to sensor 2");
            continue;
        }

        uint8_t data1[3];
        if (gpioI2CReadReg8(i2c1, 0x00, data1, 3) != 3) {
            syslog(LOG_WARNING, "Failed to read from sensor 1");
            continue;
        }

        uint8_t data2[3];
        if (gpioI2CReadReg8(i2c2, 0x00, data2, 3) != 3) {
            syslog(LOG_WARNING, "Failed to read from sensor 2");
            continue;
        }

        uint16_t crc1 = crc8(data1, 2, 0xFF, 0x31);
        if (crc1 != data1[2]) {
            syslog(LOG_WARNING, "CRC mismatch for sensor 1");
            continue;
        }

        uint16_t crc2 = crc8(data2, 2, 0xFF, 0x31);
        if (crc2 != data2[2]) {
            syslog(LOG_WARNING, "CRC mismatch for sensor 2");
            continue;
        }

        float flow1 = (data1[0] << 8 | data1[1]) * FLOW_SCALE;
        float flow2 = (data2[0] << 8 | data2[1]) * FLOW_SCALE;

        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            if (gpioWrite(gpio, 1) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO 18 high");
                continue;
            }
        } else {
            if (gpioWrite(gpio, 0) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO 18 low");
                continue;
            }
        }

        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", localtime(&time(NULL)));
        fprintf(flow_log, "%s sensor1=%f sensor2=%f\n", timestamp, flow1, flow2);
        fflush(flow_log);
    }

    if (gpioWrite(gpio, 0) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO 18 low on exit");
    }

    gpioI2CClose(i2c1);
    gpioI2CClose(i2c2);
    gpioTerminate();

    fclose(flow_log);
    syslog(LOG_INFO, "Shutting down");

    return 0;
}

uint8_t crc8(uint8_t *data, size_t len, uint8_t init, uint8_t poly) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

