#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RAIN_SENSOR_GPIO 17
#define MOTOR_ENA_GPIO 22
#define MOTOR_IN1_GPIO 23
#define MOTOR_IN2_GPIO 24
#define POLL_INTERVAL_MS 200
#define MOTOR_RUN_TIME_S 5

static int rain_detected = 0;
static int motor_running = 0;
static int dry_count = 0;

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down", sig);
    gpioWrite(MOTOR_ENA_GPIO, 0);
    gpioWrite(MOTOR_IN1_GPIO, 0);
    gpioWrite(MOTOR_IN2_GPIO, 0);
    gpioTerminate();
    closelog();
    exit(0);
}

int main() {
    int gpio_fd;
    int rain_sensor_value;
    int motor_ena_value;
    int motor_in1_value;
    int motor_in2_value;

    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if ((gpio_fd = gpioInitialise()) < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %d", gpio_fd);
        closelog();
        exit(1);
    }

    // Set up rain sensor pin as input with pull-up
    if (gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up rain sensor pin: %d", gpioSetMode(RAIN_SENSOR_GPIO, PI_INPUT));
        gpioTerminate();
        closelog();
        exit(1);
    }
    if (gpioSetPullUpDnControl(RAIN_SENSOR_GPIO, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "Failed to set up pull-up on rain sensor pin: %d", gpioSetPullUpDnControl(RAIN_SENSOR_GPIO, PI_PUD_UP));
        gpioTerminate();
        closelog();
        exit(1);
    }

    // Set up motor pins as output
    if (gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up motor ENA pin: %d", gpioSetMode(MOTOR_ENA_GPIO, PI_OUTPUT));
        gpioTerminate();
        closelog();
        exit(1);
    }
    if (gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up motor IN1 pin: %d", gpioSetMode(MOTOR_IN1_GPIO, PI_OUTPUT));
        gpioTerminate();
        closelog();
        exit(1);
    }
    if (gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up motor IN2 pin: %d", gpioSetMode(MOTOR_IN2_GPIO, PI_OUTPUT));
        gpioTerminate();
        closelog();
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Main loop
    while (1) {
        // Poll rain sensor
        rain_sensor_value = gpioRead(RAIN_SENSOR_GPIO);
        if (rain_sensor_value == 0) {
            // Rain detected
            if (rain_detected == 0) {
                // Trigger close-window sequence
                motor_ena_value = 1;
                motor_in1_value = 1;
                motor_in2_value = 0;
                if (gpioWrite(MOTOR_ENA_GPIO, motor_ena_value) < 0) {
                    syslog(LOG_WARNING, "Failed to set motor ENA: %d", gpioWrite(MOTOR_ENA_GPIO, motor_ena_value));
                }
                if (gpioWrite(MOTOR_IN1_GPIO, motor_in1_value) < 0) {
                    syslog(LOG_WARNING, "Failed to set motor IN1: %d", gpioWrite(MOTOR_IN1_GPIO, motor_in1_value));
