// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// GPIO pin numbers
#define SERVO_PIN 18
#define BUTTON_PIN1 21
#define BUTTON_PIN2 22

// Pulse widths in microseconds
#define LOCKED_PULSE_WIDTH 2000
#define UNLOCKED_PULSE_WIDTH 1000

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO: %s\n", gpioErrorStr(gpioInitialise()));
        return 1;
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up servo pin as output
    if (gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Failed to set servo pulse width: %s\n", gpioErrorStr(gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH)));
        gpioTerminate();
        return 1;
    }

    // Enable internal pull-ups on button pins
    gpioSetMode(BUTTON_PIN1, PI_INPUT);
    gpioSetMode(BUTTON_PIN2, PI_INPUT);
    gpioSetPullUpDnControl(BUTTON_PIN1, PI_PUD_UP);
    gpioSetPullUpDnControl(BUTTON_PIN2, PI_PUD_UP);

    // Main loop
    while (1) {
        // Check button 1
        int button1_state = gpioRead(BUTTON_PIN1);
        if (button1_state == 0 && gpioRead(BUTTON_PIN1) == 0) { // Debounce check
            gpioServo(SERVO_PIN, LOCKED_PULSE_WIDTH);
            printf("Locked\n");
        }

        // Check button 2
        int button2_state = gpioRead(BUTTON_PIN2);
        if (button2_state == 0 && gpioRead(BUTTON_PIN2) == 0) { // Debounce check
            gpioServo(SERVO_PIN, UNLOCKED_PULSE_WIDTH);
            printf("Unlocked\n");
        }

        // Sleep to avoid high CPU usage
        usleep(100000);
    }

    return 0;
}

