// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    gpioWrite(17, 0); // Turn off the floodlight
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO modes
    if (gpioSetMode(4, PI_INPUT) < 0 || gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file = fopen("security_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioWrite(17, 0); // Turn off the floodlight
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read PIR sensor state
        int pir_state = gpioRead(4);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR sensor\n");
            break;
        }

        // Check for motion
        if (pir_state) {
            // Log motion detection
            time_t now = time(NULL);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_file, "%s: Motion detected\n", timestamp);

            // Turn on the floodlight
            gpioWrite(17, 1);

            // Wait for 60 seconds
            sleep(60);

            // Log floodlight deactivation
            now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_file, "%s: Floodlight deactivated after %d seconds\n", timestamp, 60);

            // Turn off the floodlight
            gpioWrite(17, 0);
        }

        // Sleep for 100 ms
        usleep(100000);
    }

    // Close log file
    if (fclose(log_file) < 0) {
        fprintf(stderr, "Failed to close log file\n");
    }

    // Release pigpio resources
    gpioTerminate();

    return 0;
}

