#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <i2c-dev.h>

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Release GPIO resources
    gpioSetMode(GPIO_17, PI_OUTPUT);
    gpioWrite(GPIO_17, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Set GPIO 17 as output
    if (gpioSetMode(GPIO_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 to OFF state
    gpioWrite(GPIO_17, 0);

    // Open I2C bus 1
    int bus = open("/dev/i2c-1", O_RDWR);
    if (bus < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Set I2C address to 0x5A
    if (ioctl(bus, I2C_SLAVE, 0x5A) < 0) {
        fprintf(stderr, "Failed to set I2C address to 0x5A\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Perform MPR121 initialization
    // Soft reset
    if (i2c_write(bus, 0x5A, 0x06, 0x00) < 0) {
        fprintf(stderr, "Failed to perform soft reset\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Configure baseline filtering
    if (i2c_write(bus, 0x5A, 0x07, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x08, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x09, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x0A, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set debounce
    if (i2c_write(bus, 0x5A, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Failed to set debounce\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set FFI/SFI/CDT
    if (i2c_write(bus, 0x5A, 0x2C, 0x00) < 0) {
        fprintf(stderr, "Failed to set FFI/SFI/CDT\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set auto-config
    if (i2c_write(bus, 0x5A, 0x7B, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x7C, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x7D, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Enable 12 electrodes
    if (i2c_write(bus, 0x5A, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Failed to enable 12 electrodes\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch status
        unsigned char data[2];
        if (i2c_read(bus, 0x5A, 0x00, data, 2) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            close(bus);
            gpioTerminate();
            return 1;
        }

        // Check for fresh touch on electrode 0
        if ((data[0] & (1 << 0)) && (data[1] & (1 << 0))) {
            // Toggle relay
            gpioWrite(GPIO_17, 1);
            // Debounce
            sleep(0.2);
            gpioWrite(GPIO_17, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Release resources
    close(bus);
    gpioTerminate();
    return 0;
}

