        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x09, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x0A, 0x00) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set debounce
    if (i2c_write(bus, 0x5A, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Failed to set debounce\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set FFI/SFI/CDT
    if (i2c_write(bus, 0x5A, 0x2C, 0x00) < 0) {
        fprintf(stderr, "Failed to set FFI/SFI/CDT\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Set auto-config
    if (i2c_write(bus, 0x5A, 0x7B, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x7C, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }
    if (i2c_write(bus, 0x5A, 0x7D, 0x00) < 0) {
        fprintf(stderr, "Failed to set auto-config\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Enable 12 electrodes
    if (i2c_write(bus, 0x5A, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Failed to enable 12 electrodes\n");
        close(bus);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch status
        unsigned char data[2];
        if (i2c_read(bus, 0x5A, 0x00, data, 2) < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            close(bus);
            gpioTerminate();
            return 1;
        }

        // Check for fresh touch on electrode 0
        if ((data[0] & (1 << 0)) && (data[1] & (1 << 0))) {
            // Toggle relay
            gpioWrite(GPIO_17, 1);
            // Debounce
            sleep(0.2);
            gpioWrite(GPIO_17, 0);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    // Release resources
    close(bus);
    gpioTerminate();
    return 0;
}
```

This code initializes the GPIO and I2C bus, performs the MPR121 initialization, and enters a main loop where it reads the touch status and toggles the relay on a fresh touch of electrode 0. The relay is set to a known OFF state on both startup and shutdown. The code includes robust error handling for every pigpio/I2C call and releases resources on every exit path via SIGINT/SIGTERM handling.

