        gpiod_line_set_value(gpiod_fd, SERVO_GPIO, 0);
        usleep((SERVO_MAX_PULSE_WIDTH - (servo_angle * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / SERVO_MAX_ANGLE + SERVO_MIN_PULSE_WIDTH)) * 1000 / 2);
        servo_angle = (servo_angle + 1) % (SERVO_MAX_ANGLE + 1);
    }
}

void handle_client(int client_fd) {
    char buffer[1024];
    int bytes_received;
    while (1) {
        bytes_received = recv(client_fd, buffer, sizeof(buffer), 0);
        if (bytes_received == -1) {
            log_message(LOG_ERR, "Error receiving data from client: %s", strerror(errno));
            break;
        }
        buffer[bytes_received] = '\0';
        if (strncmp(buffer, "SERVO ", 6) == 0) {
            int angle;
            if (sscanf(buffer + 6, "%d", &angle) != 1 || angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
                log_message(LOG_ERR, "Invalid servo angle: %s", buffer);
                send(client_fd, "Invalid angle", strlen("Invalid angle"), 0);
            } else {
                servo_angle = angle;
                log_message(LOG_INFO, "Servo angle set to %d", angle);
                send(client_fd, "Servo angle set to %d", angle);
            }
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value;
            if (gpiod_line_get_value(gpiod_fd, PIR_GPIO, &pir_value) == 0) {
                log_message(LOG_INFO, "PIR sensor value: %d", pir_value);
                send(client_fd, "PIR:%d", pir_value);
            } else {
                log_message(LOG_ERR, "Error reading PIR sensor: %s", gpiod_get_error());
                send(client_fd, "Error reading PIR sensor");
            }
        } else {
            log_message(LOG_ERR, "Unknown command: %s", buffer);
            send(client_fd, "Unknown command");
        }
    }
    close(client_fd);
}

