    gpiod_line_release(gpiod_fd, SERVO_GPIO);
    gpiod_line_release(gpiod_fd, PIR_GPIO);
    gpiod_close(gpiod_fd);
    close(sock);
    fclose(stderr);
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sa.sa_handler = sigterm_handler;
    sigaction(SIGTERM, &sa, NULL);

    gpiod_fd = gpiod_chip_open("/dev/gpiochip0");
    if (gpiod_fd == -1) {
        log_message(LOG_ERR, "Error opening GPIO chip: %s", gpiod_get_error());
        exit(1);
    }

    if (gpiod_line_request_output(gpiod_fd, SERVO_GPIO, 0) == -1) {
        log_message(LOG_ERR, "Error requesting servo GPIO as output: %s", gpiod_get_error());
        gpiod_close(gpiod_fd);
        exit(1);
    }

    if (gpiod_line_request_input(gpiod_fd, PIR_GPIO, 0) == -1) {
        log_message(LOG_ERR, "Error requesting PIR GPIO as input: %s", gpiod_get_error());
        gpiod_line_release(gpiod_fd, SERVO_GPIO);
        gpiod_close(gpiod_fd);
        exit(1);
    }

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        log_message(LOG_ERR, "Error creating socket: %s", strerror(errno));
        gpiod_line_release(gpiod_fd, SERVO_GPIO);
        gpiod_line_release(gpiod_fd, PIR_GPIO);
        gpiod_close(gpiod_fd);
        exit(1);
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    inet_pton(AF_INET, "0.0.0.0", &server_addr.sin_addr);
    if (bind(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        log_message(LOG_ERR, "Error binding socket: %s", strerror(errno));
        close(sock);
        gpiod_line_release(gpiod_fd, SERVO_GPIO);
        gpiod_line_release(gpiod_fd, PIR_GPIO);
        gpiod_close(gpiod_fd);
        exit(1);
    }

    if (listen(sock, 1) == -1) {
        log_message(LOG_ERR, "Error listening on socket: %s", strerror(errno));
        close(sock);
        gpiod_line_release(gpiod_fd, SERVO_GPIO);
        gpiod_line_release(gpiod_fd, PIR_GPIO);
        gpiod_close(gpiod_fd);
        exit(1);
    }

    log_message(LOG_INFO, "Server listening on port 5000");

    pthread_create(&servo_thread, NULL, servo_thread_func, NULL);

    while (1) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(sock, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd == -1) {
            log_message(LOG_ERR, "Error accepting client: %s", strerror(errno));
            continue;
        }
        log_message(LOG_INFO, "Client connected");
        handle_client(client_fd);
    }

    return 0;
