#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define RELAY_PIN 23
#define SENSORSAMPLE_INTERVAL 2000000 // 2 seconds
#define LUX_THRESHOLD 150
#define LUX_CONVERSION 1.2

// Function to handle SIGINT and SIGTERM signals
void signal_handler(int sig) {
    // Deactivate the relay
    gpioWrite(RELAY_PIN, 0);
    // Close the I2C handle
    i2cClose(I2C_BUS);
    // Close the log file
    fclose(log_file);
    // Terminate the GPIO library
    gpioTerminate();
    // Exit the program
    exit(0);
}

// Function to read the BH1750 sensor
int read_bh1750(int i2c_bus, int i2c_address) {
    // Open the I2C bus
    int i2c_handle = i2cOpen(i2c_bus, i2c_address);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        return -1;
    }

    // Set the BH1750 to One-Time High-Resolution mode
    if (i2cWriteByte(i2c_handle, 0x20) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Wait for the conversion to complete
    usleep(120000);

    // Read the 2-byte result
    uint16_t raw;
    if (i2cReadDevice(i2c_handle, &raw, 2) < 0) {
        fprintf(stderr, "Failed to read BH1750 data\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Close the I2C handle
    i2cClose(i2c_handle);

    // Convert the raw value to lux
    uint16_t lux = raw / LUX_CONVERSION;

    return lux;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Open the log file
    FILE *log_file = fopen("grow_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize the relay
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    // Main loop
    while (1) {
        // Read the BH1750 sensor
        int lux = read_bh1750(I2C_BUS, I2C_ADDRESS);
        if (lux < 0) {
            // If the sensor is absent or the bus is in error, log an error and retry
            fprintf(stderr, "Error reading BH1750 sensor\n");
            continue;
        }

        // Log the timestamp and lux value
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s lux: %d\n", timestamp, lux);

        // Trigger the relay based on the lux value
        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        // Sleep for the sampling interval
        usleep(SENSORSAMPLE_INTERVAL);
    }

    // Close the I2C handle
    i2cClose(I2C_BUS);

    // Close the log file
    fclose(log_file);

    // Deactivate the relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}

