    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize the relay
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    // Main loop
    while (1) {
        // Read the BH1750 sensor
        int lux = read_bh1750(I2C_BUS, I2C_ADDRESS);
        if (lux < 0) {
            // If the sensor is absent or the bus is in error, log an error and retry
            fprintf(stderr, "Error reading BH1750 sensor\n");
            continue;
        }

        // Log the timestamp and lux value
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&time(NULL)));
        fprintf(log_file, "%s lux: %d\n", timestamp, lux);

        // Trigger the relay based on the lux value
        if (lux < LUX_THRESHOLD) {
            gpioWrite(RELAY_PIN, 1);
        } else {
            gpioWrite(RELAY_PIN, 0);
        }

        // Sleep for the sampling interval
        usleep(SENSORSAMPLE_INTERVAL);
    }

    // Close the I2C handle
    i2cClose(I2C_BUS);

    // Close the log file
    fclose(log_file);

    // Deactivate the relay
    gpioWrite(RELAY_PIN, 0);

    // Terminate the GPIO library
    gpioTerminate();

    return 0;
}
