#define MEASURE_READINGS 5
#define MEASURE_INTERVAL 500
#define MAX_RETRIES 3

static volatile bool running = true;
static int tare_offset = 0;
static int scale = 1;
static int threshold = 1000;
static int duration = 200;

static void sigint_handler(int sig) {
    running = false;
}

static void sigterm_handler(int sig) {
    running = false;
}

static int read_hx711(gpiod_chip *chip, int dout, int sck) {
    int value = 0;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        gpiod_line_event_subscribe(chip, dout, GPIOD_LINE_EVENT_FALLING_EDGE, NULL, NULL);
        gpiod_line_event_wait(chip, dout, GPIOD_LINE_EVENT_FALLING_EDGE, 1000);
        if (gpiod_line_event_is_valid(chip, dout)) {
            break;
        }
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        syslog(LOG_ERR, "Failed to read HX711 data");
        return -1;
    }

    gpiod_line_set_value(chip, sck, 1);
    for (int i = 0; i < 24; i++) {
        gpiod_line_set_value(chip, sck, 0);
        usleep(1);
        gpiod_line_set_value(chip, sck, 1);
        usleep(1);
        value |= (gpiod_line_get_value(chip, dout) << (23 - i));
    }

    gpiod_line_set_value(chip, sck, 0);
    usleep(1);
    gpiod_line_set_value(chip, sck, 1);
    usleep(1);

    return value;
}

