    if (!sck) {
        syslog(LOG_ERR, "Failed to get HX711 SCK line");
        gpiod_line_unref(dout);
        gpiod_chip_unref(chip);
        exit(1);
    }

    sol = gpiod_chip_get_line(chip, GPIO_SOL);
    if (!sol) {
        syslog(LOG_ERR, "Failed to get solenoid line");
        gpiod_line_unref(dout);
        gpiod_line_unref(sck);
        gpiod_chip_unref(chip);
        exit(1);
    }

    gpiod_line_request_output(chip, dout, 0);
    gpiod_line_request_output(chip, sck, 0);
    gpiod_line_request_output(chip, sol, 0);

    syslog(LOG_INFO, "Starting tare measurement");
    for (int i = 0; i < TARE_READINGS; i++) {
        measure_weight(chip, HX711_DOUT, HX711_SCK);
    }
    tare_offset = measure_weight(chip, HX711_DOUT, HX711_SCK);

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (running) {
        int weight = measure_weight(chip, HX711_DOUT, HX711_SCK) - tare_offset;
        if (weight > threshold) {
            solenoid_lock(chip, GPIO_SOL);
        }
        syslog(LOG_INFO, "Weight: %d grams", weight);
        usleep(MEASURE_INTERVAL * 1000);
    }

    gpiod_line_set_value(chip, sol, 0);
    gpiod_line_unref(sol);
    gpiod_line_unref(sck);
    gpiod_line_unref(dout);
    gpiod_chip_unref(chip);
    closelog();

    return 0;
}

