#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define RELAY_PIN 17
#define KEEPALIVE 60
#define RETRY_DELAY 5000

static int gpio = -1;
static struct mosquitto *mosq = NULL;

void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, stopping loop and shutting down.", sig);
    mosquitto_loop_stop(mosq, MOSQ_OPT_MQTT_CLEAN_SESSION);
    gpioWrite(gpio, 0);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    exit(0);
}

void on_connect(struct mosquitto *mosq, void *userdata, int result, const struct mosquitto_connect_message *msg) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker.");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0, NULL);
    } else {
        syslog(LOG_ERR, "Connection failed with result %d: %s", result, mosquitto_connack_string(result));
    }
}

void on_disconnect(struct mosquitto *mosq, void *userdata, int result) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with result %d.", result);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    mosquitto_loop_start(mosq);
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    char *payload = (char *)message->payload;
    if (payload == NULL || strlen(payload) == 0 || strcmp(payload, "ON") != 0 && strcmp(payload, "OFF") != 0) {
        syslog(LOG_ERR, "Invalid message received: %s", payload);
        return;
    }
    if (strcmp(payload, "ON") == 0) {
        gpioWrite(gpio, 1);
        syslog(LOG_INFO, "Relay energized.");
    } else {
        gpioWrite(gpio, 0);
        syslog(LOG_INFO, "Relay de-energized.");
    }
    free(message->payload);
}

int main() {
    openlog("relay_controller", LOG_PID | LOG_PERROR, LOG_USER);
    syslog(LOG_INFO, "Starting relay controller.");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio: %d", gpioInitialise());
        closelog();
        exit(1);
    }

    gpio = gpioInitialise();
    if (gpioSetMode(gpio, RELAY_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to configure GPIO17 as output: %d", gpioSetMode(gpio, RELAY_PIN, PI_OUTPUT));
        gpioTerminate();
        closelog();
        exit(1);
    }

    if (gpioWrite(gpio, 0) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO17 LOW: %d", gpioWrite(gpio, 0));
        gpioTerminate();
        closelog();
        exit(1);
    }

    mosq = mosquitto_new(NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client.");
        gpioTerminate();
        closelog();
        exit(1);
    }

    mosquitto_log_callback_set(mosq, NULL);
    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE, MQTT_CLIENT_ID, NULL, NULL) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %d", mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE, MQTT_CLIENT_ID, NULL, NULL));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (1) {
        if (mosquitto_loop(mosq, 1000) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop failed: %d", mosquitto_loop(mosq, 1000));
            sleep(1);
            mosquitto_destroy(mosq);
            mosq = mosquitto_new(NULL);
            if (!mosq) {
                syslog(LOG_ERR, "Failed to recreate mosquitto client.");
                gpioTerminate();
                closelog();
                exit(1);
            }
            mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, KEEPALIVE, MQTT_CLIENT_ID, NULL, NULL);
        }
    }

    return 0;
}

