#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define NUM_PINS 5
#define PWM_FREQ 50  // Hz
#define PWM_RANGE 1000  // us
#define PWM_PERIOD_US (1000000 / PWM_FREQ)

int main() {
    int gpio_pins[NUM_PINS] = {7, 8, 9, 10, 11};
    int pulse_widths[NUM_PINS] = {1000, 1500, 2000, 500, 2500};
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set PWM frequency and range for each pin
    for (i = 0; i < NUM_PINS; i++) {
        if (gpioSetPWMfrequency(gpio_pins[i], PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWROutput(gpio_pins[i], 1) < 0) {
            fprintf(stderr, "Failed to set pin %d as output\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioPWM(gpio_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to set initial PWM value on pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWMrange(gpio_pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range on pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Apply pulse widths
    for (i = 0; i < NUM_PINS; i++) {
        if (gpioPWM(gpio_pins[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Failed to set PWM value on pin %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Hold signals for 3 seconds
    sleep(3);

    // Cleanly stop PWM
    for (i = 0; i < NUM_PINS; i++) {
        if (gpioPWM(gpio_pins[i], 0) < 0) {
            fprintf(stderr, "Failed to stop PWM on pin %d\n", gpio_pins[i]);
        }
    }

    // Release library resources
    gpioTerminate();

    return 0;
}

