#define ENCODER_B_A 6
#define ENCODER_B_B 12

// Define the target speed in RPM
#define TARGET_SPEED 50

// Define the PI controller gains
#define Kp 0.5
#define Ki 0.05

// Define the PWM frequency
#define PWM_FREQ 10000

// Define the PWM period
#define PWM_PERIOD 1000000 / PWM_FREQ

// Define the anti-windup clamping value
#define ANTI_WINDUP_CLAMP 0.9

// Define the stall detection timeout
#define STALL_TIMEOUT 2000000

// Define the shared encoder counters
volatile uint32_t encoder_a_count = 0;
volatile uint32_t encoder_b_count = 0;

// Define the motor states
volatile uint8_t motor_a_state = 0;
volatile uint8_t motor_b_state = 0;

// Define the PI controller state
volatile double error_a = 0.0;
volatile double error_b = 0.0;
volatile double integral_a = 0.0;
volatile double integral_b = 0.0;
volatile double output_a = 0.0;
volatile double output_b = 0.0;

// Define the PI controller update function
void update_pi_controller(uint32_t encoder_count, double *error, double *integral, double *output) {
    double dt = 0.01; // 100 ms period
    *error = (TARGET_SPEED * 60.0 / 64.0) - (encoder_count / dt);
    *integral += *error * dt;
    if (*integral > ANTI_WINDUP_CLAMP) {
        *integral = ANTI_WINDUP_CLAMP;
    } else if (*integral < -ANTI_WINDUP_CLAMP) {
        *integral = -ANTI_WINDUP_CLAMP;
    }
    *output = Kp * *error + Ki * *integral;
    if (*output > 1.0) {
        *output = 1.0;
    } else if (*output < -1.0) {
        *output = -1.0;
    }
}

// Define the ISR for the encoder A
void encoder_a_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        uint32_t current_count = gpioGet(ENCODER_A_A);
        if (current_count > encoder_a_count) {
            encoder_a_count++;
        } else if (current_count < encoder_a_count) {
            encoder_a_count--;
        }
    }
}

// Define the ISR for the encoder B
void encoder_b_isr(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        uint32_t current_count = gpioGet(ENCODER_B_A);
        if (current_count > encoder_b_count) {
            encoder_b_count++;
        } else if (current_count < encoder_b_count) {
            encoder_b_count--;
        }
    }
}

// Define the signal handler for SIGINT
void sigint_handler(int sig) {
    gpioWrite(MOTOR_A_PWM, 0);
    gpioWrite(MOTOR_B_PWM, 0);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the motor and encoder pins as outputs
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set the encoder ISR callbacks
    gpioSetISR(ENCODER_A_A, EITHER_EDGE, 0, encoder_a_isr);
    gpioSetISR(ENCODER_A_B, EITHER_EDGE, 0, encoder_a_isr);
    gpioSetISR(ENCODER_B_A, EITHER_EDGE, 0, encoder_b_isr);
    gpioSetISR(ENCODER_B_B, EITHER_EDGE, 0, encoder_b_isr);

    // Set the motor states
    motor_a_state = 0;
    motor_b_state = 0;

    // Set the PI controller state
    error_a = 0.0;
    error_b = 0.0;
    integral_a = 0.0;
    integral_b = 0.0;
    output_a = 0.0;
    output_b = 0.0;

    // Set the stall detection timeout
    uint32_t stall_timeout = 0;

    // Set the signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (1) {
        // Update the PI controller
        update_pi_controller(encoder_a_count, &error_a, &integral_a, &output_a);
        update_pi_controller(encoder_b_count, &error_b, &integral_b, &output_b);

        // Print the motor RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, PWM duty cycle: %.2f\n", (encoder_a_count / 60.0) * 64.0 / 0.01, output_a * 255.0);
        printf("Motor B RPM: %.2f, PWM duty cycle: %.2f\n", (encoder_b_count / 60.0) * 64.0 / 0.01, output_b * 255.0);

        // Check for stall detection
        if (stall_timeout > 0) {
            stall_timeout--;
            if (stall_timeout == 0) {
                printf("Warning: Motor A stalled\n");
                stall_timeout = 0;
            }
        }

        // Update the motor states
        if (output_a > 0) {
            motor_a_state = 1;
            gpioWrite(MOTOR_A_DIR, 0);
            gpioWrite(MOTOR_A_PWM, (uint8_t)(output_a * 255.0));
        } else if (output_a < 0) {
            motor_a_state = 2;
            gpioWrite(MOTOR_A_DIR, 1);
            gpioWrite(MOTOR_A_PWM, (uint8_t)(-output_a * 255.0));
        } else {
            motor_a_state = 0;
            gpioWrite(MOTOR_A_PWM, 0);
        }

        if (output_b > 0) {
            motor_b_state = 1;
            gpioWrite(MOTOR_B_DIR, 0);
            gpioWrite(MOTOR_B_PWM, (uint8_t)(output_b * 255.0));
        } else if (output_b < 0) {
            motor_b_state = 2;
            gpioWrite(MOTOR_B_DIR, 1);
            gpioWrite(MOTOR_B_PWM, (uint8_t)(-output_b * 255.0));
        } else {
            motor_b_state = 0;
            gpioWrite(MOTOR_B_PWM, 0);
        }

        // Check for stall detection
        if (encoder_a_count == 0 && stall_timeout == 0) {
            stall_timeout = STALL_TIMEOUT;
        }
        if (encoder_b_count == 0 && stall_timeout == 0) {
            stall_timeout = STALL_TIMEOUT;
        }

        // Sleep for 100 ms
        usleep(PWM_PERIOD);
    }

