#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define LUX_HYSTERESIS 10
#define LUX_THRESHOLD_LOW 50
#define LUX_THRESHOLD_HIGH 200
#define POLL_INTERVAL 5000
#define DELAY_AFTER_HR_MODE 180

#define LOG_FILE "chicken_coop_log.txt"

bool running = true;
bool relay_on = false;
int i2c_handle = -1;
int relay_gpio = -1;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void log_event(const char *format, ...) {
    time_t now = time(NULL);
    struct tm *current_time = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", current_time);
    va_list args;
    va_start(args, format);
    vfprintf(stderr, format, args);
    fprintf(stderr, " %s\n", timestamp);
    va_end(args);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }
    fprintf(log_file, "%s Lux = %d, Relay = %s\n", timestamp, 0, relay_on ? "ON" : "OFF");
    fclose(log_file);
}

void read_lux() {
    if (i2c_handle == -1) {
        log_event("Error: I2C handle not initialized");
        return;
    }
    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialization failed");
        return;
    }
    if (relay_gpio == -1) {
        relay_gpio = gpioOpen(I2C_BUS, RELAY_GPIO);
        if (relay_gpio == -1) {
            log_event("Error: Unable to open relay GPIO");
            return;
        }
    }
    if (gpioSetMode(relay_gpio, PI_OUTPUT) < 0) {
        log_event("Error: Unable to set relay GPIO mode");
        return;
    }
    if (gpioWrite(relay_gpio, relay_on ? 1 : 0) < 0) {
        log_event("Error: Unable to set relay state");
        return;
    }
    if (i2cWriteReg8(i2c_handle, I2C_ADDRESS, 0x21, 0x00) < 0) {
        log_event("Error: Unable to set HR mode");
        return;
    }
    usleep(DELAY_AFTER_HR_MODE * 1000);
    uint8_t data[2];
    if (i2cReadReg8(i2c_handle, I2C_ADDRESS, 0x40, data, 2) < 0) {
        log_event("Error: Unable to read lux data");
        return;
    }
    int lux = (data[0] << 8) | data[1];
    lux /= 1.2;
    if (lux < LUX_THRESHOLD_LOW && !relay_on) {
        relay_on = true;
        log_event("Relay turned ON");
    } else if (lux > LUX_THRESHOLD_HIGH && relay_on) {
        relay_on = false;
        log_event("Relay turned OFF");
    }
    log_event("Lux = %d", lux);
}

int main() {
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS);
    if (i2c_handle == -1) {
        log_event("Error: Unable to open I2C bus");
        return 1;
    }
    if (i2cSetClock(i2c_handle, 100000) < 0) {
        log_event("Error: Unable to set I2C clock");
        return 1;
    }
    while (running) {
        read_lux();
        usleep(POLL_INTERVAL * 1000);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (relay_gpio != -1) {
        gpioClose(relay_gpio);
    }
    return 0;
}

