// Function to handle SIGINT (Ctrl+C) signal
void sigint_handler(int sig) {
    // Turn the relay OFF
    if (gpioWrite(17, 0) < 0) {
        fprintf(stderr, "Error turning relay OFF: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Release pigpio resources
    if (gpioTerminate() < 0) {
        fprintf(stderr, "Error releasing pigpio resources: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Print exit message
    printf("Exiting...\n");
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio: %s\n", pigpioErrorStr(errno));
        exit(1);
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Configure GPIO 4 as input
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 4 as input: %s\n", pigpioErrorStr(errno));
        gpioTerminate();
        exit(1);
    }

    // Configure GPIO 17 as output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO 17 as output: %s\n", pigpioErrorStr(errno));
        gpioTerminate();
        exit(1);
    }

    // Initialize relay state to OFF
    int relay_state = 0;

    while (1) {
        // Read the state of the touch sensor
        int sensor_state = gpioRead(4);

        // Check if the sensor is HIGH
        if (sensor_state == 1) {
            // Wait for 50 ms to allow for stabilization
            usleep(50000);

            // Read the state of the touch sensor again
            int sensor_state_stable = gpioRead(4);

            // Check if the sensor is still HIGH after the delay
            if (sensor_state_stable == 1) {
                // Toggle the relay state
                relay_state = !relay_state;

                // Write the new relay state
                if (gpioWrite(17, relay_state) < 0) {
                    fprintf(stderr, "Error writing to GPIO 17: %s\n", pigpioErrorStr(errno));
                    gpioTerminate();
                    exit(1);
                }

                // Log the relay state change
                char timestamp[32];
                time_t now = time(NULL);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
                printf("%s: Relay state changed to %s\n", timestamp, relay_state ? "ON" : "OFF");
            }
        }

        // Wait for the sensor to return LOW before allowing the next toggle
        while (gpioRead(4) == 1) {
            usleep(1000);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    return 0;
}

