#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLINOID_PIN 27
#define CALIBRATION_PULSES_PER_LITER 450.0
#define LPM_HYSTERESIS 0.5
#define SAMPLE_INTERVAL 1000  // milliseconds
#define LOG_FILE "water_flow.log"

// Mutex for protecting shared pulse counter
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Shared pulse counter
volatile uint32_t pulse_count = 0;

// Flag to track solenoid state
bool solenoid_open = true;

// Flag to track log file descriptor
int log_fd = -1;

// Function to log a message with timestamp
void log_message(const char *format, ...) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    char message[256];
    va_list args;
    va_start(args, format);
    vsnprintf(message, sizeof(message), format, args);
    va_end(args);
    fprintf(log_fd, "%s %s\n", timestamp, message);
    fflush(log_fd);
}

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    log_message("Received signal %d", sig);
    gpioWrite(SOLINOID_PIN, solenoid_open ? 1 : 0);
    if (log_fd != -1) {
        fclose(log_fd);
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(0);
}

// Function to compute LPM from pulse count
double compute_lpm() {
    pthread_mutex_lock(&pulse_mutex);
    double lpm = (pulse_count / CALIBRATION_PULSES_PER_LITER) * 60.0;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);
    return lpm;
}

// Function to handle flow sensor interrupts
void *flow_sensor_isr(void *arg) {
    while (1) {
        int edge = gpioRead(FLOW_SENSOR_PIN);
        if (edge == 1) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
        }
        usleep(SAMPLE_INTERVAL * 1000);
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(1);
    }

    // Set up GPIO modes
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set flow sensor pin mode");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(SOLINOID_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid pin mode");
        gpioTerminate();
        exit(1);
    }

    // Set up ISR for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, SAMPLE_INTERVAL, flow_sensor_isr, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set flow sensor ISR");
        gpioTerminate();
        exit(1);
    }

    // Open log file
    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        double lpm = compute_lpm();
        log_message("LPM: %.2f", lpm);
        if (lpm > 5.0) {
            solenoid_open = false;
            log_message("Solenoid closed");
        } else if (lpm < 4.5) {
            solenoid_open = true;
            log_message("Solenoid open");
        }
        usleep(100000);  // 100ms
    }

    // Clean up on exit
    fclose(log_fd);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    return 0;
}

