    }
    if (load_cell_data_pin != -1) {
        gpioTerminate();
    }
    exit(0);
}

void sigterm_handler(int sig) {
    sigint_handler(sig);
}

void load_config(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        exit(1);
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        line[strcspn(line, "\n")] = 0;
        if (strncmp(line, "calibration_factor =", 17) == 0) {
            config.calibration_factor = atof(line + 17);
        } else if (strncmp(line, "server_ip =", 10) == 0) {
            strncpy(config.server_ip, line + 10, 15);
            config.server_ip[15] = '\0';
        } else if (strncmp(line, "server_port =", 12) == 0) {
            config.server_port = atoi(line + 12);
        }
    }

    fclose(file);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing GPIO: %s\n", gpioErrorStr(gpioInitError()));
        exit(1);
    }
    load_cell_data_pin = gpioOpen(DEFAULT_LOAD_CELL_DATA_PIN, PI_INPUT);
    if (load_cell_data_pin == -1) {
        fprintf(stderr, "Error opening load cell data pin: %s\n", strerror(errno));
        exit(1);
    }
    load_cell_clock_pin = gpioOpen(DEFAULT_LOAD_CELL_CLOCK_PIN, PI_OUTPUT);
    if (load_cell_clock_pin == -1) {
        fprintf(stderr, "Error opening load cell clock pin: %s\n", strerror(errno));
        exit(1);
    }
    servo_pin = gpioOpen(DEFAULT_SERVO_PIN, PI_OUTPUT);
    if (servo_pin == -1) {
        fprintf(stderr, "Error opening servo pin: %s\n", strerror(errno));
        exit(1);
    }
}

void cleanup_gpio() {
    if (servo_pin != -1) {
        gpioWrite(servo_pin, 0);
        gpioTerminate();
    }
    if (load_cell_data_pin != -1) {
        gpioTerminate();
    }
}

void init_servo() {
    gpioWrite(servo_pin, 0);
}

void cleanup_servo() {
    gpioWrite(servo_pin, 0);
}

void read_load_cell() {
    int attempts = 0;
    int data = 0;
    while (attempts < DEFAULT_TIMEOUT) {
        gpioWrite(load_cell_clock_pin, 1);
        usleep(1);
        gpioWrite(load_cell_clock_pin, 0);
        usleep(1);
        data = gpioRead(load_cell_data_pin);
        if (data == 1) {
            break;
        }
        attempts++;
    }
    if (attempts == DEFAULT_TIMEOUT) {
        fprintf(stderr, "Error reading load cell: timeout\n");
        return;
    }
    int clock = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(load_cell_clock_pin, 1);
        usleep(1);
        int bit = gpioRead(load_cell_data_pin);
        gpioWrite(load_cell_clock_pin, 0);
        usleep(1);
        clock = (clock << 1) | bit;
    }
    return (double)clock * config.calibration_factor;
}

void handle_client() {
    char buffer[256];
    int bytes_received = recv(sock, buffer, 256, 0);
    if (bytes_received == -1) {
        fprintf(stderr, "Error receiving data from client: %s\n", strerror(errno));
        return;
    }
    buffer[bytes_received] = '\0';
    double target_weight = atof(buffer);
    if (target_weight <= 0) {
        fprintf(stderr, "Error: target weight must be positive\n");
        return;
    }
    init_servo();
    usleep(1000000);
    double actual_weight = read_load_cell();
    if (actual_weight == 0) {
        fprintf(stderr, "Error reading load cell\n");
        return;
    }
    char json[1024];
    json_object *root = json_object_new_object();
    json_object_object_add(root, "date", json_object_new_string(asctime(localtime(&time(NULL))));
    json_object_object_add(root, "time", json_object_new_string(ctime(&time(NULL))));
    json_object_object_add(root, "target_weight", json_object_new_double(target_weight));
    json_object_object_add(root, "actual_weight", json_object_new_double(actual_weight));
    json_object_object_add(root, "error_message", json_object_new_string(""));
    char *json_str = json_object_to_json_string_ext(root, JSON_CSTYLE | JSON_PRESERVE_ORDER);
    FILE *log_file = fopen(DEFAULT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    fprintf(log_file, "%s", json_str);
    fclose(log_file);
    free(json_str);
    json_object_put(root);
    double pulse_width = (target_weight / actual_weight) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH;
    gpioWrite(servo_pin, 1);
    usleep((int)pulse_width);
    gpioWrite(servo_pin, 0);
    usleep(1000000);
    close(sock);
}

int main() {
    load_config("config.ini");
    if (config.calibration_factor == 0) {
        config.calibration_factor = DEFAULT_CALIBRATION_FACTOR;
    }
    if (config.server_ip[0] == '\0') {
        strncpy(config.server_ip, DEFAULT_SERVER_IP, 15);
        config.server_ip[15] = '\0';
    }
    if (config.server_port == 0) {
        config.server_port = DEFAULT_SERVER_PORT;
    }
    init_gpio();
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock == -1) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        exit(1);
    }
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_port = htons(config.server_port);
    inet_pton(AF_INET, config.server_ip, &server.sin_addr);
    if (bind(sock, (struct sockaddr *)&server, sizeof(server)) == -1) {
        fprintf(stderr, "Error binding socket: %s\n", strerror(errno));
        exit(1);
    }
    if (listen(sock, 1) == -1) {
        fprintf(stderr, "Error listening on socket: %s\n", strerror(errno));
        exit(1);
    }
    printf("Server listening on %s:%d\n", config.server_ip, config.server_port);
    while (1) {
        struct sockaddr_in client;
        socklen_t client_len = sizeof(client);
        int client_sock = accept(sock, (struct sockaddr *)&client, &client_len);
        if (client_sock == -1) {
            fprintf(stderr, "Error accepting client: %s\n", strerror(errno));
            continue;
        }
        handle_client();
    }
    return 0;
}
