#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

#define RELAY_PIN 17
#define TOUCH_PIN 4
#define DEFAULT_DEBOUNCE 50

int debounce = DEFAULT_DEBOUNCE;
int relay_state = 0;
int touch_state = 0;
int touch_prev_state = 0;
int gpio_fd = -1;

void sigint_handler(int sig) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

void sigterm_handler(int sig) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    exit(0);
}

void touch_handler(int level, int edge, uint32_t tick) {
    if (edge == RISING_EDGE) {
        if (level == 1) {
            if (touch_state == 0) {
                touch_state = 1;
                touch_prev_state = 0;
            } else {
                touch_state = 0;
                touch_prev_state = 1;
            }
        }
    }
}

int main(int argc, char **argv) {
    int opt;
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpio_fd = gpioOpen(TOUCH_PIN, PI_INPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(TOUCH_PIN, PI_INPUT);
    if (gpioGetMode(TOUCH_PIN) != PI_INPUT) {
        fprintf(stderr, "Failed to set GPIO pin %d to input mode\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    gpioSetAlertFunc(TOUCH_PIN, touch_handler);
    if (gpioGetAlertFunc(TOUCH_PIN) != touch_handler) {
        fprintf(stderr, "Failed to set alert function for GPIO pin %d\n", TOUCH_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    while (1) {
        int level = gpioRead(TOUCH_PIN);
        if (level == 1 && touch_state == 1) {
            usleep(debounce * 1000);
            level = gpioRead(TOUCH_PIN);
            if (level == 1) {
                if (touch_prev_state == 0) {
                    relay_state = !relay_state;
                    if (relay_state) {
                        gpioWrite(RELAY_PIN, 1);
                        printf("%s Relay: ON\n", asctime(localtime(&time(NULL))));
                    } else {
                        gpioWrite(RELAY_PIN, 0);
                        printf("%s Relay: OFF\n", asctime(localtime(&time(NULL))));
                    }
                    touch_prev_state = 1;
                }
            } else {
                touch_prev_state = 0;
            }
        }
        usleep(10000);
    }

    return 0;
}

