#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_GPIO 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define SERVO_FREQ 50
#define SERVO_STEP 10

volatile int running = 1;
int angle = 90;

void sigint_handler(int sig) {
    running = 0;
}

void update_servo() {
    int pulse_width = (angle - 90) * (SERVO_MAX - SERVO_MIN) / 180 + SERVO_MIN;
    if (pulse_width < SERVO_MIN || pulse_width > SERVO_MAX) {
        fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        pulse_width = (pulse_width < SERVO_MIN) ? SERVO_MIN : SERVO_MAX;
    }
    if (gpioServo(SERVO_GPIO, pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width: %d\n", pulse_width);
    }
    fprintf(stderr, "Angle: %d°\n", angle);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpioInitialise());
        return 1;
    }

    struct termios old_termios;
    if (tcgetattr(STDIN_FILENO, &old_termios) == -1) {
        perror("tcgetattr");
        return 1;
    }

    struct termios new_termios = old_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO);
    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) == -1) {
        perror("tcsetattr");
        return 1;
    }

    signal(SIGINT, sigint_handler);

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetPWM(SERVO_GPIO, 0, SERVO_FREQ);

    while (running) {
        char c = getchar();
        if (c == '+') {
            angle = (angle + SERVO_STEP) % 181;
        } else if (c == '-') {
            angle = (angle - SERVO_STEP + 181) % 181;
        } else if (c == 'q') {
            running = 0;
        }
        update_servo();
    }

    gpioTerminate();
    if (tcsetattr(STDIN_FILENO, TCSANOW, &old_termios) == -1) {
        perror("tcsetattr");
    }

    return 0;
}

