#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_LINE_NUMBER 17
#define DEBOUNCE_WINDOW_US 2000
#define SAMPLE_INTERVAL_S 5
#define LOG_FILE "motor_rpm.log"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    struct timespec last_sample_time;
    clock_gettime(CLOCK_MONOTONIC, &last_sample_time);
    int pulse_count = 0;
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }

    int chip = gpiod_chip_open(GPIO_CHIP_NAME);
    if (chip == -1) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", GPIO_CHIP_NAME);
        exit(EXIT_FAILURE);
    }

    int line = gpiod_chip_get_line(chip, GPIO_LINE_NUMBER);
    if (line == -1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input_flags(line, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) == -1) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    while (running) {
        struct gpiod_line_event event;
        if (gpiod_line_event_wait(line, GPIOD_LINE_EVENT_RISING_EDGE, DEBOUNCE_WINDOW_US, &event) == -1) {
            fprintf(stderr, "Failed to wait for event on line %d: %s\n", GPIO_LINE_NUMBER, GPIO_CHIP_NAME);
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            fclose(log_file);
            exit(EXIT_FAILURE);
        }
        pulse_count++;
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_sec - last_sample_time.tv_sec >= SAMPLE_INTERVAL_S) {
            double rpm = (pulse_count / 5.0) * 60.0;
            fprintf(log_file, "%s,%.2f\n", iso8601_time_string(&now), rpm);
            fflush(log_file);
            pulse_count = 0;
            last_sample_time = now;
            printf("RPM: %.2f\n", rpm);
        }
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

char *iso8601_time_string(struct timespec *ts) {
    static char buffer[32];
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", localtime(&ts->tv_sec));
    char *result = malloc(strlen(buffer) + 9);
    sprintf(result, "%s.%06dZ", buffer, (int)ts->tv_nsec);
    return result;
}

