    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the GPIO pins
    if (gpioSetMode(4, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the relay to OFF
    gpioWrite(17, 0);

    // Main loop
    while (!exit_program) {
        // Read the state of the touch sensor
        int sensor_state = gpioRead(4);
        if (sensor_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO4\n");
            gpioTerminate();
            return 1;
        }

        // Check if the touch sensor is pressed
        if (sensor_state == 1) {
            // Check if the touch sensor has been pressed for more than 10 seconds
            if (touch_pressed) {
                touch_failsafe = 1;
            } else {
                touch_pressed = 1;
                touch_failsafe = 0;
            }
        } else {
            touch_pressed = 0;
        }

        // Check if the touch sensor has been pressed for more than 10 seconds
        if (touch_failsafe) {
            // Force the relay OFF
            gpioWrite(17, 0);
            touch_failsafe = 0;
        } else {
            // Toggle the relay state
            if (relay_on) {
                gpioWrite(17, 0);
                relay_on = 0;
            } else {
                gpioWrite(17, 1);
                relay_on = 1;
            }
        }

        // Poll the sensor every 50 ms
        usleep(50000);
    }

    // Clean up
    gpioWrite(17, 0); // Set the relay OFF
    gpioTerminate();

    return 0;
}

