#define GPIO_VALVE_ENABLE 23
#define GPIO_VALVE_PWM 18
#define GPIO_FLOW_SENSOR 24
#define FLOW_SENSOR_PULSES_PER_LITER 450.0
#define CONTROL_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

volatile int pulse_count = 0;
volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void sigterm_handler(int sig) {
    running = false;
}

void flow_sensor_isr(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

int main(int argc, char **argv) {
    int target_flow_rate = 0;
    char *endptr;
    char log_file[256];

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                target_flow_rate = strtol(optarg, &endptr, 10);
                if (*endptr != '\0' || target_flow_rate <= 0) {
                    fprintf(stderr, "Invalid target flow rate\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO modes
    if (gpioSetMode(GPIO_VALVE_ENABLE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_VALVE_ENABLE);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_VALVE_PWM, PI_PWM) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_VALVE_PWM);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_FLOW_SENSOR, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", GPIO_FLOW_SENSOR);
        gpioTerminate();
        return 1;
    }

    // Enable the valve
    gpioWrite(GPIO_VALVE_ENABLE, 1);

    // Register ISR for flow sensor
    if (gpioSetISR(GPIO_FLOW_SENSOR, EITHER_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR for GPIO %d\n", GPIO_FLOW_SENSOR);
        gpioTerminate();
        return 1;
    }

    // Open log file
    FILE *log_file_ptr = fopen(LOG_FILE, "w");
    if (log_file_ptr == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main control loop
    while (running) {
        // Sample flow rate
        usleep(CONTROL_INTERVAL_MS * 1000);
        double flow_rate = (double)pulse_count * FLOW_SENSOR_PULSES_PER_LITER / (CONTROL_INTERVAL_MS / 1000.0);
        pulse_count = 0;

        // Compute valve position
        double valve_position = (target_flow_rate > 0) ? (flow_rate / target_flow_rate) * 255 : 0;
        valve_position = (valve_position < 0) ? 0 : (valve_position > 255) ? 255 : valve_position;

        // Log data
        fprintf(log_file_ptr, "%d,%.2f,%.2f\n", (int)time(NULL) * 1000, flow_rate, valve_position);

        // Update PWM
        gpioPWM(GPIO_VALVE_PWM, (int)valve_position);

        // Check for SIGINT or SIGTERM
        if (!running) {
            break;
        }
    }

    // Clean up
    gpioPWM(GPIO_VALVE_PWM, 0);
    gpioWrite(GPIO_VALVE_ENABLE, 0);
    gpioTerminate();
    fclose(log_file_ptr);
    return 0;
}

