#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TAG_SIZE 10
#define LOCK_PIN_1 17
#define LOCK_PIN_2 27
#define RFID_PIN 0
#define BUTTON_PIN 22
#define DEBOUNCE_TIME 50
#define LOCK_TIME 5000000

// Signal handler for clean shutdown
void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
    spiClose(RFID_PIN);
    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

// Function to check RFID tag
bool check_tag(uint8_t *tag) {
    for (int i = 0; i < TAG_SIZE; i++) {
        if (tag[i] != 0x01 + i) {
            return false;
        }
    }
    return true;
}

int main() {
    // Initialize GPIO and SPI
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO");
        exit(1);
    }
    if (spiOpen(RFID_PIN, 100000, NULL) < 0) {
        syslog(LOG_ERR, "Failed to open SPI channel");
        gpioTerminate();
        exit(1);
    }

    // Set up log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file");
        gpioTerminate();
        exit(1);
    }

    // Set up signal handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set up signal handler");
        gpioTerminate();
        exit(1);
    }

    // Initialize lock pins
    gpioSetMode(LOCK_PIN_1, PI_OUTPUT);
    gpioSetMode(LOCK_PIN_2, PI_OUTPUT);
    gpioWrite(LOCK_PIN_1, 1);
    gpioWrite(LOCK_PIN_2, 1);

    // Main loop
    while (1) {
        // Check RFID tag
        uint8_t tag[TAG_SIZE];
        int len = spiXfer(RFID_PIN, tag, TAG_SIZE, NULL, 0);
        if (len < 0) {
            syslog(LOG_INFO, "RFID read failed");
            continue;
        }
        if (len != TAG_SIZE) {
            syslog(LOG_INFO, "Invalid RFID read length");
            continue;
        }
        if (memcmp(tag, "\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0A", TAG_SIZE) == 0) {
            syslog(LOG_INFO, "Valid RFID tag detected");
            // Check button press
            int button_state = gpioRead(BUTTON_PIN);
            if (button_state == 0) {
                syslog(LOG_INFO, "Button pressed");
                // Wait for debounce time
                for (int i = 0; i < DEBOUNCE_TIME / 1000; i++) {
                    gpioDelay(1000);
                    if (gpioRead(BUTTON_PIN) == 1) {
                        break;
                    }
                }
                if (gpioRead(BUTTON_PIN) == 1) {
                    syslog(LOG_INFO, "Button debounced");
                    // Disengage locks
                    gpioWrite(LOCK_PIN_1, 0);
                    gpioWrite(LOCK_PIN_2, 0);
                    syslog(LOG_INFO, "Locks disengaged");
                    gpioDelay(LOCK_TIME);
                    // Re-engage locks
                    gpioWrite(LOCK_PIN_1, 1);
                    gpioWrite(LOCK_PIN_2, 1);
                    syslog(LOG_INFO, "Locks re-engaged");
                } else {
                    syslog(LOG_INFO, "Button press without valid tag");
                }
            } else {
                syslog(LOG_INFO, "Button not pressed");
            }
        } else {
            syslog(LOG_INFO, "Invalid RFID tag");
        }
    }

    return 0;
}

