#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pthread.h>
#include <gpiod.h>

// PID controller parameters
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define SAMPLE_TIME_MS 100

// Motor and encoder pin definitions
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20
#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID state
typedef struct {
    double error;
    double integral;
    double derivative;
    double output;
} pid_state_t;

// Shared encoder counts
