#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define RELAY_PIN 17
#define MPR121_ADDRESS 0x5A
#define TOUCH_THRESHOLD 0x0F
#define RELEASE_THRESHOLD 0x0F
#define FILTER_CONFIG 0x00
#define RUN_MODE 0x01
#define TOUCH_STATUS_REG 0x00
#define TOUCH_STATUS_REG2 0x01

void relay_handler(int sig) {
    gpio_write(RELAY_PIN, 0);
    close_i2c_file();
    exit(0);
}

int main() {
    int i2c_file = -1;
    int relay_state = 0;

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    // Set up relay pin as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus 1
    if ((i2c_file = open_i2c_bus(1)) < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Soft reset MPR121
    if (i2c_write_byte(i2c_file, MPR121_ADDRESS, 0x1A) < 0) {
        fprintf(stderr, "Failed to soft reset MPR121\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    // Configure filtering
    if (i2c_write_byte(i2c_file, MPR121_ADDRESS, FILTER_CONFIG) < 0) {
        fprintf(stderr, "Failed to configure filtering\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    // Set touch and release thresholds
    for (int i = 0; i < 12; i++) {
        uint8_t reg = i + 0x02;
        if (i2c_write_byte(i2c_file, MPR121_ADDRESS, reg) < 0) {
            fprintf(stderr, "Failed to set touch/release threshold for electrode %d\n", i);
            close_i2c_file();
            gpioTerminate();
            return 1;
        }
        if (i2c_write_byte(i2c_file, MPR121_ADDRESS, reg + 1) < 0) {
            fprintf(stderr, "Failed to set touch/release threshold for electrode %d\n", i);
            close_i2c_file();
            gpioTerminate();
            return 1;
        }
    }

    // Enable run mode
    if (i2c_write_byte(i2c_file, MPR121_ADDRESS, RUN_MODE) < 0) {
        fprintf(stderr, "Failed to enable run mode\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, relay_handler);

    FILE *relay_log = fopen("relay_log.txt", "w");
    if (!relay_log) {
        fprintf(stderr, "Failed to open relay log file\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Poll touch status registers
        uint8_t touch_status[2];
        if (i2c_read(i2c_file, MPR121_ADDRESS, TOUCH_STATUS_REG, 2, touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status registers\n");
            fclose(relay_log);
            close_i2c_file();
            gpioTerminate();
            return 1;
        }

        // Check if any electrode is touched
        bool touched = false;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                touched = true;
                break;
            }
        }

        // Toggle relay state
        if (touched && relay_state == 0) {
            gpio_write(RELAY_PIN, 1);
            relay_state = 1;
            fprintf(relay_log, "%lu: Relay activated\n", time(NULL));
        } else if (!touched && relay_state == 1) {
            gpio_write(RELAY_PIN, 0);
            relay_state = 0;
            fprintf(relay_log, "%lu: Relay deactivated\n", time(NULL));
        }

        usleep(50000);
    }

    fclose(relay_log);
    close_i2c_file();
    gpioTerminate();
    return 0;
}

