            fprintf(stderr, "Failed to set touch/release threshold for electrode %d\n", i);
            close_i2c_file();
            gpioTerminate();
            return 1;
        }
    }

    // Enable run mode
    if (i2c_write_byte(i2c_file, MPR121_ADDRESS, RUN_MODE) < 0) {
        fprintf(stderr, "Failed to enable run mode\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, relay_handler);

    FILE *relay_log = fopen("relay_log.txt", "w");
    if (!relay_log) {
        fprintf(stderr, "Failed to open relay log file\n");
        close_i2c_file();
        gpioTerminate();
        return 1;
    }

    while (1) {
        // Poll touch status registers
        uint8_t touch_status[2];
        if (i2c_read(i2c_file, MPR121_ADDRESS, TOUCH_STATUS_REG, 2, touch_status) < 0) {
            fprintf(stderr, "Failed to read touch status registers\n");
            fclose(relay_log);
            close_i2c_file();
            gpioTerminate();
            return 1;
        }

        // Check if any electrode is touched
        bool touched = false;
        for (int i = 0; i < 12; i++) {
            if (touch_status[i / 8] & (1 << (i % 8))) {
                touched = true;
                break;
            }
        }

        // Toggle relay state
        if (touched && relay_state == 0) {
            gpio_write(RELAY_PIN, 1);
            relay_state = 1;
            fprintf(relay_log, "%lu: Relay activated\n", time(NULL));
        } else if (!touched && relay_state == 1) {
            gpio_write(RELAY_PIN, 0);
            relay_state = 0;
            fprintf(relay_log, "%lu: Relay deactivated\n", time(NULL));
        }

        usleep(50000);
    }

    fclose(relay_log);
    close_i2c_file();
    gpioTerminate();
    return 0;
}
