#include <libgpiod.h>

#define VALVE1_GPIO 17
#define VALVE2_GPIO 18
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000
#define PAUSE_DURATION 5
#define PAUSE_DURATION_2 10

#define LOG_FILE "valve_log.txt"

void cleanup(int sig) {
    gpiod_line_release(VALVE1_GPIO);
    gpiod_line_release(VALVE2_GPIO);
    fclose(log_file);
    exit(0);
}

int main() {
    struct gpiod_line *valve1_line, *valve2_line;
    FILE *log_file;
    char timestamp[32];

    // Initialize log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handlers
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error setting up signal handlers: %s\n", strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO chip
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error initializing GPIO chip: %s\n", gpiod_error_str(errno));
        fclose(log_file);
        return 1;
    }

    // Request output lines
    valve1_line = gpiod_chip_get_line(chip, VALVE1_GPIO);
    if (!valve1_line) {
        fprintf(stderr, "Error requesting line %d: %s\n", VALVE1_GPIO, gpiod_error_str(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    valve2_line = gpiod_chip_get_line(chip, VALVE2_GPIO);
    if (!valve2_line) {
        fprintf(stderr, "Error requesting line %d: %s\n", VALVE2_GPIO, gpiod_error_str(errno));
        gpiod_line_release(VALVE1_GPIO);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Set direction to output
    if (gpiod_line_request_output(valve1_line, 0) == -1) {
        fprintf(stderr, "Error setting line %d as output: %s\n", VALVE1_GPIO, gpiod_error_str(errno));
        gpiod_line_release(VALVE1_GPIO);
        gpiod_line_release(VALVE2_GPIO);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }
    if (gpiod_line_request_output(valve2_line, 0) == -1) {
        fprintf(stderr, "Error setting line %d as output: %s\n", VALVE2_GPIO, gpiod_error_str(errno));
        gpiod_line_release(VALVE1_GPIO);
        gpiod_line_release(VALVE2_GPIO);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        gpiod_line_set_value(valve1_line, 1);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&time(NULL)));
        fprintf(log_file, "%s: Valve 1 open\n", timestamp);
        usleep(VALVE1_DURATION * 1000);

        // Pause
        usleep(PAUSE_DURATION * 1000000);

        // Activate Valve 2
        gpiod_line_set_value(valve2_line, 1);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&time(NULL)));
        fprintf(log_file, "%s: Valve 2 open\n", timestamp);
        usleep(VALVE2_DURATION * 1000);

        // Pause
        usleep(PAUSE_DURATION_2 * 1000000);
    }

    return 0;
}

