#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Function to handle signal interrupts
void sigint_handler(int sig) {
    // Close I2C bus and terminate pigpio
    i2c_close(1);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    int i2c_fd = i2cOpen(1, 0x5A);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121 in stop mode
    uint8_t stop_mode = 0x00;
    if (i2cWriteReg8(i2c_fd, 0x02, stop_mode) < 0) {
        fprintf(stderr, "Failed to set MPR121 in stop mode\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set touch threshold and release threshold for all electrodes
    uint8_t touch_threshold = 0x10;
    uint8_t release_threshold = 0x0A;
    if (i2cWriteReg8(i2c_fd, 0x03, touch_threshold) < 0 || i2cWriteReg8(i2c_fd, 0x04, release_threshold) < 0) {
        fprintf(stderr, "Failed to set touch and release thresholds\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure filter/charge time and electrode current
    uint8_t filter_charge_time = 0x20;
    uint8_t electrode_current = 0x01;
    if (i2cWriteReg8(i2c_fd, 0x05, filter_charge_time) < 0 || i2cWriteReg8(i2c_fd, 0x06, electrode_current) < 0) {
        fprintf(stderr, "Failed to configure filter/charge time and electrode current\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Enter run mode with ELE_EN=1
    uint8_t run_mode = 0x20;
    if (i2cWriteReg8(i2c_fd, 0x02, run_mode) < 0) {
        fprintf(stderr, "Failed to enter run mode\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Wait 100 ms for stabilization
    usleep(100000);

    // Set relay pin as output
    int relay_pin = 17;
    if (gpioSetMode(relay_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin as output\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initially turn off the relay
    if (gpioWrite(relay_pin, 0) < 0) {
        fprintf(stderr, "Failed to turn off relay\n");
        i2c_close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch status registers
        uint8_t touch_status = i2cReadReg8(i2c_fd, 0x00);
        if (touch_status < 0) {
            fprintf(stderr, "Failed to read touch status\n");
            i2c_close(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Check if any electrode is touched
        if (touch_status > 0) {
            // Toggle the relay
            if (gpioWrite(relay_pin, !gpioRead(relay_pin)) < 0) {
                fprintf(stderr, "Failed to toggle relay\n");
                i2c_close(i2c_fd);
                gpioTerminate();
                return 1;
            }

            // Print the status
            printf("Relay is %s\n", gpioRead(relay_pin) ? "on" : "off");
        }

        // Delay 100 ms
        usleep(100000);
    }

    // Close I2C bus and terminate pigpio
    i2c_close(i2c_fd);
    gpioTerminate();

    return 0;
}

