#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define RELAY_GPIO 18
#define PIR_GPIO 17
#define RELAY_ON 1
#define RELAY_OFF 0
#define UNLOCK_DURATION 500
#define RATE_LIMIT 2000
#define LOG_FILE "door_events.log"

bool rateLimited = false;
time_t lastMotion = 0;

void logEvent(const char *event, time_t timestamp) {
    FILE *logFile = fopen(LOG_FILE, "a");
    if (logFile == NULL) {
        perror("fopen");
        exit(1);
    }
    fprintf(logFile, "%lld %s\n", timestamp, event);
    fclose(logFile);
}

void unlockDoor() {
    if (gpioWrite(RELAY_GPIO, RELAY_ON) != 0) {
        perror("gpioWrite");
        exit(1);
    }
    usleep(UNLOCK_DURATION * 1000);
    if (gpioWrite(RELAY_GPIO, RELAY_OFF) != 0) {
        perror("gpioWrite");
        exit(1);
    }
}

void handleMotion(int edge, int level, uint32_t tick) {
    if (edge == RISING_EDGE) {
        if (!rateLimited) {
            rateLimited = true;
            lastMotion = tick;
            logEvent("Motion detected", tick);
            unlockDoor();
            logEvent("Door unlocked", tick);
        } else {
            time_t now = tick;
            if (now - lastMotion >= RATE_LIMIT) {
                rateLimited = false;
                logEvent("Rate limit expired", now);
            }
        }
    }
}

void cleanup() {
    if (gpioTerminate() != 0) {
        perror("gpioTerminate");
        exit(1);
    }
    if (unlink(LOG_FILE) != 0) {
        perror("unlink");
    }
    if (gpioWrite(RELAY_GPIO, RELAY_OFF) != 0) {
        perror("gpioWrite");
        exit(1);
    }
}

void sigintHandler(int sig) {
    cleanup();
    exit(0);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(gpioInitialise()));
        exit(1);
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetPullUpDnControl(PIR_GPIO, PI_PUD_DOWN) != 0) {
        perror("gpioSetPullUpDnControl");
        gpioTerminate();
        exit(1);
    }
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, sigintHandler);

    time_t lastPoll = 0;
    while (1) {
        time_t now = time(NULL);
        if (now - lastPoll >= 0.05) {
            lastPoll = now;
            if (gpioRead(PIR_GPIO) != 0) {
                gpioEdgeDetect(PIR_GPIO, RISING_EDGE, handleMotion);
            }
        }
        usleep(50000);
    }

    cleanup();
    return 0;
}

