    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        perror("gpioSetMode");
        gpioTerminate();
        exit(1);
    }

    signal(SIGINT, sigintHandler);

    time_t lastPoll = 0;
    while (1) {
        time_t now = time(NULL);
        if (now - lastPoll >= 0.05) {
            lastPoll = now;
            if (gpioRead(PIR_GPIO) != 0) {
                gpioEdgeDetect(PIR_GPIO, RISING_EDGE, handleMotion);
            }
        }
        usleep(50000);
    }

    cleanup();
    return 0;
}
