    volatile sig_atomic_t *shutdown = (volatile sig_atomic_t *)0;
    *shutdown = 1;
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize GPIO library\n");
        return 1;
    }

    // Set the GPIO mode for the motor pins
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) < 0 || gpioSetMode(MOTOR2_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the random number generator
    srand(time(NULL));

    // Create a volatile sig_atomic_t to track the shutdown flag
    volatile sig_atomic_t shutdown = 0;

    // Register the SIGINT handler
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!shutdown) {
        // Generate a random pattern
        int num_steps = rand() % (MAX_PATTERN_STEPS - 4) + 5; // Ensure at least 5 steps
        int pattern[MAX_PATTERN_STEPS];
        for (int i = 0; i < num_steps; i++) {
            pattern[i] = rand() % (MAX_DUTY_CYCLE + 1);
        }

        // Play the pattern
        for (int i = 0; i < num_steps; i++) {
            // Set the PWM duty cycle for each motor
            if (gpioPWM(MOTOR1_PIN, pattern[i]) < 0 || gpioPWM(MOTOR2_PIN, pattern[i]) < 0) {
                fprintf(stderr, "Failed to set PWM duty cycle\n");
                gpioTerminate();
                return 1;
            }

            // Wait for the step duration
            int duration = rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION) + MIN_STEP_DURATION;
            if (gpioDelay(duration * 1000) < 0) {
                fprintf(stderr, "Failed to wait for step duration\n");
                gpioTerminate();
                return 1;
            }

            // Clear the PWM duty cycle for each motor
            if (gpioPWM(MOTOR1_PIN, 0) < 0 || gpioPWM(MOTOR2_PIN, 0) < 0) {
                fprintf(stderr, "Failed to clear PWM duty cycle\n");
                gpioTerminate();
                return 1;
            }
        }
    }

    // Release resources and terminate the GPIO library
    gpioTerminate();

    return 0;
}

