#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define CALIBRATION_FILE "calibration.txt"
#define SCALE_PIN 4
#define CLOCK_PIN 17
#define LOCK_PIN 27
#define THRESHOLD 10.0
#define READ_TIMEOUT 0.5
#define CALIBRATION_READINGS 100

static volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(SCALE_PIN, PI_INPUT) < 0 || gpioSetMode(CLOCK_PIN, PI_ALT0) < 0 || gpioSetMode(LOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set up GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Load calibration data
    float scale_factor = 1.0;
    float offset = 0.0;
    FILE *calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file != NULL) {
        char buffer[1024];
        if (fgets(buffer, sizeof(buffer), calibration_file) != NULL) {
            char *endptr;
            scale_factor = strtof(buffer, &endptr);
            if (*endptr == ' ') {
                endptr++;
                offset = strtof(endptr, NULL);
            }
        }
        fclose(calibration_file);
    }

    // Perform one-time startup calibration
    float sum = 0.0;
    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        int raw_value = gpioRead(SCALE_PIN);
        sum += raw_value;
        usleep(500000); // 500 ms
    }
    offset = -sum / CALIBRATION_READINGS;
    scale_factor = 1.0; // HX711 is usually calibrated to 1.0
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file != NULL) {
        fprintf(calibration_file, "%.6f %.6f\n", scale_factor, offset);
        fclose(calibration_file);
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (running) {
        int raw_value;
        struct timeval timeout;
        timeout.tv_sec = (int)READ_TIMEOUT;
        timeout.tv_usec = (int)((READ_TIMEOUT - (int)READ_TIMEOUT) * 1000000);
        if (gpioReadTimeout(SCALE_PIN, &raw_value, &timeout) < 0) {
            continue;
        }
        float weight = (raw_value + offset) * scale_factor;
        if (weight > THRESHOLD) {
            gpioWrite(LOCK_PIN, 1);
        } else {
            gpioWrite(LOCK_PIN, 0);
        }
        FILE *log_file = fopen("weight_log.txt", "a");
        if (log_file != NULL) {
            fprintf(log_file, "%.6f\n", weight);
            fclose(log_file);
        }
        usleep(500000); // 500 ms
    }

    // Clean up
    gpioWrite(LOCK_PIN, 0);
    gpioTerminate();
    return 0;
}

