        syslog(LOG_ERR, "Failed to stop PWM");
        exit(1);
    }
}

void check_rain() {
    int readings[RAIN_DEBOUNCE_READINGS];
    int low_count = 0;
    for (int i = 0; i < RAIN_DEBOUNCE_READINGS; i++) {
        if (gpioRead(RAIN_SENSOR_GPIO) == 0) {
            low_count++;
        }
        sleep(RAIN_DEBOUNCE_INTERVAL / 1000.0);
    }
    if (low_count >= RAIN_DEBOUNCE_THRESHOLD) {
        syslog(LOG_INFO, "Rain detected");
        close_window();
    }
}

