        syslog(LOG_ERR, "Failed to open log");
        gpioTerminate();
        exit(1);
    }
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);
    while (running) {
        check_rain();
        sleep(60);
    }
    closelog();
    gpioTerminate();
    return 0;
}

