#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <syslog.h>
#include <time.h>

#define WEIGHT_THRESHOLD 100  // g
#define LOCK_DURATION 5000  // ms
#define LOG_FILE "stock_events.txt"

// Function to handle signal interrupts
void sigint_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", sig);
    gpioTerminate();
    exit(0);
}

// Function to read weight from HX711
float read_weight(int dt_gpio, int sck_gpio) {
    int status;
    float weight;

    // Initialize HX711
    status = gpioInitialise();
    if (status < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %d", status);
        return -1.0f;
    }

    // Set up GPIO pins
    gpioSetMode(dt_gpio, PI_INPUT);
    gpioSetMode(sck_gpio, PI_OUTPUT);
    gpioWrite(sck_gpio, 0);

    // Read weight
    status = gpioRead(dt_gpio);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to read DT line: %d", status);
        gpioTerminate();
        return -1.0f;
    }

    // Pulse clock 24 times
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_gpio, 1);
        usleep(1);
        gpioWrite(sck_gpio, 0);
        usleep(1);
    }

    // Read 24 bits
    float sum = 0.0f;
    for (int i = 0; i < 24; i++) {
        gpioWrite(sck_gpio, 1);
        usleep(1);
        int bit = gpioRead(dt_gpio);
        gpioWrite(sck_gpio, 0);
        usleep(1);
        sum += bit * pow(2, 23 - i);
    }

    // Check for data-line-stuck-high condition
    if (sum > 8000000) {
        syslog(LOG_ERR, "Data line stuck high");
        gpioTerminate();
        return -1.0f;
    }

    // Check for timeout condition
    if (gettimeofday(NULL, NULL) == -1) {
        syslog(LOG_ERR, "Failed to get current time");
        gpioTerminate();
        return -1.0f;
    }

    // Calculate weight
    weight = sum / 8192.0f;

    // Clean up
    gpioTerminate();

    return weight;
}

int main() {
    // Initialize GPIO and logging
    int status = gpioInitialise();
    if (status < 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO: %d", status);
        return 1;
    }

    openlog("stock_monitor", LOG_PID | LOG_PERROR, LOG_USER);

    // Set up GPIO pins
    int dt_gpio = 23;
    int sck_gpio = 24;
    int lock_gpio = 17;
    gpioSetMode(dt_gpio, PI_INPUT);
    gpioSetMode(sck_gpio, PI_OUTPUT);
    gpioSetMode(lock_gpio, PI_OUTPUT);
    gpioWrite(lock_gpio, 0);

    // Main loop
    while (1) {
        // Read weight
        float weight = read_weight(dt_gpio, sck_gpio);
        if (weight < 0.0f) {
            syslog(LOG_ERR, "Failed to read weight");
            continue;
        }

        // Check if weight is below threshold
        if (weight < WEIGHT_THRESHOLD) {
            syslog(LOG_INFO, "Weight below threshold: %f g", weight);
            // Activate solenoid lock
            gpioWrite(lock_gpio, 1);
