#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define LOCK_GPIO 27
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define CALIBRATION_WEIGHT 1.0  // in kg
#define WEIGHT_THRESHOLD 5.0  // in kg
#define CLOCK_HIGH_DELAY_US 1
#define CLOCK_LOW_DELAY_US 1
#define MAX_READ_ATTEMPTS 10

// Function to read a 24-bit signed value from the HX711
int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int attempts = 0;

    while (attempts < MAX_READ_ATTEMPTS) {
        // Send clock pulses
        gpioWrite(clock_pin, 1);
        usleep(CLOCK_HIGH_DELAY_US * 1000);
        gpioWrite(clock_pin, 0);
        usleep(CLOCK_LOW_DELAY_US * 1000);

        // Read data bits
        for (int i = 0; i < 24; i++) {
            int bit = gpioRead(data_pin);
            if (i < 23) {
                value = (value << 1) | bit;
            } else {
                value = (value << 1) | (bit & 0x01);
            }
            gpioWrite(clock_pin, 1);
            usleep(CLOCK_HIGH_DELAY_US * 1000);
            gpioWrite(clock_pin, 0);
            usleep(CLOCK_LOW_DELAY_US * 1000);
        }

        // Check for timeout
        if (attempts > 0 && gpioRead(data_pin) == 1) {
            return -1;  // Timeout
        }

        attempts++;
    }

    return value;
}

// Function to calibrate the load cell
void calibrate_load_cell() {
    int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
    if (raw_value == -1) {
        fprintf(stderr, "Error reading load cell during calibration\n");
        exit(1);
    }

    double calibration_factor = (double)raw_value / CALIBRATION_WEIGHT;
    FILE *file = fopen(CALIBRATION_FILE, "w");
    if (file == NULL) {
        fprintf(stderr, "Error opening calibration file for writing\n");
        exit(1);
    }
    fprintf(file, "%f\n", calibration_factor);
    fclose(file);
}

// Function to read the current weight
double read_weight() {
    int raw_value = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
    if (raw_value == -1) {
        return -1.0;  // Timeout
    }

    double calibration_factor;
    FILE *file = fopen(CALIBRATION_FILE, "r");
    if (file == NULL) {
        fprintf(stderr, "Error opening calibration file for reading\n");
        exit(1);
    }
    fscanf(file, "%lf", &calibration_factor);
    fclose(file);

    return (double)raw_value / calibration_factor;
}

// Function to log a weight event
void log_weight_event(double weight) {
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file for writing\n");
        exit(1);
    }
    fprintf(file, "%s: Weight exceeded %f kg\n", timestamp, weight);
    fclose(file);
}

// Signal handler to unlock the solenoid and terminate pigpio
void sigint_handler(int sig) {
    gpioWrite(LOCK_GPIO, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        exit(1);
    }

    // Set up signal handler
    signal(SIGINT, sigint_handler);

    // Calibrate the load cell
    calibrate_load_cell();

    // Set up GPIO pins
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_GPIO, PI_OUTPUT);
    gpioWrite(LOCK_GPIO, 0);

    // Main loop
    while (1) {
        double weight = read_weight();
        if (weight == -1.0) {
            // Timeout, try again
            continue;
        }

        if (weight > WEIGHT_THRESHOLD) {
            log_weight_event(weight);
            gpioWrite(LOCK_GPIO, 1);
            usleep(5000000);  // 5 seconds
            gpioWrite(LOCK_GPIO, 0);
        }

        usleep(100000);  // 100 ms
    }

    // Clean up
    gpioTerminate();
    return 0;
}

