#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>

#define GPIO_CHIP_NAME "/dev/gpiochip0"
#define GPIO_SENSOR_LINE 16
#define GPIO_RELAY_LINE 20
#define RELAY_LOG_FILE "relay_events.log"

static bool relay_on = false;

static void sigint_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open_by_name(GPIO_CHIP_NAME));
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open_by_name(GPIO_CHIP_NAME), GPIO_SENSOR_LINE));
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open_by_name(GPIO_CHIP_NAME), GPIO_RELAY_LINE));
    exit(0);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    gpiod_chip_t *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        exit(1);
    }

    gpiod_line_t *sensor_line = gpiod_chip_get_line(chip, GPIO_SENSOR_LINE);
    if (!sensor_line) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        exit(1);
    }

    gpiod_line_t *relay_line = gpiod_chip_get_line(chip, GPIO_RELAY_LINE);
    if (!relay_line) {
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        exit(1);
    }

    if (gpiod_line_request_bulk(chip, sensor_line, GPIOD_LINE_REQUEST_INPUT) == -1) {
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_bulk");
        exit(1);
    }

    if (gpiod_line_request_bulk(chip, relay_line, GPIOD_LINE_REQUEST_OUTPUT) == -1) {
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_bulk");
        exit(1);
    }

    FILE *log_file = fopen(RELAY_LOG_FILE, "a");
    if (!log_file) {
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        perror("fopen");
        exit(1);
    }

    while (1) {
        int sensor_value = gpiod_line_get_value(sensor_line);
        if (sensor_value == -1) {
            gpiod_line_release(sensor_line);
            gpiod_line_release(relay_line);
            gpiod_chip_close(chip);
            fclose(log_file);
            perror("gpiod_line_get_value");
            exit(1);
        }

        if (sensor_value == 0) {
            relay_on = !relay_on;
            gpiod_line_set_value(relay_line, relay_on);
            char timestamp[32];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", localtime(&now));
            fprintf(log_file, "%s: Relay %s\n", timestamp, relay_on ? "ON" : "OFF");
            fflush(log_file);
        }

        usleep(100000); // 100ms
    }

    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);
    fclose(log_file);
    return 0;
}

