#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/time.h>
#include <gpiod.h>
#include <signal.h>

// Define constants
#define PIR_SENSOR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "motion_log.txt"

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Turn off the buzzer
    gpiod_line_set_value(gpiod, BUZZER_GPIO, 0);
    // Close the log file
    fclose(log_file);
    // Release GPIO resources
    gpiod_line_release(gpiod, PIR_SENSOR_GPIO);
    gpiod_line_release(gpiod, BUZZER_GPIO);
    gpiod_chip_close(gpiod);
    // Exit cleanly
    exit(0);
}

int main() {
    // Initialize log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }

    // Install SIGINT and SIGTERM handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    // Open the GPIO chip
    gpiod_chip *gpiod = gpiod_chip_open("/dev/gpiochip0");
    if (!gpiod) {
        fprintf(stderr, "Error opening GPIO chip\n");
        fclose(log_file);
        return 1;
    }

    // Request the PIR sensor line as an input
    int ret = gpiod_line_request_input(gpiod, PIR_SENSOR_GPIO, "active-high");
    if (ret != 0) {
        fprintf(stderr, "Error requesting PIR sensor line: %d\n", ret);
        gpiod_chip_close(gpiod);
        fclose(log_file);
        return 1;
    }

    // Request the buzzer line as an output
    ret = gpiod_line_request_output(gpiod, BUZZER_GPIO, "active-high");
    if (ret != 0) {
        fprintf(stderr, "Error requesting buzzer line: %d\n", ret);
