#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 18
#define CONFIG_FILE "watering.conf"

volatile sig_atomic_t exit_flag = 0;

void sig_handler(int sig) {
    exit_flag = 1;
}

int main() {
    gpiod_chip *chip;
    gpiod_line *line;
    int duration;
    char line_str[256];

    // Initialize signal handlers
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sa.sa_flags = SA_RESTART;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip '%s': %s\n", GPIO_CHIP, gpiod_error_str(errno));
        return EXIT_FAILURE;
    }

    // Open the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_LINE, gpiod_error_str(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line as output with active-low set to 0
    if (gpiod_line_request_output(line, 0, 0) == -1) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_LINE, gpiod_error_str(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Read the watering duration from the configuration file
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (!config_file) {
        fprintf(stderr, "Failed to open configuration file '%s': %s\n", CONFIG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (fgets(line_str, sizeof(line_str), config_file) == NULL) {
        fprintf(stderr, "Configuration file '%s' is empty\n", CONFIG_FILE);
        fclose(config_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (sscanf(line_str, "duration=%d", &duration) != 1) {
        fprintf(stderr, "Malformed configuration line in '%s'\n", CONFIG_FILE);
        fclose(config_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (duration < 1 || duration > 3600) {
        fprintf(stderr, "Invalid duration in '%s': must be between 1 and 3600\n", CONFIG_FILE);
        fclose(config_file);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fclose(config_file);

    // Activate the valve
    if (gpiod_line_set_value(line, 1) == -1) {
        fprintf(stderr, "Failed to set GPIO line %d high: %s\n", GPIO_LINE, gpiod_error_str(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Valve on for %d seconds\n", duration);

    // Wait for the configured duration
    while (!exit_flag && duration > 0) {
        sleep(1);
        duration--;
        printf("Time remaining: %d seconds\n", duration);
    }

    // Deactivate the valve
    if (gpiod_line_set_value(line, 0) == -1) {
        fprintf(stderr, "Failed to set GPIO line %d low: %s\n", GPIO_LINE, gpiod_error_str(errno));
    }

    printf("Valve off\n");

    // Release the GPIO line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

