#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>

#define LOG_FILE "trace_log.txt"
#define BASE_SPEED 150
#define PWM_FREQ 1000
#define PWM_RANGE 255

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", gpioErrorStr(gpioError()));
        return 1;
    }

    // Set up GPIOs for sensors and motors
    int sensors[] = {4, 17, 27};
    int motors[] = {22, 23, 24, 25};
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(motors[i], PI_PWM) < 0) {
            fprintf(stderr, "Failed to set mode for motor GPIO %d: %s\n", motors[i], gpioErrorStr(gpioError()));
            gpioTerminate();
            return 1;
        }
        if (gpioSetPWM(motors[i], 0, PWM_FREQ) < 0) {
            fprintf(stderr, "Failed to set PWM for motor GPIO %d: %s\n", motors[i], gpioErrorStr(gpioError()));
            gpioTerminate();
            return 1;
        }
    }
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(sensors[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set mode for sensor GPIO %d: %s\n", sensors[i], gpioErrorStr(gpioError()));
            gpioTerminate();
            return 1;
        }
    }

    // Open log file
    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor states
        int sensor_states[3];
        for (int i = 0; i < 3; i++) {
            sensor_states[i] = gpioRead(sensors[i]);
        }

        // Apply control law
        int left_speed = 0;
        int right_speed = 0;
        if (sensor_states[1] == 0) { // Middle sensor reads low
            left_speed = right_speed = BASE_SPEED;
        } else if (sensor_states[0] == 0) { // Only left sensor reads low
            left_speed = BASE_SPEED / 2;
            right_speed = BASE_SPEED;
        } else if (sensor_states[2] == 0) { // Only right sensor reads low
            left_speed = BASE_SPEED;
            right_speed = BASE_SPEED / 2;
        } else { // No sensor reads low
            left_speed = right_speed = 0;
        }

        // Log control cycle
        time_t now = time(NULL);
        struct tm *timestamp = localtime(&now);
        char log_line[256];
        sprintf(log_line, "%04d-%02d-%02d %02d:%02d:%02d %d %d %d %d\n",
                timestamp->tm_year + 1900, timestamp->tm_mon + 1, timestamp->tm_mday,
                timestamp->tm_hour, timestamp->tm_min, timestamp->tm_sec,
                sensor_states[0], sensor_states[1], sensor_states[2], left_speed, right_speed);
        fwrite(log_line, 1, strlen(log_line), log_file);

        // Set motor speeds
        gpioPWM(motors[0], left_speed);
        gpioPWM(motors[1], right_speed);
        gpioPWM(motors[2], left_speed);
        gpioPWM(motors[3], right_speed);

        // Sleep for 10 ms
        usleep(10000);
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    return 0;
}

// Signal handler for SIGINT
void sigint_handler(int sig) {
    // Stop motors
    gpioPWM(22, 0);
    gpioPWM(23, 0);
    gpioPWM(24, 0);
    gpioPWM(25, 0);

    // Close log file
    fclose(fopen(LOG_FILE, "w"));

    // Terminate pigpio
    gpioTerminate();

    // Exit
    exit(0);
}

// Register SIGINT handler
void setup_sigint_handler() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up SIGINT handler: %s\n", strerror(errno));
        exit(1);
    }
}

