#define RELAY_GPIO 23
#define I2C_BUS 1
#define I2C_ADDRESS 0x23
#define MEASUREMENT_DELAY 180
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

volatile bool running = true;

void sigint_handler(int sig) {
    running = false;
}

void log_event(const char *event, int lux, bool relay_on) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("fopen");
        return;
    }

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%03d", localtime(&time(NULL)));
    fprintf(file, "%s %s lux=%d relay=%d\n", timestamp, event, lux, relay_on);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        perror("gpioInitialise");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        perror("gpioSetMode");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDnControl(RELAY_GPIO, PI_PUD_UP) < 0) {
        perror("gpioSetPullUpDnControl");
        gpioTerminate();
        return 1;
    }

    int i2c_fd = open("/dev/i2c-" I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open");
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("ioctl");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int lux = 0;
    bool relay_on = false;

    signal(SIGINT, sigint_handler);

    while (running) {
        if (i2c_write(i2c_fd, 0x10, 1) < 0) {
            perror("i2c_write");
            log_event("I2C write error", lux, relay_on);
            continue;
        }

        usleep(MEASUREMENT_DELAY * 1000);

        uint8_t data[2];
        if (i2c_read(i2c_fd, data, 2) < 0) {
            perror("i2c_read");
            log_event("I2C read error", lux, relay_on);
            continue;
        }

        lux = (data[0] << 8) | data[1];

        if (lux < LUX_THRESHOLD) {
            if (!relay_on) {
                log_event("Relay on", lux, true);
                gpioWrite(RELAY_GPIO, 1);
                relay_on = true;
            }
        } else {
            if (relay_on) {
                log_event("Relay off", lux, false);
                gpioWrite(RELAY_GPIO, 0);
                relay_on = false;
            }
        }

        log_event("Reading", lux, relay_on);
    }

    gpioWrite(RELAY_GPIO, 0);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}
