        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDnControl(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set unlock button pull-up control\n");
        gpioTerminate();
