            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                // Move the servo to the unlocked position
                if (gpioHardwarePWM(SERVO_PIN, UNLOCKED_PULSE_WIDTH) < 0) {
                    fprintf(stderr, "Failed to set servo pulse width\n");
                }
            }
        }

        // Limit the servo pulse width to the safe range
        int pulse_width = gpioGetHardwarePWM(SERVO_PIN);
        if (pulse_width < MIN_PULSE_WIDTH) {
            gpioHardwarePWM(SERVO_PIN, MIN_PULSE_WIDTH);
        } else if (pulse_width > MAX_PULSE_WIDTH) {
            gpioHardwarePWM(SERVO_PIN, MAX_PULSE_WIDTH);
        }

        // Sleep for a short period
        sleep(0.1);
    }

    return 0;
