// GPIO line numbers for motor 1 and motor 2
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// GPIO line numbers for driver enable and disable
#define DRIVER_ENABLE_GPIO 23
#define DRIVER_DISABLE_GPIO 24

// Signal handler function to stop motors and release GPIO lines
void signal_handler(int sig) {
    gpiod_line_release(MOTOR1_GPIO);
    gpiod_line_release(MOTOR2_GPIO);
    gpiod_line_release(DRIVER_ENABLE_GPIO);
    gpiod_line_release(DRIVER_DISABLE_GPIO);
    exit(0);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(1);
    }

    // Initialize GPIO lines
    struct gpiod_line *motor1_line, *motor2_line, *driver_enable_line, *driver_disable_line;
    motor1_line = gpiod_line_request_output("gpiochip0", MOTOR1_GPIO, GPIOD_LINE_ACTIVE_LOW);
    if (!motor1_line) {
        perror("gpiod_line_request_output");
        exit(1);
    }
    motor2_line = gpiod_line_request_output("gpiochip0", MOTOR2_GPIO, GPIOD_LINE_ACTIVE_LOW);
    if (!motor2_line) {
        gpiod_line_release(motor1_line);
        perror("gpiod_line_request_output");
        exit(1);
    }
    driver_enable_line = gpiod_line_request_output("gpiochip0", DRIVER_ENABLE_GPIO, GPIOD_LINE_ACTIVE_LOW);
