        gpiod_line_release(motor1_line);
        gpiod_line_release(motor2_line);
        perror("gpiod_line_request_output");
        exit(1);
    }
    driver_disable_line = gpiod_line_request_output("gpiochip0", DRIVER_DISABLE_GPIO, GPIOD_LINE_ACTIVE_LOW);
