            gpiod_line_release(driver_enable_line);
            gpiod_line_release(driver_disable_line);
            perror("gpiod_line_set_value");
            exit(1);
        }
        usleep(300000);
        if (gpiod_line_set_value(motor2_line, 0) == -1) {
