            gpiod_line_release(motor2_line);
            gpiod_line_release(driver_enable_line);
            gpiod_line_release(driver_disable_line);
            perror("gpiod_line_set_value");
            exit(1);
        }
    }

    // Release GPIO lines on exit
    gpiod_line_release(motor1_line);
    gpiod_line_release(motor2_line);
    gpiod_line_release(driver_enable_line);
    gpiod_line_release(driver_disable_line);
    return 0;
