#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>
#include <sys/select.h>
#include <gpiod.h>
#include <czmq.h>

#define GPIO17 17
#define GPIO27 27
#define SOUND_SENSOR_MODE "sound_sensor"
#define ALARM_NODE_MODE "alarm_node"
#define SOUND_ALERTS "SOUND_ALERTS"
#define SLEEP_TIME 10 // ms
#define ALARM_DURATION 1000 // ms

void signal_handler(int sig) {
    gpiod_chip_close(gpiod_chip_open("/dev/gpiochip0"));
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), GPIO17));
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open("/dev/gpiochip0"), GPIO27));
    zctx_destroy(&ctx);
    exit(0);
}

int main(int argc, char **argv) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    char *mode = NULL;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], SOUND_SENSOR_MODE) == 0 || strcmp(argv[i], ALARM_NODE_MODE) == 0) {
            mode = argv[i];
            break;
        }
    }
    if (mode == NULL) {
        fprintf(stderr, "Usage: %s %s or %s\n", argv[0], SOUND_SENSOR_MODE, ALARM_NODE_MODE);
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open");
        return 1;
    }

    struct gpiod_line *sound_sensor = gpiod_chip_get_line(chip, GPIO17);
    if (sound_sensor == NULL) {
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        return 1;
    }
    if (gpiod_line_request_output(sound_sensor, 0) == -1) {
        gpiod_line_release(sound_sensor);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_output");
        return 1;
    }

    struct gpiod_line *alarm_led = gpiod_chip_get_line(chip, GPIO27);
    if (alarm_led == NULL) {
        gpiod_line_release(sound_sensor);
        gpiod_chip_close(chip);
        perror("gpiod_chip_get_line");
        return 1;
    }
    if (gpiod_line_request_output(alarm_led, 0) == -1) {
        gpiod_line_release(sound_sensor);
        gpiod_line_release(alarm_led);
        gpiod_chip_close(chip);
        perror("gpiod_line_request_output");
        return 1;
    }

    zctx_t *ctx = zctx_new();
    if (ctx == NULL) {
        gpiod_line_release(sound_sensor);
        gpiod_line_release(alarm_led);
        gpiod_chip_close(chip);
        perror("zctx_new");
        return 1;
    }

    zsock_t *pub = zsock_new(ZMQ_PUB);
    if (pub == NULL) {
        zctx_destroy(ctx);
        gpiod_line_release(sound_sensor);
        gpiod_line_release(alarm_led);
        gpiod_chip_close(chip);
        perror("zsock_new");
        return 1;
    }

    if (strcmp(mode, SOUND_SENSOR_MODE) == 0) {
        zsock_bind(pub, "tcp://*:5555");
        while (1) {
            struct timeval tv;
            tv.tv_sec = 0;
            tv.tv_usec = SLEEP_TIME * 1000;
            fd_set read_fds;
            FD_ZERO(&read_fds);
            FD_SET(fileno(pub), &read_fds);
            if (select(fileno(pub), &read_fds, NULL, NULL, &tv) == -1) {
                perror("select");
                break;
            }
