#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <paho-mqtt/mqtt.h>

#define GPIO_IR_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"

// Structure to hold the decoded NEC frame
typedef struct {
    uint32_t address;
    uint32_t command;
} nec_frame;

// Structure to hold the current pulse timings
typedef struct {
    uint32_t mark_start;
    uint32_t space_start;
    uint32_t mark_count;
    uint32_t space_count;
} pulse_timings;

// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    syslog(LOG_INFO, "Received signal %d, exiting...", sig);
    gpioTerminate();
    syslog(LOG_INFO, "Released pigpio resources");
    mqtt_client_destroy();
    syslog(LOG_INFO, "Released MQTT client");
    syslog(LOG_INFO, "Exiting...");
    exit(0);
}

// Function to handle the pigpio alert callback
void gpio_alert(int gpio, int level, uint32_t tick) {
    static pulse_timings pulse;
    static uint32_t pulse_buffer[10];
    static int pulse_index = 0;

    // Check if the pulse buffer is full
    if (pulse_index >= sizeof(pulse_buffer) / sizeof(pulse_buffer[0])) {
        syslog(LOG_ERR, "Pulse buffer overflow");
        return;
    }

    // Store the pulse timings
    if (level == 1) {
        pulse.mark_start = tick;
        pulse.mark_count = 0;
    } else {
        pulse.space_start = tick;
        pulse.space_count = 0;
    }

    // Check if we have a complete mark or space
    if (pulse.mark_start != 0 && tick - pulse.mark_start >= 560000) {
        pulse.mark_count++;
        pulse.mark_start = 0;
    }
    if (pulse.space_start != 0 && tick - pulse.space_start >= 1690000) {
        pulse.space_count++;
        pulse.space_start = 0;
    }

    // Check if we have a complete frame
    if (pulse.mark_count == 32 && pulse.space_count == 32) {
        // Decode the NEC frame
        uint32_t address = 0;
        uint32_t command = 0;
        for (int i = 0; i < 32; i++) {
            if (pulse_buffer[i] == 1) {
                address |= 1 << (31 - i);
            }
            if (pulse_buffer[i + 32] == 1) {
                command |= 1 << (31 - i);
            }
        }

        // Validate the decoded command against its inverted copy
        uint32_t inverted_command = 0;
        for (int i = 0; i < 32; i++) {
            inverted_command |= (1 << (31 - i)) ^ (command >> i & 1);
        }
        if (address != (address ^ inverted_command)) {
            syslog(LOG_ERR, "Invalid command");
            return;
        }

        // Validate the NEC checksum
        if ((address >> 8) != (address & 0xFF)) {
            syslog(LOG_ERR, "Invalid checksum");
            return;
        }

        // Publish the decoded command as JSON to the MQTT broker
        char json[256];
        sprintf(json, "{\"address\": %u, \"command\": %u}", address, command);
        mqtt_publish(MQTT_TOPIC, json, strlen(json), 0, 0);

        // Log the decoded command to syslog
        syslog(LOG_INFO, "Decoded command: address=%u, command=%u", address, command);

        // Reset the pulse timings
        pulse.mark_start = 0;
        pulse.space_start = 0;
        pulse.mark_count = 0;
        pulse.space_count = 0;
        pulse_index = 0;
    } else {
        // Store the pulse timings in the buffer
        pulse_buffer[pulse_index++] = pulse.mark_count;
        pulse_buffer[pulse_index++] = pulse.space_count;
    }
}

int main() {
    // Initialize the syslog
    openlog(NULL, LOG_PID | LOG_PERROR, LOG_USER);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio");
        exit(1);
    }

    // Set up the GPIO pin as an input
    if (gpioSetMode(GPIO_IR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set up GPIO pin");
        gpioTerminate();
        exit(1);
    }

    // Register the pigpio alert callback
    if (gpioSetAlertFunc(GPIO_IR_PIN, gpio_alert) < 0) {
        syslog(LOG_ERR, "Failed to register alert callback");
        gpioTerminate();
        exit(1);
    }

    // Initialize the MQTT client
    mqtt_client_t *client = mqtt_client_create();
    if (client == NULL) {
        syslog(LOG_ERR, "Failed to create MQTT client");
        gpioTerminate();
        exit(1);
    }

    // Connect to the MQTT broker
    if (mqtt_client_connect(client, MQTT_BROKER, MQTT_PORT, 60, NULL, NULL, NULL) != MQTT_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker");
        mqtt_client_destroy(client);
        gpioTerminate();
        exit(1);
    }

    // Set up the MQTT publish callback
    mqtt_client_set_callback(client, NULL, NULL, NULL, NULL);

    // Main loop
    while (1) {
        // Service the MQTT network loop
        mqtt_client_loop(client, 1000);
    }

    // Cleanly release resources on exit
    return 0;
}

