#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR_1 0x23
#define I2C_ADDR_2 0x24
#define I2C_ADDR_3 0x25
#define I2C_ADDR_4 0x26
#define UDP_PORT 5005
#define UDP_GROUP "239.255.255.250"
#define UDP_ADDR "0.0.0.0"
#define BUFFER_SIZE 1024
#define SLEEP_TIME 1000

int i2c_fd[4] = {-1, -1, -1, -1};
int udp_fd = -1;
int exit_flag = 0;

void sigint_handler(int sig) {
    exit_flag = 1;
}

int i2c_open(int addr) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("i2c_open");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("i2c_set_slave");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_read(int fd, uint8_t *data) {
    int ret = read(fd, data, 2);
    if (ret != 2) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int main() {
    struct sockaddr_in udp_addr;
    struct iovec iov;
    char buffer[BUFFER_SIZE];
    char *ptr = buffer;
    int i;

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    for (i = 0; i < 4; i++) {
        i2c_fd[i] = i2c_open((i == 0) ? I2C_ADDR_1 : (i == 1) ? I2C_ADDR_2 : (i == 2) ? I2C_ADDR_3 : I2C_ADDR_4);
        if (i2c_fd[i] < 0) {
            perror("i2c_open");
            exit(1);
        }
    }

    udp_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_fd < 0) {
        perror("socket");
        exit(1);
    }

    memset(&udp_addr, 0, sizeof(udp_addr));
    udp_addr.sin_family = AF_INET;
    inet_pton(AF_INET, UDP_GROUP, &udp_addr.sin_addr);
    udp_addr.sin_port = htons(UDP_PORT);

    while (!exit_flag) {
        for (i = 0; i < 4; i++) {
            uint8_t data[2];
            int ret;

            ret = i2c_write(i2c_fd[i], 0x20);
            if (ret < 0) {
                fprintf(stderr, "Error writing to sensor %d\n", i + 1);
                continue;
            }

            usleep(180000);

            ret = i2c_read(i2c_fd[i], data);
            if (ret < 0) {
                fprintf(stderr, "Error reading from sensor %d\n", i + 1);
                continue;
            }

            double lux = ((data[0] << 8) | data[1]) / 1.2;
            if (lux == 0) {
                fprintf(stderr, "Error calculating lux for sensor %d\n", i + 1);
                continue;
            }

            ptr += sprintf(ptr, "%d,%f;", i + 1, lux);
        }

        iov.iov_base = buffer;
        iov.iov_len = strlen(buffer);
        sendto(udp_fd, buffer, iov.iov_len, 0, (struct sockaddr *)&udp_addr, sizeof(udp_addr));
        memset(buffer, 0, BUFFER_SIZE);

        for (i = 0; i < 4; i++) {
            close(i2c_fd[i]);
            i2c_fd[i] = -1;
        }

        usleep(SLEEP_TIME);
    }

    for (i = 0; i < 4; i++) {
        if (i2c_fd[i] != -1) {
            close(i2c_fd[i]);
        }
    }

    close(udp_fd);

    return 0;
}

int i2c_write(int fd, uint8_t data) {
    int ret = write(fd, &data, 1);
    if (ret != 1) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

