int i2c_read(int fd, uint8_t reg, uint16_t *val) {
    struct i2c_msg msg[2];
    struct i2c_rdwr_ioctl_data i2c_data;
    int retries = 0;

    msg[0].addr = I2C_ADDR;
    msg[0].flags = 0;
    msg[0].len = 1;
    msg[0].buf = &reg;

    msg[1].addr = I2C_ADDR;
    msg[1].flags = I2C_M_RD;
    msg[1].len = 2;
    msg[1].buf = (uint8_t *)val;

    while (retries < 3) {
        i2c_data.msgs = msg;
        i2c_data.nmsgs = 2;
        if (ioctl(fd, I2C_RDWR, &i2c_data) == -1) {
            if (errno == ENXIO) {
                printf("Sensor absent, exiting...\n");
                return -1;
            } else if (errno == EIO) {
                printf("I2C bus error, retrying...\n");
                usleep(100000);
                retries++;
                continue;
            } else {
                printf("I2C read error: %s\n", strerror(errno));
                return -1;
            }
        }
        return 0;
    }
    printf("I2C read failed after 3 retries, exiting...\n");
    return -1;
}

int main() {
    int fd;
    uint16_t flow;
    FILE *log_file;

    signal(SIGINT, sigint_handler);

    fd = open(I2C_DEV, O_RDWR);
    if (fd == -1) {
        printf("Failed to open I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) == -1) {
        printf("Failed to set I2C address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        printf("Failed to open log file: %s\n", strerror(errno));
        close(fd);
        return 1;
    }

    while (running) {
        if (i2c_read(fd, AWM7300V_FLOW_REG, &flow) == -1) {
            break;
        }
        flow = (flow & AWM7300V_FLOW_MASK) - AWM7300V_FLOW_OFFSET;
        flow *= AWM7300V_FLOW_SCALE;
        fprintf(log_file, "%f\n", flow);
        fflush(log_file);
        usleep(1000000);
    }

    fclose(log_file);
    close(fd);
    return 0;
}

