#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x39
#define REG_WHO_AM_I 0x24
#define REG_ENABLE 0x80
#define REG_CFG6 0xAF
#define REG_SP_EN 0x01
#define REG_F1 0x60
#define REG_F2 0x61
#define REG_F3 0x62
#define REG_F4 0x63
#define REG_F5 0x64
#define REG_F6 0x65
#define REG_F7 0x66
#define REG_F8 0x67
#define REG_CLEAR 0x68
#define REG_NIR 0x69

#define LUX_A 0.0012929
#define LUX_B 0.0001246
#define LUX_C 0.000000056

int i2c_fd = -1;
FILE *log_file = NULL;

void cleanup(int sig) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    struct i2c_msg msg;
    struct i2c_rdwr_ioctl_data i2c_data;
    uint8_t buffer[10];
    uint16_t spectral_values[10];
    time_t start_time;
    struct tm *start_time_t;
    char timestamp[20];

    // Initialize signal handler for SIGINT
    signal(SIGINT, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C address");
        exit(1);
    }

    // Initialize sensor
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.buf = &REG_ENABLE;
    msg.len = 1;
    msg.buf[0] = 0x01; // Set PON bit to 1
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to set PON bit");
        exit(1);
    }

    // Verify WHO_AM_I register
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.buf = &REG_WHO_AM_I;
    msg.len = 1;
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to read WHO_AM_I register");
        exit(1);
    }
    if (buffer[0] != 0x19) {
        fprintf(stderr, "Invalid WHO_AM_I register value 0x%02x\n", buffer[0]);
        exit(1);
    }

    // Configure SMUX for spectral readings
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.buf = &REG_CFG6;
    msg.len = 1;
    msg.buf[0] = 0x80; // Set CFG6 to 0x80 for spectral readings
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to configure SMUX");
        exit(1);
    }

    // Enable spectral measurement
    msg.addr = I2C_ADDRESS;
    msg.flags = 0;
    msg.buf = &REG_SP_EN;
    msg.len = 1;
    msg.buf[0] = 0x01; // Set SP_EN bit to 1
    i2c_data.msgs = &msg;
    i2c_data.nmsgs = 1;
    if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
        perror("Failed to enable spectral measurement");
        exit(1);
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "w");
    if (log_file == NULL) {
        perror("Failed to open log file");
        exit(1);
    }

    // Main loop
    while (1) {
        // Read spectral values
        for (int i = 0; i < 10; i++) {
            msg.addr = I2C_ADDRESS;
            msg.flags = 0;
            msg.buf = &REG_F1 + i;
            msg.len = 1;
            i2c_data.msgs = &msg;
            i2c_data.nmsgs = 1;
            if (ioctl(i2c_fd, I2C_RDWR, &i2c_data) < 0) {
                perror("Failed to read spectral value");
                exit(1);
            }
            spectral_values[i] = (buffer[0] << 8) | buffer[1];
        }

        // Compute lux approximation
        uint32_t sum = 0;
        for (int i = 0; i < 8; i++) {
            sum += spectral_values[i];
        }
        uint32_t lux = (sum * LUX_A) + (spectral_values[8] * LUX_B) + (spectral_values[9] * LUX_C);

        // Log results
        time(&start_time);
        start_time_t = localtime(&start_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", start_time_t);
        fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d,%d\n",
                timestamp,
                spectral_values[0], spectral_values[1], spectral_values[2], spectral_values[3],
                spectral_values[4], spectral_values[5], spectral_values[6], spectral_values[7],
                spectral_values[8], spectral_values[9], (int)lux);
        fflush(log_file);

        // Sleep for 5 seconds
        usleep(5000000);
    }

    return 0;
}

