#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/select.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>

#define DEFAULT_I2C_ADDRESS 0x37
#define DEFAULT_INTERVAL 1
#define DEFAULT_OUTPUT_FILE "seismic_data.csv"

#define MAX_BACKOFF_ATTEMPTS 3
#define BACKOFF_INTERVAL_MS 10

#define LOG_FILE "seismic_error.log"

int i2c_fd = -1;
int output_fd = -1;
char output_filename[256];

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

void log_data(double x, double y, double z) {
    FILE *output_file = fopen(output_filename, "a");
    if (output_file) {
        fprintf(output_file, "%f,%f,%f\n", time(NULL), x, y);
        fclose(output_file);
    }
}

void read_acceleration() {
    uint8_t buffer[6];
    int attempts = 0;
    while (attempts < MAX_BACKOFF_ATTEMPTS) {
        if (ioctl(i2c_fd, I2C_SLAVE, DEFAULT_I2C_ADDRESS) < 0) {
            log_error("Failed to set I2C slave address");
            return;
        }
        if (i2c_smbus_read_byte_data(i2c_fd, 0x28) < 0) {
            log_error("Failed to read acceleration data");
            return;
        }
        if (i2c_smbus_read_i2c_block_data(i2c_fd, 0x28, 6, buffer) < 0) {
            log_error("Failed to read acceleration data");
            return;
        }
        int16_t x = (buffer[1] << 8) | buffer[0];
        int16_t y = (buffer[3] << 8) | buffer[2];
        int16_t z = (buffer[5] << 8) | buffer[4];
        double g = 0.000244 * (x | y | z);
        log_data(g, g, g);
        break;
    }
}

void sigint_handler(int signal) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (output_fd >= 0) {
        fclose(output_fd);
    }
    exit(0);
}

int main(int argc, char *argv[]) {
    int i2c_address = DEFAULT_I2C_ADDRESS;
    int interval = DEFAULT_INTERVAL;
    char *output_filename_copy = DEFAULT_OUTPUT_FILE;
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtoul(optarg, NULL, 0);
                break;
            case 'i':
                interval = atoi(optarg);
                break;
            case 'f':
                output_filename_copy = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_address>] [-i <interval>] [-f <output_filename>]\n", argv[0]);
                return 1;
        }
    }
    strcpy(output_filename, output_filename_copy);
    openlog("seismic", LOG_PID, LOG_USER);
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        return 1;
