#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_DEV "/dev/i2c-1"
#define I2C_ADDR 0x23
#define UDP_ADDR "239.255.255.250"
#define UDP_PORT 5000
#define UDP_TTL 1
#define LUX_GAIN 1.2

volatile int running = 1;

void cleanup(int sig) {
    running = 0;
}

int i2c_open() {
    int fd = open(I2C_DEV, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != len) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

int udp_socket() {
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("Failed to create UDP socket");
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    inet_pton(AF_INET, UDP_ADDR, &addr.sin_addr);
    addr.sin_port = htons(UDP_PORT);
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &UDP_TTL, sizeof(UDP_TTL)) < 0) {
        perror("Failed to set UDP TTL");
        close(sock);
        return -1;
    }
    return sock;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = cleanup;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    int i2c_fd = i2c_open();
    if (i2c_fd < 0) {
        return 1;
    }

    int udp_sock = udp_socket();
    if (udp_sock < 0) {
        close(i2c_fd);
        return 1;
    }

    uint8_t buf[2];
    while (running) {
        if (i2c_write(i2c_fd, "\x01", 1) < 0) {
            close(i2c_fd);
            close(udp_sock);
            return 1;
        }
        if (i2c_write(i2c_fd, "\x10", 1) < 0) {
            close(i2c_fd);
            close(udp_sock);
            return 1;
        }
        if (i2c_read(i2c_fd, buf, 2) < 0) {
            close(i2c_fd);
            close(udp_sock);
            return 1;
        }
        uint16_t lux_raw = (buf[0] << 8) | buf[1];
        float lux = (float)lux_raw / LUX_GAIN;
        char msg[32];
        sprintf(msg, "%.2f", lux);
        if (sendto(udp_sock, msg, strlen(msg), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
            perror("Failed to send UDP message");
            close(i2c_fd);
            close(udp_sock);
            return 1;
        }
        usleep(1000000);
    }

    close(i2c_fd);
    close(udp_sock);
    return 0;
}

