#define MAGIC_WORD 0x02040305 0x0708
#define CSV_FILE "radar_data.csv"

int uart_fd;
int csv_fd;
char csv_buf[1024];
int csv_len = 0;
bool csv_open = false;
bool uart_open = false;
bool running = true;

void uart_open_func() {
    uart_fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", strerror(errno));
        exit(1);
    }
    if (cfsetispeed(uart_fd, UART_BAUD) < 0) {
        fprintf(stderr, "Failed to set UART baudrate: %s\n", strerror(errno));
        exit(1);
    }
    if (cfsetospeed(uart_fd, UART_BAUD) < 0) {
        fprintf(stderr, "Failed to set UART baudrate: %s\n", strerror(errno));
        exit(1);
    }
    uart_open = true;
}

void csv_open_func() {
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (csv_fd < 0) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        exit(1);
    }
    csv_open = true;
}

void csv_write_func(const char *data, int len) {
    if (write(csv_fd, data, len) < 0) {
        fprintf(stderr, "Failed to write to CSV file: %s\n", strerror(errno));
        exit(1);
    }
}

void csv_close_func() {
    if (close(csv_fd) < 0) {
        fprintf(stderr, "Failed to close CSV file: %s\n", strerror(errno));
        exit(1);
    }
    csv_open = false;
}

void uart_close_func() {
    if (close(uart_fd) < 0) {
        fprintf(stderr, "Failed to close UART: %s\n", strerror(errno));
        exit(1);
    }
    uart_open = false;
}

void gpioTerminate() {
    gpioTerminate();
}

void sigint_handler(int sig) {
    running = false;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sa.sa_flags = 0;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        exit(1);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        exit(1);
    }

    uart_open_func();
    csv_open_func();

    char uart_buf[1024];
    int uart_len = 0;
    while (running) {
        fd_set read_fds;
        FD_ZERO(&read_fds);
        FD_SET(uart_fd, &read_fds);
        struct timeval tv;
        tv.tv_sec = 0;
        tv.tv_usec = UART_TIMEOUT;
        if (select(uart_fd + 1, &read_fds, NULL, NULL, &tv) < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Failed to select on UART: %s\n", strerror(errno));
            exit(1);
        }
        if (FD_ISSET(uart_fd, &read_fds)) {
            uart_len = read(uart_fd, uart_buf, 1024);
            if (uart_len < 0) {
                fprintf(stderr, "Failed to read from UART: %s\n", strerror(errno));
                exit(1);
            }
            if (uart_len == 0) {
                continue;
            }
            if (uart_len > 1024) {
                fprintf(stderr, "UART buffer overflow\n");
                continue;
            }
            uart_buf[uart_len] = '\0';
            char *p = strstr(uart_buf, "\n");
            if (p == NULL) {
                continue;
            }
            *p = '\0';
            uart_len = p - uart_buf;
            char *magic_word = strstr(uart_buf, (char *)&MAGIC_WORD);
            if (magic_word == NULL) {
                continue;
            }
            if (memcmp(magic_word, (char *)&MAGIC_WORD, 4) != 0) {
                continue;
            }
            int payload_len = 0;
            for (int i = 0; i < uart_len; i++) {
                if (uart_buf[i] == '\n') {
                    break;
                }
                payload_len++;
            }
            if (payload_len < 8) {
                continue;
            }
            char *payload = uart_buf + 8;
            int object_index = 0;
            for (int i = 0; i < payload_len; i += 8) {
                int range_m = (payload[i + 4] << 8) | payload[i + 5];
                int velocity_mps = (payload[i + 6] << 8) | payload[i + 7];
                if (range_m < 0 || range_m > 65535 || velocity_mps < -32768 || velocity_mps > 32767) {
                    continue;
                }
                char timestamp[32];
                time_t t = time(NULL);
                strftime(timestamp, 32, "%Y-%m-%d %H:%M:%S", localtime(&t));
                sprintf(csv_buf, "%s,%d,%d,%d\n", timestamp, object_index, range_m, velocity_mps);
                csv_write_func(csv_buf, strlen(csv_buf));
                object_index++;
            }
        }
    }

    csv_close_func();
    uart_close_func();
    gpioTerminate();
    return 0;
