#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define UART_DEV "/dev/serial0"
#define BAUD_RATE 115200
#define DATA_BITS 8
#define STOP_BITS 1
#define PARITY 0
#define UART_TIMEOUT 0.5
#define SELECT_TIMEOUT 2
#define LINE_BUF_SIZE 256

volatile int running = 1;
char line_buf[LINE_BUF_SIZE];
int line_len = 0;

void sigint_handler(int sig) {
    running = 0;
}

int uart_open() {
    int fd = open(UART_DEV, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("uart_open: open");
        exit(1);
    }
    return fd;
}

int uart_config(int fd) {
    struct termios options;
    if (tcgetattr(fd, &options) < 0) {
        perror("uart_config: tcgetattr");
        exit(1);
    }
    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);
    options.c_cflag = (DATA_BITS << 0) | (STOP_BITS << 1) | (PARITY << 3);
    options.c_lflag &= ~(ICANON | ECHO | ECHOE | ECHOK | ECHONL | ECHOPRT | EILSEQ);
    options.c_oflag &= ~(OPOST);
    options.c_cc[VMIN] = 1;
    options.c_cc[VTIME] = (UART_TIMEOUT * 10);
    if (tcsetattr(fd, TCSANOW, &options) < 0) {
        perror("uart_config: tcsetattr");
        exit(1);
    }
    return 0;
}

int uart_read(int fd, char *buf, int len) {
    int n = read(fd, buf, len);
    if (n < 0) {
        perror("uart_read: read");
        exit(1);
    }
    return n;
}

int uart_select(int fd, int timeout) {
    struct timeval tv;
    tv.tv_sec = timeout;
    tv.tv_usec = 0;
    fd_set rfds;
    FD_ZERO(&rfds);
    FD_SET(fd, &rfds);
    if (select(fd + 1, &rfds, NULL, NULL, &tv) < 0) {
        perror("uart_select: select");
        exit(1);
    }
    return FD_ISSET(fd, &rfds);
}

void uart_close(int fd) {
    if (close(fd) < 0) {
        perror("uart_close: close");
    }
}

int main() {
    int fd = uart_open();
    if (uart_config(fd) < 0) {
        uart_close(fd);
        exit(1);
    }

    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    while (running) {
        if (uart_select(fd, SELECT_TIMEOUT)) {
            char buf[1];
            int n = uart_read(fd, buf, 1);
            if (n > 0) {
                if (line_len + n >= LINE_BUF_SIZE) {
                    line_len = 0;
                }
                memcpy(line_buf + line_len, buf, n);
                line_len += n;
                if (buf[n - 1] == '\n') {
                    char *timestamp = strtok(line_buf, ",");
                    char *range = strtok(NULL, ",");
                    if (timestamp && range) {
                        struct tm time;
                        time.tm_year = atoi(timestamp) - 1900;
                        time.tm_mon = atoi(timestamp + 5) - 1;
                        time.tm_mday = atoi(timestamp + 8);
                        time.tm_hour = atoi(timestamp + 11);
                        time.tm_min = atoi(timestamp + 13);
                        time.tm_sec = atoi(timestamp + 15);
                        char date[20];
                        strftime(date, sizeof(date), "%Y-%m-%d %H:%M:%S", &time);
                        printf("Timestamp: %s, Range: %.2f meters\n", date, atof(range));
                    }
                    line_len = 0;
                }
            }
        }
    }

    uart_close(fd);
    return 0;
}

