// Function to handle SIGINT and SIGTERM signals
void sig_handler(int sig) {
    // Close the serial port
    close(serial_fd);
    // Release all GPIO resources
    gpioTerminate();
    // Exit the program
    exit(0);
}

int main() {
    // Initialize the GPIO library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    // Set up the serial port
    serial_fd = open("/dev/ttyAMA0", O_RDWR | O_NOCTTY | O_SYNC);
    if (serial_fd < 0) {
        fprintf(stderr, "Failed to open serial port\n");
        gpioTerminate();
        exit(1);
    }

    // Set up the serial port settings
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) < 0) {
        fprintf(stderr, "Failed to get serial port settings\n");
        close(serial_fd);
        gpioTerminate();
        exit(1);
    }
    cfsetispeed(&tty, B115200);
    cfsetospeed(&tty, B115200);
    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_iflag &= ~IGNBRK;
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;
    if (tcsetattr(serial_fd, TCSANOW, &tty) < 0) {
        fprintf(stderr, "Failed to set serial port settings\n");
        close(serial_fd);
        gpioTerminate();
        exit(1);
    }

    // Set up the GPIO pins
    gpioSetMode(GPIO4, PI_INPUT);
    gpioSetPullUpDnControl(GPIO4, PI_PUD_UP);
    gpioSetMode(GPIO17, PI_INPUT);
    gpioSetPullUpDnControl(GPIO17, PI_PUD_UP);
    gpioSetMode(GPIO27, PI_INPUT);
    gpioSetPullUpDnControl(GPIO27, PI_PUD_UP);

    // Register SIGINT and SIGTERM handlers
    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    // Main loop
    while (1) {
        // Read the GPIO pins
        int left = gpioRead(GPIO4);
        int middle = gpioRead(GPIO17);
        int right = gpioRead(GPIO27);

        // Check if all sensors read 0
        if (left == 0 && middle == 0 && right == 0) {
            // Send emergency stop message over serial port
            if (write(serial_fd, "EMERGENCY STOP!\n", 13) < 0) {
                fprintf(stderr, "Failed to write to serial port\n");
            }
        }

        // Log the sensor states
        printf("%d %d %d\n", left, middle, right);

        // Sleep for 100ms
        usleep(100000);
    }

    // Release all resources on exit
    close(serial_fd);
    gpioTerminate();
    return 0;
}

